---NEW SCRIPT 1362


ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS
SELECT     dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, 
                      CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
                       ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      FORTOTIKES.APOSTOLEASDESCR, FORTOTIKES.PARALISPTISDESCR, FORTOTIKES.ENTOLEASDESCR, 
                      dbo.FORTOTIKES.ANTAPOKRITISDESCR, dbo.FORTOTIKES.NOLISTASDIANOMIS, ACCOUNTS_3.Eponimia AS TRITOSDESCR, MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, 
                      ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS), 0) AS BAROS, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA), 0) AS KYBIKA, 
                      MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO, dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, 
                      dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUS, 
                      --CONVERT(varchar, dbo.FORTOTIKES.DATEPARAD, 102) AS 
                      DATEPARAD, dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.IDPARALIPTI, dbo.FORTOTIKES.IDENTOLEA, 
                      dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.IDPRAKTOREIO, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
