dbo.KINDPARASTATIKON.IF_BASE, dbo.KINDPARASTATIKON.IF_TRANSFORM, dbo.KINDPARASTATIKON.TRANSFORMTO, 
dbo.KINDPARASTATIKON.IFENIMEROSITAMEIO, dbo.KINDPARASTATIKON.IfDelete, dbo.KINDPARASTATIKON.AUTONUMBER_FROM, 
dbo.KINDPARASTATIKON.IF_ZERO_ON_NEW_YEAR, dbo.KINDPARASTATIKON.IF_PRINT, dbo.KINDPARASTATIKON.PREPORT, 
dbo.KINDPARASTATIKON.TAXISPERCENT, dbo.KINDPARASTATIKON.IfFortotiki, dbo.KINDPARASTATIKON.IfMisthodosia, 
