dbo.KINDPARASTATIKON.KindKINISIS, dbo.KINDPARASTATIKON.KindYpologismou, dbo.PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON, 
CASE KindYpologismou WHEN - 1 THEN 'Εξαγωγή' WHEN 0 THEN 'Δεν Ενημερώνει' WHEN 1 THEN 'Εισαγωγή' END AS TYPOSENIMERVSHS, 
dbo.CAT_PARASTATIKON.IFPLIR, dbo.CAT_PARASTATIKON.IFEISPR, dbo.KINDPARASTATIKON.IFENIMEROSITAMEIO, dbo.KINDPARASTATIKON.IF_XREOSI, 
dbo.KINDPARASTATIKON.IF_PISTOSI, dbo.KINDPARASTATIKON.IF_AUTONUMBER, dbo.KINDPARASTATIKON.IF_BASE, dbo.KINDPARASTATIKON.IF_TRANSFORM, 
dbo.KINDPARASTATIKON.TRANSFORMTO, dbo.KINDPARASTATIKON.AUTONUMBER_FROM, dbo.KINDPARASTATIKON.IF_ZERO_ON_NEW_YEAR, 
dbo.KINDPARASTATIKON.IF_PRINT, dbo.KINDPARASTATIKON.PREPORT, dbo.KINDPARASTATIKON.TAXISPERCENT, dbo.KINDPARASTATIKON.IfMisthodosia, 
dbo.KINDPARASTATIKON.IfFortotiki, dbo.KINDPARASTATIKON.IfKAA, dbo.KINDPARASTATIKON.IF_ENIMEROSIKARTELA, dbo.KINDPARASTATIKON.IF_XREOSIKARTELA, 
dbo.KINDPARASTATIKON.IF_PISTOSIKARTELA, dbo.KINDPARASTATIKON.PRINTLABEL, dbo.KINDPARASTATIKON.IfDelete, dbo.KINDPARASTATIKON.SEIRA, 
dbo.KINDPARASTATIKON.IFKEPYO, dbo.KINDPARASTATIKON.IFPROFORTOTIKI, dbo.KINDPARASTATIKON.PROEPSXOLIO, dbo.KINDPARASTATIKON.PrinterName, 
dbo.KINDPARASTATIKON.IfPreviewFirst, dbo.KINDPARASTATIKON.IDPARASTEXOFLISI, dbo.KINDPARASTATIKON.DESCRPARASTEXOFLISI, 
dbo.KINDPARASTATIKON.IFKEPXREOSI, dbo.KINDPARASTATIKON.IFKEPPISTOSI, dbo.KINDPARASTATIKON.Copies, dbo.KINDPARASTATIKON.IF_ENIMEROSIAPOTHIKI, 
dbo.KINDPARASTATIKON.IF_PAROXIYPIRESION, dbo.KINDPARASTATIKON.IDCOMPANY, dbo.KINDPARASTATIKON.IDYPOKATASTIMA, dbo.KINDPARASTATIKON.IF_LISTADIANOMIS, 
dbo.KINDPARASTATIKON.CodeLog, dbo.KINDPARASTATIKON.IFEISAGOGI, dbo.KINDPARASTATIKON.IFEXAGOGI, dbo.KINDPARASTATIKON.IF_ORDER, 
dbo.KINDPARASTATIKON.IsNoActive, dbo.KINDPARASTATIKON.IF_PRODROMOL,dbo.KINDPARASTATIKON.IF_APOGRAFI, 
dbo.KINDPARASTATIKON.IF_APOGR_PEL, dbo.KINDPARASTATIKON.IF_APOGR_APOTHIKIS, dbo.KINDPARASTATIKON.IF_APOGR_PROM, 
dbo.KINDPARASTATIKON.VoucherTypeCode,  dbo.KINDPARASTATIKON.IF_EDMETAFORAS, dbo.KINDPARASTATIKON.IF_EDSYNARMOL, 
dbo.KINDPARASTATIKON.IF_EDTOPOTH, dbo.KINDPARASTATIKON.IS_CANCELLATION, dbo.KINDPARASTATIKON.IF_FROM_ANTAP
FROM dbo.CAT_PARASTATIKON WITH (NOLOCK) INNER JOIN
dbo.PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) ON dbo.CAT_PARASTATIKON.ID = dbo.PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON INNER JOIN
dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID

GO



