ALTER VIEW [dbo].[FORTOTIKESPERMONTH] 
AS
 SELECT IDXREOUMENOU, MAX(ACCOUNTS.Eponimia) AS EPONIMMIA, MONTH(DATEPRINT) AS MONTH, YEAR(DATEPRINT) AS YEAR, 
 COUNT(FORTOTIKES.ID) AS PARASTATIKA, 
 SUM(POSO) AS POSO, SUM(FORTOTIKES.TAXIS) AS TAXIS, SUM(SUMPOSO) AS SUMPOSO, FORTOTIKES.IF_FROM_ANTAP, FORTOTIKES.IF_TO_ANTAP  
 FROM FORTOTIKES INNER JOIN 
 ACCOUNTS ON FORTOTIKES.IDXREOUMENOU = ACCOUNTS.ID LEFT OUTER JOIN
dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID LEFT OUTER JOIN
PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID INNER JOIN
CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0 
WHERE (DATEPRINT  IS NOT NULL) AND FORTOTIKES.ifDelete <>1 
 GROUP BY IDXREOUMENOU, YEAR(DATEPRINT), MONTH(DATEPRINT), FORTOTIKES.IF_FROM_ANTAP, FORTOTIKES.IF_TO_ANTAP  
 --ORDER BY IDXREOUMENOU, YEAR, MONTH 


GO




---END SCRIPT 1365
