	ACCOUNTS_1.AddressCity AS ADDRCITYPARAL,
	ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL,
	ACCOUNTS_1.Tel AS TELPARAL,
	ACCOUNTS_1.DOY AS DOYPARAL,
	ACCOUNTS_2.Epagelma AS EPAGENTOL,
