	ACCOUNTS_2.AddressNo AS ADDRNOENTOL,
	ACCOUNTS_2.AddressTK AS ADDRTKENTOL,
	ACCOUNTS_2.AddressCity AS ADDRCITYENTOL,
	ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL,
	ACCOUNTS_2.Tel AS TELENTOL,
	ACCOUNTS_2.DOY AS DOYENTOL,
	ACCOUNTS_3.Epagelma AS EPAGTR,
	ACCOUNTS_3.AddressStr AS ADDRSTTR,
	ACCOUNTS_3.AddressNo AS ADDRNOTR,
	ACCOUNTS_3.AddressTK AS ADDRTKTR,
	ACCOUNTS_3.AddressCity AS ADDRCITYTR,
	ACCOUNTS_3.AddressPref AS ADSTRDRNOMO,
	ACCOUNTS_3.Tel AS TELTR,
	ACCOUNTS_3.DOY AS DOYTR,
	dbo.FORTOTIKES.AFMAPOSTOLEA,
	dbo.FORTOTIKES.AFMENTOLEA,
	dbo.FORTOTIKES.AFMPARALIPTI,
	dbo.FORTOTIKES.AFMTRITOU,
	dbo.FORTOTIKES.AFMANTAPOKRITI,
	dbo.FORTOTIKES.IFPARADOSITOPEL,
	dbo.FORTOTIKES.IFPARALABIFROMPEL,
	ACCOUNTS_1.Mobile AS MOBILEPARALIPTI,
	dbo.FORTOTIKES.CONTAINER,
	dbo.FORTOTIKES.BOAT,
	ACCOUNTS_2.Mobile AS MOBILEENTOLTEA,
	dbo.ACCOUNTS.Mobile AS MOBILEAPOSTOLEA,
	FORTOTIKES.IDKENTROUKOSTOUS, 
	FORTOTIKES.NO_EXT_ORDER_IK, 
	FORTOTIKES.IDENTOLIS, 
	FORTOTIKES.IF_CANCEL, 
	FORTOTIKES.ID_CANCELLATION, 
	FORTOTIKES.SEIRA_CANCELLATION, 
	FORTOTIKES.NOPARAST_CANCELLATION, 
	FORTOTIKES.DETAILS_CANCELLATION,
	FORTOTIKES.CANCELDATE, 
	dbo.FORTOTIKES.IDDRIVER,
	dbo.FORTOTIKES.DRIVERDESCR,
	dbo.FORTOTIKES.IDXRHSHS,
	dbo.FORTOTIKES.IDCOMPANY,
	dbo.FORTOTIKES.IDYPOKATASTIMA,
	DBO.FORTOTIKES.EXT_BARCODE, 
	dbo.FORTOTIKES.UserCreate,
	dbo.FORTOTIKES.UserMod,
	dbo.FORTOTIKES.DateCreate,
	dbo.FORTOTIKES.DateMod, 
	dbo.FORTOTIKES.IF_FROM_ANTAP, 
	dbo.FORTOTIKES.IF_TO_ANTAP 

FROM 
(
	SELECT
		dbo.FORTOTIKES.ID [IDVOH],
		dbo.GRAMMESFORTTIKIS.ID [IDGF],
		ROW_NUMBER() OVER (PARTITION BY dbo.FORTOTIKES.ID ORDER BY dbo.GRAMMESFORTTIKIS.ID) [ROWNUM]
	FROM dbo.FORTOTIKES
	LEFT JOIN dbo.GRAMMESFORTTIKIS ON dbo.FORTOTIKES.ID = dbo.GRAMMESFORTTIKIS.IDVOH
) T

JOIN dbo.FORTOTIKES WITH (NOLOCK) 
	ON dbo.FORTOTIKES.ID = T.IDVOH

LEFT OUTER JOIN dbo.GRAMMESFORTTIKIS WITH (NOLOCK) 
	ON dbo.GRAMMESFORTTIKIS.ID = T.IDGF

LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) 
	ON dbo.FORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id

LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) 
	ON dbo.FORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id

LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) 
	ON dbo.FORTOTIKES.IDENTOLEA = ACCOUNTS_2.id

LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) 
	ON dbo.FORTOTIKES.IDTRITOU = ACCOUNTS_3.id

LEFT OUTER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) 
	ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID

LEFT OUTER JOIN PARASTATIKA_ANA_KATHGORIA 
	ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID

INNER JOIN CAT_PARASTATIKON 
	ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON
	AND If_EXODO = 0

--LEFT OUTER JOIN dbo.SUM_XREOSEIS_GRAMMES_FORTOTIKIS WITH (NOLOCK) 
--	ON dbo.SUM_XREOSEIS_GRAMMES_FORTOTIKIS.IDFORT = dbo.FORTOTIKES.ID

LEFT OUTER JOIN dbo.HEADERFORTOTIKIS
	ON dbo.HEADERFORTOTIKIS.IDFORT = dbo.FORTOTIKES.ID

LEFT OUTER JOIN dbo.Units WITH (NOLOCK) 
	ON dbo.GRAMMESFORTTIKIS.SYSKEVASIA = dbo.Units.UntID

LEFT OUTER JOIN 
(
	SELECT IDVOH, SUM(SUMPOSO) AS XREOSEIS
    FROM XREOSISANADELTIO WITH (NOLOCK)
    WHERE IF_TO_FORTOTIKI = 1
	GROUP BY IDVOH
) SUM_XREOSEIS ON SUM_XREOSEIS.IDVOH = dbo.FORTOTIKES.ID
where FORTOTIKES.ifDelete=0


GO



---END SCRIPT 1366
