ALTER VIEW [dbo].[FORTOTIKES_EXODO_ANALYSH_XREOSEON] 
AS 
SELECT A.ID, A.DATEPRINT, A.IDPARALIPTI, A.PARALISPTISDESCR, A.IDAPOSTOLEA, A.APOSTOLEASDESCR, A.IDENTOLEA, A.ENTOLEASDESCR, 
A.IDTRITOU, A.TRITOSDESCR, A.OMADPROORISMOS, A.OXIMA, A.DRIVERDESCR, A.NOPARAST, Z.Code, A.NOPARAST AS NOPARASTFORT, 
CASE WHEN A.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN A.IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN A.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
ELSE CASE WHEN A.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
CASE A.IFPREPAY WHEN 1 THEN A.SUMPOSO ELSE 0 END AS XREOSIPROPLIROMENES, 
CASE A.IFOFEILOMENI WHEN 1 THEN A.SUMPOSO ELSE 0 END AS XREOSIOFEILOMENES, 
CASE A.IFPREPAY WHEN 1 THEN CASE A.IFCASH WHEN 1 THEN A.SUMPOSO ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
CASE A.IFPREPAY WHEN 1 THEN CASE A.IFPISTOSI WHEN 1 THEN A.SUMPOSO  ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
A.POSO, A.TAXIS, A.SUMPOSO, (ISNULL(B.KOMISTRA, 0) + ISNULL(B.KOMISTRA_0, 0)) AS KOMISTRA, B.DIKAIOMA, E.OTHERPOSO, 
B.ASFALISTRA, B.ERGATIKA, A.ANTIKCASH, A.ANTIKEPIT, A.ANTIKSYNAL, A.ANTIKOTHER, A.EXODATRITON, 
A.SUMANTIK, F.BAROS, F.KYBIKA, F.TEMAXIA, F.AXIA, G.UntName AS SYSKEVASIA, 
F.PERIEXOMENO, F.TIMDA, A.IDXRHSHS, A.IDCOMPANY, A.IDYPOKATASTIMA, A.IDPRAKTOREIO, 
A.PRAKTOREIODESCR,  A.IF_TRANSFTOESEX, A.ANAMEXODO, A.IF_FROM_ANTAP, A.IF_TO_ANTAP 
FROM FORTOTIKES AS A LEFT JOIN (
SELECT IDVOH, ISNULL(SUM([ΚΟΜΙΣΤΡΑ]), 0)  AS KOMISTRA, ISNULL(SUM([ΚΟΜΙΣΤΡΑ 0%]), 0)  AS KOMISTRA_0, 
ISNULL(SUM([ΔΙΚΑΙΩΜΑ ΦΟΡΤΩΤΙΚΗΣ]), 0) AS DIKAIOMA, ISNULL(SUM([ΑΣΦΑΛΙΣΤΡΑ]), 0)  AS ASFALISTRA, ISNULL(SUM([ΕΡΓΑΤΙΚΑ]), 0)  AS ERGATIKA
 FROM (SELECT B.IDVOH, COUNT(B.ID) AS COUNTS, B.POSO AS KATHPOSO, B.DESCR 
FROM XREOSISANADELTIO AS B INNER JOIN Xreoseis AS D ON D.ID = B.IDXREOSIS
 AND B.IF_TO_FORTOTIKI = 1 GROUP BY IDVOH, B.POSO, B.DESCR
) AS S PIVOT (SUM(KATHPOSO) FOR DESCR IN ([ΚΟΜΙΣΤΡΑ], [ΚΟΜΙΣΤΡΑ 0%], [ΔΙΚΑΙΩΜΑ ΦΟΡΤΩΤΙΚΗΣ], [ΑΣΦΑΛΙΣΤΡΑ], [ΕΡΓΑΤΙΚΑ])
) AS PIV GROUP BY PIV.IDVOH
) AS B ON A.ID = B.IDVOH 
LEFT JOIN (SELECT C.IDVOH, SUM(C.OTHERPOSO) AS OTHERPOSO FROM (SELECT IDVOH, SUM(POSO) AS OTHERPOSO FROM XREOSISANADELTIO 
WHERE IDXREOSIS NOT IN (SELECT ID FROM Xreoseis WHERE ifKomistra =1 OR ifDikaiomaFortotikis = 1) 
AND IF_TO_FORTOTIKI= 1  GROUP BY IDVOH) AS C GROUP BY C.IDVOH
) AS E ON A.ID = E.IDVOH 
LEFT JOIN (SELECT IDVOH, SUM(BAROS) AS BAROS , SUM(KYBIKA) AS KYBIKA, SUM(TEMAXIA) AS TEMAXIA, SUM(SUMPOSO) AS AXIA, 
MIN(PERIEXOMENO) AS PERIEXOMENO, MIN(TIMDA) AS TIMDA, MIN(SYSKEVASIA) AS SYSKEVASIA FROM GRAMMESFORTTIKIS GROUP BY IDVOH) AS F ON A.ID = F.IDVOH
LEFT JOIN KINDPARASTATIKON AS Z ON A.IDPARAST = Z.ID INNER JOIN 
PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = Z.ID INNER JOIN
CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 1 
LEFT JOIN Units AS G ON F.SYSKEVASIA = G.UntID


GO



---END SCRIPT 1367
------------------------------------------------------------------------------------ 
