ALTER VIEW [dbo].[TIMOL_VOH_VIEW]
AS
  SELECT dbo.voh.id,
         dbo.voh.dateprint,
         dbo.kindparastatikon.code,
         dbo.voh.parastatiko,
         dbo.voh.seira,
         Cast(dbo.voh.noparast AS INT)                     AS NOPARAST,
         dbo.voh.noparastdeltioudianomis,
         dbo.voh.noparastdeltiouapostolis,
         dbo.voh.oxima,
         dbo.voh.omadproorismos,
         CASE
           WHEN ifxrentol = 1 THEN 'ΕΝΤΟΛΕΑΣ'
           ELSE
             CASE
               WHEN ifxrapost = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
               ELSE
                 CASE
                   WHEN ifxrtritou = 1 THEN 'ΤΡΙΤΟΣ'
                   ELSE
                     CASE
                       WHEN ifxrparal = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
                       ELSE 'ΑΓΝΩΣΤΟ'
                     END
                 END
             END
         END                                               AS XREOYMENOS,
         dbo.voh.apostoleasdescr,
         dbo.voh.paralisptisdescr,
         dbo.voh.entoleasdescr,
         dbo.voh.antapokritisdescr,
         dbo.voh.tritosdescr,
         Min(dbo.grammesforttikis.timda)                   AS TIMDA,
         dbo.voh.poso,
         dbo.voh.taxis,
         dbo.voh.sumposo,
         Isnull(Sum(dbo.grammesforttikis.temaxia), 0)      AS TEMAXIA,
         Isnull(Sum(dbo.grammesforttikis.baros), 0)        AS BAROS,
         Isnull(Sum(dbo.grammesforttikis.kybika), 0)       AS KYBIKA,
         Min(dbo.units.untname)                            AS SYSKEVASIA,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                        FROM   xreosis_anadeltio_view WITH (nolock)
                        WHERE  idvoh = dbo.voh.id
                               AND if_to_fortotiki = 1)
           ELSE 0
         END                                               AS
         XREOSIPROPLIROMENES,
         CASE dbo.voh.ifofeilomeni
           WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                        FROM   xreosis_anadeltio_view WITH (nolock)
                        WHERE  idvoh = dbo.voh.id
                               AND if_to_fortotiki = 1)
           ELSE 0
         END                                               AS XREOSIOFEILOMENES,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN
             CASE dbo.voh.ifcash
               WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                            FROM   xreosis_anadeltio_view WITH (nolock)
                            WHERE  idvoh = dbo.voh.id
                                   AND if_to_fortotiki = 1)
               ELSE 0
             END
           ELSE 0
         END                                               AS
            XREOSIPROPLIROMENESCASH,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN
             CASE dbo.voh.ifpistosi
               WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                            FROM   xreosis_anadeltio_view WITH (nolock)
                            WHERE  idvoh = dbo.voh.id
                                   AND if_to_fortotiki = 1)
               ELSE 0
             END
           ELSE 0
         END                                               AS
            XREOSIPROPLIROMENESPISTOSI,
         Min(dbo.grammesforttikis.periexomeno)             AS PERIEXOMENO,
         dbo.voh.perioxifortosis,
         dbo.voh.perioxiparadosis,
         dbo.voh.comments,
         dbo.voh.sumantik,
         dbo.voh.praktoreiodescr,
         dbo.voh.status,
         CONVERT(VARCHAR, dbo.voh.dateparad, 102)          AS DATEPARAD,
         dbo.voh.idapostolea,
         dbo.voh.idparalipti,
         dbo.voh.identolea,
         dbo.voh.idantapokriti,
         dbo.voh.idtritou,
         dbo.voh.idpraktoreio,
         CASE ifantikcash
           WHEN 0 THEN 0
           ELSE antikcash
         END                                               AS ANTIKCASH,
         CASE ifantikepit
           WHEN 0 THEN 0
           ELSE antikepit
         END                                               AS ANTIKEPIT,
         CASE ifantiksynal
           WHEN 0 THEN 0
           ELSE antiksynal
         END                                               AS ANTIKSYNAL,
         CASE ifantikother
           WHEN 0 THEN 0
           ELSE antikother
         END                                               AS ANTIKOTHER,
         CASE ifcancelantik
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFCANCELANTIK,
         dbo.voh.commentsantik,
         dbo.voh.dateparadosi,
         dbo.voh.comments2,
         Min(dbo.headerfortotikis.komistra)                AS KOMISTRA,
         Min(dbo.headerfortotikis.dikaiomafortotikis)      AS DIKAIOMAFORTOTIKIS
         ,
         Min(dbo.headerfortotikis.otherxreosis)            AS
         OTHERXREOSIS,
         Min(dbo.headerfortotikis.olikosynoloxreoseonfort) AS
            OLIKOSYNOLOXREOSEONFORT,
         Min(dbo.headerfortotikis.ergatika)                AS ERGATIKA,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFPREPAY,
         CASE dbo.voh.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFOFEILOMENI,
         Isnull(Sum(dbo.grammesforttikis.sumposo), 0)      AS AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRENTOL,
         dbo.voh.kindpaymentdescr,
         dbo.voh.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRTRITOU,
         dbo.voh.ifantikcash,
         dbo.voh.ifantikepit,
         dbo.voh.ifantiksynal,
         dbo.voh.ifantikother,
         dbo.voh.ifdelete,
         dbo.voh.ifcancel,
         CONVERT(VARCHAR, dbo.voh.datecancel, 102)         AS DATECANCEL,
         dbo.voh.ifparadosi,
         dbo.voh.aitiologiaparastatikou,
         CONVERT(VARCHAR, dbo.voh.datefortosis, 102)       AS DATEFORTOSIS,
         dbo.voh.ifepistrofi,
         CONVERT(VARCHAR, dbo.voh.dateepistrofis, 102)     AS DATEEPISTROFIS,
         dbo.voh.aitiologiaepistrofis,
         dbo.voh.commentsepistrofis,
         dbo.voh.ifcash,
         dbo.voh.ifpistosi,
         dbo.voh.statusdescr,
         dbo.voh.ypaitios,
         dbo.voh.ifepanadromologisi,
         dbo.voh.ifepanekdosi,
         dbo.voh.ifokepanadromologisi,
         dbo.voh.noparastantik,
         dbo.voh.commentsakirosis,
         dbo.voh.ifeisprantik,
         dbo.voh.ifparadosiantik,
         dbo.voh.ifparalaviantik,
         dbo.voh.commentsparadantik,
         dbo.voh.commantsparalantik,
         dbo.voh.commentseisprantik,
         CONVERT(VARCHAR, dbo.voh.dateparadantik, 102)     AS DATEPARADANTIK,
         CONVERT(VARCHAR, dbo.voh.dateparalantik, 102)     AS DATEPARALANTIK,
         CONVERT(VARCHAR, dbo.voh.dateeisprantik, 102)     AS DATEEISPRANTIK,
         dbo.voh.eispraxasantik,
         dbo.voh.noparparadantik,
         dbo.voh.noparasteisprantik,
         dbo.voh.noparparalantik,
         CONVERT(VARCHAR, dbo.voh.dateparal, 102)          AS DATEPARAL,
         dbo.voh.commentsparad,
         dbo.voh.commantsparal,
         dbo.voh.timeparalfrom,
         dbo.voh.timeparalto,
         dbo.voh.timeparadfrom,
         dbo.voh.timeparadto,
         CONVERT(VARCHAR, dbo.voh.datecancelantik, 102)    AS DATECANCELANTIK,
         dbo.voh.idparast,
         dbo.voh.taxispercent,
         dbo.voh.anamexodo,
         dbo.voh.id                                        AS IDFORTOTIKIS,
         dbo.voh.afmxreoumenou,
         dbo.headerfortotikis.asfalistra,
         Round(dbo.headerfortotikis.taxis, 2)              AS TAXISXREOSEON,
         dbo.headerfortotikis.sumposoxrfort,
         dbo.headerfortotikis.katharo,
         dbo.accounts.epagelma                             AS EPAGAPOST,
         dbo.accounts.addressstr                           AS ADDRSTRAPOST,
