---NEW SCRIPT 1380

create view XREOSEIS_SYNARMOLOGHSHS_VIEW
as
select 
	v.IDORDER,
	v.ID,
	xd.IDXREOSIS,
	xd.IDVOH,
	xd.DESCR,
	xd.TYPOS,
	xd.TAXISPERCENT,
	xd.TAXIS,
	xd.POSO,
	xd.SUMPOSO,
	xd.CODEXREOSIS,
	hp.CodeCatalog,
	hp.DescrCatalog,
	hp.price,
	hp.discountpercent,
	hp.discounteuro,
	hp.finalprice,
	hp.IfTransport,
	hp.IfAssembly,
	hp.SubTotal
from HEADERVOH hv
join voh v on v.id=hv.IDVOH
join XREOSISANADELTIO xd on xd.IDVOH=v.ID
join HEADERVOHPRICING hp on hp.IDVOH=v.IDORDER

GO

