---NEW SCRIPT 1381

ALTER VIEW [dbo].[VOH_VIEW]
AS
  SELECT DISTINCT dbo.voh.id,
                  dbo.voh.dateprint,
                  dbo.kindparastatikon.code,
                  dbo.voh.parastatiko,
                  dbo.voh.seira,
                  Cast(dbo.voh.noparast AS NVARCHAR(15))               AS NOPARAST,
                  dbo.voh.custdescr,
                  dbo.voh.epagelma,
                  dbo.voh.afm,
                  dbo.voh.city,
                  dbo.voh.tel,
                  dbo.voh.mobile,
                  dbo.voh.poso,
                  dbo.voh.taxis,
                  dbo.voh.sumposo,
                  dbo.voh.kindpaymentdescr,
                  dbo.voh.oxima,
                  dbo.voh.omadproorismos,
                  dbo.voh.sxetikaparastatika,
                  CASE
                    WHEN ifxrentol = 1 THEN 'ΕΝΤΟΛΕΑΣ'
                    ELSE
                      CASE
                        WHEN ifxrapost = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
                        ELSE
                          CASE
                            WHEN ifxrtritou = 1 THEN 'ΤΡΙΤΟΣ'
                            ELSE
                              CASE
                                WHEN ifxrparal = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
                                ELSE 'ΑΓΝΩΣΤΟ'
                              END
                          END
                      END
                  END AS XREOYMENOS,
                  dbo.voh.noparastdeltioudianomis,
                  dbo.voh.noparastdeltiouapostolis,
                  Min(dbo.grammesvoh.timda)                            AS TIMDA,
                  Isnull(Sum(dbo.grammesvoh.temaxia), 0)               AS TEMAXIA,
                  Isnull(Sum(dbo.grammesvoh.baros), 0)                 AS BAROS,
                  Isnull(Sum(dbo.grammesvoh.kybika), 0)                AS KYBIKA,
                  CASE dbo.voh.ifprepay
                    WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                                 FROM   xreosis_anadeltio_view WITH (nolock)
                                 WHERE  idvoh = dbo.voh.id
                                        AND ifxreositriton <> 1
                                        AND if_to_voh = 1)
                    ELSE 0
                  END AS XREOSIPROPLIROMENES,
                  CASE dbo.voh.ifofeilomeni
                    WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                                 FROM   xreosis_anadeltio_view WITH (nolock)
                                 WHERE  idvoh = dbo.voh.id
                                        AND ifxreositriton <> 1
                                        AND if_to_voh = 1)
                    ELSE 0
                  END AS XREOSIOFEILOMENES,
                  Min(dbo.grammesvoh.periexomeno)AS PERIEXOMENO,
                  dbo.voh.perioxifortosis,
                  dbo.voh.perioxiparadosis,
                  dbo.voh.comments,
                  dbo.voh.sumantik,
                  dbo.voh.praktoreiodescr,
                  dbo.voh.status,
                  dbo.voh.dateparad,
                  dbo.voh.idpraktoreio,
                  CASE ifantikcash
                    WHEN 0 THEN 0
                    ELSE antikcash
                  END AS ANTIKCASH,
                  CASE ifantikepit
                    WHEN 0 THEN 0
                    ELSE antikepit
                  END AS ANTIKEPIT,
                  CASE ifantiksynal
                    WHEN 0 THEN 0
                    ELSE antiksynal
                  END                                                  AS ANTIKSYNAL,
                  CASE ifantikother
                    WHEN 0 THEN 0
                    ELSE antikother
                  END                                                  AS ANTIKOTHER,
                  CASE ifcancelantik
                    WHEN 0 THEN 'ΟΧΙ'
                    ELSE 'ΝΑΙ'
                  END                                                  AS IFCANCELANTIK,
                  dbo.voh.commentsantik,
                  dbo.voh.dateparadosi,
                  dbo.voh.comments2,
                  Min(dbo.sum_xreoseis_grammes_voh.komistra)           AS KOMISTRA,
                  Min(dbo.sum_xreoseis_grammes_voh.xreosistriton)      AS XREOSISTRITON,
                  Min(dbo.sum_xreoseis_grammes_voh.dikaiomafortotikis) AS DIKAIOMAFORT,
                  Min(dbo.sum_xreoseis_grammes_voh.otherxreosis)       AS OTHERXREOSIS,
                  CASE dbo.voh.ifprepay
                    WHEN 1 THEN 'ΝΑΙ'
                    ELSE 'ΟΧΙ'
                  END AS IFPREPAY,
                  CASE dbo.voh.ifofeilomeni
                    WHEN 1 THEN 'ΝΑΙ'
                    ELSE 'ΟΧΙ'
                  END                                                  AS IFOFEILOMENI,
                  Isnull(Sum(dbo.grammesvoh.sumposo), 0)               AS AXIA,
                  CASE ifxrentol
                    WHEN 0 THEN 'ΟΧΙ'
                    ELSE 'ΝΑΙ'
                  END                                                  AS IFXRENTOL,
                  dbo.voh.idkindpayment,
                  CASE ifxrapost
                    WHEN 0 THEN 'ΟΧΙ'
                    ELSE 'ΝΑΙ'
                  END                                                  AS IFXRAPOST,
                  CASE ifxrparal
                    WHEN 0 THEN 'ΟΧΙ'
                    ELSE 'ΝΑΙ'
                  END                                                  AS IFXRPARAL,
                  CASE ifxrtritou
                    WHEN 0 THEN 'ΟΧΙ'
                    ELSE 'ΝΑΙ'
                  END                                                  AS IFXRTRITOU,
                  dbo.voh.ifantikcash,
                  dbo.voh.ifantikepit,
                  dbo.voh.ifantiksynal,
                  dbo.voh.ifantikother,
                  dbo.voh.ifdelete,
                  dbo.voh.ifcancel,
                  dbo.voh.datecancel,
                  dbo.voh.ifparadosi,
                  dbo.voh.aitiologiaparastatikou,
                  dbo.voh.datefortosis,
                  dbo.voh.ifepistrofi,
                  dbo.voh.dateepistrofis,
                  dbo.voh.aitiologiaepistrofis,
                  dbo.voh.commentsepistrofis,
                  dbo.voh.ifcash,
                  dbo.voh.ifpistosi,
                  dbo.voh.statusdescr,
                  dbo.voh.ypaitios,
                  dbo.voh.ifepanadromologisi,
                  dbo.voh.ifepanekdosi,
                  dbo.voh.ifokepanadromologisi,
                  dbo.voh.noparastantik,
                  dbo.voh.commentsakirosis,
                  dbo.voh.ifeisprantik,
                  dbo.voh.ifparadosiantik,
                  dbo.voh.ifparalaviantik,
                  dbo.voh.commentsparadantik,
                  dbo.voh.commantsparalantik,
                  dbo.voh.commentseisprantik,
                  dbo.voh.dateparadantik,
                  dbo.voh.dateparalantik,
                  dbo.voh.dateeisprantik,
                  dbo.voh.eispraxasantik,
                  dbo.voh.noparparadantik,
                  dbo.voh.noparasteisprantik,
                  dbo.voh.noparparalantik,
                  dbo.voh.dateparal,
                  dbo.voh.commentsparad,
                  dbo.voh.commantsparal,
                  dbo.voh.ifexoflisi,
                  dbo.voh.timeparalfrom,
                  dbo.voh.timeparalto,
                  dbo.voh.timeparadfrom,
                  dbo.voh.timeparadto,
                  dbo.voh.datecancelantik,
                  dbo.voh.idparast,
                  dbo.voh.taxispercent,
                  dbo.voh.anamexodo,
                  dbo.voh.id                                           AS IDVOH,
                  dbo.voh.afmxreoumenou,
                  dbo.sum_xreoseis_grammes_voh.asfalistra,
                  dbo.sum_xreoseis_grammes_voh.taxis                   AS TAXISXREOSEON,
                  dbo.sum_xreoseis_grammes_voh.sumposoxrvoh,
                  dbo.sum_xreoseis_grammes_voh.katharo,
                  dbo.voh.thetime,
                  dbo.voh.identolea                                    AS CUSTOMERID,
                  dbo.voh.entoleasdescr                                AS CUSTOMERDESCR,
                  dbo.voh.idapostolea                                  AS IDSYNAL,
                  dbo.voh.apostoleasdescr                              AS SYNALDESCR,
                  dbo.voh.idcustomer,
                  dbo.voh.doy,
                  dbo.voh.addressstreet,
                  dbo.voh.addressno,
                  dbo.voh.pref,
                  dbo.voh.afmapostolea,
                  ACCOUNTS_1.epagelma AS SYNALEPAGELMA,
                  ACCOUNTS_1.addressstr AS SYNALADDRSTR,
                  ACCOUNTS_1.addressno  AS SYNALADDRNO,
                  ACCOUNTS_1.addresstk  AS SYNALADDRTK,
                  ACCOUNTS_1.addresscity AS SYNALCITY,
                  ACCOUNTS_1.addresscountry AS SYNALADDRCOUNTRY,
                  ACCOUNTS_1.tel AS SYNALTEL,
                  ACCOUNTS_1.doy AS SYNALDOY,
                  ACCOUNTS_1.afm AS SYNALAFM,
                  ACCOUNTS_1.Mobile AS SYNALMOBILE,
                  dbo.accounts.code AS CodeCust,
                  dbo.accounts.addresstk AS CUSTADDRTK,
                  dbo.accounts.addressno AS CUSTADDRNO,
                  dbo.accounts.addressstr AS CUSTADDRSTR,
                  dbo.accounts.addresscity AS CUSTADDRCITY,
                  dbo.accounts.afm AS CUSTAFM,
                  dbo.accounts.doy AS CUSTDOY,
                  dbo.voh.idxrhshs,
                  dbo.voh.idcompany,
                  dbo.voh.idypokatastima,
                  dbo.voh.usermod,
                  dbo.voh.datemod,
                  dbo.voh.usercreate,
                  dbo.voh.datecreate,
                  dbo.voh.discountpercent,
                  dbo.voh.discount,
                  dbo.voh.arxikoposo,
                  dbo.voh.skoposdiakinisis,
                  dbo.voh.idskoposdiakinisis,
                  dbo.voh.afmentolea,
                  dbo.voh.afmparalipti,
                  dbo.voh.afmtritou,
                  dbo.voh.afmantapokriti,
                  dbo.voh.country,
                  dbo.voh.driver,
                  dbo.voh.idlistas,
                  dbo.voh.ifisorder,
                  dbo.voh.idorder,
                  dbo.voh.codeentolea,
                  dbo.voh.codeapostolea,
                  dbo.voh.codeparalipti,
                  dbo.voh.seiraorder,
                  dbo.voh.dateprintorder,
                  dbo.voh.orderdetails,
                  dbo.voh.if_close,
                  dbo.voh.noorder
  FROM   dbo.accounts AS ACCOUNTS_1 WITH (nolock)
         RIGHT OUTER JOIN dbo.accounts WITH (nolock)
         RIGHT OUTER JOIN dbo.voh WITH (nolock)
         LEFT OUTER JOIN dbo.grammesvoh WITH (nolock)ON dbo.voh.id =dbo.grammesvoh.idvoh
         LEFT OUTER JOIN dbo.sum_xreoseis_grammes_voh WITH (nolock)ON dbo.voh.id =dbo.sum_xreoseis_grammes_voh.idvoh
                                        ON dbo.accounts.id = dbo.voh.idcustomer
                       ON ACCOUNTS_1.id = dbo.voh.idapostolea
         LEFT OUTER JOIN dbo.kindparastatikon WITH (nolock)
                      ON dbo.voh.idparast = dbo.kindparastatikon.id
  GROUP  BY dbo.voh.id,
            dbo.voh.dateprint,
            dbo.voh.parastatiko,
