ALTER PROCEDURE [dbo].[InserttoACCOUNTS_FromXML] 
	@Eponimia NVARCHAR(100),
	@Diefthinsi NVARCHAR(100),
	@Perioxi NVARCHAR(100),
	@TK NVARCHAR(10) = null,
	@Tilefono NVARCHAR(50)= null,
	@Email NVARCHAR(50) = null,
	@IDCREATE INT OUTPUT
AS
BEGIN
	DECLARE @OUT TABLE([ACTION] NVARCHAR(10), ID INT);
	MERGE [Accounts] WITH (HOLDLOCK) AS target
	USING (
		VALUES(@Eponimia, @Diefthinsi, @Perioxi, @TK, @Tilefono, @Email)
	) AS source(Eponimia, Diefthinsi, Perioxi, TK, Tilefono, Email)
	ON 
		target.Eponimia = source.Eponimia
		AND	target.AddressStr = source.Diefthinsi
		AND target.AddressCity = source.Perioxi
		AND target.AddressTK = REPLACE(source.TK, ' ', '')
	WHEN NOT MATCHED THEN
		INSERT (Eponimia, AddressStr, AddressCity, AddressTK, Tel, EMAIL)
		VALUES (source.Eponimia, source.Diefthinsi, source.Perioxi, source.TK, source.Tilefono, source.Email)
	WHEN MATCHED THEN 
		UPDATE SET 
				target.Tel = source.Tilefono,
				target.EMAIL = source.Email	
	OUTPUT $action, INSERTED.ID INTO @OUT;

	UPDATE ACC
	SET
		XREOUMENOS = 1,
		Code = 'PEL-' + CONVERT(VARCHAR, ACC.id),
		Epagelma = '',
		LastName = Eponimia,
		FirstName = '',
		AddressNo = '',
		AddressCity = ACC.AddressCity,
		AddressPref = COALESCE(ExactAreaInfo.AstName, ApproxAreaInfo.AstName),
		AddressZone = COALESCE(ExactAreaInfo.DESCR, ApproxAreaInfo.DESCR),
		AddressCountry = 'ΕΛΛΑΔΑ',
		Tel2 = '',
		Fax = '',
		Mobile = '',
		AFM = '',
		DOY = '',
		CatProm = '',
		AMIKA = '',
		AMKA = '',
		AddrFortosis = AddressStr,
		Comments = '',
		AFMENTOLEA = '',
		PROTPERIEXOMENO = '',
		DISCPERCENT = 0,
		CodeLog = '',
		IF_PEL = 1,
		IF_PROM = 0,
		IFPREPAY = 1,
		IFCASH = 1,
		IFOFEILOMENI = 0,
		IFPISTOSI = 0,
		Fpa = '1-Κανονικό'
	FROM ACCOUNTS ACC 
	JOIN @OUT ENTRIES ON ACC.ID = ENTRIES.ID AND ENTRIES.[ACTION] = 'INSERT'
	LEFT JOIN
	(
		select REPLACE(AarZipCode, ' ', '') Zip, AarName, ast.AstName, Departements.DESCR
		from Aar
		join ast on ast.AstID = aar.AarAstID
		join Departements on Departements.ID = Ast.IDDEPARTEMENT
	) ExactAreaInfo 
		ON ExactAreaInfo.Zip = REPLACE(ACC.AddressTK, ' ', '') 
		AND ExactAreaInfo.AarName LIKE ACC.AddressCity + '%'
	LEFT JOIN
	(
		SELECT
			REPLACE(AarZipCode, ' ', '') [Zip], 
			AarName, 
			Ast.AstName,
			Departements.DESCR
		FROM Aar JOIN Ast ON Ast.AstID = Aar.AarAstID
		join Departements on Departements.ID = Ast.IDDEPARTEMENT
	) ApproxAreaInfo 
		ON ApproxAreaInfo.AarName LIKE ACC.AddressCity + '%' 
		AND LEFT(ApproxAreaInfo.Zip, 1) = LEFT(REPLACE(ACC.AddressTK, ' ', ''), 1)
	
	SET @IDCREATE = (SELECT TOP 1 ID FROM @OUT) 
END

GO

---END SCRIPT 1387
