ALTER VIEW [dbo].[TIMOL_VOH_VIEW]
AS
  SELECT dbo.voh.id,
         dbo.voh.dateprint,
         dbo.kindparastatikon.code,
         dbo.voh.parastatiko,
         dbo.voh.seira,
         Cast(dbo.voh.noparast AS INT)                     AS NOPARAST,
         dbo.voh.noparastdeltioudianomis,
         dbo.voh.noparastdeltiouapostolis,
         dbo.voh.oxima,
         dbo.voh.omadproorismos,
         CASE
           WHEN ifxrentol = 1 THEN 'ΕΝΤΟΛΕΑΣ'
           ELSE
             CASE
               WHEN ifxrapost = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
               ELSE
                 CASE
                   WHEN ifxrtritou = 1 THEN 'ΤΡΙΤΟΣ'
                   ELSE
                     CASE
                       WHEN ifxrparal = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
                       ELSE 'ΑΓΝΩΣΤΟ'
                     END
                 END
             END
         END                                               AS XREOYMENOS,
         dbo.voh.apostoleasdescr,
         dbo.voh.paralisptisdescr,
         dbo.voh.entoleasdescr,
         dbo.voh.antapokritisdescr,
         dbo.voh.tritosdescr,
         Min(dbo.grammesforttikis.timda)                   AS TIMDA,
         dbo.voh.poso,
         dbo.voh.taxis,
         dbo.voh.sumposo,
         Isnull(Sum(dbo.grammesforttikis.temaxia), 0)      AS TEMAXIA,
         Isnull(Sum(dbo.grammesforttikis.baros), 0)        AS BAROS,
         Isnull(Sum(dbo.grammesforttikis.kybika), 0)       AS KYBIKA,
         Min(dbo.units.untname)                            AS SYSKEVASIA,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                        FROM   xreosis_anadeltio_view WITH (nolock)
                        WHERE  idvoh = dbo.voh.id
                               AND if_to_fortotiki = 1)
           ELSE 0
         END                                               AS
         XREOSIPROPLIROMENES,
         CASE dbo.voh.ifofeilomeni
           WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                        FROM   xreosis_anadeltio_view WITH (nolock)
                        WHERE  idvoh = dbo.voh.id
                               AND if_to_fortotiki = 1)
           ELSE 0
         END                                               AS XREOSIOFEILOMENES,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN
             CASE dbo.voh.ifcash
               WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                            FROM   xreosis_anadeltio_view WITH (nolock)
                            WHERE  idvoh = dbo.voh.id
                                   AND if_to_fortotiki = 1)
               ELSE 0
             END
           ELSE 0
         END                                               AS
            XREOSIPROPLIROMENESCASH,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN
             CASE dbo.voh.ifpistosi
               WHEN 1 THEN (SELECT Sum(sumposo) AS XREOSEIS
                            FROM   xreosis_anadeltio_view WITH (nolock)
                            WHERE  idvoh = dbo.voh.id
                                   AND if_to_fortotiki = 1)
               ELSE 0
             END
           ELSE 0
         END                                               AS
            XREOSIPROPLIROMENESPISTOSI,
         Min(dbo.grammesforttikis.periexomeno)             AS PERIEXOMENO,
         dbo.voh.perioxifortosis,
         dbo.voh.perioxiparadosis,
         dbo.voh.comments,
         dbo.voh.sumantik,
         dbo.voh.praktoreiodescr,
         dbo.voh.status,
         CONVERT(VARCHAR, dbo.voh.dateparad, 102)          AS DATEPARAD,
         dbo.voh.idapostolea,
         dbo.voh.idparalipti,
         dbo.voh.identolea,
         dbo.voh.idantapokriti,
         dbo.voh.idtritou,
         dbo.voh.idpraktoreio,
         CASE ifantikcash
           WHEN 0 THEN 0
           ELSE antikcash
         END                                               AS ANTIKCASH,
         CASE ifantikepit
           WHEN 0 THEN 0
           ELSE antikepit
         END                                               AS ANTIKEPIT,
         CASE ifantiksynal
           WHEN 0 THEN 0
           ELSE antiksynal
         END                                               AS ANTIKSYNAL,
         CASE ifantikother
           WHEN 0 THEN 0
           ELSE antikother
         END                                               AS ANTIKOTHER,
         CASE ifcancelantik
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFCANCELANTIK,
         dbo.voh.commentsantik,
         dbo.voh.dateparadosi,
         dbo.voh.comments2,
         Min(dbo.headerfortotikis.komistra)                AS KOMISTRA,
         Min(dbo.headerfortotikis.dikaiomafortotikis)      AS DIKAIOMAFORTOTIKIS
         ,
         Min(dbo.headerfortotikis.otherxreosis)            AS
         OTHERXREOSIS,
         Min(dbo.headerfortotikis.olikosynoloxreoseonfort) AS
            OLIKOSYNOLOXREOSEONFORT,
         Min(dbo.headerfortotikis.ergatika)                AS ERGATIKA,
         CASE dbo.voh.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFPREPAY,
         CASE dbo.voh.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFOFEILOMENI,
         Isnull(Sum(dbo.grammesforttikis.sumposo), 0)      AS AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRENTOL,
         dbo.voh.kindpaymentdescr,
         dbo.voh.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRTRITOU,
         dbo.voh.ifantikcash,
         dbo.voh.ifantikepit,
         dbo.voh.ifantiksynal,
         dbo.voh.ifantikother,
         dbo.voh.ifdelete,
         dbo.voh.ifcancel,
         CONVERT(VARCHAR, dbo.voh.datecancel, 102)         AS DATECANCEL,
         dbo.voh.ifparadosi,
         dbo.voh.aitiologiaparastatikou,
         CONVERT(VARCHAR, dbo.voh.datefortosis, 102)       AS DATEFORTOSIS,
         dbo.voh.ifepistrofi,
         CONVERT(VARCHAR, dbo.voh.dateepistrofis, 102)     AS DATEEPISTROFIS,
         dbo.voh.aitiologiaepistrofis,
         dbo.voh.commentsepistrofis,
         dbo.voh.ifcash,
         dbo.voh.ifpistosi,
         dbo.voh.statusdescr,
         dbo.voh.ypaitios,
         dbo.voh.ifepanadromologisi,
         dbo.voh.ifepanekdosi,
         dbo.voh.ifokepanadromologisi,
         dbo.voh.noparastantik,
         dbo.voh.commentsakirosis,
         dbo.voh.ifeisprantik,
         dbo.voh.ifparadosiantik,
         dbo.voh.ifparalaviantik,
         dbo.voh.commentsparadantik,
         dbo.voh.commantsparalantik,
         dbo.voh.commentseisprantik,
         CONVERT(VARCHAR, dbo.voh.dateparadantik, 102)     AS DATEPARADANTIK,
         CONVERT(VARCHAR, dbo.voh.dateparalantik, 102)     AS DATEPARALANTIK,
         CONVERT(VARCHAR, dbo.voh.dateeisprantik, 102)     AS DATEEISPRANTIK,
         dbo.voh.eispraxasantik,
         dbo.voh.noparparadantik,
         dbo.voh.noparasteisprantik,
         dbo.voh.noparparalantik,
         CONVERT(VARCHAR, dbo.voh.dateparal, 102)          AS DATEPARAL,
         dbo.voh.commentsparad,
         dbo.voh.commantsparal,
         dbo.voh.timeparalfrom,
         dbo.voh.timeparalto,
         dbo.voh.timeparadfrom,
         dbo.voh.timeparadto,
         CONVERT(VARCHAR, dbo.voh.datecancelantik, 102)    AS DATECANCELANTIK,
         dbo.voh.idparast,
         dbo.voh.taxispercent,
         dbo.voh.anamexodo,
         dbo.voh.id                                        AS IDFORTOTIKIS,
         dbo.voh.afmxreoumenou,
         dbo.headerfortotikis.asfalistra,
         Round(dbo.headerfortotikis.taxis, 2)              AS TAXISXREOSEON,
         dbo.headerfortotikis.sumposoxrfort,
         dbo.headerfortotikis.katharo,
         dbo.accounts.epagelma                             AS EPAGAPOST,
         dbo.accounts.addressstr                           AS ADDRSTRAPOST,
         dbo.accounts.addressno                            AS ADDRNOAPOST,
         dbo.accounts.addresstk                            AS TKAPOST,
         dbo.accounts.addresscity                          AS CITYAPOST,
         dbo.accounts.addresspref                          AS NOMOSAPOST,
         dbo.accounts.tel                                  AS TELAPOST,
         dbo.accounts.doy                                  AS DOYAPOST,
         ACCOUNTS_1.epagelma                               AS EPAGPARAL,
         ACCOUNTS_1.addressstr                             AS ADDRSTRPARAL,
         ACCOUNTS_1.addressno                              AS ADDRNOPARAL,
         ACCOUNTS_1.addresstk                              AS ADDRTKPARAL,
         ACCOUNTS_1.addresscity                            AS ADDRCITYPARAL,
         ACCOUNTS_1.addresspref                            AS ADDRNOMOSPARAL,
         ACCOUNTS_1.tel                                    AS TELPARAL,
         ACCOUNTS_1.doy                                    AS DOYPARAL,
         ACCOUNTS_2.epagelma                               AS EPAGENTOL,
         ACCOUNTS_2.addressstr                             AS ADDRSTRENTOL,
         ACCOUNTS_2.addressno                              AS ADDRNOENTOL,
         ACCOUNTS_2.addresstk                              AS ADDRTKENTOL,
         ACCOUNTS_2.addresscity                            AS ADDRCITYENTOL,
         ACCOUNTS_2.addresspref                            AS ADDRNOMOSENTOL,
         ACCOUNTS_2.tel                                    AS TELENTOL,
         ACCOUNTS_2.doy                                    AS DOYENTOL,
         ACCOUNTS_3.epagelma                               AS EPAGTR,
         ACCOUNTS_3.addressstr                             AS ADDRSTTR,
         ACCOUNTS_3.addressno                              AS ADDRNOTR,
         ACCOUNTS_3.addresstk                              AS ADDRTKTR,
         ACCOUNTS_3.addresscity                            AS ADDRCITYTR,
         ACCOUNTS_3.addresspref                            AS ADSTRDRNOMO,
         ACCOUNTS_3.tel                                    AS TELTR,
         ACCOUNTS_3.doy                                    AS DOYTR,
         dbo.voh.afmapostolea,
         dbo.voh.afmentolea,
         dbo.voh.afmparalipti,
         dbo.voh.afmtritou,
         dbo.voh.afmantapokriti,
         ACCOUNTS_1.mobile                                 AS MOBILEPARALIPTI,
         ACCOUNTS_2.mobile                                 AS MOBILEENTOLTEA,
         accounts.mobile                                   AS MOBILEAPOSTOLEA,
         ''                                                AS IDDRIVER,
         ''                                                AS DRIVERDESCR,
         dbo.voh.idxrhshs,
         dbo.voh.idcompany,
         dbo.voh.idypokatastima,
         dbo.voh.codeparast,
         dbo.voh.sxetikaparastatika,
         dbo.voh.idsxetikaparast,
         dbo.voh.idcustomer,
         dbo.voh.codecustomer,
         dbo.voh.custdescr,
         dbo.voh.arxikoposo,
         dbo.voh.discount,
         dbo.voh.discountpercent,
         dbo.voh.datekinisis,
         dbo.voh.thetime,
         dbo.voh.idskoposdiakinisis,
         dbo.voh.skoposdiakinisis,
         dbo.voh.country,
         dbo.voh.driver,
         dbo.voh.idlistas,
         dbo.voh.ifisorder,
         dbo.voh.noorder,
         dbo.voh.idorder,
         dbo.voh.ifexoflisi,
         dbo.voh.codeentolea,
         dbo.voh.codeapostolea,
         dbo.voh.codeparalipti,
         dbo.voh.seiraorder,
         dbo.voh.dateprintorder,
         dbo.voh.orderdetails,
         dbo.voh.if_close,
         dbo.voh.posoepivar,
         dbo.voh.taxisepivar,
         dbo.voh.sumposoepivar,
         dbo.voh.ext_id,
         dbo.voh.ext_barcode,
         dbo.voh.ext_details,
         dbo.voh.sumdemata,
         dbo.voh.sumpaletes,
         dbo.voh.sumstand,
         dbo.voh.sumbaros,
         dbo.voh.sumogos,
         dbo.voh.container,
         dbo.voh.boat,
         dbo.voh.exodatriton,
         dbo.VOH.OROFOS,
         dbo.VOH.OROFOSDESCR,
         dbo.VOH.KOUDOUNI,
		 dbo.VOH.NO_EXT_ORDER_IK,
		 dbo.PARADOSEIS.PARADOSISE,
		 dbo.PARADOSEIS.Eponimia,
		 dbo.PARADOSEIS.AddressCity,
