		 dbo.PARADOSEIS.AddressNo,
		 dbo.PARADOSEIS.AddressTK,
		 dbo.VOH.UserCreate,
		 dbo.VOH.UserMod,
		 dbo.VOH.IDKENTROUKOSTOUS,
		 dbo.KentraKostous.Descr as Kentro_Kostous,
		CASE 
			WHEN SUM(dbo.grammesvoh.iftransport) > 0 THEN 1
			ELSE 0
		END [iftransport],
		CASE 
			WHEN SUM(dbo.grammesvoh.ifassembly) > 0 THEN 1
			ELSE 0
		END [ifassembly],
		CASE 
