  FROM   dbo.voh WITH (nolock)
         LEFT OUTER JOIN dbo.accounts WITH (nolock)
                      ON dbo.voh.idapostolea = dbo.accounts.id
         LEFT OUTER JOIN dbo.accounts AS ACCOUNTS_1 WITH (nolock)
                      ON dbo.voh.idparalipti = ACCOUNTS_1.id
         LEFT OUTER JOIN dbo.accounts AS ACCOUNTS_2 WITH (nolock)
                      ON dbo.voh.identolea = ACCOUNTS_2.id
         LEFT OUTER JOIN dbo.accounts AS ACCOUNTS_3 WITH (nolock)
                      ON dbo.voh.idtritou = ACCOUNTS_3.id
         LEFT OUTER JOIN dbo.kindparastatikon WITH (nolock)
                      ON dbo.voh.idparast = dbo.kindparastatikon.id
         LEFT OUTER JOIN dbo.grammesforttikis WITH (nolock)
                      ON dbo.grammesforttikis.idvoh = dbo.voh.id
         LEFT OUTER JOIN dbo.headerfortotikis WITH (nolock)
                      ON dbo.headerfortotikis.idfort = dbo.voh.id
         LEFT OUTER JOIN dbo.units WITH (nolock) ON dbo.grammesforttikis.syskevasia = dbo.units.UntID
         LEFT OUTER JOIN dbo.PARADOSEIS  ON dbo.PARADOSEIS.idvoh=dbo.VOH.ID
         LEFT OUTER JOIN dbo.KentraKostous ON dbo.KentraKostous.id=dbo.VOH.IDKENTROUKOSTOUS
         LEFT OUTER JOIN dbo.grammesvoh ON dbo.grammesvoh.idvoh=dbo.voh.id
  GROUP  BY dbo.voh.id,
            dbo.voh.dateprint,
