---NEW SCRIPT 1399
CREATE TRIGGER [dbo].[FORTOTIKES_FIX_PRAKTOREIO_FROM_LINK]
   ON  [dbo].[FORTOTIKES]
   AFTER INSERT
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;    update fort
		set 
			IDPRAKTOREIO=coalesce(prk.id, fort.IDPRAKTOREIO), 
			PRAKTOREIODESCR = coalesce(prk.Eponimia, fort.PRAKTOREIODESCR)
	from inserted 
	join FORTOTIKES fort on fort.id = inserted.id
	join (
		select min(aarid) aarid, aarname from Aar group by AarName
	) aar2 on aar2.AarName=fort.PERIOXIPARADOSIS
	join Aar on aar.AarID = aar2.aarid
	left join AarPerOmProor on AarPerOmProor.AarID = aar.AarID
	left join OMADIKOI_PROORISMOI omproor on omproor.id = AarPerOmProor.IDOmProor
	left join _Link_Prk_Per_Aar link1 on link1.IDAAR = aar.aarid
	left join _Link_Prk_Per_OmProor link2 on link2.IDOMPROOR = omproor.id
	left join PRAKTOREIA prk on prk.id = COALESCE(link1.IDPRK, link2.idprk)
	where prk.id is not null
END

GO
---END SCRIPT 1399
------------------------------------------------------------------------------------ 
---NEW SCRIPT 1400

CREATE TRIGGER [dbo].[PARADOSEIS_FIX_PRAKTOREIO_FROM_LINK]
   ON  [dbo].[PARADOSEIS]
   AFTER INSERT
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;    update voh
		set IDPRAKTOREIO=coalesce(prk.id, voh.IDPRAKTOREIO), 
			PRAKTOREIODESCR = coalesce(prk.Eponimia, voh.PRAKTOREIODESCR)
	from inserted p
	join voh on p.IDVOH=voh.ID
	join (
		select min(aarid) aarid, aarname from Aar group by AarName
	) aar2 on aar2.AarName=p.AddressCity
	join Aar on aar.AarID = aar2.aarid
	left join AarPerOmProor on AarPerOmProor.AarID = aar.AarID
	left join OMADIKOI_PROORISMOI omproor on omproor.id = AarPerOmProor.IDOmProor
	left join _Link_Prk_Per_Aar link1 on link1.IDAAR = aar.aarid
	left join _Link_Prk_Per_OmProor link2 on link2.IDOMPROOR = omproor.id
	left join PRAKTOREIA prk on prk.id = COALESCE(link1.IDPRK, link2.idprk)
	where prk.id is not null
END
GO

---END SCRIPT 1400
