CREATE TABLE [DBO].[LASTARRIVALS](
	[ID] [NUMERIC](18, 0) IDENTITY(1,1) NOT NULL,
	[IDCOMPANY] [NUMERIC](18, 0) NULL,
	[IDYPOKATASTIMA] [NUMERIC](18, 0) NULL,
	[BarCode] [NVARCHAR](20) NULL,
	[ifDelete] [INT] NULL,
	[IF_CLOSE] [INT] NULL)
	
GO
	
	CREATE FUNCTION dbo.fnNumPadLeft (@input INT, @pad tinyint)
	RETURNS VARCHAR(250)
	AS BEGIN
		DECLARE @NumStr VARCHAR(250)

		SET @NumStr = LTRIM(@input)

		IF(@pad > LEN(@NumStr))
			SET @NumStr = REPLICATE('0', @Pad - LEN(@NumStr)) + @NumStr;

		RETURN @NumStr;
	END

GO

---END SCRIPT 1405
------------------------------------------------------------------------------------ 


---NEW SCRIPT 1406



CREATE PROCEDURE [dbo].[CREATE_ARRIVALS]
(
	@IDCOMPANY			NUMERIC(18, 0) = NULL,
	@IDYPOKATASTIMA		NUMERIC(18, 0) = NULL,
	@COUNT				INT = 0,
	@ifDelete			NUMERIC(18, 0) = NULL,
	@IF_CLOSE			NUMERIC(18, 0) = NULL,
	@IFOK				NUMERIC(18, 0)= NULL output
	)
AS

DECLARE @DIGITS1 NVARCHAR(2)
DECLARE @DIGITS2 NVARCHAR(2)
DECLARE @DIGITS3 NVARCHAR(8)
DECLARE @BAR_CODE NVARCHAR(12)
DECLARE @CNT NUMERIC(8, 0)
DECLARE @NEMAXNUMBER NUMERIC(18, 0)
DECLARE @LASTNUMBER NUMERIC(18, 0)

DELETE FROM LASTARRIVALS WHERE IDCOMPANY = @IDCOMPANY AND IDYPOKATASTIMA = @IDYPOKATASTIMA

SELECT @CNT = ISNULL(MAX(LASTCOUNTER), 0) FROM ARRIVALSMASTER WHERE IDCOMPANY = @IDCOMPANY AND IDYPOKATASTIMA = @IDYPOKATASTIMA GROUP BY IDYPOKATASTIMA
SELECT @NEMAXNUMBER = @CNT + @COUNT

WHILE @CNT < @NEMAXNUMBER
BEGIN
	SET  @DIGITS1 = DBO.fnNumPadLeft (@IDCOMPANY,2)
	SET  @DIGITS2 = DBO.fnNumPadLeft (@IDYPOKATASTIMA,2)
	SET  @DIGITS3 = DBO.fnNumPadLeft (@CNT,8)
	SET  @BAR_CODE = @DIGITS1 + @DIGITS2 + @DIGITS3
	--PRINT @DIGITS1 
	--PRINT @DIGITS2 
	--PRINT @DIGITS3 
	--PRINT @BAR_CODE 
	--PRINT  @CNT
   INSERT INTO LASTARRIVALS (IDCOMPANY,	IDYPOKATASTIMA,	BarCode, ifDelete,	IF_CLOSE)
   VALUES (@IDCOMPANY, @IDYPOKATASTIMA, @BAR_CODE, @ifDelete, @IF_CLOSE)
   SET  @CNT = @CNT + 1
END;
IF EXISTS (SELECT ID FROM ARRIVALSMASTER WHERE IDCOMPANY = @IDCOMPANY AND IDYPOKATASTIMA = @IDYPOKATASTIMA)
	BEGIN
		UPDATE ARRIVALSMASTER SET LASTCOUNTER = @NEMAXNUMBER WHERE IDCOMPANY = @IDCOMPANY AND IDYPOKATASTIMA = @IDYPOKATASTIMA
	END
ELSE
	BEGIN
		INSERT INTO ARRIVALSMASTER (LASTCOUNTER, IDCOMPANY,  IDYPOKATASTIMA, DATECREATE) VALUES 
		(@NEMAXNUMBER, @IDCOMPANY, @IDYPOKATASTIMA, GETDATE())
	END
	
SELECT @IFOK = 1
GO




---END SCRIPT 1406
------------------------------------------------------------------------------------ 


