         dbo.voh.timeparadfrom,
         dbo.voh.timeparadto,
         CONVERT(VARCHAR, dbo.voh.datecancelantik, 102)    AS DATECANCELANTIK,
         dbo.voh.idparast,
         dbo.voh.taxispercent,
         dbo.voh.anamexodo,
         dbo.voh.id                                        AS IDFORTOTIKIS,
         dbo.voh.afmxreoumenou,
         dbo.headerfortotikis.asfalistra,
         Round(dbo.headerfortotikis.taxis, 2)              AS TAXISXREOSEON,
         dbo.headerfortotikis.sumposoxrfort,
