ALTER PROCEDURE [dbo].[InserttoACCOUNTS_FromXML] 
	@Eponimia NVARCHAR(100),
	@Diefthinsi NVARCHAR(100),
	@Perioxi NVARCHAR(100),
	@TK NVARCHAR(10) = null,
	@Tilefono NVARCHAR(50)= null,
	@Email NVARCHAR(50) = null,
	@IDCREATE INT OUTPUT
AS
BEGIN
	DECLARE @OUT TABLE([ACTION] NVARCHAR(10), ID INT);

	DECLARE @AARID INT;
	DECLARE @FILTEREDAARNAME NVARCHAR(50)
	DECLARE @FILTEREDADDRESS NVARCHAR(80)
	DECLARE @FILTEREDTK NVARCHAR(10)


	SELECT @AARID=AarID from Aar WHERE AarZipCode = @TK AND AarName = @Perioxi

	IF @AARID IS NULL SELECT @AARID=AarID from AarAlternativeNames WHERE [FreeText] LIKE '%' + @Perioxi + '%' and ISNULL(FreeZip, '') = @TK

	IF @AARID IS NULL
		BEGIN
			INSERT INTO AarAlternativeNames([FreeText], [FreeZip])
			VALUES (@Perioxi, @TK)
		END

	IF @AARID IS NULL SELECT TOP 1 @AARID=AarID from Aar WHERE AarZipCode = @TK
	IF @AARID IS NULL SELECT TOP 1 @AARID=AarID from Aar WHERE AarZipCode = '00000'
	IF @AARID IS NULL
	BEGIN
		RAISERROR (15600, 12, 1, 'No valid zipcode');  
		RETURN -1
	END 

	SELECT @FILTEREDAARNAME=AarName FROM Aar WHERE AarId = @AARID
	SELECT @FILTEREDTK=AarZipcode FROM Aar WHERE AarId = @AARID

	SELECT @FILTEREDADDRESS= CASE WHEN LEN(LTRIM(RTRIM(@Perioxi))) > 0 THEN @Diefthinsi +'(' + @Perioxi + ')' ELSE @Diefthinsi END;
	
	MERGE [Accounts] WITH (HOLDLOCK) AS target
	USING (
		VALUES(@Eponimia, @FILTEREDADDRESS, @FILTEREDAARNAME, @FILTEREDTK, @Tilefono, @Email)
	) AS source(Eponimia, Diefthinsi, Perioxi, TK, Mobile, Email)
	ON 
		target.Eponimia = source.Eponimia
		AND	target.AddressStr = source.Diefthinsi
		AND target.AddressCity = source.Perioxi
		AND target.AddressTK = REPLACE(source.TK, ' ', '')
	WHEN NOT MATCHED THEN
		INSERT (Eponimia, AddressStr, AddressCity, AddressTK, Mobile, EMAIL)
		VALUES (source.Eponimia, source.Diefthinsi, source.Perioxi, source.TK, source.Mobile, source.Email)
	WHEN MATCHED THEN 
		UPDATE SET 
				target.Mobile = source.Mobile,
				target.EMAIL = source.Email	
	OUTPUT $action, INSERTED.ID INTO @OUT;

	UPDATE ACC
	SET
		XREOUMENOS = 1,
		IDPARAST = PARAST.id,
		PARASTATIKODESCR = PARAST.Descr,
		Code = 'PEL-' + CONVERT(VARCHAR, ACC.id),
		Epagelma = '',
		LastName = Eponimia,
		FirstName = '',
		AddressNo = '',
		AddressCity = ACC.AddressCity,
		AddressPref = AreaInfo.AstName,
		AddressZone = AreaInfo.DESCR,
		AddressCountry = 'ΕΛΛΑΔΑ',
		Tel2 = '',
		Fax = '',
		Mobile = '',
		AFM = '',
		DOY = '',
		CatProm = '',
		AMIKA = '',
		AMKA = '',
		AddrFortosis = AddressStr,
		Comments = '',
		AFMENTOLEA = '',
		PROTPERIEXOMENO = '',
		DISCPERCENT = 0,
		CodeLog = '',
		IF_PEL = 1,
		IF_PROM = 0,
		IFPREPAY = 1,
		IFCASH = 1,
		IFOFEILOMENI = 0,
		IFPISTOSI = 0,
		Fpa = '1-Κανονικό'
	FROM ACCOUNTS ACC 
	JOIN @OUT ENTRIES ON ACC.ID = ENTRIES.ID AND ENTRIES.[ACTION] = 'INSERT'
	JOIN KINDPARASTATIKON PARAST ON PARAST.ID = 4
	LEFT JOIN
	(
		select REPLACE(AarZipCode, ' ', '') Zip, AarName, ast.AstName, Departements.DESCR
		from Aar
		join ast on ast.AstID = aar.AarAstID
		join Departements on Departements.ID = Ast.IDDEPARTEMENT
	) AreaInfo 
		ON AreaInfo.Zip = ACC.AddressTK
		AND AreaInfo.AarName LIKE ACC.AddressCity
	
	SET @IDCREATE = (SELECT TOP 1 ID FROM @OUT) 
END

GO



---END SCRIPT 1410
------------------------------------------------------------------------------------ 


