                      FORTOTIKES.UserMod, FORTOTIKES.DateMod, FORTOTIKES.IF_FROM_ANTAP, FORTOTIKES.IF_TO_ANTAP,
                      dbo.FORTOTIKES.ARANAFORAS,
					  DBO.COMPANIES.Eponimia AS YPOKATASTHMA,
					  DBO.COMPANIES.AddressStr AS ADDRESS_YPOKATASTHMA,
					  dbo.COMPANIES.AddressTK AS TK_YPOKATASTHMA,
					  dbo.COMPANIES.AddressCity as CITY_YPOKATASTHMA,
					  dbo.COMPANIES.BARCODE_Prefix AS BARCODEPREFIX_YPOKAT,
					  DBO.COMPANIES.EMAIL AS EMAIL_YPOKATASTHMA 
FROM         dbo.FORTOTIKES WITH (NOLOCK) 
					  LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) ON dbo.FORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON dbo.FORTOTIKES.IDENTOLEA = ACCOUNTS_2.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON dbo.FORTOTIKES.IDTRITOU = ACCOUNTS_3.id 
					  LEFT OUTER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID 
					  LEFT OUTER JOIN PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID 
					  INNER JOIN CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0 
					  LEFT OUTER JOIN dbo.GRAMMESFORTTIKIS WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.IDVOH = dbo.FORTOTIKES.ID 
					  LEFT OUTER JOIN dbo.HEADERFORTOTIKIS WITH (NOLOCK) ON dbo.HEADERFORTOTIKIS.IDFORT = dbo.FORTOTIKES.ID 
                      LEFT OUTER JOIN dbo.Units WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.SYSKEVASIA = dbo.Units.UntID
                      LEFT OUTER JOIN dbo.COMPANIES on dbo.COMPANIES.id=dbo.FORTOTIKES.IDYPOKATASTIMA
GROUP BY dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, dbo.FORTOTIKES.NOPARAST, 
                      dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.IFPREPAY, dbo.FORTOTIKES.IFOFEILOMENI, dbo.FORTOTIKES.SUMPOSO, 
                      dbo.FORTOTIKES.IDAPOSTOLEA, ACCOUNTS_3.Eponimia, dbo.FORTOTIKES.IDPARALIPTI, FORTOTIKES.ENTOLEASDESCR, 
                      dbo.FORTOTIKES.IDENTOLEA, FORTOTIKES.APOSTOLEASDESCR, dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.ANTAPOKRITISDESCR, 
                      dbo.FORTOTIKES.IDTRITOU, FORTOTIKES.PARALISPTISDESCR, dbo.FORTOTIKES.IDPRAKTOREIO, dbo.FORTOTIKES.PRAKTOREIODESCR, 
                      dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.ANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, 
                      dbo.FORTOTIKES.ANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.ANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, 
                      dbo.FORTOTIKES.ANTIKOTHER, dbo.FORTOTIKES.IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.STATUS, dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.PERIOXIFORTOSIS, 
                      dbo.FORTOTIKES.PERIOXIPARADOSIS, dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.COMMENTS2, dbo.FORTOTIKES.OMADPROORISMOS, 
                      dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, dbo.FORTOTIKES.IFXRAPOST, 
                      dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, dbo.FORTOTIKES.IFXRTRITOU, dbo.FORTOTIKES.IFANTIKCASH, 
                      dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, dbo.FORTOTIKES.ifDelete, 
                      dbo.FORTOTIKES.IFCANCEL, dbo.FORTOTIKES.DATECANCEL, dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, 
                      dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.IFXRTRITOU, dbo.FORTOTIKES.ANAMEXODO, dbo.FORTOTIKES.IFPARADOSI, 
                      dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, dbo.FORTOTIKES.DATEFORTOSIS, dbo.FORTOTIKES.IFEPISTROFI, dbo.FORTOTIKES.DATEEPISTROFIS, 
                      dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, dbo.FORTOTIKES.IFPISTOSI, 
                      dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, dbo.FORTOTIKES.IFEPANEKDOSI, 
                      dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, 
                      dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.IFPARADOSIANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK,  FORTOTIKES.IF_TRANSFTOESEX, 
                      dbo.FORTOTIKES.COMMENTSPARADANTIK, dbo.FORTOTIKES.COMMANTSPARALANTIK, dbo.FORTOTIKES.COMMENTSEISPRANTIK, 
                      dbo.FORTOTIKES.DATEPARADANTIK, dbo.FORTOTIKES.DATEPARALANTIK, dbo.FORTOTIKES.DATEEISPRANTIK, dbo.FORTOTIKES.EISPRAXASANTIK, 
                      dbo.FORTOTIKES.NOPARPARADANTIK, dbo.FORTOTIKES.NOPARASTEISPRANTIK, dbo.FORTOTIKES.NOPARPARALANTIK, FORTOTIKES.NOLISTASANTIK,
                      dbo.FORTOTIKES.DATEPARAL, dbo.FORTOTIKES.DATEPARAD, dbo.FORTOTIKES.COMMENTSPARAD, dbo.FORTOTIKES.COMMANTSPARAL, 
                      dbo.FORTOTIKES.TIMEPARALFROM, dbo.FORTOTIKES.TIMEPARALTO, dbo.FORTOTIKES.TIMEPARADFROM, dbo.FORTOTIKES.TIMEPARADTO, 
                      dbo.FORTOTIKES.ANTIKCASH, dbo.FORTOTIKES.ANTIKEPIT, dbo.FORTOTIKES.ANTIKSYNAL, dbo.FORTOTIKES.ANTIKOTHER, 
