ALTER VIEW [dbo].[VOH_EDOLES_VIEW]
AS
SELECT DISTINCT 
                      dbo.VOH.ID, dbo.VOH.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.VOH.PARASTATIKO, dbo.VOH.SEIRA, dbo.VOH.NOPARAST, dbo.VOH.CustDescr, 
                      dbo.VOH.EPAGELMA, dbo.VOH.AFM, dbo.VOH.CITY, dbo.VOH.TEL, dbo.VOH.MOBILE, dbo.VOH.POSO, dbo.VOH.TAXIS, dbo.VOH.SUMPOSO, dbo.VOH.OXIMA, 
                      dbo.VOH.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE
                       WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, dbo.VOH.NOPARASTDELTIOUDIANOMIS, 
                      dbo.VOH.NOPARASTDELTIOUAPOSTOLIS, MIN(dbo.GRAMMESVOH.TIMDA) AS TIMDA, ISNULL(SUM(dbo.GRAMMESVOH.TEMAXIA), 0) AS TEMAXIA, 
                      ISNULL(SUM(dbo.GRAMMESVOH.BAROS), 0) AS BAROS, ISNULL(SUM(dbo.GRAMMESVOH.KYBIKA), 0) AS KYBIKA, CASE dbo.VOH.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1 AND IF_TO_VOH = 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.VOH.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1 AND IF_TO_VOH = 1) ELSE 0 END AS XREOSIOFEILOMENES, MIN(dbo.GRAMMESVOH.PERIEXOMENO) 
                      AS PERIEXOMENO, dbo.VOH.PERIOXIFORTOSIS, dbo.VOH.PERIOXIPARADOSIS, dbo.VOH.COMMENTS, dbo.VOH.SUMANTIK, dbo.VOH.PRAKTOREIODESCR, 
                      dbo.VOH.STATUS, dbo.VOH.DATEPARAD, dbo.VOH.IDPRAKTOREIO, CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, 
                      CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, 
                      dbo.VOH.COMMENTSANTIK, dbo.VOH.DATEPARADOSI, dbo.VOH.COMMENTS2, MIN(dbo.SUM_XREOSEIS_GRAMMES_VOH.KOMISTRA) AS KOMISTRA, 
                      MIN(dbo.SUM_XREOSEIS_GRAMMES_VOH.XREOSISTRITON) AS XREOSISTRITON, MIN(dbo.SUM_XREOSEIS_GRAMMES_VOH.DIKAIOMAFORTOTIKIS) 
                      AS DIKAIOMAFORT, MIN(dbo.SUM_XREOSEIS_GRAMMES_VOH.OTHERXREOSIS) AS OTHERXREOSIS, 
                      CASE dbo.VOH.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, CASE dbo.VOH.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, 
                      ISNULL(SUM(dbo.GRAMMESVOH.SUMPOSO), 0) AS AXIA, CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.VOH.KINDPAYMENTDESCR, 
                      dbo.VOH.IDKINDPAYMENT, CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
                      CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, dbo.VOH.IFANTIKCASH, 
                      dbo.VOH.IFANTIKEPIT, dbo.VOH.IFANTIKSYNAL, dbo.VOH.IFANTIKOTHER, dbo.VOH.ifDelete, dbo.VOH.IFCANCEL, dbo.VOH.DATECANCEL, dbo.VOH.IFPARADOSI, 
                      dbo.VOH.AITIOLOGIAPARASTATIKOU, dbo.VOH.DATEFORTOSIS, dbo.VOH.IFEPISTROFI, dbo.VOH.DATEEPISTROFIS, dbo.VOH.AITIOLOGIAEPISTROFIS, 
                      dbo.VOH.COMMENTSEPISTROFIS, dbo.VOH.IFCASH, dbo.VOH.IFPISTOSI, dbo.VOH.STATUSDESCR, dbo.VOH.YPAITIOS, dbo.VOH.IFEPANADROMOLOGISI, 
                      dbo.VOH.IFEPANEKDOSI, dbo.VOH.IFOKEPANADROMOLOGISI, dbo.VOH.NOPARASTANTIK, dbo.VOH.COMMENTSAKIROSIS, dbo.VOH.IFEISPRANTIK, 
                      dbo.VOH.IFPARADOSIANTIK, dbo.VOH.IFPARALAVIANTIK, dbo.VOH.COMMENTSPARADANTIK, dbo.VOH.COMMANTSPARALANTIK, dbo.VOH.COMMENTSEISPRANTIK, 
                      dbo.VOH.DATEPARADANTIK, dbo.VOH.DATEPARALANTIK, dbo.VOH.DATEEISPRANTIK, dbo.VOH.EISPRAXASANTIK, dbo.VOH.NOPARPARADANTIK, 
                      dbo.VOH.NOPARASTEISPRANTIK, dbo.VOH.NOPARPARALANTIK, dbo.VOH.DATEPARAL, dbo.VOH.COMMENTSPARAD, dbo.VOH.COMMANTSPARAL, 
                      dbo.VOH.TIMEPARALFROM, dbo.VOH.TIMEPARALTO, dbo.VOH.TIMEPARADFROM, dbo.VOH.TIMEPARADTO, dbo.VOH.DATECANCELANTIK, dbo.VOH.IDPARAST, 
                      dbo.VOH.TAXISPERCENT, dbo.VOH.ANAMEXODO, dbo.VOH.ID AS IDVOH, CXR.IDXREOUMENOU, dbo.VOH.AFMXREOUMENOU, dbo.SUM_XREOSEIS_GRAMMES_VOH.ASFALISTRA, 
                      dbo.SUM_XREOSEIS_GRAMMES_VOH.TAXIS AS TAXISXREOSEON, dbo.SUM_XREOSEIS_GRAMMES_VOH.SUMPOSOXRVOH, 
                      VOH.POSOEPIVAR, VOH.TAXISEPIVAR, VOH.SUMPOSOEPIVAR, (VOH.POSO + VOH.POSOEPIVAR) AS SUMKATHARO, (VOH.TAXIS + VOH.TAXISEPIVAR) AS SUMTAXIS, (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) AS SUMSUMPOSO, 
                      dbo.SUM_XREOSEIS_GRAMMES_VOH.KATHARO, dbo.VOH.THETIME, dbo.VOH.IDENTOLEA AS CUSTOMERID, dbo.VOH.ENTOLEASDESCR AS CUSTOMERDESCR, 
                      dbo.VOH.IDAPOSTOLEA AS IDSYNAL, dbo.VOH.APOSTOLEASDESCR AS SYNALDESCR, dbo.VOH.IDCUSTOMER, dbo.VOH.DOY, dbo.VOH.ADDRESSSTREET, 
                      dbo.VOH.ADDRESSNO, dbo.VOH.PREF, dbo.VOH.AFMAPOSTOLEA, ACCOUNTS_1.Epagelma AS SYNALEPAGELMA, ACCOUNTS_1.AddressStr AS SYNALADDRSTR, 
                      ACCOUNTS_1.AddressNo AS SYNALADDRNO, ACCOUNTS_1.AddressTK AS SYNALADDRTK, ACCOUNTS_1.AddressCity AS SYNALCITY, 
                      ACCOUNTS_1.AddressCountry AS SYNALADDRCOUNTRY, ACCOUNTS_1.Tel AS SYNALTEL, ACCOUNTS_1.DOY AS SYNALDOY, ACCOUNTS_1.AFM AS SYNALAFM, 
                      dbo.ACCOUNTS.AddressTK AS CUSTADDRTK, dbo.ACCOUNTS.AddressNo AS CUSTADDRNO, dbo.ACCOUNTS.AddressStr AS CUSTADDRSTR, 
                      dbo.ACCOUNTS.AddressCity AS CUSTADDRCITY, dbo.ACCOUNTS.AFM AS CUSTAFM, dbo.ACCOUNTS.DOY AS CUSTDOY, KINDPARASTATIKON.IF_TRANSFORM,
                      dbo.VOH.IDXRHSHS, dbo.VOH.IDCOMPANY, dbo.VOH.IDYPOKATASTIMA, VOH.IF_CLOSE, KINDPARASTATIKON.IF_ORDER, KINDPARASTATIKON.KindKINISIS,
                      dbo.KINDPARASTATIKON.IF_EDMETAFORAS, dbo.KINDPARASTATIKON.IF_EDSYNARMOL, dbo.KINDPARASTATIKON.IF_ENDILMETAFORAS, KINDPARASTATIKON.IF_EDTOPOTH,
					  dbo.voh.EXT_BARCODE,  dbo.voh.NO_EXT_ORDER, dbo.voh.NO_EXT_ORDER_IK,	DBO.COMPANIES.Eponimia AS YPOKATASTHMA,
					  DBO.COMPANIES.AddressStr AS ADDRESS_YPOKATASTHMA,	dbo.COMPANIES.AddressTK AS TK_YPOKATASTHMA, dbo.COMPANIES.AddressCity as CITY_YPOKATASTHMA,
					  dbo.COMPANIES.BARCODE_Prefix AS BARCODEPREFIX_YPOKAT,  DBO.COMPANIES.EMAIL AS EMAIL_YPOKATASTHMA  
FROM         dbo.ACCOUNTS WITH (NOLOCK) RIGHT OUTER JOIN
                      dbo.SUM_XREOSEIS_GRAMMES_VOH WITH (NOLOCK) RIGHT OUTER JOIN
                      dbo.Products WITH (NOLOCK) INNER JOIN
                      dbo.GRAMMESVOH ON dbo.Products.Code = dbo.GRAMMESVOH.CodeEidos RIGHT OUTER JOIN
                      dbo.VOH WITH (NOLOCK) ON dbo.GRAMMESVOH.IDVOH = dbo.VOH.ID ON dbo.SUM_XREOSEIS_GRAMMES_VOH.IDVOH = dbo.VOH.ID ON 
                      dbo.ACCOUNTS.id = dbo.VOH.IDCUSTOMER LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.VOH.IDAPOSTOLEA = ACCOUNTS_1.id LEFT OUTER JOIN
                      dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.VOH.IDPARAST = dbo.KINDPARASTATIKON.ID 
                      INNER JOIN (SELECT ID, IDPARAST, 
CASE WHEN IFXRENTOL = 1 THEN IDENTOLEA ELSE CASE WHEN IFXRAPOST = 1  THEN CXR.IDAPOSTOLEA ELSE CASE WHEN 
IFXRTRITOU = 1 THEN IDTRITOU ELSE CASE WHEN IFXRPARAL = 1 THEN CXR.IDPARALIPTI ELSE CXR.IDCUSTOMER END END
END END AS IDXREOUMENOU FROM VOH AS CXR) AS CXR ON  CXR.ID = VOH.ID 
         LEFT OUTER JOIN  COMPANIES on dbo.COMPANIES.id=dbo.VOH.IDYPOKATASTIMA    
WHERE     (dbo.VOH.IDPARAST IN (SELECT ID FROM dbo.KINDPARASTATIKON AS KINPAR WITH (NOLOCK) 
					WHERE (KINPAR.IF_EDMETAFORAS = 1 OR KINPAR.IF_EDSYNARMOL = 1 OR KINPAR.IF_ENDILMETAFORAS = 1 OR  KINPAR.IF_EDTOPOTH = 1))) 
GROUP BY dbo.VOH.ID, dbo.VOH.DATEPRINT, dbo.VOH.PARASTATIKO, dbo.VOH.SEIRA, dbo.VOH.NOPARAST, dbo.VOH.OXIMA, dbo.VOH.IFPREPAY, dbo.VOH.IFOFEILOMENI, 
                      dbo.VOH.SUMPOSO, dbo.VOH.IDPRAKTOREIO, dbo.VOH.PRAKTOREIODESCR, dbo.VOH.SUMANTIK, dbo.VOH.IFANTIKCASH, dbo.VOH.ANTIKCASH, 
                      dbo.VOH.IFANTIKEPIT, dbo.VOH.ANTIKEPIT, dbo.VOH.IFANTIKSYNAL, dbo.VOH.ANTIKSYNAL, dbo.VOH.IFANTIKOTHER, dbo.VOH.ANTIKOTHER, 
                      dbo.VOH.IFCANCELANTIK, dbo.VOH.COMMENTSANTIK, dbo.VOH.POSO, dbo.VOH.TAXIS, dbo.VOH.STATUS, dbo.VOH.NOPARASTDELTIOUAPOSTOLIS, 
                      dbo.VOH.NOPARASTDELTIOUDIANOMIS, dbo.VOH.DATEPARADOSI, dbo.VOH.PERIOXIFORTOSIS, dbo.VOH.PERIOXIPARADOSIS, dbo.VOH.COMMENTS, 
                      dbo.VOH.COMMENTS2, dbo.VOH.OMADPROORISMOS, dbo.VOH.IFXRENTOL, dbo.VOH.KINDPAYMENTDESCR, dbo.VOH.IDKINDPAYMENT, dbo.VOH.IFXRAPOST, 
                      dbo.VOH.IFXRAPOST, dbo.VOH.IFXRPARAL, dbo.VOH.IFXRTRITOU, dbo.VOH.IFANTIKCASH, dbo.VOH.IFANTIKEPIT, dbo.VOH.IFANTIKSYNAL, dbo.VOH.IFANTIKOTHER, 
                      dbo.VOH.ifDelete, dbo.VOH.IFCANCEL, dbo.VOH.DATECANCEL, dbo.VOH.IFXRAPOST, dbo.VOH.IFXRPARAL, dbo.VOH.IFXRENTOL, dbo.VOH.IFXRTRITOU, 
                      dbo.VOH.ANAMEXODO, dbo.VOH.IFPARADOSI, dbo.VOH.AITIOLOGIAPARASTATIKOU, dbo.VOH.DATEFORTOSIS, dbo.VOH.IFEPISTROFI, dbo.VOH.DATEEPISTROFIS, 
                      dbo.VOH.AITIOLOGIAEPISTROFIS, dbo.VOH.COMMENTSEPISTROFIS, dbo.VOH.IFCASH, dbo.VOH.IFPISTOSI, dbo.VOH.STATUSDESCR, dbo.VOH.YPAITIOS, 
                      dbo.VOH.IFEPANADROMOLOGISI, dbo.VOH.IFEPANEKDOSI, dbo.VOH.IFOKEPANADROMOLOGISI, dbo.VOH.NOPARASTANTIK, dbo.VOH.COMMENTSAKIROSIS, 
                      dbo.VOH.IFEISPRANTIK, dbo.VOH.IFPARADOSIANTIK, dbo.VOH.IFPARALAVIANTIK, dbo.VOH.COMMENTSPARADANTIK, dbo.VOH.COMMANTSPARALANTIK, 
                      dbo.VOH.COMMENTSEISPRANTIK, dbo.VOH.DATEPARADANTIK, dbo.VOH.DATEPARALANTIK, dbo.VOH.DATEEISPRANTIK, dbo.VOH.EISPRAXASANTIK, 
                      dbo.VOH.NOPARPARADANTIK, dbo.VOH.NOPARASTEISPRANTIK, dbo.VOH.NOPARPARALANTIK, dbo.VOH.DATEPARAL, dbo.VOH.DATEPARAD, KINDPARASTATIKON.KindKINISIS, 
                      dbo.VOH.COMMENTSPARAD, dbo.VOH.COMMANTSPARAL, dbo.VOH.TIMEPARALFROM, dbo.VOH.TIMEPARALTO, dbo.VOH.TIMEPARADFROM, dbo.VOH.TIMEPARADTO, 
                      dbo.VOH.ANTIKCASH, dbo.VOH.ANTIKEPIT, dbo.VOH.ANTIKSYNAL, dbo.VOH.ANTIKOTHER, dbo.VOH.IFCANCELANTIK, dbo.VOH.DATECANCELANTIK, 
                      dbo.VOH.TAXISPERCENT, dbo.VOH.IDPARAST, dbo.KINDPARASTATIKON.Code, CXR.IDXREOUMENOU, dbo.VOH.AFMXREOUMENOU, dbo.SUM_XREOSEIS_GRAMMES_VOH.ASFALISTRA, 
                      dbo.SUM_XREOSEIS_GRAMMES_VOH.TAXIS, dbo.SUM_XREOSEIS_GRAMMES_VOH.SUMPOSOXRVOH, dbo.SUM_XREOSEIS_GRAMMES_VOH.KATHARO, 
                      VOH.POSOEPIVAR, TAXISEPIVAR, VOH.SUMPOSOEPIVAR,
                      dbo.VOH.CustDescr, dbo.VOH.EPAGELMA, dbo.VOH.AFM, dbo.VOH.CITY, dbo.VOH.TEL, dbo.VOH.MOBILE, dbo.VOH.THETIME, dbo.VOH.IDAPOSTOLEA, 
                      dbo.VOH.APOSTOLEASDESCR, dbo.VOH.IDPARALIPTI, dbo.VOH.PARALISPTISDESCR, dbo.VOH.IDCUSTOMER, dbo.VOH.DOY, dbo.VOH.ADDRESSSTREET, 
                      dbo.VOH.ADDRESSNO, dbo.VOH.PREF, dbo.VOH.AFMAPOSTOLEA, ACCOUNTS_1.Epagelma, ACCOUNTS_1.AddressStr, ACCOUNTS_1.AddressNo, 
                      dbo.VOH.ENTOLEASDESCR, ACCOUNTS_1.AddressTK, ACCOUNTS_1.AddressCity, ACCOUNTS_1.AddressCountry, ACCOUNTS_1.Tel, ACCOUNTS_1.DOY, 
                      ACCOUNTS_1.AFM, dbo.VOH.IDENTOLEA, dbo.ACCOUNTS.AddressTK, dbo.ACCOUNTS.AddressNo, dbo.ACCOUNTS.AddressStr, dbo.ACCOUNTS.AddressCity, 
                      dbo.ACCOUNTS.AFM, dbo.ACCOUNTS.DOY, dbo.VOH.IDXRHSHS, dbo.VOH.IDCOMPANY, dbo.VOH.IDYPOKATASTIMA, KINDPARASTATIKON.IF_TRANSFORM, VOH.IF_CLOSE, 
                      KINDPARASTATIKON.IF_ORDER, dbo.KINDPARASTATIKON.IF_EDMETAFORAS, dbo.KINDPARASTATIKON.IF_EDSYNARMOL, dbo.KINDPARASTATIKON.IF_ENDILMETAFORAS, KINDPARASTATIKON.IF_EDTOPOTH,
                      dbo.voh.EXT_BARCODE,  dbo.voh.NO_EXT_ORDER, dbo.voh.NO_EXT_ORDER_IK,	DBO.COMPANIES.Eponimia,
					  DBO.COMPANIES.AddressStr,	dbo.COMPANIES.AddressTK, dbo.COMPANIES.AddressCity,  dbo.COMPANIES.BARCODE_Prefix,  DBO.COMPANIES.EMAIL





