ALTER VIEW [dbo].[ISOZYGIO_ESODA_EXODA]
AS
SELECT     '103' + dbo.ESODA.ID AS ID, dbo.ESODA.DATEPRINT AS DATEPRINT, ACCOUNTS_2.id AS ACCOUNTID, ACCOUNTS_2.Eponimia, ACCOUNTS_2.Eponimia as EPON, 
ACCOUNTS_2.Epagelma, ACCOUNTS_2.AddressStr, ACCOUNTS_2.AddressNo, ACCOUNTS_2.Code, 
                      ACCOUNTS_2.AddressTK, ACCOUNTS_2.Tel, ACCOUNTS_2.Tel2, ACCOUNTS_2.Fax, ACCOUNTS_2.Mobile, ACCOUNTS_2.AFM, ACCOUNTS_2.IF_PROM, 
                      ACCOUNTS_2.IF_PEL, dbo.ESODA.THETIME, dbo.ESODA.SEIRA, CAST(dbo.ESODA.NOPARAST AS NVARCHAR(20))  AS NOPARAST, NULL AS AFORA, dbo.ESODA.IDPARAST, 
                      dbo.ESODA.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, ISNULL(dbo.ESODA.SUMPOSO,0) * KINDPARASTATIKON_5.IF_XREOSI AS XREOSI, 
                      ISNULL(dbo.ESODA.SUMPOSO,0) * KINDPARASTATIKON_5.IF_PISTOSI AS PISTOSI, '' AS SKOPOSDIAKINISIS, 
                      CASE KINDPARASTATIKON_5.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.ESODA.POSO,0)*(- 1) ELSE ISNULL(dbo.ESODA.POSO,0) END AS POSO,   
                      CASE KINDPARASTATIKON_5.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.ESODA.TAXIS,0)*(- 1) ELSE ISNULL(dbo.ESODA.TAXIS,0) END AS taxis, 
                      CASE KINDPARASTATIKON_5.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.ESODA.SUMPOSO,0)*(- 1) ELSE ISNULL(dbo.ESODA.SUMPOSO,0) END AS sumposo, 
                      NULL AS MHNASPOYAFORA, NULL 
                      AS ETOSPOYAFORA, NULL AS IFEXOFLISI, NULL AS IFPROKATABOLI, dbo.ESODA.COMMENTS, NULL AS OXIMA, '' AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      dbo.ESODA.ifDelete, dbo.ESODA.IDXRHSHS, dbo.ESODA.IDCOMPANY, dbo.ESODA.IDYPOKATASTIMA, ESODA.UserCreate, ESODA.UserMod
FROM         dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) INNER JOIN
                      dbo.ESODA WITH (NOLOCK) ON ACCOUNTS_2.id = dbo.ESODA.IDPROM INNER JOIN
