                      ISNULL(dbo.EXODA.SUMPOSO,0) * KINDPARASTATIKON_7.IF_PISTOSI AS PISTOSI, '' AS SKOPOSDIAKINISIS, 
                      CASE KINDPARASTATIKON_7.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.EXODA.POSO,0)*(- 1) ELSE ISNULL(dbo.EXODA.POSO,0) END AS POSO,   
					CASE KINDPARASTATIKON_7.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.EXODA.TAXIS,0)*(- 1) ELSE ISNULL(dbo.EXODA.TAXIS,0) END AS taxis, 
