                          ISNULL(dbo.EXODA.SUMPOSO,0)*(- 1) ELSE ISNULL(dbo.EXODA.SUMPOSO,0) END AS sumposo, 
					 NULL AS MHNASPOYAFORA, NULL 
                      AS ETOSPOYAFORA, NULL AS IFEXOFLISI, NULL AS IFPROKATABOLI, dbo.EXODA.COMMENTS, NULL AS OXIMA, '' AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
