                      dbo.KINDPARASTATIKON AS KINDPARASTATIKON_6 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = KINDPARASTATIKON_6.ID LEFT OUTER JOIN
					  PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = KINDPARASTATIKON_6.ID INNER JOIN
					  CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 1
