                      0 AS IF_PEL, dbo.EXODA.THETIME, dbo.EXODA.SEIRA, CAST(dbo.EXODA.NOPARAST AS NVARCHAR(20))  AS NOPARAST, NULL AS AFORA, dbo.EXODA.IDPARAST, 
                      dbo.EXODA.PARASTATIKO, 'ΜΙΣΘΟΔΟΣΙΑ' AS EIDOSKINHSHS, ISNULL(dbo.EXODA.SUMPOSO,0) * PACV.IF_XREOSI AS XREOSI, 
                      ISNULL(dbo.EXODA.SUMPOSO,0) * PACV.IF_PISTOSI AS PISTOSI, '' AS SKOPOSDIAKINISIS, 
                      CASE PACV.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.EXODA.POSO,0)*(- 1) ELSE ISNULL(dbo.EXODA.POSO,0) END AS POSO,   
					CASE PACV.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.EXODA.TAXIS,0)*(- 1) ELSE ISNULL(dbo.EXODA.TAXIS,0) END AS taxis, 
                      CASE PACV.IF_PISTOSI WHEN 1 THEN
                          ISNULL(dbo.EXODA.SUMPOSO,0)*(- 1) ELSE ISNULL(dbo.EXODA.SUMPOSO,0) END AS sumposo, 
					 NULL AS MHNASPOYAFORA, NULL 
                      AS ETOSPOYAFORA, NULL AS IFEXOFLISI, NULL AS IFPROKATABOLI, dbo.EXODA.COMMENTS, NULL AS OXIMA, '' AS IDKINDPAYMENT, '' 
                      AS KINDPAYMENTDESCR, 
                      dbo.EXODA.ifDelete, dbo.EXODA.IDXRHSHS, dbo.EXODA.IDCOMPANY, dbo.EXODA.IDYPOKATASTIMA, EXODA.UserCreate, EXODA.UserMod
FROM         dbo.EMPLOYEE AS EMPLOYEE WITH (NOLOCK) INNER JOIN
                      dbo.EXODA WITH (NOLOCK) ON EMPLOYEE.id = dbo.EXODA.IDPROM INNER JOIN
                      dbo.PAR_ANA_CAT_VIEW AS PACV WITH (NOLOCK) ON dbo.EXODA.IDPARAST = PACV.ID_KINDPARASTATIKON AND PACV.ID_CAT_PARASTATIKON = 2
WHERE     (PACV.IF_ENIMEROSIKARTELA = 1)




GO




---END SCRIPT 1420
------------------------------------------------------------------------------------ 


