-- =============================================
-- Author:        <Author,,Name>
-- Create date: <Create Date, ,>
-- Description:    <Description, ,>
-- =============================================
/*
ΠΑΡΑΔΕΙΓΜΑΤΑ ΚΛΗΣΗΣ
-------------------

ΓΙΑ ΤΙΜΟΛΟΓΙΑ
-------------
Select VOH.*, DBO.GetVOHEAFDSS(993, 1) AS EAFDSS from VOH where VOH.ID = 993
Select dbo.GetVOHEAFDSS(993, 1)

ΓΙΑ ΦΟΡΤΩΤΙΚΕΣ
--------------
Select FORTOTIKES.*, DBO.GetVOHEAFDSS(993, 2) AS EAFDSS from FORTOTIKES where FORTOTIKES.ID = 993
Select dbo.GetVOHEAFDSS(993, 2)

*/
/*
<%SL999081650;887718888;0;162; ;373;34;0;0;0;0;7.82;0;0;0;41.82;0%SL>
*/
ALTER FUNCTION [dbo].[GetVOHEAFDSS]
(    @VOHID Numeric,
    @VOHTYPE INT   -- =  1  voh, 2  =  fortotikes
)
RETURNS VarChar(Max)
AS
BEGIN    
Declare @result varChar(Max)
IF @VOHTYPE = 1
BEGIN
    Select    @result    =(    Select
                        '<%SL ;'+                                --Συμβολοσειρά Αναγνώρισης Αρχής (8)
                        --CP.AFM + ';;'+                            --1    ΑΦΜ Εκδότη     (12)
                        IsNull(VOH.AFM,'')+';;'+                    --2    ΑΦΜ Παραλήπτη    (12)
                        ';;;;;'+                                     --3    Αριθμός Κάρτας Αποδείξεων Πελάτη     (19)
                        KP.VoucherTypeCode +';'+                --4    Είδος Παρ/κού    (4)
                        IsNull(VOH.SEIRA,'')+';'+                --5    Σειρά Θεώρησης    (10)
                        Cast(VOH.NOPARAST As VarChar(20))+';'+    --6    Αριθμός Παραστατικού    (10)
                        '0;'+                                    --8        Καθαρό Ποσό Α    (18:2)
                        '0;'+                                    --9        Καθαρό Ποσό Β    (18:2)
                        Replace(Cast(Cast(VOH.POSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --7    Καθαρό Ποσό Γ    (18:2)
                        '0;'+                                    --10    Καθαρό Ποσό Δ    (18:2)
                        '0;'+                                    --11    Καθαρό Ποσό Ε         (18:2)
                        '0;'+                                    --13    ΦΠΑ Α            (18:2)
                        '0;'+                                    --14    ΦΠΑ Β                (18:2)
                        Replace(Cast(Cast(VOH.TAXIS As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --12    ΦΠΑ Γ          (18:2)
                        '0;'+                                    --15    ΦΠΑ Δ    (18:2)
                        Replace(Cast(Cast(VOH.SUMPOSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --16    Γενικό Σύνολο Παρ/κού    (18:2)
                        '0;'+                                    --17    Κωδικός νομίσματος    (1)
                        '>'										 --Συμβολοσειρά Αναγνώρισης Τέλους (8)
						--'%SL>'                                    --Συμβολοσειρά Αναγνώρισης Τέλους (8)
    
    
    
                        --'<%SL ;'+                                --Συμβολοσειρά Αναγνώρισης Αρχής (8)
                        --CP.AFM + ';;'+                            --1    ΑΦΜ Εκδότη     (12)
                        --IsNull(VOH.AFM,'')+';;;;;'+                    --2    ΑΦΜ Παραλήπτη    (12)
                        ----'0;'+                                     --3    Αριθμός Κάρτας Αποδείξεων Πελάτη     (19)
                        --KP.VoucherTypeCode +';'+                --4    Είδος Παρ/κού    (4)
                        --IsNull(VOH.SEIRA,'')+';'+                --5    Σειρά Θεώρησης    (10)
                        --Cast(VOH.NOPARAST As VarChar(20))+';'+    --6    Αριθμός Παραστατικού    (10)
                        --'0;'+                                    --8        Καθαρό Ποσό Α    (18:2)
                        --'0;'+                                    --9        Καθαρό Ποσό Β    (18:2)
                        --Replace(Cast(Cast(VOH.POSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --7    Καθαρό Ποσό Γ    (18:2)
                        --'0;'+                                    --10    Καθαρό Ποσό Δ    (18:2)
                        --'0;'+                                    --11    Καθαρό Ποσό Ε         (18:2)
                        --'0;'+                                    --13    ΦΠΑ Α            (18:2)
                        --'0;'+                                    --14    ΦΠΑ Β                (18:2)
                        --Replace(Cast(Cast(VOH.TAXIS As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --12    ΦΠΑ Γ          (18:2)
                        --'0;'+                                    --15    ΦΠΑ Δ    (18:2)
                        --Replace(Cast(Cast(VOH.SUMPOSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --16    Γενικό Σύνολο Παρ/κού    (18:2)
                        --'0'+                                    --17    Κωδικός νομίσματος    (1)
                        --'%SL>'                                    --Συμβολοσειρά Αναγνώρισης Τέλους (8)
                    From VOH With(NoLock)
                    Left Outer Join KINDPARASTATIKON AS KP With(NoLock) On VOH.IDPARAST =KP.ID
                    AND KP.IF_ENIMEROSIKARTELA = 1
                    Left Outer Join COMPANIES AS CP With(NoLock) On VOH.IDCOMPANY =CP.ID                    
                    Where VOH.ID = @VOHID
                )
    Select @result =IsNull(@result,'')
    END
ELSE
    BEGIN
    Select    @result    =(    Select
                        '<%SL ;'+                                --Συμβολοσειρά Αναγνώρισης Αρχής (8)
                        --CP.AFM + ';;'+                            --1    ΑΦΜ Εκδότη     (12)
                        --IsNull(FR.AFMXREOUMENOU,'')+';'+        --2    ΑΦΜ Παραλήπτη    (12)                        
                        CASE
                        WHEN (FR.IFXRAPOST = 1) THEN     ISNULL(FR.AFMAPOSTOLEA, '')
                        WHEN (FR.IFXRENTOL = 1) THEN ISNULL(FR.AFMENTOLEA, '')  
                        WHEN (FR.IFXRPARAL = 1) THEN     ISNULL(FR.AFMPARALIPTI, '')
                        WHEN (FR.IFXRTRITOU = 1) THEN ISNULL(FR.AFMTRITOU, '')  
                        END +';;'+        --2    ΑΦΜ Παραλήπτη    (12)    
                        ';;;;;'+                                 --3    Αριθμός Κάρτας Αποδείξεων Πελάτη     (19)
                        KP.VoucherTypeCode +';'+                --4    Είδος Παρ/κού    (4)
                        IsNull(FR.SEIRA,'')+';'+                --5    Σειρά Θεώρησης    (10)
                        Cast(FR.NOPARAST As VarChar(20))+';'+    --6    Αριθμός Παραστατικού    (10)
                        '0;'+                                    --8        Καθαρό Ποσό Α    (18:2)
                        '0;'+                                    --9        Καθαρό Ποσό Β    (18:2)
                        Replace(Cast(Cast(FR.POSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --7    Καθαρό Ποσό Γ    (18:2)
                        '0;'+                                    --10    Καθαρό Ποσό Δ    (18:2)
                        '0;'+                                    --11    Καθαρό Ποσό Ε         (18:2)
                        '0;'+                                    --13    ΦΠΑ Α            (18:2)
                        '0;'+                                    --14    ΦΠΑ Β                (18:2)
                        Replace(Cast(Cast(FR.TAXIS As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --12    ΦΠΑ Γ          (18:2)
                        '0;'+                                    --15    ΦΠΑ Δ    (18:2)
                        Replace(Cast(Cast(FR.SUMPOSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --16    Γενικό Σύνολο Παρ/κού    (18:2)
                        '0'+                                   --17    Κωδικός νομίσματος    (1)
                        '>'                                    --Συμβολοσειρά Αναγνώρισης Τέλους (8)                                     
                        --'%SL>'                                 --Συμβολοσειρά Αναγνώρισης Τέλους (8)        
                        
                        --'0;'+                                     --3    Αριθμός Κάρτας Αποδείξεων Πελάτη     (19)
                        --KP.VoucherTypeCode +';'+                --4    Είδος Παρ/κού    (4)
                        --IsNull(FR.SEIRA,'')+';'+                --5    Σειρά Θεώρησης    (10)
                        --Cast(FR.NOPARAST As VarChar(20))+';'+    --6    Αριθμός Παραστατικού    (10)
                        --Replace(Cast(Cast(FR.POSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --7    Καθαρό Ποσό Α    (18:2)
                        --'0;'+                                    --8        Καθαρό Ποσό Β    (18:2)
                        --'0;'+                                    --9        Καθαρό Ποσό Γ    (18:2)
                        --'0;'+                                    --10    Καθαρό Ποσό Δ    (18:2)
                        --'0;'+                                    --11    Καθαρό Ποσό Ε         (18:2)
                        --Replace(Cast(Cast(FR.TAXIS As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --12    ΦΠΑ Α          (18:2)
                        --'0;'+                                    --13    ΦΠΑ Β            (18:2)
                        --'0;'+                                    --14    ΦΠΑ Γ                (18:2)
                        --'0;'+                                    --15    ΦΠΑ Δ    (18:2)
                        --Replace(Cast(Cast(FR.SUMPOSO As Decimal(10,2)) As VarChar(20)),'.',',')+';'+    --16    Γενικό Σύνολο Παρ/κού    (18:2)
                        --'0'+                                    --17    Κωδικός νομίσματος    (1)
                        --'%SL>'                                    --Συμβολοσειρά Αναγνώρισης Τέλους (8)
                    From FORTOTIKES AS FR With(NoLock)
                    Left Outer Join KINDPARASTATIKON AS KP With(NoLock) On FR.IDPARAST =KP.ID
                    AND KP.IF_ENIMEROSIKARTELA = 1
                    Left Outer Join COMPANIES AS CP With(NoLock) On FR.IDCOMPANY =CP.ID                    
                    Where FR.ID = @VOHID
                )
    Select @result =IsNull(@result,'')
    END

    RETURN @result
                        
END

GO


---END SCRIPT 1421
