ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS
SELECT     dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, 
                      CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
                       ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      FORTOTIKES.APOSTOLEASDESCR, FORTOTIKES.PARALISPTISDESCR, FORTOTIKES.ENTOLEASDESCR, 
                      dbo.FORTOTIKES.ANTAPOKRITISDESCR, dbo.FORTOTIKES.NOLISTASDIANOMIS, ACCOUNTS_3.Eponimia AS TRITOSDESCR, MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, 
                      ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS), 0) AS BAROS, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA), 0) AS KYBIKA, 
                      MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO, dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, 
                      dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUS, 
                      --CONVERT(varchar, dbo.FORTOTIKES.DATEPARAD, 102) AS 
                      DATEPARAD, dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.IDPARALIPTI, dbo.FORTOTIKES.IDENTOLEA, 
                      dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.IDPRAKTOREIO, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
                      CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, 
                      dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.COMMENTS2, MIN(dbo.HEADERFORTOTIKIS.KOMISTRA) AS KOMISTRA, 
                      dbo.FORTOTIKES.EXODATRITON AS XREOSISTRITON, MIN(dbo.HEADERFORTOTIKIS.DIKAIOMAFORTOTIKIS) 
                      AS DIKAIOMAFORTOTIKIS, MIN(dbo.HEADERFORTOTIKIS.OTHERXREOSIS) AS OTHERXREOSIS, 
                      MIN(dbo.HEADERFORTOTIKIS.OLIKOSYNOLOXREOSEONFORT) AS OLIKOSYNOLOXREOSEONFORT, 
                      MIN(dbo.HEADERFORTOTIKIS.ERGATIKA) AS ERGATIKA, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.SUMPOSO), 0) 
                      AS AXIA, CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, 
                      dbo.FORTOTIKES.IDKINDPAYMENT, CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
                      CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, 
                      dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, 
                      dbo.FORTOTIKES.ifDelete, dbo.FORTOTIKES.IFCANCEL, --CONVERT(varchar, dbo.FORTOTIKES.DATECANCEL, 102) AS 
                      DATECANCEL, FORTOTIKES.AA_ANTIK, FORTOTIKES.NOLISTASANTIK ,
                      dbo.FORTOTIKES.IFPARADOSI, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, CONVERT(varchar, dbo.FORTOTIKES.DATEFORTOSIS, 103) 
                      AS DATEFORTOSIS, dbo.FORTOTIKES.IFEPISTROFI, --CONVERT(varchar, dbo.FORTOTIKES.DATEEPISTROFIS, 102) AS 
                      DATEEPISTROFIS,  FORTOTIKES.DROMOLOGIO, FORTOTIKES.THESI,
                      dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, dbo.FORTOTIKES.IFPISTOSI, 
                      dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, dbo.FORTOTIKES.IFEPANEKDOSI, 
                      dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, 
                      dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.IFPARADOSIANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK, 
                      dbo.FORTOTIKES.COMMENTSPARADANTIK, dbo.FORTOTIKES.COMMANTSPARALANTIK, dbo.FORTOTIKES.COMMENTSEISPRANTIK, CONVERT(varchar, 
                      dbo.FORTOTIKES.DATEPARADANTIK, 102) AS DATEPARADANTIK, --CONVERT(varchar, dbo.FORTOTIKES.DATEPARALANTIK, 102) AS 
                      DATEPARALANTIK, 
                      CONVERT(varchar, dbo.FORTOTIKES.DATEEISPRANTIK, 102) AS DATEEISPRANTIK, dbo.FORTOTIKES.EISPRAXASANTIK, 
                      dbo.FORTOTIKES.NOPARPARADANTIK, dbo.FORTOTIKES.NOPARASTEISPRANTIK, dbo.FORTOTIKES.NOPARPARALANTIK, 
                      --CONVERT(varchar, dbo.FORTOTIKES.DATEPARAL, 102) AS 
                      DATEPARAL, dbo.FORTOTIKES.COMMENTSPARAD, dbo.FORTOTIKES.COMMANTSPARAL,  FORTOTIKES.IF_TRANSFTOESEX, 
                      dbo.FORTOTIKES.TIMEPARALFROM, dbo.FORTOTIKES.TIMEPARALTO, dbo.FORTOTIKES.TIMEPARADFROM, dbo.FORTOTIKES.TIMEPARADTO, 
                      CONVERT(varchar, dbo.FORTOTIKES.DATECANCELANTIK, 102) AS DATECANCELANTIK, dbo.FORTOTIKES.IDPARAST, dbo.FORTOTIKES.TAXISPERCENT, 
                      dbo.FORTOTIKES.ANAMEXODO, dbo.FORTOTIKES.ID AS IDFORTOTIKIS, dbo.FORTOTIKES.AFMXREOUMENOU, 
                      dbo.HEADERFORTOTIKIS.ASFALISTRA, ROUND(dbo.HEADERFORTOTIKIS.TAXIS, 2) AS TAXISXREOSEON, 
                      dbo.HEADERFORTOTIKIS.SUMPOSOXRFORT, dbo.HEADERFORTOTIKIS.KATHARO, FORTOTIKES.OROFOS, FORTOTIKES.OROFOSDESCR, FORTOTIKES.KOUDOUNI, 
                      dbo.ACCOUNTS.Epagelma AS EPAGAPOST, dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, 
                      dbo.ACCOUNTS.AddressTK AS TKAPOST, dbo.ACCOUNTS.AddressCity AS CITYAPOST, dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, 
                      dbo.ACCOUNTS.Tel AS TELAPOST, dbo.ACCOUNTS.Tel2 AS TEL2APOST, dbo.ACCOUNTS.Fax AS FAXAPOST, dbo.ACCOUNTS.DOY AS DOYAPOST, ACCOUNTS_1.Epagelma AS EPAGPARAL, 
                      ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, ACCOUNTS_1.AddressNo AS ADDRNOPARAL, ACCOUNTS_1.AddressTK AS ADDRTKPARAL, 
                      ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, ACCOUNTS_1.Tel AS TELPARAL, 
                      ACCOUNTS_1.Tel2 AS TEL2PARAL, ACCOUNTS_1.Fax AS FAXPARAL, ACCOUNTS_1.DOY AS DOYPARAL, ACCOUNTS_2.Epagelma AS EPAGENTOL, ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, 
                      ACCOUNTS_2.AddressNo AS ADDRNOENTOL, ACCOUNTS_2.AddressTK AS ADDRTKENTOL, ACCOUNTS_2.AddressCity AS ADDRCITYENTOL, 
                      ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL, ACCOUNTS_2.Tel AS TELENTOL, ACCOUNTS_2.Tel2 AS TEL2ENTOL, ACCOUNTS_2.Fax AS FAXENTOL, 
                      ACCOUNTS_2.DOY AS DOYENTOL, 
                      ACCOUNTS_3.Epagelma AS EPAGTR, ACCOUNTS_3.AddressStr AS ADDRSTTR, ACCOUNTS_3.AddressNo AS ADDRNOTR, 
                      ACCOUNTS_3.AddressTK AS ADDRTKTR, ACCOUNTS_3.AddressCity AS ADDRCITYTR, ACCOUNTS_3.AddressPref AS ADSTRDRNOMO, 
                      ACCOUNTS_3.Tel AS TELTR, ACCOUNTS_3.Tel2 AS TEL2TR, ACCOUNTS_3.Fax AS FAXTR, ACCOUNTS_3.DOY AS DOYTR, dbo.FORTOTIKES.AFMAPOSTOLEA, dbo.FORTOTIKES.AFMENTOLEA, 
                      dbo.FORTOTIKES.AFMPARALIPTI, dbo.FORTOTIKES.AFMTRITOU, dbo.FORTOTIKES.AFMANTAPOKRITI, dbo.FORTOTIKES.IFPARADOSITOPEL, 
                      dbo.FORTOTIKES.IFPARALABIFROMPEL, ACCOUNTS_1.Mobile AS MOBILEPARALIPTI, dbo.FORTOTIKES.IFEXOFLISI,
                      ACCOUNTS_2.Mobile AS MOBILEENTOLTEA, ACCOUNTS.Mobile AS MOBILEAPOSTOLEA, ACCOUNTS_3.Mobile AS MOBILETRITOU, FORTOTIKES.IDDRIVER, FORTOTIKES.DRIVERDESCR, 
                      dbo.FORTOTIKES.IDXRHSHS, dbo.FORTOTIKES.IDCOMPANY, dbo.FORTOTIKES.IDYPOKATASTIMA, dbo.FORTOTIKES.CONTAINER, dbo.FORTOTIKES.BOAT, 
                      CASE WHEN IFXRENTOL = 1 THEN ACCOUNTS_2.PrintableComment ELSE CASE WHEN IFXRAPOST = 1 THEN ACCOUNTS.PrintableComment 
                      ELSE CASE WHEN IFXRTRITOU = 1 THEN ACCOUNTS_3.PrintableComment
                       ELSE CASE WHEN IFXRPARAL = 1 THEN ACCOUNTS_1.PrintableComment ELSE ' ' END END END END AS PROEP_SXOLIO, 
                      FORTOTIKES.POD_ADDED, FORTOTIKES.POD_PATH, FORTOTIKES.POD_USER, FORTOTIKES.POD_PATH_2, FORTOTIKES.EXT_ID, FORTOTIKES.NO_EXT_ORDER, 
					  FORTOTIKES.UserCreate, FORTOTIKES.DateCreate, FORTOTIKES.EXT_BARCODE, 
					  FORTOTIKES.IDKENTROUKOSTOUS, FORTOTIKES.NO_EXT_ORDER_IK, FORTOTIKES.IDENTOLIS, FORTOTIKES.IF_CANCEL, FORTOTIKES.ID_CANCELLATION, 
					  FORTOTIKES.SEIRA_CANCELLATION, FORTOTIKES.NOPARAST_CANCELLATION, FORTOTIKES.DETAILS_CANCELLATION,FORTOTIKES.CANCELDATE, 
                      FORTOTIKES.UserMod, FORTOTIKES.DateMod, FORTOTIKES.IF_FROM_ANTAP, FORTOTIKES.IF_TO_ANTAP,
                      dbo.FORTOTIKES.ARANAFORAS,
					  DBO.COMPANIES.Eponimia AS YPOKATASTHMA,
					  DBO.COMPANIES.AddressStr AS ADDRESS_YPOKATASTHMA,
					  dbo.COMPANIES.AddressTK AS TK_YPOKATASTHMA,
					  dbo.COMPANIES.AddressCity as CITY_YPOKATASTHMA,
					  dbo.COMPANIES.BARCODE_Prefix AS BARCODEPREFIX_YPOKAT,
					  DBO.COMPANIES.EMAIL AS EMAIL_YPOKATASTHMA, DBO.GetVOHEAFDSS(FORTOTIKES.ID, 2) AS EAFDSS 
FROM         dbo.FORTOTIKES WITH (NOLOCK) 
					  LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) ON dbo.FORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON dbo.FORTOTIKES.IDENTOLEA = ACCOUNTS_2.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON dbo.FORTOTIKES.IDTRITOU = ACCOUNTS_3.id 
					  LEFT OUTER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID 
					  LEFT OUTER JOIN PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID 
					  INNER JOIN CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0 
					  LEFT OUTER JOIN dbo.GRAMMESFORTTIKIS WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.IDVOH = dbo.FORTOTIKES.ID 
					  LEFT OUTER JOIN dbo.HEADERFORTOTIKIS WITH (NOLOCK) ON dbo.HEADERFORTOTIKIS.IDFORT = dbo.FORTOTIKES.ID 
                      LEFT OUTER JOIN dbo.Units WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.SYSKEVASIA = dbo.Units.UntID
                      LEFT OUTER JOIN dbo.COMPANIES on dbo.COMPANIES.id=dbo.FORTOTIKES.IDYPOKATASTIMA
GROUP BY dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, dbo.FORTOTIKES.NOPARAST, 
                      dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.IFPREPAY, dbo.FORTOTIKES.IFOFEILOMENI, dbo.FORTOTIKES.SUMPOSO, 
                      dbo.FORTOTIKES.IDAPOSTOLEA, ACCOUNTS_3.Eponimia, dbo.FORTOTIKES.IDPARALIPTI, FORTOTIKES.ENTOLEASDESCR, 
                      dbo.FORTOTIKES.IDENTOLEA, FORTOTIKES.APOSTOLEASDESCR, dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.ANTAPOKRITISDESCR, 
                      dbo.FORTOTIKES.IDTRITOU, FORTOTIKES.PARALISPTISDESCR, dbo.FORTOTIKES.IDPRAKTOREIO, dbo.FORTOTIKES.PRAKTOREIODESCR, 
                      dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.ANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, 
                      dbo.FORTOTIKES.ANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.ANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, 
                      dbo.FORTOTIKES.ANTIKOTHER, dbo.FORTOTIKES.IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.STATUS, dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.PERIOXIFORTOSIS, 
                      dbo.FORTOTIKES.PERIOXIPARADOSIS, dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.COMMENTS2, dbo.FORTOTIKES.OMADPROORISMOS, 
                      dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, dbo.FORTOTIKES.IFXRAPOST, 
