                  dbo.voh.if_close,
                  dbo.voh.noorder,
				  dbo.voh.EXT_BARCODE,
				  dbo.voh.NO_EXT_ORDER,
				  dbo.voh.NO_EXT_ORDER_IK,
				  DBO.COMPANIES.Eponimia AS YPOKATASTHMA,
				  DBO.COMPANIES.AddressStr AS ADDRESS_YPOKATASTHMA,
				  dbo.COMPANIES.AddressTK AS TK_YPOKATASTHMA,
				  dbo.COMPANIES.AddressCity as CITY_YPOKATASTHMA,
				  dbo.COMPANIES.BARCODE_Prefix AS BARCODEPREFIX_YPOKAT,
