	SET NOCOUNT ON
	SET @ErrorNumber = 0

	SET @TRACOUNT = @@TRANCOUNT
	IF @TRACOUNT = 0 

	--EISAGOGI TOY PARALIPTI EAN DEN YPARXEI STO PINAKA MAS
	--***************************************************************************
	DECLARE @RowCountPelati INT
	DECLARE @IDPARAST INT
	DECLARE @ClientCode INT
	DECLARE @ClientTownCode NVARCHAR(10)
	DECLARE @ClientRegionCode NVARCHAR(10) --TASK 12899
	DECLARE @PelatesAddr	NVARCHAR(60) --TASK 11593
	DECLARE @PelatesProfID	NVARCHAR(30) --TASK 11623
	SET @RowCountPelati=0

	IF @IDAFORA = 0
		BEGIN 	
			SET @KINDKINISIS = 1 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 1
		BEGIN 	
			SET @KINDKINISIS = 0 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 4
		BEGIN 	
			SET @KINDKINISIS = 99 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 5
		BEGIN 	
			SET @KINDKINISIS = 5 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 6
		BEGIN 	
			SET @KINDKINISIS = 6 --@KINDKINISIS = 1
		END 



		BEGIN
			INSERT INTO KINDPARASTATIKON
				(
				Code,
				Descr,
				KindKINISIS,
				KindYpologismou,
				IFENIMEROSITAMEIO,
