				IF_XREOSIKARTELA,
				IF_PISTOSIKARTELA,
				IFKEPXREOSI,
				IFKEPPISTOSI,
				IFPROFORTOTIKI,
				IFKEPYO,
				SEIRA,
				PRINTLABEL,
				PROEPSXOLIO,
				IfPreviewFirst,
				PrinterName,
				IDPARASTEXOFLISI,
