CREATE VIEW [dbo].[LISTESSYNARMOLOGISIS_VOH_VIEW]
AS
SELECT     dbo.VOH.ID, dbo.VOH.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.VOH.PARASTATIKO, dbo.VOH.SEIRA, 
                      dbo.VOH.NOPARAST, dbo.VOH.NOPARASTDELTIOUDIANOMIS, dbo.VOH.NOPARASTDELTIOUAPOSTOLIS, dbo.VOH.OXIMA, 
                      dbo.VOH.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE
                       WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, dbo.VOH.APOSTOLEASDESCR, 
                      dbo.VOH.PARALISPTISDESCR, dbo.VOH.ENTOLEASDESCR, dbo.VOH.ANTAPOKRITISDESCR, dbo.VOH.TRITOSDESCR, 
                      MIN(dbo.GRAMMESVOH.TIMDA) AS TIMDA, dbo.VOH.POSO, dbo.VOH.TAXIS, dbo.VOH.SUMPOSO, 
                      ISNULL(SUM(dbo.GRAMMESVOH.TEMAXIA), 0) AS TEMAXIA, ISNULL(SUM(dbo.GRAMMESVOH.BAROS), 0) AS BAROS, 
                      ISNULL(SUM(dbo.GRAMMESVOH.KYBIKA), 0) AS KYBIKA, MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.VOH.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.VOH.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.VOH.IFPREPAY WHEN 1 THEN CASE dbo.VOH.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.VOH.IFPREPAY WHEN 1 THEN CASE dbo.VOH.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESVOH.PERIEXOMENO) AS PERIEXOMENO, dbo.VOH.PERIOXIFORTOSIS, dbo.VOH.PERIOXIPARADOSIS, 
                      dbo.VOH.COMMENTS, dbo.VOH.SUMANTIK, dbo.VOH.PRAKTOREIODESCR, dbo.VOH.STATUS, dbo.VOH.DATEPARAD, 
                      dbo.VOH.IDAPOSTOLEA, dbo.VOH.IDPARALIPTI, dbo.VOH.IDENTOLEA, dbo.VOH.IDANTAPOKRITI, dbo.VOH.IDTRITOU, 
                      dbo.VOH.IDPRAKTOREIO, CASE IFANTIKCASH WHEN 0 THEN 0 ELSE dbo.VOH.ANTIKCASH END AS ANTIKCASH, 
                      CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE dbo.VOH.ANTIKEPIT END AS ANTIKEPIT, CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE dbo.VOH.ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE dbo.VOH.ANTIKOTHER END AS ANTIKOTHER, CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, 
                      dbo.VOH.COMMENTSANTIK, dbo.VOH.DATEPARADOSI, dbo.VOH.COMMENTS2, 
                      MIN(dbo.HEADERVOH.KOMISTRA) AS KOMISTRA, MIN(dbo.VOH.EXODATRITON)
                      AS XREOSISTRITON, MIN(dbo.HEADERVOH.DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORTOTIKIS, 
                      MIN(dbo.HEADERVOH.OTHERXREOSIS) AS OTHERXREOSIS,
                      MIN(dbo.HEADERVOH.ERGATIKA) AS ERGATIKA, CASE dbo.VOH.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
                      CASE dbo.VOH.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, ISNULL(SUM(dbo.GRAMMESVOH.SUMPOSO), 0) AS AXIA, 
                      CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.VOH.KINDPAYMENTDESCR, dbo.VOH.IDKINDPAYMENT, 
                      CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, 
                      CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, dbo.VOH.IFANTIKCASH, dbo.VOH.IFANTIKEPIT, 
                      dbo.VOH.IFANTIKSYNAL, dbo.VOH.IFANTIKOTHER, dbo.VOH.ifDelete, dbo.VOH.IFCANCEL, dbo.VOH.DATECANCEL, 
                      dbo.VOH.IFPARADOSI, dbo.VOH.AITIOLOGIAPARASTATIKOU, dbo.VOH.DATEFORTOSIS, dbo.VOH.IFEPISTROFI, 
                      dbo.VOH.DATEEPISTROFIS, dbo.VOH.AITIOLOGIAEPISTROFIS, dbo.VOH.COMMENTSEPISTROFIS, dbo.VOH.IFCASH, 
                      dbo.VOH.IFPISTOSI, dbo.VOH.STATUSDESCR, dbo.VOH.YPAITIOS, dbo.VOH.IFEPANADROMOLOGISI, 
                      dbo.VOH.IFEPANEKDOSI, dbo.VOH.IFOKEPANADROMOLOGISI, dbo.VOH.NOPARASTANTIK, dbo.VOH.COMMENTSAKIROSIS, 
                      dbo.VOH.IFEISPRANTIK, dbo.VOH.IFPARADOSIANTIK, dbo.VOH.IFPARALAVIANTIK, dbo.VOH.COMMENTSPARADANTIK, 
                      dbo.VOH.COMMANTSPARALANTIK, dbo.VOH.COMMENTSEISPRANTIK, dbo.VOH.DATEPARADANTIK, dbo.VOH.DATEPARALANTIK, 
                      dbo.VOH.DATEEISPRANTIK, dbo.VOH.EISPRAXASANTIK, dbo.VOH.NOPARPARADANTIK, dbo.VOH.NOPARASTEISPRANTIK, 
                      dbo.VOH.NOPARPARALANTIK, dbo.VOH.DATEPARAL, dbo.VOH.COMMENTSPARAD, dbo.VOH.COMMANTSPARAL, 
                      dbo.VOH.TIMEPARALFROM, dbo.VOH.TIMEPARALTO, dbo.VOH.TIMEPARADFROM, dbo.VOH.TIMEPARADTO, 
                      dbo.VOH.DATECANCELANTIK, dbo.VOH.IDPARAST, dbo.VOH.TAXISPERCENT, dbo.VOH.ANAMEXODO, 
                      dbo.VOH.ID AS IDFORTOTIKIS, dbo.VOH.AFMXREOUMENOU, dbo.HEADERVOH.ASFALISTRA, 
                      dbo.HEADERVOH.TAXIS AS TAXISXREOSEON, 
                      dbo.HEADERVOH.KATHARO, dbo.ACCOUNTS.Epagelma AS EPAGAPOST, dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, 
                      dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, dbo.ACCOUNTS.AddressTK AS TKAPOST, dbo.ACCOUNTS.AddressCity AS CITYAPOST, 
                      dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, dbo.ACCOUNTS.Tel AS TELAPOST, dbo.ACCOUNTS.DOY AS DOYAPOST, ACCOUNTS_1.Epagelma AS EPAGPARAL, 
                      ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, ACCOUNTS_1.AddressNo AS ADDRNOPARAL, ACCOUNTS_1.AddressTK AS ADDRTKPARAL, 
                      ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, ACCOUNTS_1.Tel AS TELPARAL, 
                      ACCOUNTS_1.DOY AS DOYPARAL, ACCOUNTS_2.Epagelma AS EPAGENTOL, ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, 
                      ACCOUNTS_2.AddressNo AS ADDRNOENTOL, ACCOUNTS_2.AddressTK AS ADDRTKENTOL, ACCOUNTS_2.AddressCity AS ADDRCITYENTOL, 
                      ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL, ACCOUNTS_2.Tel AS TELENTOL, ACCOUNTS_2.DOY AS DOYENTOL, ACCOUNTS_3.Epagelma AS EPAGTR, 
                      ACCOUNTS_3.AddressStr AS ADDRSTTR, ACCOUNTS_3.AddressNo AS ADDRNOTR, ACCOUNTS_3.AddressTK AS ADDRTKTR, 
                      ACCOUNTS_3.AddressCity AS ADDRCITYTR, ACCOUNTS_3.AddressPref AS ADSTRDRNOMO, ACCOUNTS_3.Tel AS TELTR, ACCOUNTS_3.DOY AS DOYTR, 
                      dbo.VOH_ANA_LISTAASS.IDLISTAS, dbo.VOH_ANA_LISTAASS.IDVOH AS IDVOH,
                      dbo.VOH.NO_EXT_ORDER, dbo.VOH.IDXRHSHS, dbo.VOH.IDCOMPANY, dbo.VOH.IDYPOKATASTIMA

FROM         dbo.VOH WITH (NOLOCK) LEFT OUTER JOIN
                      dbo.VOH_ANA_LISTAASS WITH (NOLOCK) ON dbo.VOH.ID = dbo.VOH_ANA_LISTAASS.IDVOH LEFT OUTER JOIN
                      dbo.ACCOUNTS WITH (NOLOCK) ON dbo.VOH.IDAPOSTOLEA = dbo.ACCOUNTS.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.VOH.IDPARALIPTI = ACCOUNTS_1.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON dbo.VOH.IDENTOLEA = ACCOUNTS_2.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON dbo.VOH.IDTRITOU = ACCOUNTS_3.id LEFT OUTER JOIN
                      dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.VOH.IDPARAST = dbo.KINDPARASTATIKON.ID LEFT OUTER JOIN
                      dbo.GRAMMESVOH WITH (NOLOCK) ON dbo.GRAMMESVOH.IDVOH = dbo.VOH.ID LEFT OUTER JOIN
                      dbo.HEADERVOH WITH (NOLOCK) ON dbo.HEADERVOH.IDVOH = dbo.VOH.ID LEFT OUTER JOIN
                      dbo.Units WITH (NOLOCK) ON dbo.GRAMMESVOH.SYSKEVASIA = dbo.Units.UntID 
GROUP BY dbo.VOH.ID, dbo.VOH.DATEPRINT, dbo.VOH.PARASTATIKO, dbo.VOH.SEIRA, dbo.VOH.NOPARAST, 
                      dbo.VOH.OXIMA, dbo.VOH.IFPREPAY, dbo.VOH.IFOFEILOMENI, dbo.VOH.SUMPOSO, dbo.VOH.IDAPOSTOLEA, 
                      dbo.VOH.APOSTOLEASDESCR, dbo.VOH.IDPARALIPTI, dbo.VOH.PARALISPTISDESCR, dbo.VOH.IDENTOLEA, 
                      dbo.VOH.ENTOLEASDESCR, dbo.VOH.IDANTAPOKRITI, dbo.VOH.ANTAPOKRITISDESCR, dbo.VOH.IDTRITOU, 
                      dbo.VOH.TRITOSDESCR, dbo.VOH.IDPRAKTOREIO, dbo.VOH.PRAKTOREIODESCR, dbo.VOH.SUMANTIK, 
                      dbo.VOH.IFANTIKCASH, dbo.VOH.ANTIKCASH, dbo.VOH.IFANTIKEPIT, dbo.VOH.ANTIKEPIT, dbo.VOH.IFANTIKSYNAL, 
