                      dbo.VOH.STATUSDESCR, dbo.VOH.YPAITIOS, dbo.VOH.IFEPANADROMOLOGISI, dbo.VOH.IFEPANEKDOSI, 
                      dbo.VOH.IFOKEPANADROMOLOGISI, dbo.VOH.NOPARASTANTIK, dbo.VOH.COMMENTSAKIROSIS, dbo.VOH.IFEISPRANTIK, 
                      dbo.VOH.IFPARADOSIANTIK, dbo.VOH.IFPARALAVIANTIK, dbo.VOH.COMMENTSPARADANTIK, dbo.VOH.COMMANTSPARALANTIK, 
                      dbo.VOH.COMMENTSEISPRANTIK, dbo.VOH.DATEPARADANTIK, dbo.VOH.DATEPARALANTIK, dbo.VOH.DATEEISPRANTIK, 
                      dbo.VOH.EISPRAXASANTIK, dbo.VOH.NOPARPARADANTIK, dbo.VOH.NOPARASTEISPRANTIK, dbo.VOH.NOPARPARALANTIK, 
                      dbo.VOH.DATEPARAL, dbo.VOH.DATEPARAD, dbo.VOH.COMMENTSPARAD, dbo.VOH.COMMANTSPARAL, 
