				TAXISPERCENTEXODA,
				TAXISEXODA,
				SUMPOSOEXODA,
				STATUS,
				COMMENTS,
				SUMBAROS,
				IDSTATUS,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IDCUSTOMER,
				AFMCUSTOMER,
				CUSTOMER,
				IDEMPLOYEE,
				EMPLOYEE,
				UserCreate,
				DateCreate,
				ifDelete
				)
			VALUES
				(
				@IDPARAST,
				@PARASTATIKO,
				@SEIRA,
				@NOPARAST,
				@DATEPRINT,
				@DATEPARADOSI,
				@IFCANCEL,
				@DATECANCEL,
				@POSO,
				@TAXISPERCENT,
				@TAXIS,
				@SUMPOSO,
				@POSOEXODA,
				@TAXISPERCENTEXODA,
				@TAXISEXODA,
				@SUMPOSOEXODA,
				@STATUS,
				@COMMENTS,
				@SUMBAROS,
				@IDSTATUS,
				@IDXRHSHS,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IDCUSTOMER,
				@AFMCUSTOMER,
				@CUSTOMER,
				@IDEMPLOYEE,
				@EMPLOYEE,
				@UserCreate,
				@DateCreate,
				@ifDelete
				)
			SELECT  @TheID = MAX(ID) FROM dbo.LISTESSYNARMOLOGISIS WITH (NOLOCK)

		END


