ALTER VIEW [dbo].[LISTESSYNARMOLOGISIS_VOH_VIEW]
AS
SELECT     dbo.VOH.ID, dbo.VOH.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.VOH.PARASTATIKO, dbo.VOH.SEIRA, 
                      dbo.VOH.NOPARAST, dbo.VOH.NOPARASTDELTIOUDIANOMIS, dbo.VOH.NOPARASTDELTIOUAPOSTOLIS, dbo.VOH.OXIMA, 
                      dbo.VOH.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE
                       WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, dbo.VOH.APOSTOLEASDESCR, 
                      dbo.VOH.PARALISPTISDESCR, dbo.VOH.ENTOLEASDESCR, dbo.VOH.ANTAPOKRITISDESCR, dbo.VOH.TRITOSDESCR, 
                      MIN(dbo.GRAMMESVOH.TIMDA) AS TIMDA, dbo.VOH.POSO, dbo.VOH.TAXIS, dbo.VOH.SUMPOSO, 
                      ISNULL(SUM(dbo.GRAMMESVOH.TEMAXIA), 0) AS TEMAXIA, ISNULL(SUM(dbo.GRAMMESVOH.BAROS), 0) AS BAROS, 
                      ISNULL(SUM(dbo.GRAMMESVOH.KYBIKA), 0) AS KYBIKA, MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.VOH.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.VOH.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.VOH.IFPREPAY WHEN 1 THEN CASE dbo.VOH.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.VOH.IFPREPAY WHEN 1 THEN CASE dbo.VOH.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
                            WHERE      IDVOH = dbo.VOH.ID AND ifXreosiTriton <> 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESVOH.PERIEXOMENO) AS PERIEXOMENO, dbo.VOH.PERIOXIFORTOSIS, dbo.VOH.PERIOXIPARADOSIS, 
                      dbo.VOH.COMMENTS, dbo.VOH.SUMANTIK, dbo.VOH.PRAKTOREIODESCR, dbo.VOH.STATUS, dbo.VOH.DATEPARAD, 
                      dbo.VOH.IDAPOSTOLEA, dbo.VOH.IDPARALIPTI, dbo.VOH.IDENTOLEA, dbo.VOH.IDANTAPOKRITI, dbo.VOH.IDTRITOU, 
