ALTER PROCEDURE [dbo].[inserttoVOH_ANA_LISTAASS]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDLISTAS				NUMERIC(18, 0)= NULL,
	@NoPARASTLISTAS			NVARCHAR(10)= NULL,
	@IDEMPLOYEE				NUMERIC(18, 0)= NULL, 
	@EMPLOYEE				NVARCHAR(60)= NULL,
	@INSERTVOH				NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='inserttoVOH_ANA_LISTAASS', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000


DECLARE @_STATUS varchar(75)
SET @_STATUS = 'ΣΕ ΚΑΤΑΣΤΑΣΗ ΑΝΑΘΕΣΗΣ'
DECLARE @_NULL varchar(75)
SET @_NULL = ''
--------------------------------------------------

---- START FIX
---- TRY TO FIX EMPTY IDs IN A ROW ie ,,2,3,4 or 1,2,,4 or 1,2,3,, or even ,,2,,
---- BUT KEEP A LOG BEFORE CHANGING THE PARAMETER FOR FUTURE REFERENCE
--DECLARE @BXSTRING NVARCHAR(MAX)
--SET @BXSTRING = @NoPARASTLISTAS + '/' + @IDEMPLOYEE + '/' + @EMPLOYEE + '/' + @INSERTVOH
--INSERT INTO BLACKBOX (REFID, [DATA]) VALUES (ISNULL(@IDLISTAS, 0), @BXSTRING)

--WHILE CHARINDEX(',', @INSERTVOH)=1
--	SET @INSERTVOH = SUBSTRING(@INSERTVOH, 2, LEN(@INSERTVOH)-1)

--WHILE CHARINDEX(',', REVERSE(@INSERTVOH))=1
--	SET @INSERTVOH = SUBSTRING(@INSERTVOH, 0, LEN(@INSERTVOH))

--WHILE PATINDEX('%,,%', @INSERTVOH) > 0
--	SET @INSERTVOH = REPLACE(@INSERTVOH, ',,', ',')

--END FIX

--------------------------------------------------
EXEC('UPDATE VOH SET NOPARASTLISTASSYNARMOLOGISIS ='''+@NoPARASTLISTAS +''',  EMPLOYEE ='''+	@EMPLOYEE +
	''', IDEMPLOYEE ='''+@IDEMPLOYEE +''', STATUS =	11, STATUSDESCR = '''+@_STATUS+''' WHERE ID IN(' + @INSERTVOH + ')')
declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @INSERTVOH) 
    WHILE @start < LEN(@INSERTVOH) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@INSERTVOH) + 1
       INSERT INTO VOH_ANA_LISTAASS (IDLISTAS, IDVOH, OTHERPOSO, POSO, TAXIS, SUMPOSO, ANTIKCASH, 
       ANTIKEPIT, ANTIKSYNAL, ANTIKOTHER, SUMANTIK, IDPARALIPTI, PARALISPTISDESCR, IDAPOSTOLEA, APOSTOLEASDESCR, 
       IDENTOLEA, ENTOLEASDESCR, IDEMPLOYEE, EMPLOYEE, XREOYMENOS, BAROS, KYBIKA, TEMAXIA) 
       SELECT @IDLISTAS AS IDLISTAS, A.ID, 0 AS OTHERPOSO, A.POSO, A.TAXIS, A.SUMPOSO, A.ANTIKCASH, 
       A.ANTIKEPIT, A.ANTIKSYNAL, A.ANTIKOTHER, A.SUMANTIK, A.IDPARALIPTI, A.PARALISPTISDESCR, A.IDAPOSTOLEA, A.APOSTOLEASDESCR, 
       A.IDENTOLEA, A.ENTOLEASDESCR, @IDEMPLOYEE, @EMPLOYEE,NULL AS  XREOYMENOS, G.BAROS, G.KYBIKA, G.TEMAXIA FROM
       VOH AS A LEFT JOIN (SELECT  IDVOH, ISNULL(SUM(BAROS), 0) AS BAROS, ISNULL(SUM(KYBIKA), 0) AS KYBIKA, 
       ISNULL(SUM(PCS), 0) AS TEMAXIA FROM GRAMMESVOH GROUP BY IDVOH)
       AS G ON A.ID = G.IDVOH WHERE  
       
       --SELECT @IDLISTAS AS IDLISTAS, A.ID, 0 AS OTHERPOSO, A.POSO, A.TAXIS, A.SUMPOSO, A.ANTIKCASH, 
       --A.ANTIKEPIT, A.ANTIKSYNAL, A.ANTIKOTHER, A.SUMANTIK, A.IDPARALIPTI, A.PARALISPTISDESCR, A.IDAPOSTOLEA, A.APOSTOLEASDESCR, 
       --A.IDENTOLEA, A.ENTOLEASDESCR, @IDEMPLOYEE, @EMPLOYEE, NULL AS XREOYMENOS, G.BAROS, G.KYBIKA, G.TEMAXIA FROM
       --VOH AS A LEFT JOIN (SELECT  IDVOH, ISNULL(SUM(BAROS), 0) AS BAROS, ISNULL(SUM(KYBIKA), 0) AS KYBIKA, 
       --ISNULL(SUM(PCS), 0) AS TEMAXIA FROM GRAMMESVOH GROUP BY IDVOH)
       --AS G ON A.ID = G.IDVOH WHERE  
       A.ID  = CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC)
       
        --VALUES(@IDKAA, CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC)) 
        
        SET @start = @end + 1 
        SET @end = CHARINDEX(@coma, @INSERTVOH, @start)      
    END 
END

waitfor delay '00:00:00:40'            
commit;

GO

---END SCRIPT 1445
------------------------------------------------------------------------------------ 

