create VIEW [dbo].[LISTAASS_VOH_REPORT]
AS
 SELECT
        distinct  TOP (100) PERCENT VOH_EDOLES_VIEW.IDVOH,
        LISTESSYNARMOLOGISIS.ID,
        VOH_EDOLES_VIEW.XREOYMENOS,
        VOH_EDOLES_VIEW.AFMAPOSTOLEA,
        VOH_EDOLES_VIEW.APOSTOLEASDESCR,
        VOH_EDOLES_VIEW.ENTOLEASDESCR,
        VOH_EDOLES_VIEW.PARALISPTISDESCR,
        VOH_EDOLES_VIEW.TEMAXIA,
        VOH_EDOLES_VIEW.NOPARAST,
        VOH_EDOLES_VIEW.Code,
        ACCOUNTS.AddressCity,
        VOH_EDOLES_VIEW.KOMISTRA,
        VOH_EDOLES_VIEW.OTHERXREOSIS,
        VOH_EDOLES_VIEW.TIMDA,
        ISNULL(VOH_EDOLES_VIEW.AXIA,0) AS AXIA,
        ISNULL(VOH_EDOLES_VIEW.BAROS,0) AS BAROS,
        ISNULL(VOH_EDOLES_VIEW.KYBIKA,0) AS KYBIKA,
        VOH_EDOLES_VIEW.PERIEXOMENO ,
        VOH_EDOLES_VIEW.XREOSIPROPLIROMENES,
        VOH_EDOLES_VIEW.XREOSIOFEILOMENES,
        VOH_EDOLES_VIEW.SUMANTIK,
        LISTESSYNARMOLOGISIS.IDPARAST,
        LISTESSYNARMOLOGISIS.PARASTATIKO,
        LISTESSYNARMOLOGISIS.SEIRA AS SEIRALUISTA,
        LISTESSYNARMOLOGISIS.NOPARAST  AS NOPARASTLISTAS,
        LISTESSYNARMOLOGISIS.DATEPRINT,
        LISTESSYNARMOLOGISIS.OXIMA,
        LISTESSYNARMOLOGISIS.DRIVER,
        VOH_EDOLES_VIEW.XREOSISTRITON,
        VOH_EDOLES_VIEW.OMADPROORISMOS,
        VOH_EDOLES_VIEW.ASFALISTRA,
        VOH_EDOLES_VIEW.TAXISXREOSEON,
        VOH_EDOLES_VIEW.KATHARO,
        VOH_EDOLES_VIEW.IDEMPLOYEE,
        VOH_EDOLES_VIEW.EMPLOYEE,
        VOH_EDOLES_VIEW.IF_ANTIKCASHSYNAR,
        CASE IF_ANTIKCASHSYNAR
			WHEN 1 THEN VOH_EDOLES_VIEW.ANTIKCASHSYNAR
		ELSE 0
		END AS ANTIKCASHSYNAR,
        --VOH_EDOLES_VIEW.ANTIKCASHSYNAR,
        VOH_EDOLES_VIEW.ANAMEXODO,
        VOH_EDOLES_VIEW.POSO,
        VOH_EDOLES_VIEW.SUMPOSO,
        LISTESSYNARMOLOGISIS.IDCOMPANY,
        LISTESSYNARMOLOGISIS.IDYPOKATASTIMA,
        LISTESSYNARMOLOGISIS.IDXRHSHS,
        VOH_EDOLES_VIEW.IDPRAKTOREIO,
        VOH_EDOLES_VIEW.PRAKTOREIODESCR,
        LISTESSYNARMOLOGISIS.AFMCUSTOMER,
        LISTESSYNARMOLOGISIS.CUSTOMER,
        VOH_EDOLES_VIEW.EXT_BARCODE,
        VOH_EDOLES_VIEW.PARALAFM,
        VOH_EDOLES_VIEW.PARALEPAGELMA,
        VOH_EDOLES_VIEW.PARALADDRSTR,
        VOH_EDOLES_VIEW.PARALADDRNO,
        VOH_EDOLES_VIEW.PARALADDRTK,
        VOH_EDOLES_VIEW.PARALCITY,
        VOH_EDOLES_VIEW.EMPLAFM,
        VOH_EDOLES_VIEW.EMPLDOY,
        VOH_EDOLES_VIEW.Epagelma AS EMPLLEPAGELMA,
        VOH_EDOLES_VIEW.EMPLADDRSTR,
        VOH_EDOLES_VIEW.EMPLADDRNO,
        VOH_EDOLES_VIEW.EMPLADDRTK,
        VOH_EDOLES_VIEW.EMPLLCITY,
        VOH_EDOLES_VIEW.IDKINDPAYMENT,
        VOH_EDOLES_VIEW.KINDPAYMENTDESCR   
    FROM dbo.VOH_EDOLES_VIEW AS VOH_EDOLES_VIEW 
    INNER JOIN dbo.VOH_ANA_LISTAASS AS VOH_ANA_LISTAASS ON VOH_EDOLES_VIEW.IDVOH = VOH_ANA_LISTAASS.IDVOH 
    INNER JOIN dbo.ACCOUNTS AS ACCOUNTS WITH (NOLOCK) ON VOH_EDOLES_VIEW.IDPARALIPTI = ACCOUNTS.id 
    INNER JOIN dbo.LISTESSYNARMOLOGISIS WITH (NOLOCK) ON VOH_ANA_LISTAASS.IDLISTAS = LISTESSYNARMOLOGISIS.ID  
    ORDER BY  VOH_EDOLES_VIEW.Code,   NOPARAST 




GO


---END SCRIPT 1447
------------------------------------------------------------------------------------ 

