CREATE view [dbo].[EXPORT_ENTOLES_METAFORAS] as
select
	voh.identolea [entolid],
	paraliptis.id [paralid],
	apostoleas.id [apostid],
	kentrakostous.id [kekoid],
	sugkentrotiko.id [sugkid],
	voh.idparast [vohparastkindid],
	companies.id [companyid],
	companies.Eponimia [Κατάστημα Εντολής],
	convert(date, voh.Dateprint) [Ημερομηνία Εντολής],
	month(voh.DATEPRINT) [Μήνας Εντολής],
	voh.PARASTATIKO [Τύπος Παραστατικού],
	voh.SEIRA [Σειρά Παραστατικού],
	voh.NOPARAST [Αριθμός Παραστατικού],
	rtrim(VOH.SEIRA)+VOH.NOPARAST [Barcode ID Παραστατικού],
	voh.arrival [Αριθμός Άφιξης],
	voh.aranaforas [Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	cast(voh.SUMPOSO as float) [Αξία Παραστατικού (Συνολική)],
	cast(voh.poso as float) [Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [Αξία Παραστατικού (ΦΠΑ)],
	headervohpricing.DescrCatalog [Τιμοκατάλογος Παραστατικού],
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [Αξία Εμπορευμάτων Παραστατικού],
	null [Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [SLOT Υπηρεσίας Σύμφωνα με Reservation],
	FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS [Αρ. Διπλότυπης Καταστήματος],
	KAA.DATEPRINT [Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [Οδηγός Διπλότυπης Καταστήματος],
	FORTOTIKES.NOLISTASDIANOMIS [Αρ. Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DATEPRINT [Ημερομηνία Διπλότυπης Κέντρου Διανομής],
	MONTH(LISTESDIANOMIS.DATEPRINT) [Μήνας Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.OXIMA [Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DRIVER [Οδηγός Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.STATUS [Status Διπλότυπης Κέντρου Διανομής],
	cast(grammesvohsum.temaxia as float) [Σύνολο Τεμαχίων],
	grammesvohsum.countid [Σύνολο κωδικών εμπορευμάτων],
	cast(grammesvohsum.baros as float) [Συνολικό Βάρος],
	cast(grammesvohsum.kybika as float) [Συνολικός Όγκος],
	voh.COMMENTS [Σχόλια - Παρατηρήσεις],
	paraliptis.Eponimia [Επωνυμία Παραλήπτη],
	paraliptis.AddressTK [ΤΚ Παραλήπτη],
	NULL [Ζώνη ΤΚ Παραλήπτη],
	paraliptis.AddressCity [Περιοχή Παραλήπτη],
	paraliptis.AddressPref [Νομός Παραλήπτη],
	paraliptis.AddressStr [Διεύθυνση Παραλήπτη],
	paraliptis.Mobile [Κινητό Τηλέφωνο Παραλήπτη],
	paraliptis.Tel [1ο Τηλέφωνο Παραλήπτη],
	voh.OROFOS [Όροφος Παράδοσης Παραλήπτη],
	voh.ENTOLEASDESCR [Επωνυμία Εντολέα],
	apostoleas.Eponimia [Επωνυμία Αποστολέα],
	apostoleas.AddressTK [ΤΚ Αποστολέα],
	NULL [Ζώνη ΤΚ Αποστολέα],
	apostoleas.AddressCity [Περιοχή Αποστολέα],
	apostoleas.AddressPref [Νομός Αποστολέα],
	apostoleas.addressstr [Διεύθυνση Αποστολέα],
	apostoleas.Mobile [Κινητό Τηλέφωνο Αποστολέα],
	apostoleas.Tel [1ο Τηλέφωνο Αποστολέα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΟΧΙ'
		else 'ΝΑΙ'
	end [Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [Δελατόλας Καταβάλλων τα Κόμιστρα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN ''
		else paradoseis.Eponimia
	end [Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
	voh.PRAKTOREIODESCR [Πρακτορείο Συνεργάτης],
	case ISNULL(VOH.IF_CLOSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [Τιμολογημένη κατα την έκδοση],
	voh.UserCreate [Χρήστης εκδόσας την Εντολή],
	voh.UserMod [Χρήστης μεταβολής Εντολής],
	-- syndedemeno pistwtiko parastatiko ?
	NULL [Συνδεδεμένο Πιστωτικό Παραστατικό],
	NULL [Είδος Πιστωτικού Παραστατικού],
	NULL [Ημερομηνία Πιστωτικού Παρσταατικού],
	NULL [Μήνας Πιστωτικού Παρσταατικού],
	NULL [Σειρά Πιστωτικού Παραστατικού],
	NULL [Αρ. Πιστωτικού Παραστατικού],
	NULL [Barcode ID Πιστωτικού Παραστατικού],
	NULL [Αξία Πιστωτικού Παραστατικού (Συνολική)],
	NULL [Αξία Πιστωτικού Παραστατικού (Καθαρή)],
	NULL [Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
	NULL [Εκδόσας Πιστωτικού],
	case isnull(kindparastatikon.IF_TRANSFORM, 0)
		when 0 then 'ΟΧΙ'
		else 'ΝΑΙ'
	end [Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο], 
	case 
		when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
	sugkentrotiko.DATEPRINT [Ημερομηνία Τιμολόγησης],
	month(sugkentrotiko.DATEPRINT) [Μήνας Τιμολόγησης],
	sugkentrotiko.seira [Σειρά Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.NOPARAST [Αρ. Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.EXT_BARCODE [Barcode ID Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.SUMPOSO [Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
	sugkentrotiko.poso [Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
	sugkentrotiko.taxis [Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
	sugkentrotiko.UserCreate [Εκδόσας Τιμολογίου],
	null [Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]

from voh
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
join (
	select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
join (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		SUM(TEMAXIA) countid,
		sum(BAROS) baros,
		sum(KYBIKA) kybika
	from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.IDENTOLIS = voh.id
left join voh sugkentrotiko on sugkentrotiko.SEIRA + sugkentrotiko.NOPARAST = fortotikes.NOPARASTDELTIOUDIANOMIS
left join KINDPARASTATIKON on KINDPARASTATIKON.id = fortotikes.IDPARAST
left join FORTOTIKES_ANA_KAA on FORTOTIKES_ANA_KAA.IDFORTOTIKIS = FORTOTIKES.ID
left join KAA on KAA.ID = FORTOTIKES_ANA_KAA.IDKAA
--left join FORTOTIKES_ANA_LISTA on FORTOTIKES_ANA_LISTA.IDFORTOTIKIS = FORTOTIKES.ID
--left join LISTESDIANOMIS on LISTESDIANOMIS.id = FORTOTIKES_ANA_LISTA.IDLISTAS

left join (
	SELECT MAX(IDLISTAS) IDLISTAS, IDFORTOTIKIS FROM FORTOTIKES_ANA_LISTA GROUP BY IDFORTOTIKIS
) FAL ON FAL.IDFORTOTIKIS = FORTOTIKES.ID
left join LISTESDIANOMIS on LISTESDIANOMIS.id = FAL.IDLISTAS

--left join LISTESDIANOMIS on LISTESDIANOMIS.id = FORTOTIKES.IDLISTAS
where voh.parastatiko not like '%ΣΥΝΑΡΜ%'
and voh.ifDelete = 0
--order by 1
GO

---END SCRIPT 1448
------------------------------------------------------------------------------------ 

---NEW SCRIPT 1449


CREATE TRIGGER [dbo].[CHANGE_ENTOLEAS_WHEN_EKDOSH_APODEIKSH]
   ON  [dbo].[VOH]
   AFTER INSERT
AS 
BEGIN
	
	SET NOCOUNT ON;
	update entolh
	set entolh.IDENTOLEA = apodeixh.IDENTOLEA,
		entolh.ENTOLEASDESCR = apodeixh.ENTOLEASDESCR,
		entolh.AFMENTOLEA = a.AFM,
		entolh.CODEENTOLEA = a.Code, -- ypo suzhthsh
		entolh.IDCUSTOMER = a.id,
		entolh.CodeCustomer = a.Code,
		entolh.CustDescr = a.Eponimia,
		entolh.EPAGELMA = a.Epagelma,
		entolh.AFM = a.AFM,
		entolh.DOY = a.DOY,
		entolh.ADDRESSSTREET = a.AddressStr,
		entolh.ADDRESSNO = a.AddressNo,
		entolh.PREF = a.AddressPref,
		entolh.CITY = a.AddressCity,
		entolh.tel = a.tel,
		entolh.MOBILE = a.Mobile
	from inserted apodeixh
	join accounts a on a.id = apodeixh.identolea
	join voh entolh on entolh.id=apodeixh.IDORDER
	join KINDPARASTATIKON kp on kp.id = apodeixh.idparast and kp.IF_ENIMEROSIKARTELA = 1
	where (entolh.IDENTOLEA <> apodeixh.IDENTOLEA OR entolh.ENTOLEASDESCR <> apodeixh.ENTOLEASDESCR)

END
GO



---END SCRIPT 1449
