CREATE TRIGGER [dbo].[REMOVE_IFCLOSE_WHEN_DELETE_APODEIKSH] 
   ON  [dbo].[VOH]
   AFTER DELETE
AS 
BEGIN
	
	SET NOCOUNT ON;

    update v set v.if_close = 0 
	from deleted d 
	join voh v on v.id = d.IDORDER

END
GO


