---NEW SCRIPT 1451

create PROCEDURE [dbo].[updateVOH_ANA_LISTAASS]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDLISTAS				NUMERIC(18, 0)= NULL,
	@NoPARASTLISTAS			NVARCHAR(10)= NULL, 
	@IDEMPLOYEE				NUMERIC(18, 0)= NULL, 
	@EMPLOYEE				NVARCHAR(60)= NULL,
	@INSERTVOH				NVARCHAR(MAX)= NULL,
	@DELETEDVOH				NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON
DECLARE @_STATUS varchar(75)
SET @_STATUS = 'ΣΕ ΚΑΤΑΣΤΑΣΗ ΑΝΑΘΕΣΗΣ'
DECLARE @_NULL varchar(75)
SET @_NULL = ''

EXEC('DELETE FROM VOH_ANA_LISTAASS WHERE  IDLISTAS = ' + @IDLISTAS)
IF LEN(@DELETEDVOH)>0
BEGIN
	EXEC('UPDATE VOH SET NOPARASTLISTASSYNARMOLOGISIS ='''+@_NULL+''' WHERE ID IN(' + @DELETEDVOH + ')')
END
--EXEC('DELETE FROM dbo.FORTOTIKES_ANA_KAA WHERE IDFORTOTIKIS IN(' + @DELETEDFORTOTIKES + ') AND IDKAA = '+@IDKAA)
EXEC('UPDATE VOH SET NOPARASTLISTASSYNARMOLOGISIS ='''+@NoPARASTLISTAS +''', EMPLOYEE ='''+	@EMPLOYEE +
	''', IDEMPLOYEE ='''+@IDEMPLOYEE +''', STATUS =	3, STATUSDESCR = '''+@_STATUS+''' WHERE ID IN(' + @INSERTVOH + ')')
declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @INSERTVOH) 
    WHILE @start < LEN(@INSERTVOH) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@INSERTVOH) + 1
       
        INSERT INTO VOH_ANA_LISTAASS (IDLISTAS, IDVOH)  
        VALUES(@IDLISTAS, CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC)) 
        SET @start = @end + 1 
        SET @end = CHARINDEX(@coma, @INSERTVOH, @start)
        
    END 
   
END

GO

---END SCRIPT 1451
------------------------------------------------------------------------------------ 

---NEW SCRIPT 1452


ALTER PROCEDURE [dbo].[insertTOLISTAASS]

(
	@IDPARAST					numeric(18, 0)= NULL,
	@PARASTATIKO				nvarchar(100)= NULL,
	@SEIRA						nvarchar(10)  = NULL,
	@NOPARAST					nvarchar(20) = NULL,
	@DATEPRINT					smalldatetime =NULL,
	@DATEPARADOSI				smalldatetime =NULL,
	@IFCANCEL					int =0,
	@DATECANCEL					smalldatetime =NULL,
	@PERIOXIPROORISMOU			nvarchar(50) = NULL,
	@PERIOXIPARADOSIS			nvarchar(50) = NULL,
	@POSO						numeric(18, 2)= NULL,
	@TAXISPERCENT				numeric(18, 2) =NULL,
	@TAXIS						numeric(18, 2)= NULL,
	@SUMPOSO					numeric(18, 2)= NULL,
	@POSOEXODA					numeric(18, 2)= NULL,
	@TAXISPERCENTEXODA			numeric(18, 2)= NULL,
	@TAXISEXODA					numeric(18, 2) =NULL,
	@SUMPOSOEXODA				numeric(18, 2)= NULL,
	@STATUS						nvarchar(50) = NULL,
	@COMMENTS					nvarchar(max)= NULL,
	@POSOOFEIL					numeric(18, 2)= NULL,
	@SUMBAROS					numeric(18, 2)= NULL,
	@IDSTATUS					numeric(18, 0)= NULL,
	@OMADPROORISMOS				nvarchar(50) = NULL,
	@IDXRHSHS					NUMERIC(18,0) = 0,
	@IDCOMPANY					NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = 0,
	@IDCUSTOMER					numeric(18, 0)= NULL,
	@AFMCUSTOMER				NVARCHAR(10)= NULL,
	@CUSTOMER					nchar(80)= NULL,
	@FORTOSI					NVARCHAR (50) = NULL,
	@IDEMPLOYEE					numeric(18, 0)= NULL,
	@EMPLOYEE					NVARCHAR (50) =NULL,
	@BOAT						NVARCHAR (50) =NULL,
	@UserCreate					nvarchar (50)= NULL,
	@DateCreate					datetime = NULL,	
	@IFAUTONUMBER				int = 0,
	@ifDelete					int = 0,
	@TheID						NUMERIC(18, 0)= NULL output
) 
AS

DECLARE @NEWNOPARAST NUMERIC(18,2)=0
--GO

IF @IFAUTONUMBER =1
	BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM LISTESSYNARMOLOGISIS WHERE  SEIRA = @SEIRA AND  IDPARAST =@IDPARAST)
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM LISTESSYNARMOLOGISIS WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END		
		END
	ELSE
		BEGIN
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM LISTESSYNARMOLOGISIS WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST)
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM LISTESSYNARMOLOGISIS WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END		
		END
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END;
	
		BEGIN
			INSERT INTO LISTESSYNARMOLOGISIS
				(
				IDPARAST,
				PARASTATIKO,
				SEIRA,
				NOPARAST,
				DATEPRINT,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				POSOEXODA,
				TAXISPERCENTEXODA,
				TAXISEXODA,
				SUMPOSOEXODA,
				STATUS,
				COMMENTS,
				SUMBAROS,
				IDSTATUS,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IDCUSTOMER,
				AFMCUSTOMER,
				CUSTOMER,
				IDEMPLOYEE,
				EMPLOYEE,
				UserCreate,
				DateCreate,
				ifDelete
				)
			VALUES
				(
				@IDPARAST,
				@PARASTATIKO,
				@SEIRA,
				@NOPARAST,
				@DATEPRINT,
				@DATEPARADOSI,
				@IFCANCEL,
				@DATECANCEL,
				@POSO,
				@TAXISPERCENT,
				@TAXIS,
				@SUMPOSO,
				@POSOEXODA,
				@TAXISPERCENTEXODA,
				@TAXISEXODA,
				@SUMPOSOEXODA,
				@STATUS,
				@COMMENTS,
				@SUMBAROS,
				@IDSTATUS,
				@IDXRHSHS,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IDCUSTOMER,
				@AFMCUSTOMER,
				@CUSTOMER,
				@IDEMPLOYEE,
				@EMPLOYEE,
				@UserCreate,
				@DateCreate,
				@ifDelete
				)
			SELECT  @TheID = MAX(ID) FROM dbo.LISTESSYNARMOLOGISIS WITH (NOLOCK)

		END

GO

---END SCRIPT 1452
------------------------------------------------------------------------------------ 

---NEW SCRIPT 1453

--EXEC sp_rename LISTAASS_VOH_REPORT, LISTAASS_VOH_REPORT_OLD_1

ALTER VIEW LISTAASS_VOH_REPORT
AS

SELECT
	VOH.ID as IDVOH,
	LISTESSYNARMOLOGISIS.ID,
	CASE VOH.IFXRENTOL + VOH.IFXRAPOST * 2 + VOH.IFXRPARAL * 4 + VOH.IFXRTRITOU * 8
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		WHEN 8 THEN 'ΤΡΙΤΟΣ'
	ELSE 'ΑΓΝΩΣΤΟΣ'
	END AS XREOYMENOS,	
	VOH.AFMAPOSTOLEA,
	VOH.APOSTOLEASDESCR,
	VOH.ENTOLEASDESCR,
	VOH.PARALISPTISDESCR,
	GRAMMESVOH.POSOTHTA,
	GRAMMESVOH.TEMAXIA,
	(RTRIM(VOH.SEIRA)+ VOH.NOPARAST) AS NOPARAST,
	KINDPARASTATIKON.Code AS CODE,
	ACCOUNTS.AddressCity,
	CAST(HEADERVOH.KOMISTRA AS NUMERIC(18,2)) AS KOMISTRA,
	CAST (HEADERVOH.OTHERXREOSIS AS NUMERIC(18,2)) AS OTHERXREOSIS,
	GRAMMESVOH.TIMDA,
	GRAMMESVOH.AXIA,
	GRAMMESVOH.BAROS,
	GRAMMESVOH.KYBIKA,
	GRAMMESVOH.PERIEXOMENO,
	CASE VOH.IFPREPAY
		WHEN 1 THEN ISNULL(XREOSISANADELTIO.SUMPOSO ,0)
	END AS XREOSIPROPLIROMENES,
	CASE VOH.IFOFEILOMENI
		WHEN 1 THEN ISNULL(XREOSISANADELTIO.SUMPOSO,0)
	END AS XREOSIOFEILOMENES,
	VOH.SUMANTIK,
	LISTESSYNARMOLOGISIS.IDPARAST,
    LISTESSYNARMOLOGISIS.PARASTATIKO,
    LISTESSYNARMOLOGISIS.SEIRA AS SEIRALUISTA,
    LISTESSYNARMOLOGISIS.NOPARAST  AS NOPARASTLISTAS,
    LISTESSYNARMOLOGISIS.DATEPRINT,
    LISTESSYNARMOLOGISIS.OXIMA,
    LISTESSYNARMOLOGISIS.DRIVER,
    HEADERVOH.XREOSISTRITON,
    VOH.OMADPROORISMOS,
    CAST(HEADERVOH.ASFALISTRA AS NUMERIC(18,2)) AS ASFALISTRA,
    CAST(HEADERVOH.TAXIS AS NUMERIC(18,2)) AS TAXISXREOSEON,
    CAST(HEADERVOH.KATHARO AS NUMERIC(18,2)) AS KATHARO,
    EMPLOYEE.id AS IDEMPLOYEE,
    EMPLOYEE.Eponimia AS EMPLOYEE,
    VOH.IF_ANTIKCASHSYNAR,
    CASE IF_ANTIKCASHSYNAR
			WHEN 1 THEN VOH.ANTIKCASHSYNAR
		ELSE 0
		END AS ANTIKCASHSYNAR,
	VOH.ANAMEXODO,
	VOH.POSO,
	VOH.SUMPOSO,
	LISTESSYNARMOLOGISIS.IDCOMPANY,
    LISTESSYNARMOLOGISIS.IDYPOKATASTIMA,
    LISTESSYNARMOLOGISIS.IDXRHSHS,
    VOH.IDPRAKTOREIO,
    VOH.PRAKTOREIODESCR,
    LISTESSYNARMOLOGISIS.AFMCUSTOMER,
    LISTESSYNARMOLOGISIS.CUSTOMER,
    VOH.EXT_BARCODE,
    ACCOUNTS.AFM AS PARALAFM,
    ACCOUNTS.Epagelma AS  PARALEPAGELMA,
    ACCOUNTS.AddressStr AS  PARALADDRSTR,
    ACCOUNTS.AddressNo AS PARALADDRNO,
    ACCOUNTS.AddressTK AS PARALADDRTK,
    ACCOUNTS.AddressCity AS  PARALCITY,
    EMPLOYEE.AFM AS EMPLAFM,
    EMPLOYEE.DOY AS EMPLDOY,
    EMPLOYEE.Epagelma AS EMPLLEPAGELMA,
    EMPLOYEE.AddressStr AS EMPLADDRSTR,
    EMPLOYEE.AddressNo AS EMPLADDRNO,
    EMPLOYEE.AddressTK AS EMPLADDRTK,
    EMPLOYEE.AddressCity AS EMPLLCITY,
    VOH.IDKINDPAYMENT,
    VOH.KINDPAYMENTDESCR
		
FROM VOH
inner join  VOH_ANA_LISTAASS ON VOH_ANA_LISTAASS.IDVOH=VOH.ID
INNER JOIN LISTESSYNARMOLOGISIS ON LISTESSYNARMOLOGISIS.ID=VOH_ANA_LISTAASS.IDLISTAS
INNER JOIN (
	select 
		IDVOH,
		TIMDA,
		PERIEXOMENO,
		CAST(SUM(TEMAXIA) as FLOAT) as POSOTHTA,
		CAST(SUM(PCS) AS FLOAT) AS TEMAXIA,
		CAST(SUM(BAROS) AS FLOAT) AS BAROS,
		CAST(SUM(KYBIKA) AS NUMERIC(18,3)) AS KYBIKA,
		CAST(SUM(ARXTIMI) AS NUMERIC(18,2)) AS AXIA 
		from GRAMMESVOH
		GROUP BY IDVOH ,TIMDA,PERIEXOMENO
			)AS GRAMMESVOH ON grammesvoH.IDVOH=VOH.ID
INNER JOIN KINDPARASTATIKON ON KINDPARASTATIKON.ID=VOH.IDPARAST
INNER JOIN ACCOUNTS ON ACCOUNTS.id=VOH.IDPARALIPTI
INNER JOIN HEADERVOH ON HEADERVOH.IDVOH=VOH.ID
LEFT JOIN	(
				SELECT 
					ID,
					IDVOH,
					SUM(POSO) AS POSO,
					SUM(TAXIS) AS TAXIS,
					SUM(SUMPOSO) AS SUMPOSO
				FROM XREOSISANADELTIO
				WHERE IDVOH=1 
				GROUP BY ID,IDVOH
			) AS XREOSISANADELTIO ON XREOSISANADELTIO.IDVOH=VOH.ID	
LEFT JOIN EMPLOYEE ON EMPLOYEE.ID=LISTESSYNARMOLOGISIS.IDEMPLOYEE			

GO

---END SCRIPT 1453
------------------------------------------------------------------------------------ 
