ALTER PROCEDURE [dbo].[updateFORT_ANA_KAA]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDKAA					NUMERIC(18, 0)= NULL,
	@NoPARASTKAA			NVARCHAR(10)= NULL, 
	@OXIMA					NVARCHAR(60)= NULL,
	@CONTAINER				NVARCHAR (50) =NULL,
	@BOAT					NVARCHAR (50) =NULL,
	@INSERTFORTOTIKES		NVARCHAR(MAX)= NULL,
	@DELETEDFORTOTIKES		NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON

DECLARE @_STATUSID int
DECLARE @_STATUS varchar(75)
--SET @_STATUS = 'ΣΕ ΚΑΑ'

SELECT @_STATUS = STATUS, @_STATUSID = IDSTATUS FROM KAA WHERE ID = @IDKAA

IF LEN(@_STATUS) < 3 
BEGIN
	SELECT TOP 1 @_STATUS = DESCR, @_STATUSID = ID FROM DOC_STATUS WHERE IFSEKAA = 1 
END



DECLARE @_NULL varchar(75)
SET @_NULL = ''

EXEC('DELETE FROM FORTOTIKES_ANA_KAA WHERE  IDKAA = ' + @IDKAA)
IF LEN(@DELETEDFORTOTIKES)>0
BEGIN
	EXEC('UPDATE FORTOTIKES SET NOPARASTDELTIOUAPOSTOLIS ='''+@_NULL+''' WHERE ID IN(' + @DELETEDFORTOTIKES + ')')
END
--EXEC('DELETE FROM dbo.FORTOTIKES_ANA_KAA WHERE IDFORTOTIKIS IN(' + @DELETEDFORTOTIKES + ') AND IDKAA = '+@IDKAA)
EXEC('UPDATE FORTOTIKES SET NOPARASTDELTIOUAPOSTOLIS ='''+@NoPARASTKAA +''', CONTAINER ='''+@CONTAINER +''', OXIMA ='''+	@OXIMA +
	''', BOAT ='''+@BOAT +''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = '''+@_STATUS+''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')
declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @INSERTFORTOTIKES) 
    WHILE @start < LEN(@INSERTFORTOTIKES) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@INSERTFORTOTIKES) + 1
       INSERT INTO FORTOTIKES_ANA_KAA (IDKAA, IDFORTOTIKIS, KOMISTRA, DIKAIOMA, OTHERPOSO, EXODATRITON, XREOSIPROPLIROMENES, 
      XREOSIOFEILOMENES, XREOSIPROPLIROMENESCASH, XREOSIPROPLIROMENESPISTOSI, POSO, TAXIS, SUMPOSO, ANTIKCASH, 
      ANTIKEPIT, ANTIKSYNAL, ANTIKOTHER, SUMANTIK, IDPARALIPTI, PARALISPTISDESCR, IDAPOSTOLEA, APOSTOLEASDESCR, 
       IDENTOLEA, ENTOLEASDESCR, IDTRITOU, TRITOSDESCR, XREOYMENOS, OMADPROORISMOS, OXIMA, DRIVERDESCR, BAROS, 
       KYBIKA, TEMAXIA, AXIA, PERIEXOMENO, TIMDA, ASFALISTRA, ERGATIKA, CODE, NOPARASTFORT, SYSKEVASIA, DIAFORA_EXODA, 
      XREOSEISTRITON, EMVASTIKA, OTHERXREOSEIS, PROPLMETRERGATIKA, PROPLMETRASFALISTRA, PROPLMETRDIKAIOMA, PROPLMETRKOMISTRA, 
      IDPRAKTOREIO, PRAKTOREIODESCR, ANAMEXODO, PROPLMETROTHERXREOSEIS, ANTAPOKRITIS, OFEILOMENAKOMISTRA, SYN_POSO_FORTOTIKIS, 
      TAXISOFEIL, TAXISPROPLMETR, KATHAROOFEIL, KATHAROPROPLMETR) 
      SELECT @IDKAA AS IDKAA, A.ID, A.KOMISTRA, A.DIKAIOMA, A.OTHERPOSO, A.EXODATRITON, A.XREOSIPROPLIROMENES, 
      A.XREOSIOFEILOMENES, A.XREOSIPROPLIROMENESCASH, A.XREOSIPROPLIROMENESPISTOSI, A.POSO, A.TAXIS, A.SUMPOSO, A.ANTIKCASH, 
      A.ANTIKEPIT, A.ANTIKSYNAL, A.ANTIKOTHER, A.SUMANTIK, A.IDPARALIPTI, A.PARALISPTISDESCR, A.IDAPOSTOLEA, A.APOSTOLEASDESCR, 
       A.IDENTOLEA, A.ENTOLEASDESCR, A.IDTRITOU, A.TRITOSDESCR, A.XREOYMENOS, A.OMADPROORISMOS, A.OXIMA, A.DRIVERDESCR, A.BAROS, 
       A.KYBIKA, A.TEMAXIA, A.AXIA, A.PERIEXOMENO, A.TIMDA, G.ASFALISTRA, G.ERGATIKA, A.CODE, A.NOPARASTFORT, A.SYSKEVASIA, G.DIAFORA_EXODA, 
      G.XREOSEISTRITON, G.EMVASTIKA, G.OTHERXREOSEIS, G.PROPLMETRERGATIKA, G.PROPLMETRASFALISTRA, G.PROPLMETRDIKAIOMA, G.PROPLMETRKOMISTRA, 
      A.IDPRAKTOREIO, A.PRAKTOREIODESCR, A.ANAMEXODO, G.PROPLMETROTHERXREOSEIS, FR.ANTAPOKRITISDESCR, G.OFEILOMENAKOMISTRA, G.SYN_POSO_FORTOTIKIS, 
      G.TAXISOFEIL, G.TAXISPROPLMETR, G.KATHAROOFEIL, G.KATHAROPROPLMETR FROM
       FORTOTIKES_ANALYSH_XREOSEON AS A LEFT JOIN FORTOTIKES AS FR ON FR.ID = A.ID 
       INNER JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI AS G ON A.ID = G.ID WHERE  A.ID  = CAST( SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start)AS NUMERIC)
       
        --VALUES(@IDKAA, CAST( SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start)AS NUMERIC)) 
        SET @start = @end + 1 
        SET @end = CHARINDEX(@coma, @INSERTFORTOTIKES, @start)
        
    END 
   
END
