-- =============================================

CREATE TRIGGER [dbo].[FORTOTIKES_SCHEDULE_API_NOTIFICATION] 
   ON  [dbo].[FORTOTIKES]
   AFTER INSERT, UPDATE, DELETE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	with t(fortid, act, username) as (
		SELECT
			COALESCE(inserted.id, deleted.id),
			CASE 
				WHEN deleted.ifDelete IS NULL AND inserted.ifDelete IS NOT NULL THEN -- kanoniko insert
						'INS'	
				WHEN deleted.ifDelete IS NOT NULL AND inserted.ifDelete IS NULL THEN -- hard delete
						'DEL'
				WHEN deleted.ifDelete = 1 AND inserted.ifDelete = 0 THEN -- soft undelete, to theoroume san insert gia na steilei pali nea eggrafh
						'INS'
				WHEN deleted.ifDelete = 0 AND inserted.ifDelete = 1 THEN -- soft delete
						'DEL'
				WHEN deleted.ifDelete = 1 AND inserted.ifDelete = 1 THEN -- den stelnoume tipota giati den exei thn eggrafh perasmenh afou exei ginei hdh to delete
						'N/A'
				WHEN deleted.ifDelete = 0 AND inserted.ifDelete = 0 THEN -- update
						'UPD'
			END,
			COALESCE(inserted.USERMOD, inserted.USERCREATE, CURRENT_USER)
		FROM deleted
		FULL JOIN inserted on deleted.id = inserted.id
	)

	INSERT INTO API_NOTIFICATION_LIST (FORTID, DATEMODIFIED, [USER], [EVENT], [IFSENT])
	SELECT
		t.fortid,
		SYSDATETIME(),
		t.username,
		t.act,
		0
	FROM t
	where t.act in ('INS', 'DEL', 'N/A')			-- katagrafoume panta ta events INSERT,DELETE, WTF MAN TI EGINE EDO
	or (
		t.act = 'UPD' 
		and (
			SELECT COUNT(ID) 
			from API_NOTIFICATION_LIST ANL 
			where ANL.FORTID = t.fortid 
			AND ANL.EVENT IN ('INS', 'UPD') 
			AND ANL.IFSENT = 0
		) = 0										-- kai ta UPDATE ta katagrafoume gia apostolh mono an DEN ekkremei
	)												-- na steiloume kapoio prohgoumeno UPDATE h to INSERT
													-- (allios den exei nohma, giati tha fugoun pollapla idia requests 
													-- otan tha ginei h mazeutikh apo to docuclasspush
													-- px ena gia to insert kai 5 update me tis idies plirofories akrivos)
END
GO

ALTER TABLE [dbo].[FORTOTIKES] ENABLE TRIGGER [FORTOTIKES_SCHEDULE_API_NOTIFICATION]
GO

---END SCRIPT 1464
------------------------------------------------------------------------------------ 

