---NEW SCRIPT 1473


CREATE NONCLUSTERED INDEX LOUKAS8
ON [dbo].[VOH] ([IDAPOSTOLEA])
INCLUDE ([ID],[IDPARAST],[PARASTATIKO],[SEIRA],[NOPARAST],[IFXRAPOST],[APOSTOLEASDESCR],[IFXRPARAL],[IDPARALIPTI],[IFXRENTOL],[IDENTOLEA],[ENTOLEASDESCR],[IFXRTRITOU],[IDTRITOU],[IDCUSTOMER],[CustDescr],[EPAGELMA],[AFM],[DOY],[ADDRESSSTREET],[ADDRESSNO],[PREF],[CITY],[TEL],[MOBILE],[THETIME],[DATEPRINT],[DISCOUNTPerCent],[DISCOUNT],[POSO],[TAXISPERCENT],[TAXIS],[SUMPOSO],[OMADPROORISMOS],[IDKINDPAYMENT],[KINDPAYMENTDESCR],[IFANTIKCASH],[ANTIKCASH],[ANTIKEPIT],[ANTIKSYNAL],[ANTIKOTHER],[SUMANTIK],[IFCANCELANTIK],[DATECANCELANTIK],[COMMENTSANTIK],[IFPARADOSI],[DATEPARADOSI],[IFCANCEL],[DATECANCEL],[PERIOXIFORTOSIS],[PERIOXIPARADOSIS],[COMMENTS],[OXIMA],[AITIOLOGIAPARASTATIKOU],[DATEFORTOSIS],[IFEPISTROFI],[DATEEPISTROFIS],[AITIOLOGIAEPISTROFIS],[COMMENTSEPISTROFIS],[IFCASH],[IFPISTOSI],[IFPREPAY],[IFOFEILOMENI],[IDPRAKTOREIO],[PRAKTOREIODESCR],[STATUS],[STATUSDESCR],[YPAITIOS],[IFEPANADROMOLOGISI],[IFEPANEKDOSI],[IFOKEPANADROMOLOGISI],[NOPARASTANTIK],[COMMENTSAKIROSIS],[IFEISPRANTIK],[IFPARADOSIANTIK],[IFPARALAVIANTIK],[COMMENTSPARADANTIK],[COMMANTSPARALANTIK],[COMMENTSEISPRANTIK],[DATEPARADANTIK],[DATEPARALANTIK],[DATEEISPRANTIK],[EISPRAXASANTIK],[NOPARPARADANTIK],[NOPARASTEISPRANTIK],[NOPARPARALANTIK],[DATEPARAL],[DATEPARAD],[COMMENTSPARAD],[COMMANTSPARAL],[TIMEPARALFROM],[TIMEPARALTO],[TIMEPARADFROM],[TIMEPARADTO],[ANAMEXODO],[COMMENTS2],[AFMXREOUMENOU],[UserCreate],[UserMod],[ifDelete],[AFMAPOSTOLEA],[IDXRHSHS],[IDCOMPANY],[IDYPOKATASTIMA],[IF_CLOSE],[POSOEPIVAR],[TAXISEPIVAR],[SUMPOSOEPIVAR],[NO_EXT_ORDER],[OROFOS],[OROFOSDESCR],[KOUDOUNI],[ARRIVAL],[IDKENTROUKOSTOUS],[NO_EXT_ORDER_IK],[IF_ANTIKCASHSYNAR],[ANTIKCASHSYNAR],[IDXREOUMENOUENTOLIS],[ARANAFORAS],[NOPARASTLISTASSYNARMOLOGISIS],[IDEMPLOYEE],[EMPLOYEE])
GO


CREATE NONCLUSTERED INDEX LOUKAS
ON [dbo].[HEADERVOHPRICING] ([IDVOH])
INCLUDE ([DescrCatalog],[discountpercent],[discounteuro])
GO



