ALTER VIEW [dbo].[ENTOLES_METAFORAS_VIEW_NEW]
AS
select
    VOH.ID,
    voh.identolea [IDENTOLEA],
    paraliptis.id [IDPARALIPTI],
    apostoleas.id [IDAPOSTOLEA],
    kentrakostous.id [IDKENTROKOSTOUS],
    sugkentrotiko.id [IDSYGKENTROTIKO],
    voh.idparast [IDPARAST],
    VOH.IDXRHSHS,
    VOH.IDCOMPANY,
    companies.id [IDYPOKATASTIMA],
    companies.Eponimia [YPOKATASTHMA],                                         --[Κατάστημα Εντολής],
    convert(date, voh.Dateprint) [DATEPRINT],                                 --[Ημερομηνία Εντολής],
    month(voh.DATEPRINT) [MONTHDATE],                                         --[Μήνας Εντολής],
    KPR.Code,
    voh.PARASTATIKO [PARASTATIKO],                                             --[Τύπος Παραστατικού],
    voh.SEIRA [SEIRA],                                                         --[Σειρά Παραστατικού],
    convert(nvarchar(20),voh.NOPARAST) [NOPARAST],                             --[Αριθμός Παραστατικού],
    rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE],     --[Barcode ID Παραστατικού],
    voh.arrival [ARRIVAL],                                                     --[Αριθμός Άφιξης],
    voh.aranaforas [ARANAFORAS],                                                 --[Αρ. Αναφοράς ΙΚΕΑ],
    voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK],                                 --[Αρ. Παραγγελίας ΙΚΕΑ],
    voh.KINDPAYMENTDESCR,                                                     --[Τρόπος Πληρωμής],
    cast(voh.SUMPOSO as float) [SUMPOSO],                                     --[Αξία Παραστατικού (Συνολική)],
    cast(voh.poso as float) [POSO],                                         --[Αξία Παραστατικού (Καθαρή)],
    cast(voh.TAXIS as float) [TAXIS],                                         --[Αξία Παραστατικού (ΦΠΑ)],
    headervohpricing.DescrCatalog [TIMOKATALOGOS],                             --[Τιμοκατάλογος Παραστατικού],
    case
        when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
        else 'ΟΧΙ'
    end [IF_DISCOUNT_ALL],                                                     --[Έχει λάβει έκπτωση (Γενική)],
    case
        when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ'
        else 'ΟΧΙ'
    end [IF_DISCOUNT_SERVICE],                                                 --[Έχει λάβει έκπτωση (Υπηρεσίας)],
    kentrakostous.Descr [KENTRO_KOSTOUS],                                     --[Κέντρο Κόστους Παραστατικού],
    grammesvohsum.timitem [AXIA_EMPOREUMATON],                                 --[Αξία Εμπορευμάτων Παραστατικού],
    null [RESERVATION_DATE],                                                 --[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
    null [RESERVATION_SLOT],                                                 --[SLOT Υπηρεσίας Σύμφωνα με Reservation],
    FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS [NOPARASTDELTIOUAPOSTOLIS],            --[Αρ. Διπλότυπης Καταστήματος],
    KAA.DATEPRINT [KAA_DATE],                                                 --[Ημερομηνία Διπλότυπης Καταστήματος],
    MONTH(KAA.DATEPRINT) [KAA_MONTH],                                         --[Μήνας Διπλότυπης Καταστήματος],
    KAA.OXIMA [KAA_TRUCK],                                                     --[Αρ. Οχήματος Διπλότυπης Καταστήματος],
    KAA.DRIVER [KAA_DRIVER] ,                                                 --[Οδηγός Διπλότυπης Καταστήματος],    
    FORTOTIKES.SEIRA + convert(nvarchar(20),FORTOTIKES.NOPARAST) [NOPARASTFORTOTIKI],                             --[Αριθμός Παραστατικού],
    FORTOTIKES.NOLISTASDIANOMIS [NOPARASTDELTIOUDIANOMIS],                         --[Αρ. Διπλότυπης Κέντρου Διανομής],
    LISTESDIANOMIS.DATEPRINT [LISTADIANOMIS_DATE],                             --[Ημερομηνία Διπλότυπης Κέντρου Διανομής],
    MONTH(LISTESDIANOMIS.DATEPRINT) [LISTADIANOMIS_MONTH],                     --[Μήνας Διπλότυπης Κέντρου Διανομής],
    LISTESDIANOMIS.OXIMA [LISTADIANOMIS_TRUCK],                             --[Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
    LISTESDIANOMIS.DRIVER [LISTADIANOMIS_DRIVER],                             --[Οδηγός Διπλότυπης Κέντρου Διανομής],
    LISTESDIANOMIS.STATUS [LISTADIANOMIS_STATUS],                             --[Status Διπλότυπης Κέντρου Διανομής],
    cast(grammesvohsum.temaxia as float) AS [TEMAXIA],                             --[Σύνολο Τεμαχίων],
    grammesvohsum.countid [POSOTHTA],                                         --[Σύνολο κωδικών εμπορευμάτων],
    cast(grammesvohsum.baros as float) [BAROS],                             --[Συνολικό Βάρος],
    cast(grammesvohsum.kybika as float) [KYBIKA],                             --[Συνολικός Όγκος],
    voh.COMMENTS [COMMENTS],                                                 --[Σχόλια - Παρατηρήσεις],
    paraliptis.Eponimia [PARALISPTISDESCR],                                 --[Επωνυμία Παραλήπτη],
    paraliptis.AddressTK [PARALIPTIS_ZIPCODE],                                 --[ΤΚ Παραλήπτη],
    NULL  [PARALIPTIS_ZONE],                                                 --[Ζώνη ΤΚ Παραλήπτη],
    paraliptis.AddressCity [PARALIPTIS_CITY],                                 --[Περιοχή Παραλήπτη],
    paraliptis.AddressPref [PARALIPTIS_NOMOS],                                 --[Νομός Παραλήπτη],
    paraliptis.AddressStr [PARALIPTIS_ADDRESS],                             --[Διεύθυνση Παραλήπτη],
    paraliptis.Mobile [PARALIPTIS_MOBILE],                                     --[Κινητό Τηλέφωνο Παραλήπτη],
    paraliptis.Tel [PARALIPTIS_TELEPHONE],                                     --[1ο Τηλέφωνο Παραλήπτη],
    voh.OROFOS [OROFOS],                                                     --[Όροφος Παράδοσης Παραλήπτη],
    voh.ENTOLEASDESCR,                                                         --[Επωνυμία Εντολέα],
    apostoleas.Eponimia [APOSTOLEASDESCR],                                    --[Επωνυμία Αποστολέα],
    apostoleas.AddressTK [APOSTOLEAS_ZIPCODE],                                 --[ΤΚ Αποστολέα],
    NULL [APOSTOLEAS_ZONE],                                                 --[Ζώνη ΤΚ Αποστολέα],
    apostoleas.AddressCity [APOSTOLEAS_CITY],                                 --[Περιοχή Αποστολέα],
    apostoleas.AddressPref [APOSTOLEAS_NOMOS],                                 --[Νομός Αποστολέα],
    apostoleas.addressstr [APOSTOLEAS_ADDRESS],                             --[Διεύθυνση Αποστολέα],
    apostoleas.Mobile [APOSTOLEAS_MOBILE],                                     --[Κινητό Τηλέφωνο Αποστολέα],
    apostoleas.Tel [APOSTOLEAS_TELEPHONE],                                     --[1ο Τηλέφωνο Αποστολέα],
    paradoseis.PARADOSISE,
    case paradoseis.PARADOSISE
        when 'Παραλήπτη' THEN 'ΟΧΙ'
        else 'ΝΑΙ'
    end [IF_PRAKTOREIO_EPILOGHS],                                             --[Πρακτορείο Επιλογής Πελάτη],
    case paradoseis.PARADOSISE
        when 'Παραλήπτη' THEN 'ΝΑΙ'
        else 'ΟΧΙ'
    end [IF_XREOSI_DELATOLAS],                                                 --[Δελατόλας Καταβάλλων τα Κόμιστρα],
    case paradoseis.PARADOSISE
        when 'Παραλήπτη' THEN ''
        else paradoseis.Eponimia
    end [PRAKTOREIO_EPILOGHS],                                                 --[Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
    voh.PRAKTOREIODESCR [PRAKTOREIODESCR],                                     --[Πρακτορείο Συνεργάτης],
    case ISNULL(VOH.IF_CLOSE, 0)
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END [IF_CLOSE_ALREADY],                                                 --[Τιμολογημένη κατα την έκδοση],
    case ISNULL(VOH.IFCHECKED, 0)
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END [IFCHECKED],                                                         --  ΑΝ ΕΛΕΓΧΘΗΚΕ
    case ISNULL(VOH.IFREVERSE, 0)
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END [IFREVERSE],                                                         -- ΑΝ ΕΙΝΑΙ ΕΠΙΣΤΡΟΦΗ
    voh.UserCreate [USERCREATE],                                             --[Χρήστης εκδόσας την Εντολή],
    voh.UserMod [USEMOD],                                                     --[Χρήστης μεταβολής Εντολής],
    -- syndedemeno pistwtiko parastatiko ?
    NULL [ID_PISTOTIKO],                                                     --[Συνδεδεμένο Πιστωτικό Παραστατικό],
    NULL [PISTOTIKODESCR],                                                     --[Είδος Πιστωτικού Παραστατικού],
    NULL [PISTOTIKO_DATE],                                                     --[Ημερομηνία Πιστωτικού Παρσταατικού],
    NULL [PISTOTIKO_MONTH],                                                 --[Μήνας Πιστωτικού Παρσταατικού],
    NULL [PISTOTIKO_SEIRA],                                                 --[Σειρά Πιστωτικού Παραστατικού],
    NULL [PISTOTIKO_NO],                                                     --[Αρ. Πιστωτικού Παραστατικού],
    NULL [PISTOTIKO_BARCODE],                                                 --[Barcode ID Πιστωτικού Παραστατικού],
    NULL [PISTOTIKO_SUMPOSO],                                                 --[Αξία Πιστωτικού Παραστατικού (Συνολική)],
    NULL [PISTOTIKO_KATHARO],                                                --[Αξία Πιστωτικού Παραστατικού (Καθαρή)],
    NULL [PISTOTIKO_FPA],                                                     --[Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
    NULL [PISTOTIKO_USERCREATE],                                             --[Εκδόσας Πιστωτικού],
    case isnull(kpr.IF_TRANSFORM, 0)
        when 0 then 'ΟΧΙ'
        else 'ΝΑΙ'
    end [IF_TRANSFORM_INFORM],                                                 --[Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο],
    case
        when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
        else 'ΟΧΙ'
    end [IF_TRANSFORMED],                                                     --[Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
    sugkentrotiko.DATEPRINT [SYGKENTROTIKO_DATE],                             --[Ημερομηνία Τιμολόγησης],
    month(sugkentrotiko.DATEPRINT) [SYGKENTROTIKO_MONTH],                     --[Μήνας Τιμολόγησης],
    sugkentrotiko.seira [SYGKENTROTIKO_SEIRA],                                 --[Σειρά Συγκεντρωτικού Τιμολογίου],
    sugkentrotiko.NOPARAST [SYGKENTROTIKO_NOPARAST],                         --[Αρ. Συγκεντρωτικού Τιμολογίου],
    sugkentrotiko.EXT_BARCODE [SYGKENTROTIKO_EXT_BARCODE],                    --[Barcode ID Συγκεντρωτικού Τιμολογίου],
    sugkentrotiko.SUMPOSO [SYGKENTROTIKO_SUMPOSO],                             --[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
    sugkentrotiko.poso [SYGKENTROTIKO_KATHARO],                             --[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
    sugkentrotiko.taxis [SYGKENTROTIKO_FPA],                                 --[Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
    sugkentrotiko.UserCreate [SYGKENTROTIKO_USERCREATE],                     --[Εκδόσας Τιμολογίου],
    null [SYGKENTROTIKO_PISTOTIKOID],                                         --[Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]
    VOH.IF_CLOSE,
    kpr.IF_ORDER,
    KPR.KindKINISIS,
    kpr.IF_EDMETAFORAS,
    kpr.IF_EDSYNARMOL,
    kpr.IF_ENDILMETAFORAS,
    kpr.IF_EDTOPOTH,
    VOH.NO_EXT_ORDER,
    VOH.NOPARASTLISTASSYNARMOLOGISIS,
    COMPANIES.AddressStr [ADDRESS_YPOKATASTHMA],
    COMPANIES.AddressTK [TK_YPOKATASTHMA],
    COMPANIES.AddressCity [CITY_YPOKATASTHMA],
    COMPANIES.BARCODE_Prefix [BARCODEPREFIX_YPOKAT],
    COMPANIES.EMAIL [EMAIL_YPOKATASTHMA],
    DBO.GetVOHEAFDSS(VOH.ID, 1) AS EAFDSS,
    VOH.CustDescr,
    VOH.EPAGELMA,
    VOH.AFM,
    VOH.CITY,
    VOH.TEL,
    VOH.MOBILE,
    VOH.OXIMA,
    VOH.OMADPROORISMOS,
    CASE
    WHEN VOH.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ'
    ELSE
    CASE WHEN VOH.IFXRAPOST = 1  THEN 'ΑΠΟΣΤΟΛΕΑΣ'
    ELSE
    CASE WHEN VOH.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
    ELSE
    CASE WHEN VOH.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
    ELSE 'ΑΓΝΩΣΤΟ'
    END
    END
    END
    END AS XREOΥMENOS,
    GRAMMESVOH.TIMDA,
    CASE
        WHEN VOH.IFPREPAY=1 THEN 1 ELSE 0
    END AS XREOSIPROPLIROMENES,        
    CASE
        WHEN VOH.IFOFEILOMENI=1 THEN 1 ELSE 0
    END AS XREOSIOFEILOMENES,
    GRAMMESVOH.PERIEXOMENO,
    VOH.PERIOXIFORTOSIS,
    VOH.PERIOXIPARADOSIS,
    VOH.SUMANTIK,
    VOH.STATUS,
    VOH.DATEPARAD,
    VOH.IDPRAKTOREIO,
    VOH.ANTIKCASH,
    VOH.ANTIKEPIT,
    VOH.ANTIKSYNAL,
    VOH.ANTIKOTHER,
    VOH.IFCANCELANTIK,
    VOH.COMMENTSANTIK,
    VOH.DATEPARADOSI,
    VOH.COMMENTS2,
    VOH.IDEMPLOYEE,
    VOH.EMPLOYEE,
    CASE    
        WHEN VOH.IFPREPAY= 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END AS IFPREPAY,
    CASE
        WHEN VOH.IFOFEILOMENI=1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END AS IFOFEILOMENI,
    GRAMMESVOH.AXIA,
    CASE
        WHEN VOH.IFXRENTOL=1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
    END AS IFXRENTOL,
    VOH.IDKINDPAYMENT,
    CASE VOH.IFXRAPOST
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
    END AS IFXRAPOST,
    CASE VOH.IFXRPARAL
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
    END AS IFXRPARAL,
    CASE VOH.IFXRTRITOU
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
    END AS IFXRTRITOU,
    VOH.IFANTIKCASH,
    --VOH.ANTIKEPIT,
    --VOH.ANTIKSYNAL,
    --VOH.ANTIKOTHER,
    VOH.ifDelete,
    VOH.IFCANCEL,
    VOH.DATECANCEL,
    VOH.IFPARADOSI,
    VOH.AITIOLOGIAPARASTATIKOU,
    VOH.DATEFORTOSIS,
    VOH.IFEPISTROFI,
    VOH.DATEEPISTROFIS,
    VOH.AITIOLOGIAEPISTROFIS,
    VOH.COMMENTSEPISTROFIS,
    VOH.IFCASH,
    VOH.IFPISTOSI,
    VOH.STATUSDESCR,
    VOH.YPAITIOS,
    VOH.IFEPANADROMOLOGISI,
    VOH.IFEPANEKDOSI,
    VOH.IFOKEPANADROMOLOGISI,
    VOH.NOPARASTANTIK,
    VOH.COMMENTSAKIROSIS,
    VOH.IFEISPRANTIK,
    VOH.IFPARADOSIANTIK,
    VOH.IFPARALAVIANTIK,
    VOH.COMMENTSPARADANTIK,
    VOH.COMMANTSPARALANTIK,
    VOH.COMMENTSEISPRANTIK,
    VOH.DATEPARADANTIK,
    VOH.DATEPARALANTIK,
    VOH.DATEEISPRANTIK,
    VOH.EISPRAXASANTIK,
    VOH.NOPARPARADANTIK,
    VOH.NOPARASTEISPRANTIK,
    VOH.NOPARPARALANTIK,
    VOH.DATEPARAL,
    VOH.COMMENTSPARAD,
    VOH.COMMANTSPARAL,
    VOH.TIMEPARALFROM,
    VOH.TIMEPARALTO,
    VOH.TIMEPARADFROM,
    VOH.TIMEPARADTO,
    VOH.DATECANCELANTIK,
    VOH.TAXISPERCENT,
    VOH.ANAMEXODO,
    VOH.ID AS IDVOH,
    CASE
        WHEN VOH.IFXRENTOL = 1 THEN VOH.IDENTOLEA
        ELSE
    CASE WHEN VOH.IFXRAPOST = 1  THEN VOH.IDAPOSTOLEA
    ELSE
    CASE
        WHEN VOH.IFXRTRITOU = 1 THEN VOH.IDTRITOU
        ELSE
    CASE WHEN VOH.IFXRPARAL = 1 THEN VOH.IDPARALIPTI
    ELSE VOH.IDCUSTOMER
    END
    END
    END
    END AS IDXREOUMENOU,
    VOH.AFMXREOUMENOU,
    HEADERVOH.ASFALISTRA,
    HEADERVOH.TAXISXREOSEON,
    HEADERVOH.SUMPOSOXRVOH,
    --VOH.OROFOS,
    VOH.OROFOSDESCR,
    VOH.KOUDOUNI,
    VOH.POSOEPIVAR,
    VOH.TAXISEPIVAR,
    VOH.SUMPOSOEPIVAR,
    (VOH.POSO + VOH.POSOEPIVAR) AS SUMKATHARO,
    (VOH.TAXIS + VOH.TAXISEPIVAR) AS SUMTAXIS,
    (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) AS SUMSUMPOSO,
    HEADERVOH.KATHARO,
    VOH.THETIME,
    VOH.IDENTOLEA AS CUSTOMERID,
    VOH.ENTOLEASDESCR AS CUSTOMERDESCR,
    VOH.IDAPOSTOLEA AS IDSYNAL,
    VOH.APOSTOLEASDESCR AS SYNALDESCR,
    VOH.IDCUSTOMER,
    VOH.DOY,
    VOH.ADDRESSSTREET,
    VOH.ADDRESSNO,
    VOH.PREF,
    VOH.AFMAPOSTOLEA,
	APOSTOLEAS.Epagelma AS SYNALEPAGELMA,
    APOSTOLEAS.AddressStr AS SYNALADDRSTR,
    APOSTOLEAS.AddressNo AS SYNALADDRNO,
    APOSTOLEAS.AddressTK AS SYNALADDRTK,
    APOSTOLEAS.AddressCity AS SYNALCITY,
    VOH.IDXREOUMENOUENTOLIS,
    APOSTOLEAS.AddressCountry AS SYNALADDRCOUNTRY,
    APOSTOLEAS.Tel AS SYNALTEL,
    APOSTOLEAS.DOY AS SYNALDOY,
    APOSTOLEAS.AFM AS SYNALAFM,
    CUSTOMERS.AddressTK AS CUSTADDRTK,
    CUSTOMERS.AddressNo AS CUSTADDRNO,
    CUSTOMERS.AddressStr AS CUSTADDRSTR,
    VOH.IF_ANTIKCASHSYNAR,
    VOH.ANTIKCASHSYNAR,
    CUSTOMERS.AddressCity AS CUSTADDRCITY,
    CUSTOMERS.AFM AS CUSTAFM,
    CUSTOMERS.DOY AS CUSTDOY,
    paraliptis.AFM AS PARALAFM,
    paraliptis.Epagelma AS PARALEPAGELMA,
    paraliptis.AddressStr AS PARALADDRSTR,
    grammesvohsum.baros as SUMBAROS,
    paraliptis.AddressNo AS PARALADDRNO,
    paraliptis.AddressTK AS PARALADDRTK,
    paraliptis.AddressCity AS PARALCITY,
    EMPLOYEE.AFM AS EMPLAFM,
    EMPLOYEE.DOY AS EMPLDOY,
    EMPLOYEE.Epagelma AS EMPLLEPAGELMA,
    EMPLOYEE.AddressStr AS EMPLADDRSTR,
    EMPLOYEE.AddressNo AS EMPLADDRNO,
    EMPLOYEE.AddressTK AS EMPLADDRTK,
    EMPLOYEE.AddressCity AS EMPLLCITY,
    kpr.IF_TRANSFORM

from voh
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
JOIN ACCOUNTS CUSTOMERS ON CUSTOMERS.ID=VOH.IDCUSTOMER
LEFT JOIN EMPLOYEE ON EMPLOYEE.id=VOH.IDEMPLOYEE
join (
    select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
join (
    select
        idvoh,
        sum(timitem) timitem,
        sum(PCS) temaxia,
        SUM(TEMAXIA) countid,
        sum(BAROS) baros,
        sum(KYBIKA) kybika
    from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
JOIN (SELECT
        IDVOH,
        SUM(SUMPOSO) AS AXIA,
        MIN(TIMDA) AS TIMDA,
        MIN(PERIEXOMENO) AS PERIEXOMENO
      FROM GRAMMESVOH
      GROUP BY IDVOH
      )GRAMMESVOH ON GRAMMESVOH.IDVOH=VOH.ID
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.IDENTOLIS = voh.id
left join voh sugkentrotiko on sugkentrotiko.SEIRA + convert(nvarchar(20),sugkentrotiko.NOPARAST) = fortotikes.NOPARASTDELTIOUDIANOMIS
left join (
    SELECT IDFORTOTIKIS, MAX(IDKAA) IDKAA FROM FORTOTIKES_ANA_KAA GROUP BY IDFORTOTIKIS
) FAK on FAK.IDFORTOTIKIS = FORTOTIKES.ID
left join KAA on KAA.ID = FAK.IDKAA
join KINDPARASTATIKON kpr on kpr.id=voh.IDPARAST and kpr.IF_EDMETAFORAS=1

left join (
    SELECT MAX(IDLISTAS) IDLISTAS, IDFORTOTIKIS FROM FORTOTIKES_ANA_LISTA GROUP BY IDFORTOTIKIS
) FAL ON FAL.IDFORTOTIKIS = FORTOTIKES.ID
left join LISTESDIANOMIS on LISTESDIANOMIS.id = FAL.IDLISTAS
LEFT JOIN(
        SELECT
        IDVOH,
        SUM(KOMISTRA) AS KOMISTRA,
        SUM(XREOSISTRITON) AS XREOSISTRITON,
        SUM(DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORT,
        SUM(OTHERXREOSIS) AS OTHERXREOSIS,
        SUM(ASFALISTRA) AS ASFALISTRA,
        SUM(TAXIS) AS TAXISXREOSEON,
        SUM(SUMPOSOXRVOH) AS SUMPOSOXRVOH,
        SUM(KATHARO) AS KATHARO
        FROM HEADERVOH
        GROUP BY IDVOH
        )HEADERVOH ON HEADERVOH.IDVOH=VOH.ID
where  voh.ifDelete = 0







GO



