	rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE], 							--[Barcode ID Παραστατικού],
	voh.arrival [ARRIVAL], 													--[Αριθμός Άφιξης],
	voh.aranaforas [ARANAFORAS], 											--[Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK], 									--[Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR, 													--[Τρόπος Πληρωμής],
	cast(voh.SUMPOSO as float) [SUMPOSO], 									--[Αξία Παραστατικού (Συνολική)],
	cast(voh.poso as float) [POSO], 										--[Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [TAXIS], 										--[Αξία Παραστατικού (ΦΠΑ)],
	headervohpricing.DescrCatalog [TIMOKATALOGOS], 							--[Τιμοκατάλογος Παραστατικού],
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_DISCOUNT_ALL], 													--[Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [IF_DISCOUNT_SERVICE], 												--[Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [KENTRO_KOSTOUS], 									--[Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [AXIA_EMPOREUMATON], 								--[Αξία Εμπορευμάτων Παραστατικού],
	null [RESERVATION_DATE], 												--[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [RESERVATION_SLOT],												--[SLOT Υπηρεσίας Σύμφωνα με Reservation],
	LISTESSYNARMOLOGISIS.DATEPRINT	[DATE_LISTAS_ASS],						--[Ημερ. Λίστας Ανάθεσης],
	listessynarmologisis.PARASTATIKO [PARASTATIKO_ASS],						--[Παραστατικό Ανάθεσης],
	rtrim(listessynarmologisis.seira)+ listessynarmologisis.NOPARAST [NOPARAST_LISTAS_ASS], --[Αρ.Λίστας Ανάθεσης],
	listessynarmologisis.EMPLOYEE [SYNERGATIS],								--[Συνεργάτης],
	listessynarmologisis.STATUS [STATUS_LISTAS_ASS],						--[Κατάσταση Λίστας Ανάθεσης], 												
	FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS [NOPARASTDELTIOUAPOSTOLIS],			--[Αρ. Διπλότυπης Καταστήματος],
	KAA.DATEPRINT [KAA_DATE], 												--[Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [KAA_MONTH], 										--[Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [KAA_TRUCK], 													--[Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [KAA_DRIVER] , 												--[Οδηγός Διπλότυπης Καταστήματος],
