		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRTRITOU,
	VOH.IFANTIKCASH,
	--VOH.ANTIKEPIT,
	--VOH.ANTIKSYNAL,
