	VOH.IFCASH,
	VOH.IFPISTOSI,
	VOH.STATUSDESCR,
	VOH.YPAITIOS,
	VOH.IFEPANADROMOLOGISI,
	VOH.IFEPANEKDOSI,
	VOH.IFOKEPANADROMOLOGISI,
	VOH.NOPARASTANTIK,
	VOH.COMMENTSAKIROSIS,
	VOH.IFEISPRANTIK,
	VOH.IFPARADOSIANTIK,
	VOH.IFPARALAVIANTIK,
	VOH.COMMENTSPARADANTIK,
	VOH.COMMANTSPARALANTIK,
	VOH.COMMENTSEISPRANTIK,
	VOH.DATEPARADANTIK,
	VOH.DATEPARALANTIK,
	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
	VOH.NOPARPARALANTIK,
	VOH.DATEPARAL,
	VOH.COMMENTSPARAD,
	VOH.COMMANTSPARAL,
	VOH.TIMEPARALFROM,
	VOH.TIMEPARALTO,
	VOH.TIMEPARADFROM,
	VOH.TIMEPARADTO,
	VOH.DATECANCELANTIK,
	VOH.TAXISPERCENT,
	VOH.ANAMEXODO,
	VOH.ID AS IDVOH,
	CASE 
		WHEN VOH.IFXRENTOL = 1 THEN VOH.IDENTOLEA 
		ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN VOH.IDAPOSTOLEA 
	ELSE 
	CASE 
		WHEN VOH.IFXRTRITOU = 1 THEN VOH.IDTRITOU 
		ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN VOH.IDPARALIPTI 
	ELSE VOH.IDCUSTOMER 
	END 
