create VIEW [dbo].[REPORT_COST_ASSEMBLY]
AS

SELECT 
	LS.ID,
	ls.IDYPOKATASTIMA,
	c.Eponimia,
	voh.id [IDVOH],
	RTRIM(LS.SEIRA)+LS.NOPARAST [NOPARAST],
	LS.EMPLOYEE ,
	CONVERT (DATE,LS.DATEPRINT) [DATEPRINT],
	CONVERT(NVARCHAR,LS.DATEPRINT,108) [TIME],
	LS.STATUS,   
	VOH.SYNOLO_ENTOLON,
	ISNULL(voh.assembly_cash,0) [ASSEMBLY_CASH],
	ISNULL(voh.assembly_pistosi,0) [ASSEMBLY_PISTOSI],
	ISNULL(voh.pistosi_xoris_HM,0) [PISTOSI_XORIS_HM],
	hp.CodeCatalog,
	hp.DescrCatalog,
	vp.Descr,
	VOH.POSO,
	VOH.TAXIS,
	voh.SUMPOSO,
	voh.ifDelete



FROM LISTESSYNARMOLOGISIS LS
left  join companies c on c.id = ls.idypokatastima
LEFT JOIN VOH_ANA_LISTAASS VLS ON VLS.IDLISTAS=LS.ID
LEFT JOIN (
			SELECT 
				voh.ID,
				voh.IDKINDPAYMENT,
				voh.IDLISTAS_ASS,
				VOH.IDENTOLEA,
				COUNT(voh.ID) [SYNOLO_ENTOLON],
				case kp.if_cash
					when 1 then count(voh.id) 
				end as assembly_cash,
				case kp.IF_CASH	
					when 0 then count(voh.id)
				end as assembly_pistosi,
				case 
					when kp.IF_CASH=0 and voh.identolea!=1 then count(voh.id)
				end as pistosi_xoris_HM,
				voh.poso,
				voh.TAXIS,
				voh.SUMPOSO,
				voh.ifDelete
					
			FROM VOH
			join KINDOFPAYMENTS kp on kp.ID=voh.IDKINDPAYMENT
			GROUP BY voh.ID,voh.IDKINDPAYMENT,voh.IDLISTAS_ASS,VOH.IDENTOLEA,kp.IF_CASH,
			voh.poso,voh.taxis,voh.SUMPOSO, voh.ifDelete
			) VOH ON VOH.ID=VLS.IDVOH
left join HEADERVOHPRICING hp on hp.IDVOH=voh.ID
left join VOHPRICING  vp on vp.IDVOH=voh.id

GO

---END SCRIPT 1493
------------------------------------------------------------------------------------ 

