CREATE VIEW [dbo].[EXPORT_SYNARMOLOGISI_LOGISTIKIS_IKEA] as
with souma_ana_tropo_pliromis as (
select 
	convert(date, f.dateprint) dateprint,
	f.IDPARAST,
	f.IDYPOKATASTIMA,
	f.IDKINDPAYMENT,
	sum(f.POSO) poso,
	sum(f.TAXIS) taxis,
	sum(f.sumposo) sumposo
	from VOH f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifdelete = 0
	group by convert(date, f.dateprint), f.idparast, f.idypokatastima, f.IDKINDPAYMENT
),

souma_arithmisi as (
	select 
		convert(date, f.dateprint) dateprint,
		f.IDPARAST,
		f.IDYPOKATASTIMA,
		min(cast(f.noparast as int)) noparastmin,
		max(cast(f.noparast as int)) noparastmax
	from voh f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifdelete = 0
	group by convert(date, f.dateprint), f.idparast, f.idypokatastima
),

souma_antikatavoles as (
	select
		convert(date, f.dateprint) dateprint,
		kp.CATKEPYO,
		f.IDPARAST,
		f.IDYPOKATASTIMA,
		sum(f.SUMANTIK) SUMANTIK
	from voh f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifDelete = 0
	group by convert(date, f.dateprint), kp.CATKEPYO, f.IDPARAST, f.IDYPOKATASTIMA
) 


select distinct
	convert(date, f.dateprint) [ΗΜΕΡΟΜΗΝΙΑ],-- [dateprint],
	c.id [idypokatastima],
	c.eponimia [Ypokatastima],
	ISNULL(arithmisi_lianikon.norange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΛΙΑΝΙΚΗΣ],-- [noumera lianikon],
	ISNULL(arithmisi_xondrikis.norange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΧΟΝΔΡΙΚΗΣ],--[noumera xondrikis],
	ISNULL(convert(float,posa.poso) , 0) [ΚΑΘΑΡΗ ΑΞΙΑ],-- [synolo kathara],
	ISNULL(convert(float,posa.taxis) , 0) [ΦΠΑ],--[synolo fpa],
	ISNULL(convert(float,posa.sumposo), 0)  [ΣΥΝΟΛΙΚΗ ΑΞΙΑ],--[synolo synolo],
	ISNULL(convert(float,posalianikon.sumposo) , 0) [ΠΩΛΗΣΕΙΣ ΛΙΑΝΙΚΗΣ],--[lianikes synolo],
	ISNULL(convert(float,posaxondrikis.sumposo) , 0) [ΠΩΛΗΣΕΙΣ ΧΟΟΝΔΡΙΚΗΣ],-- [xondriki	synolo],
	ISNULL(convert(float,s_poliseis_house_market.sumposo), 0) [ΠΩΛΗΣΕΙΣ HOUSE MARKET],--[poliseis house market], --kati gia sygkentrotiko timologio ?
	ISNULL(convert(float,s_pistosi_lianikis.sumposo), 0) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΛΙΑΝΙΚΗΣ],--[pistosi lianikis],
	ISNULL(convert(float,s_pistosi_xondrikis.sumposo), 0) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΧΟΝΔΡΙΚΗΣ],--[pistosi xondrikis],
	ISNULL(convert(float,s_metrita_xondrikis.sumposo), 0) [ΜΕΤΡΗΤΑ ΧΟΝΔΡΙΚΗΣ],--[metrita xondrikis],
	ISNULL(convert(float,s_metrita_lianikis.sumposo), 0) [ΜΕΤΡΗΤΑ ΛΙΑΝΙΚΗΣ],--[metrita lianikis],
	ISNULL(convert(float,s_kartes_xondrikis.sumposo), 0) [ΚΑΡΤΑ ΧΟΝΔΡΙΚΗΣ],--[kartes xondrikis],
	ISNULL(convert(float,s_kartes_lianikis.sumposo), 0) [ΚΑΡΤΑ ΛΙΑΝΙΚΗΣ],--[kartes lianikis],
	ISNULL(convert(float,s_antik_lianikis.SUMANTIK), 0) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΛΙΑΝΙΚΗΣ],--[antikatavoles lianikis],
	ISNULL(convert(float,s_antik_xondrikis.SUMANTIK), 0) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΧΟΝΔΡΙΚΗΣ],--[antikatavoles xondrikis],
	ISNULL(convert(float,s_emvasmata_lianikis.SUMPOSO), 0) [ΕΜΒΑΣΜΑ ΛΙΑΝΙΚΗΣ],--[emvasmata lianikis],
	ISNULL(convert(float,s_emvasmata_xondrikis.SUMPOSO), 0) [ΕΜΒΑΣΜΑ ΧΟΝΔΡΙΚΗΣ]--[emvasmata xondrikis]

from voh f
join COMPANIES c on c.id = f.IDYPOKATASTIMA
join KINDPARASTATIKON kp on kp.id = f.IDPARAST

left join (
	select 
		souma_arithmisi.dateprint,
		souma_arithmisi.IDYPOKATASTIMA,
		kp.SEIRA + ' ' + convert(varchar, souma_arithmisi.noparastmin) + '..' + convert(varchar, souma_arithmisi.noparastmax) norange

		from souma_arithmisi
		join KINDPARASTATIKON kp on kp.ID = souma_arithmisi.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.CATKEPYO = 1 and kp.IF_ENIMEROSIKARTELA = 1

) arithmisi_lianikon on arithmisi_lianikon.IDYPOKATASTIMA = f.IDYPOKATASTIMA and arithmisi_lianikon.dateprint = convert(date, f.dateprint)

left join (
	select 
		souma_arithmisi.dateprint,
		souma_arithmisi.IDYPOKATASTIMA,
		kp.SEIRA + ' ' + convert(varchar, souma_arithmisi.noparastmin) + '..' + convert(varchar, souma_arithmisi.noparastmax) norange

		from souma_arithmisi
		join KINDPARASTATIKON kp on kp.ID = souma_arithmisi.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.CATKEPYO = 0 and kp.IF_ENIMEROSIKARTELA = 1

) arithmisi_xondrikis on arithmisi_xondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA and arithmisi_xondrikis.dateprint = convert(date, f.dateprint)

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.poso) poso,
		sum(s.taxis) taxis,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s
	group by s.dateprint, s.IDYPOKATASTIMA
) posa on posa.dateprint = convert(date, f.dateprint) and posa.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.poso) poso,
		sum(s.taxis) taxis,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.CATKEPYO = 1 and kp.IF_ENIMEROSIKARTELA = 1
	group by s.dateprint, s.IDYPOKATASTIMA
) posalianikon on posalianikon.dateprint = convert(date, f.dateprint) and posalianikon.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.poso) poso,
		sum(s.taxis) taxis,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.CATKEPYO = 0 and kp.IF_ENIMEROSIKARTELA = 1
	group by s.dateprint, s.IDYPOKATASTIMA
) posaxondrikis on posaxondrikis.dateprint = convert(date, f.dateprint) and posaxondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		s.sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 1 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 2	
) s_pistosi_lianikis 
	on s_pistosi_lianikis.dateprint = convert(date, f.dateprint)
	and s_pistosi_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		s.sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 0 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 2	
) s_pistosi_xondrikis 
	on s_pistosi_xondrikis.dateprint = convert(date, f.dateprint)
	and s_pistosi_xondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		s.sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 0 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 1	
) s_metrita_xondrikis 
	on s_metrita_xondrikis.dateprint = convert(date, f.dateprint)
	and s_metrita_xondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		s.sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 1 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 1	
) s_metrita_lianikis 
	on s_metrita_lianikis.dateprint = convert(date, f.dateprint)
	and s_metrita_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 0 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
where s.IDKINDPAYMENT in (5, 14, 15, 16)
	group by s.dateprint, s.IDYPOKATASTIMA
) s_kartes_xondrikis 
	on s_kartes_xondrikis.dateprint = convert(date, f.dateprint)
	and s_kartes_xondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 1 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT in (5, 14, 15, 16)
	group by s.dateprint, s.IDYPOKATASTIMA
) s_kartes_lianikis 
	on s_kartes_lianikis.dateprint = convert(date, f.dateprint)
	and s_kartes_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join souma_antikatavoles s_antik_lianikis 
	on s_antik_lianikis.dateprint = convert(date, f.dateprint)
	and s_antik_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA
	and s_antik_lianikis.CATKEPYO = 1

left join souma_antikatavoles s_antik_xondrikis 
	on s_antik_lianikis.dateprint = convert(date, f.dateprint)
	and s_antik_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA
	and s_antik_lianikis.CATKEPYO = 0

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 1 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 11
	group by s.dateprint, s.IDYPOKATASTIMA
) s_emvasmata_lianikis
	on s_emvasmata_lianikis.dateprint = convert(date, f.dateprint)
	and s_emvasmata_lianikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select 
		s.dateprint,
		s.IDYPOKATASTIMA,
		sum(s.sumposo) sumposo
	from souma_ana_tropo_pliromis s 
	join KINDPARASTATIKON kp on kp.id = s.IDPARAST and kp.CATKEPYO = 0 and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where s.IDKINDPAYMENT = 11
	group by s.dateprint, s.IDYPOKATASTIMA
) s_emvasmata_xondrikis
	on s_emvasmata_xondrikis.dateprint = convert(date, f.dateprint)
	and s_emvasmata_xondrikis.IDYPOKATASTIMA = f.IDYPOKATASTIMA

left join (
	select
		f.idypokatastima,
		convert(date, f.dateprint) dateprint,
		sum(f.SUMPOSO) sumposo
	from fortotikes f
	join voh on voh.SEIRA + voh.NOPARAST = f.NOPARASTDELTIOUDIANOMIS
	join KINDPARASTATIKON kpvoh on kpvoh.id = voh.IDPARAST and kpvoh.IF_TRANSFORM = 1
	group by convert(date, f.dateprint), f.IDYPOKATASTIMA
)  s_poliseis_house_market
	on s_poliseis_house_market.dateprint = convert(date, f.dateprint)
	and s_poliseis_house_market.IDYPOKATASTIMA = f.IDYPOKATASTIMA

where f.ifdelete = 0 
GO



---END SCRIPT 1495
------------------------------------------------------------------------------------ 

