		else 'ΝΑΙ'
	end [IF_PRAKTOREIO_EPILOGHS], 											--[Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
