		ELSE 'ΟΧΙ'
	END AS IFOFEILOMENI,
	GRAMMESVOH.AXIA,
	CASE
		WHEN VOH.IFXRENTOL=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFXRENTOL,
