	VOH.YPAITIOS,
	VOH.IFEPANADROMOLOGISI,
	VOH.IFEPANEKDOSI,
	VOH.IFOKEPANADROMOLOGISI,
	VOH.NOPARASTANTIK,
	VOH.COMMENTSAKIROSIS,
	VOH.IFEISPRANTIK,
	VOH.IFPARADOSIANTIK,
	VOH.IFPARALAVIANTIK,
	VOH.COMMENTSPARADANTIK,
	VOH.COMMANTSPARALANTIK,
	VOH.COMMENTSEISPRANTIK,
	VOH.DATEPARADANTIK,
	VOH.DATEPARALANTIK,
	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
