---NEW SCRIPT 1510
ALTER VIEW [dbo].[ENTOLES_SYNARMOLOGISIS_VIEW_NEW]
AS

select 
	VOH.ID,
	voh.identolea [IDENTOLEA],
	paraliptis.id [IDPARALIPTI],
	apostoleas.id [IDAPOSTOLEA],
	kentrakostous.id [IDKENTROKOSTOUS],
	sugkentrotiko.id [IDSYGKENTROTIKO],
	voh.idparast [IDPARAST],
	VOH.IDXRHSHS,
	VOH.IDCOMPANY,
	companies.id [IDYPOKATASTIMA],
	companies.Eponimia [YPOKATASTHMA], 										--[Κατάστημα Εντολής],
	convert(date, voh.Dateprint) [DATEPRINT], 								--[Ημερομηνία Εντολής],
	month(voh.DATEPRINT) [MONTHDATE], 										--[Μήνας Εντολής],
	KPR.Code,
	voh.PARASTATIKO [PARASTATIKO], 											--[Τύπος Παραστατικού],
	voh.SEIRA [SEIRA], 														--[Σειρά Παραστατικού],
	convert(nvarchar(20),voh.NOPARAST) [NOPARAST], 												--[Αριθμός Παραστατικού],
		case ISNULL(VOH.IFCHECKED, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFCHECKED], 														--  ΑΝ ΕΛΕΓΧΘΗΚΕ
	rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE], 							--[Barcode ID Παραστατικού],
	voh.arrival [ARRIVAL], 													--[Αριθμός Άφιξης],
	voh.aranaforas [ARANAFORAS], 											--[Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK], 									--[Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR, 													--[Τρόπος Πληρωμής],
	cast(voh.SUMPOSO as float) [SUMPOSO], 									--[Αξία Παραστατικού (Συνολική)],
	cast(voh.poso as float) [POSO], 										--[Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [TAXIS], 										--[Αξία Παραστατικού (ΦΠΑ)],
	
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_DISCOUNT_ALL], 													--[Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [IF_DISCOUNT_SERVICE], 												--[Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [KENTRO_KOSTOUS], 									--[Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [AXIA_EMPOREUMATON], 								--[Αξία Εμπορευμάτων Παραστατικού],
	null [RESERVATION_DATE], 												--[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [RESERVATION_SLOT],												--[SLOT Υπηρεσίας Σύμφωνα με Reservation],
	LISTESSYNARMOLOGISIS.DATEPRINT	[DATE_LISTAS_ASS],						--[Ημερ. Λίστας Ανάθεσης],
	listessynarmologisis.PARASTATIKO [PARASTATIKO_ASS],						--[Παραστατικό Ανάθεσης],
	listessynarmologisis.EMPLOYEE [SYNERGATIS],								--[Συνεργάτης],
	listessynarmologisis.STATUS [STATUS_LISTAS_ASS],						--[Κατάσταση Λίστας Ανάθεσης], 												
	KAA.DATEPRINT [KAA_DATE], 												--[Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [KAA_MONTH], 										--[Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [KAA_TRUCK], 													--[Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [KAA_DRIVER] , 												--[Οδηγός Διπλότυπης Καταστήματος],
	LISTESDIANOMIS.DATEPRINT [LISTADIANOMIS_DATE], 							--[Ημερομηνία Διπλότυπης Κέντρου Διανομής],
	MONTH(LISTESDIANOMIS.DATEPRINT) [LISTADIANOMIS_MONTH], 					--[Μήνας Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.OXIMA [LISTADIANOMIS_TRUCK], 							--[Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DRIVER [LISTADIANOMIS_DRIVER], 							--[Οδηγός Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.STATUS [LISTADIANOMIS_STATUS], 							--[Status Διπλότυπης Κέντρου Διανομής],
	cast(grammesvohsum.temaxia as float) AS [TEMAXIA], 							--[Σύνολο Τεμαχίων],
	grammesvohsum.countid [POSOTHTA], 										--[Σύνολο κωδικών εμπορευμάτων],
	cast(grammesvohsum.baros as float) [BAROS], 							--[Συνολικό Βάρος],
	cast(grammesvohsum.kybika as float) [KYBIKA], 							--[Συνολικός Όγκος],
	voh.COMMENTS [COMMENTS], 												--[Σχόλια - Παρατηρήσεις],
	paraliptis.Eponimia [PARALISPTISDESCR], 								--[Επωνυμία Παραλήπτη],
	paraliptis.AddressTK [PARALIPTIS_ZIPCODE], 								--[ΤΚ Παραλήπτη],
	NULL  [PARALIPTIS_ZONE], 												--[Ζώνη ΤΚ Παραλήπτη],
	paraliptis.AddressCity [PARALIPTIS_CITY], 								--[Περιοχή Παραλήπτη],
	paraliptis.AddressPref [PARALIPTIS_NOMOS], 								--[Νομός Παραλήπτη],
	paraliptis.AddressStr [PARALIPTIS_ADDRESS], 							--[Διεύθυνση Παραλήπτη],
	paraliptis.Mobile [PARALIPTIS_MOBILE], 									--[Κινητό Τηλέφωνο Παραλήπτη],
	paraliptis.Tel [PARALIPTIS_TELEPHONE], 									--[1ο Τηλέφωνο Παραλήπτη],
	voh.OROFOS [OROFOS], 	
	VOH.AFMENTOLEA,															--[Όροφος Παράδοσης Παραλήπτη],
	voh.ENTOLEASDESCR,			 											--[Επωνυμία Εντολέα],
	apostoleas.Eponimia [APOSTOLEASDESCR],									--[Επωνυμία Αποστολέα],
	apostoleas.AddressTK [APOSTOLEAS_ZIPCODE], 								--[ΤΚ Αποστολέα],
	NULL [APOSTOLEAS_ZONE], 												--[Ζώνη ΤΚ Αποστολέα],
	apostoleas.AddressCity [APOSTOLEAS_CITY], 								--[Περιοχή Αποστολέα],
	apostoleas.AddressPref [APOSTOLEAS_NOMOS], 								--[Νομός Αποστολέα],
	apostoleas.addressstr [APOSTOLEAS_ADDRESS], 							--[Διεύθυνση Αποστολέα],
	apostoleas.Mobile [APOSTOLEAS_MOBILE], 									--[Κινητό Τηλέφωνο Αποστολέα],
	apostoleas.Tel [APOSTOLEAS_TELEPHONE], 									--[1ο Τηλέφωνο Αποστολέα],
	headervohpricing.DescrCatalog [TIMOKATALOGOS], 							--[Τιμοκατάλογος Παραστατικού],
	rtrim(listessynarmologisis.seira)+ listessynarmologisis.NOPARAST [NOPARAST_LISTAS_ASS], --[Αρ.Λίστας Ανάθεσης],
	RTRIM(LTRIM(KAA.SEIRA)) + KAA.NOPARAST [NOPARASTDELTIOUAPOSTOLIS],			--[Αρ. Διπλότυπης Καταστήματος], KAA
	RTRIM(LTRIM(LISTESDIANOMIS.SEIRA)) + LISTESDIANOMIS.NOPARAST [NOPARASTDELTIOUDIANOMIS], 						--[Αρ. Διπλότυπης Κέντρου Διανομής], LISTA DIANOMIS
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_PRAKTOREIO_EPILOGHS], 											--[Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_XREOSI_DELATOLAS], 												--[Δελατόλας Καταβάλλων τα Κόμιστρα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN ''
		else paradoseis.Eponimia
	end [PRAKTOREIO_EPILOGHS], 												--[Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
	voh.PRAKTOREIODESCR [PRAKTOREIODESCR], 									--[Πρακτορείο Συνεργάτης],
	case ISNULL(VOH.IF_CLOSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IF_CLOSE_ALREADY], 												--[Τιμολογημένη κατα την έκδοση],
	case ISNULL(VOH.IFREVERSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFREVERSE], 														-- ΑΝ ΕΙΝΑΙ ΕΠΙΣΤΡΟΦΗ
	voh.UserCreate [USERCREATE], 											--[Χρήστης εκδόσας την Εντολή],
	voh.UserMod [USEMOD], 													--[Χρήστης μεταβολής Εντολής],
	-- syndedemeno pistwtiko parastatiko ?
	NULL [ID_PISTOTIKO], 													--[Συνδεδεμένο Πιστωτικό Παραστατικό],
	NULL [PISTOTIKODESCR], 													--[Είδος Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_DATE], 													--[Ημερομηνία Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_MONTH], 												--[Μήνας Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_SEIRA], 												--[Σειρά Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_NO], 													--[Αρ. Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_BARCODE], 												--[Barcode ID Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_SUMPOSO], 												--[Αξία Πιστωτικού Παραστατικού (Συνολική)],
	NULL [PISTOTIKO_KATHARO],												--[Αξία Πιστωτικού Παραστατικού (Καθαρή)],
	NULL [PISTOTIKO_FPA], 													--[Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
	NULL [PISTOTIKO_USERCREATE], 											--[Εκδόσας Πιστωτικού],
	case isnull(kpr.IF_TRANSFORM, 0)
		when 0 then 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_TRANSFORM_INFORM], 												--[Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο], 
	case 
		when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_TRANSFORMED], 													--[Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
	sugkentrotiko.DATEPRINT [SYGKENTROTIKO_DATE], 							--[Ημερομηνία Τιμολόγησης],
	month(sugkentrotiko.DATEPRINT) [SYGKENTROTIKO_MONTH], 					--[Μήνας Τιμολόγησης],
	sugkentrotiko.seira [SYGKENTROTIKO_SEIRA], 								--[Σειρά Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.NOPARAST [SYGKENTROTIKO_NOPARAST], 						--[Αρ. Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.EXT_BARCODE [SYGKENTROTIKO_EXT_BARCODE],					--[Barcode ID Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.SUMPOSO [SYGKENTROTIKO_SUMPOSO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
	sugkentrotiko.poso [SYGKENTROTIKO_KATHARO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
	sugkentrotiko.taxis [SYGKENTROTIKO_FPA], 								--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
	sugkentrotiko.UserCreate [SYGKENTROTIKO_USERCREATE], 					--[Εκδόσας Τιμολογίου],
	null [SYGKENTROTIKO_PISTOTIKOID], 										--[Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]
	VOH.IF_CLOSE,
	kpr.IF_ORDER,
	KPR.KindKINISIS,
	kpr.IF_EDMETAFORAS,
	kpr.IF_EDSYNARMOL,
	kpr.IF_ENDILMETAFORAS,
	kpr.IF_EDTOPOTH,
	VOH.NO_EXT_ORDER,
	VOH.NOPARASTLISTASSYNARMOLOGISIS,
	COMPANIES.AddressStr [ADDRESS_YPOKATASTHMA],
	COMPANIES.AddressTK [TK_YPOKATASTHMA],
	COMPANIES.AddressCity [CITY_YPOKATASTHMA],
	COMPANIES.BARCODE_Prefix [BARCODEPREFIX_YPOKAT],
	COMPANIES.EMAIL [EMAIL_YPOKATASTHMA],
	DBO.GetVOHEAFDSS(VOH.ID, 1) AS EAFDSS,
	VOH.CustDescr,
	VOH.EPAGELMA,
	VOH.AFM,
	VOH.CITY,
	VOH.TEL,
	VOH.MOBILE,
	VOH.OXIMA,
	VOH.OMADPROORISMOS,
	CASE 
	WHEN VOH.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN 'ΑΠΟΣΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
	ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
	ELSE 'ΑΓΝΩΣΤΟ' 
	END 
	END
	END 
	END AS XREOΥMENOS,
	GRAMMESVOH.TIMDA,
	CASE 
		WHEN VOH.IFPREPAY=1 THEN 1 ELSE 0
	END AS XREOSIPROPLIROMENES,		
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 1 ELSE 0
	END AS XREOSIOFEILOMENES,
	GRAMMESVOH.PERIEXOMENO,
	VOH.PERIOXIFORTOSIS,
	VOH.PERIOXIPARADOSIS,
	VOH.SUMANTIK,
	VOH.STATUS,
	VOH.DATEPARAD,
	VOH.IDPRAKTOREIO,
	VOH.ANTIKCASH,
	VOH.ANTIKEPIT,
	VOH.ANTIKSYNAL,
	VOH.ANTIKOTHER,
	VOH.IFCANCELANTIK,
	VOH.COMMENTSANTIK,
	VOH.DATEPARADOSI,
	VOH.COMMENTS2,
	VOH.IDEMPLOYEE,
	VOH.EMPLOYEE,
	voh.SERVICEZONE,
	CASE	
		WHEN VOH.IFPREPAY= 1 THEN 'ΝΑΙ' 
		ELSE 'ΟΧΙ'
	END AS IFPREPAY,
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFOFEILOMENI,
	GRAMMESVOH.AXIA,
	CASE
		WHEN VOH.IFXRENTOL=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFXRENTOL,
	VOH.IDKINDPAYMENT,
	CASE VOH.IFXRAPOST 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRAPOST,
	CASE VOH.IFXRPARAL 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRPARAL,
	CASE VOH.IFXRTRITOU 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRTRITOU,
	VOH.IFANTIKCASH,
	--VOH.ANTIKEPIT,
	--VOH.ANTIKSYNAL,
	--VOH.ANTIKOTHER,
	VOH.ifDelete,
	VOH.IFCANCEL,
	VOH.DATECANCEL,
	VOH.IFPARADOSI,
	VOH.AITIOLOGIAPARASTATIKOU,
	VOH.DATEFORTOSIS,
	VOH.IFEPISTROFI,
	VOH.DATEEPISTROFIS,
	VOH.AITIOLOGIAEPISTROFIS,
	VOH.COMMENTSEPISTROFIS,
	VOH.IFCASH,
	VOH.IFPISTOSI,
	VOH.STATUSDESCR,
	VOH.YPAITIOS,
	VOH.IFEPANADROMOLOGISI,
	VOH.IFEPANEKDOSI,
	VOH.IFOKEPANADROMOLOGISI,
	VOH.NOPARASTANTIK,
	VOH.COMMENTSAKIROSIS,
	VOH.IFEISPRANTIK,
	VOH.IFPARADOSIANTIK,
	VOH.IFPARALAVIANTIK,
	VOH.COMMENTSPARADANTIK,
	VOH.COMMANTSPARALANTIK,
	VOH.COMMENTSEISPRANTIK,
	VOH.DATEPARADANTIK,
	VOH.DATEPARALANTIK,
	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
	VOH.NOPARPARALANTIK,
	VOH.DATEPARAL,
	VOH.COMMENTSPARAD,
	VOH.COMMANTSPARAL,
	VOH.TIMEPARALFROM,
	VOH.TIMEPARALTO,
	VOH.TIMEPARADFROM,
	VOH.TIMEPARADTO,
	VOH.DATECANCELANTIK,
	VOH.TAXISPERCENT,
	VOH.ANAMEXODO,
	VOH.ID AS IDVOH,
	CASE 
		WHEN VOH.IFXRENTOL = 1 THEN VOH.IDENTOLEA 
		ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN VOH.IDAPOSTOLEA 
	ELSE 
	CASE 
		WHEN VOH.IFXRTRITOU = 1 THEN VOH.IDTRITOU 
		ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN VOH.IDPARALIPTI 
	ELSE VOH.IDCUSTOMER 
	END 
	END
	END 
	END AS IDXREOUMENOU,
	VOH.AFMXREOUMENOU,
	HEADERVOH.ASFALISTRA,
	HEADERVOH.TAXISXREOSEON,
	HEADERVOH.SUMPOSOXRVOH,
	--VOH.OROFOS,
	VOH.OROFOSDESCR,
	VOH.KOUDOUNI,
	VOH.POSOEPIVAR,
	VOH.TAXISEPIVAR,
	VOH.SUMPOSOEPIVAR,
	(VOH.POSO + VOH.POSOEPIVAR) AS SUMKATHARO,
	(VOH.TAXIS + VOH.TAXISEPIVAR) AS SUMTAXIS, 
    (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) AS SUMSUMPOSO,
    HEADERVOH.KATHARO,
    VOH.THETIME,
    VOH.IDENTOLEA AS CUSTOMERID,
    VOH.ENTOLEASDESCR AS CUSTOMERDESCR,
    VOH.IDAPOSTOLEA AS IDSYNAL, 
    VOH.APOSTOLEASDESCR AS SYNALDESCR,
	VOH.IDCUSTOMER,
	VOH.DOY, 
    VOH.ADDRESSSTREET,
    VOH.ADDRESSNO, 
    VOH.PREF, 
    VOH.AFMAPOSTOLEA,
    VOH.IfTransport,
	VOH.IfAssembly,
	VOH.IfDisAssembly,
	VOH.IfPlacement,  
	VOH.SUMPALETES,
	VOH.SUMDEMATA,
	VOH.SUMSTAND,
	VOH.SUMOGOS,
	VOH.SUMPOSO-VOH.DISCOUNT [TELTIMI],
    APOSTOLEAS.Epagelma AS SYNALEPAGELMA, 
    APOSTOLEAS.AddressStr AS SYNALADDRSTR,
    APOSTOLEAS.AddressNo AS SYNALADDRNO, 
    APOSTOLEAS.AddressTK AS SYNALADDRTK, 
    APOSTOLEAS.AddressCity AS SYNALCITY,
    VOH.IDXREOUMENOUENTOLIS,
    APOSTOLEAS.AddressCountry AS SYNALADDRCOUNTRY, 
    APOSTOLEAS.Tel AS SYNALTEL, 
    APOSTOLEAS.DOY AS SYNALDOY, 
    APOSTOLEAS.AFM AS AFMSYNAL,--SYNALAFM,
    CUSTOMERS.AddressTK AS CUSTADDRTK, 
    CUSTOMERS.AddressNo AS CUSTADDRNO, 
    CUSTOMERS.AddressStr AS CUSTADDRSTR,
    VOH.IF_ANTIKCASHSYNAR,
    VOH.ANTIKCASHSYNAR,
    CUSTOMERS.AddressCity AS CUSTADDRCITY, 
    CUSTOMERS.AFM AS AFMCUSTOMER, --CUSTAFM, 
    CUSTOMERS.DOY AS CUSTDOY,
    paraliptis.AFM AS AFMPARALIPTI, --PARALAFM, 
    paraliptis.Epagelma AS PARALEPAGELMA, 
    paraliptis.AddressStr AS PARALADDRSTR,
    grammesvohsum.baros as SUMBAROS,
    paraliptis.AddressNo AS PARALADDRNO, 
    paraliptis.AddressTK AS PARALADDRTK, 
    paraliptis.AddressCity AS PARALCITY,
    EMPLOYEE.AFM AS AFMEMPLOYEE, --EMPLAFM, 
    EMPLOYEE.DOY AS EMPLDOY, 
    EMPLOYEE.Epagelma AS EMPLLEPAGELMA, 
    EMPLOYEE.AddressStr AS EMPLADDRSTR,
    EMPLOYEE.AddressNo AS EMPLADDRNO, 
    EMPLOYEE.AddressTK AS EMPLADDRTK, 
    EMPLOYEE.AddressCity AS EMPLLCITY,
    kpr.IF_TRANSFORM

from voh
left join SYNARMOLOGISI_DIANOMI sd on sd.vohsynarmid = voh.id
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
JOIN ACCOUNTS CUSTOMERS ON CUSTOMERS.ID=VOH.IDCUSTOMER
LEFT JOIN EMPLOYEE ON EMPLOYEE.id=VOH.IDEMPLOYEE
join (
	select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
join (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		SUM(TEMAXIA) countid,
		sum(BAROS) baros,
		sum(KYBIKA) kybika
	from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
JOIN (SELECT
		IDVOH,
		SUM(SUMPOSO) AS AXIA,
		MIN(TIMDA) AS TIMDA,
		MIN(PERIEXOMENO) AS PERIEXOMENO
	  FROM GRAMMESVOH
	  GROUP BY IDVOH
	  )GRAMMESVOH ON GRAMMESVOH.IDVOH=VOH.ID 
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.id = sd.fortid
left join voh sugkentrotiko on sugkentrotiko.SEIRA + convert(nvarchar(20),sugkentrotiko.NOPARAST) = fortotikes.NOPARASTDELTIOUDIANOMIS
left join KAA on KAA.ID = sd.idkaa
join KINDPARASTATIKON kpr on kpr.id=voh.IDPARAST and kpr.IF_EDSYNARMOL=1
left join LISTESDIANOMIS on LISTESDIANOMIS.id = sd.idlistas
LEFT JOIN(
		SELECT 
		IDVOH,
		SUM(KOMISTRA) AS KOMISTRA,
		SUM(XREOSISTRITON) AS XREOSISTRITON,
		SUM(DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORT,
		SUM(OTHERXREOSIS) AS OTHERXREOSIS,
		SUM(ASFALISTRA) AS ASFALISTRA,
		SUM(TAXIS) AS TAXISXREOSEON,
		SUM(SUMPOSOXRVOH) AS SUMPOSOXRVOH,
		SUM(KATHARO) AS KATHARO
		FROM HEADERVOH
		GROUP BY IDVOH
		)HEADERVOH ON HEADERVOH.IDVOH=VOH.ID

left join 
	(select			
		idvoh,
		max(idlistas) as idlistas
	from VOH_ANA_LISTAASS
	group by IDVOH) voh_ana_listaass_max on voh_ana_listaass_max.IDVOH=voh.ID
--left join voh_ana_listaass on voh_ana_listaass.idvoh=voh_ana_listaass_max.IDVOH
left join LISTESSYNARMOLOGISIS on LISTESSYNARMOLOGISIS.id=voh_ana_listaass_max.idlistas

--where  voh.ifDelete = 0 





GO




---END SCRIPT 1510
------------------------------------------------------------------------------------

---NEW SCRIPT 1511

ALTER VIEW [dbo].[FORTOTIKESLIGHT_VIEW]
AS

SELECT     TOP (100) PERCENT dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, 
                      CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.OXIMA, 
                      dbo.FORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
                       ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, dbo.ACCOUNTS.Eponimia AS APOSTOLEASDESCR, ACCOUNTS_1.Eponimia AS PARALISPTISDESCR, 
                      ACCOUNTS_2.Eponimia AS ENTOLEASDESCR, dbo.FORTOTIKES.ANTAPOKRITISDESCR, dbo.FORTOTIKES.NOLISTASDIANOMIS, ACCOUNTS_3.Eponimia AS TRITOSDESCR, 
                      HEADERVOHPRICING.DESCRCATALOG AS TIMOKATALOGOS,
					  MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA, dbo.FORTOTIKES.POSO, ROUND(MIN(dbo.FORTOTIKES.TAXIS), 2) AS TAXISXREOSEON, ROUND(MIN(dbo.FORTOTIKES.SUMPOSO), 2) 
                      AS SUMPOSOXRFORT, dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS), 0) 
                      AS BAROS, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA), 0) AS KYBIKA, MIN(dbo.Units.UntName) AS SYSKEVASIA, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI WHEN 1 THEN SUM(FORTOTIKES.SUMPOSO) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO, dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, dbo.FORTOTIKES.COMMENTS, 
                      dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUS, dbo.FORTOTIKES.DATEPARAD, dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.IDPARALIPTI, 
                      dbo.FORTOTIKES.IDENTOLEA, dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.IDPRAKTOREIO, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
                      CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.COMMENTS2, 
                      dbo.FORTOTIKES.EXODATRITON AS XREOSISTRITON, CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, dbo.FORTOTIKES.NO_EXT_ORDER, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, ISNULL(MIN(dbo.GRAMMESFORTTIKIS.SUMPOSO), 0) AS AXIA, 
                      CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, 
                      CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, 
                      CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, 
                      dbo.FORTOTIKES.IFANTIKOTHER, dbo.FORTOTIKES.ifDelete, dbo.FORTOTIKES.IFCANCEL, dbo.FORTOTIKES.DATECANCEL, dbo.FORTOTIKES.DROMOLOGIO, dbo.FORTOTIKES.THESI, 
                      dbo.FORTOTIKES.IFPARADOSI, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, CONVERT(varchar, dbo.FORTOTIKES.DATEFORTOSIS, 102) AS DATEFORTOSIS, dbo.FORTOTIKES.IFEPISTROFI, 
                      dbo.FORTOTIKES.DATEEPISTROFIS, dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, dbo.FORTOTIKES.IFPISTOSI, 
                      dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, dbo.FORTOTIKES.IFEPANEKDOSI, dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, 
                      dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.IFPARADOSIANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK, 
                      dbo.FORTOTIKES.COMMENTSPARADANTIK, dbo.FORTOTIKES.COMMANTSPARALANTIK, dbo.FORTOTIKES.COMMENTSEISPRANTIK, CONVERT(varchar, dbo.FORTOTIKES.DATEPARADANTIK, 102) 
                      AS DATEPARADANTIK, CONVERT(varchar, dbo.FORTOTIKES.DATEPARALANTIK, 102) AS DATEPARALANTIK, CONVERT(varchar, dbo.FORTOTIKES.DATEEISPRANTIK, 102) AS DATEEISPRANTIK, 
                      dbo.FORTOTIKES.EISPRAXASANTIK, dbo.FORTOTIKES.NOPARPARADANTIK, dbo.FORTOTIKES.NOPARASTEISPRANTIK, dbo.FORTOTIKES.NOPARPARALANTIK, dbo.FORTOTIKES.DATEPARAL, 
                      dbo.FORTOTIKES.COMMENTSPARAD, dbo.FORTOTIKES.COMMANTSPARAL, dbo.FORTOTIKES.TIMEPARALFROM, dbo.FORTOTIKES.TIMEPARALTO, dbo.FORTOTIKES.TIMEPARADFROM, 
                      dbo.FORTOTIKES.TIMEPARADTO, CONVERT(varchar, dbo.FORTOTIKES.DATECANCELANTIK, 102) AS DATECANCELANTIK, dbo.FORTOTIKES.IDPARAST, dbo.FORTOTIKES.TAXISPERCENT, 
                      dbo.FORTOTIKES.ANAMEXODO, dbo.FORTOTIKES.ID AS IDFORTOTIKIS, dbo.FORTOTIKES.AFMXREOUMENOU, ROUND(MIN(dbo.FORTOTIKES.POSO), 2) AS KATHARO, 
                      dbo.ACCOUNTS.Epagelma AS EPAGAPOST, dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, dbo.ACCOUNTS.AddressTK AS TKAPOST, 
                      dbo.ACCOUNTS.AddressCity AS CITYAPOST, dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, dbo.ACCOUNTS.Tel AS TELAPOST, dbo.ACCOUNTS.DOY AS DOYAPOST, 
                      ACCOUNTS_1.Epagelma AS EPAGPARAL, ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, ACCOUNTS_1.AddressNo AS ADDRNOPARAL, ACCOUNTS_1.AddressTK AS ADDRTKPARAL, 
                      ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, ACCOUNTS_1.Tel AS TELPARAL, ACCOUNTS_1.DOY AS DOYPARAL, 
                      ACCOUNTS_2.Epagelma AS EPAGENTOL, ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, ACCOUNTS_2.AddressNo AS ADDRNOENTOL, ACCOUNTS_2.AddressTK AS ADDRTKENTOL, 
                      ACCOUNTS_2.AddressCity AS ADDRCITYENTOL, ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL, ACCOUNTS_2.Tel AS TELENTOL, ACCOUNTS_2.DOY AS DOYENTOL, 
                      ACCOUNTS_3.Epagelma AS EPAGTR, ACCOUNTS_3.AddressStr AS ADDRSTTR, ACCOUNTS_3.AddressNo AS ADDRNOTR, ACCOUNTS_3.AddressTK AS ADDRTKTR, 
                      ACCOUNTS_3.AddressCity AS ADDRCITYTR, ACCOUNTS_3.AddressPref AS ADSTRDRNOMO, ACCOUNTS_3.Tel AS TELTR, ACCOUNTS_3.DOY AS DOYTR, dbo.FORTOTIKES.AFMAPOSTOLEA, 
                      dbo.FORTOTIKES.AFMENTOLEA, dbo.FORTOTIKES.IF_TRANSFTOESEX, dbo.FORTOTIKES.AFMPARALIPTI, dbo.FORTOTIKES.AFMTRITOU, dbo.FORTOTIKES.AFMANTAPOKRITI, 
                      dbo.FORTOTIKES.IFPARADOSITOPEL, dbo.FORTOTIKES.IFPARALABIFROMPEL, dbo.FORTOTIKES.IDXRHSHS, dbo.FORTOTIKES.IDCOMPANY, dbo.FORTOTIKES.IFEXOFLISI, 
                      dbo.FORTOTIKES.IDYPOKATASTIMA, dbo.FORTOTIKES.UserMod, dbo.FORTOTIKES.DateMod, dbo.FORTOTIKES.CONTAINER, dbo.FORTOTIKES.BOAT, dbo.FORTOTIKES.POD_ADDED, 
					  FORTOTIKES.IDKENTROUKOSTOUS, FORTOTIKES.NO_EXT_ORDER_IK, FORTOTIKES.IDENTOLIS, FORTOTIKES.IF_CANCEL, FORTOTIKES.ID_CANCELLATION, 
					  FORTOTIKES.SEIRA_CANCELLATION, FORTOTIKES.NOPARAST_CANCELLATION, FORTOTIKES.DETAILS_CANCELLATION,FORTOTIKES.CANCELDATE, FORTOTIKES.EXT_BARCODE, 
                      dbo.FORTOTIKES.POD_PATH, dbo.FORTOTIKES.POD_USER, dbo.FORTOTIKES.POD_PATH_2, dbo.FORTOTIKES.UserCreate, dbo.FORTOTIKES.DateCreate, FORTOTIKES.IF_FROM_ANTAP, 
                      FORTOTIKES.IF_TO_ANTAP
FROM         dbo.FORTOTIKES WITH (NOLOCK) 
					  LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) ON dbo.FORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON dbo.FORTOTIKES.IDENTOLEA = ACCOUNTS_2.id 
					  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON dbo.FORTOTIKES.IDTRITOU = ACCOUNTS_3.id 
					  LEFT OUTER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID 
					  LEFT OUTER JOIN dbo.PARASTATIKA_ANA_KATHGORIA ON dbo.PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID 
					  INNER JOIN dbo.CAT_PARASTATIKON ON dbo.CAT_PARASTATIKON.ID = dbo.PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND dbo.CAT_PARASTATIKON.If_EXODO = 0 
					  LEFT OUTER JOIN dbo.GRAMMESFORTTIKIS WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.IDVOH = dbo.FORTOTIKES.ID 
					  LEFT OUTER JOIN dbo.Units WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.SYSKEVASIA = dbo.Units.UntID
					  LEFT OUTER JOIN dbo.HEADERVOHPRICING WITH (NOLOCK) ON dbo.HEADERVOHPRICING.IDVOH=dbo.FORTOTIKES.IDENTOLIS
					 
