                      dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, 
                      dbo.FORTOTIKES.IFXRTRITOU, dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, dbo.FORTOTIKES.ifDelete, 
                      dbo.FORTOTIKES.IFCANCEL, dbo.FORTOTIKES.DATECANCEL, dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.IFXRTRITOU, 
                      dbo.FORTOTIKES.ANAMEXODO, dbo.FORTOTIKES.IFPARADOSI, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, dbo.FORTOTIKES.DATEFORTOSIS, dbo.FORTOTIKES.IFEPISTROFI, 
                      dbo.FORTOTIKES.DATEEPISTROFIS, dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, dbo.FORTOTIKES.IFPISTOSI, 
                      dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, dbo.FORTOTIKES.IFEPANEKDOSI, dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, 
                      dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.IFPARADOSIANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK, 
                      dbo.FORTOTIKES.COMMENTSPARADANTIK, dbo.FORTOTIKES.COMMANTSPARALANTIK, dbo.FORTOTIKES.COMMENTSEISPRANTIK, dbo.FORTOTIKES.DATEPARADANTIK, 
                      dbo.FORTOTIKES.DATEPARALANTIK, dbo.FORTOTIKES.DATEEISPRANTIK, dbo.FORTOTIKES.EISPRAXASANTIK, dbo.FORTOTIKES.NOPARPARADANTIK, dbo.FORTOTIKES.NOPARASTEISPRANTIK, 
                      dbo.FORTOTIKES.NOPARPARALANTIK, dbo.FORTOTIKES.DATEPARAL, dbo.FORTOTIKES.DATEPARAD, dbo.FORTOTIKES.COMMENTSPARAD, dbo.FORTOTIKES.COMMANTSPARAL, 
                      dbo.FORTOTIKES.TIMEPARALFROM, dbo.FORTOTIKES.TIMEPARALTO, dbo.FORTOTIKES.TIMEPARADFROM, dbo.FORTOTIKES.TIMEPARADTO, dbo.FORTOTIKES.ANTIKCASH, 
                      dbo.FORTOTIKES.ANTIKEPIT, dbo.FORTOTIKES.ANTIKSYNAL, dbo.FORTOTIKES.ANTIKOTHER, dbo.FORTOTIKES.IFCANCELANTIK, dbo.FORTOTIKES.DATECANCELANTIK, 
                      dbo.FORTOTIKES.TAXISPERCENT, dbo.FORTOTIKES.IDPARAST, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.AFMXREOUMENOU, dbo.FORTOTIKES.CONTAINER, dbo.FORTOTIKES.BOAT, 
                      dbo.FORTOTIKES.IF_TRANSFTOESEX, dbo.ACCOUNTS.Epagelma, dbo.ACCOUNTS.AddressStr, dbo.ACCOUNTS.AddressNo, dbo.FORTOTIKES.IFEXOFLISI, dbo.FORTOTIKES.NO_EXT_ORDER, 
                      dbo.ACCOUNTS.AddressTK, dbo.ACCOUNTS.AddressCity, dbo.ACCOUNTS.AddressPref, dbo.ACCOUNTS.Tel, dbo.ACCOUNTS.DOY, ACCOUNTS_1.Epagelma, ACCOUNTS_1.AddressStr, 
                      ACCOUNTS_1.AddressNo, ACCOUNTS_1.AddressTK, ACCOUNTS_1.AddressCity, ACCOUNTS_1.AddressPref, ACCOUNTS_1.Tel, ACCOUNTS_1.DOY, ACCOUNTS_2.Epagelma, 
                      ACCOUNTS_2.AddressStr, ACCOUNTS_2.AddressNo, ACCOUNTS_2.AddressTK, ACCOUNTS_2.AddressCity, ACCOUNTS_2.AddressPref, ACCOUNTS_2.Tel, ACCOUNTS_2.DOY, 
