                      dbo.FORTOTIKES.UserMod, dbo.FORTOTIKES.DateMod, dbo.FORTOTIKES.UserCreate, dbo.FORTOTIKES.DateCreate, dbo.FORTOTIKES.DROMOLOGIO, dbo.FORTOTIKES.THESI, FORTOTIKES.IF_FROM_ANTAP, 
                      FORTOTIKES.IF_TO_ANTAP


