                      dbo.FORTOTIKES.ANTIKOTHER, dbo.FORTOTIKES.IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.STATUS, dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.PERIOXIFORTOSIS, 
                      dbo.FORTOTIKES.PERIOXIPARADOSIS, dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.COMMENTS2, dbo.FORTOTIKES.OMADPROORISMOS, 
                      dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, dbo.FORTOTIKES.IFXRAPOST, 
                      dbo.FORTOTIKES.IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, dbo.FORTOTIKES.IFXRTRITOU, dbo.FORTOTIKES.IFANTIKCASH, 
                      dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, dbo.FORTOTIKES.ifDelete, 
