	apostoleas.addressstr [Διεύθυνση Αποστολέα],
	apostoleas.Mobile [Κινητό Τηλέφωνο Αποστολέα],
	apostoleas.Tel [1ο Τηλέφωνο Αποστολέα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΟΧΙ'
		else 'ΝΑΙ'
	end [Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [Δελατόλας Καταβάλλων τα Κόμιστρα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN ''
		else paradoseis.Eponimia
	end [Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
	voh.PRAKTOREIODESCR [Πρακτορείο Συνεργάτης],
	case ISNULL(VOH.IF_CLOSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [Τιμολογημένη κατα την έκδοση],
	voh.UserCreate [Χρήστης εκδόσας την Εντολή],
	voh.UserMod [Χρήστης μεταβολής Εντολής],
	-- syndedemeno pistwtiko parastatiko ?
	NULL [Συνδεδεμένο Πιστωτικό Παραστατικό],
	NULL [Είδος Πιστωτικού Παραστατικού],
	NULL [Ημερομηνία Πιστωτικού Παρσταατικού],
	NULL [Μήνας Πιστωτικού Παρσταατικού],
	NULL [Σειρά Πιστωτικού Παραστατικού],
	NULL [Αρ. Πιστωτικού Παραστατικού],
	NULL [Barcode ID Πιστωτικού Παραστατικού],
	NULL [Αξία Πιστωτικού Παραστατικού (Συνολική)],
	NULL [Αξία Πιστωτικού Παραστατικού (Καθαρή)],
	NULL [Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
	NULL [Εκδόσας Πιστωτικού],
	case isnull(kindparastatikon.IF_TRANSFORM, 0)
		when 0 then 'ΟΧΙ'
		else 'ΝΑΙ'
	end [Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο], 
	case 
		when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
	sugkentrotiko.DATEPRINT [Ημερομηνία Τιμολόγησης],
	month(sugkentrotiko.DATEPRINT) [Μήνας Τιμολόγησης],
	sugkentrotiko.seira [Σειρά Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.NOPARAST [Αρ. Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.EXT_BARCODE [Barcode ID Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.SUMPOSO [Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
	sugkentrotiko.poso [Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
	sugkentrotiko.taxis [Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
	sugkentrotiko.UserCreate [Εκδόσας Τιμολογίου],
	null [Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]

from voh
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
join (
	select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
left join (
	select 
		idvoh, 
		ISNULL(sum(timitem), 0) timitem, 
		ISNULL(sum(PCS), 0) temaxia, 
		ISNULL(SUM(TEMAXIA), 0) countid,
		ISNULL(sum(BAROS), 0) baros,
		ISNULL(sum(KYBIKA), 0) kybika
	from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.IDENTOLIS = voh.id
left join voh sugkentrotiko on sugkentrotiko.SEIRA + sugkentrotiko.NOPARAST = fortotikes.NOPARASTDELTIOUDIANOMIS
left join KINDPARASTATIKON on KINDPARASTATIKON.id = fortotikes.IDPARAST
join KINDPARASTATIKON KINDPARASTATIKON_VOH on KINDPARASTATIKON_VOH.ID = VOH.IDPARAST AND KINDPARASTATIKON_VOH.IF_EDSYNARMOL = 1
left join (
	SELECT IDFORTOTIKIS, MAX(IDKAA) IDKAA FROM FORTOTIKES_ANA_KAA GROUP BY IDFORTOTIKIS
) FAK on FAK.IDFORTOTIKIS = FORTOTIKES.ID
left join KAA on KAA.ID = FAK.IDKAA
--left join FORTOTIKES_ANA_LISTA on FORTOTIKES_ANA_LISTA.IDFORTOTIKIS = FORTOTIKES.ID
--left join LISTESDIANOMIS on LISTESDIANOMIS.id = FORTOTIKES_ANA_LISTA.IDLISTAS

left join (
	SELECT MAX(IDLISTAS) IDLISTAS, IDFORTOTIKIS FROM FORTOTIKES_ANA_LISTA GROUP BY IDFORTOTIKIS
) FAL ON FAL.IDFORTOTIKIS = FORTOTIKES.ID
left join LISTESDIANOMIS on LISTESDIANOMIS.id = FAL.IDLISTAS

--left join LISTESDIANOMIS on LISTESDIANOMIS.id = FORTOTIKES.IDLISTAS
where voh.ifDelete = 0
--order by 1
GO


