CREATE view [dbo].[EXPORT_METAFORIKO_LOGISTIKIS_IKEA_FORTOTIKES]
as

with souma_ana_tropo_pliromis as (
select 
	convert(date, f.dateprint) dateprint,
	f.IDPARAST,
	f.IDYPOKATASTIMA,
	f.IDKINDPAYMENT,
	sum(f.POSO) poso,
	sum(f.TAXIS) taxis,
	sum(f.sumposo) sumposo
	from fortotikes f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifdelete = 0
	group by convert(date, f.dateprint), f.idparast, f.idypokatastima, f.IDKINDPAYMENT
),

souma_arithmisi as (
	select 
		convert(date, f.dateprint) dateprint,
		f.IDPARAST,
		f.IDYPOKATASTIMA,
		min(cast(f.noparast as int)) noparastmin,
		max(cast(f.noparast as int)) noparastmax
	from fortotikes f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifdelete = 0
	group by convert(date, f.dateprint), f.idparast, f.idypokatastima
),

souma_antikatavoles as (
	select
		convert(date, f.dateprint) dateprint,
		kp.CATKEPYO,
		f.IDPARAST,
		f.IDYPOKATASTIMA,
		sum(f.SUMANTIK) SUMANTIK
	from fortotikes f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 1 and kp.IF_ENIMEROSIKARTELA = 1
	where f.ifDelete = 0
	group by convert(date, f.dateprint), kp.CATKEPYO, f.IDPARAST, f.IDYPOKATASTIMA
) 


select distinct
	convert(date, f.dateprint) [ΗΜΕΡΟΜΗΝΙΑ],-- [dateprint],
	c.id [idypokatastima],
	c.eponimia [ΥΠΟΚΑΤΑΣΤΗΜΑ],
	ISNULL(arithmisi_lianikon.norange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΛΙΑΝΙΚΗΣ],-- [noumera lianikon],
	ISNULL(arithmisi_xondrikis.norange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΧΟΝΔΡΙΚΗΣ],--[noumera xondrikis],
	ISNULL(convert(float,posa.poso) , 0) [ΚΑΘΑΡΗ ΑΞΙΑ],-- [synolo kathara],
	ISNULL(convert(float,posa.taxis) , 0) [ΦΠΑ],--[synolo fpa],
	ISNULL(convert(float,posa.sumposo), 0)  [ΣΥΝΟΛΙΚΗ ΑΞΙΑ],--[synolo synolo],
	ISNULL(convert(float,posalianikon.sumposo) , 0) [ΠΩΛΗΣΕΙΣ ΛΙΑΝΙΚΗΣ],--[lianikes synolo],
	ISNULL(convert(float,posaxondrikis.sumposo) , 0) [ΠΩΛΗΣΕΙΣ ΧΟΝΔΡΙΚΗΣ],-- [xondriki	synolo],
	--ISNULL(convert(float,s_poliseis_house_market.sumposo), 0) [ΠΩΛΗΣΕΙΣ HOUSE MARKET],--[poliseis house market], --kati gia sygkentrotiko timologio ?
	0 [ΠΩΛΗΣΕΙΣ HOUSE MARKET],
	ISNULL(convert(float,s_pistosi_lianikis.sumposo), 0) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΛΙΑΝΙΚΗΣ],--[pistosi lianikis],
	ISNULL(convert(float,s_pistosi_xondrikis.sumposo), 0) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΧΟΝΔΡΙΚΗΣ],--[pistosi xondrikis],
	ISNULL(convert(float,s_metrita_xondrikis.sumposo), 0) [ΜΕΤΡΗΤΑ ΧΟΝΔΡΙΚΗΣ],--[metrita xondrikis],
	ISNULL(convert(float,s_metrita_lianikis.sumposo), 0) [ΜΕΤΡΗΤΑ ΛΙΑΝΙΚΗΣ],--[metrita lianikis],
	ISNULL(convert(float,s_kartes_xondrikis.sumposo), 0) [ΚΑΡΤΑ ΧΟΝΔΡΙΚΗΣ],--[kartes xondrikis],
	ISNULL(convert(float,s_kartes_lianikis.sumposo), 0) [ΚΑΡΤΑ ΛΙΑΝΙΚΗΣ],--[kartes lianikis],
	ISNULL(convert(float,s_antik_lianikis.SUMANTIK), 0) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΛΙΑΝΙΚΗΣ],--[antikatavoles lianikis],
	ISNULL(convert(float,s_antik_xondrikis.SUMANTIK), 0) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΧΟΝΔΡΙΚΗΣ],--[antikatavoles xondrikis],
	ISNULL(convert(float,s_emvasmata_lianikis.SUMPOSO), 0) [ΕΜΒΑΣΜΑ ΛΙΑΝΙΚΗΣ],--[emvasmata lianikis],
	ISNULL(convert(float,s_emvasmata_xondrikis.SUMPOSO), 0) [ΕΜΒΑΣΜΑ ΧΟΝΔΡΙΚΗΣ]--[emvasmata xondrikis]

from fortotikes f
join COMPANIES c on c.id = f.IDYPOKATASTIMA
join KINDPARASTATIKON kp on kp.id = f.IDPARAST

left join (
	select 
		souma_arithmisi.dateprint,
		souma_arithmisi.IDYPOKATASTIMA,
		kp.SEIRA + ' ' + convert(varchar, souma_arithmisi.noparastmin) + '..' + convert(varchar, souma_arithmisi.noparastmax) norange

		from souma_arithmisi
		join KINDPARASTATIKON kp on kp.ID = souma_arithmisi.IDPARAST and kp.IfFortotiki = 1 and kp.CATKEPYO = 1 and kp.IF_ENIMEROSIKARTELA = 1

