ALTER view [dbo].[REPORT_COST_DILOTYPES_IKEA]
as
with t (id, ifkaa, iflista, uuid) as (
	select id, 1, 0, newid() from KAA
	union
	select id, 0, 1, newid() from LISTESDIANOMIS
),


fortsum as (
	select
		id,
		IDPARALIPTI,
		EXT_BARCODE,
		count(id) [synolo_fortotikon],
		sum(POSO) [poso],
		sum(Taxis) [taxis],
		sum(SUMPOSO) [sumposo]
	from FORTOTIKES 
	group by ID,IDPARALIPTI,EXT_BARCODE
),

gfsum as (
	SELECT
		IDVOH,
		SUM(BAROS) [BAROS],
		SUM(KYBIKA) [OGKOS]
	FROM GRAMMESFORTTIKIS 
	group by IDVOH
)

select 
	convert (NUMERIC(18,0),'200'+CAST(kaa.ID AS NVARCHAR(50)) )[ID],
	--t.uuid [id],
	kaa.IDYPOKATASTIMA,
	c.Eponimia,
	kaa.IDPARAST,
	kaa.PARASTATIKO,
	rtrim(kaa.SEIRA) + kaa.NOPARAST [noparast],
	kaa.OXIMA,
	tr.OLastName,
	kaa.DRIVER,
	convert(date,kaa.DATEPRINT,103) [DATEPRINT],
	CONVERT(nvarchar, kaa.dateprint,108) [time],
	month(kaa.DATEPRINT) [month],
	kaa.STATUS,
	f.EXT_BARCODE,
	accparal.Eponimia [paraliptisdescr],
	accparal.AddressCity [town],
	accparal.AddressStr + accparal.AddressNo [address],
	f.synolo_fortotikon,
	F.poso,
	F.taxis,
	F.sumposo,
	gf.BAROS,
	gf.OGKOS,
	kaa.ifDelete


from kaa
join t on t.ifkaa = 1 and t.iflista = 0 and t.id = kaa.id
left join companies c on c.id = kaa.IDYPOKATASTIMA
left join TRUCKS tr on tr.ArKykloforias=kaa.OXIMA
left join MAX_FORTOTIKES_ANA_KAA fkaa on fkaa.IDKAA=kaa.ID
left join fortsum f on f.ID=fkaa.IDFORTOTIKIS
left join ACCOUNTS accparal on accparal.id=f.IDPARALIPTI
left join gfsum gf on gf.IDVOH=f.ID

union all


select 
	convert(NUMERIC(18,0),'300'+ CAST(ld.id AS nvarchar(50))) [ID],
	--t.uuid [id],
	ld.IDYPOKATASTIMA,
	c.Eponimia,
	ld.IDPARAST,
	ld.PARASTATIKO,
	rtrim(ld.SEIRA) + ld.NOPARAST [noparast],
	ld.OXIMA,
	tr.OLastName,
	ld.DRIVER,
	convert(date,ld.DATEPRINT,103) [DATEPRINT],
	CONVERT(nvarchar, ld.dateprint,108) [time],
	month(ld.DATEPRINT) [month],
	ld.STATUS,
	f.EXT_BARCODE,
	accparal.Eponimia [paraliptisdescr],
	accparal.AddressCity [town],
	accparal.AddressStr + accparal.AddressNo [address],
	f.synolo_fortotikon,
	F.poso,
	F.taxis,
	F.sumposo,
	GF.BAROS,
	gf.OGKOS,
	ld.ifDelete

from LISTESDIANOMIS ld 
join t on t.iflista = 1 and t.ifkaa = 0 and t.id = ld.id
left join companies c on c.id = ld.IDYPOKATASTIMA
left join TRUCKS tr on tr.ArKykloforias=ld.OXIMA
left join MAX_FORTOTIKES_ANA_LISTA fl on fl.IDLISTAS=ld.ID
left join fortsum f on f.ID=fl.IDFORTOTIKIS
left join ACCOUNTS accparal on accparal.id=f.IDPARALIPTI
left join gfsum gf on gf.IDVOH=f.ID

			
GO




