alter PROCEDURE [dbo].[InserttogRAMMESFORTOTIKIS]
(
	@TIMDA				NVARCHAR(20),
	@IDVOH				NUMERIC(8,0)= NULL,
	@TEMAXIA			NUMERIC(8,0)= NULL,
	@PERIEXOMENO		NVARCHAR(50)= NULL,
	@SYSKEVASIA			NUMERIC(8,0)= NULL,
	@SYSKEVASIADESCR	NVARCHAR(50)= NULL,
	@BAROS				NUMERIC(18,2)= NULL,
	@KYBIKA				NUMERIC(8,2)= NULL,
	@SUMPOSO			NUMERIC(8,2)= NULL,
	@XreosiAnaMonada	NUMERIC(8,2)= NULL,
	@XeosiSeMonada		NVARCHAR(15)= NULL,
	@XreosiGrammis		NUMERIC(8,2)= NULL,
	@IF_KOMISTRO		int = 0,
	@IF_KATHARO			int = 0,
	@IF_MIKTO			int = 0,
	@IF_STANDAR			int = 0,
	@TheID				NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;
			INSERT INTO GRAMMESFORTTIKIS
				(
				TIMDA,
				IDVOH,
				TEMAXIA,
				PERIEXOMENO,
				SYSKEVASIA,
				SYSKEVASIADESCR,
				BAROS,
				KYBIKA,
				SUMPOSO,
				XreosiAnaMonada,
				XeosiSeMonada,
				XreosiGrammis,
				IF_KOMISTRO,
				IF_KATHARO,
				IF_MIKTO,
				IF_STANDAR
				)
			VALUES
				(
				@TIMDA,
				@IDVOH,
				@TEMAXIA,
				@PERIEXOMENO,
				@SYSKEVASIA,
				@SYSKEVASIADESCR,
				@BAROS,
				@KYBIKA,
				@SUMPOSO,
				@XreosiAnaMonada,
				@XeosiSeMonada,
				@XreosiGrammis,
				@IF_KOMISTRO,
				@IF_KATHARO,
				@IF_MIKTO,
				@IF_STANDAR
				)

--SELECT  @TheID = MAX(ID) FROM dbo.GRAMMESFORTTIKIS WITH (NOLOCK)

;
GO

