create VIEW [dbo].[DELTIA_APOTHIKIS_WITH_DETAILS] 
AS
with t (idgv, idvoh, rownum) as (
	select
		gv.id idgv,
		gv.IDVOH,
		ROW_NUMBER() OVER (partition by gv.idvoh order by gv.timda, gv.syskevasiadescr, gv.id) rownum
	from GRAMMESVOH gv)
select
	v.id as  Barcode,
	CONVERT(date,v.dateprint) dateprint,
	case t.rownum
		when 1 then CONVERT(varchar,v.DATEPRINT,103)
		else null
	end as 'Ημερομηνία',
	v.IDPARAST,
	V.PARASTATIKO AS 'Παραστατικό',
	v.NOPARAST  as 'Αρ.Παραστατικού',
	case t.rownum
		when 1 then v.SXETIKAPARASTATIKA
		else null
	end AS 'Σχετ.Παραστατικά',
	v.IDENTOLEA,
	v.entoleasdescr 'Εντολέας',
	v.IDAPOSTOLEA,
	v.apostoleasdescr 'Αποστολέας',
	case t.rownum
		when 1 then p.Code
		else null
	end AS 'Κωδ.Παραλήπτη',
	v.idparalipti,
	case t.rownum
		when 1 then p.Eponimia
		else null
	end AS 'Παραλήπτης',						
	case t.rownum
		when 1 then p.AddressCity
		else null
	end AS 'Πόλη Παραλήπτη',	
	case t.rownum
		when 1 then p.AddressStr
		else null
	end AS 'Διευθ.Παραλήπτη',	
	case t.rownum
		when 1 then v.PRAKTOREIODESCR
		else null
	end AS 'Πρακτορείο',
	t.rownum as 'Αρ.Γραμμής',
	CONVERT(VARCHAR,gv.codeeidos) 'Κωδ.Είδους',
	gv.DescrEidos 'Περιγραφή Είδους',	
	REPLACE(convert(numeric(18,3),gv.TEMAXIA),'.',',') as 'Τεμάχια',
	gv.SYSKEVASIA 'Συσκευασία',
	REPLACE(convert(numeric(18,4),gv.BAROS),'.',',') AS 'Βάρος',
	REPLACE(convert(numeric(18,4),gv.KYBIKA),'.',',') AS 'Κυβικά' 
	from VOH v
left join ACCOUNTS p on p.id = v.IDPARALIPTI
join GRAMMESVOH gv on gv.IDVOH = v.ID 
join t on t.idgv = gv.id
join KINDPARASTATIKON kp on kp.ID=v.IDPARAST and kp.IF_ENIMEROSIAPOTHIKI=1  and kp.IFKEPYO=0

where v.ifDelete=0

GO

---END SCRIPT 1533
