ALTER VIEW [dbo].[EXPORT_SYNARMOLOGISI_LOGISTIKIS_IKEA_POLISEIS] AS
with activity as (
	select distinct 
		convert(date, f.dateprint) dateprint, 
		f.idypokatastima 
	from voh f
	join KINDPARASTATIKON kp 
			on kp.ID = f.IDPARAST 
			and kp.IfFortotiki = 0 
			and kp.IF_PAROXIYPIRESION = 1 
			and kp.IF_ENIMEROSIKARTELA = 1 
			and ISNULL(kp.IF_SYGMET, 0) = 0 
			and ISNULL(kp.IF_SYGSYN, 0) = 0
	where f.ifDelete = 0
),

souma_arithmisi as (
	select
		t.dateprint,
		t.IDPARAST,
		t.IDYPOKATASTIMA,
		kp.CATKEPYO,
		kp.Descr,
		kp.SEIRA + ' ' + convert(nvarchar, t.noparastmin) + '..' + convert(nvarchar, t.noparastmax) noparastrange
	from (
		select 
			convert(date, f.dateprint) dateprint,
			f.IDPARAST,
			f.IDYPOKATASTIMA,
			min(cast(f.noparast as int)) noparastmin,
			max(cast(f.noparast as int)) noparastmax
		from voh f
		join KINDPARASTATIKON kp 
			on kp.ID = f.IDPARAST 
			and kp.IfFortotiki = 0 
			and kp.IF_PAROXIYPIRESION = 1 
			and kp.IF_ENIMEROSIKARTELA = 1 
			and ISNULL(kp.IF_SYGMET, 0) = 0 
			and ISNULL(kp.IF_SYGSYN, 0) = 0
		where f.ifdelete = 0
		group by convert(date, f.dateprint), f.idparast, f.idypokatastima
	) t
	join KINDPARASTATIKON kp on kp.ID = t.IDPARAST
),

souma_poson as (
	select 
		grouping(kp.catkepyo) agg_catkepyo,
		grouping(f.idkindpayment) agg_idkindpayment,
		grouping(f.ifkarta) agg_ifkarta,
		f.dateprint,
		f.IDYPOKATASTIMA,
		f.IDKINDPAYMENT,
		f.ifkarta,
		kp.CATKEPYO,
		sum(f.POSO) poso,
		sum(f.TAXIS) taxis,
		sum(f.sumposo) sumposo,
		sum(f.SUMANTIK) sumantik
	from (
		select 
			convert(date, v.DATEPRINT) dateprint,
			v.IDPARAST,
			v.IDYPOKATASTIMA,
			v.IDKINDPAYMENT,
			case when v.IDKINDPAYMENT IN (5, 14, 15, 16) THEN 1
				ELSE 0
			END ifkarta,
			v.POSO,
			v.TAXIS,
			v.SUMPOSO,
			v.SUMANTIK
		from voh v
		where v.ifDelete = 0
	) f
	join KINDPARASTATIKON kp on kp.ID = f.IDPARAST and kp.IfFortotiki = 0 and kp.IF_PAROXIYPIRESION = 1 and kp.IF_ENIMEROSIKARTELA = 1 and ISNULL(kp.IF_SYGMET, 0) = 0 and ISNULL(kp.IF_SYGSYN, 0) = 0
	group by grouping sets (
		(f.dateprint, f.idypokatastima, kp.CATKEPYO, f.ifkarta),
		(f.dateprint, f.idypokatastima, kp.CATKEPYO, f.IDKINDPAYMENT),
		(f.dateprint, f.idypokatastima, kp.CATKEPYO),
		(f.dateprint, f.idypokatastima)
	)
)

select 
	a.dateprint [ΗΜΕΡΟΜΗΝΙΑ],
	c.id [idypokatastima],
	c.Eponimia [ΥΠΟΚΑΤΑΣΤΗΜΑ],
	ISNULL(arithmisi_lianikon.noparastrange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΛΙΑΝΙΚΗΣ],
	ISNULL(arithmisi_xondrikis.noparastrange, '.') [ΠΑΡΑΣΤΑΤΙΚΑ ΧΟΝΔΡΙΚΗΣ],
	synolikaposa.poso [ΚΑΘΑΡΗ ΑΞΙΑ],
	synolikaposa.taxis [ΦΠΑ],
	synolikaposa.sumposo [ΣΥΝΟΛΙΚΗ ΑΞΙΑ],
	ISNULL(synola_lianikon.sumposo, 0.00) [ΠΩΛΗΣΕΙΣ ΛΙΑΝΙΚΗΣ],
	ISNULL(synola_xondrikis.sumposo, 0.00) [ΠΩΛΗΣΕΙΣ ΧΟΝΔΡΙΚΗΣ],
	0 [ΠΩΛΗΣΕΙΣ HOUSE MARKET],

	ISNULL(pistosi_lianikis.sumposo, 0.00) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΛΙΑΝΙΚΗΣ],
	ISNULL(pistosi_xondrikis.sumposo, 0.00) [ΠΩΛΗΣΕΙΣ ΕΠΙ ΠΙΣΤΩΣΗ ΧΟΝΔΡΙΚΗΣ],

	ISNULL(metrita_xondrikis.sumposo, 0.00) [ΜΕΤΡΗΤΑ ΧΟΝΔΡΙΚΗΣ],
	ISNULL(metrita_lianikis.sumposo, 0.00) [ΜΕΤΡΗΤΑ ΛΙΑΝΙΚΗΣ],
	
	ISNULL(kartes_xondrikis.sumposo, 0.00) [ΚΑΡΤΑ ΧΟΝΔΡΙΚΗΣ],
	ISNULL(kartes_lianikis.sumposo, 0.00) [ΚΑΡΤΑ ΛΙΑΝΙΚΗΣ],

	ISNULL(antikataboles_lianikis.sumantik, 0.00) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΛΙΑΝΙΚΗΣ],
	ISNULL(antikataboles_xondrikis.sumantik, 0.00) [ΑΝΤΙΚΑΤΑΒΟΛΗ ΧΟΝΔΡΙΚΗΣ],
	
	
	ISNULL(embasma_lianikis.sumposo, 0.00) [ΕΜΒΑΣΜΑ ΛΙΑΝΙΚΗΣ],
	ISNULL(embasma_xondrikis.sumposo, 0.00) [ΕΜΒΑΣΜΑ ΧΟΝΔΡΙΚΗΣ]
	


from activity a
join companies c on c.id = a.IDYPOKATASTIMA

left join souma_arithmisi arithmisi_lianikon
	on arithmisi_lianikon.dateprint = a.dateprint
	and arithmisi_lianikon.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and arithmisi_lianikon.CATKEPYO = 1

left join souma_arithmisi arithmisi_xondrikis
	on arithmisi_xondrikis.dateprint = a.dateprint
	and arithmisi_xondrikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and arithmisi_xondrikis.CATKEPYO = 0

left join souma_poson synolikaposa 
	on synolikaposa.dateprint = a.dateprint
	and synolikaposa.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and synolikaposa.agg_catkepyo = 1
	and synolikaposa.agg_idkindpayment = 1
	and synolikaposa.agg_ifkarta = 1

left join souma_poson synola_lianikon 
	on synola_lianikon.dateprint = a.dateprint
	and synola_lianikon.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and synola_lianikon.agg_catkepyo = 0
	and synola_lianikon.agg_idkindpayment = 1
	and synola_lianikon.agg_ifkarta = 1

	and synola_lianikon.CATKEPYO = 1


left join souma_poson synola_xondrikis 
	on synola_xondrikis.dateprint = a.dateprint
	and synola_xondrikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and synola_xondrikis.agg_catkepyo = 0
	and synola_xondrikis.CATKEPYO = 0
	and synola_xondrikis.agg_idkindpayment = 1
	and synola_xondrikis.agg_ifkarta = 1

left join souma_poson pistosi_lianikis 
	on pistosi_lianikis.dateprint = a.dateprint
	and pistosi_lianikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and pistosi_lianikis.agg_catkepyo = 0
	and pistosi_lianikis.CATKEPYO = 1
	and pistosi_lianikis.agg_idkindpayment = 0
	and pistosi_lianikis.IDKINDPAYMENT = 2
	and pistosi_lianikis.agg_ifkarta = 1

left join souma_poson pistosi_xondrikis 
	on pistosi_xondrikis.dateprint = a.dateprint
	and pistosi_xondrikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and pistosi_xondrikis.agg_catkepyo = 0
	and pistosi_xondrikis.CATKEPYO = 0
	and pistosi_xondrikis.agg_idkindpayment = 0
	and pistosi_xondrikis.IDKINDPAYMENT = 2
	and pistosi_xondrikis.agg_ifkarta = 1

left join souma_poson metrita_lianikis
	on metrita_lianikis.dateprint = a.dateprint
	and metrita_lianikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and metrita_lianikis.agg_catkepyo = 0
	and metrita_lianikis.CATKEPYO = 1
	and metrita_lianikis.agg_idkindpayment = 0
	and metrita_lianikis.IDKINDPAYMENT = 1
	and metrita_lianikis.agg_ifkarta = 1

left join souma_poson metrita_xondrikis
	on metrita_xondrikis.dateprint = a.dateprint
	and metrita_xondrikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and metrita_xondrikis.agg_catkepyo = 0
	and metrita_xondrikis.CATKEPYO = 0
	and metrita_xondrikis.agg_idkindpayment = 0
	and metrita_xondrikis.IDKINDPAYMENT = 1
	and metrita_xondrikis.agg_ifkarta = 1

left join souma_poson kartes_lianikis
	on kartes_lianikis.dateprint = a.dateprint
	and kartes_lianikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and kartes_lianikis.agg_catkepyo = 0
	and kartes_lianikis.agg_idkindpayment = 1
	and kartes_lianikis.agg_ifkarta = 0
	and kartes_lianikis.CATKEPYO = 1
	and kartes_lianikis.ifkarta = 1

left join souma_poson kartes_xondrikis
	on kartes_xondrikis.dateprint = a.dateprint
	and kartes_xondrikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and kartes_xondrikis.agg_catkepyo = 0
	and kartes_xondrikis.agg_idkindpayment = 1
	and kartes_xondrikis.agg_ifkarta = 0
	and kartes_xondrikis.CATKEPYO = 0
	and kartes_xondrikis.ifkarta = 1

left join souma_poson embasma_lianikis
	on embasma_lianikis.dateprint = a.dateprint
	and embasma_lianikis.IDYPOKATASTIMA = a.IDYPOKATASTIMA
	and embasma_lianikis.agg_catkepyo = 0
	and embasma_lianikis.CATKEPYO = 1
	and embasma_lianikis.agg_idkindpayment = 0
