ALTER TABLE PAYMENTS ALTER COLUMN AITIOLOGIA NVARCHAR(500) NULL;
GO

ALTER PROCEDURE [dbo].[InserttoPAYMENTS]
	(
	@SEIRA					NVARCHAR(3)= NULL,
	@DOCNO					NVARCHAR(10)= NULL,
	@IDKINDPARAST			NUMERIC(18, 0),                    
	@KINDPARASTDESCR        NVARCHAR(100),  
	@IDAFORA                NUMERIC(18, 0) =1, 
	@AFORA					NVARCHAR(30)= NULL,                                                
	@AITIOLOGIA             NVARCHAR(500)= NULL,                                                                             
	@EISPRAXAS              NVARCHAR(100)= NULL,                                                                            
	@IDKINDPAYMENT			NUMERIC(18, 0),                  
	@KINDPAYMENTDESCR       NVARCHAR(60)= NULL, 
	@AFMCUSTOMER			NVARCHAR(10)= NULL,                          
	@IDVOH					NUMERIC(18, 0)= 0,                    
	@IDCUSTOMER				NUMERIC(18, 0)= 0,                    
	@CUSTOMERDESCR          NVARCHAR(100)= NULL,                            
	@SUMPOSO				DECIMAL(18, 2)=0,                            
	@DATEPRINT				DATETIME,
	@IfMisthodosia			int = 0,
	@IF_TO_FORTOTIKI		int = 0,
	@IF_TO_VOH				int = 0,
	@IF_APOGRAFI			int = 0,
	@IDXRHSHS				NUMERIC(18,0) = 0,
	@IDCOMPANY				NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA			NUMERIC(18,0) = 0,
	@DateCreate				DATETIME,-- = NULL,
	@UserCreate				NVARCHAR(50),
	@TheID					NUMERIC(18, 0)= NULL output
	--@TheKeySeries			varchar(10) output

	)
AS
SET NOCOUNT ON;
DECLARE @NEWNOPARAST NUMERIC(18, 0)=0;
IF (LEN(@DOCNO)<1 OR CONVERT(NUMERIC(18,0),@DOCNO )<1)
BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			if EXISTS (SELECT (ISNULL(DOCNO,0)) FROM PAYMENTS WHERE  SEIRA = @SEIRA AND  IDKINDPARAST =@IDKINDPARAST)
				 BEGIN
					SELECT @DOCNO = ROUND(MAX(ISNULL(DOCNO +1, 0)),0)  FROM PAYMENTS WHERE SEIRA = @SEIRA AND  IDKINDPARAST =@IDKINDPARAST
					SET @DOCNO = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @DOCNO =  1
				 END
		END;
	ELSE
		BEGIN
			if EXISTS (SELECT (ISNULL(DOCNO,0)) FROM PAYMENTS WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDKINDPARAST =@IDKINDPARAST)
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(DOCNO +1, 0)),0)  FROM PAYMENTS WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDKINDPARAST =@IDKINDPARAST
					SET @DOCNO = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @DOCNO =  1
				 END
		END;
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@DOCNO + 1) WHERE ID = @IDKINDPARAST;
	END
	INSERT INTO PAYMENTS
	(                                      
	SEIRA, 
	DOCNO,         
	IDKINDPARAST,                            
	KINDPARASTDESCR,  
	IDAFORA,
	AFORA,                                                                                    
	AITIOLOGIA,                                                                                           
	EISPRAXAS,                                                                                            
	IDKINDPAYMENT,                           
	KINDPAYMENTDESCR,                                   
	IDVOH,      
	AFMCUSTOMER,                            
	IDCUSTOMER,                              
	CUSTOMERDESCR,                                      
	SUMPOSO,                                 
	DATEPRINT,
	IfMisthodosia,
	IF_TO_FORTOTIKI,
	IF_TO_VOH,
	IF_APOGRAFI,
	IDXRHSHS,
	IDCOMPANY,
	IDYPOKATASTIMA,
	DateCreate,
	UserCreate
	)
	VALUES
	(
	@SEIRA, 
	@DOCNO,         
	@IDKINDPARAST,                            
	@KINDPARASTDESCR,   
	@IDAFORA,
	@AFORA,                                                                                   
	@AITIOLOGIA,                                                                                           
	@EISPRAXAS,                                                                                            
