	CASE VOH.IFXRAPOST 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRAPOST,
	CASE VOH.IFXRPARAL 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRPARAL,
	CASE VOH.IFXRTRITOU 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRTRITOU,
	VOH.IFANTIKCASH,
	--VOH.ANTIKEPIT,
	--VOH.ANTIKSYNAL,
	--VOH.ANTIKOTHER,
