	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
	VOH.NOPARPARALANTIK,
	VOH.DATEPARAL,
	VOH.COMMENTSPARAD,
	VOH.COMMANTSPARAL,
	VOH.TIMEPARALFROM,
	VOH.TIMEPARALTO,
	VOH.TIMEPARADFROM,
	VOH.TIMEPARADTO,
	VOH.DATECANCELANTIK,
	VOH.TAXISPERCENT,
