create TRIGGER [dbo].[REMOVE_IDSYGTIMOL] 
   ON  [dbo].[VOH]
   AFTER INSERT, UPDATE
AS 
BEGIN
	SET NOCOUNT ON;

	update entolh 
		set IDSYGTIMOL = NULL
	from voh entolh
	join inserted i on i.id = entolh.id
	join voh timol on timol.id = entolh.IDSYGTIMOL
	join KINDPARASTATIKON kpentol on kpentol.id = entolh.IDPARAST
	join KINDPARASTATIKON kptimol on kptimol.id = timol.IDPARAST
	where ISNULL(kpentol.IF_EDSYNARMOL, 0) = 1
	and ISNULL(kptimol.IF_SYGSYN, 0) = 0

END
GO
