CREATE view [dbo].[REPORT_KPI_ENTOLES] as
with gvsum as (
	select 
		idvoh, 
		sum(KYBIKA) kybika, 
		sum(BAROS) baros, 
		count(id) proionta,
		sum(pcs) temaxia
	from GRAMMESVOH
	group by idvoh
)

select
	voh.ID,
	RTRIM(LTRIM(voh.SEIRA)) + voh.NOPARAST [arithmos],
	convert(date, voh.DATEPRINT) [date],
	kp.IF_EDMETAFORAS [ifmetafora],
	kp.IF_EDSYNARMOL [ifsynarmologisi],
	voh.IDYPOKATASTIMA,
	c.Eponimia [ypokatastima],
	voh.IDENTOLEA,
	voh.ENTOLEASDESCR,
	hvp.CodeCatalog,
	hvp.DescrCatalog,
	gvsum.proionta,
	gvsum.temaxia,
	gvsum.baros,
	gvsum.kybika,
	
	voh.SERVICEZONE [zoni], --zoni
	voh.POSO,
	voh.TAXIS,
	voh.SUMPOSO,
	voh.ifDelete
from voh
join gvsum on gvsum.IDVOH = voh.ID
join HEADERVOHPRICING hvp on hvp.idvoh = voh.id
join KINDPARASTATIKON kp on kp.id = voh.idparast
join companies c on c.id = voh.IDYPOKATASTIMA
where kp.IF_EDMETAFORAS = 1 or kp.IF_EDSYNARMOL = 1
GO


---END SCRIPT 1544
