ALTER VIEW [dbo].[KAA_FORT_REPORT]
AS
SELECT   distinct  TOP (100) PERCENT FORTOTIKES_VIEW.XREOYMENOS, FORTOTIKES_VIEW.AFMAPOSTOLEA, FORTOTIKES_VIEW.APOSTOLEASDESCR, FORTOTIKES_VIEW.ENTOLEASDESCR, FORTOTIKES_VIEW.AFMPARALIPTI AS  AFMPARALIPTI, FORTOTIKES_VIEW.PARALISPTISDESCR, 
                      (FORTOTIKES_VIEW.ADDRSTRPARAL + ' ' + FORTOTIKES_VIEW.ADDRNOPARAL) AS ADDRPARADOSIS, FORTOTIKES_VIEW.ADDRCITYPARAL,FORTOTIKES_VIEW.TEMAXIA, FORTOTIKES_VIEW.SYSKEVASIA, FORTOTIKES_VIEW.NOPARAST, FORTOTIKES_VIEW.Code, 
                      ACCOUNTS.AddressCity, FORTOTIKES_VIEW.KOMISTRA, FORTOTIKES_VIEW.DIKAIOMAFORTOTIKIS, FORTOTIKES_VIEW.OTHERXREOSIS, FORTOTIKES_VIEW.TIMDA, 
                      ISNULL(FORTOTIKES_VIEW.AXIA, 0) AS AXIA, ISNULL(FORTOTIKES_VIEW.BAROS, 0) AS BAROS, ISNULL(FORTOTIKES_VIEW.KYBIKA, 0) AS KYBIKA, FORTOTIKES_VIEW.PERIEXOMENO ,FORTOTIKES_VIEW.XREOSIPROPLIROMENES, 
                      FORTOTIKES_VIEW.XREOSIOFEILOMENES, FORTOTIKES_VIEW.SUMANTIK, KAA.IDPARAST, KAA.PARASTATIKO, KAA.SEIRA AS SEIRAKAA, KAA.NOPARAST AS NOPARASTKAA, ACCOUNTS.Mobile AS PARALIPTIS_MOBILE,
                      KAA.DATEPRINT, KAA.OXIMA, KAA.DRIVER, FORTOTIKES_VIEW.XREOSISTRITON, TRUCKS.OLastName, TRUCKS.OmProorDescr,(FORTOTIKES_VIEW.TELPARAL + ' ' + FORTOTIKES_VIEW.MOBILEPARALIPTI) AS TELPARALIPTI,  
                      FORTOTIKES_VIEW.OMADPROORISMOS, FORTOTIKES_VIEW.ASFALISTRA, FORTOTIKES_VIEW.TAXISXREOSEON, FORTOTIKES_VIEW.KATHARO, FORTOTIKES_VIEW.ANAMEXODO, FORTOTIKES_VIEW.EXT_BARCODE, 
                      FORTOTIKES_VIEW.XREOSIPROPLIROMENESCASH, FORTOTIKES_VIEW.XREOSIPROPLIROMENESPISTOSI, KAA.ID, FORTOTIKES_ANA_KAA.IDFORTOTIKIS, ISNULL(G.PROPLMETROTHERXREOSEIS , 0) AS PROPLMETROTHERXREOSEIS, 
                      KAA.IDCOMPANY, KAA.IDYPOKATASTIMA, KAA.IDXRHSHS, KAA.PERIOXIPROORISMOU, KAA.PERIOXIPARADOSIS, TRUCKS.Tel AS TELOWNER, FORTOTIKES_VIEW.IDPRAKTOREIO, FORTOTIKES_VIEW.PRAKTOREIODESCR, 
                      KAA.AFMCUSTOMER, KAA.AFMANTAPOKRITIS, KAA.ANTAPOKRITIS AS ANTAPOKRITISKAA, KAA.FORTOSI, KAA.CUSTOMER, KAA.ANTAPOKRITIS, KAA.OMADPROORISMOS AS OMPROORKAA, dbo.ODIGOI.Tel AS 
                      TELDRIVER, KAA.CONTAINER, KAA.BOAT, (ANTAP.AddressStr + ' ' + ANTAP.AddressNo + '  ' + ANTAP.AddressCity + ' - ' + ANTAP.AddressCountry) 
                      AS ADDRESSANTAPOKRITI, ANTAP.AFM AS AFMANTAPOKRITI, ANTAP.DOY AS DOYANTAPOKRITI, ISNULL(G.DIAFORA_EXODA , 0) AS DIAFORA_EXODA, ISNULL(G.OFEILOMENAKOMISTRA , 0) AS OFEILOMENAKOMISTRA,
                      ISNULL(G.ERGATIKA , 0) AS ERGETIKA, ISNULL(G.XREOSEISTRITON , 0) AS XREOSEISTRITON, ISNULL(G.EMVASTIKA , 0) AS EMVASTIKA, ISNULL(G.KATHAROPROPLMETR, 0) AS  KATHAROPROPLMETR, ISNULL(G.TAXISPROPLMETR, 0) AS  TAXISPROPLMETR,
                      ISNULL(G.KATHAROOFEIL, 0) AS  KATHAROOFEIL, ISNULL(G.TAXISOFEIL, 0) AS  TAXISOFEIL, ISNULL(G.OTHERXREOSEIS , 0) AS OTHERXREOSEIS, ISNULL(G.EXODATRITON, 0)AS EXODATRITON, ISNULL(G.SYN_POSO_FORTOTIKIS, 0) AS SYN_POSO_FORTOTIKIS,
                      ISNULL(G.PROPLMETRERGATIKA , 0) AS PROPLMETRERGATIKA, ISNULL(G.PROPLMETRASFALISTRA , 0) AS PROPLMETRASFALISTRA, ISNULL(G.PROPLMETRDIKAIOMA , 0) AS PROPLMETRDIKAIOMA, 
                      ISNULL(G.PROPLMETRKOMISTRA , 0) AS PROPLMETRKOMISTRA, (ISNULL(G.ERGATIKA , 0)+ ISNULL(G.OTHERXREOSEIS , 0) + ISNULL(G.ASFALISTRA , 0)) AS ERG_ASF_OTHER, 
                      (ISNULL(G.ERGATIKA , 0)+ ISNULL(G.OTHERXREOSEIS , 0)) AS ERG_OTHER, (ISNULL(G.ERGATIKA , 0) + ISNULL(G.ASFALISTRA , 0)) AS ERG_ASF, 
                      (ISNULL(G.OTHERXREOSEIS , 0) + ISNULL(G.ASFALISTRA , 0)) AS ASF_OTHER, (ISNULL(FORTOTIKES_VIEW.KOMISTRA , 0)+ ISNULL(FORTOTIKES_VIEW.DIKAIOMAFORTOTIKIS , 0)) AS KOM_DIKAIOMA
FROM         dbo.FORTOTIKES_VIEW AS FORTOTIKES_VIEW WITH(INDEX(IX_FORTOTIKES_ID))  LEFT OUTER JOIN
                      dbo.FORTOTIKES_ANA_KAA AS FORTOTIKES_ANA_KAA WITH(INDEX(IX_FORTOTIKES_ANA_KAA_ID)) ON 
                      FORTOTIKES_VIEW.IDFORTOTIKIS = FORTOTIKES_ANA_KAA.IDFORTOTIKIS LEFT JOIN
                      dbo.ACCOUNTS AS ACCOUNTS WITH (NOLOCK) ON FORTOTIKES_VIEW.IDPARALIPTI = ACCOUNTS.id LEFT OUTER JOIN
                      dbo.KAA AS KAA WITH (NOLOCK) ON FORTOTIKES_ANA_KAA.IDKAA = KAA.ID FULL JOIN
                      dbo.TRUCKS AS TRUCKS WITH (NOLOCK) ON KAA.OXIMA = TRUCKS.ArKykloforias FULL JOIN
                      dbo.ODIGOI ON KAA.DRIVER = dbo.ODIGOI.LastName + ' ' + ODIGOI.FirstName --.ArKykloforias = dbo.ODIGOI.ArKikloforias 
                      LEFT JOIN ACCOUNTS AS ANTAP 
                      ON KAA.IDANTAPOKRITIS = ANTAP.id INNER JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI AS G ON FORTOTIKES_VIEW.ID = G.ID
      --                LEFT JOIN (SELECT  J.ID, ISNULL(SUM(P.POSO), 0) AS OTHERXREOSEIS	from dbo.FORTOTIKES AS J 
						--LEFT JOIN XREOSISANADELTIO AS P ON J.ID=P.IDVOH AND P.IF_TO_FORTOTIKI  = 1 AND P.IDXREOSIS 
						--IN (SELECT ID FROM Xreoseis WHERE ifOther = 1) group by J.ID) AS X ON FORTOTIKES_VIEW.ID = X.ID
ORDER BY FORTOTIKES_VIEW.Code, NOPARAST





GO



