ALTER VIEW [dbo].[LISTADIAN_FORT_REPORT]
AS
SELECT  distinct   TOP (100) PERCENT FORTOTIKES_VIEW.XREOYMENOS, FORTOTIKES_VIEW.APOSTOLEASDESCR, FORTOTIKES_VIEW.PARALISPTISDESCR, 
                      ACCOUNTS.AddressCity, LISTESDIANOMIS.PARASTATIKO, FORTOTIKES_VIEW.Code, FORTOTIKES_VIEW.NOPARAST, ACCOUNTS.Mobile AS PARALIPTIS_MOBILE,
                      LISTESDIANOMIS.SEIRA AS SEIRALISTA, LISTESDIANOMIS.NOPARAST AS NOPARASTKAA, LISTESDIANOMIS.DATEPRINT, LISTESDIANOMIS.OXIMA, 
                      LISTESDIANOMIS.DRIVER, FORTOTIKES_VIEW.XREOSISTRITON, TRUCKS.OLastName, TRUCKS.OmProorDescr, FORTOTIKES_VIEW.OMADPROORISMOS, 
                      FORTOTIKES_VIEW.SYSKEVASIA, FORTOTIKES_VIEW.TEMAXIA, FORTOTIKES_VIEW.BAROS, FORTOTIKES_VIEW.KYBIKA, 
                      ISNULL((FORTOTIKES_VIEW.KOMISTRA * KPAR.IFENIMEROSITAMEIO), 0) AS KOMISTRA, 
					  ISNULL((FORTOTIKES_VIEW.DIKAIOMAFORTOTIKIS * KPAR.IFENIMEROSITAMEIO), 0) AS DIKAIOMAFORTOTIKIS, 
                      ISNULL((FORTOTIKES_VIEW.OTHERXREOSIS * KPAR.IFENIMEROSITAMEIO), 0) AS OTHERXREOSIS, FORTOTIKES_VIEW.EXT_BARCODE,  
                      ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENES * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENES, 
                      ISNULL((FORTOTIKES_VIEW.XREOSIOFEILOMENES * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIOFEILOMENES,                       
                      ISNULL((FORTOTIKES_VIEW.ASFALISTRA * KPAR.IFENIMEROSITAMEIO), 0) AS ASFALISTRA, 
                      ISNULL((FORTOTIKES_VIEW.TAXISXREOSEON * KPAR.IFENIMEROSITAMEIO), 0) AS TAXISXREOSEON, 
                      ISNULL((FORTOTIKES_VIEW.KATHARO * KPAR.IFENIMEROSITAMEIO), 0) AS KATHARO, 
                      ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENESCASH * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENESCASH, 
                      ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENESPISTOSI * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENESPISTOSI,
                      FORTOTIKES_VIEW.SUMANTIK, LISTESDIANOMIS.ID, FORTOTIKES_ANA_LISTA.IDFORTOTIKIS
FROM         dbo.FORTOTIKES_VIEW AS FORTOTIKES_VIEW WITH (NOLOCK) LEFT JOIN
                      dbo.FORTOTIKES_ANA_LISTA AS FORTOTIKES_ANA_LISTA WITH (NOLOCK) ON FORTOTIKES_VIEW.IDFORTOTIKIS = 
					  FORTOTIKES_ANA_LISTA.IDFORTOTIKIS LEFT JOIN
                      dbo.ACCOUNTS AS ACCOUNTS WITH (NOLOCK) ON FORTOTIKES_VIEW.IDPARALIPTI = ACCOUNTS.id INNER JOIN
                      dbo.LISTESDIANOMIS AS LISTESDIANOMIS WITH (NOLOCK) ON FORTOTIKES_ANA_LISTA.IDLISTAS = LISTESDIANOMIS.ID LEFT JOIN
                      dbo.TRUCKS AS TRUCKS WITH (NOLOCK) ON LISTESDIANOMIS.OXIMA = TRUCKS.ArKykloforias LEFT JOIN KINDPARASTATIKON AS KPAR 
                      ON FORTOTIKES_VIEW.IDPARAST = KPAR.ID
ORDER BY FORTOTIKES_VIEW.Code, NOPARAST 
GO


---END SCRIPT 1547
