ALTER VIEW [dbo].[STORED_KAA_FORT_REPORT]
AS
SELECT   DISTINCT  TOP (100) PERCENT B.XREOYMENOS, B.APOSTOLEASDESCR, FORTOTIKES_VIEW.ENTOLEASDESCR, FORTOTIKES_VIEW.AFMPARALIPTI AS  AFMPARALIPTI, B.PARALISPTISDESCR, APOST.AFM AS AFMAPOSTOLEA, 
        B.TEMAXIA, B.SYSKEVASIA, B.NOPARASTFORT AS NOPARAST, B.Code, ISNULL(B.BAROS, 0) AS BAROS, ISNULL(B.KYBIKA, 0) AS KYBIKA, B.PERIEXOMENO, ACCOUNTS.Mobile AS PARALIPTIS_MOBILE,
        ACCOUNTS.AddressCity, B.KOMISTRA, B.DIKAIOMA AS DIKAIOMAFORTOTIKIS, B.OTHERPOSO AS OTHERXREOSIS, 
        (FORTOTIKES_VIEW.ADDRSTRPARAL + ' ' + FORTOTIKES_VIEW.ADDRNOPARAL) AS ADDRPARADOSIS, FORTOTIKES_VIEW.ADDRCITYPARAL, B.XREOSIPROPLIROMENES, 
        B.XREOSIOFEILOMENES, (FORTOTIKES_VIEW.TELPARAL + ' ' + FORTOTIKES_VIEW.MOBILEPARALIPTI) AS TELPARALIPTI,  B.SUMANTIK, KAA.PARASTATIKO, 
        KAA.SEIRA AS SEIRAKAA, KAA.NOPARAST AS NOPARASTKAA, KAA.DATEPRINT, KAA.OXIMA, KAA.DRIVER, B.EXODATRITON AS XREOSISTRITON, 
        TRUCKS.OLastName, TRUCKS.OmProorDescr, ISNULL(B.AXIA, 0) AS AXIA, B.TIMDA, B.ANTAPOKRITIS, FORTOTIKES_VIEW.EXT_BARCODE,  
        B.OMADPROORISMOS, B.ASFALISTRA, B.TAXIS AS TAXISXREOSEON, B.POSO AS KATHARO, B.EXODATRITON,
        B.XREOSIPROPLIROMENESCASH, B.XREOSIPROPLIROMENESPISTOSI, KAA.ID, B.IDFORTOTIKIS, B.OFEILOMENAKOMISTRA, B.SYN_POSO_FORTOTIKIS,
        KAA.IDCOMPANY, KAA.IDYPOKATASTIMA, KAA.IDXRHSHS, KAA.PERIOXIPROORISMOU, KAA.PERIOXIPARADOSIS, TRUCKS.Tel AS TELOWNER, 
        KAA.AFMCUSTOMER, KAA.AFMANTAPOKRITIS, KAA.FORTOSI, KAA.CUSTOMER, ANTAP.Eponimia AS ANTAPOKRITISKAA, KAA.OMADPROORISMOS AS OMPROORKAA, 
        dbo.ODIGOI.Tel AS TELDRIVER, KAA.CONTAINER, KAA.BOAT, (ANTAP.AddressStr + ' ' + ANTAP.AddressNo + '  ' + ANTAP.AddressCity + ' - ' + ANTAP.AddressCountry) 
		AS ADDRESSANTAPOKRITI, ANTAP.AFM AS AFMANTAPOKRITI, ANTAP.DOY AS DOYANTAPOKRITI , ISNULL(B.DIAFORA_EXODA , 0) AS DIAFORA_EXODA,
		ISNULL(B.ERGATIKA , 0) AS ERGETIKA, ISNULL(B.XREOSEISTRITON , 0) AS XREOSEISTRITON, ISNULL(B.EMVASTIKA , 0) AS EMVASTIKA, ISNULL(B.OTHERXREOSEIS , 0) AS OTHERXREOSEIS,--, 
		ISNULL(B.PROPLMETRERGATIKA , 0) AS PROPLMETRERGATIKA, ISNULL(B.PROPLMETRASFALISTRA , 0) AS PROPLMETRASFALISTRA, ISNULL(B.PROPLMETRDIKAIOMA , 0) AS PROPLMETRDIKAIOMA, 
		ISNULL(B.PROPLMETRKOMISTRA , 0) AS PROPLMETRKOMISTRA, (ISNULL(B.ERGATIKA , 0)+ ISNULL(B.OTHERXREOSEIS , 0) + ISNULL(B.ASFALISTRA , 0)) AS ERG_ASF_OTHER, 
		(ISNULL(B.ERGATIKA , 0)+ ISNULL(B.OTHERXREOSEIS , 0)) AS ERG_OTHER, (ISNULL(B.ERGATIKA , 0) + ISNULL(B.ASFALISTRA , 0)) AS ERG_ASF, ISNULL(B.KATHAROPROPLMETR , 0) AS KATHAROPROPLMETR, 
		ISNULL(B.TAXISPROPLMETR , 0) AS TAXISPROPLMETR, ISNULL(B.KATHAROOFEIL , 0) AS KATHAROOFEIL, ISNULL(B.TAXISOFEIL , 0) AS TAXISOFEIL, 
		(ISNULL(B.OTHERXREOSEIS , 0) + ISNULL(B.ASFALISTRA , 0)) AS ASF_OTHER, (ISNULL(B.KOMISTRA , 0)+ ISNULL(B.DIKAIOMA , 0)) AS KOM_DIKAIOMA, 
		B.IDPRAKTOREIO, B.PRAKTOREIODESCR,  ISNULL(B.PROPLMETROTHERXREOSEIS , 0) AS PROPLMETROTHERXREOSEIS,ISNULL(B.ANAMEXODO , 0) AS ANAMEXODO
FROM         --dbo.FORTOTIKES_VIEW AS FORTOTIKES_VIEW WITH(INDEX(IX_FORTOTIKES_ID))  LEFT OUTER JOIN
         dbo.FORTOTIKES_ANA_KAA AS B LEFT OUTER JOIN FORTOTIKES_VIEW 
        ON FORTOTIKES_VIEW.IDFORTOTIKIS = B.IDFORTOTIKIS LEFT OUTER JOIN
        dbo.ACCOUNTS AS ACCOUNTS WITH (NOLOCK) ON B.IDPARALIPTI = ACCOUNTS.id LEFT OUTER JOIN
        dbo.KAA AS KAA WITH (NOLOCK) ON B.IDKAA = KAA.ID LEFT OUTER JOIN
        dbo.TRUCKS AS TRUCKS WITH (NOLOCK) ON KAA.OXIMA = TRUCKS.ArKykloforias LEFT OUTER JOIN
        dbo.ODIGOI ON TRUCKS.ArKykloforias = dbo.ODIGOI.ArKikloforias LEFT OUTER JOIN ACCOUNTS AS ANTAP 
                      ON KAA.IDANTAPOKRITIS = ANTAP.id LEFT OUTER JOIN ACCOUNTS AS APOST 
                      ON B.IDAPOSTOLEA = APOST.id 
ORDER BY Code, NOPARAST





GO




