ALTER VIEW [dbo].[FORTOTIKESVOHLIGHT_VIEW]
AS

SELECT   DISTINCT  FORTOTIKES.ID, FORTOTIKES.DATEPRINT, KINDPARASTATIKON.Code, FORTOTIKES.PARASTATIKO, FORTOTIKES.SEIRA, 
                      CAST(FORTOTIKES.NOPARAST AS int) AS NOPARAST,
                      FORTOTIKES.IDXREOUMENOU AS IDCUSTOMER,  
                      CASE WHEN IFXRAPOST = 1 THEN ACCOUNTS.AFM 
                        ELSE 
                      CASE WHEN IFXRPARAL = 1 THEN ACCOUNTS_1.AFM  
						ELSE 
                      CASE WHEN IFXRENTOL = 1 THEN ACCOUNTS_2.AFM 
						ELSE 
					  CASE WHEN IFXRTRITOU = 1 THEN ACCOUNTS_3.AFM ELSE 'ΑΓΝΩΣΤΟΣ' 
                      END 
                      END 
                      END 
                      END AS AFM, 
                      CASE WHEN IFXRENTOL = 1 THEN ACCOUNTS_2.Eponimia 
						ELSE 
					  CASE WHEN IFXRAPOST = 1 THEN ACCOUNTS.Eponimia 
						ELSE 
					  CASE WHEN IFXRTRITOU = 1 THEN ACCOUNTS_3.Eponimia 
                        ELSE 
					  CASE WHEN IFXRPARAL = 1 THEN ACCOUNTS_1.Eponimia  ELSE 'ΑΓΝΩΣΤΟΣ' 
                      END 
                      END 
                      END 
                      END AS CustDescr,   
                      CASE WHEN IFXRAPOST = 1 THEN ACCOUNTS.Epagelma
                        ELSE 
                      CASE WHEN IFXRPARAL = 1 THEN ACCOUNTS_1.Epagelma
						ELSE   
                      CASE WHEN IFXRENTOL = 1 THEN ACCOUNTS_2.Epagelma 
						ELSE 
					  CASE WHEN IFXRTRITOU = 1 THEN ACCOUNTS_3.Epagelma ELSE 'ΑΓΝΩΣΤΟΣ' 
                      END 
                      END 
                      END 
                      END AS EPAGELMA, FORTOTIKES.POSO, 
                      (FORTOTIKES.SUMPOSO - FORTOTIKES.POSO) AS TAXIS, FORTOTIKES.SUMPOSO,   
                      FORTOTIKES.OXIMA, FORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
                      ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      CASE WHEN IFXRAPOST = 1 THEN ACCOUNTS.Code  
                        ELSE 
                      CASE WHEN IFXRPARAL = 1 THEN ACCOUNTS_1.Code
						ELSE 
					  CASE WHEN IFXRENTOL = 1 THEN ACCOUNTS_2.Code 
						ELSE 
					  CASE WHEN IFXRTRITOU = 1 THEN ACCOUNTS_3.Code  ELSE 'ΑΓΝΩΣΤΟΣ' 
                      END 
                      END 
                      END 
                      END AS CodeACCOUNT, FORTOTIKES.IDPRAKTOREIO, 
                      FORTOTIKES.IDENTOLEA, FORTOTIKES.IDAPOSTOLEA, FORTOTIKES.IDPARALIPTI, FORTOTIKES.IDTRITOU, FORTOTIKES.IDANTAPOKRITI,  
                      FORTOTIKES.AFMENTOLEA, FORTOTIKES.AFMAPOSTOLEA, FORTOTIKES.AFMPARALIPTI, FORTOTIKES.AFMTRITOU, FORTOTIKES.AFMANTAPOKRITI,
                      FORTOTIKES.PRAKTOREIODESCR, 
                      FORTOTIKES.ENTOLEASDESCR, FORTOTIKES.APOSTOLEASDESCR, FORTOTIKES.PARALISPTISDESCR, FORTOTIKES.TRITOSDESCR, FORTOTIKES.ANTAPOKRITISDESCR,
					  FORTOTIKES.IDXRHSHS, FORTOTIKES.IDCOMPANY,  FORTOTIKES.IDPARAST,
					  FORTOTIKES.UserMod, FORTOTIKES.DateMod, FORTOTIKES.UserCreate, FORTOTIKES.DateCreate, FORTOTIKES.IfDelete,
					  FORTOTIKES.KINDPAYMENTDESCR,FORTOTIKES.IDKINDPAYMENT,COMPANIES.Eponimia [YPOKATASTIMADESCR],FORTOTIKES.IDYPOKATASTIMA
			FROM FORTOTIKES WITH (NOLOCK) 
			LEFT JOIN ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDAPOSTOLEA = ACCOUNTS.id 
			LEFT JOIN ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON FORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id 
			LEFT JOIN ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON FORTOTIKES.IDENTOLEA = ACCOUNTS_2.id 
			LEFT JOIN ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON FORTOTIKES.IDTRITOU = ACCOUNTS_3.id 
			LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID 
			LEFT JOIN GRAMMESFORTTIKIS WITH (NOLOCK) ON FORTOTIKES.ID = GRAMMESFORTTIKIS.IDVOH 
			LEFT JOIN SUM_XREOSEIS_GRAMMES_FORTOTIKIS WITH (NOLOCK) ON FORTOTIKES.ID = SUM_XREOSEIS_GRAMMES_FORTOTIKIS.IDFORT 
			LEFT JOIN Units WITH (NOLOCK) ON GRAMMESFORTTIKIS.SYSKEVASIA = Units.UntID
			LEFT JOIN COMPANIES WITH (NOLOCK) ON COMPANIES.ID=FORTOTIKES.IDYPOKATASTIMA
WHERE FORTOTIKES.IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA=1 and IF_FROM_ANTAP=0)

UNION All

SELECT DISTINCT 
                      VOH.ID, VOH.DATEPRINT, KINDPARASTATIKON.Code, VOH.PARASTATIKO, VOH.SEIRA, VOH.NOPARAST, VOH.IDCUSTOMER, 
                      VOH.AFM, ACCOUNTS_1.Eponimia AS CustDescr, --VOH.IDENTOLEA AS IDCUSTOMER,
                      VOH.EPAGELMA, VOH.POSO, VOH.TAXIS, VOH.SUMPOSO, VOH.OXIMA, VOH.OMADPROORISMOS,  
                      CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE  
                      CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE
                      CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      VOH.CodeCustomer AS CodeACCOUNT,VOH.IDPRAKTOREIO, 
                      VOH.IDENTOLEA, VOH.IDAPOSTOLEA, VOH.IDPARALIPTI, VOH.IDTRITOU, VOH.IDANTAPOKRITI,  
					  VOH.AFMENTOLEA, VOH.AFMAPOSTOLEA, VOH.AFMPARALIPTI, VOH.AFMTRITOU, VOH.AFMANTAPOKRITI,
                      VOH.PRAKTOREIODESCR, 
                      VOH.ENTOLEASDESCR, VOH.APOSTOLEASDESCR, VOH.PARALISPTISDESCR, VOH.TRITOSDESCR, VOH.ANTAPOKRITISDESCR,
						VOH.IDXRHSHS, VOH.IDCOMPANY, 
                       VOH.IDPARAST, VOH.UserMod, VOH.DateMod, VOH.UserCreate, VOH.DateCreate, VOH.IfDelete,
					  VOH.KINDPAYMENTDESCR,VOH.IDKINDPAYMENT,COMPANIES.EPONIMIA [YPOKATASTIMADESCR],VOH.IDYPOKATASTIMA
			FROM VOH WITH (NOLOCK) LEFT JOIN ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON VOH.IDCUSTOMER = ACCOUNTS_1.id 
			LEFT JOIN GRAMMESVOH WITH (NOLOCK) ON VOH.ID = GRAMMESVOH.IDVOH 
			LEFT JOIN SUM_XREOSEIS_GRAMMES_VOH ON VOH.ID = SUM_XREOSEIS_GRAMMES_VOH.IDVOH AND SUM_XREOSEIS_GRAMMES_VOH.IF_TO_VOH = 1 
			LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON VOH.IDPARAST = KINDPARASTATIKON.ID 
			LEFT JOIN COMPANIES WITH (NOLOCK) ON COMPANIES.ID=VOH.IDYPOKATASTIMA
WHERE VOH.IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA=1)
UNION All

SELECT DISTINCT 
                      ESODA.ID, ESODA.DATEPRINT, KINDPARASTATIKON.Code, ESODA.PARASTATIKO, ESODA.SEIRA, ESODA.NOPARAST, ESODA.IDPROM AS IDCUSTOMER, 
                      ESODA.AFM, ACCOUNTS_1.Eponimia AS CustDescr, --VOH.IDENTOLEA AS IDCUSTOMER,
                      ACCOUNTS_1.EPAGELMA, ESODA.POSO, ESODA.TAXIS, ESODA.SUMPOSO, ESODA.OXIMA, '' AS OMADPROORISMOS,'ΑΓΝΩΣΤΟ' AS XREOYMENOS, 
                      ACCOUNTS_1.CODE AS CodeACCOUNT,IDPROM AS IDPRAKTOREIO, 
                      IDPROM AS IDENTOLEA, IDPROM AS IDAPOSTOLEA, IDPROM AS IDPARALIPTI, IDPROM AS IDTRITOU, IDPROM AS IDANTAPOKRITI,   
					  ACCOUNTS_1.AFM AS AFMENTOLEA, ACCOUNTS_1.AFM AS AFMAPOSTOLEA, ACCOUNTS_1.AFM AS AFMPARALIPTI, 
					  ACCOUNTS_1.AFM AS AFMTRITOU, ACCOUNTS_1.AFM AS AFMANTAPOKRITI,
                      ACCOUNTS_1.Eponimia AS PRAKTOREIODESCR, ACCOUNTS_1.Eponimia AS ENTOLEASDESCR, ACCOUNTS_1.Eponimia AS APOSTOLEASDESCR, 
                      ACCOUNTS_1.Eponimia AS PARALISPTISDESCR, ACCOUNTS_1.Eponimia AS TRITOSDESCR, ACCOUNTS_1.Eponimia AS ANTAPOKRITISDESCR,
					  ESODA.IDXRHSHS, ESODA.IDCOMPANY, 
                       ESODA.IDPARAST, ESODA.UserMod, ESODA.DateMod, ESODA.UserCreate, ESODA.DateCreate, ESODA.IfDelete,
					  ESODA.KINDPAYMENTDESCR,ESODA.IDKINDPAYMENT,COMPANIES.EPONIMIA [YPOKATASTIMADESCR],ESODA.IDYPOKATASTIMA
			FROM ESODA WITH (NOLOCK) 
			LEFT JOIN ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON ESODA.IDPROM = ACCOUNTS_1.id 
			LEFT JOIN GRAMMESVOH WITH (NOLOCK) ON ESODA.ID = GRAMMESVOH.IDVOH 
			LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON ESODA.IDPARAST = KINDPARASTATIKON.ID 
			LEFT JOIN COMPANIES WITH (NOLOCK) ON COMPANIES.ID=ESODA.IDYPOKATASTIMA
WHERE ESODA.IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA=1)

UNION All

SELECT DISTINCT 
                      EXODA.ID, EXODA.DATEPRINT, KINDPARASTATIKON.Code, EXODA.PARASTATIKO, EXODA.SEIRA, EXODA.NOPARAST, EXODA.IDPROM AS IDCUSTOMER, 
                      EXODA.AFM, ACCOUNTS_1.Eponimia AS CustDescr, --VOH.IDENTOLEA AS IDCUSTOMER,
                      ACCOUNTS_1.EPAGELMA, EXODA.POSO, EXODA.TAXIS, EXODA.SUMPOSO, EXODA.OXIMA, '' AS OMADPROORISMOS,'ΑΓΝΩΣΤΟ' AS XREOYMENOS, 
                      ACCOUNTS_1.CODE AS CodeACCOUNT,IDPROM AS IDPRAKTOREIO, 
                      IDPROM AS IDENTOLEA, IDPROM AS IDAPOSTOLEA, IDPROM AS IDPARALIPTI, IDPROM AS IDTRITOU, IDPROM AS IDANTAPOKRITI,   
					  ACCOUNTS_1.AFM AS AFMENTOLEA, ACCOUNTS_1.AFM AS AFMAPOSTOLEA, ACCOUNTS_1.AFM AS AFMPARALIPTI, 
					  ACCOUNTS_1.AFM AS AFMTRITOU, ACCOUNTS_1.AFM AS AFMANTAPOKRITI,    
                      ACCOUNTS_1.Eponimia AS PRAKTOREIODESCR, ACCOUNTS_1.Eponimia AS ENTOLEASDESCR, ACCOUNTS_1.Eponimia AS APOSTOLEASDESCR, 
                      ACCOUNTS_1.Eponimia AS PARALISPTISDESCR, ACCOUNTS_1.Eponimia AS TRITOSDESCR, ACCOUNTS_1.Eponimia AS ANTAPOKRITISDESCR,
					  EXODA.IDXRHSHS, EXODA.IDCOMPANY, 
                       EXODA.IDPARAST, EXODA.UserMod, EXODA.DateMod, EXODA.UserCreate, EXODA.DateCreate, EXODA.IfDelete,
					  EXODA.KINDPAYMENTDESCR,EXODA.IDKINDPAYMENT,COMPANIES.EPONIMIA [YPOKATASTIMADESCR],EXODA.IDYPOKATASTIMA
			FROM EXODA WITH (NOLOCK) 
			LEFT JOIN ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON EXODA.IDPROM = ACCOUNTS_1.id 
			LEFT JOIN GRAMMESVOH WITH (NOLOCK) ON EXODA.ID = GRAMMESVOH.IDVOH 
			LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON EXODA.IDPARAST = KINDPARASTATIKON.ID 
			LEFT JOIN COMPANIES WITH (NOLOCK) ON COMPANIES.ID=EXODA.IDYPOKATASTIMA
WHERE EXODA.IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA=1
					 AND KINDPARASTATIKON.ID IN(select ID_KINDPARASTATIKON from PARASTATIKA_ANA_KATHGORIA where ID_CAT_PARASTATIKON != 2))


UNION All
SELECT DISTINCT 
                      EXODA.ID, EXODA.DATEPRINT, KINDPARASTATIKON.Code, EXODA.PARASTATIKO, EXODA.SEIRA, EXODA.NOPARAST, EXODA.IDPROM AS IDCUSTOMER, 
                      EXODA.AFM, EMPLOYEE.Eponimia AS CustDescr, --VOH.IDENTOLEA AS IDCUSTOMER,
                      EMPLOYEE.EPAGELMA, EXODA.POSO, EXODA.TAXIS, EXODA.SUMPOSO, EXODA.OXIMA, '' AS OMADPROORISMOS,'ΑΓΝΩΣΤΟ' AS XREOYMENOS, 
                      EMPLOYEE.CODE AS CodeACCOUNT,IDPROM AS IDPRAKTOREIO, 
                      IDPROM AS IDENTOLEA, IDPROM AS IDAPOSTOLEA, IDPROM AS IDPARALIPTI, IDPROM AS IDTRITOU, IDPROM AS IDANTAPOKRITI,   
					  EMPLOYEE.AFM AS AFMENTOLEA, EMPLOYEE.AFM AS AFMAPOSTOLEA, EMPLOYEE.AFM AS AFMPARALIPTI, 
					  EMPLOYEE.AFM AS AFMTRITOU, EMPLOYEE.AFM AS AFMANTAPOKRITI,    
                      EMPLOYEE.Eponimia AS PRAKTOREIODESCR, EMPLOYEE.Eponimia AS ENTOLEASDESCR, EMPLOYEE.Eponimia AS APOSTOLEASDESCR, 
                      EMPLOYEE.Eponimia AS PARALISPTISDESCR, EMPLOYEE.Eponimia AS TRITOSDESCR, EMPLOYEE.Eponimia AS ANTAPOKRITISDESCR,
					  EXODA.IDXRHSHS, EXODA.IDCOMPANY, 
                      EXODA.IDPARAST, EXODA.UserMod, EXODA.DateMod, EXODA.UserCreate, EXODA.DateCreate, EXODA.IfDelete,
					  EXODA.KINDPAYMENTDESCR,EXODA.IDKINDPAYMENT,COMPANIES.Eponimia [YPOKATASTIMADESCR], EXODA.IDYPOKATASTIMA

			FROM EXODA WITH (NOLOCK) 
			LEFT JOIN EMPLOYEE WITH (NOLOCK) ON EXODA.IDPROM = EMPLOYEE.id 
			LEFT JOIN GRAMMESVOH WITH (NOLOCK) ON EXODA.ID = GRAMMESVOH.IDVOH 
			LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON EXODA.IDPARAST = KINDPARASTATIKON.ID 
			LEFT JOIN COMPANIES WITH (NOLOCK) ON COMPANIES.ID=EXODA.IDYPOKATASTIMA
WHERE EXODA.IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA=1 AND KINDPARASTATIKON.ID IN(select ID_KINDPARASTATIKON from PARASTATIKA_ANA_KATHGORIA where ID_CAT_PARASTATIKON = 2))






GO


---END SCRIPT 1550
