ALTER VIEW [dbo].[ENTOLES_SYNARMOLOGISIS_VIEW_NEW]
AS
select 
	
	case ISNULL(VOH.IFCHECKED, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFCHECKED], 														--  ΑΝ ΕΛΕΓΧΘΗΚΕ
	voh.identolea [IDENTOLEA],
