create VIEW [dbo].[ENTOLES_WITH_CBM]
AS

Select 
	V.ID,
	v.SEIRA + convert(nvarchar(20),(v.NOPARAST)) [AR.ENTOLIS],
	comp.Eponimia [YPOKATASTHMA],
	v.dateprint,
	v.IDENTOLEA,
	entol.Eponimia [ENTOLEAS],
	entol.Epagelma [EPAGGELMA_ENTOLEA],
	(ENTOL.AddressStr + ENTOL.AddressNo) [ADDRESS_ENTOLEA],
	ENTOL.AddressCity [CITY_ENTOLEA],
	ENTOL.AddressTK [TK_ENTOLEA],
	ENTOL.Tel [TILEFWNO_ENTOLEA],
	ENTOL.Mobile [KINHTO_ENTOLEA],
	HV.CodeCatalog,
	HV.DescrCatalog,
	V.IDPARALIPTI,
	PARAL.Eponimia [PARALIPTIS],
	PARAL.Epagelma [EPAGGELMA_PARALIPTI],
	(PARAL.AddressStr + PARAL.AddressNo) [ADDRESS_PARALIPTI],
	PARAL.AddressCity [CITY_PARALIPTI],
	PARAL.AddressTK [TK_PARALIPTI],
	PARAL.Tel [TILEFWNO_PARALIPTI],
	PARAL.Mobile [KINHTO_PARALIPTI],
	GV.[AR.EIDWN],
	GV.BAROS,
	GV.KYBIKA,
	GV.TEMAXIA,
	V.SERVICEZONE,
	V.IDKINDPAYMENT,
	V.KINDPAYMENTDESCR,
	V.POSO,
	V.TAXIS,
	V.SUMPOSO,
	V.UserCreate [CreatedBy]

from voh v
LEFT join companies comp on comp.id=v.IDYPOKATASTIMA
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id=V.IDENTOLEA
LEFT JOIN HEADERVOHPRICING HV ON HV.IDVOH=V.ID
LEFT JOIN ACCOUNTS PARAL ON PARAL.id=V.IDPARALIPTI
LEFT JOIN (
			SELECT
				IDVOH,
				COUNT(CODEEIDOS) [AR.EIDWN],
				SUM(BAROS) [BAROS],
				SUM(KYBIKA) [KYBIKA],
				SUM(PCS) [TEMAXIA]
			FROM GRAMMESVOH
			GROUP BY IDVOH
		  )GV ON GV.IDVOH=V.ID
JOIN KINDPARASTATIKON KP ON KP.ID=V.IDPARAST AND KP.IF_EDMETAFORAS=1
WHERE 
	V.ifDelete=0
AND V.IDXREOUMENOUENTOLIS = 0 
AND V.XREOUMENOSDESCRENTOLIS LIKE '%Άλλος%'
AND V.[ID] IN (SELECT DISTINCT(IDVOH) FROM VOHPRICING WHERE Descr='CBM')
GO


---END SCRIPT 1564
