ALTER VIEW [dbo].[FORTOTIKESLIGHT_VIEW]
AS
SELECT
        TOP (100) PERCENT dbo.FORTOTIKES.ID,
        dbo.FORTOTIKES.DATEPRINT,
        dbo.KINDPARASTATIKON.Code,
        dbo.FORTOTIKES.PARASTATIKO,
        dbo.FORTOTIKES.SEIRA,
        CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST,
        dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS,
        dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS,
        dbo.FORTOTIKES.OXIMA,
        dbo.FORTOTIKES.OMADPROORISMOS,
        CASE 
            WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' 
            ELSE CASE 
                WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' 
                ELSE CASE 
                    WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
                    ELSE CASE 
                        WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'                        
                        ELSE 'ΑΓΝΩΣΤΟ' 
                    END 
                END 
            END 
        END AS XREOYMENOS,
        dbo.ACCOUNTS.Eponimia AS APOSTOLEASDESCR,
        ACCOUNTS_1.Eponimia AS PARALISPTISDESCR,
        ACCOUNTS_2.Eponimia AS ENTOLEASDESCR,
        dbo.FORTOTIKES.ANTAPOKRITISDESCR,
        dbo.FORTOTIKES.NOLISTASDIANOMIS,
        CONVERT(VARCHAR,LISTADIANOMIS.DATEPRINT,103) [DATE_LISTAS_DIANOMIS],
        ACCOUNTS_3.Eponimia AS TRITOSDESCR,
        HEADERVOHPRICING.DESCRCATALOG AS TIMOKATALOGOS,
        MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA,
        dbo.FORTOTIKES.POSO,
        ROUND(MIN(dbo.FORTOTIKES.TAXIS),2) AS TAXISXREOSEON,
        ROUND(MIN(dbo.FORTOTIKES.SUMPOSO),2) AS SUMPOSOXRFORT,
        dbo.FORTOTIKES.TAXIS,
        dbo.FORTOTIKES.SUMPOSO,
        ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA),0) AS TEMAXIA,
        ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS),0) AS BAROS,
        ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA),0) AS KYBIKA,
        MIN(dbo.Units.UntName) AS SYSKEVASIA,
        CASE dbo.FORTOTIKES.IFPREPAY 
            WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) 
            ELSE 0 
        END AS XREOSIPROPLIROMENES,
        CASE dbo.FORTOTIKES.IFOFEILOMENI 
            WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) 
            ELSE 0 
        END AS XREOSIOFEILOMENES,
        CASE dbo.FORTOTIKES.IFPREPAY 
            WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH 
                WHEN 1 THEN MIN(FORTOTIKES.SUMPOSO) 
                ELSE 0 
            END 
            ELSE 0 
        END AS XREOSIPROPLIROMENESCASH,
        CASE dbo.FORTOTIKES.IFPREPAY 
            WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI 
                WHEN 1 THEN SUM(FORTOTIKES.SUMPOSO) 
                ELSE 0 
            END 
            ELSE 0 
        END AS XREOSIPROPLIROMENESPISTOSI,
        MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO,
        dbo.FORTOTIKES.PERIOXIFORTOSIS,
        dbo.FORTOTIKES.PERIOXIPARADOSIS,
        dbo.FORTOTIKES.COMMENTS,
        dbo.FORTOTIKES.SUMANTIK,
        dbo.FORTOTIKES.PRAKTOREIODESCR,
        dbo.FORTOTIKES.STATUS,
        dbo.FORTOTIKES.DATEPARAD,
        dbo.FORTOTIKES.IDAPOSTOLEA,
        dbo.FORTOTIKES.IDPARALIPTI,
        dbo.FORTOTIKES.IDENTOLEA,
        dbo.FORTOTIKES.IDANTAPOKRITI,
        dbo.FORTOTIKES.IDTRITOU,
        dbo.FORTOTIKES.IDPRAKTOREIO,
        CASE IFANTIKCASH 
            WHEN 0 THEN 0 
            ELSE ANTIKCASH 
        END AS ANTIKCASH,
        CASE IFANTIKEPIT 
            WHEN 0 THEN 0 
            ELSE ANTIKEPIT 
        END AS ANTIKEPIT,
        CASE IFANTIKSYNAL 
            WHEN 0 THEN 0 
            ELSE ANTIKSYNAL 
        END AS ANTIKSYNAL,
        CASE IFANTIKOTHER 
            WHEN 0 THEN 0 
            ELSE ANTIKOTHER 
        END AS ANTIKOTHER,
        CASE IFCANCELANTIK 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFCANCELANTIK,
        dbo.FORTOTIKES.COMMENTSANTIK,
        dbo.FORTOTIKES.DATEPARADOSI,
        dbo.FORTOTIKES.COMMENTS2,
        dbo.FORTOTIKES.EXODATRITON AS XREOSISTRITON,
        CASE dbo.FORTOTIKES.IFPREPAY 
            WHEN 1 THEN 'ΝΑΙ' 
            ELSE 'ΟΧΙ' 
        END AS IFPREPAY,
        dbo.FORTOTIKES.NO_EXT_ORDER,
        CASE dbo.FORTOTIKES.IFOFEILOMENI 
            WHEN 1 THEN 'ΝΑΙ' 
            ELSE 'ΟΧΙ' 
        END AS IFOFEILOMENI,
        ISNULL(MIN(dbo.GRAMMESFORTTIKIS.SUMPOSO),0) AS AXIA,
        CASE IFXRENTOL 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRENTOL,
        dbo.FORTOTIKES.KINDPAYMENTDESCR,
        dbo.FORTOTIKES.IDKINDPAYMENT,
        CASE IFXRAPOST 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRAPOST,
        CASE IFXRPARAL 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRPARAL,
        CASE IFXRTRITOU 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRTRITOU,
        dbo.FORTOTIKES.IFANTIKCASH,
        dbo.FORTOTIKES.IFANTIKEPIT,
        dbo.FORTOTIKES.IFANTIKSYNAL,
        dbo.FORTOTIKES.IFANTIKOTHER,
        dbo.FORTOTIKES.ifDelete,
        dbo.FORTOTIKES.IFCANCEL,
        dbo.FORTOTIKES.DATECANCEL,
        dbo.FORTOTIKES.DROMOLOGIO,
        dbo.FORTOTIKES.THESI,
        dbo.FORTOTIKES.IFPARADOSI,
        dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU,
        CONVERT(varchar,dbo.FORTOTIKES.DATEFORTOSIS,102) AS DATEFORTOSIS,
        dbo.FORTOTIKES.IFEPISTROFI,
        dbo.FORTOTIKES.DATEEPISTROFIS,
        dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS,
        dbo.FORTOTIKES.COMMENTSEPISTROFIS,
        dbo.FORTOTIKES.IFCASH,
