CREATE PROCEDURE [dbo].[updateKINDOFPAYMENTS]
(
	@id						NUMERIC(8,0),
	@DESCR					NVARCHAR(100)= NULL,
	@IF_IN					INT= 0,
	@IF_OUT					INT= 0,
	@KINDOFCALCULATION		INT= 0,
	@IF_CASH				INT= 0,
	@IFENDDATE				INT= 0,
	@PAY_AFTER				INT= 0,
	@PAY_AFTERDESCR			NVARCHAR(50)= NULL,
	@IF_EKDOSI				INT= 0,
	@CodeLog				NVARCHAR(50)= NULL,
	@IDCOMPANY				NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA			NUMERIC(18,0) = 0
	)
AS


SET NOCOUNT ON;
		
UPDATE KINDOFPAYMENTS SET 
	DESCR				=	@DESCR,
	IF_IN				=	@IF_IN,
	IF_OUT				=	@IF_OUT,
	KINDOFCALCULATION	=	@KINDOFCALCULATION,
	IF_CASH				=	@IF_CASH,
	IFENDDATE			=	@IFENDDATE,
	PAY_AFTER			=	@PAY_AFTER,
	PAY_AFTERDESCR		=	@PAY_AFTERDESCR,
	IF_EKDOSI			=	@IF_EKDOSI,
	CodeLog				=	@CodeLog,
	IDCOMPANY			=	@IDCOMPANY,
	IDYPOKATASTIMA		=	@IDYPOKATASTIMA

WHERE ID  = @ID;

GO

---END SCRIPT 1567
------------------------------------------------------------------------------------


