---NEW SCRIPT 1568

CREATE PROCEDURE [dbo].[InserttoKINDOFPAYMENTS]
(                  
	@DESCR					NVARCHAR(100)= NULL,
	@IF_IN					INT= 0,
	@IF_OUT					INT= 0,
	@KINDOFCALCULATION		INT= 0,
	@IF_CASH				INT= 0,
	@IFENDDATE				INT= 0,
	@PAY_AFTER				INT= 0,
	@PAY_AFTERDESCR			NVARCHAR(50)= NULL,
	@IF_EKDOSI				INT= 0,
	@CodeLog				NVARCHAR(50)= NULL,
	@IDCOMPANY				NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA			NUMERIC(18,0) = 0,
	@TheID					NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoKINDOFPAYMENTS', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000
--SELECT @@SPID [session_id], @RC [return code], GETDATE()

INSERT INTO KINDOFPAYMENTS
(
	DESCR,
	IF_IN,
	IF_OUT,
	KINDOFCALCULATION,
	IF_CASH,
	IFENDDATE,
	PAY_AFTER,
	PAY_AFTERDESCR,
	IF_EKDOSI,
	CodeLog,
	IDCOMPANY,
	IDYPOKATASTIMA
)
VALUES
(
	@DESCR,
	@IF_IN,
	@IF_OUT,
	@KINDOFCALCULATION,
	@IF_CASH,
	@IFENDDATE,
	@PAY_AFTER,
	@PAY_AFTERDESCR,
	@IF_EKDOSI,
	@CodeLog,
	@IDCOMPANY,
	@IDYPOKATASTIMA
)

SET @TheID = (SELECT MAX(ID) AS ID FROM dbo.KINDOFPAYMENTS WITH (NOLOCK))
waitfor delay '00:00:00:40'            
commit;

GO

---END SCRIPT 1568
------------------------------------------------------------------------------------




