ALTER VIEW [dbo].[ANTIKATAVOLESPERDAY_VIEW]
AS

               SELECT     dbo.FORTOTIKES.ID, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, dbo.FORTOTIKES.NOPARAST, 
                      cast(DATEPART(day, dbo.FORTOTIKES.DATEPRINT)as varchar) +'/' + cast(DATEPART(month, dbo.FORTOTIKES.DATEPRINT)as varchar)  + '/' + cast(DATEPART(year, dbo.FORTOTIKES.DATEPRINT)as varchar) AS DATERINT,
                      dbo.FORTOTIKES.POSO, dbo.FORTOTIKES.TAXISPERCENT, dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, 
                      dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, '' AS STATUS,  dbo.FORTOTIKES.DRIVERDESCR, 
                      CASE IFXRAPOST WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRAPOST, dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.APOSTOLEASDESCR, 
                      CASE IFXRPARAL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRPARAL, dbo.FORTOTIKES.IDPARALIPTI, dbo.FORTOTIKES.PARALISPTISDESCR, 
                      CASE IFXRENTOL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRENTOL, dbo.FORTOTIKES.IDENTOLEA, dbo.FORTOTIKES.ENTOLEASDESCR, 
                      CASE IFXRTRITOU WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRTRITOU, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.TRITOSDESCR, 
                      dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.ANTAPOKRITISDESCR, dbo.FORTOTIKES.IFANTIKCASH, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, 
                      CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, dbo.FORTOTIKES.SUMANTIK, 
                      CASE IFCANCELANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFCANCELANTIK, 
                      CASE IFCANCELANTIK WHEN 0 THEN NULL ELSE dbo.FORTOTIKES.DATECANCELANTIK END AS DATECANCELANTIK,  
                      dbo.FORTOTIKES.COMMENTSANTIK,  FORTOTIKES.NOLISTASANTIK, 
                      CASE IFPARADOSIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARADOSIANTIK, 
                      CASE IFPARADOSIANTIK WHEN 0 THEN NULL ELSE dbo.FORTOTIKES.DATEPARADANTIK  END AS DATEPARADANTIK,
                      CASE IFEISPRANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFEISPRANTIK, 
                      CASE IFEISPRANTIK WHEN 0 THEN NULL ELSE dbo.FORTOTIKES.DATEEISPRANTIK  END AS DATEEISPRANTIK,  
                      CASE IFPARALAVIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARALAVIANTIK, 
                      CASE IFPARALAVIANTIK WHEN 0 THEN NULL ELSE dbo.FORTOTIKES.DATEPARALANTIK END AS DATEPARALANTIK,  
                      dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, dbo.FORTOTIKES.STATUS AS Expr1, MIN(SUM_XREOSEIS_GRAMMES_FORTOTIKIS.TIMDA) AS TIMDA, 
                      dbo.FORTOTIKES.IDPARAST, dbo.FORTOTIKES.IFXRENTOL AS Expr2, dbo.FORTOTIKES.IFXRPARAL AS Expr3, dbo.FORTOTIKES.IFXRTRITOU AS Expr4, 
                      dbo.FORTOTIKES.IFXRAPOST AS Expr5, dbo.FORTOTIKES.ANTIKCASH AS Expr6, dbo.FORTOTIKES.ANTIKEPIT AS Expr7, dbo.FORTOTIKES.ANTIKSYNAL AS Expr8, 
                      dbo.FORTOTIKES.ANTIKOTHER AS Expr9, dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.ifDelete,
                      dbo.FORTOTIKES.OMADPROORISMOS, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, dbo.FORTOTIKES.DATEFORTOSIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.IFEPISTROFI, 
                      dbo.FORTOTIKES.DATEEPISTROFIS, dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, 
                      dbo.FORTOTIKES.IFPISTOSI, dbo.FORTOTIKES.IFPREPAY, dbo.FORTOTIKES.IFOFEILOMENI, dbo.FORTOTIKES.IDPRAKTOREIO, 
                      dbo.FORTOTIKES.IDYPOKEISPRANTIK, dbo.FORTOTIKES.IDYPOKPARALANTIK, dbo.FORTOTIKES.IDYPOKPARADANTIK, 
                      dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, 
                      dbo.FORTOTIKES.IFEPANEKDOSI, dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, 
                      dbo.FORTOTIKES.NOLISTASDIANOMIS, dbo.FORTOTIKES.IDXRHSHS, dbo.FORTOTIKES.IDCOMPANY, dbo.FORTOTIKES.IDYPOKATASTIMA
FROM         dbo.FORTOTIKES  WITH(NOLOCK) LEFT OUTER JOIN
                      dbo.KINDPARASTATIKON  WITH(NOLOCK) ON dbo.FORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID 
                      INNER JOIN SUM_XREOSEIS_GRAMMES_FORTOTIKIS WITH(NOLOCK)  ON 
                      FORTOTIKES.ID = SUM_XREOSEIS_GRAMMES_FORTOTIKIS.IDFORT 
WHERE     (dbo.FORTOTIKES.IFANTIKCASH = 1) AND (dbo.FORTOTIKES.IFCANCELANTIK <> 1) OR
                      (dbo.FORTOTIKES.IFCANCELANTIK <> 1) AND (dbo.FORTOTIKES.IFANTIKEPIT = 1) OR
                      (dbo.FORTOTIKES.IFCANCELANTIK <> 1) AND (dbo.FORTOTIKES.IFANTIKSYNAL = 1) OR
                      (dbo.FORTOTIKES.IFCANCELANTIK <> 1) AND (dbo.FORTOTIKES.IFANTIKOTHER = 1)
                      GROUP BY 
                      dbo.FORTOTIKES.ID, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, dbo.FORTOTIKES.NOPARAST, 
                      dbo.FORTOTIKES.DATEPRINT, dbo.FORTOTIKES.POSO, dbo.FORTOTIKES.TAXISPERCENT, dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, 
                      dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.KINDPAYMENTDESCR, dbo.FORTOTIKES.IDKINDPAYMENT, dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.ANTAPOKRITISDESCR, 
                      dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.COMMENTSANTIK, dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, 
                      dbo.FORTOTIKES.IDPARAST, dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.OMADPROORISMOS, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, 
                      dbo.FORTOTIKES.DATEFORTOSIS, dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.FORTOTIKES.IFEPISTROFI, 
                      dbo.FORTOTIKES.DATEEPISTROFIS, dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, 
                      dbo.FORTOTIKES.IFPISTOSI, dbo.FORTOTIKES.IFPREPAY, dbo.FORTOTIKES.IFOFEILOMENI, dbo.FORTOTIKES.IDPRAKTOREIO,  dbo.FORTOTIKES.DRIVERDESCR, 
                      dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, 
                      dbo.FORTOTIKES.IFEPANEKDOSI, dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, 
                      dbo.FORTOTIKES.NOLISTASDIANOMIS, dbo.FORTOTIKES.IDXRHSHS, dbo.FORTOTIKES.IDCOMPANY, dbo.FORTOTIKES.IDYPOKATASTIMA , 
                      dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.APOSTOLEASDESCR, dbo.FORTOTIKES.IDPARALIPTI, dbo.FORTOTIKES.PARALISPTISDESCR, 
                      dbo.FORTOTIKES.IDENTOLEA, dbo.FORTOTIKES.ENTOLEASDESCR, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.TRITOSDESCR, dbo.FORTOTIKES.IFANTIKCASH, ANTIKCASH,
                      dbo.FORTOTIKES.IFANTIKEPIT, ANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, ANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, ANTIKOTHER, dbo.FORTOTIKES.IFPARADOSIANTIK, 
                      dbo.FORTOTIKES.SUMANTIK, IFXRAPOST, dbo.FORTOTIKES.IFXRPARAL, IFCANCELANTIK,DATECANCELANTIK, STATUS, dbo.FORTOTIKES.IFXRENTOL, dbo.FORTOTIKES.IFXRTRITOU, 
                      dbo.FORTOTIKES.IDYPOKEISPRANTIK, dbo.FORTOTIKES.IDYPOKPARALANTIK, dbo.FORTOTIKES.IDYPOKPARADANTIK,  FORTOTIKES.NOLISTASANTIK, 
                      dbo.FORTOTIKES.DATEPARADANTIK, dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.DATEEISPRANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK, dbo.FORTOTIKES.DATEPARALANTIK, dbo.FORTOTIKES.ifDelete




