ALTER VIEW [dbo].[ISOZYGIO_PAYMENTS_RECEIPTS_SUM_PERDAY] 
AS 
SELECT '105-' + CAST(ID AS NVARCHAR(20)) AS ID, IDVOH, 
	CONVERT(VARCHAR(10), DATEPRINT, 103) AS DATEPRINT,
	IF_TO_FORTOTIKI, 
	IF_TO_VOH, 
	0 AS IF_TO_EXODA, 
	IF_TO_ESODA, 
	IDKINDPARAST,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '1.Μετρητοίς' OR KINDPAYMENTDESCR = 'Μετρητοίς') THEN SUMPOSO ELSE 0 END) METRITA,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '3.Έμβασμα' OR KINDPAYMENTDESCR = 'Έμβασμα') THEN SUMPOSO ELSE 0 END) EMVASMA,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '4.Επιταγή' OR KINDPAYMENTDESCR = 'Επιταγή') THEN SUMPOSO ELSE 0 END) EPITAGI,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '5.Συναλαγματική' OR KINDPAYMENTDESCR = 'Συναλαγματική') THEN SUMPOSO ELSE 0 END) SYNALAGMATIKI,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '6.Κάρτα Visa' OR KINDPAYMENTDESCR = 'Κάρτα Visa') THEN SUMPOSO ELSE 0 END) VISACARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '7.Κάρτα MasterCard' OR KINDPAYMENTDESCR = 'Κάρτα MasterCard') THEN SUMPOSO ELSE 0 END) MASTERCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '8.Κάρτα American Express' OR KINDPAYMENTDESCR = 'Κάρτα American Express') THEN SUMPOSO ELSE 0 END) AMEXPRESSCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '9.Κάρτα Diners' OR KINDPAYMENTDESCR = 'Κάρτα Diners') THEN SUMPOSO ELSE 0 END) DINERSCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR != '1.Μετρητοίς' AND KINDPAYMENTDESCR != 'Μετρητοίς' 
				AND KINDPAYMENTDESCR != '4.Επιταγή' AND KINDPAYMENTDESCR != 'Επιταγή' 
				AND KINDPAYMENTDESCR != '3.Έμβασμα' AND KINDPAYMENTDESCR != 'Έμβασμα')THEN SUMPOSO ELSE 0 END) ALLO, 
  ifDelete, 
  IDXRHSHS, 
  IDCOMPANY, 
  IDYPOKATASTIMA, 
  UserCreate, 
  UserMod--,
  --SUM(case when KINDPAYMENTDESCR = 'Συναλαγματική' then SUMPOSO end) LastName,
  --SUM(case when KINDPAYMENTDESCR = 'Επι πιστώσει' then SUMPOSO end) Accounmber
FROM RECEIPTS  
GROUP BY  ID, IDVOH, DATEPRINT, IDKINDPAYMENT, KINDPAYMENTDESCR,  ifDelete, IDXRHSHS, IDCOMPANY, 
IF_TO_FORTOTIKI, IF_TO_VOH, IF_TO_ESODA, IDKINDPARAST,
 IDYPOKATASTIMA, UserCreate, UserMod
UNION
SELECT 
	'106-' + CAST(ID AS NVARCHAR(20)) AS  ID,
	 IDVOH, 
	 CONVERT(VARCHAR(10), DATEPRINT, 103) AS DATEPRINT,
	 IF_TO_FORTOTIKI, IF_TO_VOH, IF_TO_EXODA, 0 AS IF_TO_ESODA, IDKINDPARAST,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '1.Μετρητοίς' OR KINDPAYMENTDESCR = 'Μετρητοίς') THEN SUMPOSO*(-1) ELSE 0 END) METRITA,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '3.Έμβασμα' OR KINDPAYMENTDESCR = 'Έμβασμα') THEN SUMPOSO*(-1) ELSE 0 END) EMVASMA,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '4.Επιταγή' OR KINDPAYMENTDESCR = 'Επιταγή') THEN SUMPOSO*(-1) ELSE 0 END) EPITAGI,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '5.Συναλαγματική' OR KINDPAYMENTDESCR = 'Συναλαγματική') THEN SUMPOSO*(-1) ELSE 0 END) SYNALAGMATIKI,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '6.Κάρτα Visa' OR KINDPAYMENTDESCR = 'Κάρτα Visa') THEN SUMPOSO*(-1) ELSE 0 END) VISACARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '7.Κάρτα MasterCard' OR KINDPAYMENTDESCR = 'Κάρτα MasterCard') THEN SUMPOSO*(-1) ELSE 0 END) MASTERCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '8.Κάρτα American Express' OR KINDPAYMENTDESCR = 'Κάρτα American Express') THEN SUMPOSO*(-1) ELSE 0 END) AMEXPRESSCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR = '9.Κάρτα Diners' OR KINDPAYMENTDESCR = 'Κάρτα Diners') THEN SUMPOSO*(-1) ELSE 0 END) DINERSCARD,
  SUM(CASE WHEN (KINDPAYMENTDESCR != '1.Μετρητοίς' AND KINDPAYMENTDESCR != 'Μετρητοίς' AND KINDPAYMENTDESCR != '4.Επιταγή' 
  AND KINDPAYMENTDESCR != 'Επιταγή' AND KINDPAYMENTDESCR != '3.Έμβασμα' AND KINDPAYMENTDESCR != 'Έμβασμα') THEN ((-1) * SUMPOSO) ELSE 0 END) ALLO, 
  ifDelete, IDXRHSHS, IDCOMPANY, IDYPOKATASTIMA, UserCreate, UserMod--,
  --SUM(case when KINDPAYMENTDESCR = 'Συναλαγματική' then SUMPOSO end) LastName,
  --SUM(case when KINDPAYMENTDESCR = 'Επι πιστώσει' then SUMPOSO end) Accounmber
FROM PAYMENTS  
GROUP BY  ID, IDVOH, DATEPRINT, IDKINDPAYMENT, KINDPAYMENTDESCR, ifDelete, IDXRHSHS, IDCOMPANY, 
IF_TO_FORTOTIKI, IF_TO_VOH, IF_TO_EXODA, IDKINDPARAST, IDYPOKATASTIMA, UserCreate, UserMod 






GO



---END SCRIPT 1573
