	@PAY_AFTERDESCR			NVARCHAR(50)= NULL,
	@IF_EKDOSI				INT= 0,
	@CodeLog				NVARCHAR(50)= NULL,
	@IF_PISTOSI				INT = 0,
	@IF_EMVASMA				INT = 0,
	@IF_EPITAGI				INT = 0,
	@IF_SYNALAGMATIKI		INT = 0,
	@IF_KARTA				INT = 0,
