	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoKINDOFPAYMENTS', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000
--SELECT @@SPID [session_id], @RC [return code], GETDATE()

INSERT INTO KINDOFPAYMENTS
(
	DESCR,
	IF_IN,
	IF_OUT,
	KINDOFCALCULATION,
	IF_CASH,
	IFENDDATE,
	PAY_AFTER,
	PAY_AFTERDESCR,
	IF_EKDOSI,
	CodeLog,
	IF_PISTOSI,
	IF_EMVASMA,
	IF_EPITAGI,
	IF_SYNALAGMATIKI,
	IF_KARTA,
	IF_MASTER,
	IF_VISA,
	IF_DINERS,
	IF_AMEXPRESS,	
	IDCOMPANY,
	IDYPOKATASTIMA
)
VALUES
(
	@DESCR,
	@IF_IN,
	@IF_OUT,
	@KINDOFCALCULATION,
	@IF_CASH,
	@IFENDDATE,
	@PAY_AFTER,
	@PAY_AFTERDESCR,
	@IF_EKDOSI,
	@CodeLog,
	@IF_PISTOSI,
	@IF_EMVASMA,
	@IF_EPITAGI,
	@IF_SYNALAGMATIKI,
	@IF_KARTA,
	@IF_MASTER,
	@IF_VISA,
	@IF_DINERS,
	@IF_AMEXPRESS,	
	@IDCOMPANY,
	@IDYPOKATASTIMA
)

SET @TheID = (SELECT MAX(ID) AS ID FROM dbo.KINDOFPAYMENTS WITH (NOLOCK))
waitfor delay '00:00:00:40'            
commit;

GO

