ALTER VIEW [dbo].[SUMPOSA_PER_ACCOUNT_PEL]
AS 
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDPARASTATIKON.IF_XREOSI) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA 
FROM FORTOTIKES LEFT JOIN KINDPARASTATIKON ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_XREOSI = 1 
AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) LEFT OUTER JOIN
PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID INNER JOIN
CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0
INNER JOIN ACCOUNTS ON FORTOTIKES.IDXREOUMENOU = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE FORTOTIKES.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, 
ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA 
 UNION 
 SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
 SUM(SUMPOSO * KINDPARASTATIKON.IF_PISTOSI) * (-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA  
 FROM FORTOTIKES LEFT JOIN KINDPARASTATIKON ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_PISTOSI = 1 
 AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) LEFT OUTER JOIN
PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID INNER JOIN
CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0
 INNER JOIN ACCOUNTS ON FORTOTIKES.IDXREOUMENOU = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE FORTOTIKES.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, 
ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM((VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) * IF_XREOSI) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, VOH.IDCOMPANY, VOH.IDYPOKATASTIMA  
FROM VOH LEFT JOIN KINDPARASTATIKON ON VOH.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_XREOSI = 1 
AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1  AND KINDPARASTATIKON.KindKINISIS IN(1, 5)
INNER JOIN ACCOUNTS ON VOH.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE VOH.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, 
ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, VOH.IDCOMPANY, VOH.IDYPOKATASTIMA  
 UNION 
 SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
 SUM((VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) * KINDPARASTATIKON.IF_PISTOSI) * (-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, VOH.IDCOMPANY, VOH.IDYPOKATASTIMA  
 FROM VOH LEFT JOIN KINDPARASTATIKON ON VOH.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_PISTOSI = 1 
 AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1  AND KINDPARASTATIKON.KindKINISIS  IN( 1,5)
 INNER JOIN ACCOUNTS ON VOH.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE VOH.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, 
ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, VOH.IDCOMPANY, VOH.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * IF_XREOSI) * (1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA  
FROM ESODA LEFT JOIN KINDPARASTATIKON ON ESODA.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_XREOSI = 1 
AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5)
INNER JOIN ACCOUNTS ON ESODA.IDPROM = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE ESODA.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, 
ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA  
 UNION 
 SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
 SUM(SUMPOSO * KINDPARASTATIKON.IF_PISTOSI) * (-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA  
 FROM ESODA LEFT JOIN KINDPARASTATIKON ON ESODA.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_PISTOSI = 1 
 AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5)
 INNER JOIN ACCOUNTS ON ESODA.IDPROM = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE ESODA.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, 
ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDPARASTATIKON.IF_PISTOSI)*(-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA 
FROM RECEIPTS LEFT JOIN KINDOFPAYMENTS ON RECEIPTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID AND KINDOFPAYMENTS.IF_CASH = 1-- AND IF_IN = 1 
LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON RECEIPTS.IDKINDPARAST = KINDPARASTATIKON.ID 
INNER JOIN ACCOUNTS ON RECEIPTS.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE RECEIPTS.ifDelete = 0 
AND (IFENIMEROSITAMEIO = 1 OR IF_ENIMEROSIKARTELA = 1)  
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * IF_XREOSI)*(1) AS SUMPOSO,DATEPRINT,  ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA  
FROM RECEIPTS LEFT JOIN KINDOFPAYMENTS ON RECEIPTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID AND KINDOFPAYMENTS.IF_CASH = 1-- AND IF_OUT = 1
LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON RECEIPTS.IDKINDPARAST = KINDPARASTATIKON.ID
INNER JOIN ACCOUNTS ON RECEIPTS.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE RECEIPTS.ifDelete = 0 
AND ((IFENIMEROSITAMEIO = 1 OR IF_ENIMEROSIKARTELA = 1) AND IF_AFORAEXTRITON != 1)
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA  




