	@IF_ZERO_ON_NEW_YEAR		INT= 0,
	@IF_PRINT					INT=0,
	@PREPORT					NVARCHAR(255),
	@TAXISPERCENT				NUMERIC(18,0)=0,
	@IF_XREOSI					INT= 0,
	@IfMisthodosia				INT=0,
	@IfFortotiki				INT=0,
	@IF_PISTOSI					INT= 0,
	@IfKAA						INT= 0,
	@IFPROFORTOTIKI				INT= 0,
