ALTER PROCEDURE [dbo].[updateCATPARAST]
(
	@IDPARAST					NUMERIC(8,0)= NULL,
	--@AFORA						NVARCHAR(100),
	@PARASTATIKO				NVARCHAR(150),
	@IDAFORA					NUMERIC(8,0)= NULL,
