	@IFKEPXREOSI				INT= 0,
	@IFKEPPISTOSI				INT= 0,
	@IFPROFORTOTIKI				INT= 0,
	@IFKEPYO					INT= 0,
	@IF_LISTAANTIKATABOLON		INT = 0,
	--@IFCASH						int = NULL,
	--@IFPISTOSI					int = NULL,
	--@IFOFEILOMENI				int = NULL,
	--@IFPREPAY					int = NULL,
	@CATKEPYO					int = 0,
	@SEIRA						NVARCHAR(5),
	@PROEPSXOLIO				NVARCHAR(150) = NULL,
	@PrinterName				NVARCHAR(50) = NULL,
	@IfPreviewFirst				int = 0,
	@PRINTLABEL					NVARCHAR(50),
	@IDPARASTEXOFLISI			NUMERIC(18,0)=0,
	@DESCRPARASTEXOFLISI		NVARCHAR(30),
	@IF_ENIMEROSIAPOTHIKI		INT =0,
	@IFEXAGOGI					INT =0,
	@IFEISAGOGI					INT =0,
	@IF_PAROXIYPIRESION			INT =0,
	@IF_ORDER					INT = 0,
	@IF_PRODROMOL				INT = 0,
	@IF_FROM_ANTAP				INT = 0,
	@IDCOMPANY					numeric(18,0) =0,
	@IDYPOKATASTIMA				numeric(18,0) =0,
	@CodeLog					NVARCHAR(30),
	@Copies						int = 1,
	@IF_EDMETAFORAS				INT = 0,
	@IF_EDSYNARMOL				INT = 0,
	@IS_CANCELLATION			INT = 0,
	@IF_LISTA_ASS				INT = 0,
	--@IF_EDTOPOTH				INT = 0,
	@WEBPARASTATIKO				INT = 0,
	@IF_ENIMEROSI_AADE			INT = 0,
	@AADE_CODE					NVARCHAR(30),
	@VoucherTypeCode			NVARCHAR(3)
		)
AS
-- TASK 
-- TASK 
	DECLARE @KINDKINISIS 	INT
	DECLARE @TRACOUNT 	INT
	DECLARE @ErrorNumber 	INT
	DECLARE @ErrorDescription NVARCHAR(255)
	DECLARE @Rowcount	INT
	DECLARE @RetVal 	INT
	DECLARE @Number 	NVARCHAR(30)	
	DECLARE @IDOC_COMM	INT
	DECLARE @IDOC_XRE	INT
	DECLARE @CAN_PRINT   	BIT
	DECLARE @ID 		INT
	DECLARE @RET_BATCH_NUM	NVARCHAR(30)
	DECLARE @Courier_Group_Code NVARCHAR(5)

	SET NOCOUNT ON
	SET @ErrorNumber = 0

	SET @TRACOUNT = @@TRANCOUNT
	IF @TRACOUNT = 0 
	--EISAGOGI TOY PARALIPTI EAN DEN YPARXEI STO PINAKA MAS
	--***************************************************************************
	DECLARE @RowCountPelati INT
	DECLARE @ClientCode INT
	DECLARE @ClientTownCode NVARCHAR(10)
	DECLARE @ClientRegionCode NVARCHAR(10) --TASK 12899
	DECLARE @PelatesAddr	NVARCHAR(60) --TASK 11593
	DECLARE @PelatesProfID	NVARCHAR(30) --TASK 11623
	SET @RowCountPelati=0

	IF @IDAFORA = 0
		BEGIN 	
			SET @KINDKINISIS = 1 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 1
		BEGIN 	
			SET @KINDKINISIS = 0 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 4
		BEGIN 	
			SET @KINDKINISIS = 99 --@KINDKINISIS = 1
		END 
		
	IF @IDAFORA = 5
		BEGIN 	
			SET @KINDKINISIS = 5 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 6
		BEGIN 	
			SET @KINDKINISIS = 6 --@KINDKINISIS = 1
		END 


		BEGIN
			UPDATE KINDPARASTATIKON
				SET
				Code					=		@CODEPARAST,
				Descr					=		@PARASTATIKO,
				KindKINISIS				=		@KINDKINISIS,
				KindYpologismou			=		@KINDENIMEROSI,
				IFENIMEROSITAMEIO		=		@IFENIMEROSITAMEIO,
				TRANSFORMTO				=		@TRANSFORMTO,
				IF_AUTONUMBER			=		@IF_AUTONUMBER,
				IF_TRANSFORM			=		@IF_TRANSFORM,
				AUTONUMBER_FROM			=		@AUTONUMBER_FROM,
				IF_ZERO_ON_NEW_YEAR		=		@IF_ZERO_ON_NEW_YEAR,
				IF_PRINT				=		@IF_PRINT,
				PREPORT					=		@PREPORT,
				TAXISPERCENT			=		@TAXISPERCENT,
				IF_XREOSI				=		@IF_XREOSI,
				IF_PISTOSI				=		@IF_PISTOSI,
				IfMisthodosia			=		@IfMisthodosia,
				IfFortotiki				=		@IfFortotiki,
				IfKAA					=		@IfKAA,
				IF_ENIMEROSIKARTELA		=		@IF_ENIMEROSIKARTELA,
				IF_XREOSIKARTELA		=		@IF_XREOSIKARTELA,
				IF_PISTOSIKARTELA		=		@IF_PISTOSIKARTELA,
				SEIRA					=		@SEIRA,
				IFKEPXREOSI				=		@IFKEPXREOSI,
				IFKEPPISTOSI			=		@IFKEPPISTOSI,
				IFPROFORTOTIKI			=		@IFPROFORTOTIKI,
				IFKEPYO					=		@IFKEPYO,
				PRINTLABEL				=		@PRINTLABEL,
				PROEPSXOLIO				=		@PROEPSXOLIO,
				IfPreviewFirst			=		@IfPreviewFirst,
				PrinterName				=		@PrinterName,
				IDPARASTEXOFLISI		=		@IDPARASTEXOFLISI,
				DESCRPARASTEXOFLISI		=		@DESCRPARASTEXOFLISI, 
				IF_ENIMEROSIAPOTHIKI	=		@IF_ENIMEROSIAPOTHIKI,
				IFEISAGOGI				=		@IFEISAGOGI,
				IFEXAGOGI				=		@IFEXAGOGI,	
				IF_PAROXIYPIRESION		=		@IF_PAROXIYPIRESION,
				IF_ORDER				=		@IF_ORDER,
				IDCOMPANY				=		@IDCOMPANY,
				IDYPOKATASTIMA			=		@IDYPOKATASTIMA,
				IF_LISTADIANOMIS		=		@IF_LISTADIANOMIS,
				IF_PRODROMOL			=		@IF_PRODROMOL,
				IF_LISTAANTIKATABOLON	=		@IF_LISTAANTIKATABOLON,
				IF_FROM_ANTAP			=		@IF_FROM_ANTAP,
				--IFCASH					=		@IFCASH,
				--IFPISTOSI				=		@IFPISTOSI,
				--IFOFEILOMENI			=		@IFOFEILOMENI,
				--IFPREPAY				=		@IFPREPAY,
				CATKEPYO				=		@CATKEPYO,
				CodeLog					=		@CodeLog,	
				Copies					=		@Copies,
				IF_EDMETAFORAS			=		@IF_EDMETAFORAS,
				IF_EDSYNARMOL			=		@IF_EDSYNARMOL,
				IS_CANCELLATION			=		@IS_CANCELLATION,
				IF_LISTA_ASS			=		@IF_LISTA_ASS,
				WEBPARASTATIKO			=		@WEBPARASTATIKO,
				IF_ENIMEROSI_AADE		=		@IF_ENIMEROSI_AADE,
				AADE_CODE				=		@AADE_CODE,
				--IF_EDTOPOTH				=		@IF_EDTOPOTH,
				VoucherTypeCode			=		@VoucherTypeCode

				WHERE ID = @IDPARAST
		END
--'''''''''''''''''''''''''''''''''''''''''''''''''''
		BEGIN
			DELETE FROM PARASTATIKA_ANA_KATHGORIA WHERE ID_KINDPARASTATIKON = @IDPARAST --AND  ID_CAT_PARASTATIKON = @IDCATPARAST
			INSERT INTO PARASTATIKA_ANA_KATHGORIA
				(
				ID_CAT_PARASTATIKON,
				ID_KINDPARASTATIKON
				)
			VALUES
				(
				@IDCATPARAST,
				@IDPARAST
				)
		END
--...................................................
	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************


ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint

GO


