ALTER VIEW [dbo].[ENTOLES_SYNARMOLOGISIS_VIEW_NEW]
AS
select 
	
	case ISNULL(VOH.IFCHECKED, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFCHECKED], 														--  ΑΝ ΕΛΕΓΧΘΗΚΕ
	voh.identolea [IDENTOLEA],
	paraliptis.id [IDPARALIPTI],
	apostoleas.id [IDAPOSTOLEA],
	kentrakostous.id [IDKENTROKOSTOUS],
	sugkentrotiko.id [IDSYGKENTROTIKO],
	voh.idparast [IDPARAST],
	VOH.IDXRHSHS,
	VOH.IDCOMPANY,
	companies.id [IDYPOKATASTIMA],
	companies.Eponimia [YPOKATASTHMA], 										--[Κατάστημα Εντολής],
	convert(date, voh.Dateprint) [DATEPRINT], 								--[Ημερομηνία Εντολής],
	RTRIM(timol.SEIRA)+ convert(nvarchar(20),timol.NOPARAST) as NOTIMOL,							--[Αριθμός που Τιμολογήθηκε η Εντολή]
	rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE], 	--[Barcode ID Παραστατικού],
	cast(voh.SUMPOSO as float) [SUMPOSO], 									--[Αξία Παραστατικού (Συνολική)],
	month(voh.DATEPRINT) [MONTHDATE], 										--[Μήνας Εντολής],
	LISTESSYNARMOLOGISIS.DATEPRINT	[DATE_LISTAS_ASS],						--[Ημερ. Λίστας Ανάθεσης],
	listessynarmologisis.PARASTATIKO [PARASTATIKO_ASS],						--[Παραστατικό Ανάθεσης],
	listessynarmologisis.EMPLOYEE [SYNERGATIS],								--[Συνεργάτης],
	rtrim(listessynarmologisis.seira)+ CONVERT(NVARCHAR(20), listessynarmologisis.NOPARAST) [NOPARAST_LISTAS_ASS], --[Αρ.Λίστας Ανάθεσης],
	VOH.EMPLOYEE,
	paraliptis.Eponimia [PARALISPTISDESCR], 								--[Επωνυμία Παραλήπτη],
	paraliptis.Mobile [PARALIPTIS_MOBILE], 									--[Κινητό Τηλέφωνο Παραλήπτη],
	paraliptis.AddressCity [PARALIPTIS_CITY], 								--[Περιοχή Παραλήπτη],
	paraliptis.AddressTK [PARALIPTIS_ZIPCODE], 								--[ΤΚ Παραλήπτη],

	KPR.Code,
	voh.PARASTATIKO [PARASTATIKO], 											--[Τύπος Παραστατικού],
	voh.SEIRA [SEIRA], 														--[Σειρά Παραστατικού],
	convert(nvarchar(20),voh.NOPARAST) [NOPARAST], 												--[Αριθμός Παραστατικού],
	voh.arrival [ARRIVAL], 													--[Αριθμός Άφιξης],
	voh.aranaforas [ARANAFORAS], 											--[Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK], 									--[Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR, 													--[Τρόπος Πληρωμής],
	cast(voh.poso as float) [POSO], 										--[Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [TAXIS], 										--[Αξία Παραστατικού (ΦΠΑ)],
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_DISCOUNT_ALL], 													--[Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [IF_DISCOUNT_SERVICE], 												--[Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [KENTRO_KOSTOUS], 									--[Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [AXIA_EMPOREUMATON], 								--[Αξία Εμπορευμάτων Παραστατικού],
	null [RESERVATION_DATE], 												--[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [RESERVATION_SLOT],												--[SLOT Υπηρεσίας Σύμφωνα με Reservation],
	
	
	listessynarmologisis.STATUS [STATUS_LISTAS_ASS],						--[Κατάσταση Λίστας Ανάθεσης], 												
	KAA.DATEPRINT [KAA_DATE], 												--[Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [KAA_MONTH], 										--[Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [KAA_TRUCK], 													--[Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [KAA_DRIVER] , 												--[Οδηγός Διπλότυπης Καταστήματος],
	LISTESDIANOMIS.DATEPRINT [LISTADIANOMIS_DATE], 							--[Ημερομηνία Διπλότυπης Κέντρου Διανομής],
	MONTH(LISTESDIANOMIS.DATEPRINT) [LISTADIANOMIS_MONTH], 					--[Μήνας Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.OXIMA [LISTADIANOMIS_TRUCK], 							--[Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DRIVER [LISTADIANOMIS_DRIVER], 							--[Οδηγός Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.STATUS [LISTADIANOMIS_STATUS], 							--[Status Διπλότυπης Κέντρου Διανομής],
	cast(grammesvohsum.temaxia as float) AS [TEMAXIA], 							--[Σύνολο Τεμαχίων],
	grammesvohsum.countid [POSOTHTA], 										--[Σύνολο κωδικών εμπορευμάτων],
	cast(grammesvohsum.baros as float) [BAROS], 							--[Συνολικό Βάρος],
	cast(grammesvohsum.kybika as float) [KYBIKA], 							--[Συνολικός Όγκος],
	voh.COMMENTS [COMMENTS], 												--[Σχόλια - Παρατηρήσεις],
	VOH.ID,
	
