GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[XREOSISANADELTIO_CORRECTED] AS 
SELECT 
	XAD.ID,
	CASE ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH, XAD.IF_TO_FORTOTIKI, XAD.IF_TO_VOH ORDER BY XAD.ID ) 
		WHEN 1 THEN XAD.TAXIS + ISNULL(taxisdiff.diff, 0)
		ELSE XAD.TAXIS
	END TAXIS
FROM XREOSISANADELTIO XAD 
LEFT JOIN (
	select
		sumdeltiou.id,
		sumdeltiou.if_to_fortotiki,
		sumdeltiou.if_to_voh,
		abs(sumxreoseonanadeltio.taxis - sumdeltiou.taxis) diff
	from (
		select 
			id, 
			1 [IF_TO_FORTOTIKI],
			0 [IF_TO_VOH],
			taxis
		from fortotikes f
		union
		select 
			id, 
			0 [IF_TO_FORTOTIKI],
			1 [IF_TO_VOH],
			taxis
		from voh v
	) sumdeltiou 
	join (
		select
			idvoh,
			if_to_fortotiki,
			if_to_voh,
			sum(poso) poso,
			sum(taxis) taxis
		from XREOSISANADELTIO
		group by idvoh, IF_TO_FORTOTIKI, IF_TO_VOH
	) sumxreoseonanadeltio 
		on sumxreoseonanadeltio.idvoh = sumdeltiou.ID
		and sumxreoseonanadeltio.IF_TO_FORTOTIKI = ISNULL(sumdeltiou.IF_TO_FORTOTIKI , 0)
		and sumxreoseonanadeltio.IF_TO_VOH = ISNULL(sumdeltiou.IF_TO_VOH, 0)
	where sumdeltiou.taxis <> sumxreoseonanadeltio.taxis
) taxisdiff on taxisdiff.ID = XAD.IDVOH
GO


---END SCRIPT 1596
------------------------------------------------------------------------------------

