ALTER PROCEDURE [dbo].[inserttoUsers]
(
	@LastName					NVARCHAR(50),
	@FirstName					NVARCHAR(50),
	@UserName					NVARCHAR(50)= NULL,
	@Password					NVARCHAR(50)= NULL,
	@IF_ES_EX					INT = 0,
	@IF_ALL_YPOKATASTIMATA		INT=0,
	@IfModRecs					INT = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = NULL,
	@YPOKATASTIMADESCR			NVARCHAR(80) = NULL,
	@TheID						NUMERIC(18, 0)= NULL output

	)
AS

	DECLARE @TRACOUNT 	INT
	DECLARE @ErrorNumber 	INT
	DECLARE @ErrorDescription NVARCHAR(255)
	DECLARE @Rowcount	INT
	DECLARE @RetVal 	INT
	DECLARE @Number 	NVARCHAR(30)	
	DECLARE @IDOC_COMM	INT
	DECLARE @IDOC_XRE	INT
	DECLARE @CAN_PRINT   	BIT
	DECLARE @ID 		INT
	DECLARE @RET_BATCH_NUM	NVARCHAR(30)
	DECLARE @Courier_Group_Code NVARCHAR(5)

	SET NOCOUNT ON
	SET @ErrorNumber = 0

	SET @TRACOUNT = @@TRANCOUNT
	IF @TRACOUNT = 0 

	--***************************************************************************
	DECLARE @RowCountPelati INT
	DECLARE @ClientCode INT
	DECLARE @ClientTownCode NVARCHAR(10)
	DECLARE @ClientRegionCode NVARCHAR(10) --TASK 12899
	DECLARE @PelatesAddr	NVARCHAR(60) --TASK 11593
	DECLARE @PelatesProfID	NVARCHAR(30) --TASK 11623
	SET @RowCountPelati=0

		BEGIN
			INSERT INTO ActiveUsers
				(
				LastName,
				FirstName,
				UserName,
				Password,
				IF_ALL_YPOKATASTIMATA,
				IDYPOKATASTIMA,
				YPOKATASTIMADESCR,
				IF_ES_EX,
				IfModRecs
				)
			VALUES
				(
				@LastName,
				@FirstName,
				@UserName,
				@Password,
				@IF_ALL_YPOKATASTIMATA,
				@IDYPOKATASTIMA,
				@YPOKATASTIMADESCR,
				@IF_ES_EX,
				@IfModRecs
				)
			SELECT  @TheID = MAX(ID) FROM dbo.ActiveUsers WITH (NOLOCK)

		END

	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************


ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint

;

GO

---END SCRIPT 1600
------------------------------------------------------------------------------------


