create view FORTOTIKES_PER_SYSKEVASIA
AS

WITH GRAMMES AS (
					
			select
				IDVOH AS FORTID,[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
			from 
				(
					select
						idvoh,
						case 
							--when CONVERT(NVARCHAR(50),isnull(SYSKEVASIADESCR,0))=0 then 'ΔΕΜΑΤΑ'
							when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
							when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
							when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
							when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
							when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
							when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
							ELSE 'KOLA'
						END AS SYSKEVASIA,
						TEMAXIA
					FROM  GRAMMESFORTTIKIS
				)AS GF
			PIVOT
			(
				SUM(TEMAXIA)
				FOR SYSKEVASIA IN ([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
			) AS PV
	)
select
	f.id,
	f.DATEPRINT,
	f.noparast,
	f.IDAPOSTOLEA,
	apost.Eponimia [APOSTOLEAS],
	f.IDPARALIPTI,
	paral.Eponimia [PARALIPTIS],
	(paral.AddressStr +' '+ paral.AddressNo) [PARALIPTI_DIEYTHINSI],
	paral.AddressCity,
	paral.AddressTK,
	case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as [SYNTHIKI],
	f.THESI,
	f.DROMOLOGIO,
	grammes.DEMATA,
	grammes.PALETA,
	grammes.[STAND],
	grammes.[KOLA],
	grammes.[ROLI],
	grammes.[THALAMOS],
	F.OMADPROORISMOS,
	f.ifDelete
		
from FORTOTIKES f

left join ACCOUNTS apost on apost.id=f.IDAPOSTOLEA
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI
left join GRAMMES ON GRAMMES.FORTID=F.ID 

GO



---END SCRIPT 1602
------------------------------------------------------------------------------------

