CREATE VIEW  FORTOTIKES_ANA_KAA_PIVOTED
AS

WITH GRAMMES AS (
					select
						IDVOH,
						[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
					from(
							select
								IDVOH,
								case 
									when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
									when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
									when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
									when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
									when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
									when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
									ELSE 'KOLA'
								END AS SYSKEVASIA,
								TEMAXIA
							from GRAMMESFORTTIKIS
						) AS GF
					pivot
						(
							sum(GF.TEMAXIA)
							FOR GF.SYSKEVASIA in([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
						)AS PV
		)

SELECT
		FK.ID,
		FK.IDKAA,
		FK.IDFORTOTIKIS,
		F.DATEPRINT,
		FK.APOSTOLEASDESCR,
		FK.PARALISPTISDESCR,
		(PARAL.AddressStr +' '+ PARAL.AddressNo) AS PARAL_DIEYTHINSI,
		PARAL.AddressCity,
		case APOST.ext_id
			when '300' then 'ΞΗΡΟ'
			when '134' then 'ΨΥΓΕΙΟ'
			when '395' then 'ΜΑΝΑΒΙΚΗ'
			else null
		end as [SYNTHIKI],
		FK.TIMDA,
		F.THESI,
 		KOMISTRA,
		DIKAIOMA,
		OTHERPOSO,
		FK.EXODATRITON,
		XREOSIPROPLIROMENES,
		XREOSIOFEILOMENES,
		XREOSIPROPLIROMENESCASH,
		XREOSIPROPLIROMENESPISTOSI,
		FK.POSO,
		FK.TAXIS,
		FK.SUMPOSO,
		FK.ANTIKCASH,
		GRAMMES.DEMATA,
		GRAMMES.PALETA,
		GRAMMES.KOLA,
		GRAMMES.ROLI,
		GRAMMES.THALAMOS,
		GRAMMES.STAND,
		F.IFDELETE
		
FROM FORTOTIKES_ANA_KAA FK
LEFT JOIN GRAMMES ON GRAMMES.IDVOH=IDFORTOTIKIS
LEFT JOIN ACCOUNTS PARAL ON PARAL.id=FK.IDPARALIPTI
LEFT JOIN ACCOUNTS APOST ON APOST.id=FK.IDAPOSTOLEA
LEFT JOIN FORTOTIKES F ON F.ID=FK.IDFORTOTIKIS

GO

---END SCRIPT 1604
------------------------------------------------------------------------------------

---NEW SCRIPT 1605


ALTER view [dbo].[FORTOTIKES_WEB_STATUS_HISTORY] as
select 
	FSH.ID,
	CONVERT(DATE, FSH.DATE) [DATE],
	FSH.FORT_ID,
	FSH.NO_EXT_ORDER,
	DS.DESCR,
	CASE
		WHEN (DS.IFPARALAVI=1 OR DS.IFEKDOSI=1) THEN KENTRIKO.Eponimia + ' - ' + YPOKAT.Eponimia
		WHEN DS.IFSEKAA=1 THEN 'ΟΔΗΓΟΣ: ' + DRV_KAA.LastName + ' ' + DRV_KAA.FirstName
		WHEN (DS.IFSELISTA=1 OR DS.IFEPANADR=1) THEN 'ΟΔΗΓΟΣ: ' + DRV_LISTA.LastName + ' ' + DRV_LISTA.FirstName
		WHEN (DS.IFAKIROSI=1 OR DS.IFPARADOSI=1 OR DS.IFEPISTROFI=1) THEN NULL
		WHEN DS.IFPRK=1 THEN PRK.Eponimia
	END [ContactPerson],
	CASE
		WHEN (DS.IFPARALAVI=1 OR DS.IFEKDOSI=1) THEN YPOKAT.Tel
		WHEN DS.IFSEKAA=1 THEN DRV_KAA.Tel
		WHEN (DS.IFSELISTA=1 OR DS.IFEPANADR=1) THEN ISNULL(DRV_LISTA.Tel, '')
		WHEN (DS.IFAKIROSI=1 OR DS.IFPARADOSI=1 OR DS.IFEPISTROFI=1) THEN NULL
		WHEN DS.IFPRK=1 THEN PRK.Tel
	END [ContactNumber]
	
FROM FORT_STATUS_HISTORY FSH
JOIN DOC_STATUS DS ON DS.ID = FSH.STATUS_ID
JOIN FORTOTIKES FORT ON FORT.ID = FSH.FORT_ID
LEFT JOIN FORTOTIKES_ANA_KAA FAK ON FAK.IDFORTOTIKIS = FORT.ID
LEFT JOIN KAA ON KAA.ID = FAK.IDKAA
LEFT JOIN ODIGOI DRV_KAA ON DRV_KAA.LastName + ' ' + DRV_KAA.FirstName = KAA.DRIVER

LEFT JOIN FORTOTIKES_ANA_LISTA FAL ON FAL.IDFORTOTIKIS = FORT.ID
LEFT JOIN LISTESDIANOMIS LISTA ON LISTA.ID = FAL.IDLISTAS
LEFT JOIN ODIGOI DRV_LISTA ON DRV_LISTA.LastName + ' ' + DRV_LISTA.FirstName = LISTA.DRIVER

LEFT JOIN PRAKTOREIA PRK ON PRK.ID = FORT.IDPRAKTOREIO


JOIN COMPANIES KENTRIKO 
	ON KENTRIKO.IFYPOKATASTHMATA = 1 AND KENTRIKO.IFYPOKATASTHMA = 0 AND KENTRIKO.ID = FORT.IDCOMPANY
	
JOIN COMPANIES YPOKAT ON YPOKAT.ID = FORT.IDYPOKATASTIMA

GO



---END SCRIPT 1605
------------------------------------------------------------------------------------


---NEW SCRIPT 1606

EXEC SP_RENAME 'FORTOTIKESLIGHT_VIEW','FORTOTIKESLIGHT_VIEW_OLD'
GO

CREATE VIEW FORTOTIKESLIGHT_VIEW
AS


WITH GRAMMES AS 
(
				SELECT 
					IDVOH,
					MIN(TIMDA) AS TIMDA,
					ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
					MIN(U.UntName) AS SYSKEVASIADESCR,
					MIN(PERIEXOMENO) AS PERIEXOMENO,
					ISNULL(SUM(BAROS),0) AS BAROS,
					ISNULL(SUM(KYBIKA),0) AS KYBIKA,
					ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
				FROM GRAMMESFORTTIKIS
				LEFT JOIN Units U ON U.UntID=GRAMMESFORTTIKIS.SYSKEVASIA
				GROUP BY IDVOH
),
POSA AS
(
SELECT 
	ID,
	SUMPOSO,
	ROUND(MIN(FORTOTIKES.POSO),2) AS KATHARO,
	ROUND(MIN(FORTOTIKES.TAXIS),2) AS TAXISXREOSEON,
	ROUND(MIN(FORTOTIKES.SUMPOSO),2) AS SUMPOSOXRFORT
FROM FORTOTIKES
GROUP BY ID,SUMPOSO
),
pivoted as
(
					
			select
				IDVOH AS FORTID,[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
			from 
				(
					select
						idvoh,
						case 
							when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
							when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
							when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
							when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
							when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
							when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
							ELSE 'KOLA'
						END AS SYSKEVASIA,
						TEMAXIA
					FROM  GRAMMESFORTTIKIS
				)AS GF
			PIVOT
			(
				SUM(TEMAXIA)
				FOR SYSKEVASIA IN ([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
			) AS PV
	
)


select 
	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	CAST(f.noparast as int) as NOPARAST,
	F.NOPARASTDELTIOUDIANOMIS,
	F.NOPARASTDELTIOUAPOSTOLIS,
	F.OXIMA,
	F.OMADPROORISMOS,
	CASE 
            WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' 
            ELSE CASE 
                WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' 
                ELSE CASE 
                    WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
                    ELSE CASE 
                        WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'                        
                        ELSE 'ΑΓΝΩΣΤΟ' 
                    END 
                END 
            END 
        END AS XREOYMENOS,
        APOST.Eponimia AS APOSTOLEASDESCR,
        PARAL.Eponimia AS PARALISPTISDESCR,
        ENTOL.Eponimia AS ENTOLEASDESCR,
        F.ANTAPOKRITISDESCR,
        f.NOLISTASDIANOMIS,
        CONVERT(VARCHAR,LD.DATEPRINT,103) [DATE_LISTAS_DIANOMIS],
        TRITOS.Eponimia AS TRITOSDESCR,
        HD.DESCRCATALOG AS TIMOKATALOGOS,
        GRAMMES.TIMDA AS TIMDA,
        ISNULL(f.POSO,0) AS POSO,
        ISNULL(POSA.TAXISXREOSEON,0) AS TAXISXREOSEON,
        ISNULL(POSA.SUMPOSOXRFORT,0) AS SUMPOSOXRFORT,
        ISNULL(f.TAXIS,0) AS TAXIS,
        ISNULL(F.SUMPOSO,0) AS SUMPOSO,
        ISNULL(GRAMMES.TEMAXIA,0) AS TEMAXIA,
        ISNULL(GRAMMES.BAROS,0) AS BAROS,
        ISNULL(GRAMMES.KYBIKA,0) AS KYBIKA,
        GRAMMES.SYSKEVASIADESCR AS SYSKEVASIA,
        CASE F.IFPREPAY 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0) 
            ELSE 0 
        END AS XREOSIPROPLIROMENES,
        CASE F.IFOFEILOMENI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END AS XREOSIOFEILOMENES,
        CASE F.IFPREPAY 
            WHEN 1 THEN CASE F.IFCASH 
                WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
                ELSE 0 
            END 
            ELSE 0 
        END AS XREOSIPROPLIROMENESCASH,
        CASE F.IFPREPAY 
            WHEN 1 THEN CASE F.IFPISTOSI 
                WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
                ELSE 0 
            END 
            ELSE 0 
        END AS XREOSIPROPLIROMENESPISTOSI,
        GRAMMES.PERIEXOMENO,
        F.PERIOXIFORTOSIS,
        F.PERIOXIPARADOSIS,
        F.COMMENTS,
        ISNULL(F.SUMANTIK,0) AS SUMANTIK,
        F.PRAKTOREIODESCR,
        F.STATUS,
        F.DATEPARAD,
        F.IDAPOSTOLEA,
        F.IDPARALIPTI,
        F.IDENTOLEA,
        F.IDANTAPOKRITI,
        F.IDTRITOU,
        F.IDPRAKTOREIO,
        CASE IFANTIKCASH 
            WHEN 0 THEN 0 
            ELSE ANTIKCASH 
        END AS ANTIKCASH,
        CASE IFANTIKEPIT 
            WHEN 0 THEN 0 
            ELSE ANTIKEPIT 
        END AS ANTIKEPIT,
        CASE IFANTIKSYNAL 
            WHEN 0 THEN 0 
            ELSE ANTIKSYNAL 
        END AS ANTIKSYNAL,
        CASE IFANTIKOTHER 
            WHEN 0 THEN 0 
            ELSE ANTIKOTHER 
        END AS ANTIKOTHER,
        CASE IFCANCELANTIK 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFCANCELANTIK,
        F.COMMENTSANTIK,
        F.DATEPARADOSI,
        F.COMMENTS2,
        ISNULL(F.EXODATRITON,0) AS XREOSISTRITON,
        CASE F.IFPREPAY 
            WHEN 1 THEN 'ΝΑΙ' 
            ELSE 'ΟΧΙ' 
        END AS IFPREPAY,
        F.NO_EXT_ORDER,
        CASE f.IFOFEILOMENI 
            WHEN 1 THEN 'ΝΑΙ' 
            ELSE 'ΟΧΙ' 
        END AS IFOFEILOMENI,
       ISNULL(GRAMMES.SUMPOSO,0) AS AXIA,
        CASE IFXRENTOL 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRENTOL,
        F.KINDPAYMENTDESCR,
        F.IDKINDPAYMENT,
        CASE IFXRAPOST 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRAPOST,
        CASE IFXRPARAL 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRPARAL,
        CASE IFXRTRITOU 
            WHEN 0 THEN 'ΟΧΙ' 
            ELSE 'ΝΑΙ' 
        END AS IFXRTRITOU,
        F.IFANTIKCASH,
        F.IFANTIKEPIT,
        F.IFANTIKSYNAL,
        F.IFANTIKOTHER,
        F.ifDelete,
        F.IFCANCEL,
        F.DATECANCEL,
        F.DROMOLOGIO,
        F.THESI,
        F.IFPARADOSI,
        F.AITIOLOGIAPARASTATIKOU,
        CONVERT(varchar,F.DATEFORTOSIS,102) AS DATEFORTOSIS,
        F.IFEPISTROFI,
        F.DATEEPISTROFIS,
        F.AITIOLOGIAEPISTROFIS,
        F.COMMENTSEPISTROFIS,
        F.IFCASH,
        F.IFPISTOSI,
        F.STATUSDESCR,
        F.YPAITIOS,
        F.IFEPANADROMOLOGISI,
        F.IFEPANEKDOSI,
        F.IFOKEPANADROMOLOGISI,
        F.NOPARASTANTIK,
        F.COMMENTSAKIROSIS,
        F.IFEISPRANTIK,
        F.IFPARADOSIANTIK,
        F.IFPARALAVIANTIK,
        F.COMMENTSPARADANTIK,
        F.COMMANTSPARALANTIK,
        F.COMMENTSEISPRANTIK,
        CONVERT(varchar,F.DATEPARADANTIK,102) AS DATEPARADANTIK,
        CONVERT(varchar,F.DATEPARALANTIK,102) AS DATEPARALANTIK,
        CONVERT(varchar, F.DATEEISPRANTIK,102) AS DATEEISPRANTIK,
        F.EISPRAXASANTIK,
        F.NOPARPARADANTIK,
        F.NOPARASTEISPRANTIK,
        F.NOPARPARALANTIK,
        F.DATEPARAL,
        F.COMMENTSPARAD,
        F.COMMANTSPARAL,
        F.TIMEPARALFROM,
        F.TIMEPARALTO,
        F.TIMEPARADFROM,
        F.TIMEPARADTO,
        CONVERT(varchar,F.DATECANCELANTIK,102) AS DATECANCELANTIK,
        F.IDPARAST,
        ISNULL(F.TAXISPERCENT,0) AS TAXISPERCENT,
        ISNULL(F.ANAMEXODO,0) AS ANAMEXODO,
        F.ID AS IDFORTOTIKIS,
        F.AFMXREOUMENOU,
        ISNULL(posa.KATHARO,0) AS KATHARO,
        apost.Epagelma AS EPAGAPOST,
        apost.AddressStr AS ADDRSTRAPOST,
        apost.AddressNo AS ADDRNOAPOST,
        apost.AddressTK AS TKAPOST,
        apost.AddressCity AS CITYAPOST,
        apost.AddressPref AS NOMOSAPOST,
        apost.Tel AS TELAPOST,
        apost.DOY AS DOYAPOST,
        PARAL.Epagelma AS EPAGPARAL,
        PARAL.AddressStr AS ADDRSTRPARAL,
        PARAL.AddressNo AS ADDRNOPARAL,
        PARAL.AddressTK AS ADDRTKPARAL,
        PARAL.AddressCity AS ADDRCITYPARAL,
        PARAL.AddressPref AS ADDRNOMOSPARAL,
        PARAL.Tel AS TELPARAL,
        PARAL.DOY AS DOYPARAL,
        ENTOL.Epagelma AS EPAGENTOL,
        ENTOL.AddressStr AS ADDRSTRENTOL,
        ENTOL.AddressNo AS ADDRNOENTOL,
        ENTOL.AddressTK AS ADDRTKENTOL,
        ENTOL.AddressCity AS ADDRCITYENTOL,
        ENTOL.AddressPref AS ADDRNOMOSENTOL,
        ENTOL.Tel AS TELENTOL,
        ENTOL.DOY AS DOYENTOL,
        TRITOS.Epagelma AS EPAGTR,
        TRITOS.AddressStr AS ADDRSTTR,
        TRITOS.AddressNo AS ADDRNOTR,
        TRITOS.AddressTK AS ADDRTKTR,
        TRITOS.AddressCity AS ADDRCITYTR,
        TRITOS.AddressPref AS ADSTRDRNOMO,
        TRITOS.Tel AS TELTR,
        TRITOS.DOY AS DOYTR,
        F.AFMAPOSTOLEA,
        F.AFMENTOLEA,
        F.IF_TRANSFTOESEX,
        F.AFMPARALIPTI,
        F.AFMTRITOU,
        F.AFMANTAPOKRITI,
        F.IFPARADOSITOPEL,
        F.IFPARALABIFROMPEL,
        F.IDXRHSHS,
        F.IDCOMPANY,
        F.IFEXOFLISI,
        F.IDYPOKATASTIMA,
        F.UserMod,
        F.DateMod,
        F.CONTAINER,
        F.BOAT,
        F.POD_ADDED,
        F.IDKENTROUKOSTOUS,
        F.NO_EXT_ORDER_IK,
        F.IDENTOLIS,
        F.IF_CANCEL,
        F.ID_CANCELLATION,
        F.SEIRA_CANCELLATION,
        F.NOPARAST_CANCELLATION,
        F.DETAILS_CANCELLATION,
        F.CANCELDATE,
        F.EXT_BARCODE,
        F.POD_PATH,
        F.POD_USER,
        F.POD_PATH_2,
        F.UserCreate,
        F.DateCreate,
        F.IF_FROM_ANTAP,
        F.IF_TO_ANTAP,
        isnull(pivoted.DEMATA,0) as DEMATA,
        isnull(pivoted.KOLA,0) AS KOLA,
        isnull(pivoted.STAND,0) AS STAND,
        isnull(pivoted.ROLI,0) AS ROLI,
        isnull(pivoted.THALAMOS,0) AS THALAMOS
        
	
from FORTOTIKES f
join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
LEFT JOIN ACCOUNTS APOST ON APOST.id=F.IDAPOSTOLEA
LEFT JOIN ACCOUNTS PARAL ON PARAL.id = F.IDPARALIPTI
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
LEFT JOIN ACCOUNTS TRITOS ON TRITOS.id=F.IDTRITOU
LEFT JOIN MAX_FORTOTIKES_ANA_LISTA FAL ON FAL.IDFORTOTIKIS=F.ID
LEFT JOIN LISTESDIANOMIS LD ON LD.ID=FAL.IDLISTAS
LEFT JOIN dbo.HEADERVOHPRICING HD WITH (NOLOCK) ON HD.IDVOH=F.IDENTOLIS  

LEFT JOIN GRAMMES ON GRAMMES.IDVOH=f.ID
LEFT JOIN POSA ON POSA.ID=f.ID
left join pivoted on pivoted.FORTID=f.id

GO






---END SCRIPT 1606
