CREATE PROCEDURE [dbo].[InserttoACCOUNTS_IMPORT]
(
	@Name			VARCHAR(50),
	@Address		VARCHAR(50),
	@ZipCode		VARCHAR(10) = NULL,
	@Telephone		VARCHAR(20) = NULL,
	@Mobile			VARCHAR(20) = NULL,
	@Email			VARCHAR(50) = NULL,
	@CityID			INT,
	@ExternalID		NVARCHAR(20) = NULL,
	@TheID			INT = NULL output
	
	)
AS

SET NOCOUNT ON;

DECLARE @AddressCity NVARCHAR(50)

SELECT TOP 1 @AddressCity = AarName FROM Aar WHERE AarId = @CityID

EXEC InserttoACCOUNTS
	--@Code						nvarchar(50) = NULL,
	@Eponimia				= @Name,
	@Epagelma				= '',
	@LastName				= '',
	@FirstName				= '',
	@AddressStr				= @Address,
	@AddressNo				= '',
	@AddressTK				= @ZipCode,
	@AddressCity			= @AddressCity,
	--@AddressPref				nvarchar(150) = NULL,
	--@AddressZone				nvarchar(150) = NULL,
	--@AddressCountry				nvarchar(150) = NULL,
	@Tel					= @Telephone,
	--@Tel2						nvarchar(50) = NULL,
	--@Fax						nvarchar(50) = NULL,
	@Mobile					= @Mobile,
	--@AFM						nvarchar(50) = NULL,
	--@DOY						nvarchar(150) = NULL,
	@Fpa					= '1 - Κανονικό',
	--@CatProm					nvarchar(150) = NULL,
	--@CatAccount					nvarchar(150) = NULL,
	--@Ypokatastima				numeric(18, 0) = NULL,
	--@AMIKA						nchar(20) = NULL,
	--@AMKA						nchar(20) = NULL,
	@IF_PROM				=	0,
	@IF_PEL					=	1,
	@IF_ERG					=	0,
	--@ifDelete					int = NULL,
	@AddrFortosis			=	@Address,
	@IF_ANTAPOKRITIS		= 0,
	@Comments				= '',
	@IDPARAST				= 0,
	--@PARASTATIKODESCR			nvarchar(100) = NULL,
	@EMAIL					=	@Email,
	--@IDENTOLEA					numeric(18, 0) = NULL,
	--@ENTOLEASDESCR				nchar(50) = NULL,
	--@IFCASH						int = NULL,
	--@IFPISTOSI					int = NULL,
	--@IFOFEILOMENI				int = NULL,
	--@IFPREPAY					int = NULL,
	--@IfTimokatPol				bit = NULL,
	--@IfTimokatAg				bit = NULL,
	--@IfTimokatEtair				bit = NULL,
	--@AFMENTOLEA					nvarchar(10) = NULL,
	--@PROTPERIEXOMENO			nvarchar(50) = NULL,
	@XREOUMENOS				= 1,
	@CATKEPYO				= 0,
	--@DISCPERCENT				numeric(18, 2) = NULL,
	--@CodeLog					varchar(30) = NULL,
	--@IDBANKA					NVARCHAR(10) = NULL,
	--@IDBANKB					NVARCHAR(10) = NULL,
	--@PrintableComment			NVARCHAR(60) = NULL,
	--@WarningComment				NVARCHAR(60) = NULL,
	--@IDBANKC					NVARCHAR(10) = NULL,
	--@IDBANKD					NVARCHAR(10) = NULL,
	--@IBANA						NVARCHAR(30) = NULL,
	--@IBANB						NVARCHAR(30) = NULL,
	--@IBANC						NVARCHAR(30) = NULL,
	--@IBAND						NVARCHAR(30) = NULL,
	--@IDOMPROOR					NUMERIC(18,0) =  NULL,
	--@OMPROOR					NVARCHAR(40) = NULL,
	--@IF_EMVASTIKA				int = 0,
	--@IF_ASFALISTRA				int = 0,
	--@ASFALISTRA					NUMERIC(18,0) = 0,
	--@IF_SCENARIO				int = 0,
	--@EMVASTIKA					NUMERIC(18,0) = 0,
	--@IDDEPARTEMENT				NUMERIC(18,0) = 0,
	--@IF_REMINDER				int = 0,
	--@REMINDER					NVARCHAR(MAX) = NULL,
	@EXT_ID					= @ExternalID,
	@TheID					= @TheID output;


	UPDATE ACC
	    SET 
			Code = 'PEL-' + CONVERT(NVARCHAR, @TheID),
			AddressPref = Ast.AstName,
		    AddressCountry = Acr.AcrName,
		    AddressZone = DEP.DESCR
		    --AddressTK = AAR.AarZipCode
    FROM ACCOUNTS ACC
    LEFT JOIN AAR AAR1 ON REPLACE(AAR1.AarZipCode, ' ', '') = REPLACE(ACC.AddressTK, ' ', '') AND LEN(AAR1.AarZipCode) > 4
    LEFT JOIN AAR AAR2 ON AAR2.AarName = ACC.AddressCity AND LEN(AAR2.AarName) > 1
    JOIN AAR ON AAR.AarID = COALESCE(AAR1.AarID, AAR2.AarID, 0)
    JOIN Ast ON AST.AstID = AAR.AarAstID
    JOIN Departements DEP ON DEP.ID = AST.IDDEPARTEMENT
    JOIN ACR ON ACR.AcrID = Ast.AstAcrID
    WHERE ACC.ID = @TheID

GO




---END SCRIPT 1615
