ALTER PROCEDURE [dbo].[InserttoPROFORTOTIKES_IMPORT]
(
	
	@IDENTOLEA					NUMERIC(18,0)= NULL,
	@IDAPOSTOLEA				NUMERIC(18,0)= NULL,
	@IDPARALIPTI				NUMERIC(18,0)= NULL,
	@IDTRITOU					NUMERIC(18,0)= NULL,
	@IDPARAST					NUMERIC(18,0)= NULL,
	
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	
	@DATEPRINT					SMALLDATETIME= NULL,

	@NO_EXT_ORDER				NVARCHAR(50) = NULL,
	@EXT_BARCODE				NVARCHAR (150) =NULL,


	@POSO						NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,

	
	
	
	@NOPARASTANTIK				NVARCHAR(50) = NULL,
	@COMMENTS					NVARCHAR(MAX)= NULL,

	@COMPANYID					INT = NULL,
	@YPOKATID					INT = NULL,

	@TheID						NUMERIC(18, 0)= NULL output
	
	)
AS

SET NOCOUNT ON;


DECLARE @PARAST_SEIRA NVARCHAR(50)
DECLARE @PARAST_DESC NVARCHAR(50)
DECLARE @PARAST_AUTONUMBER BIT
DECLARE @PARAST_TAXISPERCENT NUMERIC(18,2)

DECLARE @IDKINDPAYMENT INT
DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

DECLARE @IDSTATUS INT
DECLARE @STATUSDESCR NVARCHAR(50)

DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
DECLARE @AFMAPOSTOLEA NVARCHAR (10) =NULL
DECLARE @AFMENTOLEA NVARCHAR (10) =NULL
DECLARE @AFMPARALIPTI NVARCHAR (10) =NULL
DECLARE @AFMTRITOU NVARCHAR (10) =NULL


DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL
DECLARE @PERIOXIPARADOSIS NVARCHAR(50) = NULL
DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

DECLARE @APOSTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @PARALISPTISDESCR NVARCHAR(50)= NULL
DECLARE @ENTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

DECLARE @IDXRHSHS INT;

select top 1 @IDXRHSHS=ID from XRHSEIS where getdate() between FIRSTDATE and LASTDATE

SELECT @AFMXREOUMENOU = AFM FROM ACCOUNTS WHERE ID = @IDENTOLEA
SELECT @AFMENTOLEA = AFM, @ENTOLEASDESCR = Eponimia FROM ACCOUNTS WHERE ID = @IDENTOLEA

SELECT 
	@AFMAPOSTOLEA = AFM, 
	@APOSTOLEASDESCR = Eponimia,
	@PERIOXIFORTOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDAPOSTOLEA

SELECT 
	@AFMTRITOU = afm, 
	@TRITOSDESCR = Eponimia
FROM ACCOUNTS WHERE ID = @IDTRITOU

SELECT 
	@AFMPARALIPTI = AFM, 
	@PARALISPTISDESCR = Eponimia,
	@PERIOXIPARADOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDPARALIPTI

SELECT TOP 1
	@IDKINDPAYMENT=ID,
	@KINDPAYMENTDESCR=DESCR
FROM KINDOFPAYMENTS
WHERE IF_PISTOSI = 1
AND IF_IN = 1

SELECT TOP 1
	@IDSTATUS=ID,
	@STATUSDESCR=DESCR
FROM DOC_STATUS
WHERE IF_PRINT = 1
AND IFEKDOSI = 1

SELECT 
	@PARAST_SEIRA = SEIRA,
	@PARAST_DESC = DESCR,
	@PARAST_AUTONUMBER = IF_AUTONUMBER,
	@PARAST_TAXISPERCENT = TAXISPERCENT

FROM KINDPARASTATIKON
WHERE ID = @IDPARAST


	--@STATUSDESCR				NVARCHAR(50) = NULL,


EXEC InserttoPROFORTOTIKES
	@TheID = @TheID output,
	@IDENTOLEA = @IDENTOLEA,
	@IDAPOSTOLEA = @IDAPOSTOLEA,
	@IDPARALIPTI = @IDPARALIPTI,
	@IDTRITOU = @IDTRITOU,
	@IDANTAPOKRITI = -1,
	@IDXREOUMENOU = @IDENTOLEA,

	@IDPARAST = @IDPARAST,
	@PARASTATIKO = @PARAST_DESC,
	@SEIRA = @PARAST_SEIRA,
	@IFAUTONUMBER = @PARAST_AUTONUMBER,

	@ANTIKCASH = @ANTIKCASH,
	@ANTIKEPIT = @ANTIKEPIT,
	@ANTIKSYNAL = @ANTIKSYNAL,
	@ANTIKOTHER = @ANTIKOTHER,

	@PERIOXIPARADOSIS = @PERIOXIPARADOSIS,
	@PERIOXIFORTOSIS = @PERIOXIFORTOSIS,



	@IFCASH = 0,
	@IFPISTOSI = 1,
	@IFPREPAY = 1,
	@IFOFEILOMENI = 0,
	@DATEPRINT = @DATEPRINT,
	@IDKINDPAYMENT = @IDKINDPAYMENT,
	@KINDPAYMENTDESCR = @KINDPAYMENTDESCR,
	@NO_EXT_ORDER = @NO_EXT_ORDER,
	@EXT_BARCODE = @EXT_BARCODE,
	@STATUS = @IDSTATUS,
	@STATUSDESCR = @STATUSDESCR,
	@AFMXREOUMENOU = @AFMXREOUMENOU,
	@AFMENTOLEA = @AFMENTOLEA,
	@AFMAPOSTOLEA = @AFMAPOSTOLEA,
	@AFMPARALIPTI = @AFMPARALIPTI,
	@AFMTRITOU = @AFMTRITOU,

	@APOSTOLEASDESCR = @APOSTOLEASDESCR,
	@PARALISPTISDESCR = @PARALISPTISDESCR,
	@ENTOLEASDESCR = @ENTOLEASDESCR,
	@TRITOSDESCR = @TRITOSDESCR,
	@DateCreate = @DATEPRINT,
	@UserCreate	='Import Tool',

	@IDXRHSHS = @IDXRHSHS,
	@TAXISPERCENT = @PARAST_TAXISPERCENT,
	@COMMENTS = @COMMENTS,
	@IDCOMPANY = @COMPANYID,
	@IDYPOKATASTIMA = @YPOKATID


update PF
	SET 
		IFANTIKCASH = CASE WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKEPIT = CASE WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKSYNAL = CASE WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKOTHER = CASE WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1 ELSE 0 END,
		SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER,0),
		IFXRENTOL = 1,
		IFPREPAY = ENTOL.IFPREPAY,
		IFCASH = ENTOL.IFCASH,
		IFOFEILOMENI = ENTOL.IFOFEILOMENI,
		IFPISTOSI = ENTOL.IFPISTOSI
FROM PROFORTOTIKES PF
join ACCOUNTS ENTOL ON ENTOL.id = PF.IDENTOLEA
WHERE PF.ID = @TheID;

UPDATE PF SET
	PF.OMADPROORISMOS=OP.Descr

FROM PROFORTOTIKES PF
LEFT JOIN Aar ON Aar.AarName=PF.PERIOXIPARADOSIS
LEFT JOIN AarPerOmProor AOM ON AOM.AarID=Aar.AarID
LEFT JOIN OMADIKOI_PROORISMOI OP ON OP.ID=AOM.IDOmProor
WHERE PF.ID = @TheID;


INSERT INTO XREOSISANAPRODELTIO(
	IDVOH, 
	IDXREOSIS, 
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_PROFORTOTIKI,
	IF_TO_PROVOH
)
SELECT
	PROFORT.ID,
	XR.ID,
	XR.CODE,
	XR.Descr,
	XR.TAXISPERCENT,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 1
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 0.24
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 1.24
		ELSE 0
	END,
	1,
	0
		
FROM XREOSISANAPARASTATIKO XAP
JOIN PROFORTOTIKES PROFORT ON PROFORT.IDPARAST = XAP.IDKINDPARASTTIKON
JOIN Xreoseis XR ON XR.ID = XAP.IDXREOSIS
WHERE XAP.ifDelete = 0
AND XR.ifDelete = 0
AND XAP.IDKINDPARASTTIKON = PROFORT.IDPARAST
AND PROFORT.ID = @theID;

-- κλαιει η μανα του πελε
with SUMXRPF as (
	select
		xap.IDVOH,
		ISNULL(XR.ifKomistra, 0) ifKomistra,
		ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis,
		ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton,
		ISNULL(xr.ifOther, 0) ifOther,
		ISNULL(xr.IfAsfalistra, 0) ifAsfalistra,
		ISNULL(xr.ifErgatika, 0) ifErgatika,
		ISNULL(xr.IfEmvastika, 0) ifEmvastika,
		sum(xap.POSO) POSO
	from XREOSISANAPRODELTIO XAP
	join Xreoseis XR ON XR.ID = XAP.IDXREOSIS
	where xap.IDVOH = @TheID
	GROUP BY
		GROUPING SETS (
			(IDVOH, ifKomistra),
			(IDVOH, ifDikaiomaFortotikis),
			(IDVOH, ifXreosiTriton),
			(IDVOH, ifOther),
			(IDVOH, IfAsfalistra),
			(IDVOH, ifErgatika),
			(IDVOH, ifEmvastika)
		)
	HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		or ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		or ISNULL(xr.ifXreosiTriton, 0) = 1
		or ISNULL(xr.ifOther, 0) = 1
		or ISNULL(xr.IfAsfalistra, 0) = 1
		or ISNULL(xr.ifErgatika, 0) = 1
		or ISNULL(xr.IfEmvastika, 0) = 1
	)
)
INSERT INTO HEADERPROFORTOTIKIS (
	IDPROFORT,
	PARASTATIKOPROFORT,
	SEIRAPROFORT,
	NOPARASTPROFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRPROFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONPROFORT,
	BAROSPROFORT,
	KYBIKAPROFORT,
	POSOPROFORT,
	TEMAXIAPROFORT
)
select
	PF.ID,
	PF.PARASTATIKO,
	PF.SEIRA,
	PF.NOPARAST,
	PF.ENTOLEASDESCR,
	PF.PARALISPTISDESCR,
	PF.APOSTOLEASDESCR,
	ISNULL(SUM_KOMISTRA.POSO, 0),
	ISNULL(SUM_DIKAIOMA.POSO, 0),
	ISNULL(SUM_OTHER.POSO, 0),
	ISNULL(GPF.SYSKEVASIA, 0),
	ISNULL(SUM_ASFALISTRA.POSO, 0),
	
	--katharo?
	PF.POSO,

	PF.TAXIS,
	SUMXR.POSO,
	ISNULL(SUM_ERGATIKA.POSO, 0),
	ISNULL(SUM_TRITON.POSO, 0),
	
	--oliko synolo xreoson ?!
	SUMXR.POSO,
	
	ISNULL(GPF.BAROS, 0),
	ISNULL(GPF.KYBIKA, 0),

	--what the fuck den perigrafw allo
	PF.POSO,
	ISNULL(GPF.TEMAXIA, 0)

from profortotikes PF
left join (
	SELECT 
		IDVOH,
		MIN(SYSKEVASIA) SYSKEVASIA,
		SUM(BAROS) BAROS,
		SUM(KYBIKA) KYBIKA,
		SUM(TEMAXIA) TEMAXIA
	FROM GRAMMESPROFORTTIKIS
	GROUP BY IDVOH
) GPF ON GPF.IDVOH = PF.ID
left join SUMXRPF SUM_KOMISTRA on SUM_KOMISTRA.ifKomistra = 1
left join SUMXRPF SUM_DIKAIOMA on SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
left join SUMXRPF SUM_OTHER on SUM_OTHER.ifOther = 1
left join SUMXRPF SUM_ASFALISTRA ON SUM_ASFALISTRA.ifAsfalistra = 1
left join SUMXRPF SUM_ERGATIKA ON SUM_ERGATIKA.ifErgatika = 1
left join SUMXRPF SUM_TRITON ON SUM_TRITON.ifXreosiTriton = 1
left join (
	SELECT IDVOH, SUM(POSO) POSO FROM XREOSISANAPRODELTIO GROUP BY IDVOH
) SUMXR ON SUMXR.IDVOH = PF.ID

where id = @TheID


GO



---END SCRIPT 1617
------------------------------------------------------------------------------------

---NEW SCRIPT 1618





ALTER PROCEDURE [dbo].[InserttoFORTOTIKES_IMPORT]
(
	
	@IDENTOLEA					NUMERIC(18,0)= NULL,
	@IDAPOSTOLEA				NUMERIC(18,0)= NULL,
	@IDPARALIPTI				NUMERIC(18,0)= NULL,
	@IDTRITOU					NUMERIC(18,0)= NULL,
	@IDPARAST					NUMERIC(18,0)= NULL,
	
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	
	@DATEPRINT					SMALLDATETIME= NULL,

	@NO_EXT_ORDER				NVARCHAR(50) = NULL,
	@EXT_BARCODE				NVARCHAR (150) =NULL,


	@POSO						NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,

	
	
	
	@NOPARASTANTIK				NVARCHAR(50) = NULL,
	@COMMENTS					NVARCHAR(MAX)= NULL,

	@COMPANYID					INT = NULL,
	@YPOKATID					INT = NULL,


	@TheID						NUMERIC(18, 0)= NULL output
	
	)
AS

SET NOCOUNT ON;


DECLARE @PARAST_SEIRA NVARCHAR(50)
DECLARE @PARAST_DESC NVARCHAR(50)
DECLARE @PARAST_AUTONUMBER BIT
DECLARE @PARAST_TAXISPERCENT NUMERIC(18,2)

DECLARE @IDKINDPAYMENT INT
DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

DECLARE @IDSTATUS INT
DECLARE @STATUSDESCR NVARCHAR(50)

DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
DECLARE @AFMAPOSTOLEA NVARCHAR (10) =NULL
DECLARE @AFMENTOLEA NVARCHAR (10) =NULL
DECLARE @AFMPARALIPTI NVARCHAR (10) =NULL
DECLARE @AFMTRITOU NVARCHAR (10) =NULL

DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL
DECLARE @PERIOXIPARADOSIS NVARCHAR(50) = NULL
DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

DECLARE @APOSTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @PARALISPTISDESCR NVARCHAR(50)= NULL
DECLARE @ENTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

DECLARE @IDXRHSHS INT;

select top 1 @IDXRHSHS=ID from XRHSEIS where getdate() between FIRSTDATE and LASTDATE

SELECT @AFMXREOUMENOU = AFM FROM ACCOUNTS WHERE ID = @IDENTOLEA
SELECT @AFMENTOLEA = AFM, @ENTOLEASDESCR = Eponimia FROM ACCOUNTS WHERE ID = @IDENTOLEA

SELECT 
	@AFMAPOSTOLEA = AFM, 
	@APOSTOLEASDESCR = Eponimia,
	@PERIOXIFORTOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDAPOSTOLEA

SELECT 
	@AFMPARALIPTI = AFM, 
	@PARALISPTISDESCR = Eponimia,
	@PERIOXIPARADOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDPARALIPTI

SELECT 
	@AFMTRITOU = AFM, 
	@TRITOSDESCR = Eponimia
FROM ACCOUNTS WHERE ID = @IDTRITOU

SELECT TOP 1
	@IDKINDPAYMENT=ID,
	@KINDPAYMENTDESCR=DESCR
FROM KINDOFPAYMENTS
WHERE IF_PISTOSI = 1
AND IF_IN = 1

SELECT TOP 1
	@IDSTATUS=ID,
	@STATUSDESCR=DESCR
FROM DOC_STATUS
WHERE IF_PRINT = 1
AND IFEKDOSI = 1

SELECT 
	@PARAST_SEIRA = SEIRA,
	@PARAST_DESC = DESCR,
	@PARAST_AUTONUMBER = IF_AUTONUMBER,
	@PARAST_TAXISPERCENT = TAXISPERCENT

FROM KINDPARASTATIKON
WHERE ID = @IDPARAST


	--@STATUSDESCR				NVARCHAR(50) = NULL,


EXEC InserttoFORTOTIKES
	@TheID = @TheID output,
	@IDENTOLEA = @IDENTOLEA,
	@IDAPOSTOLEA = @IDAPOSTOLEA,
	@IDPARALIPTI = @IDPARALIPTI,
	@IDTRITOU = @IDTRITOU,
	@IDANTAPOKRITI = -1,
	@IDXREOUMENOU = @IDTRITOU,
	
	@IDPARAST = @IDPARAST,
	@PARASTATIKO = @PARAST_DESC,
	@SEIRA = @PARAST_SEIRA,
	@IFAUTONUMBER = @PARAST_AUTONUMBER,

	@ANTIKCASH = @ANTIKCASH,
	@ANTIKEPIT = @ANTIKEPIT,
	@ANTIKSYNAL = @ANTIKSYNAL,
	@ANTIKOTHER = @ANTIKOTHER,

	@PERIOXIPARADOSIS = @PERIOXIPARADOSIS,
	@PERIOXIFORTOSIS = @PERIOXIFORTOSIS,



	@IFCASH = 0,
	@IFPISTOSI = 1,
	@IFPREPAY = 1,
	@IFOFEILOMENI = 0,
	@DATEPRINT = @DATEPRINT,
	@IDKINDPAYMENT = @IDKINDPAYMENT,
	@KINDPAYMENTDESCR = @KINDPAYMENTDESCR,
	@NO_EXT_ORDER = @NO_EXT_ORDER,
	@EXT_BARCODE = @EXT_BARCODE,
	@STATUS = @IDSTATUS,
	@STATUSDESCR = @STATUSDESCR,
	@AFMXREOUMENOU = @AFMXREOUMENOU,
	@AFMENTOLEA = @AFMENTOLEA,
	@AFMAPOSTOLEA = @AFMAPOSTOLEA,
	@AFMPARALIPTI = @AFMPARALIPTI,
	@AFMTRITOU = @AFMTRITOU,

	@APOSTOLEASDESCR = @APOSTOLEASDESCR,
	@PARALISPTISDESCR = @PARALISPTISDESCR,
	@ENTOLEASDESCR = @ENTOLEASDESCR,
	@TRITOSDESCR = @TRITOSDESCR,
	@DateCreate = @DATEPRINT,
	@UserCreate	='Import Tool',

	@IDXRHSHS = @IDXRHSHS,
	@IDCOMPANY = 1,
	@IDYPOKATASTIMA = 2,
	@TAXISPERCENT = @PARAST_TAXISPERCENT,
	@COMMENTS = @COMMENTS


update F
	SET 
		IFANTIKCASH = CASE WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKEPIT = CASE WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKSYNAL = CASE WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKOTHER = CASE WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1 ELSE 0 END,
		SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER,0),
		IF_FROM_ANTAP = KP.IF_FROM_ANTAP,
		IFXRTRITOU = 1,
		IFPREPAY = ENTOL.IFPREPAY,
		IFCASH = ENTOL.IFCASH,
		IFOFEILOMENI = ENTOL.IFOFEILOMENI,
		IFPISTOSI = ENTOL.IFPISTOSI
from FORTOTIKES F
join KINDPARASTATIKON KP ON KP.ID = F.IDPARAST
join ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
WHERE F.ID = @TheID;


UPDATE F SET
	F.OMADPROORISMOS=OP.Descr

FROM FORTOTIKES F
LEFT JOIN Aar ON Aar.AarName=F.PERIOXIPARADOSIS
LEFT JOIN AarPerOmProor AOM ON AOM.AarID=Aar.AarID
LEFT JOIN OMADIKOI_PROORISMOI OP ON OP.ID=AOM.IDOmProor
WHERE F.ID = @TheID;


INSERT INTO XREOSISANADELTIO(
	IDVOH, 
	IDXREOSIS, 
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_FORTOTIKI,
	IF_TO_VOH
)
SELECT
	FORT.ID,
	XR.ID,
	XR.CODE,
	XR.Descr,
	XR.TAXISPERCENT,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 1
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 0.24
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN 1.24
		ELSE 0
	END,
	1,
	0
		
FROM XREOSISANAPARASTATIKO XAP
JOIN FORTOTIKES FORT ON FORT.IDPARAST = XAP.IDKINDPARASTTIKON
JOIN Xreoseis XR ON XR.ID = XAP.IDXREOSIS
WHERE XAP.ifDelete = 0
AND XR.ifDelete = 0
AND XAP.IDKINDPARASTTIKON = FORT.IDPARAST
AND FORT.ID = @theID;

-- κλαιει η μανα του πελε
with SUMXRPF as (
	select
		xap.IDVOH,
		ISNULL(XR.ifKomistra, 0) ifKomistra,
		ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis,
		ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton,
		ISNULL(xr.ifOther, 0) ifOther,
		ISNULL(xr.IfAsfalistra, 0) ifAsfalistra,
		ISNULL(xr.ifErgatika, 0) ifErgatika,
		ISNULL(xr.IfEmvastika, 0) ifEmvastika,
		sum(xap.POSO) POSO
	from XREOSISANADELTIO XAP
	join Xreoseis XR ON XR.ID = XAP.IDXREOSIS
	where xap.IDVOH = @TheID
	GROUP BY
		GROUPING SETS (
			(IDVOH, ifKomistra),
			(IDVOH, ifDikaiomaFortotikis),
			(IDVOH, ifXreosiTriton),
			(IDVOH, ifOther),
			(IDVOH, IfAsfalistra),
			(IDVOH, ifErgatika),
			(IDVOH, ifEmvastika)
		)
	HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		or ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		or ISNULL(xr.ifXreosiTriton, 0) = 1
		or ISNULL(xr.ifOther, 0) = 1
		or ISNULL(xr.IfAsfalistra, 0) = 1
		or ISNULL(xr.ifErgatika, 0) = 1
		or ISNULL(xr.IfEmvastika, 0) = 1
	)
)
INSERT INTO HEADERFORTOTIKIS (
	IDFORT,
	PARASTATIKOFORT,
	SEIRAFORT,
	NOPARASTFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONFORT,
	BAROSFORT,
	KYBIKAFORT,
	POSOFORT,
	TEMAXIAFORT
)
select
	FORT.ID,
	FORT.PARASTATIKO,
	FORT.SEIRA,
	FORT.NOPARAST,
	FORT.ENTOLEASDESCR,
	FORT.PARALISPTISDESCR,
	FORT.APOSTOLEASDESCR,
	ISNULL(SUM_KOMISTRA.POSO, 0),
	ISNULL(SUM_DIKAIOMA.POSO, 0),
	ISNULL(SUM_OTHER.POSO, 0),
	ISNULL(GF.SYSKEVASIA, 0),
	ISNULL(SUM_ASFALISTRA.POSO, 0),
	
	--katharo?
	FORT.POSO,

	FORT.TAXIS,
	SUMXR.POSO,
	ISNULL(SUM_ERGATIKA.POSO, 0),
	ISNULL(SUM_TRITON.POSO, 0),
	
	--oliko synolo xreoson ?!
	SUMXR.POSO,
	
	ISNULL(GF.BAROS, 0),
	ISNULL(GF.KYBIKA, 0),

	--what the fuck den perigrafw allo
	FORT.POSO,
	ISNULL(GF.TEMAXIA, 0)

from fortotikes FORT
left join (
	SELECT 
		IDVOH,
		MIN(SYSKEVASIA) SYSKEVASIA,
		SUM(BAROS) BAROS,
		SUM(KYBIKA) KYBIKA,
		SUM(TEMAXIA) TEMAXIA
	FROM GRAMMESFORTTIKIS
	GROUP BY IDVOH
) GF ON GF.IDVOH = FORT.ID
left join SUMXRPF SUM_KOMISTRA on SUM_KOMISTRA.ifKomistra = 1
left join SUMXRPF SUM_DIKAIOMA on SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
left join SUMXRPF SUM_OTHER on SUM_OTHER.ifOther = 1
left join SUMXRPF SUM_ASFALISTRA ON SUM_ASFALISTRA.ifAsfalistra = 1
left join SUMXRPF SUM_ERGATIKA ON SUM_ERGATIKA.ifErgatika = 1
left join SUMXRPF SUM_TRITON ON SUM_TRITON.ifXreosiTriton = 1
left join (
	SELECT IDVOH, SUM(POSO) POSO FROM XREOSISANADELTIO GROUP BY IDVOH
) SUMXR ON SUMXR.IDVOH = FORT.ID

where id = @TheID


GO


---END SCRIPT 1618
------------------------------------------------------------------------------------

---NEW SCRIPT 1619


ALTER PROCEDURE [dbo].[InserttoACCOUNTS_IMPORT]
(
	@Name			VARCHAR(50),
	@Address		VARCHAR(50),
	@ZipCode		VARCHAR(10) = NULL,
	@Telephone		VARCHAR(20) = NULL,
	@Mobile			VARCHAR(20) = NULL,
	@Email			VARCHAR(50) = NULL,
	@CityID			INT,
	@ExternalID		NVARCHAR(20) = NULL,
	@TheID			INT = NULL output
	
	)
AS

SET NOCOUNT ON;

DECLARE @AddressCity NVARCHAR(50)

SELECT TOP 1 @AddressCity = AarName FROM Aar WHERE AarId = @CityID

EXEC InserttoACCOUNTS
	@Eponimia				= @Name,
	@Epagelma				= '',
	@LastName				= '',
	@FirstName				= '',
	@AddressStr				= @Address,
	@AddressNo				= '',
	@AddressTK				= @ZipCode,
	@AddressCity			= @AddressCity,
	@Tel					= @Telephone,
	@Mobile					= @Mobile,
	@Fpa					= '1 - Κανονικό',
	@IF_PROM				=	0,
	@IF_PEL					=	1,
	@IF_ERG					=	0,
	@AddrFortosis			=	@Address,
	@IF_ANTAPOKRITIS		= 0,
	@Comments				= '',
	@IDPARAST				= 0,
	@EMAIL					=	@Email,
	@XREOUMENOS				= 1,
	@CATKEPYO				= 0,
	@EXT_ID					= @ExternalID,
	@TheID					= @TheID output;


	UPDATE ACC
	    SET 
			Code = 'PEL-' + CONVERT(NVARCHAR, @TheID),
			AddressPref = Ast.AstName,
		    AddressCountry = Acr.AcrName,
		    AddressZone = DEP.DESCR
		FROM ACCOUNTS ACC
    LEFT JOIN AAR AAR1 ON REPLACE(AAR1.AarZipCode, ' ', '') = REPLACE(ACC.AddressTK, ' ', '') AND LEN(AAR1.AarZipCode) > 4
    LEFT JOIN AAR AAR2 ON AAR2.AarName = ACC.AddressCity AND LEN(AAR2.AarName) > 1
    JOIN AAR ON AAR.AarID = COALESCE(AAR1.AarID, AAR2.AarID, 0)
    JOIN Ast ON AST.AstID = AAR.AarAstID
    JOIN Departements DEP ON DEP.ID = AST.IDDEPARTEMENT
    JOIN ACR ON ACR.AcrID = Ast.AstAcrID
    WHERE ACC.ID = @TheID

GO


---END SCRIPT 1619
------------------------------------------------------------------------------------

---NEW SCRIPT 1620



ALTER VIEW [dbo].[ENTOLES_METAFORAS_VIEW_NEW]
AS
select 
	VOH.ID,
	voh.identolea [IDENTOLEA],
	paraliptis.id [IDPARALIPTI],
	apostoleas.id [IDAPOSTOLEA],
	kentrakostous.id [IDKENTROKOSTOUS],
	sugkentrotiko.id [IDSYGKENTROTIKO],
	voh.idparast [IDPARAST],
	VOH.IDXRHSHS,
	VOH.IDCOMPANY,
	companies.id [IDYPOKATASTIMA],
	companies.Eponimia [YPOKATASTHMA], 										--[Κατάστημα Εντολής],
	convert(date, voh.Dateprint) [DATEPRINT], 								--[Ημερομηνία Εντολής],
	month(voh.DATEPRINT) [MONTHDATE], 										--[Μήνας Εντολής],
	KPR.Code,
	voh.PARASTATIKO [PARASTATIKO], 											--[Τύπος Παραστατικού],
	voh.SEIRA [SEIRA], 														--[Σειρά Παραστατικού],
	convert(nvarchar(20),voh.NOPARAST) [NOPARAST], 							--[Αριθμός Παραστατικού],
	rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE], 	--[Barcode ID Παραστατικού],
	voh.arrival [ARRIVAL], 													--[Αριθμός Άφιξης],
	voh.aranaforas [ARANAFORAS], 												--[Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK], 								--[Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR, 													--[Τρόπος Πληρωμής],
	cast(voh.SUMPOSO as float) [SUMPOSO], 									--[Αξία Παραστατικού (Συνολική)],
	cast(voh.poso as float) [POSO], 										--[Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [TAXIS], 										--[Αξία Παραστατικού (ΦΠΑ)],
	
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_DISCOUNT_ALL], 													--[Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [IF_DISCOUNT_SERVICE], 												--[Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [KENTRO_KOSTOUS], 									--[Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [AXIA_EMPOREUMATON], 								--[Αξία Εμπορευμάτων Παραστατικού],
	null [RESERVATION_DATE], 												--[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [RESERVATION_SLOT], 												--[SLOT Υπηρεσίας Σύμφωνα με Reservation],
	FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS [NOPARASTDELTIOUAPOSTOLIS],			--[Αρ. Διπλότυπης Καταστήματος],
	KAA.DATEPRINT [KAA_DATE], 												--[Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [KAA_MONTH], 										--[Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [KAA_TRUCK], 													--[Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [KAA_DRIVER] , 												--[Οδηγός Διπλότυπης Καταστήματος],	
	FORTOTIKES.SEIRA + convert(nvarchar(20),FORTOTIKES.NOPARAST) [NOPARASTFORTOTIKI], 							--[Αριθμός Παραστατικού],
	FORTOTIKES.NOLISTASDIANOMIS [NOPARASTDELTIOUDIANOMIS], 						--[Αρ. Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DATEPRINT [LISTADIANOMIS_DATE], 							--[Ημερομηνία Διπλότυπης Κέντρου Διανομής],
	MONTH(LISTESDIANOMIS.DATEPRINT) [LISTADIANOMIS_MONTH], 					--[Μήνας Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.OXIMA [LISTADIANOMIS_TRUCK], 							--[Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DRIVER [LISTADIANOMIS_DRIVER], 							--[Οδηγός Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.STATUS [LISTADIANOMIS_STATUS], 							--[Status Διπλότυπης Κέντρου Διανομής],
	cast(grammesvohsum.temaxia as float) AS [TEMAXIA], 							--[Σύνολο Τεμαχίων],
	grammesvohsum.countid [POSOTHTA], 										--[Σύνολο κωδικών εμπορευμάτων],
	cast(grammesvohsum.baros as float) [BAROS], 							--[Συνολικό Βάρος],
	cast(grammesvohsum.kybika as float) [KYBIKA], 							--[Συνολικός Όγκος],
	voh.COMMENTS [COMMENTS], 												--[Σχόλια - Παρατηρήσεις],
	paraliptis.Eponimia [PARALISPTISDESCR], 								--[Επωνυμία Παραλήπτη],
	paraliptis.AddressTK [PARALIPTIS_ZIPCODE], 								--[ΤΚ Παραλήπτη],
	NULL  [PARALIPTIS_ZONE], 												--[Ζώνη ΤΚ Παραλήπτη],
	paraliptis.AddressCity [PARALIPTIS_CITY], 								--[Περιοχή Παραλήπτη],
	paraliptis.AddressPref [PARALIPTIS_NOMOS], 								--[Νομός Παραλήπτη],
	paraliptis.AddressStr [PARALIPTIS_ADDRESS], 							--[Διεύθυνση Παραλήπτη],
	paraliptis.Mobile [PARALIPTIS_MOBILE], 									--[Κινητό Τηλέφωνο Παραλήπτη],
	paraliptis.Tel [PARALIPTIS_TELEPHONE], 									--[1ο Τηλέφωνο Παραλήπτη],
	voh.OROFOS [OROFOS], 
	VOH.AFMENTOLEA,													--[Όροφος Παράδοσης Παραλήπτη],
	voh.ENTOLEASDESCR,			 											--[Επωνυμία Εντολέα],
	apostoleas.Eponimia [APOSTOLEASDESCR],									--[Επωνυμία Αποστολέα],
	apostoleas.AddressTK [APOSTOLEAS_ZIPCODE], 								--[ΤΚ Αποστολέα],
	NULL [APOSTOLEAS_ZONE], 												--[Ζώνη ΤΚ Αποστολέα],
	apostoleas.AddressCity [APOSTOLEAS_CITY], 								--[Περιοχή Αποστολέα],
	apostoleas.AddressPref [APOSTOLEAS_NOMOS], 								--[Νομός Αποστολέα],
	apostoleas.addressstr [APOSTOLEAS_ADDRESS], 							--[Διεύθυνση Αποστολέα],
	apostoleas.Mobile [APOSTOLEAS_MOBILE], 									--[Κινητό Τηλέφωνο Αποστολέα],
	apostoleas.Tel [APOSTOLEAS_TELEPHONE], 									--[1ο Τηλέφωνο Αποστολέα],
	headervohpricing.DescrCatalog [TIMOKATALOGOS], 							--[Τιμοκατάλογος Παραστατικού],
	paradoseis.PARADOSISE,
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_PRAKTOREIO_EPILOGHS], 											--[Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_XREOSI_DELATOLAS], 												--[Δελατόλας Καταβάλλων τα Κόμιστρα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN ''
		else paradoseis.Eponimia
	end [PRAKTOREIO_EPILOGHS], 												--[Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
	voh.PRAKTOREIODESCR [PRAKTOREIODESCR], 									--[Πρακτορείο Συνεργάτης],
	case ISNULL(VOH.IF_CLOSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IF_CLOSE_ALREADY], 												--[Τιμολογημένη κατα την έκδοση],
	case ISNULL(VOH.IFCHECKED, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFCHECKED], 														--  ΑΝ ΕΛΕΓΧΘΗΚΕ
	case ISNULL(VOH.IFREVERSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFREVERSE], 														-- ΑΝ ΕΙΝΑΙ ΕΠΙΣΤΡΟΦΗ
	voh.UserMod [USEMOD], 													--[Χρήστης μεταβολής Εντολής],
	-- syndedemeno pistwtiko parastatiko ?
	NULL [ID_PISTOTIKO], 													--[Συνδεδεμένο Πιστωτικό Παραστατικό],
	NULL [PISTOTIKODESCR], 													--[Είδος Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_DATE], 													--[Ημερομηνία Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_MONTH], 												--[Μήνας Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_SEIRA], 												--[Σειρά Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_NO], 													--[Αρ. Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_BARCODE], 												--[Barcode ID Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_SUMPOSO], 												--[Αξία Πιστωτικού Παραστατικού (Συνολική)],
	NULL [PISTOTIKO_KATHARO],												--[Αξία Πιστωτικού Παραστατικού (Καθαρή)],
	NULL [PISTOTIKO_FPA], 													--[Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
	NULL [PISTOTIKO_USERCREATE], 											--[Εκδόσας Πιστωτικού],
	case isnull(kpr.IF_TRANSFORM, 0)
		when 0 then 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_TRANSFORM_INFORM], 												--[Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο], 
	case 
		when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_TRANSFORMED], 													--[Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
	sugkentrotiko.DATEPRINT [SYGKENTROTIKO_DATE], 							--[Ημερομηνία Τιμολόγησης],
	month(sugkentrotiko.DATEPRINT) [SYGKENTROTIKO_MONTH], 					--[Μήνας Τιμολόγησης],
	sugkentrotiko.seira [SYGKENTROTIKO_SEIRA], 								--[Σειρά Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.NOPARAST [SYGKENTROTIKO_NOPARAST], 						--[Αρ. Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.EXT_BARCODE [SYGKENTROTIKO_EXT_BARCODE],					--[Barcode ID Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.SUMPOSO [SYGKENTROTIKO_SUMPOSO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
	sugkentrotiko.poso [SYGKENTROTIKO_KATHARO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
	sugkentrotiko.taxis [SYGKENTROTIKO_FPA], 								--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
	sugkentrotiko.UserCreate [SYGKENTROTIKO_USERCREATE], 					--[Εκδόσας Τιμολογίου],
	null [SYGKENTROTIKO_PISTOTIKOID], 										--[Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]
	VOH.IF_CLOSE,
	kpr.IF_ORDER,
	KPR.KindKINISIS,
	kpr.IF_EDMETAFORAS,
	kpr.IF_EDSYNARMOL,
	kpr.IF_ENDILMETAFORAS,
	kpr.IF_EDTOPOTH,
	VOH.NO_EXT_ORDER,
	VOH.NOPARASTLISTASSYNARMOLOGISIS,
	COMPANIES.AddressStr [ADDRESS_YPOKATASTHMA],
	COMPANIES.AddressTK [TK_YPOKATASTHMA],
	COMPANIES.AddressCity [CITY_YPOKATASTHMA],
	COMPANIES.BARCODE_Prefix [BARCODEPREFIX_YPOKAT],
	COMPANIES.EMAIL [EMAIL_YPOKATASTHMA],
	DBO.GetVOHEAFDSS(VOH.ID, 1) AS EAFDSS,
	VOH.CustDescr,
	VOH.EPAGELMA,
	VOH.AFM,
	VOH.CITY,
	VOH.TEL,
	VOH.MOBILE,
	VOH.OXIMA,
	VOH.OMADPROORISMOS,
	CASE 
	WHEN VOH.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN 'ΑΠΟΣΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
	ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
	ELSE 'ΑΓΝΩΣΤΟ' 
	END 
	END
	END 
	END AS XREOΥMENOS,
	GRAMMESVOH.TIMDA,
	CASE 
		WHEN VOH.IFPREPAY=1 THEN 1 ELSE 0
	END AS XREOSIPROPLIROMENES,		
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 1 ELSE 0
	END AS XREOSIOFEILOMENES,
	GRAMMESVOH.PERIEXOMENO,
	VOH.PERIOXIFORTOSIS,
	voh.UserCreate [USERCREATE], 											--[Χρήστης εκδόσας την Εντολή],
	VOH.PERIOXIPARADOSIS,
	VOH.SUMANTIK,
	VOH.STATUS,
	VOH.DATEPARAD,
	VOH.IDPRAKTOREIO,
	VOH.ANTIKCASH,
	VOH.ANTIKEPIT,
	VOH.ANTIKSYNAL,
	VOH.ANTIKOTHER,
	VOH.IFCANCELANTIK,
	VOH.COMMENTSANTIK,
	VOH.DATEPARADOSI,
	VOH.COMMENTS2,
	VOH.IDEMPLOYEE,
	VOH.EMPLOYEE,
	VOH.SERVICEZONE,									-- Ζώνη Υπηρεσίας
	CASE	
		WHEN VOH.IFPREPAY= 1 THEN 'ΝΑΙ' 
		ELSE 'ΟΧΙ'
	END AS IFPREPAY,
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFOFEILOMENI,
	GRAMMESVOH.AXIA,
	CASE
		WHEN VOH.IFXRENTOL=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFXRENTOL,
	VOH.IDKINDPAYMENT,
	CASE VOH.IFXRAPOST 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRAPOST,
	CASE VOH.IFXRPARAL 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRPARAL,
	CASE VOH.IFXRTRITOU 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRTRITOU,
	VOH.IFANTIKCASH,
	--VOH.ANTIKEPIT,
	--VOH.ANTIKSYNAL,
	--VOH.ANTIKOTHER,
	VOH.ifDelete,
	VOH.IFCANCEL,
	VOH.DATECANCEL,
	VOH.IFPARADOSI,
	VOH.AITIOLOGIAPARASTATIKOU,
	VOH.DATEFORTOSIS,
	VOH.IFEPISTROFI,
	VOH.DATEEPISTROFIS,
	VOH.AITIOLOGIAEPISTROFIS,
	VOH.COMMENTSEPISTROFIS,
	VOH.IFCASH,
	VOH.IFPISTOSI,
	VOH.STATUSDESCR,
	VOH.YPAITIOS,
	VOH.IFEPANADROMOLOGISI,
	VOH.IFEPANEKDOSI,
	VOH.IFOKEPANADROMOLOGISI,
	VOH.NOPARASTANTIK,
	VOH.COMMENTSAKIROSIS,
	VOH.IFEISPRANTIK,
	VOH.IFPARADOSIANTIK,
	VOH.IFPARALAVIANTIK,
	VOH.COMMENTSPARADANTIK,
	VOH.COMMANTSPARALANTIK,
	VOH.COMMENTSEISPRANTIK,
	VOH.DATEPARADANTIK,
	VOH.DATEPARALANTIK,
	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
	VOH.NOPARPARALANTIK,
	VOH.DATEPARAL,
	VOH.COMMENTSPARAD,
	VOH.COMMANTSPARAL,
	VOH.TIMEPARALFROM,
	VOH.TIMEPARALTO,
	VOH.TIMEPARADFROM,
	VOH.TIMEPARADTO,
	VOH.DATECANCELANTIK,
	VOH.TAXISPERCENT,
	VOH.ANAMEXODO,
	VOH.ID AS IDVOH,
	CASE 
		WHEN VOH.IFXRENTOL = 1 THEN VOH.IDENTOLEA 
		ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN VOH.IDAPOSTOLEA 
	ELSE 
	CASE 
		WHEN VOH.IFXRTRITOU = 1 THEN VOH.IDTRITOU 
		ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN VOH.IDPARALIPTI 
	ELSE VOH.IDCUSTOMER 
	END 
	END
	END 
	END AS IDXREOUMENOU,
	VOH.AFMXREOUMENOU,
	HEADERVOH.ASFALISTRA,
	HEADERVOH.TAXISXREOSEON,
	HEADERVOH.SUMPOSOXRVOH,
	--VOH.OROFOS,
	VOH.OROFOSDESCR,
	VOH.KOUDOUNI,
	VOH.POSOEPIVAR,
	VOH.TAXISEPIVAR,
	VOH.SUMPOSOEPIVAR,
	(VOH.POSO + VOH.POSOEPIVAR) AS SUMKATHARO,
	(VOH.TAXIS + VOH.TAXISEPIVAR) AS SUMTAXIS, 
    (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) AS SUMSUMPOSO,
    HEADERVOH.KATHARO,
    VOH.THETIME,
    VOH.IDENTOLEA AS CUSTOMERID,
    VOH.ENTOLEASDESCR AS CUSTOMERDESCR,
    VOH.IDAPOSTOLEA AS IDSYNAL, 
    VOH.APOSTOLEASDESCR AS SYNALDESCR,
	VOH.IDCUSTOMER,
	VOH.DOY, 
    VOH.ADDRESSSTREET,
    VOH.ADDRESSNO, 
    VOH.PREF, 
    VOH.AFMAPOSTOLEA,
    APOSTOLEAS.Epagelma AS SYNALEPAGELMA, 
    APOSTOLEAS.AddressStr AS SYNALADDRSTR,
    APOSTOLEAS.AddressNo AS SYNALADDRNO, 
    APOSTOLEAS.AddressTK AS SYNALADDRTK, 
    APOSTOLEAS.AddressCity AS SYNALCITY,
    VOH.IDXREOUMENOUENTOLIS,
    APOSTOLEAS.AddressCountry AS SYNALADDRCOUNTRY, 
    APOSTOLEAS.Tel AS SYNALTEL, 
    APOSTOLEAS.DOY AS SYNALDOY, 
    APOSTOLEAS.AFM AS AFMSYNAL,--SYNALAFM,
    CUSTOMERS.AddressTK AS CUSTADDRTK, 
    CUSTOMERS.AddressNo AS CUSTADDRNO, 
    CUSTOMERS.AddressStr AS CUSTADDRSTR,
    VOH.IF_ANTIKCASHSYNAR,
    VOH.ANTIKCASHSYNAR,
    CUSTOMERS.AddressCity AS CUSTADDRCITY, 
    CUSTOMERS.AFM AS AFMCUSTOMER,--CUSTAFM, 
    CUSTOMERS.DOY AS CUSTDOY,
    paraliptis.AFM AS AFMPARALIPTI,--PARALAFM, 
    paraliptis.Epagelma AS PARALEPAGELMA, 
    paraliptis.AddressStr AS PARALADDRSTR,
    grammesvohsum.baros as SUMBAROS,
    paraliptis.AddressNo AS PARALADDRNO, 
    paraliptis.AddressTK AS PARALADDRTK, 
    paraliptis.AddressCity AS PARALCITY,
    EMPLOYEE.AFM AS AFMEMPLOYEE, --EMPLAFM, 
    EMPLOYEE.DOY AS EMPLDOY, 
    EMPLOYEE.Epagelma AS EMPLLEPAGELMA, 
    EMPLOYEE.AddressStr AS EMPLADDRSTR,
    EMPLOYEE.AddressNo AS EMPLADDRNO, 
    EMPLOYEE.AddressTK AS EMPLADDRTK, 
    EMPLOYEE.AddressCity AS EMPLLCITY,
    kpr.IF_TRANSFORM

from voh
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
JOIN ACCOUNTS CUSTOMERS ON CUSTOMERS.ID=VOH.IDCUSTOMER
LEFT JOIN EMPLOYEE ON EMPLOYEE.id=VOH.IDEMPLOYEE
join (
	select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
left join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
left join (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		SUM(TEMAXIA) countid,
		sum(BAROS) baros,
		sum(KYBIKA) kybika
	from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
left JOIN (SELECT
		IDVOH,
		SUM(SUMPOSO) AS AXIA,
		MIN(TIMDA) AS TIMDA,
		MIN(PERIEXOMENO) AS PERIEXOMENO
	  FROM GRAMMESVOH
	  GROUP BY IDVOH
	  )GRAMMESVOH ON GRAMMESVOH.IDVOH=VOH.ID 
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.IDENTOLIS = voh.id
left join voh sugkentrotiko on sugkentrotiko.SEIRA + convert(nvarchar(20),sugkentrotiko.NOPARAST) = fortotikes.NOPARASTDELTIOUDIANOMIS
left join (
	SELECT IDFORTOTIKIS, MAX(IDKAA) IDKAA FROM FORTOTIKES_ANA_KAA GROUP BY IDFORTOTIKIS
) FAK on FAK.IDFORTOTIKIS = FORTOTIKES.ID
left join KAA on KAA.ID = FAK.IDKAA
join KINDPARASTATIKON kpr on kpr.id=voh.IDPARAST and kpr.IF_EDMETAFORAS=1

left join (
	SELECT MAX(IDLISTAS) IDLISTAS, IDFORTOTIKIS FROM FORTOTIKES_ANA_LISTA GROUP BY IDFORTOTIKIS
) FAL ON FAL.IDFORTOTIKIS = FORTOTIKES.ID
left join LISTESDIANOMIS on LISTESDIANOMIS.id = FAL.IDLISTAS
LEFT JOIN(
		SELECT 
		IDVOH,
		SUM(KOMISTRA) AS KOMISTRA,
		SUM(XREOSISTRITON) AS XREOSISTRITON,
		SUM(DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORT,
		SUM(OTHERXREOSIS) AS OTHERXREOSIS,
		SUM(ASFALISTRA) AS ASFALISTRA,
		SUM(TAXIS) AS TAXISXREOSEON,
		SUM(SUMPOSOXRVOH) AS SUMPOSOXRVOH,
		SUM(KATHARO) AS KATHARO
		FROM HEADERVOH
		GROUP BY IDVOH
		)HEADERVOH ON HEADERVOH.IDVOH=VOH.ID
--where  voh.ifDelete = 0 




GO



---END SCRIPT 1620
------------------------------------------------------------------------------------

---NEW SCRIPT 1621


ALTER VIEW [dbo].[ENTOLES_SYNARMOLOGISIS_VIEW_NEW]
AS
select 
	
	case ISNULL(VOH.IFCHECKED, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFCHECKED], 														--  ΑΝ ΕΛΕΓΧΘΗΚΕ
	voh.identolea [IDENTOLEA],
	paraliptis.id [IDPARALIPTI],
	apostoleas.id [IDAPOSTOLEA],
	kentrakostous.id [IDKENTROKOSTOUS],
	sugkentrotiko.id [IDSYGKENTROTIKO],
	voh.idparast [IDPARAST],
	VOH.IDXRHSHS,
	VOH.IDCOMPANY,
	companies.id [IDYPOKATASTIMA],
	companies.Eponimia [YPOKATASTHMA], 										--[Κατάστημα Εντολής],
	convert(date, voh.Dateprint) [DATEPRINT], 								--[Ημερομηνία Εντολής],
	RTRIM(timol.SEIRA)+ convert(nvarchar(20),timol.NOPARAST) as NOTIMOL,							--[Αριθμός που Τιμολογήθηκε η Εντολή]
	rtrim(VOH.SEIRA)+ convert(nvarchar(20),VOH.NOPARAST) [EXT_BARCODE], 	--[Barcode ID Παραστατικού],
	cast(voh.SUMPOSO as float) [SUMPOSO], 									--[Αξία Παραστατικού (Συνολική)],
	month(voh.DATEPRINT) [MONTHDATE], 										--[Μήνας Εντολής],
	LISTESSYNARMOLOGISIS.DATEPRINT	[DATE_LISTAS_ASS],						--[Ημερ. Λίστας Ανάθεσης],
	listessynarmologisis.PARASTATIKO [PARASTATIKO_ASS],						--[Παραστατικό Ανάθεσης],
	listessynarmologisis.EMPLOYEE [SYNERGATIS],								--[Συνεργάτης],
	rtrim(listessynarmologisis.seira)+ listessynarmologisis.NOPARAST [NOPARAST_LISTAS_ASS], --[Αρ.Λίστας Ανάθεσης],
	VOH.EMPLOYEE,
	paraliptis.Eponimia [PARALISPTISDESCR], 								--[Επωνυμία Παραλήπτη],
	paraliptis.Mobile [PARALIPTIS_MOBILE], 									--[Κινητό Τηλέφωνο Παραλήπτη],
	paraliptis.AddressCity [PARALIPTIS_CITY], 								--[Περιοχή Παραλήπτη],
	VOH.COMMENTS2,
	paraliptis.AddressTK [PARALIPTIS_ZIPCODE], 								--[ΤΚ Παραλήπτη],

	KPR.Code,
	voh.PARASTATIKO [PARASTATIKO], 											--[Τύπος Παραστατικού],
	voh.SEIRA [SEIRA], 														--[Σειρά Παραστατικού],
	convert(nvarchar(20),voh.NOPARAST) [NOPARAST], 												--[Αριθμός Παραστατικού],
	voh.arrival [ARRIVAL], 													--[Αριθμός Άφιξης],
	voh.aranaforas [ARANAFORAS], 											--[Αρ. Αναφοράς ΙΚΕΑ],
	voh.NO_EXT_ORDER_IK [NO_EXT_ORDER_IK], 									--[Αρ. Παραγγελίας ΙΚΕΑ],
	voh.KINDPAYMENTDESCR, 													--[Τρόπος Πληρωμής],
	cast(voh.poso as float) [POSO], 										--[Αξία Παραστατικού (Καθαρή)],
	cast(voh.TAXIS as float) [TAXIS], 										--[Αξία Παραστατικού (ΦΠΑ)],
	case
		when voh.DISCOUNT > 0 or voh.DISCOUNTPerCent > 0 then 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_DISCOUNT_ALL], 													--[Έχει λάβει έκπτωση (Γενική)],
	case 
		when HEADERVOHPRICING.discounteuro > 0 or HEADERVOHPRICING.discountpercent > 0 then 'ΝΑΙ' 
		else 'ΟΧΙ'
	end [IF_DISCOUNT_SERVICE], 												--[Έχει λάβει έκπτωση (Υπηρεσίας)],
	kentrakostous.Descr [KENTRO_KOSTOUS], 									--[Κέντρο Κόστους Παραστατικού],
	grammesvohsum.timitem [AXIA_EMPOREUMATON], 								--[Αξία Εμπορευμάτων Παραστατικού],
	null [RESERVATION_DATE], 												--[Ημερομηνία Υπηρεσίας Σύμφωνα με Reservation],
	null [RESERVATION_SLOT],												--[SLOT Υπηρεσίας Σύμφωνα με Reservation],
	
	
	listessynarmologisis.STATUS [STATUS_LISTAS_ASS],						--[Κατάσταση Λίστας Ανάθεσης], 												
	KAA.DATEPRINT [KAA_DATE], 												--[Ημερομηνία Διπλότυπης Καταστήματος],
	MONTH(KAA.DATEPRINT) [KAA_MONTH], 										--[Μήνας Διπλότυπης Καταστήματος],
	KAA.OXIMA [KAA_TRUCK], 													--[Αρ. Οχήματος Διπλότυπης Καταστήματος],
	KAA.DRIVER [KAA_DRIVER] , 												--[Οδηγός Διπλότυπης Καταστήματος],
	LISTESDIANOMIS.DATEPRINT [LISTADIANOMIS_DATE], 							--[Ημερομηνία Διπλότυπης Κέντρου Διανομής],
	MONTH(LISTESDIANOMIS.DATEPRINT) [LISTADIANOMIS_MONTH], 					--[Μήνας Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.OXIMA [LISTADIANOMIS_TRUCK], 							--[Αρ. Οχήματος Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.DRIVER [LISTADIANOMIS_DRIVER], 							--[Οδηγός Διπλότυπης Κέντρου Διανομής],
	LISTESDIANOMIS.STATUS [LISTADIANOMIS_STATUS], 							--[Status Διπλότυπης Κέντρου Διανομής],
	cast(grammesvohsum.temaxia as float) AS [TEMAXIA], 							--[Σύνολο Τεμαχίων],
	grammesvohsum.countid [POSOTHTA], 										--[Σύνολο κωδικών εμπορευμάτων],
	cast(grammesvohsum.baros as float) [BAROS], 							--[Συνολικό Βάρος],
	cast(grammesvohsum.kybika as float) [KYBIKA], 							--[Συνολικός Όγκος],
	voh.COMMENTS [COMMENTS], 												--[Σχόλια - Παρατηρήσεις],
	VOH.ID,
	
	NULL  [PARALIPTIS_ZONE], 												--[Ζώνη ΤΚ Παραλήπτη],
	
	paraliptis.AddressPref [PARALIPTIS_NOMOS], 								--[Νομός Παραλήπτη],
	paraliptis.AddressStr [PARALIPTIS_ADDRESS], 							--[Διεύθυνση Παραλήπτη],
	
	paraliptis.Tel [PARALIPTIS_TELEPHONE], 									--[1ο Τηλέφωνο Παραλήπτη],
	voh.OROFOS [OROFOS], 	
	VOH.AFMENTOLEA,															--[Όροφος Παράδοσης Παραλήπτη],
	voh.ENTOLEASDESCR,			 											--[Επωνυμία Εντολέα],
	apostoleas.Eponimia [APOSTOLEASDESCR],									--[Επωνυμία Αποστολέα],
	apostoleas.AddressTK [APOSTOLEAS_ZIPCODE], 								--[ΤΚ Αποστολέα],
	NULL [APOSTOLEAS_ZONE], 												--[Ζώνη ΤΚ Αποστολέα],
	apostoleas.AddressCity [APOSTOLEAS_CITY], 								--[Περιοχή Αποστολέα],
	apostoleas.AddressPref [APOSTOLEAS_NOMOS], 								--[Νομός Αποστολέα],
	apostoleas.addressstr [APOSTOLEAS_ADDRESS], 							--[Διεύθυνση Αποστολέα],
	apostoleas.Mobile [APOSTOLEAS_MOBILE], 									--[Κινητό Τηλέφωνο Αποστολέα],
	apostoleas.Tel [APOSTOLEAS_TELEPHONE], 									--[1ο Τηλέφωνο Αποστολέα],
	headervohpricing.DescrCatalog [TIMOKATALOGOS], 							--[Τιμοκατάλογος Παραστατικού],
	rtrim(sugkentrotiko.seira)+sugkentrotiko.NOPARAST [SYGKENTROTIKO_NOPARAST], 	--[Αρ. Συγκεντρωτικού Τιμολογίου],
	
	RTRIM(LTRIM(KAA.SEIRA)) + KAA.NOPARAST [NOPARASTDELTIOUAPOSTOLIS],			--[Αρ. Διπλότυπης Καταστήματος], KAA
	RTRIM(LTRIM(LISTESDIANOMIS.SEIRA)) + LISTESDIANOMIS.NOPARAST [NOPARASTDELTIOUDIANOMIS], 						--[Αρ. Διπλότυπης Κέντρου Διανομής], LISTA DIANOMIS
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_PRAKTOREIO_EPILOGHS], 											--[Πρακτορείο Επιλογής Πελάτη],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_XREOSI_DELATOLAS], 												--[Δελατόλας Καταβάλλων τα Κόμιστρα],
	case paradoseis.PARADOSISE
		when 'Παραλήπτη' THEN ''
		else paradoseis.Eponimia
	end [PRAKTOREIO_EPILOGHS], 												--[Επωνυμία Επιλογής Πρακτορείου Παράδοσης],
	voh.PRAKTOREIODESCR [PRAKTOREIODESCR], 									--[Πρακτορείο Συνεργάτης],
	case ISNULL(VOH.IF_CLOSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IF_CLOSE_ALREADY], 												--[Τιμολογημένη κατα την έκδοση],
	case ISNULL(VOH.IFREVERSE, 0)
		WHEN 1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END [IFREVERSE], 														-- ΑΝ ΕΙΝΑΙ ΕΠΙΣΤΡΟΦΗ
	voh.UserMod [USEMOD], 													--[Χρήστης μεταβολής Εντολής],
	-- syndedemeno pistwtiko parastatiko ?
	NULL [ID_PISTOTIKO], 													--[Συνδεδεμένο Πιστωτικό Παραστατικό],
	NULL [PISTOTIKODESCR], 													--[Είδος Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_DATE], 													--[Ημερομηνία Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_MONTH], 												--[Μήνας Πιστωτικού Παρσταατικού],
	NULL [PISTOTIKO_SEIRA], 												--[Σειρά Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_NO], 													--[Αρ. Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_BARCODE], 												--[Barcode ID Πιστωτικού Παραστατικού],
	NULL [PISTOTIKO_SUMPOSO], 												--[Αξία Πιστωτικού Παραστατικού (Συνολική)],
	NULL [PISTOTIKO_KATHARO],												--[Αξία Πιστωτικού Παραστατικού (Καθαρή)],
	NULL [PISTOTIKO_FPA], 													--[Αξία Πιστωτικού Παραστατικού (ΦΠΑ)],
	NULL [PISTOTIKO_USERCREATE], 											--[Εκδόσας Πιστωτικού],
	case isnull(kpr.IF_TRANSFORM, 0)
		when 0 then 'ΟΧΙ'
		else 'ΝΑΙ'
	end [IF_TRANSFORM_INFORM], 												--[Για συμμετοχή σε Συγκεντρωτικό Τιμολόγιο], 
	case 
		when sugkentrotiko.id IS NOT NULL THEN 'ΝΑΙ'
		else 'ΟΧΙ'
	end [IF_TRANSFORMED], 													--[Βρίσκεται σε Συγκεντρωτικό Τιμολόγιο],
	sugkentrotiko.DATEPRINT [SYGKENTROTIKO_DATE], 							--[Ημερομηνία Τιμολόγησης],
	month(sugkentrotiko.DATEPRINT) [SYGKENTROTIKO_MONTH], 					--[Μήνας Τιμολόγησης],
	sugkentrotiko.seira [SYGKENTROTIKO_SEIRA], 								--[Σειρά Συγκεντρωτικού Τιμολογίου],
	
	sugkentrotiko.EXT_BARCODE [SYGKENTROTIKO_EXT_BARCODE],					--[Barcode ID Συγκεντρωτικού Τιμολογίου],
	sugkentrotiko.SUMPOSO [SYGKENTROTIKO_SUMPOSO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Συνολική)],
	sugkentrotiko.poso [SYGKENTROTIKO_KATHARO], 							--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (Καθαρή)],
	sugkentrotiko.taxis [SYGKENTROTIKO_FPA], 								--[Αξία Γραμμής Επί Συνολικού Τιμολογίου (ΦΠΑ)],
	sugkentrotiko.UserCreate [SYGKENTROTIKO_USERCREATE], 					--[Εκδόσας Τιμολογίου],
	null [SYGKENTROTIKO_PISTOTIKOID], 										--[Συνδεδεμένο Πιστωτικό Παραστατικό Συγκεντρωτικού Τιμολογίου]
	VOH.IF_CLOSE,
	kpr.IF_ORDER,
	KPR.KindKINISIS,
	kpr.IF_EDMETAFORAS,
	kpr.IF_EDSYNARMOL,
	kpr.IF_ENDILMETAFORAS,
	kpr.IF_EDTOPOTH,
	VOH.NO_EXT_ORDER,
	VOH.NOPARASTLISTASSYNARMOLOGISIS,
	COMPANIES.AddressStr [ADDRESS_YPOKATASTHMA],
	COMPANIES.AddressTK [TK_YPOKATASTHMA],
	COMPANIES.AddressCity [CITY_YPOKATASTHMA],
	COMPANIES.BARCODE_Prefix [BARCODEPREFIX_YPOKAT],
	COMPANIES.EMAIL [EMAIL_YPOKATASTHMA],
	DBO.GetVOHEAFDSS(VOH.ID, 1) AS EAFDSS,
	VOH.CustDescr,
	VOH.EPAGELMA,
	VOH.AFM,
	VOH.CITY,
	VOH.TEL,
	VOH.MOBILE,
	VOH.OXIMA,
	VOH.OMADPROORISMOS,
	CASE 
	WHEN VOH.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN 'ΑΠΟΣΤΟΛΕΑΣ'
	ELSE 
	CASE WHEN VOH.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
	ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
	ELSE 'ΑΓΝΩΣΤΟ' 
	END 
	END
	END 
	END AS XREOΥMENOS,
	GRAMMESVOH.TIMDA,
	CASE 
		WHEN VOH.IFPREPAY=1 THEN 1 ELSE 0
	END AS XREOSIPROPLIROMENES,		
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 1 ELSE 0
	END AS XREOSIOFEILOMENES,
	GRAMMESVOH.PERIEXOMENO,
	VOH.PERIOXIFORTOSIS,
	voh.UserCreate [USERCREATE], 											--[Χρήστης εκδόσας την Εντολή],
	VOH.PERIOXIPARADOSIS,
	VOH.SUMANTIK,
	VOH.STATUS,
	VOH.DATEPARAD,
	VOH.IDPRAKTOREIO,
	VOH.ANTIKCASH,
	VOH.ANTIKEPIT,
	VOH.ANTIKSYNAL,
	VOH.ANTIKOTHER,
	VOH.IFCANCELANTIK,
	VOH.COMMENTSANTIK,
	VOH.DATEPARADOSI,
	
	VOH.IDEMPLOYEE,
	
	voh.SERVICEZONE,
	CASE	
		WHEN VOH.IFPREPAY= 1 THEN 'ΝΑΙ' 
		ELSE 'ΟΧΙ'
	END AS IFPREPAY,
	CASE 
		WHEN VOH.IFOFEILOMENI=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFOFEILOMENI,
	GRAMMESVOH.AXIA,
	CASE
		WHEN VOH.IFXRENTOL=1 THEN 'ΝΑΙ'
		ELSE 'ΟΧΙ'
	END AS IFXRENTOL,
	VOH.IDKINDPAYMENT,
	CASE VOH.IFXRAPOST 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRAPOST,
	CASE VOH.IFXRPARAL 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRPARAL,
	CASE VOH.IFXRTRITOU 
		WHEN 0 THEN 'ΟΧΙ' 
		ELSE 'ΝΑΙ' 
	END AS IFXRTRITOU,
	VOH.IFANTIKCASH,
	--VOH.ANTIKEPIT,
	--VOH.ANTIKSYNAL,
	--VOH.ANTIKOTHER,
	VOH.ifDelete,
	VOH.IFCANCEL,
	VOH.DATECANCEL,
	VOH.IFPARADOSI,
	VOH.AITIOLOGIAPARASTATIKOU,
	VOH.DATEFORTOSIS,
	VOH.IFEPISTROFI,
	VOH.DATEEPISTROFIS,
	VOH.AITIOLOGIAEPISTROFIS,
	VOH.COMMENTSEPISTROFIS,
	VOH.IFCASH,
	VOH.IFPISTOSI,
	VOH.STATUSDESCR,
	VOH.YPAITIOS,
	VOH.IFEPANADROMOLOGISI,
	VOH.IFEPANEKDOSI,
	VOH.IFOKEPANADROMOLOGISI,
	VOH.NOPARASTANTIK,
	VOH.COMMENTSAKIROSIS,
	VOH.IFEISPRANTIK,
	VOH.IFPARADOSIANTIK,
	VOH.IFPARALAVIANTIK,
	VOH.COMMENTSPARADANTIK,
	VOH.COMMANTSPARALANTIK,
	VOH.COMMENTSEISPRANTIK,
	VOH.DATEPARADANTIK,
	VOH.DATEPARALANTIK,
	VOH.DATEEISPRANTIK,
	VOH.EISPRAXASANTIK,
	VOH.NOPARPARADANTIK,
	VOH.NOPARASTEISPRANTIK,
	VOH.NOPARPARALANTIK,
	VOH.DATEPARAL,
	VOH.COMMENTSPARAD,
	VOH.COMMANTSPARAL,
	VOH.TIMEPARALFROM,
	VOH.TIMEPARALTO,
	VOH.TIMEPARADFROM,
	VOH.TIMEPARADTO,
	VOH.DATECANCELANTIK,
	VOH.TAXISPERCENT,
	VOH.ANAMEXODO,
	VOH.ID AS IDVOH,
	CASE 
		WHEN VOH.IFXRENTOL = 1 THEN VOH.IDENTOLEA 
		ELSE 
	CASE WHEN VOH.IFXRAPOST = 1  THEN VOH.IDAPOSTOLEA 
	ELSE 
	CASE 
		WHEN VOH.IFXRTRITOU = 1 THEN VOH.IDTRITOU 
		ELSE 
	CASE WHEN VOH.IFXRPARAL = 1 THEN VOH.IDPARALIPTI 
	ELSE VOH.IDCUSTOMER 
	END 
	END
	END 
	END AS IDXREOUMENOU,
	VOH.AFMXREOUMENOU,
	HEADERVOH.ASFALISTRA,
	HEADERVOH.TAXISXREOSEON,
	HEADERVOH.SUMPOSOXRVOH,
	--VOH.OROFOS,
	VOH.OROFOSDESCR,
	VOH.KOUDOUNI,
	VOH.POSOEPIVAR,
	VOH.TAXISEPIVAR,
	VOH.SUMPOSOEPIVAR,
	(VOH.POSO + VOH.POSOEPIVAR) AS SUMKATHARO,
	(VOH.TAXIS + VOH.TAXISEPIVAR) AS SUMTAXIS, 
    (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) AS SUMSUMPOSO,
    HEADERVOH.KATHARO,
    VOH.THETIME,
    VOH.IDENTOLEA AS CUSTOMERID,
    VOH.ENTOLEASDESCR AS CUSTOMERDESCR,
    VOH.IDAPOSTOLEA AS IDSYNAL, 
    VOH.APOSTOLEASDESCR AS SYNALDESCR,
	VOH.IDCUSTOMER,
	VOH.DOY, 
    VOH.ADDRESSSTREET,
    VOH.ADDRESSNO, 
    VOH.PREF, 
    VOH.AFMAPOSTOLEA,
    VOH.IfTransport,
	VOH.IfAssembly,
	VOH.IfDisAssembly,
	VOH.IfPlacement,  
	VOH.SUMPALETES,
	VOH.SUMDEMATA,
	VOH.SUMSTAND,
	VOH.SUMOGOS,
	VOH.SUMPOSO-VOH.DISCOUNT [TELTIMI],
    APOSTOLEAS.Epagelma AS SYNALEPAGELMA, 
    APOSTOLEAS.AddressStr AS SYNALADDRSTR,
    APOSTOLEAS.AddressNo AS SYNALADDRNO, 
    APOSTOLEAS.AddressTK AS SYNALADDRTK, 
    APOSTOLEAS.AddressCity AS SYNALCITY,
    VOH.IDXREOUMENOUENTOLIS,
    APOSTOLEAS.AddressCountry AS SYNALADDRCOUNTRY, 
    APOSTOLEAS.Tel AS SYNALTEL, 
    APOSTOLEAS.DOY AS SYNALDOY, 
    APOSTOLEAS.AFM AS AFMSYNAL,--SYNALAFM,
    CUSTOMERS.AddressTK AS CUSTADDRTK, 
    CUSTOMERS.AddressNo AS CUSTADDRNO, 
    CUSTOMERS.AddressStr AS CUSTADDRSTR,
    VOH.IF_ANTIKCASHSYNAR,
    VOH.ANTIKCASHSYNAR,
    CUSTOMERS.AddressCity AS CUSTADDRCITY, 
    CUSTOMERS.AFM AS AFMCUSTOMER, --CUSTAFM, 
    CUSTOMERS.DOY AS CUSTDOY,
    paraliptis.AFM AS AFMPARALIPTI, --PARALAFM, 
    paraliptis.Epagelma AS PARALEPAGELMA, 
    paraliptis.AddressStr AS PARALADDRSTR,
    grammesvohsum.baros as SUMBAROS,
    paraliptis.AddressNo AS PARALADDRNO, 
    paraliptis.AddressTK AS PARALADDRTK, 
    paraliptis.AddressCity AS PARALCITY,
    EMPLOYEE.AFM AS AFMEMPLOYEE, --EMPLAFM, 
    EMPLOYEE.DOY AS EMPLDOY, 
    EMPLOYEE.Epagelma AS EMPLLEPAGELMA, 
    EMPLOYEE.AddressStr AS EMPLADDRSTR,
    EMPLOYEE.AddressNo AS EMPLADDRNO, 
    EMPLOYEE.AddressTK AS EMPLADDRTK, 
    EMPLOYEE.AddressCity AS EMPLLCITY,
    kpr.IF_TRANSFORM
	

from voh
left join SYNARMOLOGISI_DIANOMI sd on sd.vohsynarmid = voh.id
join ACCOUNTS paraliptis on paraliptis.id = voh.IDPARALIPTI
join ACCOUNTS apostoleas on apostoleas.id = voh.IDAPOSTOLEA
JOIN ACCOUNTS CUSTOMERS ON CUSTOMERS.ID=VOH.IDCUSTOMER
LEFT JOIN EMPLOYEE ON EMPLOYEE.id=VOH.IDEMPLOYEE
join (
	select idvoh, min(id) idparad from paradoseis group by idvoh
) m on m.idvoh = voh.id
join PARADOSEIS on PARADOSEIS.id = m.idparad
left join HEADERVOHPRICING on HEADERVOHPRICING.IDVOH = voh.ID
left join (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		SUM(TEMAXIA) countid,
		sum(BAROS) baros,
		sum(KYBIKA) kybika
	from grammesvoh group by idvoh
) grammesvohsum on grammesvohsum.IDVOH = voh.id
join companies on companies.id = voh.IDYPOKATASTIMA
left JOIN (SELECT
		IDVOH,
		SUM(SUMPOSO) AS AXIA,
		MIN(TIMDA) AS TIMDA,
		MIN(PERIEXOMENO) AS PERIEXOMENO
	  FROM GRAMMESVOH
	  GROUP BY IDVOH
	  )GRAMMESVOH ON GRAMMESVOH.IDVOH=VOH.ID 
left join KentraKostous on KentraKostous.id = voh.IDKENTROUKOSTOUS
left join FORTOTIKES on FORTOTIKES.id = sd.fortid
left join voh sugkentrotiko on sugkentrotiko.id = voh.IDSYGTIMOL
left join KAA on KAA.ID = sd.idkaa
join KINDPARASTATIKON kpr on kpr.id=voh.IDPARAST and kpr.IF_EDSYNARMOL=1
left join LISTESDIANOMIS on LISTESDIANOMIS.id = sd.idlistas
LEFT JOIN(
		SELECT 
		IDVOH,
		SUM(KOMISTRA) AS KOMISTRA,
		SUM(XREOSISTRITON) AS XREOSISTRITON,
		SUM(DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORT,
		SUM(OTHERXREOSIS) AS OTHERXREOSIS,
		SUM(ASFALISTRA) AS ASFALISTRA,
		SUM(TAXIS) AS TAXISXREOSEON,
		SUM(SUMPOSOXRVOH) AS SUMPOSOXRVOH,
		SUM(KATHARO) AS KATHARO
		FROM HEADERVOH
		GROUP BY IDVOH
		)HEADERVOH ON HEADERVOH.IDVOH=VOH.ID

left join 
	(select			
		idvoh,
		max(idlistas) as idlistas
	from VOH_ANA_LISTAASS
	group by IDVOH) voh_ana_listaass_max on voh_ana_listaass_max.IDVOH=voh.ID
left join LISTESSYNARMOLOGISIS on LISTESSYNARMOLOGISIS.id=voh_ana_listaass_max.idlistas
LEFT JOIN (
	select max(id) maxid, idorder from voh where voh.ifDelete = 0 group by idorder
) xartis_thisavrou on xartis_thisavrou.IDORDER = voh.id
LEFT join voh timol on timol.id = xartis_thisavrou.maxid
LEFT JOIN KINDPARASTATIKON kptimol on kptimol.id = timol.IDPARAST and ISNULL(kptimol.IF_SYGSYN, 0) = 0 



GO




