				@IF_LISTAANTIKATABOLON,
				@IF_FROM_ANTAP,
				--@IFCASH,
				--@IFPISTOSI,
				--@IFOFEILOMENI,
				--@IFPREPAY,
				@CATKEPYO,
				@CodeLog,
				@Copies,			
				@IF_EDMETAFORAS,
				@IF_EDSYNARMOL,
				@IS_CANCELLATION,
				--@IF_ENDILMETAFORAS,
				--@IF_EDTOPOTH,
				@VoucherTypeCode,
				@IDCURRENCY
				)
		END

		SET @IDPARAST= (SELECT MAX(ID) FROM KINDPARASTATIKON WITH (NOLOCK))

		BEGIN
			INSERT INTO PARASTATIKA_ANA_KATHGORIA
				(
				ID_CAT_PARASTATIKON,
				ID_KINDPARASTATIKON
				)
			VALUES
				(
				@IDCATPARAST,
				@IDPARAST
				)
		END

	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************

ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint 


GO

