create VIEW [dbo].[VOH_VIEW]
AS

WITH GRAMMES AS 
	(
		SELECT 
			IDVOH,
			ISNULL(Min(dbo.grammesvoh.timda),'')                 AS TIMDA,
            Isnull(Sum(dbo.grammesvoh.temaxia), 0)               AS TEMAXIA,
            Isnull(Sum(dbo.grammesvoh.baros), 0)                 AS BAROS,
            Isnull(Sum(dbo.grammesvoh.kybika), 0)                AS KYBIKA,
            ISNULL(MIN(PERIEXOMENO),'')							 AS PERIEXOMENO,
            ISNULL(SUM(SUMPOSO),0)								 AS AXIA
		
		FROM GRAMMESVOH
		GROUP BY IDVOH
	),
XREOSIS AS	(
		SELECT 
			IDVOH,
			SUM(SUMPOSO) AS SUPOSO
			
		FROM XREOSISANADELTIO
		WHERE IF_TO_VOH=1
			
		GROUP BY IDVOH
		)

SELECT

	V.ID,
	V.DATEPRINT,
	KP.Code,
	V.PARASTATIKO,
	V.SEIRA,
	CAST(V.NOPARAST AS NVARCHAR(15)) [NOPARAST],
	V.CustDescr,
	V.EPAGELMA,
	V.AFM,
	V.CITY,
	V.TEL,
	V.MOBILE,
	V.POSO,
	V.TAXIS,
	V.SUMPOSO,
	V.KINDPAYMENTDESCR,
	V.EXT_BARCODE,
	V.OXIMA,
	V.OMADPROORISMOS,
	V.SXETIKAPARASTATIKA,
	CASE ifxrentol * 1 + ifxrapost * 2 + ifxrtritou * 4 + ifxrparal * 8
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		ELSE 'ΑΓΝΩΣΤΟ'
	END AS XREOYMENOS,
	  V.noparastdeltioudianomis,
      V.noparastdeltiouapostolis,
      GRAMMES.TIMDA,
      GRAMMES.TEMAXIA,
      GRAMMES.BAROS,
      GRAMMES.KYBIKA,
      CASE V.IFPREPAY
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIPROPLIROMENES,
	  CASE V.IFOFEILOMENI
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIOFEILOMENES,
	  GRAMMES.PERIEXOMENO,
	  V.perioxifortosis,
      V.perioxiparadosis,
      V.comments,
      V.sumantik,
      V.praktoreiodescr,
      V.status,
      V.dateparad,
      V.idpraktoreio,
      CASE ifantikcash
        WHEN 0 THEN 0
        ELSE antikcash
      END AS ANTIKCASH,
      CASE ifantikepit
        WHEN 0 THEN 0
        ELSE antikepit
      END AS ANTIKEPIT,
      CASE ifantiksynal
        WHEN 0 THEN 0
        ELSE antiksynal
      END AS ANTIKSYNAL,
      CASE ifantikother
        WHEN 0 THEN 0
        ELSE antikother
      END AS ANTIKOTHER,
      CASE ifcancelantik
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFCANCELANTIK,
      V.commentsantik,
      V.dateparadosi,
      V.comments2,
      hv.KOMISTRA,
      hv.XREOSISTRITON,
      hv.DIKAIOMAFORTOTIKIS,
      hv.OTHERXREOSIS,
      CASE V.ifprepay
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFPREPAY,
      CASE V.ifofeilomeni
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFOFEILOMENI,
      GRAMMES.AXIA,
      CASE ifxrentol
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRENTOL,
      V.idkindpayment,
      CASE ifxrapost
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRAPOST,
      CASE ifxrparal
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRPARAL,
      CASE ifxrtritou
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRTRITOU,
      V.ifantikcash,
      V.ifantikepit,
      V.ifantiksynal,
      V.ifantikother,
      V.ifdelete,
      V.ifcancel,
      V.datecancel,
      V.ifparadosi,
      V.aitiologiaparastatikou,
      V.datefortosis,
      V.ifepistrofi,
      V.dateepistrofis,
      V.aitiologiaepistrofis,
      V.commentsepistrofis,
      V.ifcash,
      V.ifpistosi,
      V.statusdescr,
      V.ypaitios,
      V.ifepanadromologisi,
      V.ifepanekdosi,
      V.ifokepanadromologisi,
      V.noparastantik,
      V.commentsakirosis,
      V.ifeisprantik,
      V.ifparadosiantik,
      V.ifparalaviantik,
      V.commentsparadantik,
      V.commantsparalantik,
      V.commentseisprantik,
      V.dateparadantik,
      V.dateparalantik,
      V.dateeisprantik,
      V.eispraxasantik,
      V.noparparadantik,
      V.noparasteisprantik,
      V.noparparalantik,
      V.dateparal,
      V.commentsparad,
      V.commantsparal,
      V.ifexoflisi,
      V.timeparalfrom,
      V.timeparalto,
      V.timeparadfrom,
      V.timeparadto,
      V.datecancelantik,
      V.idparast,
      V.taxispercent,
      V.anamexodo,
      V.id                                           AS IDVOH,
      V.afmxreoumenou,
      hv.ASFALISTRA,
      hv.TAXIS										 AS TAXISXREOSEON,
      hv.SUMPOSOXRVOH,
      hv.KATHARO,
      V.thetime,
      V.identolea                                    AS CUSTOMERID,
      V.entoleasdescr                                AS CUSTOMERDESCR,
      V.idapostolea                                  AS IDSYNAL,
      V.apostoleasdescr                              AS SYNALDESCR,
      V.idcustomer,
      V.doy,
      V.addressstreet,
      V.addressno,
      V.pref,
      V.afmapostolea,
      APOST.epagelma                                 AS SYNALEPAGELMA,
      APOST.addressstr                               AS SYNALADDRSTR,
      APOST.addressno                                AS SYNALADDRNO,
      APOST.addresstk                                AS SYNALADDRTK,
      APOST.addresscity                              AS SYNALCITY,
      APOST.addresscountry                           AS SYNALADDRCOUNTRY,
      APOST.tel                                      AS SYNALTEL,
      APOST.doy										 AS SYNALDOY,
      APOST.afm                                      AS SYNALAFM,
      APOST.mobile				                     AS SYNALMOBILE,
      APOST.code                                     AS CodeCust,
      APOST.addresstk			                     AS CUSTADDRTK,
      APOST.addressno                                AS CUSTADDRNO,
      APOST.addressstr                               AS CUSTADDRSTR,
      APOST.addresscity                              AS CUSTADDRCITY,
      APOST.afm                                      AS CUSTAFM,
      APOST.doy                                      AS CUSTDOY,
      V.idxrhshs,
      V.idcompany,
      V.idypokatastima,
      V.usermod,
      V.datemod,
      V.usercreate,
      V.datecreate,
      V.discountpercent,
      V.discount,
      V.arxikoposo,
      V.skoposdiakinisis,
      V.idskoposdiakinisis,
      V.afmentolea,
      V.afmparalipti,
      V.afmtritou,
      V.afmantapokriti,
      V.country,
      V.driver,
      V.idlistas,
      V.ifisorder,
      V.idorder,
      V.codeentolea,
      V.codeapostolea,
      V.codeparalipti,
      V.seiraorder,
      V.dateprintorder,
      V.orderdetails,
      V.if_close,
      V.noorder,
      V.no_ext_order,
      V.no_ext_order_ik,
      YPOK.eponimia                                  AS YPOKATASTHMA,
      YPOK.addressstr                                AS ADDRESS_YPOKATASTHMA,
      YPOK.addresstk                                 AS TK_YPOKATASTHMA,
      YPOK.addresscity                               AS CITY_YPOKATASTHMA,
      YPOK.barcode_prefix                            AS BARCODEPREFIX_YPOKAT,
      YPOK.email                                     AS EMAIL_YPOKATASTHMA,
	  kp.PRINTLABEL,	
      dbo.Getvoheafdss(V.id, 1)                      AS EAFDSS

FROM VOH V
LEFT JOIN KINDPARASTATIKON KP ON KP.ID=V.IDPARAST
LEFT JOIN GRAMMES ON GRAMMES.IDVOH=V.ID
LEFT JOIN XREOSIS ON XREOSIS.IDVOH=V.ID
LEFT JOIN HEADERVOH hv on hv.IDVOH=V.ID
LEFT JOIN ACCOUNTS APOST ON APOST.ID=V.IDAPOSTOLEA
LEFT JOIN COMPANIES YPOK ON YPOK.id=V.IDYPOKATASTIMA

GO


