ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS
SELECT     dbo.FORTOTIKES.ID, dbo.FORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.FORTOTIKES.PARASTATIKO, dbo.FORTOTIKES.SEIRA, 
                      CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, 
                      dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.FORTOTIKES.OXIMA, dbo.FORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
                       ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      FORTOTIKES.APOSTOLEASDESCR, FORTOTIKES.PARALISPTISDESCR, FORTOTIKES.ENTOLEASDESCR, 
                      dbo.FORTOTIKES.ANTAPOKRITISDESCR, dbo.FORTOTIKES.NOLISTASDIANOMIS, ACCOUNTS_3.Eponimia AS TRITOSDESCR, MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA, dbo.FORTOTIKES.POSO, 
                      dbo.FORTOTIKES.TAXIS, dbo.FORTOTIKES.SUMPOSO, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, 
                      ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS), 0) AS BAROS, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA), 0) AS KYBIKA, 
                      MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANADELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.FORTOTIKES.ID AND IF_TO_FORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO, dbo.FORTOTIKES.PERIOXIFORTOSIS, dbo.FORTOTIKES.PERIOXIPARADOSIS, 
                      dbo.FORTOTIKES.COMMENTS, dbo.FORTOTIKES.SUMANTIK, dbo.FORTOTIKES.PRAKTOREIODESCR, dbo.FORTOTIKES.STATUS, 
                      --CONVERT(varchar, dbo.FORTOTIKES.DATEPARAD, 102) AS 
                      DATEPARAD, dbo.FORTOTIKES.IDAPOSTOLEA, dbo.FORTOTIKES.IDPARALIPTI, dbo.FORTOTIKES.IDENTOLEA, 
                      dbo.FORTOTIKES.IDANTAPOKRITI, dbo.FORTOTIKES.IDTRITOU, dbo.FORTOTIKES.IDPRAKTOREIO, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
                      CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, dbo.FORTOTIKES.COMMENTSANTIK, 
                      dbo.FORTOTIKES.DATEPARADOSI, dbo.FORTOTIKES.COMMENTS2, MIN(dbo.HEADERFORTOTIKIS.KOMISTRA) AS KOMISTRA, 
                      dbo.FORTOTIKES.EXODATRITON AS XREOSISTRITON, MIN(dbo.HEADERFORTOTIKIS.DIKAIOMAFORTOTIKIS) 
                      AS DIKAIOMAFORTOTIKIS, MIN(dbo.HEADERFORTOTIKIS.OTHERXREOSIS) AS OTHERXREOSIS, 
                      MIN(dbo.HEADERFORTOTIKIS.OLIKOSYNOLOXREOSEONFORT) AS OLIKOSYNOLOXREOSEONFORT, 
                      MIN(dbo.HEADERFORTOTIKIS.ERGATIKA) AS ERGATIKA, 
                      CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
                      CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, ISNULL(SUM(dbo.GRAMMESFORTTIKIS.SUMPOSO), 0) 
                      AS AXIA, CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.FORTOTIKES.KINDPAYMENTDESCR, 
                      dbo.FORTOTIKES.IDKINDPAYMENT, CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
                      CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, 
                      dbo.FORTOTIKES.IFANTIKCASH, dbo.FORTOTIKES.IFANTIKEPIT, dbo.FORTOTIKES.IFANTIKSYNAL, dbo.FORTOTIKES.IFANTIKOTHER, 
                      dbo.FORTOTIKES.ifDelete, dbo.FORTOTIKES.IFCANCEL, --CONVERT(varchar, dbo.FORTOTIKES.DATECANCEL, 102) AS 
                      DATECANCEL, FORTOTIKES.AA_ANTIK, FORTOTIKES.NOLISTASANTIK ,
                      dbo.FORTOTIKES.IFPARADOSI, dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, CONVERT(varchar, dbo.FORTOTIKES.DATEFORTOSIS, 103) 
                      AS DATEFORTOSIS, dbo.FORTOTIKES.IFEPISTROFI, --CONVERT(varchar, dbo.FORTOTIKES.DATEEPISTROFIS, 102) AS 
                      DATEEPISTROFIS,  FORTOTIKES.DROMOLOGIO, FORTOTIKES.THESI,
                      dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.FORTOTIKES.COMMENTSEPISTROFIS, dbo.FORTOTIKES.IFCASH, dbo.FORTOTIKES.IFPISTOSI, 
                      dbo.FORTOTIKES.STATUSDESCR, dbo.FORTOTIKES.YPAITIOS, dbo.FORTOTIKES.IFEPANADROMOLOGISI, dbo.FORTOTIKES.IFEPANEKDOSI, 
                      dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, dbo.FORTOTIKES.NOPARASTANTIK, dbo.FORTOTIKES.COMMENTSAKIROSIS, 
                      dbo.FORTOTIKES.IFEISPRANTIK, dbo.FORTOTIKES.IFPARADOSIANTIK, dbo.FORTOTIKES.IFPARALAVIANTIK, 
                      dbo.FORTOTIKES.COMMENTSPARADANTIK, dbo.FORTOTIKES.COMMANTSPARALANTIK, dbo.FORTOTIKES.COMMENTSEISPRANTIK, CONVERT(varchar, 
                      dbo.FORTOTIKES.DATEPARADANTIK, 102) AS DATEPARADANTIK, --CONVERT(varchar, dbo.FORTOTIKES.DATEPARALANTIK, 102) AS 
                      DATEPARALANTIK, 
                      CONVERT(varchar, dbo.FORTOTIKES.DATEEISPRANTIK, 102) AS DATEEISPRANTIK, dbo.FORTOTIKES.EISPRAXASANTIK, 
                      dbo.FORTOTIKES.NOPARPARADANTIK, dbo.FORTOTIKES.NOPARASTEISPRANTIK, dbo.FORTOTIKES.NOPARPARALANTIK, 
                      --CONVERT(varchar, dbo.FORTOTIKES.DATEPARAL, 102) AS 
                      DATEPARAL, dbo.FORTOTIKES.COMMENTSPARAD, dbo.FORTOTIKES.COMMANTSPARAL,  FORTOTIKES.IF_TRANSFTOESEX, 
                      dbo.FORTOTIKES.TIMEPARALFROM, dbo.FORTOTIKES.TIMEPARALTO, dbo.FORTOTIKES.TIMEPARADFROM, dbo.FORTOTIKES.TIMEPARADTO, 
                      CONVERT(varchar, dbo.FORTOTIKES.DATECANCELANTIK, 102) AS DATECANCELANTIK, dbo.FORTOTIKES.IDPARAST, dbo.FORTOTIKES.TAXISPERCENT, 
                      dbo.FORTOTIKES.ANAMEXODO, dbo.FORTOTIKES.ID AS IDFORTOTIKIS, dbo.FORTOTIKES.AFMXREOUMENOU, 
                      dbo.HEADERFORTOTIKIS.ASFALISTRA, ROUND(dbo.HEADERFORTOTIKIS.TAXIS, 2) AS TAXISXREOSEON, 
