                      dbo.ACCOUNTS.Epagelma AS EPAGAPOST, dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, 
                      dbo.ACCOUNTS.AddressTK AS TKAPOST, dbo.ACCOUNTS.AddressCity AS CITYAPOST, dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, 
