create FUNCTION [dbo].[GET_XREOSEISFORTOTIKIS] (
	@IDFORT INT
) RETURNS @OUTPUT TABLE (
	ID INT,
	POSO NUMERIC(18,2),
	TAXIS NUMERIC(18,2),
	SUMPOSO NUMERIC(18,2)
)
AS
BEGIN
DECLARE CUR CURSOR FOR
WITH T AS (
	SELECT 
		SUM(KOMISTRA) KOMISTRA,
		SUM(ERGATIKA) ERGATIKA,
		SUM(ASFALISTRA) ASFALISTRA,
		IF_KOMISTRO,
		IF_MIKTO,
		IF_KATHARO
	FROM dbo.GET_XREOSEISGRAMMONFORTOTIKIS(@IDFORT)
	GROUP BY GROUPING SETS (
		(IF_KOMISTRO, IF_KATHARO, IF_MIKTO)
	)
)
SELECT
	KOMISTRA,
	ERGATIKA,
	ASFALISTRA,
	IF_KOMISTRO * 1 + IF_MIKTO * 2 + IF_KATHARO * 4
FROM T;


DECLARE 
	@IDPARAST INT,
	@CUR_KOMISTRA REAL,
	@CUR_ERGATIKA REAL,
	@CUR_ASFALISTRA REAL,
	@CUR_FLAG INT,
	@KOMISTRA_KATHARA REAL,
	@ERGATIKA_KATHARA REAL,
	@ASFALISTRA_KATHARA REAL,
	@KOMISTRA_TOTAL_KATHARA REAL = 0,
	@ERGATIKA_TOTAL_KATHARA REAL = 0,
	@ASFALISTRA_TOTAL_KATHARA REAL = 0,
	@FLAG_POUTSES_MPLE INT = 0,
	@MULTIPLIER REAL;

SELECT @IDPARAST = IDPARAST FROM FORTOTIKES WHERE ID = @IDFORT;

OPEN CUR;

FETCH NEXT FROM CUR INTO @CUR_KOMISTRA, @CUR_ERGATIKA, @CUR_ASFALISTRA, @CUR_FLAG;

WHILE @@FETCH_STATUS = 0 
BEGIN

	IF @CUR_FLAG = 2  
		SET @MULTIPLIER = 1/1.24;
	ELSE
		SET @MULTIPLIER = 1;

	IF @CUR_FLAG <> 1
		SET @FLAG_POUTSES_MPLE = @FLAG_POUTSES_MPLE + 1;
	
	--select @cur_flag cflag, @MULTIPLIER cmultiplier, @CUR_KOMISTRA ckomistra, @cur_ergatika cergatika, @CUR_ASFALISTRA casfalistra
	
	SET @KOMISTRA_KATHARA = @CUR_KOMISTRA * @MULTIPLIER;
	SET @ERGATIKA_KATHARA = @CUR_ERGATIKA * @MULTIPLIER;
	SET @ASFALISTRA_KATHARA = @CUR_ASFALISTRA * @MULTIPLIER;

	SET @KOMISTRA_TOTAL_KATHARA = @KOMISTRA_TOTAL_KATHARA + @KOMISTRA_KATHARA;
	SET @ERGATIKA_TOTAL_KATHARA = @ERGATIKA_TOTAL_KATHARA + @ERGATIKA_KATHARA;
	SET @ASFALISTRA_TOTAL_KATHARA = @ASFALISTRA_TOTAL_KATHARA + @ASFALISTRA_KATHARA;

	FETCH NEXT FROM CUR INTO @CUR_KOMISTRA, @CUR_ERGATIKA, @CUR_ASFALISTRA, @CUR_FLAG;
END

CLOSE CUR;
DEALLOCATE CUR;


IF @FLAG_POUTSES_MPLE > 0 
	SET @KOMISTRA_TOTAL_KATHARA = 
		@KOMISTRA_TOTAL_KATHARA - (
			SELECT SUM(XAP.POSO) 
			FROM XREOSISANAPARASTATIKO XAP 
			JOIN XREOSEIS XR ON XR.ID = XAP.IDXREOSIS
			WHERE XR.ifDikaiomaFortotikis = 1
			AND XAP.IDKINDPARASTTIKON = @IDPARAST
		)

--SELECT
--	@KOMISTRA_TOTAL_KATHARA KOMISTRA_total_kathara,
--	@ERGATIKA_TOTAL_KATHARA ERGATIKA_total_kathara,
--	@ASFALISTRA_TOTAL_KATHARA ASFALISTRA_total_kathara


INSERT INTO @OUTPUT(ID, POSO)
SELECT
	XR.ID,
	CASE XAP.ifChange
		when 0 then XAP.POSO
		else
			case xr.ifKomistra * 1 + xr.IfAsfalistra * 2 + xr.ifErgatika * 4 + 8 * xr.ifOther + 16 * XR.ifDikaiomaFortotikis
			when 1 then @KOMISTRA_TOTAL_KATHARA
			when 2 then @ASFALISTRA_TOTAL_KATHARA
			when 4 then @ERGATIKA_TOTAL_KATHARA
			when 8 then XAP.POSO
			when 16 then XAP.POSO
			else 999999
		end 
	END POSO
FROM XREOSISANAPARASTATIKO XAP 
JOIN Xreoseis XR ON XR.ID = XAP.IDXREOSIS
WHERE XAP.IDKINDPARASTTIKON = @IDPARAST

UPDATE OUTP 
	SET TAXIS = POSO * Xreoseis.TAXISPERCENT * 0.01,
		SUMPOSO = POSO + POSO * Xreoseis.TAXISPERCENT * 0.01
FROM @OUTPUT OUTP
JOIN XREOSEIS ON Xreoseis.ID = OUTP.ID


RETURN
END
GO

