CREATE FUNCTION [dbo].[GET_XREOSIGRAMMISFORTOTIKIS] (
	@IDGRAMMIS INT
)
RETURNS @OUTPUT TABLE (
	IDGRAMMIS INT,
	KOMISTRA REAL,
	ERGATIKA REAL,
	ASFALISTRA REAL,
	IF_KOMISTRO BIT,
	IF_KATHARO BIT,
	IF_MIKTO BIT,
	TROPOS_YPOLOGISMOU NVARCHAR(20),
	XREOSI_MONADAS NUMERIC(18,2)
)
AS
BEGIN
	DECLARE @TMP TABLE (
		ID INT,
		IDACCOUNT INT,
		IDOMPROOR INT,
		IDETAIRIAS INT,
		POSOXREOSIS REAL,
		MINXREOSI REAL,
		MAXXREOSI REAL,
		MINBAL REAL,
		MAXBAL REAL,
		IF_KLIMAKA BIT,
		IF_TEMAXIA BIT,
		IF_OGOS BIT,
		IF_VAROS BIT,
		XREOSITYPE INT,
		IF_KOMISTRO BIT,
		IF_KATHARO BIT,
		IF_MIKTO BIT,
		ASFALISTRA REAL,
		ERGATIKA REAL,
		IDUNIT INT,
		TROPOS_YPOLOGISMOU NVARCHAR(20) NULL
	)

	DECLARE 
			@IDGRAMMISXREOSISTIMOKATALOGOU INT,
			@IDENTOLEA INT,
			@IDAPOSTOLEA INT,
			@IDOMPROOR INT,
			@IDUNIT INT,
			@IF_KLIMAKA BIT,
			@QTY real,
			@WEIGHT real,
			@VOLUME real;

	
	SELECT TOP 1
		@IDENTOLEA = FORTOTIKES.IDENTOLEA,
		@IDAPOSTOLEA = FORTOTIKES.IDAPOSTOLEA,
		@IDOMPROOR = OMPROOR.ID,
		@IDUNIT = GRAMMESFORTTIKIS.SYSKEVASIA,
		@QTY = GRAMMESFORTTIKIS.TEMAXIA,
		@WEIGHT = GRAMMESFORTTIKIS.BAROS,
		@VOLUME = GRAMMESFORTTIKIS.KYBIKA
	FROM FORTOTIKES 
	JOIN OMADIKOI_PROORISMOI OMPROOR ON OMPROOR.Descr = FORTOTIKES.OMADPROORISMOS
	JOIN GRAMMESFORTTIKIS ON FORTOTIKES.ID = GRAMMESFORTTIKIS.IDVOH
	WHERE GRAMMESFORTTIKIS.ID = @IDGRAMMIS

	select top 1 
		@IDGRAMMISXREOSISTIMOKATALOGOU = ID
	from XreoseisANATIMOKATALOGO XAT
	where IDACCOUNT in(0, @IDENTOLEA)
	and IDETAIRIAS in (0, @IDAPOSTOLEA)
	and IDOMPROOR in (0, @IDOMPROOR)
	and IDUNIT in (0, @IDUNIT)
	and (
		IF_KLIMAKA = 0
		or (
			IF_KLIMAKA = 1 and (
				(IF_VAROS = 1 and @WEIGHT between MINBAL and MAXBAL)
				or (IF_OGOS = 1 and @VOLUME between MINBAL and MAXBAL)
				or (IF_TEMAXIA = 1 and @QTY between MINBAL and MAXBAL)
			)
		)
	)
	order by
		CASE WHEN IDUNIT > 0 THEN 1 ELSE 0 END * 1 +
		CASE WHEN IDETAIRIAS > 0 THEN 1 ELSE 0 END * 2 +
		CASE WHEN IDOMPROOR > 0 THEN 1 ELSE 0 END * 4 +
		CASE WHEN IDACCOUNT > 0 THEN 1 ELSE 0 END * 8
	DESC

	INSERT INTO @TMP (
		ID,
		IDACCOUNT,
		IDOMPROOR,
		IDETAIRIAS,
		POSOXREOSIS,
		MINXREOSI,
		MAXXREOSI,
		MINBAL,
		MAXBAL,
		IF_KLIMAKA,
		IF_TEMAXIA,
		IF_OGOS,
		IF_VAROS,
		XREOSITYPE,
		IF_KOMISTRO,
		IF_KATHARO,
		IF_MIKTO,
		ASFALISTRA,
		ERGATIKA,
		IDUNIT
	)
	select
		ID,
		IDACCOUNT,
		IDOMPROOR,
		IDETAIRIAS,
		POSOXREOSIS,
		MINXREOSI,
		MAXXREOSI,
		MINBAL,
		MAXBAL,
		IF_KLIMAKA,
		IF_TEMAXIA,
		IF_OGOS,
		IF_VAROS,
		XREOSITYPE,
		IF_KOMISTRO,
		IF_KATHARO,
		IF_MIKTO,
		ASFALISTRA,
		ERGATIKA,
		IDUNIT
	from XreoseisANATIMOKATALOGO XAT WHERE XAT.ID = @IDGRAMMISXREOSISTIMOKATALOGOU

	DECLARE @KOMISTRA real,
			@ERGATIKA real,
			@ASFALISTRA real,
			@MULTIPLIER real;

		
	SELECT @MULTIPLIER = 
		CASE ISNULL(IF_TEMAXIA,0) * 1 + ISNULL(IF_OGOS,0) * 2 + ISNULL(IF_VAROS,0) * 4
		WHEN 1 THEN @QTY
		WHEN 2 THEN @VOLUME
		WHEN 4 THEN @WEIGHT
		ELSE 0.00
		END
	FROM @TMP

	UPDATE @TMP SET TROPOS_YPOLOGISMOU =
		CASE @MULTIPLIER
			WHEN 1 THEN 'ΣΥΣΚΕΥΑΣΙΑ'
			WHEN 2 THEN 'ΟΓΚΟΣ'
			WHEN 4 THEN 'ΒΑΡΟΣ'
			ELSE ''
		END

	SELECT DISTINCT TOP 1 @IF_KLIMAKA = IF_KLIMAKA FROM @TMP

	IF @IF_KLIMAKA = 1 DELETE FROM @TMP WHERE @MULTIPLIER NOT BETWEEN MINBAL AND MAXBAL

	--FAIL FUCKING SAFE


	SELECT @KOMISTRA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * PosoXreosis
			WHEN 1 THEN PosoXreosis
		END
	FROM @TMP

	-- Elaxisth?
	SELECT @KOMISTRA =
		CASE 
			WHEN MinXreosi > @KOMISTRA THEN MinXreosi
			ELSE @KOMISTRA
		END
	FROM @TMP

	-- Megisth?
	SELECT @KOMISTRA =	
		CASE 
			WHEN MaxXreosi > 0 THEN
				CASE 
					WHEN @KOMISTRA > MaxXreosi THEN MaxXreosi
					ELSE @KOMISTRA
				END
			ELSE @KOMISTRA
		END
	FROM @TMP

	SELECT @ERGATIKA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * ISNULL(ERGATIKA, 0)
			WHEN 1 THEN Ergatika
		END
	FROM @TMP

	SELECT @ASFALISTRA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * ISNULL(ASFALISTRA, 0)
			WHEN 1 THEN ASFALISTRA
		END
	FROM @TMP

	INSERT INTO @OUTPUT 
	SELECT 
		@IDGRAMMIS,
		@KOMISTRA [KOMISTRA GRAMMIS], 
		@ERGATIKA [ERGATIKA GRAMMIS],
		@ASFALISTRA [ASFALISTRA GRAMMIS],
		IF_KOMISTRO, IF_KATHARO, IF_MIKTO, TROPOS_YPOLOGISMOU, POSOXREOSIS FROM @TMP;

	RETURN
END
GO

