	JOIN OMADIKOI_PROORISMOI OMPROOR ON OMPROOR.Descr = PROFORTOTIKES.OMADPROORISMOS
	JOIN GRAMMESPROFORTTIKIS ON PROFORTOTIKES.ID = GRAMMESPROFORTTIKIS.IDVOH
	WHERE GRAMMESPROFORTTIKIS.ID = @IDGRAMMIS

	select top 1 
		@IDGRAMMISXREOSISTIMOKATALOGOU = ID
	from XreoseisANATIMOKATALOGO XAT
	where IDACCOUNT in(0, @IDENTOLEA)
	and IDETAIRIAS in (0, @IDAPOSTOLEA)
	and IDOMPROOR in (0, @IDOMPROOR)
	and IDUNIT in (0, @IDUNIT)
	and (
		IF_KLIMAKA = 0
		or (
			IF_KLIMAKA = 1 and (
				(IF_VAROS = 1 and @WEIGHT between MINBAL and MAXBAL)
				or (IF_OGOS = 1 and @VOLUME between MINBAL and MAXBAL)
				or (IF_TEMAXIA = 1 and @QTY between MINBAL and MAXBAL)
			)
		)
	)
	order by
		CASE WHEN IDUNIT > 0 THEN 1 ELSE 0 END * 1 +
		CASE WHEN IDETAIRIAS > 0 THEN 1 ELSE 0 END * 2 +
		CASE WHEN IDOMPROOR > 0 THEN 1 ELSE 0 END * 4 +
		CASE WHEN IDACCOUNT > 0 THEN 1 ELSE 0 END * 8
	DESC

	INSERT INTO @TMP (
		ID,
		IDACCOUNT,
		IDOMPROOR,
		IDETAIRIAS,
		POSOXREOSIS,
		MINXREOSI,
		MAXXREOSI,
		MINBAL,
		MAXBAL,
		IF_KLIMAKA,
		IF_TEMAXIA,
		IF_OGOS,
		IF_VAROS,
		XREOSITYPE,
		IF_KOMISTRO,
		IF_KATHARO,
		IF_MIKTO,
		ASFALISTRA,
		ERGATIKA,
		IDUNIT
	)
	select
		ID,
		IDACCOUNT,
		IDOMPROOR,
		IDETAIRIAS,
		POSOXREOSIS,
		MINXREOSI,
		MAXXREOSI,
		MINBAL,
		MAXBAL,
		IF_KLIMAKA,
		IF_TEMAXIA,
		IF_OGOS,
		IF_VAROS,
		XREOSITYPE,
		IF_KOMISTRO,
		IF_KATHARO,
		IF_MIKTO,
		ASFALISTRA,
		ERGATIKA,
		IDUNIT
	from XreoseisANATIMOKATALOGO XAT WHERE XAT.ID = @IDGRAMMISXREOSISTIMOKATALOGOU

	DECLARE @KOMISTRA real,
			@ERGATIKA real,
			@ASFALISTRA real,
			@MULTIPLIER real;

		
	SELECT @MULTIPLIER = 
		CASE ISNULL(IF_TEMAXIA,0) * 1 + ISNULL(IF_OGOS,0) * 2 + ISNULL(IF_VAROS,0) * 4
		WHEN 1 THEN @QTY
		WHEN 2 THEN @VOLUME
		WHEN 4 THEN @WEIGHT
		ELSE 0.00
		END
	FROM @TMP

	UPDATE @TMP SET TROPOS_YPOLOGISMOU =
		CASE @MULTIPLIER
			WHEN 1 THEN 'ΣΥΣΚΕΥΑΣΙΑ'
			WHEN 2 THEN 'ΟΓΚΟΣ'
			WHEN 4 THEN 'ΒΑΡΟΣ'
			ELSE ''
		END

	SELECT DISTINCT TOP 1 @IF_KLIMAKA = IF_KLIMAKA FROM @TMP

	IF @IF_KLIMAKA = 1 DELETE FROM @TMP WHERE @MULTIPLIER NOT BETWEEN MINBAL AND MAXBAL

	--FAIL FUCKING SAFE


	SELECT @KOMISTRA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * PosoXreosis
			WHEN 1 THEN PosoXreosis
		END
	FROM @TMP

	-- Elaxisth?
	SELECT @KOMISTRA =
		CASE 
			WHEN MinXreosi > @KOMISTRA THEN MinXreosi
			ELSE @KOMISTRA
		END
	FROM @TMP

	-- Megisth?
	SELECT @KOMISTRA =	
		CASE 
			WHEN MaxXreosi > 0 THEN
				CASE 
					WHEN @KOMISTRA > MaxXreosi THEN MaxXreosi
					ELSE @KOMISTRA
				END
			ELSE @KOMISTRA
		END
	FROM @TMP

	SELECT @ERGATIKA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * ISNULL(ERGATIKA, 0)
			WHEN 1 THEN Ergatika
		END
	FROM @TMP

	SELECT @ASFALISTRA = 
		CASE ISNULL(XreosiTYPE, 0)
			WHEN 0 THEN @MULTIPLIER * ISNULL(ASFALISTRA, 0)
			WHEN 1 THEN ASFALISTRA
		END
	FROM @TMP

	INSERT INTO @OUTPUT 
	SELECT 
		@IDGRAMMIS,
		@KOMISTRA [KOMISTRA GRAMMIS], 
		@ERGATIKA [ERGATIKA GRAMMIS],
		@ASFALISTRA [ASFALISTRA GRAMMIS],
		IF_KOMISTRO, IF_KATHARO, IF_MIKTO, TROPOS_YPOLOGISMOU, POSOXREOSIS FROM @TMP;

	RETURN
END
GO

/****** Object:  StoredProcedure [dbo].[EPANAYPOLOGISMOS_XREOSEON_FORTOTIKIS]    Script Date: 17/02/2021 5:09:53 μμ ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procedure [dbo].[EPANAYPOLOGISMOS_XREOSEON_FORTOTIKIS] (
	@IDFORT INT
) AS

BEGIN

	SET NOCOUNT ON;

	DELETE FROM XREOSISANADELTIO WHERE IDVOH = @IDFORT AND IF_TO_FORTOTIKI = 1

	INSERT INTO XREOSISANADELTIO(
		IDXREOSIS,
		IDVOH,
		DESCR,
		TYPOS,
		TAXISPERCENT,
		TAXIS,
		POSO,
		SUMPOSO,
		IF_TO_FORTOTIKI,
		CODEXREOSIS,
		IF_TO_VOH
	)
	SELECT
		XR.ID,
		@IDFORT,
		XR.Descr,
		'',
		XR.TAXISPERCENT,
		NEWXREOSEIS.TAXIS,
		NEWXREOSEIS.POSO,
		NEWXREOSEIS.SUMPOSO,
		1,
		XR.CODE,
		0
	FROM dbo.GET_XREOSEISFORTOTIKIS(@IDFORT) NEWXREOSEIS
	JOIN XREOSEIS XR ON XR.ID = NEWXREOSEIS.ID;
	
	WITH SUMXREOSEONFORT AS (
		SELECT
			XR.ifKomistra,
			XR.IfAsfalistra,
			XR.ifErgatika,
			XR.ifOther,
			XR.ifDikaiomaFortotikis,
			SUM(POSO) POSO,
			SUM(TAXIS) TAXIS,
			SUM(SUMPOSO) SUMPOSO
		FROM XREOSISANADELTIO XAD
		JOIN XREOSEIS XR ON XR.ID = XAD.IDXREOSIS
		WHERE IDVOH = @IDFORT AND IF_TO_FORTOTIKI = 1
		GROUP BY GROUPING SETS (
			(XR.ifKomistra, XR.IfAsfalistra, XR.ifErgatika, XR.ifOther, XR.ifDikaiomaFortotikis)
		)
	)
	UPDATE HF
	SET 
		ASFALISTRA = ISNULL(ASFALISTRA.POSO, 0),
		KOMISTRA = ISNULL(KOMISTRA.POSO, 0),
		ERGATIKA = ISNULL(ERGATIKA.POSO, 0),
		DIKAIOMAFORTOTIKIS = ISNULL(DIKAIOMA.POSO, 0),
		KATHARO = ISNULL(ASFALISTRA.POSO, 0) + ISNULL(KOMISTRA.POSO, 0) + ISNULL(ERGATIKA.POSO, 0) + ISNULL(DIKAIOMA.POSO, 0),
		TAXIS = ISNULL(ASFALISTRA.TAXIS, 0) + ISNULL(KOMISTRA.TAXIS, 0) + ISNULL(ERGATIKA.TAXIS, 0) + ISNULL(DIKAIOMA.TAXIS, 0)
	FROM HEADERFORTOTIKIS HF
	LEFT JOIN SUMXREOSEONFORT KOMISTRA ON KOMISTRA.ifKomistra = 1
	LEFT JOIN SUMXREOSEONFORT ASFALISTRA ON ASFALISTRA.IfAsfalistra = 1
	LEFT JOIN SUMXREOSEONFORT ERGATIKA ON ERGATIKA.ifErgatika = 1
	LEFT JOIN SUMXREOSEONFORT DIKAIOMA ON DIKAIOMA.ifDikaiomaFortotikis = 1
	WHERE HF.IDFORT = @IDFORT;

	UPDATE HEADERFORTOTIKIS 
		SET SUMPOSOXRFORT = KATHARO + TAXIS ,
			OLIKOSYNOLOXREOSEONFORT = KATHARO + TAXIS,
			POSOFORT = KATHARO
	WHERE IDFORT = @IDFORT;

	UPDATE FORT
		SET FORT.POSO = HF.KATHARO,
			FORT.TAXIS = HF.TAXIS,
			FORT.SUMPOSO = HF.SUMPOSOXRFORT
	FROM FORTOTIKES FORT
	JOIN HEADERFORTOTIKIS HF ON HF.IDFORT = FORT.ID

	UPDATE GF
		SET XreosiGrammis = XR.KOMISTRA,
			XeosiSeMonada = XR.TROPOS_YPOLOGISMOU,
			XreosiAnaMonada = XR.XREOSI_MONADAS
	FROM GRAMMESFORTTIKIS GF
	JOIN dbo.GET_XREOSEISGRAMMONFORTOTIKIS(@IDFORT) XR ON XR.IDGRAMMIS = GF.ID

END
GO

