CREATE procedure [dbo].[EPANAYPOLOGISMOS_XREOSEON_PROFORTOTIKIS] (
	@IDPROFORT INT
) AS

BEGIN

	SET NOCOUNT ON;

	DELETE FROM XREOSISANAPRODELTIO WHERE IDVOH = @IDPROFORT AND IF_TO_PROFORTOTIKI = 1

	INSERT INTO XREOSISANAPRODELTIO(
		IDXREOSIS,
		IDVOH,
		DESCR,
		TYPOS,
		TAXISPERCENT,
		TAXIS,
		POSO,
		SUMPOSO,
		IF_TO_PROFORTOTIKI,
		CODEXREOSIS,
		IF_TO_PROVOH
	)
	SELECT
		XR.ID,
		@IDPROFORT,
		XR.Descr,
		'',
		XR.TAXISPERCENT,
		NEWXREOSEIS.TAXIS,
		NEWXREOSEIS.POSO,
		NEWXREOSEIS.SUMPOSO,
		1,
		XR.CODE,
		0
	FROM dbo.GET_XREOSEISPROFORTOTIKIS(@IDPROFORT) NEWXREOSEIS
	JOIN XREOSEIS XR ON XR.ID = NEWXREOSEIS.ID;
	
	WITH SUMXREOSEONFORT AS (
		SELECT
			XR.ifKomistra,
			XR.IfAsfalistra,
			XR.ifErgatika,
			XR.ifOther,
			XR.ifDikaiomaFortotikis,
			SUM(POSO) POSO,
			SUM(TAXIS) TAXIS,
			SUM(SUMPOSO) SUMPOSO
		FROM XREOSISANAPRODELTIO XAD
		JOIN XREOSEIS XR ON XR.ID = XAD.IDXREOSIS
		WHERE IDVOH = @IDPROFORT AND IF_TO_PROFORTOTIKI = 1
		GROUP BY GROUPING SETS (
			(XR.ifKomistra, XR.IfAsfalistra, XR.ifErgatika, XR.ifOther, XR.ifDikaiomaFortotikis)
		)
	)
	UPDATE HPF
	SET 
		ASFALISTRA = ISNULL(ASFALISTRA.POSO, 0),
		KOMISTRA = ISNULL(KOMISTRA.POSO, 0),
		ERGATIKA = ISNULL(ERGATIKA.POSO, 0),
		DIKAIOMAFORTOTIKIS = ISNULL(DIKAIOMA.POSO, 0),
		KATHARO = ISNULL(ASFALISTRA.POSO, 0) + ISNULL(KOMISTRA.POSO, 0) + ISNULL(ERGATIKA.POSO, 0) + ISNULL(DIKAIOMA.POSO, 0),
		TAXIS = ISNULL(ASFALISTRA.TAXIS, 0) + ISNULL(KOMISTRA.TAXIS, 0) + ISNULL(ERGATIKA.TAXIS, 0) + ISNULL(DIKAIOMA.TAXIS, 0)
	FROM HEADERPROFORTOTIKIS HPF
	LEFT JOIN SUMXREOSEONFORT KOMISTRA ON KOMISTRA.ifKomistra = 1
	LEFT JOIN SUMXREOSEONFORT ASFALISTRA ON ASFALISTRA.IfAsfalistra = 1
	LEFT JOIN SUMXREOSEONFORT ERGATIKA ON ERGATIKA.ifErgatika = 1
	LEFT JOIN SUMXREOSEONFORT DIKAIOMA ON DIKAIOMA.ifDikaiomaFortotikis = 1
	WHERE HPF.IDPROFORT = @IDPROFORT;

	UPDATE HEADERPROFORTOTIKIS 
		SET SUMPOSOXRPROFORT = KATHARO + TAXIS ,
			OLIKOSYNOLOXREOSEONPROFORT = KATHARO + TAXIS,
			POSOPROFORT = KATHARO
	WHERE IDPROFORT = @IDPROFORT;

	UPDATE PROFORT
		SET PROFORT.POSO = HPF.KATHARO,
			PROFORT.TAXIS = HPF.TAXIS,
			PROFORT.SUMPOSO = HPF.SUMPOSOXRPROFORT
	FROM PROFORTOTIKES PROFORT
	JOIN HEADERPROFORTOTIKIS HPF ON HPF.IDPROFORT = PROFORT.ID

	UPDATE GPF
		SET XreosiGrammis = XR.KOMISTRA,
			XeosiSeMonada = XR.TROPOS_YPOLOGISMOU,
			XreosiAnaMonada = XR.XREOSI_MONADAS
	FROM GRAMMESPROFORTTIKIS GPF
	JOIN dbo.GET_XREOSEISGRAMMONPROFORTOTIKIS(@IDPROFORT) XR ON XR.IDGRAMMIS = GPF.ID

END
GO



