---NEW SCRIPT 1654

ALTER VIEW dbo.FORTOTIKESWEB_VIEW
AS
SELECT
	F1.ID
 ,F1.EXT_BARCODE
 ,'(' + CONVERT(NVARCHAR, ISNULL(F1.STATUS, 6)) + ') ' +
	CASE
		WHEN DS1.DESCR IS NULL THEN ''
		ELSE DS1.DESCR
	END AS [STATUS]
 ,CONVERT(VARCHAR, F1.DATEPRINT, 103) AS DATEPRINT
 ,CONVERT(VARCHAR, CASE
		WHEN F1.IFPARADOSITOPEL = 0 THEN NULL
		ELSE F1.DATEPARAD
	END, 103) AS DATEPARADOSI
 ,F1.STATUS AS RAWSTATUS
 ,F1.NOPARASTDELTIOUAPOSTOLIS
 ,F1.APOSTOLEASDESCR
 ,F1.PARALISPTISDESCR
 ,GF1.TIMDA
 ,CASE ISNULL(F1.POD_AUTO, 0)
		WHEN 0 THEN 'Όχι'
		ELSE 'Ναι'
	END AS PODEXISTS
 ,CASE ISNULL(F1.FILE_PHOTO, '')
		WHEN '' THEN 'Όχι'
		ELSE 'Ναι'
	END AS PHOTOEXISTS
 ,ISNULL(F1.IDPRAKTOREIO, 0) AS IDPRAKTOREIO
 ,F1.PRAKTOREIODESCR +
	CASE
		WHEN LEN(PRK.TEL) > 1 THEN '(' + PRK.TEL + ')'
		ELSE ''
	END PRAKTOREIODESCR
 ,F1.ENTOLEASDESCR
 ,F1.PERIOXIPARADOSIS
 ,F1.PERIOXIFORTOSIS
 ,ISNULL(F1.IDENTOLEA, 0) AS IDENTOLEA
 ,ISNULL(F1.IDANTAPOKRITI, 0) AS IDANTAPOKRITI
 ,F1.ANTAPOKRITISDESCR
 ,CONVERT(DATE, F1.DATEPRINT) AS DATEPRINTRAW
 ,CONVERT(DATE, CASE
		WHEN F1.IFPARADOSITOPEL = 0 THEN NULL
		ELSE F1.DATEPARAD
	END) AS DATEPARADOSIRAW
 ,IDDRIVER
 ,
	--DRIVERDESCR,
	COALESCE(LD.DRIVER, DRIVERDESCR) AS DRIVERDESCR
 , --faaaaak giouuuuu
	O.ID AS IDDRIVER2
 ,O.LastName + ' ' + O.FirstName AS DRIVERDESCR2
 ,FORTSUM.TEMAXIA
 ,PARAL.Tel [TEL]
 ,PARAL.Tel2 [TEL2]
 ,PARAL.Mobile [MOBILE]
 ,F1.NO_EXT_ORDER
 ,F1.UserCreate
FROM FORTOTIKES F1
LEFT JOIN (SELECT
		IDVOH
	 ,SUM(TEMAXIA) [TEMAXIA]
	FROM GRAMMESFORTTIKIS
	GROUP BY IDVOH) FORTSUM
	ON FORTSUM.IDVOH = F1.ID
LEFT JOIN PRAKTOREIA PRK
	ON PRK.ID = F1.IDPRAKTOREIO
LEFT JOIN (SELECT
		GF.IDVOH
	 ,dbo.GROUP_CONCAT(GF.TIMDA) TIMDA
	FROM GRAMMESFORTTIKIS GF
	GROUP BY GF.IDVOH) GF1
	ON F1.ID = GF1.IDVOH
LEFT JOIN DOC_STATUS DS1
	ON DS1.ID = F1.STATUS
LEFT JOIN MAX_FORTOTIKES_ANA_LISTA FL
	ON FL.IDFORTOTIKIS = F1.ID
LEFT JOIN LISTESDIANOMIS LD
	ON LD.ID = FL.IDLISTAS
LEFT JOIN ODIGOI O
	ON (O.LastName + ' ' + O.FirstName) = LD.DRIVER
LEFT JOIN ACCOUNTS PARAL
	ON PARAL.id = F1.IDPARALIPTI
WHERE ISNULL(F1.IFDELETE, 0) = 0
                --and f1.id = 26277
GO



