CREATE PROCEDURE [dbo].[CREATE_BARCODE_TEMAXION_PROFORTOTIKIS] (@IDPROFORT INT)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @BARCODE_PROFORTOTIKIS NVARCHAR(150);

	DECLARE @ID_GRAMMIS INT
				 ,@TEMAXIA_GRAMMIS INT;

	DECLARE @AA_GRAMMIS INT
				 ,@AA_SYNOLIKOS INT
				 ,@I INT;

	SELECT
		@BARCODE_PROFORTOTIKIS = EXT_BARCODE
	FROM PROFORTOTIKES
	WHERE ID = @IDPROFORT;


	DECLARE CUR CURSOR FOR SELECT
		ID
	 ,TEMAXIA
	FROM GRAMMESPROFORTTIKIS
	WHERE IDVOH = @IDPROFORT;

	OPEN CUR;

	FETCH NEXT FROM CUR INTO @ID_GRAMMIS, @TEMAXIA_GRAMMIS;

	SET @AA_SYNOLIKOS = 1;
	WHILE @@FETCH_STATUS = 0
	BEGIN
	SET @AA_GRAMMIS = 1;

	WHILE @AA_GRAMMIS <= @TEMAXIA_GRAMMIS
	BEGIN
	INSERT INTO TEMAXIAPROFORTOTIKIS (IDPROFORTOTIKIS, IDGRAMMIS, AAFORT, AAGRAMMIS, BARCODE)
		SELECT
			@IDPROFORT
		 ,@ID_GRAMMIS
		 ,@AA_SYNOLIKOS
		 ,@AA_GRAMMIS
		 ,@BARCODE_PROFORTOTIKIS + '-' + CONVERT(NVARCHAR, @AA_SYNOLIKOS);

	SET @AA_GRAMMIS = @AA_GRAMMIS + 1;
	SET @AA_SYNOLIKOS = @AA_SYNOLIKOS + 1;
	END

	FETCH NEXT FROM CUR INTO @ID_GRAMMIS, @TEMAXIA_GRAMMIS;
	END

	CLOSE CUR;
	DEALLOCATE CUR;


END
GO



