create PROCEDURE [dbo].[AUDIT_FORTOTIKES_SEQUENCE_NEXT] ( @BATCHID BIGINT OUTPUT)
AS
    --Act like we are INSERTing a row to increment the IDENTITY
	--BEGIN TRANSACTION
	INSERT AUDIT_FORTOTIKES_SEQUENCE DEFAULT VALUES;
    --ROLLBACK TRANSACTION;
    --Return the latest IDENTITY value.
    SELECT @BATCHID = SCOPE_IDENTITY();

