CREATE TRIGGER [dbo].[FORTOTIKES_AUDIT] 
   ON  [dbo].[FORTOTIKES]
   AFTER UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @BATCHID BIGINT;

	--gamo ton sql 2008
	--SET @BATCHID = NEXT VALUE FOR FORTOTIKES_AUDIT_BATCH;
	EXECUTE dbo.AUDIT_FORTOTIKES_SEQUENCE_NEXT @BATCHID OUTPUT;
	
	DECLARE @INSERT_USERCREATE NVARCHAR(30);
	DECLARE @INSERT_USERUPDATE NVARCHAR(30);
	DECLARE @DELETE_USERCREATE NVARCHAR(30);
	DECLARE @DELETE_USERUPDATE NVARCHAR(30);
	DECLARE @USER NVARCHAR(20);

	SET @INSERT_USERCREATE = (SELECT TOP 1 UserCreate FROM INSERTED);
	SET @INSERT_USERUPDATE = (SELECT TOP 1 UserMod FROM INSERTED);
	
	SET @DELETE_USERCREATE = (SELECT TOP 1 UserCreate FROM INSERTED);
	SET @DELETE_USERUPDATE = (SELECT TOP 1 UserMod FROM INSERTED);
	
	SET @USER = COALESCE(@DELETE_USERUPDATE, @INSERT_USERUPDATE, @INSERT_USERCREATE, @DELETE_USERUPDATE);
	
	    WITH deleted_unpvt AS (
        SELECT ID, FieldName, FieldValue
        FROM 
           (SELECT
				ID,
				cast([IDPARAST] AS sql_variant) AS [IDPARAST], 
				cast([PARASTATIKO] AS sql_variant) AS [PARASTATIKO], 
				cast([SEIRA] AS sql_variant) AS [SEIRA], 
				cast([NOPARAST] AS sql_variant) AS [NOPARAST], 
				cast([IFXRAPOST] AS sql_variant) AS [IFXRAPOST], 
				cast([IDAPOSTOLEA] AS sql_variant) AS [IDAPOSTOLEA], 
				cast([APOSTOLEASDESCR] AS sql_variant) AS [APOSTOLEASDESCR], 
				cast([IFXRPARAL] AS sql_variant) AS [IFXRPARAL], 
				cast([IDPARALIPTI] AS sql_variant) AS [IDPARALIPTI], 
