				cast([DROMOLOGIO] AS sql_variant) AS [DROMOLOGIO], 
				cast([THESI] AS sql_variant) AS [THESI], 
				cast([IDYPOKWISPRANTIK] AS sql_variant) AS [IDYPOKWISPRANTIK], 
				cast([IDYPOKPARALANTIK] AS sql_variant) AS [IDYPOKPARALANTIK], 
				cast([IDYPOKPARADANTIK] AS sql_variant) AS [IDYPOKPARADANTIK], 
				cast([IDYPOKEISPRANTIK] AS sql_variant) AS [IDYPOKEISPRANTIK], 
				cast([IFMERIKIEXOFL] AS sql_variant) AS [IFMERIKIEXOFL] 
			FROM inserted) p
        UNPIVOT
           (FieldValue FOR FieldName IN 
              (
				[IDPARAST], [PARASTATIKO], [SEIRA], [NOPARAST], [IFXRAPOST], [IDAPOSTOLEA], [APOSTOLEASDESCR], [IFXRPARAL],
				[IDPARALIPTI], [PARALISPTISDESCR], [IFXRENTOL], [IDENTOLEA], [ENTOLEASDESCR], [IFXRTRITOU], [IDTRITOU], [TRITOSDESCR],
				[IDANTAPOKRITI], [ANTAPOKRITISDESCR], [DATEPRINT], [POSO], [TAXISPERCENT], [TAXIS], [SUMPOSO], [IFANTIKCASH], [ANTIKCASH],
				[IFANTIKEPIT], [ANTIKEPIT], [IFANTIKSYNAL], [ANTIKSYNAL], [IFANTIKOTHER], [ANTIKOTHER], [SUMANTIK], [IFCANCELANTIK],
				[DATECANCELANTIK], 
				--[COMMENTSANTIK],
				[IFPARADOSI], [DATEPARADOSI], [IFCANCEL], [DATECANCEL], [PERIOXIFORTOSIS], [PERIOXIPARADOSIS],
				[OMADPROORISMOS], 
				--[COMMENTS],
				[OXIMA], [IDKINDPAYMENT], [KINDPAYMENTDESCR], [AITIOLOGIAPARASTATIKOU], [DATEFORTOSIS],
				[NOPARASTDELTIOUAPOSTOLIS], [NOPARASTDELTIOUDIANOMIS], [IFEPISTROFI], [DATEEPISTROFIS], [AITIOLOGIAEPISTROFIS], 
				--[COMMENTSEPISTROFIS],
				[IFCASH], [IFPISTOSI], [IFPREPAY], [IFOFEILOMENI], [IDPRAKTOREIO], [PRAKTOREIODESCR], [STATUS], [STATUSDESCR], [YPAITIOS],
				[IFEPANADROMOLOGISI], [IFEPANEKDOSI], [IFOKEPANADROMOLOGISI], [NOPARASTANTIK], 
				--[COMMENTSAKIROSIS],
				[IFEISPRANTIK], [IFPARADOSIANTIK],
				[IFPARALAVIANTIK], 
				--[COMMENTSPARADANTIK], [COMMANTSPARALANTIK], [COMMENTSEISPRANTIK], 
				[DATEPARADANTIK], [DATEPARALANTIK],
				[DATEEISPRANTIK], [EISPRAXASANTIK], [NOPARPARADANTIK], [NOPARASTEISPRANTIK], [NOPARPARALANTIK], [ifDelete], [DATEPARAL],
				[DATEPARAD], 
				--[COMMENTSPARAD], [COMMANTSPARAL], 
				[TIMEPARALFROM], [TIMEPARALTO], [TIMEPARADFROM], [TIMEPARADTO], [ANAMEXODO],
				--[COMMENTS2], 
				[AFMXREOUMENOU],  [AFMAPOSTOLEA], [AFMENTOLEA], [AFMPARALIPTI], [AFMTRITOU], [AFMANTAPOKRITI], [COUNTRY], [IDLISTAS],
				[EXODATRITON], [IFPARADOSITOPEL], [IFPARALABIFROMPEL], [NOLISTASDIANOMIS], [IDXRHSHS], [IDCOMPANY], [IDYPOKATASTIMA], [UserCreate],
				[DateCreate], [UserMod], [DateMod], [AA_ANTIK], [IDDRIVER], [DRIVERDESCR], [IFEXOFLISI], [IDXREOUMENOU], [IDPROFORTOTIKIS],
				[CONTAINER], [BOAT], [IFASFALISTRA], [ASFALISTRAPERCENT], 
				--[POD_PATH],
				[POD_ADDED], [_LASTMODIFIED], [POD_AUTO], 
				--[POD_SCAN_LOCATION], [POD_USER],
				[NOPARASTEMVAST], 
				--[POD_PATH_2], 
				[EXT_ID], [EXT_BARCODE], 
				--[EXT_DETAILS], 
				[NOORDER], [IF_PRODROMOL], [IDWAREHOUSE],
				[NO_EXT_ORDER], [DROMOLOGIO], [THESI], [IDYPOKWISPRANTIK], [IDYPOKPARALANTIK], [IDYPOKPARADANTIK], [IDYPOKEISPRANTIK]
			  )
        ) AS inserted_unpvt
    )


    --Join them together and show what's changed
    INSERT INTO AUDIT_FORTOTIKES (AuditBATCH, FORTID, FieldName, FieldValueWas, FieldValueIs, SQLUSER, APPUSER)
    SELECT 
		@BATCHID,
		Coalesce (D.ID, I.ID) ID,
		Coalesce (D.FieldName, I.FieldName) FieldName,
		D.FieldValue as FieldValueWas,
        I.FieldValue AS FieldValueIs,
		CURRENT_USER,
		@USER
    FROM 
        deleted_unpvt d
    FULL OUTER JOIN 
        inserted_unpvt i
            ON D.ID = I.ID
			AND D.FieldName = I.FieldName
    WHERE
        D.FieldValue <> I.FieldValue --Changes
        OR (D.FieldValue IS NOT NULL AND I.FieldValue IS NULL) -- Deletions
        OR (D.FieldValue IS NULL AND I.FieldValue IS NOT NULL) -- Insertions
END
GO





