CREATE VIEW [dbo].[ENTOLESVOHLABES]
AS
  SELECT GVD.id,
         Round(GVD.baros, 2)                     AS BAROS,
         V.DATEPRINT							 AS DATEMOVE,
         GVD.idline,
         GVD.idvoh,
         Round(GVD.kybika, 3)                    AS KYBIKA,
         GVD.periexomeno,
         GVD.status,
         Round(GVD.sumposo, 2)                   AS SUMPOSO,
         Round(GVD.sumtemaxia, 0)                AS SUMTEMAXIA,
         GVD.syskevasia,
         GVD.syskevasiadescr,
         Round(GVD.temaxia, 2)                   AS TEMAXIA,
         GVD.BARCODE							 AS BARCODETAMAXIOU, 
         replace((V.SEIRA+ CAST(V.NOPARAST AS NVARCHAR(25))),' ','')	 AS timda,
         GVD.xeosisemonada,
         V.koudouni,
         Round(GVD.xreosianamonada, 2)           AS XreosiAnaMonada,
         Round(GVD.xreosigrammis, 2)             AS XreosiGrammis,
         V.SUMANTIK								 AS ANTIKATAVOLI,
         ACP.eponimia,
         acp.addresscountry,
         ACP.addresspref,
         ( ACP.addressstr + ' ' + acp.addressno + ' ' + V.OROFOSDESCR)  AS ADDRESS,
         ( ACP.addresscity + ' - ' + ACP.addresstk ) AS ADDRESSCITY,
         YP.eponimia                             AS YPOKATASIMA,
         CP.eponimia                             AS COMPANY,
         V.orofosdescr,
         (LTRIM(RTRIM(V.seira)) + LTRIM(RTRIM(CONVERT(NVARCHAR, V.noparast))))					 as noparast,
		 V.ARRIVAL
  FROM   GRAMMESVOHDETAILS AS GVD
		 LEFT JOIN VOH AS V  ON GVD.idvoh = V.id
         --LEFT JOIN paradoseis AS PR ON V.identolis = PR.idvoh
		 --LEFT JOIN VOH AS V ON V.ID=V.IDENTOLIS
         LEFT JOIN accounts AS ACP  ON V.idparalipti = ACP.id
         LEFT JOIN companies AS CP  ON V.idcompany = CP.iddepartement
         LEFT JOIN companies AS YP  ON V.idypokatastima = YP.id 
         --LEFT JOIN VOHITEMSLABELS AS E ON V.ID = E.IDVOH




GO




