	--************************************************************************
	IF @pos IS NULL 
		SELECT @pos = 0
 	--************************************************************************
 	
IF  (@pos > 0)
	BEGIN
	  EXEC ('INSERT INTO TmpTableGRAMMESFORTTIKISDETAILS ( IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, PERIEXOMENO, BAROS, KYBIKA, 
		  SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis) 
		SELECT A.ID AS IDLine, A.IDVOH, A.TIMDA, A.TEMAXIA, A.TEMAXIA AS SUMTEMAXIA, A.SYSKEVASIA, 
		A.PERIEXOMENO, A.BAROS, A.KYBIKA, A.SUMPOSO, A.SYSKEVASIADESCR, A.XreosiAnaMonada, A.XeosiSeMonada, A.XreosiGrammis
	  FROM GRAMMESFORTTIKIS AS A INNER JOIN FORTOTIKES AS B ON A.IDVOH = B.ID LEFT JOIN 
	  ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH IN( ' + @THEIDS + ')');
	END
ELSE
	BEGIN
	
	--CREATE TABLE TMPLABEL
 	--([ID] [numeric](18, 0) IDENTITY(1,1) NOT NULL,
	--	[IDVOH] [numeric](18, 0) NULL)
	EXEC ('INSERT INTO TmpTableGRAMMESFORTTIKISDETAILS ( IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, PERIEXOMENO, BAROS, KYBIKA, 
		  SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis) 
		SELECT A.ID AS IDLine, A.IDVOH, A.TIMDA, A.TEMAXIA, A.TEMAXIA AS SUMTEMAXIA, A.SYSKEVASIA, 
		A.PERIEXOMENO, A.BAROS, A.KYBIKA, A.SUMPOSO, A.SYSKEVASIADESCR, A.XreosiAnaMonada, A.XeosiSeMonada, A.XreosiGrammis
	  FROM GRAMMESFORTTIKIS AS A INNER JOIN FORTOTIKES AS B ON A.IDVOH = B.ID LEFT JOIN 
	  ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH = ' + @THEIDS + '');
	END

