ALTER PROCEDURE [dbo].[CREATEGRAMMESVOHDETAILS]
(
	@THEIDS				NVARCHAR(MAX) 
	)
AS
DECLARE
  @ErrorMessage   varchar(2000)
 ,@ErrorSeverity  tinyint
 ,@ErrorState     tinyint

BEGIN TRY

SET NOCOUNT ON;
DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='CREATEGRAMMESVOHDETAILS', @LockMode='Exclusive', @LockOwner='Transaction', 
@LockTimeout = 1000
-------------------------------------------------------------------------------------------------------------------------

	EXEC('DELETE FROM GRAMMESVOHDETAILS WHERE IDVOH IN(' + @THEIDS + ')');
	EXEC('DELETE FROM TmpTableGRAMMESVOHDETAILS');

	DECLARE @SUMTEMATIAOFVOH NUMERIC (10, 0) = 0
	DECLARE @CURRRENTTEMATIO NUMERIC (10, 0) = 0

	DECLARE @pos INT = 0;
	DECLARE @substr NVARCHAR(1)
	SET @substr = ',';
	SET @pos = CHARINDEX(@substr, @THEIDS, @pos);
	--************************************************************************
	IF @pos IS NULL 
		SELECT @pos = 0
 	--************************************************************************
 	
IF  (@pos > 0)
	BEGIN
	SELECT	@SUMTEMATIAOFVOH = SUM(A.PCS) 
	FROM GRAMMESVOH AS A INNER JOIN VOH AS B ON A.IDVOH = B.ID LEFT JOIN 
	ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH IN(@THEIDS)

	  EXEC ('INSERT INTO TmpTableGRAMMESVOHDETAILS ( IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, PERIEXOMENO, BAROS, KYBIKA, 
		  SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis, BARCODE) 
		SELECT A.ID AS IDLine, A.IDVOH, A.TIMDA, A.TEMAXIA,  A.PCS AS SUMTEMAXIA, A.IDSYSKEVASIAS, 
		A.PERIEXOMENO, A.BAROS, A.KYBIKA, A.SUMPOSO, A.SYSKEVASIADESCR, A.TIMITEM AS XreosiAnaMonada, ' + '''' +
		'ΣΥΣΚΕΥΑΣΙΑ' + '''' + ', A.SUMPOSO AS XreosiGrammis, (LTRIM(RTRIM(B.SEIRA)) + CAST(B.NOPARAST AS NVARCHAR(15))) AS BARCODE 
		FROM GRAMMESVOH AS A INNER JOIN VOH AS B ON A.IDVOH = B.ID LEFT JOIN 
		ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH IN(' + @THEIDS + ')');
		  
	END
ELSE
	BEGIN
		SELECT	@SUMTEMATIAOFVOH = SUM(A.PCS) 
	FROM GRAMMESVOH AS A INNER JOIN VOH AS B ON A.IDVOH = B.ID LEFT JOIN 
	ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH IN(@THEIDS)

	EXEC ('INSERT INTO TmpTableGRAMMESVOHDETAILS ( IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, PERIEXOMENO, BAROS, KYBIKA, 
		  SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis, BARCODE) 
		SELECT A.ID AS IDLine, A.IDVOH, A.TIMDA, A.TEMAXIA, A.PCS AS SUMTEMAXIA, A.IDSYSKEVASIAS, 
		A.PERIEXOMENO, A.BAROS, A.KYBIKA, A.SUMPOSO, A.SYSKEVASIADESCR, A.TIMITEM AS XreosiAnaMonada, ' + '''' +
		'ΣΥΣΚΕΥΑΣΙΑ' + '''' + ', A.SUMPOSO AS XreosiGrammis, (LTRIM(RTRIM(B.SEIRA)) + CAST(B.NOPARAST AS NVARCHAR(15))) AS BARCODE
		FROM GRAMMESVOH AS A INNER JOIN VOH AS B ON A.IDVOH = B.ID LEFT JOIN 
		ACCOUNTS AS C ON B.IDAPOSTOLEA = C.ID LEFT JOIN ACCOUNTS AS D ON B.IDPARALIPTI = D.ID WHERE A.IDVOH =' + @THEIDS + '');
		
	END

--------------------------------------------------------------------------------------------------------------------------
SELECT @CURRRENTTEMATIO = 0

 
DECLARE CUR CURSOR FAST_FORWARD READ_ONLY FOR SELECT IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, STATUS, DATEMOVE, 
	PERIEXOMENO, BAROS, KYBIKA, SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis, BARCODE  
    FROM TmpTableGRAMMESVOHDETAILS;
  

DECLARE @IDVOH numeric(18, 0)= NULL
DECLARE @IDLine   numeric(18, 0)= NULL
DECLARE @TIMDA nvarchar(20) =NULL
DECLARE @TEMAXIA numeric(18, 0)= NULL
DECLARE @SUMTEMAXIA numeric(18,0) =NULL
DECLARE @SYSKEVASIA numeric(8, 0) = NULL
DECLARE @STATUS NVARCHAR (30) =NULL
DECLARE @DATEMOVE smalldatetime = NULL
DECLARE @PERIEXOMENO  nvarchar(50)= NULL
DECLARE @BAROS numeric(18, 2)= NULL
DECLARE @KYBIKA numeric(18, 2)= NULL
DECLARE @SUMPOSO numeric(18, 2) =NULL
DECLARE @SYSKEVASIADESCR nvarchar(50)= NULL
DECLARE @XreosiAnaMonada numeric(18, 2)= NULL
DECLARE @XeosiSeMonada nvarchar(15) =NULL
DECLARE @XreosiGrammis numeric(18, 2)= NULL
DECLARE @BARCODE NVARCHAR(30) = NULL
DECLARE @BARCODETEMAXIOU NVARCHAR(30) = NULL

OPEN CUR
FETCH NEXT FROM CUR INTO @IDLine, @IDVOH, @TIMDA, @TEMAXIA, @SUMTEMAXIA, @SYSKEVASIA, @STATUS, @DATEMOVE, @PERIEXOMENO, 
@BAROS, @KYBIKA, @SUMPOSO, @SYSKEVASIADESCR, @XreosiAnaMonada, @XeosiSeMonada, @XreosiGrammis, @BARCODE

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @TEMAXIA = 0
	WHILE @TEMAXIA < @SUMTEMAXIA 
	BEGIN
		SELECT @TEMAXIA =  @TEMAXIA +1
		SELECT @CURRRENTTEMATIO = @CURRRENTTEMATIO +1
		SELECT @BARCODETEMAXIOU = LTRIM(RTRIM(@BARCODE)) + '-' + CONVERT(NVARCHAR, @TEMAXIA)
		
		INSERT INTO  GRAMMESVOHDETAILS (IDLine, IDVOH, TIMDA, TEMAXIA, SUMTEMAXIA, SYSKEVASIA, STATUS, DATEMOVE,  
		PERIEXOMENO, BAROS, KYBIKA, SUMPOSO, SYSKEVASIADESCR, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis, BARCODE)
		VALUES (@IDLine, @IDVOH, @TIMDA, @CURRRENTTEMATIO, @SUMTEMATIAOFVOH, @SYSKEVASIA, @STATUS, @DATEMOVE, @PERIEXOMENO, 
		@BAROS, @KYBIKA, @SUMPOSO, @SYSKEVASIADESCR, @XreosiAnaMonada, @XeosiSeMonada, @XreosiGrammis, @BARCODETEMAXIOU)	
	END	
	FETCH NEXT FROM CUR INTO @IDLine, @IDVOH, @TIMDA, @TEMAXIA, @SUMTEMAXIA, @SYSKEVASIA, @STATUS, @DATEMOVE, @PERIEXOMENO, 
	@BAROS, @KYBIKA, @SUMPOSO, @SYSKEVASIADESCR, @XreosiAnaMonada, @XeosiSeMonada, @XreosiGrammis, @BARCODE		
END
CLOSE CUR
DEALLOCATE CUR
waitfor delay '00:00:00:40'            
commit;
END TRY

BEGIN CATCH
    SET @ErrorMessage  = ERROR_MESSAGE()
    SET @ErrorSeverity = ERROR_SEVERITY()
    SET @ErrorState    = ERROR_STATE()
    RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState)

END CATCH 

GO

