create PROCEDURE [dbo].[CREATE_BARCODE_TEMAXION_FORTOTIKIS] (@IDFORT INT)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @BARCODE_FORTOTIKIS NVARCHAR(150);

	DECLARE @ID_GRAMMIS INT
				 ,@TEMAXIA_GRAMMIS INT;

	DECLARE @AA_GRAMMIS INT
				 ,@AA_SYNOLIKOS INT
				 ,@I INT;

	SELECT
		@BARCODE_FORTOTIKIS = EXT_BARCODE
	FROM FORTOTIKES
	WHERE ID = @IDFORT;


	DECLARE CUR CURSOR FOR SELECT
		ID
	 ,TEMAXIA
	FROM GRAMMESFORTTIKIS
	WHERE IDVOH = @IDFORT;

	OPEN CUR;

	FETCH NEXT FROM CUR INTO @ID_GRAMMIS, @TEMAXIA_GRAMMIS;

	SET @AA_SYNOLIKOS = 1;
	WHILE @@FETCH_STATUS = 0
	BEGIN
	SET @AA_GRAMMIS = 1;

	WHILE @AA_GRAMMIS <= @TEMAXIA_GRAMMIS
	BEGIN
	INSERT INTO TEMAXIAFORTOTIKIS (IDFORTOTIKIS, IDGRAMMIS, AAFORT, AAGRAMMIS, BARCODE)
		SELECT
			@IDFORT
		 ,@ID_GRAMMIS
		 ,@AA_SYNOLIKOS
		 ,@AA_GRAMMIS
		 ,@BARCODE_FORTOTIKIS + '-' + CONVERT(NVARCHAR, @AA_SYNOLIKOS);

	SET @AA_GRAMMIS = @AA_GRAMMIS + 1;
	SET @AA_SYNOLIKOS = @AA_SYNOLIKOS + 1;
	END

	FETCH NEXT FROM CUR INTO @ID_GRAMMIS, @TEMAXIA_GRAMMIS;
	END

	CLOSE CUR;
	DEALLOCATE CUR;


END
GO
