ALTER PROCEDURE [dbo].[inserttoFORT_ANA_KAA] (@ID NUMERIC(18, 0) = NULL,
@IDKAA NUMERIC(18, 0) = NULL,
@NoPARASTKAA NVARCHAR(10) = NULL,
@OXIMA NVARCHAR(60) = NULL,
@CONTAINER NVARCHAR(50) = NULL,
@BOAT NVARCHAR(50) = NULL,
@INSERTFORTOTIKES NVARCHAR(MAX) = NULL)
AS
	SET NOCOUNT ON

	DECLARE @RC INT
	BEGIN TRAN
	EXEC @RC = sp_getapplock @Resource = 'inserttoFORT_ANA_KAA'
													,@LockMode = 'Exclusive'
													,@LockOwner = 'Transaction'
													,@LockTimeout = 1000

	DECLARE @_STATUSID INT
	DECLARE @_STATUS VARCHAR(75)
	--SET @_STATUS = 'ΣΕ ΚΑΑ'

	DECLARE @_DRIVERID INT
	DECLARE @_DRIVERDESCR NVARCHAR(50)

	SELECT
		@_STATUS = STATUS
	 ,@_STATUSID = IDSTATUS
	 ,@_DRIVERID = ODIGOI.ID
	 ,@_DRIVERDESCR = KAA.DRIVER
	FROM KAA
	LEFT JOIN ODIGOI ON ODIGOI.LastName + ' ' + ODIGOI.FirstName = KAA.DRIVER
	WHERE KAA.ID = @IDKAA

	IF LEN(@_STATUS) < 3
	BEGIN
		SELECT TOP 1
			@_STATUS = DESCR
		 ,@_STATUSID = ID
		FROM DOC_STATUS
		WHERE IFSEKAA = 1
	END



	DECLARE @_NULL VARCHAR(75)
	SET @_NULL = ''

	EXEC ('UPDATE FORTOTIKES SET NOPARASTDELTIOUAPOSTOLIS =''' + @NoPARASTKAA + ''', CONTAINER =''' + @CONTAINER + ''', OXIMA =''' + @OXIMA +
	''', BOAT =''' + @BOAT + ''', IDDRIVER =	''' + @_DRIVERID + ''', DRIVERDESCR= ''' + @_DRIVERDESCR + ''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = ''' + @_STATUS + ''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')
	DECLARE @coma CHAR(1)
	SELECT
		@coma = ','
	BEGIN
		DECLARE @start INT
					 ,@end INT
		SELECT
			@start = 1
		 ,@end = CHARINDEX(@coma, @INSERTFORTOTIKES)
		WHILE @start < LEN(@INSERTFORTOTIKES) + 1
		BEGIN
		IF @end = 0
			SET @end = LEN(@INSERTFORTOTIKES) + 1
		INSERT INTO FORTOTIKES_ANA_KAA (IDKAA, IDFORTOTIKIS, KOMISTRA, DIKAIOMA, OTHERPOSO, EXODATRITON, XREOSIPROPLIROMENES,
		XREOSIOFEILOMENES, XREOSIPROPLIROMENESCASH, XREOSIPROPLIROMENESPISTOSI, POSO, TAXIS, SUMPOSO, ANTIKCASH,
		ANTIKEPIT, ANTIKSYNAL, ANTIKOTHER, SUMANTIK, IDPARALIPTI, PARALISPTISDESCR, IDAPOSTOLEA, APOSTOLEASDESCR,
		IDENTOLEA, ENTOLEASDESCR, IDTRITOU, TRITOSDESCR, XREOYMENOS, OMADPROORISMOS, OXIMA, DRIVERDESCR, BAROS,
		KYBIKA, TEMAXIA, AXIA, PERIEXOMENO, TIMDA, ASFALISTRA, ERGATIKA, CODE, NOPARASTFORT, SYSKEVASIA, DIAFORA_EXODA,
		XREOSEISTRITON, EMVASTIKA, OTHERXREOSEIS, PROPLMETRERGATIKA, PROPLMETRASFALISTRA, PROPLMETRDIKAIOMA, PROPLMETRKOMISTRA,
		IDPRAKTOREIO, PRAKTOREIODESCR, ANAMEXODO, PROPLMETROTHERXREOSEIS, ANTAPOKRITIS, OFEILOMENAKOMISTRA, SYN_POSO_FORTOTIKIS,
		TAXISOFEIL, TAXISPROPLMETR, KATHAROOFEIL, KATHAROPROPLMETR)
			SELECT
				@IDKAA AS IDKAA
			 ,A.ID
			 ,A.KOMISTRA
			 ,A.DIKAIOMA
			 ,A.OTHERPOSO
			 ,A.EXODATRITON
			 ,A.XREOSIPROPLIROMENES
			 ,A.XREOSIOFEILOMENES
			 ,A.XREOSIPROPLIROMENESCASH
			 ,A.XREOSIPROPLIROMENESPISTOSI
			 ,A.POSO
			 ,A.TAXIS
			 ,A.SUMPOSO
			 ,A.ANTIKCASH
			 ,A.ANTIKEPIT
			 ,A.ANTIKSYNAL
			 ,A.ANTIKOTHER
			 ,A.SUMANTIK
			 ,A.IDPARALIPTI
			 ,A.PARALISPTISDESCR
			 ,A.IDAPOSTOLEA
			 ,A.APOSTOLEASDESCR
			 ,A.IDENTOLEA
			 ,A.ENTOLEASDESCR
			 ,A.IDTRITOU
			 ,A.TRITOSDESCR
			 ,A.XREOYMENOS
			 ,A.OMADPROORISMOS
			 ,A.OXIMA
			 ,A.DRIVERDESCR
			 ,A.BAROS
			 ,A.KYBIKA
			 ,A.TEMAXIA
			 ,A.AXIA
			 ,A.PERIEXOMENO
			 ,A.TIMDA
			 ,G.ASFALISTRA
			 ,G.ERGATIKA
			 ,A.CODE
			 ,A.NOPARASTFORT
			 ,A.SYSKEVASIA
			 ,G.DIAFORA_EXODA
			 ,G.XREOSEISTRITON
			 ,G.EMVASTIKA
			 ,G.OTHERXREOSEIS
			 ,G.PROPLMETRERGATIKA
			 ,G.PROPLMETRASFALISTRA
			 ,G.PROPLMETRDIKAIOMA
			 ,G.PROPLMETRKOMISTRA
			 ,A.IDPRAKTOREIO
			 ,A.PRAKTOREIODESCR
			 ,A.ANAMEXODO
			 ,G.PROPLMETROTHERXREOSEIS
			 ,FR.ANTAPOKRITISDESCR
			 ,G.OFEILOMENAKOMISTRA
			 ,G.SYN_POSO_FORTOTIKIS
			 ,G.TAXISOFEIL
			 ,G.TAXISPROPLMETR
			 ,G.KATHAROOFEIL
			 ,G.KATHAROPROPLMETR
			FROM FORTOTIKES_ANALYSH_XREOSEON AS A
			LEFT JOIN FORTOTIKES AS FR
				ON FR.ID = A.ID
			INNER JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI AS G
				ON A.ID = G.ID
			WHERE A.ID = CAST(SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start) AS NUMERIC)

		--VALUES(@IDKAA, CAST( SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start)AS NUMERIC)) 

		SET @start = @end + 1
		SET @end = CHARINDEX(@coma, @INSERTFORTOTIKES, @start)
		END
	END

	WAITFOR DELAY '00:00:00:40'
	COMMIT;
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


ALTER PROCEDURE [dbo].[inserttoFORT_ANA_LISTA] (@ID NUMERIC(18, 0) = NULL,
@IDLISTAS NUMERIC(18, 0) = NULL,
@NoPARASTKAA NVARCHAR(10) = NULL,
@OXIMA NVARCHAR(60) = NULL,
@INSERTFORTOTIKES NVARCHAR(MAX) = NULL)
AS
	SET NOCOUNT ON
	DECLARE @_STATUS VARCHAR(75)
	DECLARE @_STATUSID INT

	--SET @_STATUS = 'ΣΕ ΛΙΣΤΑ ΔΙΑΝΟΜΗΣ'


	DECLARE @_DRIVERID INT
	DECLARE @_DRIVERDESCR NVARCHAR(50)


	SELECT
		@_STATUS = STATUS
	 ,@_STATUSID = IDSTATUS
	 ,@_DRIVERID = ODIGOI.ID
	 ,@_DRIVERDESCR = LISTESDIANOMIS.DRIVER

	FROM LISTESDIANOMIS
	LEFT JOIN ODIGOI ON ODIGOI.LastName + ' ' + ODIGOI.FirstName = LISTESDIANOMIS.DRIVER
	WHERE LISTESDIANOMIS.ID = @IDLISTAS


	IF LEN(@_STATUS) < 3
	BEGIN
		SELECT TOP 1
			@_STATUS = DESCR
		 ,@_STATUSID = ID
		FROM DOC_STATUS
		WHERE IFSELISTA = 1
	END


	DECLARE @_NULL VARCHAR(75)
	SET @_NULL = ''

	EXEC ('UPDATE FORTOTIKES SET NOLISTASDIANOMIS =''' + @NoPARASTKAA + ''', OXIMA =''' + @OXIMA +
	''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = ''' + @_STATUS + ''', IDDRIVER = ''' + @_DRIVERID + ''' , DRIVERDESCR = ''' + @_DRIVERDESCR + ''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')
	DECLARE @coma CHAR(1)
	SELECT
		@coma = ','
	BEGIN
		DECLARE @start INT
					 ,@end INT
		SELECT
			@start = 1
		 ,@end = CHARINDEX(@coma, @INSERTFORTOTIKES)
		WHILE @start < LEN(@INSERTFORTOTIKES) + 1
		BEGIN
		IF @end = 0
			SET @end = LEN(@INSERTFORTOTIKES) + 1

		INSERT INTO FORTOTIKES_ANA_LISTA (IDLISTAS, IDFORTOTIKIS)
			VALUES (@IDLISTAS, CAST(SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start) AS NUMERIC))
		SET @start = @end + 1
		SET @end = CHARINDEX(@coma, @INSERTFORTOTIKES, @start)

		END

	END
GO



SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[InserttoPROFORTOTIKES_IMPORT] (@IDENTOLEA NUMERIC(18, 0) = NULL,
@IDAPOSTOLEA NUMERIC(18, 0) = NULL,
@IDPARALIPTI NUMERIC(18, 0) = NULL,
@IDTRITOU NUMERIC(18, 0) = NULL,
@IDPARAST NUMERIC(18, 0) = NULL,

@ANTIKCASH NUMERIC(8, 2) = NULL,
@ANTIKEPIT NUMERIC(8, 2) = NULL,
@ANTIKSYNAL NUMERIC(8, 2) = NULL,
@ANTIKOTHER NUMERIC(8, 2) = NULL,

@DATEPRINT SMALLDATETIME = NULL,

@NO_EXT_ORDER NVARCHAR(50) = NULL,
@EXT_BARCODE NVARCHAR(150) = NULL,


@POSO NUMERIC(8, 2) = NULL,
@TAXIS NUMERIC(8, 2) = NULL,
@SUMPOSO NUMERIC(8, 2) = NULL,




@NOPARASTANTIK NVARCHAR(50) = NULL,
@COMMENTS NVARCHAR(MAX) = NULL,

@COMPANYID INT = NULL,
@YPOKATID INT = NULL,

@USERCREATE NVARCHAR(50) = 'Import Tool',

@FLAG_PROPLIROMENI BIT = NULL,
@FLAG_OFEILOMENI BIT = NULL,
@FLAG_METRITIS BIT = NULL,
@FLAG_PISTOSI BIT = NULL,
@ANTIKCOMMENTS NVARCHAR(100) = NULL,

@PERIOXIPARADOSIS NVARCHAR(50) = NULL,

@TheID NUMERIC(18, 0) = NULL OUTPUT)
AS

	SET NOCOUNT ON;


	DECLARE @PARAST_SEIRA NVARCHAR(50)
	DECLARE @PARAST_DESC NVARCHAR(50)
	DECLARE @PARAST_AUTONUMBER BIT
	DECLARE @PARAST_TAXISPERCENT NUMERIC(18, 2)

	DECLARE @IDKINDPAYMENT INT
	DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

	DECLARE @IDSTATUS INT
	DECLARE @STATUSDESCR NVARCHAR(50)

	DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
	DECLARE @AFMAPOSTOLEA NVARCHAR(10) = NULL
	DECLARE @AFMENTOLEA NVARCHAR(10) = NULL
	DECLARE @AFMPARALIPTI NVARCHAR(10) = NULL
	DECLARE @AFMTRITOU NVARCHAR(10) = NULL


	DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL

	DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

	DECLARE @APOSTOLEASDESCR NVARCHAR(50) = NULL
	DECLARE @PARALISPTISDESCR NVARCHAR(50) = NULL
	DECLARE @ENTOLEASDESCR NVARCHAR(50) = NULL
	DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

	DECLARE @IDXRHSHS INT;

	SELECT TOP 1
		@IDXRHSHS = ID
	FROM XRHSEIS
	WHERE GETDATE() BETWEEN FIRSTDATE AND LASTDATE

	SELECT
		@AFMXREOUMENOU = AFM
	FROM ACCOUNTS
	WHERE ID = @IDENTOLEA
	SELECT
		@AFMENTOLEA = AFM
	 ,@ENTOLEASDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDENTOLEA

	SELECT
		@AFMAPOSTOLEA = AFM
	 ,@APOSTOLEASDESCR = Eponimia
	 ,@PERIOXIFORTOSIS = AddressCity
	FROM ACCOUNTS
	WHERE ID = @IDAPOSTOLEA

	SELECT
		@AFMTRITOU = afm
	 ,@TRITOSDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDTRITOU

	SELECT
		@AFMPARALIPTI = AFM
	 ,@PARALISPTISDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDPARALIPTI

	SELECT TOP 1
		@IDKINDPAYMENT = ID
	 ,@KINDPAYMENTDESCR = DESCR
	FROM KINDOFPAYMENTS
	WHERE IF_PISTOSI = 1
	AND IF_IN = 1

	SELECT TOP 1
		@IDSTATUS = ID
	 ,@STATUSDESCR = DESCR
	FROM DOC_STATUS
	WHERE IF_PRINT = 1
	AND IFEKDOSI = 1

	SELECT
		@PARAST_SEIRA = SEIRA
	 ,@PARAST_DESC = DESCR
	 ,@PARAST_AUTONUMBER = IF_AUTONUMBER
	 ,@PARAST_TAXISPERCENT = TAXISPERCENT

	FROM KINDPARASTATIKON
	WHERE ID = @IDPARAST


	--@STATUSDESCR				NVARCHAR(50) = NULL,

	DECLARE @BARCODE_PREFIX NVARCHAR(50)
	SET @BARCODE_PREFIX = (SELECT
			BARCODE_PREFIX
		FROM COMPANIES
		WHERE id = @YPOKATID)
	+ CONVERT(NVARCHAR, @IDENTOLEA)


	EXEC InserttoPROFORTOTIKES @TheID = @TheID OUTPUT
														,@IDENTOLEA = @IDENTOLEA
														,@IDAPOSTOLEA = @IDAPOSTOLEA
														,@IDPARALIPTI = @IDPARALIPTI
														,@IDTRITOU = @IDTRITOU
														,@IDANTAPOKRITI = -1
														,@IDXREOUMENOU = @IDENTOLEA
														,@IDPARAST = @IDPARAST
														,@PARASTATIKO = @PARAST_DESC
														,@SEIRA = @PARAST_SEIRA
														,@IFAUTONUMBER = @PARAST_AUTONUMBER
														,@ANTIKCASH = @ANTIKCASH
														,@ANTIKEPIT = @ANTIKEPIT
														,@ANTIKSYNAL = @ANTIKSYNAL
														,@ANTIKOTHER = @ANTIKOTHER
														,@PERIOXIPARADOSIS = @PERIOXIPARADOSIS
														,@PERIOXIFORTOSIS = @PERIOXIFORTOSIS
														,@IFCASH = 0
														,@IFPISTOSI = 1
														,@IFPREPAY = 1
														,@IFOFEILOMENI = 0
														,@DATEPRINT = @DATEPRINT
														,@IDKINDPAYMENT = @IDKINDPAYMENT
														,@KINDPAYMENTDESCR = @KINDPAYMENTDESCR
														,@NO_EXT_ORDER = @NO_EXT_ORDER
														,@EXT_BARCODE = @EXT_BARCODE
														,@STATUS = @IDSTATUS
														,@STATUSDESCR = @STATUSDESCR
														,@AFMXREOUMENOU = @AFMXREOUMENOU
														,@AFMENTOLEA = @AFMENTOLEA
														,@AFMAPOSTOLEA = @AFMAPOSTOLEA
														,@AFMPARALIPTI = @AFMPARALIPTI
														,@AFMTRITOU = @AFMTRITOU
														,@APOSTOLEASDESCR = @APOSTOLEASDESCR
														,@PARALISPTISDESCR = @PARALISPTISDESCR
														,@ENTOLEASDESCR = @ENTOLEASDESCR
														,@TRITOSDESCR = @TRITOSDESCR
														,@DateCreate = @DATEPRINT
														,@UserCreate = @USERCREATE
														,@IDXRHSHS = @IDXRHSHS
														,@TAXISPERCENT = @PARAST_TAXISPERCENT
														,@COMMENTS = @COMMENTS
														,@IDCOMPANY = @COMPANYID
														,@IDYPOKATASTIMA = @YPOKATID


	UPDATE PF
	SET IFANTIKCASH =
			CASE
				WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKEPIT =
			CASE
				WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKSYNAL =
			CASE
				WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKOTHER =
			CASE
				WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1
				ELSE 0
			END
		 ,SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER, 0)
		 ,IFXRENTOL = 1
		 ,IFPREPAY = ENTOL.IFPREPAY
		 ,IFCASH = ENTOL.IFCASH
		 ,IFOFEILOMENI = ENTOL.IFOFEILOMENI
		 ,IFPISTOSI = ENTOL.IFPISTOSI
		 ,COMMENTSANTIK = @ANTIKCOMMENTS

	FROM PROFORTOTIKES PF
	JOIN ACCOUNTS ENTOL
		ON ENTOL.id = PF.IDENTOLEA
	WHERE PF.ID = @TheID;

	UPDATE PF
	SET PF.OMADPROORISMOS =
			CASE
				WHEN LEN(OP.Descr) >= 2 THEN OP.Descr
				ELSE (SELECT TOP 1
							Descr
						FROM OMADIKOI_PROORISMOI
						WHERE LEN(Descr) <= 1)
			END
		 ,PF.OXIMA = (SELECT
					ARKYKLOFORIAS
				FROM TRUCKS
				WHERE LEN(ArKykloforias) <= 2)
		 ,PF.IDDRIVER = (SELECT
					MIN(ID) [ID]
				FROM ODIGOI
				WHERE ifDelete = 0)
		 ,PF.DRIVERDESCR = (SELECT TOP 1
					(LastName + ' ' + FirstName)
				FROM ODIGOI
				WHERE IFDELETE = 0)
		 ,pf.PERIOXIPARADOSIS = paral.AddressCity

	FROM PROFORTOTIKES PF
	JOIN ACCOUNTS paral
		ON paral.id = pf.IDPARALIPTI
	LEFT JOIN Aar
		ON Aar.AarName = paral.AddressCity
	LEFT JOIN AarPerOmProor AOM
		ON AOM.AarID = Aar.AarID
	LEFT JOIN OMADIKOI_PROORISMOI OP
		ON OP.ID = AOM.IDOmProor
	WHERE PF.ID = @TheID;

	INSERT INTO XREOSISANAPRODELTIO (IDVOH,
	IDXREOSIS,
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_PROFORTOTIKI,
	IF_TO_PROVOH)
		SELECT
			PROFORT.ID
		 ,XR.ID
		 ,XR.CODE
		 ,XR.Descr
		 ,XR.TAXISPERCENT
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 1
				ELSE 0
			END
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 0.24
				ELSE 0
			END
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 1.24
				ELSE 0
			END
		 ,1
		 ,0

		FROM XREOSISANAPARASTATIKO XAP
		JOIN PROFORTOTIKES PROFORT
			ON PROFORT.IDPARAST = XAP.IDKINDPARASTTIKON
		JOIN Xreoseis XR
			ON XR.ID = XAP.IDXREOSIS
		WHERE XAP.ifDelete = 0
		AND XR.ifDelete = 0
		AND XAP.IDKINDPARASTTIKON = PROFORT.IDPARAST
		AND PROFORT.ID = @theID;

	-- update #10523
	WITH sumxr
	AS
	(SELECT
			xad.IDVOH
		 ,SUM(xad.POSO) POSO
		 ,SUM(xad.TAXIS) TAXIS
		 ,SUM(xad.SUMPOSO) SUMPOSO
		FROM XREOSISANAPRODELTIO xad
		WHERE xad.IF_TO_PROFORTOTIKI = 1
		AND xad.IDVOH = @TheID
		GROUP BY xad.IDVOH)
	UPDATE PF
	SET POSO = SUMXR.POSO
		 ,TAXIS = SUMXR.TAXIS
		 ,SUMPOSO = SUMXR.SUMPOSO
	FROM PROFORTOTIKES PF
	JOIN SUMXR
		ON PF.ID = SUMXR.IDVOH;


	-- κλαιει η μανα του πελε
	WITH SUMXRPF
	AS
	(SELECT
			xap.IDVOH
		 ,ISNULL(XR.ifKomistra, 0) ifKomistra
		 ,ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis
		 ,ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton
		 ,ISNULL(xr.ifOther, 0) ifOther
		 ,ISNULL(xr.IfAsfalistra, 0) ifAsfalistra
		 ,ISNULL(xr.ifErgatika, 0) ifErgatika
		 ,ISNULL(xr.IfEmvastika, 0) ifEmvastika
		 ,SUM(xap.POSO) POSO
		FROM XREOSISANAPRODELTIO XAP
		JOIN Xreoseis XR
			ON XR.ID = XAP.IDXREOSIS
		WHERE xap.IDVOH = @TheID
		GROUP BY GROUPING SETS (
		(IDVOH, ifKomistra),
		(IDVOH, ifDikaiomaFortotikis),
		(IDVOH, ifXreosiTriton),
		(IDVOH, ifOther),
		(IDVOH, IfAsfalistra),
		(IDVOH, ifErgatika),
		(IDVOH, ifEmvastika)
		)
		HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		OR ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		OR ISNULL(xr.ifXreosiTriton, 0) = 1
		OR ISNULL(xr.ifOther, 0) = 1
		OR ISNULL(xr.IfAsfalistra, 0) = 1
		OR ISNULL(xr.ifErgatika, 0) = 1
		OR ISNULL(xr.IfEmvastika, 0) = 1
		))
	INSERT INTO HEADERPROFORTOTIKIS (IDPROFORT,
	PARASTATIKOPROFORT,
	SEIRAPROFORT,
	NOPARASTPROFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRPROFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONPROFORT,
	BAROSPROFORT,
	KYBIKAPROFORT,
	POSOPROFORT,
	TEMAXIAPROFORT)
		SELECT
			PROFORT.ID
		 ,PROFORT.PARASTATIKO
		 ,PROFORT.SEIRA
		 ,PROFORT.NOPARAST
		 ,PROFORT.ENTOLEASDESCR
		 ,PROFORT.PARALISPTISDESCR
		 ,PROFORT.APOSTOLEASDESCR
		 ,ISNULL(SUM_KOMISTRA.POSO, 0)
		 ,ISNULL(SUM_DIKAIOMA.POSO, 0)
		 ,ISNULL(SUM_OTHER.POSO, 0)
		 ,ISNULL(GPF.SYSKEVASIA, 0)
		 ,ISNULL(SUM_ASFALISTRA.POSO, 0)
		 ,

			--katharo?
			PROFORT.POSO
		 ,PROFORT.TAXIS
		 ,PROFORT.SUMPOSO
		 ,ISNULL(SUM_ERGATIKA.POSO, 0)
		 ,ISNULL(PROFORT.EXODATRITON, 0)
		 ,

			--oliko synolo xreoson ?!
			PROFORT.SUMPOSO + PROFORT.EXODATRITON
		 ,ISNULL(GPF.BAROS, 0)
		 ,ISNULL(GPF.KYBIKA, 0)
		 ,

			--what the fuck den perigrafw allo
			PROFORT.POSO
		 ,ISNULL(GPF.TEMAXIA, 0)

		FROM PROFORTOTIKES PROFORT
		LEFT JOIN (SELECT
				IDVOH
			 ,MIN(SYSKEVASIADESCR) SYSKEVASIA
			 ,SUM(BAROS) BAROS
			 ,SUM(KYBIKA) KYBIKA
			 ,SUM(TEMAXIA) TEMAXIA
			FROM GRAMMESPROFORTTIKIS
			GROUP BY IDVOH) GPF
			ON GPF.IDVOH = PROFORT.ID
		LEFT JOIN SUMXRPF SUM_KOMISTRA
			ON SUM_KOMISTRA.ifKomistra = 1
		LEFT JOIN SUMXRPF SUM_DIKAIOMA
			ON SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
		LEFT JOIN SUMXRPF SUM_OTHER
			ON SUM_OTHER.ifOther = 1
		LEFT JOIN SUMXRPF SUM_ASFALISTRA
			ON SUM_ASFALISTRA.ifAsfalistra = 1
		LEFT JOIN SUMXRPF SUM_ERGATIKA
			ON SUM_ERGATIKA.ifErgatika = 1
		LEFT JOIN SUMXRPF SUM_TRITON
			ON SUM_TRITON.ifXreosiTriton = 1
		LEFT JOIN (SELECT
				IDVOH
			 ,SUM(POSO) POSO
			 ,SUM(TAXIS) TAXIS
			 ,SUM(SUMPOSO) SUMPOSO
			FROM XREOSISANAPRODELTIO
			GROUP BY IDVOH) SUMXR
			ON SUMXR.IDVOH = PROFORT.ID

		WHERE id = @TheID;
	INSERT INTO AarAlternativeNames ([FreeText],
	FreeZip)
		SELECT
			P.PERIOXIPARADOSIS
		 ,A.AddressTK
		FROM PROFORTOTIKES p
		LEFT JOIN ACCOUNTS a
			ON A.id = P.IDPARALIPTI

	SELECT
		@TheID AS IDVOH;
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[SAVEHEADERFORTOTIKIS] (@IDFORT NUMERIC(18, 0) = NULL,
@PARASTATIKOFORT NVARCHAR(100) = NULL,
@SEIRAFORT NVARCHAR(10) = NULL,
@NOPARASTFORT NVARCHAR(20) = NULL,
@ENTOLEASDESCR NVARCHAR(50) = NULL,
@PARALISPTISDESCR NVARCHAR(50) = NULL,
@APOSTOLEASDESCR NVARCHAR(50) = NULL,
@KOMISTRA NUMERIC(18, 3) = NULL,
@DIKAIOMAFORTOTIKIS NUMERIC(18, 3) = NULL,
@OTHERXREOSIS NUMERIC(18, 3) = NULL,
@SYSKEVASIA NVARCHAR(30) = NULL,
@ASFALISTRA NUMERIC(18, 3) = NULL,
@KATHARO NUMERIC(18, 3) = NULL,
@TAXIS NUMERIC(18, 3) = NULL,
@SUMPOSOXRFORT NUMERIC(18, 3) = NULL,
@ERGATIKA NUMERIC(18, 3) = NULL,
@XREOSISTRITON NUMERIC(18, 3) = NULL,
@OLIKOSYNOLOXREOSEONFORT NUMERIC(18, 3) = NULL,
@BAROSFORT NUMERIC(18, 3) = NULL,
@KYBIKAFORT NUMERIC(18, 3) = NULL,
@POSOFORT NUMERIC(18, 3) = NULL,
@TEMAXIAFORT NUMERIC(18, 0) = NULL)
AS
	DECLARE @ErrorMessage VARCHAR(2000)
				 ,@ErrorSeverity TINYINT
				 ,@ErrorState TINYINT

	BEGIN TRY

		SET NOCOUNT ON;
		DECLARE @RC INT


		BEGIN TRANSACTION
		IF EXISTS (SELECT
					1
				FROM HEADERFORTOTIKIS
				WHERE IDFORT = @IDFORT)--LTRIM(RTRIM(@TheID)))
		BEGIN
			DELETE FROM HEADERFORTOTIKIS
			WHERE IDFORT = @IDFORT
		END

		INSERT INTO HEADERFORTOTIKIS (IDFORT, PARASTATIKOFORT, SEIRAFORT, NOPARASTFORT, ENTOLEASDESCR, PARALISPTISDESCR
		, APOSTOLEASDESCR, KOMISTRA, DIKAIOMAFORTOTIKIS, OTHERXREOSIS, SYSKEVASIA
		, ASFALISTRA, KATHARO, TAXIS, SUMPOSOXRFORT, ERGATIKA, XREOSISTRITON
		, OLIKOSYNOLOXREOSEONFORT, BAROSFORT, KYBIKAFORT, POSOFORT, TEMAXIAFORT)
			VALUES (@IDFORT, @PARASTATIKOFORT, @SEIRAFORT, @NOPARASTFORT, @ENTOLEASDESCR, @PARALISPTISDESCR, @APOSTOLEASDESCR, @KOMISTRA, @DIKAIOMAFORTOTIKIS, @OTHERXREOSIS, @SYSKEVASIA, @ASFALISTRA, @KATHARO, @TAXIS, @SUMPOSOXRFORT, @ERGATIKA, @XREOSISTRITON, @OLIKOSYNOLOXREOSEONFORT, @BAROSFORT, @KYBIKAFORT, @POSOFORT, @TEMAXIAFORT)
		COMMIT TRANSACTION
		;

		DELETE FROM TEMAXIAFORTOTIKIS
		WHERE IDFORTOTIKIS = @IDFORT;

		DECLARE @POUTSBLOU INT = CONVERT(INT, @IDFORT);

		EXEC CREATE_BARCODE_TEMAXION_FORTOTIKIS @IDFORT = @POUTSBLOU;

	END TRY

	BEGIN CATCH
		SET @ErrorMessage = ERROR_MESSAGE()
		SET @ErrorSeverity = ERROR_SEVERITY()
		SET @ErrorState = ERROR_STATE()
		RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState)

	--BREAK
	END CATCH
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[SAVEHEADERPROFORTOTIKIS] (@IDFORT NUMERIC(18, 0) = NULL,
@PARASTATIKOFORT NVARCHAR(100) = NULL,
@SEIRAFORT NVARCHAR(10) = NULL,
@NOPARASTFORT NVARCHAR(20) = NULL,
@ENTOLEASDESCR NVARCHAR(50) = NULL,
@PARALISPTISDESCR NVARCHAR(50) = NULL,
@APOSTOLEASDESCR NVARCHAR(50) = NULL,
@KOMISTRA NUMERIC(18, 3) = NULL,
@DIKAIOMAFORTOTIKIS NUMERIC(18, 3) = NULL,
@OTHERXREOSIS NUMERIC(18, 3) = NULL,
@SYSKEVASIA NVARCHAR(30) = NULL,
@ASFALISTRA NUMERIC(18, 3) = NULL,
@KATHARO NUMERIC(18, 3) = NULL,
@TAXIS NUMERIC(18, 3) = NULL,
@SUMPOSOXRFORT NUMERIC(18, 3) = NULL,
@ERGATIKA NUMERIC(18, 3) = NULL,
@XREOSISTRITON NUMERIC(18, 3) = NULL,
@OLIKOSYNOLOXREOSEONFORT NUMERIC(18, 3) = NULL,
@BAROSFORT NUMERIC(18, 3) = NULL,
@KYBIKAFORT NUMERIC(18, 3) = NULL,
@POSOFORT NUMERIC(18, 3) = NULL,
@TEMAXIAFORT NUMERIC(18, 0) = NULL)
AS
	DECLARE @ErrorMessage VARCHAR(2000)
				 ,@ErrorSeverity TINYINT
				 ,@ErrorState TINYINT

	BEGIN TRY

		SET NOCOUNT ON;
		DECLARE @RC INT


		BEGIN TRANSACTION
		IF EXISTS (SELECT
					1
				FROM HEADERPROFORTOTIKIS
				WHERE IDPROFORT = @IDFORT)--LTRIM(RTRIM(@TheID)))
		BEGIN
			DELETE FROM HEADERPROFORTOTIKIS
			WHERE IDPROFORT = @IDFORT
		END

		INSERT INTO HEADERPROFORTOTIKIS (IDPROFORT, PARASTATIKOPROFORT, SEIRAPROFORT, NOPARASTPROFORT, ENTOLEASDESCR, PARALISPTISDESCR
		, APOSTOLEASDESCR, KOMISTRA, DIKAIOMAFORTOTIKIS, OTHERXREOSIS, SYSKEVASIA
		, ASFALISTRA, KATHARO, TAXIS, SUMPOSOXRPROFORT, ERGATIKA, XREOSISTRITON
		, OLIKOSYNOLOXREOSEONPROFORT, BAROSPROFORT, KYBIKAPROFORT, POSOPROFORT, TEMAXIAPROFORT)
			VALUES (@IDFORT, @PARASTATIKOFORT, @SEIRAFORT, @NOPARASTFORT, @ENTOLEASDESCR, @PARALISPTISDESCR, @APOSTOLEASDESCR, @KOMISTRA, @DIKAIOMAFORTOTIKIS, @OTHERXREOSIS, @SYSKEVASIA, @ASFALISTRA, @KATHARO, @TAXIS, @SUMPOSOXRFORT, @ERGATIKA, @XREOSISTRITON, @OLIKOSYNOLOXREOSEONFORT, @BAROSFORT, @KYBIKAFORT, @POSOFORT, @TEMAXIAFORT)
		COMMIT TRANSACTION
		;

		DELETE FROM TEMAXIAPROFORTOTIKIS
		WHERE ID = @IDFORT;

		EXEC CREATE_BARCODE_TEMAXION_PROFORTOTIKIS @IDPROFORT = @IDFORT;

	END TRY

	BEGIN CATCH
		SET @ErrorMessage = ERROR_MESSAGE()
		SET @ErrorSeverity = ERROR_SEVERITY()
		SET @ErrorState = ERROR_STATE()
		RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState)

	--BREAK
	END CATCH
GO


SET ANSI_NULLS ON
GO
