@OXIMA NVARCHAR(60) = NULL,
@IDKINDPAYMENT NUMERIC(8, 0) = 0,
@KINDPAYMENTDESCR NVARCHAR(50) = NULL,
@AITIOLOGIAPARASTATIKOU NVARCHAR(50) = NULL,
@DATEFORTOSIS SMALLDATETIME = NULL,
@NOPARASTDELTIOUAPOSTOLIS NVARCHAR(50) = NULL,
@NOPARASTDELTIOUDIANOMIS NVARCHAR(50) = NULL,
@IFEPISTROFI INT = 0,
@DATEEPISTROFIS SMALLDATETIME = NULL,
@AITIOLOGIAEPISTROFIS NVARCHAR(50) = NULL,
@IDDRIVER NUMERIC(18, 0) = NULL,
@DRIVERDESCR NVARCHAR(60) = NULL,
@IFCASH INT = 0,
@IFPISTOSI INT = 0,
@IFPREPAY INT = 0,
@IFOFEILOMENI INT = 0,
@IDPRAKTOREIO NUMERIC(8, 0) = NULL,
@PRAKTOREIODESCR NVARCHAR(50) = NULL,
@YPAITIOS INT = 0, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
@IFEPANADROMOLOGISI INT = 0,
@IFEPANEKDOSI INT = 0,
@IFOKEPANADROMOLOGISI INT = 0,
@NOPARASTANTIK NVARCHAR(50) = NULL,
@IFEXOFLISI INT = 0,
@STATUS INT = 0,
@STATUSDESCR NVARCHAR(50) = NULL,
@AFMXREOUMENOU NVARCHAR(10) = NULL,
@DATEPARAL SMALLDATETIME = NULL,
@DATEPARAD SMALLDATETIME = NULL,
@COMMENTSPARAD NVARCHAR(MAX) = NULL,
@COMMANTSPARAL NVARCHAR(MAX) = NULL,
@COMMENTSAKIROSIS NVARCHAR(MAX) = NULL,
@COMMENTSEPISTROFIS NVARCHAR(MAX) = NULL,
@COMMENTS NVARCHAR(MAX) = NULL,
@COMMENTSANTIK NVARCHAR(MAX) = NULL,
@COMMENTS2 NVARCHAR(MAX) = NULL,
@TIMEPARALFROM NVARCHAR(5) = NULL,
@TIMEPARALTO NVARCHAR(5) = NULL,
@TIMEPARADFROM NVARCHAR(5) = NULL,
@TIMEPARADTO NVARCHAR(5) = NULL,
@ANAMEXODO NUMERIC(18, 2) = 0,
@AFMAPOSTOLEA NVARCHAR(10) = NULL,
@AFMENTOLEA NVARCHAR(10) = NULL,
@AFMPARALIPTI NVARCHAR(10) = NULL,
@AFMTRITOU NVARCHAR(10) = NULL,
@NOLISTASDIANOMIS NVARCHAR(10) = NULL,
@IFAUTONUMBER INT = 0,
@IFPARADOSITOPEL INT = 0,
@IFPARALABIFROMPEL INT = 0,
@AFMANTAPOKRITI NVARCHAR(10) = NULL,
@IDXRHSHS NUMERIC(18, 0) = 0,
@IDCOMPANY NUMERIC(18, 0) = 0,
@IDYPOKATASTIMA NUMERIC(18, 0) = 0,
@DateCreate DATETIME,-- = NULL,
@UserCreate NVARCHAR(50),
@CONTAINER NVARCHAR(50) = NULL,
@BOAT NVARCHAR(50) = NULL,
@IFASFALISTRA INT = 0,
@ASFALISTRAPERCENT NUMERIC(18, 0) = 0,
@UntRatio FLOAT = 0,
@IDWAREHOUSE NUMERIC(18, 0) = NULL,
@IF_PRODROMOL INT = 0,
@NO_EXT_ORDER NVARCHAR(50) = NULL,
@OROFOS NUMERIC(3, 2) = 0.00,
@OROFOSDESCR NVARCHAR(100) = NULL,
@KOUDOUNI NVARCHAR(100) = NULL,
@EXT_BARCODE NVARCHAR(150) = NULL,
@TheID NUMERIC(18, 0) = NULL OUTPUT)
AS

	SET NOCOUNT ON;

	DECLARE @RC INT
	BEGIN TRAN
	EXEC @RC = sp_getapplock @Resource = 'InserttoPROFORTOTIKES'
													,@LockMode = 'Exclusive'
													,@LockOwner = 'Transaction'
													,@LockTimeout = 1000
	--SELECT @@SPID [session_id], @RC [return code], GETDATE()


	DECLARE @NEWNOPARAST NUMERIC(18, 2) = 0
	--GO

	IF @IFAUTONUMBER = 1
	BEGIN
		IF LEN(@SEIRA) > 0
		BEGIN
			IF EXISTS (SELECT
						(ISNULL(CAST(NOPARAST AS INT), 0))
					FROM PROFORTOTIKES
					WHERE SEIRA = @SEIRA
					AND IDPARAST = @IDPARAST)
			BEGIN
				SELECT
					@NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS INT) + 1, 0)), 0)
				FROM PROFORTOTIKES
				WHERE SEIRA = @SEIRA
				AND IDPARAST = @IDPARAST
				SET @NOPARAST = REPLACE(@NEWNOPARAST, '.00', '')
			END
			ELSE
			BEGIN
				SET @NOPARAST = 1
			END
		--SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
		--SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
		ELSE
		BEGIN
			IF EXISTS (SELECT
						(ISNULL(CAST(NOPARAST AS INT), 0))
					FROM PROFORTOTIKES
					WHERE ((SEIRA = '')
					OR (SEIRA IS NULL))
					AND IDPARAST = @IDPARAST)
			BEGIN
				SELECT
					@NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS INT) + 1, 0)), 0)
				FROM PROFORTOTIKES
				WHERE ((SEIRA = '')
				OR (SEIRA IS NULL))
				AND IDPARAST = @IDPARAST
				SET @NOPARAST = REPLACE(@NEWNOPARAST, '.00', '')
			END
			ELSE
			BEGIN
				SET @NOPARAST = 1
			END
		--SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int)+1, 0)),0)  FROM FORTOTIKES WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
		--SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
		UPDATE KINDPARASTATIKON
		SET AUTONUMBER_FROM = (@NOPARAST + 1)
		WHERE ID = @IDPARAST;
	END;

	IF (LEN(@NO_EXT_ORDER) < 1)
	BEGIN
		SELECT
			@NO_EXT_ORDER = @SEIRA + @NOPARAST;
	END
	--GO
	INSERT INTO PROFORTOTIKES (SEIRA,
	NOPARAST,
	IDPARAST,
	PARASTATIKO,
	IFXRAPOST,
	IFXRPARAL,
	IFXRENTOL,
	IFXRTRITOU,
	IDAPOSTOLEA,
	APOSTOLEASDESCR,
	IDPARALIPTI,
	PARALISPTISDESCR,
	IDENTOLEA,
	ENTOLEASDESCR,
	IDTRITOU,
	TRITOSDESCR,
	IDANTAPOKRITI,
	ANTAPOKRITISDESCR,
	IDXREOUMENOU,
	DATEPRINT,
	POSO,
	TAXISPERCENT,
	TAXIS,
	SUMPOSO,
	IFANTIKCASH,
	IFANTIKEPIT,
	IFANTIKSYNAL,
	IFANTIKOTHER,
	ANTIKCASH,
	ANTIKEPIT,
	ANTIKSYNAL,
	ANTIKOTHER,
	SUMANTIK,
	EXODATRITON,
	IFCANCELANTIK,
	DATECANCELANTIK,
	COMMENTSANTIK,
	IFPARADOSI,
	DATEPARADOSI,
	IFCANCEL,
	DATECANCEL,
	PERIOXIFORTOSIS,
	PERIOXIPARADOSIS,
	OMADPROORISMOS,
	OXIMA,
	IDKINDPAYMENT,
	KINDPAYMENTDESCR,
	AITIOLOGIAPARASTATIKOU,
	DATEFORTOSIS,
	NOPARASTDELTIOUAPOSTOLIS,
	NOPARASTDELTIOUDIANOMIS,
	IFEPISTROFI,
	DATEEPISTROFIS,
	AITIOLOGIAEPISTROFIS,
	COMMENTSEPISTROFIS,
	COMMENTS,
	COMMENTS2,
	IFCASH,
	IFPISTOSI,
	IFPREPAY,
	IFOFEILOMENI,
	IDPRAKTOREIO,
	PRAKTOREIODESCR,
	YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
	IFEPANADROMOLOGISI,
	IFEPANEKDOSI,
	IFOKEPANADROMOLOGISI,
	NOPARASTANTIK,
	COMMENTSAKIROSIS,
	STATUSDESCR,
	IDDRIVER,
	DRIVERDESCR,
	IFEXOFLISI,
	STATUS,
	DATEPARAL,
	DATEPARAD,
	COMMENTSPARAD,
	COMMANTSPARAL,
	TIMEPARALFROM,
	TIMEPARALTO,
	TIMEPARADFROM,
	TIMEPARADTO,
	ANAMEXODO,
	AFMAPOSTOLEA,
	AFMENTOLEA,
	AFMPARALIPTI,
	AFMTRITOU,
	AFMANTAPOKRITI,
	AFMXREOUMENOU,
	IFPARADOSITOPEL,
	IFPARALABIFROMPEL,
	NOLISTASDIANOMIS,
	AA_ANTIK,
	CONTAINER,
	BOAT,
	IDXRHSHS,
	IDCOMPANY,
	IDYPOKATASTIMA,
	IDWAREHOUSE,
	UntRatio,
	IF_PRODROMOL,
	IFASFALISTRA,
	ASFALISTRAPERCENT,
	NO_EXT_ORDER,
	OROFOS,
	EXT_BARCODE,
	OROFOSDESCR,
	KOUDOUNI,
	DateCreate,
	UserCreate)
		VALUES (@SEIRA, @NOPARAST, @IDPARAST, @PARASTATIKO, @IFXRAPOST, @IFXRPARAL, @IFXRENTOL, @IFXRTRITOU, @IDAPOSTOLEA, @APOSTOLEASDESCR, @IDPARALIPTI, @PARALISPTISDESCR, @IDENTOLEA, @ENTOLEASDESCR, @IDTRITOU, @TRITOSDESCR, @IDANTAPOKRITI, @ANTAPOKRITISDESCR, @IDXREOUMENOU, @DATEPRINT, @POSO, @TAXISPERCENT, @TAXIS, @SUMPOSO, @IFANTIKCASH, @IFANTIKEPIT, @IFANTIKSYNAL, @IFANTIKOTHER, @ANTIKCASH, @ANTIKEPIT, @ANTIKSYNAL, @ANTIKOTHER, @SUMANTIK, @EXODATRITON, @IFCANCELANTIK, @DATECANCELANTIK, @COMMENTSANTIK, @IFPARADOSI, @DATEPARADOSI, @IFCANCEL, @DATECANCEL, @PERIOXIFORTOSIS, @PERIOXIPARADOSIS, @OMADPROORISMOS, @OXIMA, @IDKINDPAYMENT, @KINDPAYMENTDESCR, @AITIOLOGIAPARASTATIKOU, @DATEFORTOSIS, @NOPARASTDELTIOUAPOSTOLIS, @NOPARASTDELTIOUDIANOMIS, @IFEPISTROFI, @DATEEPISTROFIS, @AITIOLOGIAEPISTROFIS, @COMMENTSEPISTROFIS, @COMMENTS, @COMMENTS2, @IFCASH, @IFPISTOSI, @IFPREPAY, @IFOFEILOMENI, @IDPRAKTOREIO, @PRAKTOREIODESCR, @YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
		@IFEPANADROMOLOGISI, @IFEPANEKDOSI, @IFOKEPANADROMOLOGISI, @NOPARASTANTIK, @COMMENTSAKIROSIS, @STATUSDESCR, @IDDRIVER, @DRIVERDESCR, @IFEXOFLISI, @STATUS, @DATEPARAL, @DATEPARAD, @COMMENTSPARAD, @COMMANTSPARAL, @TIMEPARALFROM, @TIMEPARALTO, @TIMEPARADFROM, @TIMEPARADTO, @ANAMEXODO, @AFMAPOSTOLEA, @AFMENTOLEA, @AFMPARALIPTI, @AFMTRITOU, @AFMANTAPOKRITI, @AFMXREOUMENOU, @IFPARADOSITOPEL, @IFPARALABIFROMPEL, @NOLISTASDIANOMIS, @AA_ANTIK, @CONTAINER, @BOAT, @IDXRHSHS, @IDCOMPANY, @IDYPOKATASTIMA, @IDWAREHOUSE, @UntRatio, @IF_PRODROMOL, @IFASFALISTRA, @ASFALISTRAPERCENT, @NO_EXT_ORDER, @OROFOS, @EXT_BARCODE, @OROFOSDESCR, @KOUDOUNI, @DateCreate, @UserCreate)

	SELECT
		@TheID = MAX(ID)
	FROM dbo.PROFORTOTIKES WITH (NOLOCK)

	IF LEN(ISNULL(@EXT_BARCODE, '')) = 0
	BEGIN
		UPDATE p
		SET EXT_BARCODE = c.BARCODE_Prefix + '0' + CONVERT(VARCHAR, p.ID)
		FROM PROFORTOTIKES p
		JOIN COMPANIES c ON c.ID = p.IDYPOKATASTIMA
		WHERE p.ID = @TheID
	END

	WAITFOR DELAY '00:00:00:40'
	COMMIT;
GO


