ALTER PROCEDURE [dbo].[SAVEHEADERPROFORTOTIKIS] (@IDFORT NUMERIC(18, 0) = NULL,
@PARASTATIKOFORT NVARCHAR(100) = NULL,
@SEIRAFORT NVARCHAR(10) = NULL,
@NOPARASTFORT NVARCHAR(20) = NULL,
@ENTOLEASDESCR NVARCHAR(50) = NULL,
@PARALISPTISDESCR NVARCHAR(50) = NULL,
@APOSTOLEASDESCR NVARCHAR(50) = NULL,
@KOMISTRA NUMERIC(18, 3) = NULL,
@DIKAIOMAFORTOTIKIS NUMERIC(18, 3) = NULL,
@OTHERXREOSIS NUMERIC(18, 3) = NULL,
@SYSKEVASIA NVARCHAR(30) = NULL,
@ASFALISTRA NUMERIC(18, 3) = NULL,
@KATHARO NUMERIC(18, 3) = NULL,
@TAXIS NUMERIC(18, 3) = NULL,
@SUMPOSOXRFORT NUMERIC(18, 3) = NULL,
@ERGATIKA NUMERIC(18, 3) = NULL,
@XREOSISTRITON NUMERIC(18, 3) = NULL,
@OLIKOSYNOLOXREOSEONFORT NUMERIC(18, 3) = NULL,
@BAROSFORT NUMERIC(18, 3) = NULL,
@KYBIKAFORT NUMERIC(18, 3) = NULL,
@POSOFORT NUMERIC(18, 3) = NULL,
@TEMAXIAFORT NUMERIC(18, 0) = NULL)
AS
	DECLARE @ErrorMessage VARCHAR(2000)
				 ,@ErrorSeverity TINYINT
				 ,@ErrorState TINYINT

	BEGIN TRY

		SET NOCOUNT ON;
		DECLARE @RC INT


		BEGIN TRANSACTION
		IF EXISTS (SELECT
					1
				FROM HEADERPROFORTOTIKIS
				WHERE IDPROFORT = @IDFORT)--LTRIM(RTRIM(@TheID)))
		BEGIN
			DELETE FROM HEADERPROFORTOTIKIS
			WHERE IDPROFORT = @IDFORT
		END

		INSERT INTO HEADERPROFORTOTIKIS (IDPROFORT, PARASTATIKOPROFORT, SEIRAPROFORT, NOPARASTPROFORT, ENTOLEASDESCR, PARALISPTISDESCR
		, APOSTOLEASDESCR, KOMISTRA, DIKAIOMAFORTOTIKIS, OTHERXREOSIS, SYSKEVASIA
		, ASFALISTRA, KATHARO, TAXIS, SUMPOSOXRPROFORT, ERGATIKA, XREOSISTRITON
		, OLIKOSYNOLOXREOSEONPROFORT, BAROSPROFORT, KYBIKAPROFORT, POSOPROFORT, TEMAXIAPROFORT)
			VALUES (@IDFORT, @PARASTATIKOFORT, @SEIRAFORT, @NOPARASTFORT, @ENTOLEASDESCR, @PARALISPTISDESCR, @APOSTOLEASDESCR, @KOMISTRA, @DIKAIOMAFORTOTIKIS, @OTHERXREOSIS, @SYSKEVASIA, @ASFALISTRA, @KATHARO, @TAXIS, @SUMPOSOXRFORT, @ERGATIKA, @XREOSISTRITON, @OLIKOSYNOLOXREOSEONFORT, @BAROSFORT, @KYBIKAFORT, @POSOFORT, @TEMAXIAFORT)
		COMMIT TRANSACTION
		;

		DELETE FROM TEMAXIAPROFORTOTIKIS
		WHERE IDPROFORTOTIKIS = @IDFORT;

		EXEC CREATE_BARCODE_TEMAXION_PROFORTOTIKIS @IDPROFORT = @IDFORT;

	END TRY

	BEGIN CATCH
		SET @ErrorMessage = ERROR_MESSAGE()
		SET @ErrorSeverity = ERROR_SEVERITY()
		SET @ErrorState = ERROR_STATE()
		RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState)

	--BREAK
	END CATCH

	GO

---END SCRIPT 1667
------------------------------------------------------------------------------------

