CREATE VIEW EXPORT_EISPRAXEIS_PLIROMES
AS

SELECT 
	k.ID [KID],
	a.id [ACID],	
	r.DATEPRINT [Ημερομηνία],
	r.DOCNO [Αρ.Παρ.],
	a.AFM [ΑΦΜ],
	a.Eponimia [Συναλλασόμενος],
	r.EISPRAXAS [Εισπράξας],
	r.AITIOLOGIA [Αιτιολογία],
	r.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	k.Descr [Παραστατικό],
	r.SUMPOSO [Ποσό]
	
from RECEIPTS r
JOIN ACCOUNTS a ON a.id=r.IDCUSTOMER
JOIN KINDPARASTATIKON k ON k.ID=r.IDKINDPARAST AND k.KindKINISIS=3
WHERE ISNULL(r.ifDelete,0)=0

UNION

SELECT 
	k.ID [KID],
	a.id [ACID],
	p.DATEPRINT [Ημερομηνία],
	p.DOCNO [Αρ.Παρ.],
	a.AFM [ΑΦΜ],
	a.Eponimia [Συναλλασόμενος],
	p.EISPRAXAS [Εισπράξας],
	p.AITIOLOGIA [Αιτιολογία],
	p.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	k.Descr [Παραστατικό],
	p.SUMPOSO [Ποσό]
	
from PAYMENTS p
JOIN ACCOUNTS a ON a.id=p.IDCUSTOMER
JOIN KINDPARASTATIKON k ON k.ID=p.IDKINDPARAST AND k.KindKINISIS=2
WHERE ISNULL(p.ifDelete,0)=0

GO
---END SCRIPT 1675
