ALTER PROCEDURE [dbo].[updateFORT_ANA_LISTA]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDLISTAS				NUMERIC(18, 0)= NULL,
	@NoPARASTKAA			NVARCHAR(10)= NULL, 
	@OXIMA					NVARCHAR(60)= NULL,
	@INSERTFORTOTIKES		NVARCHAR(MAX)= NULL,
	@DELETEDFORTOTIKES		NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON
DECLARE @_STATUS varchar(75)
DECLARE @_STATUSID int
--SET @_STATUS = 'ΣΕ ΛΙΣΤΑ ΔΙΑΝΟΜΗΣ'

--SELECT @_STATUS = STATUS, @_STATUSID = IDSTATUS FROM LISTESDIANOMIS WHERE ID = @IDLISTAS


--IF LEN(@_STATUS) < 3
--BEGIN
--	SELECT TOP 1 @_STATUS = DESCR, @_STATUSID = ID FROM DOC_STATUS WHERE IFSELISTA = 1 
--END



	DECLARE @_DRIVERID INT
	DECLARE @_DRIVERDESCR NVARCHAR(50)


	SELECT
		@_STATUS = STATUS
	 ,@_STATUSID = IDSTATUS
	 ,@_DRIVERID = isnull(ODIGOI.ID,0)
	 ,@_DRIVERDESCR = isnull(LISTESDIANOMIS.DRIVER,'')

	FROM LISTESDIANOMIS
	LEFT JOIN ODIGOI ON ODIGOI.LastName + ' ' + ODIGOI.FirstName = LISTESDIANOMIS.DRIVER
	WHERE LISTESDIANOMIS.ID = @IDLISTAS


	IF LEN(@_STATUS) < 3
	BEGIN
		SELECT TOP 1
			@_STATUS = DESCR
		 ,@_STATUSID = ID
		FROM DOC_STATUS
		WHERE IFSELISTA = 1
	END








DECLARE @_NULL varchar(75)
SET @_NULL = ''

EXEC('DELETE FROM FORTOTIKES_ANA_LISTA WHERE  IDLISTAS = ' + @IDLISTAS)
IF LEN(@DELETEDFORTOTIKES)>0
BEGIN
	EXEC('UPDATE FORTOTIKES SET NOLISTASDIANOMIS ='''+@_NULL+''' WHERE ID IN(' + @DELETEDFORTOTIKES + ')')
END
--EXEC('DELETE FROM dbo.FORTOTIKES_ANA_KAA WHERE IDFORTOTIKIS IN(' + @DELETEDFORTOTIKES + ') AND IDKAA = '+@IDKAA)
--EXEC('UPDATE FORTOTIKES SET NOLISTASDIANOMIS ='''+@NoPARASTKAA +''', OXIMA ='''+	@OXIMA + ''', STATUS = ''' + @_STATUSID + ''', STATUSDESCR = '''+@_STATUS+''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')
EXEC ('UPDATE FORTOTIKES SET NOLISTASDIANOMIS =''' + @NoPARASTKAA + ''', OXIMA =''' + @OXIMA + ''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = ''' + @_STATUS + ''', IDDRIVER = ''' + @_DRIVERID + ''' , DRIVERDESCR = ''' + @_DRIVERDESCR + ''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')

declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @INSERTFORTOTIKES) 
    WHILE @start < LEN(@INSERTFORTOTIKES) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@INSERTFORTOTIKES) + 1
       
        INSERT INTO FORTOTIKES_ANA_LISTA (IDLISTAS, IDFORTOTIKIS)  
        VALUES(@IDLISTAS, CAST( SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start)AS NUMERIC)) 
        SET @start = @end + 1 
        SET @end = CHARINDEX(@coma, @INSERTFORTOTIKES, @start)
        
    END 
   
END

GO

---END SCRIPT 1679
------------------------------------------------------------------------------------

