ALTER VIEW [dbo].[FORTOTIKESLIGHT_VIEW]
AS


WITH GRAMMES AS (
	SELECT 
		IDVOH,
		MIN(TIMDA) AS TIMDA,
		ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
		MIN(U.UntName) AS SYSKEVASIADESCR,
		MIN(PERIEXOMENO) AS PERIEXOMENO,
		ISNULL(SUM(BAROS),0) AS BAROS,
		ISNULL(SUM(KYBIKA),0) AS KYBIKA,
		ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
	FROM GRAMMESFORTTIKIS
	LEFT JOIN Units U ON U.UntID=GRAMMESFORTTIKIS.SYSKEVASIA
	GROUP BY IDVOH
),
POSA AS (
	SELECT 
		ID,
		SUMPOSO,
		ROUND(FORTOTIKES.POSO, 2) AS KATHARO,
		ROUND(FORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
		ROUND(FORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT
	FROM FORTOTIKES
),
pivoted as (
	select
		IDVOH AS FORTID,[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
	from 
		(
			select
				idvoh,
				case 
					when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
					when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
					when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
					when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
					when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
					when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
					ELSE 'KOLA'
				END AS SYSKEVASIA,
				TEMAXIA
			FROM  GRAMMESFORTTIKIS
		)AS GF
	PIVOT
	(
		SUM(TEMAXIA)
		FOR SYSKEVASIA IN ([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
	) AS PV
	
)


select 
	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	CAST(f.noparast as int) as NOPARAST,
	F.NOPARASTDELTIOUDIANOMIS,
	F.NOPARASTDELTIOUAPOSTOLIS,
	F.OXIMA,
	F.DRIVERDESCR,
	F.OMADPROORISMOS,

	CASE 
		ISNULL(IFXRENTOL, 0) * 1
		+ ISNULL(IFXRAPOST, 0) * 2
		+ ISNULL(IFXRTRITOU, 0) * 4
		+ ISNULL(IFXRPARAL, 0) * 8

		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'

		ELSE 'ΑΓΝΩΣΤΟΣ'
	END XREOYMENOS,
    APOST.Eponimia AS APOSTOLEASDESCR,
    PARAL.Eponimia AS PARALISPTISDESCR,
    ENTOL.Eponimia AS ENTOLEASDESCR,
    F.ANTAPOKRITISDESCR,
    f.NOLISTASDIANOMIS,
    CONVERT(VARCHAR,LD.DATEPRINT,103) [DATE_LISTAS_DIANOMIS],
    TRITOS.Eponimia AS TRITOSDESCR,
    HD.DESCRCATALOG AS TIMOKATALOGOS,
    GRAMMES.TIMDA AS TIMDA,
    ISNULL(f.POSO,0) AS POSO,
    ISNULL(POSA.TAXISXREOSEON,0) AS TAXISXREOSEON,
    ISNULL(POSA.SUMPOSOXRFORT,0) AS SUMPOSOXRFORT,
    ISNULL(f.TAXIS,0) AS TAXIS,
    ISNULL(F.SUMPOSO,0) AS SUMPOSO,
    ISNULL(GRAMMES.TEMAXIA,0) AS TEMAXIA,
    ISNULL(GRAMMES.BAROS,0) AS BAROS,
    ISNULL(GRAMMES.KYBIKA,0) AS KYBIKA,
    GRAMMES.SYSKEVASIADESCR AS SYSKEVASIA,
    CASE F.IFPREPAY 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0) 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE F.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFCASH 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFPISTOSI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GRAMMES.PERIEXOMENO,
    F.PERIOXIFORTOSIS,
    F.PERIOXIPARADOSIS,
    F.COMMENTS,
    ISNULL(F.SUMANTIK,0) AS SUMANTIK,
    F.PRAKTOREIODESCR,
    F.STATUS,
    F.DATEPARAD,
    F.IDAPOSTOLEA,
    F.IDPARALIPTI,
    F.IDENTOLEA,
    F.IDANTAPOKRITI,
    F.IDTRITOU,
    F.IDPRAKTOREIO,
	F.ANTIKCASH,
	F.ANTIKEPIT,
	F.ANTIKSYNAL,
	F.ANTIKOTHER,

    CASE F.IFCANCELANTIK 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFCANCELANTIK,
    F.COMMENTSANTIK,
    F.DATEPARADOSI,
    F.COMMENTS2,
    ISNULL(F.EXODATRITON,0) AS XREOSISTRITON,
    CASE F.IFPREPAY 
        WHEN 1 THEN 'ΝΑΙ' 
        ELSE 'ΟΧΙ' 
    END AS IFPREPAY,
    F.NO_EXT_ORDER,
    CASE f.IFOFEILOMENI 
        WHEN 1 THEN 'ΝΑΙ' 
        ELSE 'ΟΧΙ' 
    END AS IFOFEILOMENI,
    ISNULL(GRAMMES.SUMPOSO,0) AS AXIA,
    CASE IFXRENTOL 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRENTOL,
    F.KINDPAYMENTDESCR,
    F.IDKINDPAYMENT,
    CASE IFXRAPOST 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRAPOST,
    CASE IFXRPARAL 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRPARAL,
    CASE IFXRTRITOU 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRTRITOU,
    F.IFANTIKCASH,
    F.IFANTIKEPIT,
    F.IFANTIKSYNAL,
    F.IFANTIKOTHER,
    F.ifDelete,
    F.IFCANCEL,
    F.DATECANCEL,
    F.DROMOLOGIO,
    F.THESI,
    F.IFPARADOSI,
    F.AITIOLOGIAPARASTATIKOU,
    CONVERT(varchar,F.DATEFORTOSIS,102) AS DATEFORTOSIS,
    F.IFEPISTROFI,
    F.DATEEPISTROFIS,
    F.AITIOLOGIAEPISTROFIS,
    F.COMMENTSEPISTROFIS,
    F.IFCASH,
    F.IFPISTOSI,
    F.STATUSDESCR,
    F.YPAITIOS,
    F.IFEPANADROMOLOGISI,
    F.IFEPANEKDOSI,
    F.IFOKEPANADROMOLOGISI,
    F.NOPARASTANTIK,
    F.COMMENTSAKIROSIS,
    F.IFEISPRANTIK,
    F.IFPARADOSIANTIK,
    F.IFPARALAVIANTIK,
    F.COMMENTSPARADANTIK,
    F.COMMANTSPARALANTIK,
    F.COMMENTSEISPRANTIK,
    CONVERT(varchar,F.DATEPARADANTIK,102) AS DATEPARADANTIK,
    CONVERT(varchar,F.DATEPARALANTIK,102) AS DATEPARALANTIK,
    CONVERT(varchar, F.DATEEISPRANTIK,102) AS DATEEISPRANTIK,
    F.EISPRAXASANTIK,
    F.NOPARPARADANTIK,
    F.NOPARASTEISPRANTIK,
    F.NOPARPARALANTIK,
    F.DATEPARAL,
    F.COMMENTSPARAD,
    F.COMMANTSPARAL,
    F.TIMEPARALFROM,
    F.TIMEPARALTO,
    F.TIMEPARADFROM,
    F.TIMEPARADTO,
    CONVERT(varchar,F.DATECANCELANTIK,102) AS DATECANCELANTIK,
    F.IDPARAST,
    ISNULL(F.TAXISPERCENT,0) AS TAXISPERCENT,
    ISNULL(F.ANAMEXODO,0) AS ANAMEXODO,
    F.ID AS IDFORTOTIKIS,
    F.AFMXREOUMENOU,
    ISNULL(posa.KATHARO,0) AS KATHARO,
    apost.Epagelma AS EPAGAPOST,
    apost.AddressStr AS ADDRSTRAPOST,
    apost.AddressNo AS ADDRNOAPOST,
    apost.AddressTK AS TKAPOST,
    apost.AddressCity AS CITYAPOST,
    apost.AddressPref AS NOMOSAPOST,
    apost.Tel AS TELAPOST,
    apost.DOY AS DOYAPOST,
    PARAL.Epagelma AS EPAGPARAL,
    PARAL.AddressStr AS ADDRSTRPARAL,
    PARAL.AddressNo AS ADDRNOPARAL,
    PARAL.AddressTK AS ADDRTKPARAL,
    PARAL.AddressCity AS ADDRCITYPARAL,
    PARAL.AddressPref AS ADDRNOMOSPARAL,
    PARAL.Tel AS TELPARAL,
    PARAL.DOY AS DOYPARAL,
    ENTOL.Epagelma AS EPAGENTOL,
    ENTOL.AddressStr AS ADDRSTRENTOL,
    ENTOL.AddressNo AS ADDRNOENTOL,
    ENTOL.AddressTK AS ADDRTKENTOL,
    ENTOL.AddressCity AS ADDRCITYENTOL,
    ENTOL.AddressPref AS ADDRNOMOSENTOL,
    ENTOL.Tel AS TELENTOL,
    ENTOL.DOY AS DOYENTOL,
    TRITOS.Epagelma AS EPAGTR,
    TRITOS.AddressStr AS ADDRSTTR,
    TRITOS.AddressNo AS ADDRNOTR,
    TRITOS.AddressTK AS ADDRTKTR,
    TRITOS.AddressCity AS ADDRCITYTR,
    TRITOS.AddressPref AS ADSTRDRNOMO,
    TRITOS.Tel AS TELTR,
    TRITOS.DOY AS DOYTR,
    F.AFMAPOSTOLEA,
    F.AFMENTOLEA,
    F.IF_TRANSFTOESEX,
    F.AFMPARALIPTI,
    F.AFMTRITOU,
    F.AFMANTAPOKRITI,
    F.IFPARADOSITOPEL,
    F.IFPARALABIFROMPEL,
    F.IDXRHSHS,
    F.IDCOMPANY,
    F.IFEXOFLISI,
    F.IDYPOKATASTIMA,
    F.UserMod,
    F.DateMod,
    F.CONTAINER,
    F.BOAT,
    F.POD_ADDED,
    F.IDKENTROUKOSTOUS,
    F.NO_EXT_ORDER_IK,
    F.IDENTOLIS,
    F.IF_CANCEL,
    F.ID_CANCELLATION,
    F.SEIRA_CANCELLATION,
    F.NOPARAST_CANCELLATION,
    F.DETAILS_CANCELLATION,
    F.CANCELDATE,
    F.EXT_BARCODE,
    F.POD_PATH,
    F.POD_USER,
    F.POD_PATH_2,
    F.UserCreate,
    F.DateCreate,
    F.IF_FROM_ANTAP,
    F.IF_TO_ANTAP,
	F.ARRIVAL,
	f.ARANAFORAS,
    case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as SYNTHIKI,
    isnull(pivoted.DEMATA,0) as DEMATA,
    isnull(pivoted.PALETA,0) as PALETA,
    isnull(pivoted.KOLA,0) AS KOLA,
    isnull(pivoted.STAND,0) AS STAND,
    isnull(pivoted.ROLI,0) AS ROLI,
    isnull(pivoted.THALAMOS,0) AS THALAMOS
from FORTOTIKES f
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
LEFT JOIN ACCOUNTS APOST ON APOST.id=F.IDAPOSTOLEA
LEFT JOIN ACCOUNTS PARAL ON PARAL.id = F.IDPARALIPTI
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
LEFT JOIN ACCOUNTS TRITOS ON TRITOS.id=F.IDTRITOU
LEFT JOIN MAX_FORTOTIKES_ANA_LISTA FAL ON FAL.IDFORTOTIKIS=F.ID
LEFT JOIN LISTESDIANOMIS LD ON LD.ID=FAL.IDLISTAS
LEFT JOIN dbo.HEADERVOHPRICING HD WITH (NOLOCK) ON HD.IDVOH=F.IDENTOLIS  

LEFT JOIN GRAMMES ON GRAMMES.IDVOH=f.ID
LEFT JOIN POSA ON POSA.ID=f.ID
left join pivoted on pivoted.FORTID=f.id

GO


---END SCRIPT 1682
------------------------------------------------------------------------------------

---NEW SCRIPT 1683
CREATE VIEW FORTOTIKES_WEB_VOUCHER
AS

SELECT 

f.ID,
f.IDAPOSTOLEA,
f.IDPARALIPTI,
f.IDENTOLEA,
f.IDPARAST,
f.PARASTATIKO,
f.STATUS,
f.STATUSDESCR,

f.NO_EXT_ORDER [Αρ.Παραγγελίας],
CASE 
	WHEN ROW_NUMBER()OVER (PARTITION BY F.ID ORDER BY f.ID)>1 
	THEN NULL
	ELSE f.DATEPRINT 
END AS [Ημερομηνία],
gf.TEMAXIA [Ποσότητα],
gf.SYSKEVASIADESCR [Συσκευασία],
gf.PERIEXOMENO [Περιεχόμενο],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY f.ID ORDER BY f.ID)>1 THEN NULL 
	ELSE f.ANTIKCASH 
END AS [Αντικαταβολή Μετρητά],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY F.ID ORDER BY f.ID) > 1 THEN NULL
	ELSE f.ANTIKEPIT 
END AS [Αντικαταβολή Επιταγή],
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY f.ID ORDER BY f.ID)>1 THEN NULL 
	ELSE f.ANTIKSYNAL 
END AS [Αντικαταβολή Συναλ/κη],
f.APOSTOLEASDESCR [Αποστολέας],
f.PARALISPTISDESCR [Παραλήπτης],
f.EXT_BARCODE [Εξωτ.Barcode],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
	ELSE (LTRIM(RTRIM(f.SEIRA))+'-'+f.NOPARAST)
END AS [Αρ.Παραστατικού]

from FORTOTIKES f
left JOIN GRAMMESFORTTIKIS gf ON gf.IDVOH=f.ID 
WHERE ISNULL(f.ifDelete,0)<>1

GO



---END SCRIPT 1683
------------------------------------------------------------------------------------

---NEW SCRIPT 1684

ALTER VIEW [dbo].[PROFORTOTIKES_VIEW]
AS
SELECT     dbo.PROFORTOTIKES.ID, dbo.PROFORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.PROFORTOTIKES.PARASTATIKO, dbo.PROFORTOTIKES.SEIRA, 
                      CAST(dbo.PROFORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.PROFORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.PROFORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, 
                      dbo.PROFORTOTIKES.OMADPROORISMOS, dbo.PROFORTOTIKES.APOSTOLEASDESCR, dbo.PROFORTOTIKES.PARALISPTISDESCR, dbo.PROFORTOTIKES.ENTOLEASDESCR, 
                      dbo.PROFORTOTIKES.COMMENTS, dbo.PROFORTOTIKES.EXODATRITON AS XREOSISTRITON, dbo.PROFORTOTIKES.SUMANTIK, ROUND(dbo.PROFORTOTIKES.POSO, 2) AS POSO, ROUND(dbo.PROFORTOTIKES.TAXIS, 2) AS TAXIS, 
                      ROUND(dbo.HEADERPROFORTOTIKIS.TAXIS, 2) AS TAXISXREOSEON, ROUND(dbo.PROFORTOTIKES.SUMPOSO, 2) AS SUMPOSO, ROUND(dbo.HEADERPROFORTOTIKIS.SUMPOSOXRPROFORT, 2) AS SUMPOSOXRPROFORT, dbo.PROFORTOTIKES.OXIMA, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
                       ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, dbo.PROFORTOTIKES.ANTAPOKRITISDESCR, dbo.PROFORTOTIKES.NOLISTASDIANOMIS, dbo.PROFORTOTIKES.TRITOSDESCR, 
                      dbo.HEADERPROFORTOTIKIS.KATHARO, MIN(dbo.GRAMMESPROFORTTIKIS.TIMDA) AS TIMDA, ISNULL(SUM(dbo.GRAMMESPROFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, 
                      ISNULL(SUM(dbo.GRAMMESPROFORTTIKIS.BAROS), 0) AS BAROS, ISNULL(SUM(dbo.GRAMMESPROFORTTIKIS.KYBIKA), 0) AS KYBIKA, MIN(dbo.Units.UntName) AS SYSKEVASIA, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN
                          (SELECT     ROUND(SUM(SUMPOSO) ,2) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END AS XREOSIPROPLIROMENES, CASE dbo.PROFORTOTIKES.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     ROUND(SUM(SUMPOSO), 2) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.PROFORTOTIKES.IFCASH WHEN 1 THEN
                          (SELECT     ROUND(SUM(SUMPOSO), 2) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.PROFORTOTIKES.IFPISTOSI WHEN 1 THEN
                          (SELECT     ROUND(SUM(SUMPOSO), 2) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, MIN(dbo.GRAMMESPROFORTTIKIS.PERIEXOMENO) 
                      AS PERIEXOMENO, dbo.PROFORTOTIKES.PERIOXIFORTOSIS, dbo.PROFORTOTIKES.PERIOXIPARADOSIS, dbo.PROFORTOTIKES.PRAKTOREIODESCR, dbo.PROFORTOTIKES.STATUS, 
                      CONVERT(varchar, dbo.PROFORTOTIKES.DATEPARAD, 102) AS DATEPARAD, dbo.PROFORTOTIKES.IDAPOSTOLEA, dbo.PROFORTOTIKES.IDPARALIPTI, dbo.PROFORTOTIKES.IDENTOLEA, 
                      dbo.PROFORTOTIKES.IDANTAPOKRITI, dbo.PROFORTOTIKES.IDTRITOU, dbo.PROFORTOTIKES.IDPRAKTOREIO, CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, 
                      CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, 
                      dbo.PROFORTOTIKES.COMMENTSANTIK, dbo.PROFORTOTIKES.DATEPARADOSI, dbo.PROFORTOTIKES.COMMENTS2, MIN(dbo.HEADERPROFORTOTIKIS.KOMISTRA) AS KOMISTRA, 
                      MIN(dbo.HEADERPROFORTOTIKIS.DIKAIOMAFORTOTIKIS) AS DIKAIOMAFORTOTIKIS, MIN(dbo.HEADERPROFORTOTIKIS.OTHERXREOSIS) AS OTHERXREOSIS, 
                      MIN(dbo.HEADERPROFORTOTIKIS.OLIKOSYNOLOXREOSEONPROFORT) AS OLIKOSYNOLOXREOSEONFORT, MIN(dbo.HEADERPROFORTOTIKIS.ERGATIKA) AS ERGATIKA, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, CASE dbo.PROFORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, 
                      ISNULL(SUM(dbo.GRAMMESPROFORTTIKIS.SUMPOSO), 0) AS AXIA, CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.PROFORTOTIKES.KINDPAYMENTDESCR, 
                      dbo.PROFORTOTIKES.IDKINDPAYMENT, CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, 
                      CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, dbo.PROFORTOTIKES.IFANTIKCASH, dbo.PROFORTOTIKES.IFANTIKEPIT, dbo.PROFORTOTIKES.IFANTIKSYNAL, 
                      dbo.PROFORTOTIKES.IFANTIKOTHER, dbo.PROFORTOTIKES.ifDelete, dbo.PROFORTOTIKES.IFCANCEL, CONVERT(varchar, dbo.PROFORTOTIKES.DATECANCEL, 102) AS DATECANCEL, 
                      dbo.PROFORTOTIKES.AA_ANTIK, dbo.PROFORTOTIKES.IFPARADOSI, dbo.PROFORTOTIKES.AITIOLOGIAPARASTATIKOU, CONVERT(varchar, dbo.PROFORTOTIKES.DATEFORTOSIS, 102) 
                      AS DATEFORTOSIS, dbo.PROFORTOTIKES.IFEPISTROFI, CONVERT(varchar, dbo.PROFORTOTIKES.DATEEPISTROFIS, 102) AS DATEEPISTROFIS, dbo.PROFORTOTIKES.AITIOLOGIAEPISTROFIS, 
                      dbo.PROFORTOTIKES.COMMENTSEPISTROFIS, dbo.PROFORTOTIKES.IFCASH, dbo.PROFORTOTIKES.IFPISTOSI, dbo.PROFORTOTIKES.STATUSDESCR, dbo.PROFORTOTIKES.YPAITIOS, 
                      dbo.PROFORTOTIKES.IFEPANADROMOLOGISI, dbo.PROFORTOTIKES.IFEPANEKDOSI, dbo.PROFORTOTIKES.IFOKEPANADROMOLOGISI, dbo.PROFORTOTIKES.NOPARASTANTIK, 
                      dbo.PROFORTOTIKES.COMMENTSAKIROSIS, dbo.PROFORTOTIKES.IFEISPRANTIK, dbo.PROFORTOTIKES.IFPARADOSIANTIK, dbo.PROFORTOTIKES.IFPARALAVIANTIK, 
                      dbo.PROFORTOTIKES.COMMENTSPARADANTIK, dbo.PROFORTOTIKES.COMMANTSPARALANTIK, dbo.PROFORTOTIKES.COMMENTSEISPRANTIK, CONVERT(varchar, 
                      dbo.PROFORTOTIKES.DATEPARADANTIK, 102) AS DATEPARADANTIK, CONVERT(varchar, dbo.PROFORTOTIKES.DATEPARALANTIK, 102) AS DATEPARALANTIK, CONVERT(varchar, 
                      dbo.PROFORTOTIKES.DATEEISPRANTIK, 102) AS DATEEISPRANTIK, dbo.PROFORTOTIKES.EISPRAXASANTIK, dbo.PROFORTOTIKES.NOPARPARADANTIK, 
                      dbo.PROFORTOTIKES.NOPARASTEISPRANTIK, dbo.PROFORTOTIKES.NOPARPARALANTIK, CONVERT(varchar, dbo.PROFORTOTIKES.DATEPARAL, 102) AS DATEPARAL, 
                      dbo.PROFORTOTIKES.COMMENTSPARAD, dbo.PROFORTOTIKES.COMMANTSPARAL, dbo.PROFORTOTIKES.TIMEPARALFROM, dbo.PROFORTOTIKES.TIMEPARALTO, 
                      dbo.PROFORTOTIKES.TIMEPARADFROM, dbo.PROFORTOTIKES.TIMEPARADTO, CONVERT(varchar, dbo.PROFORTOTIKES.DATECANCELANTIK, 102) AS DATECANCELANTIK, 
                      dbo.PROFORTOTIKES.IDPARAST, dbo.PROFORTOTIKES.TAXISPERCENT, dbo.PROFORTOTIKES.ANAMEXODO, dbo.PROFORTOTIKES.ID AS IDFORTOTIKIS, dbo.PROFORTOTIKES.AFMXREOUMENOU, 
                      dbo.HEADERPROFORTOTIKIS.ASFALISTRA, dbo.PROFORTOTIKES.CONTAINER, dbo.PROFORTOTIKES.BOAT, dbo.ACCOUNTS.Epagelma AS EPAGAPOST, 
                      dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, dbo.ACCOUNTS.AddressTK AS TKAPOST, dbo.ACCOUNTS.AddressCity AS CITYAPOST, 
                      dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, dbo.ACCOUNTS.Tel AS TELAPOST, dbo.ACCOUNTS.DOY AS DOYAPOST, ACCOUNTS_1.Epagelma AS EPAGPARAL, 
                      ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, ACCOUNTS_1.AddressNo AS ADDRNOPARAL, ACCOUNTS_1.AddressTK AS ADDRTKPARAL, ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, 
                      ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, ACCOUNTS_1.Tel AS TELPARAL, ACCOUNTS_1.DOY AS DOYPARAL, ACCOUNTS_2.Epagelma AS EPAGENTOL, 
                      ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, ACCOUNTS_2.AddressNo AS ADDRNOENTOL, ACCOUNTS_2.AddressTK AS ADDRTKENTOL, ACCOUNTS_2.AddressCity AS ADDRCITYENTOL, 
                      ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL, ACCOUNTS_2.Tel AS TELENTOL, ACCOUNTS_2.DOY AS DOYENTOL, ACCOUNTS_3.Epagelma AS EPAGTR, 
                      ACCOUNTS_3.AddressStr AS ADDRSTTR, ACCOUNTS_3.AddressNo AS ADDRNOTR, ACCOUNTS_3.AddressTK AS ADDRTKTR, ACCOUNTS_3.AddressCity AS ADDRCITYTR, 
                      ACCOUNTS_3.AddressPref AS ADSTRDRNOMO, ACCOUNTS_3.Tel AS TELTR, ACCOUNTS_3.DOY AS DOYTR, dbo.PROFORTOTIKES.AFMAPOSTOLEA, dbo.PROFORTOTIKES.AFMENTOLEA, 
                      dbo.PROFORTOTIKES.AFMPARALIPTI, dbo.PROFORTOTIKES.AFMTRITOU, dbo.PROFORTOTIKES.AFMANTAPOKRITI, dbo.PROFORTOTIKES.IFPARADOSITOPEL, 
                      dbo.PROFORTOTIKES.IFPARALABIFROMPEL, ACCOUNTS_1.Mobile AS MOBILEPARALIPTI, dbo.PROFORTOTIKES.IDXREOUMENOU, dbo.PROFORTOTIKES.IF_PRODROMOL, 
                      ACCOUNTS_2.Mobile AS MOBILEENTOLTEA, dbo.ACCOUNTS.Mobile AS MOBILEAPOSTOLEA, dbo.PROFORTOTIKES.IDDRIVER, dbo.PROFORTOTIKES.DRIVERDESCR, 
                      dbo.PROFORTOTIKES.IDXRHSHS, dbo.PROFORTOTIKES.IDCOMPANY, dbo.PROFORTOTIKES.IDYPOKATASTIMA, dbo.PROFORTOTIKES.IDWAREHOUSE, dbo.PROFORTOTIKES.EXT_ID, 
                      dbo.PROFORTOTIKES.NO_EXT_ORDER,dbo.PROFORTOTIKES.EXT_BARCODE, dbo.PROFORTOTIKES.IFCLOSE, dbo.PROFORTOTIKES.UserCreate, dbo.PROFORTOTIKES.DateCreate
FROM         dbo.PROFORTOTIKES WITH (NOLOCK) LEFT OUTER JOIN
                      dbo.ACCOUNTS WITH (NOLOCK) ON dbo.PROFORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON dbo.PROFORTOTIKES.IDPARALIPTI = ACCOUNTS_1.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON dbo.PROFORTOTIKES.IDENTOLEA = ACCOUNTS_2.id LEFT OUTER JOIN
                      dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON dbo.PROFORTOTIKES.IDTRITOU = ACCOUNTS_3.id LEFT OUTER JOIN
                      dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.PROFORTOTIKES.IDPARAST = dbo.KINDPARASTATIKON.ID LEFT OUTER JOIN
                      dbo.GRAMMESPROFORTTIKIS WITH (NOLOCK) ON dbo.GRAMMESPROFORTTIKIS.IDVOH = dbo.PROFORTOTIKES.ID LEFT OUTER JOIN
                      dbo.HEADERPROFORTOTIKIS WITH (NOLOCK) ON dbo.HEADERPROFORTOTIKIS.IDPROFORT = dbo.PROFORTOTIKES.ID LEFT OUTER JOIN
                      dbo.Units WITH (NOLOCK) ON dbo.GRAMMESPROFORTTIKIS.SYSKEVASIA = dbo.Units.UntID
GROUP BY dbo.PROFORTOTIKES.ID, dbo.PROFORTOTIKES.DATEPRINT, dbo.PROFORTOTIKES.PARASTATIKO, dbo.PROFORTOTIKES.SEIRA, dbo.PROFORTOTIKES.NOPARAST, dbo.PROFORTOTIKES.OXIMA, 
                      dbo.PROFORTOTIKES.IFPREPAY, dbo.PROFORTOTIKES.IFOFEILOMENI, dbo.PROFORTOTIKES.SUMPOSO, dbo.PROFORTOTIKES.IDAPOSTOLEA, dbo.PROFORTOTIKES.APOSTOLEASDESCR, 
                      dbo.PROFORTOTIKES.IDPARALIPTI, dbo.PROFORTOTIKES.PARALISPTISDESCR, dbo.PROFORTOTIKES.IDENTOLEA, dbo.PROFORTOTIKES.ENTOLEASDESCR, dbo.PROFORTOTIKES.IDANTAPOKRITI, 
                      dbo.PROFORTOTIKES.ANTAPOKRITISDESCR, dbo.PROFORTOTIKES.IDTRITOU, dbo.PROFORTOTIKES.TRITOSDESCR, dbo.PROFORTOTIKES.IDPRAKTOREIO, 
                      dbo.PROFORTOTIKES.PRAKTOREIODESCR, dbo.PROFORTOTIKES.SUMANTIK, dbo.PROFORTOTIKES.IFANTIKCASH, dbo.PROFORTOTIKES.ANTIKCASH, dbo.PROFORTOTIKES.IFANTIKEPIT, 
                      dbo.PROFORTOTIKES.ANTIKEPIT, dbo.PROFORTOTIKES.IFANTIKSYNAL, dbo.PROFORTOTIKES.ANTIKSYNAL, dbo.PROFORTOTIKES.IFANTIKOTHER, dbo.PROFORTOTIKES.ANTIKOTHER, 
                      dbo.PROFORTOTIKES.IFCANCELANTIK, dbo.PROFORTOTIKES.COMMENTSANTIK, dbo.PROFORTOTIKES.POSO, dbo.PROFORTOTIKES.TAXIS, dbo.PROFORTOTIKES.STATUS, 
                      dbo.PROFORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.PROFORTOTIKES.NOPARASTDELTIOUDIANOMIS, dbo.PROFORTOTIKES.DATEPARADOSI, dbo.PROFORTOTIKES.PERIOXIFORTOSIS, 
                      dbo.PROFORTOTIKES.PERIOXIPARADOSIS, dbo.PROFORTOTIKES.COMMENTS, dbo.PROFORTOTIKES.COMMENTS2, dbo.PROFORTOTIKES.OMADPROORISMOS, dbo.PROFORTOTIKES.IFXRENTOL, 
                      dbo.PROFORTOTIKES.KINDPAYMENTDESCR, dbo.PROFORTOTIKES.IDKINDPAYMENT, dbo.PROFORTOTIKES.IFXRAPOST, dbo.PROFORTOTIKES.IFXRAPOST, dbo.PROFORTOTIKES.IFXRPARAL, 
                      dbo.PROFORTOTIKES.IFXRTRITOU, dbo.PROFORTOTIKES.IFANTIKCASH, dbo.PROFORTOTIKES.IFANTIKEPIT, dbo.PROFORTOTIKES.IFANTIKSYNAL, dbo.PROFORTOTIKES.IFANTIKOTHER, 
                      dbo.PROFORTOTIKES.ifDelete, dbo.PROFORTOTIKES.IFCANCEL, dbo.PROFORTOTIKES.DATECANCEL, dbo.PROFORTOTIKES.IFXRAPOST, dbo.PROFORTOTIKES.IFXRPARAL, 
                      dbo.PROFORTOTIKES.IFXRENTOL, dbo.PROFORTOTIKES.IFXRTRITOU, dbo.PROFORTOTIKES.ANAMEXODO, dbo.PROFORTOTIKES.IFPARADOSI, dbo.PROFORTOTIKES.AITIOLOGIAPARASTATIKOU, 
                      dbo.PROFORTOTIKES.DATEFORTOSIS, dbo.PROFORTOTIKES.IFEPISTROFI, dbo.PROFORTOTIKES.DATEEPISTROFIS, dbo.PROFORTOTIKES.AITIOLOGIAEPISTROFIS, 
                      dbo.PROFORTOTIKES.COMMENTSEPISTROFIS, dbo.PROFORTOTIKES.IFCASH, dbo.PROFORTOTIKES.IFPISTOSI, dbo.PROFORTOTIKES.STATUSDESCR, dbo.PROFORTOTIKES.YPAITIOS, 
                      dbo.PROFORTOTIKES.IFEPANADROMOLOGISI, dbo.PROFORTOTIKES.IFEPANEKDOSI, dbo.PROFORTOTIKES.IFOKEPANADROMOLOGISI, dbo.PROFORTOTIKES.NOPARASTANTIK, 
                      dbo.PROFORTOTIKES.COMMENTSAKIROSIS, dbo.PROFORTOTIKES.IFEISPRANTIK, dbo.PROFORTOTIKES.IFPARADOSIANTIK, dbo.PROFORTOTIKES.IFPARALAVIANTIK, 
                      dbo.PROFORTOTIKES.COMMENTSPARADANTIK, dbo.PROFORTOTIKES.COMMANTSPARALANTIK, dbo.PROFORTOTIKES.COMMENTSEISPRANTIK, dbo.PROFORTOTIKES.DATEPARADANTIK, 
                      dbo.PROFORTOTIKES.DATEPARALANTIK, dbo.PROFORTOTIKES.DATEEISPRANTIK, dbo.PROFORTOTIKES.EISPRAXASANTIK, dbo.PROFORTOTIKES.NOPARPARADANTIK, 
                      dbo.PROFORTOTIKES.NOPARASTEISPRANTIK, dbo.PROFORTOTIKES.NOPARPARALANTIK, dbo.PROFORTOTIKES.DATEPARAL, dbo.PROFORTOTIKES.DATEPARAD, 
                      dbo.PROFORTOTIKES.COMMENTSPARAD, dbo.PROFORTOTIKES.COMMANTSPARAL, dbo.PROFORTOTIKES.TIMEPARALFROM, dbo.PROFORTOTIKES.TIMEPARALTO, 
                      dbo.PROFORTOTIKES.TIMEPARADFROM, dbo.PROFORTOTIKES.TIMEPARADTO, dbo.PROFORTOTIKES.ANTIKCASH, dbo.PROFORTOTIKES.ANTIKEPIT, dbo.PROFORTOTIKES.ANTIKSYNAL, 
                      dbo.PROFORTOTIKES.ANTIKOTHER, dbo.PROFORTOTIKES.IFCANCELANTIK, dbo.PROFORTOTIKES.DATECANCELANTIK, dbo.PROFORTOTIKES.TAXISPERCENT, dbo.PROFORTOTIKES.IDPARAST, 
                      dbo.KINDPARASTATIKON.Code, dbo.PROFORTOTIKES.AFMXREOUMENOU, dbo.HEADERPROFORTOTIKIS.ASFALISTRA, dbo.HEADERPROFORTOTIKIS.TAXIS, 
                      dbo.HEADERPROFORTOTIKIS.SUMPOSOXRPROFORT, dbo.PROFORTOTIKES.CONTAINER, dbo.PROFORTOTIKES.BOAT, dbo.HEADERPROFORTOTIKIS.KATHARO, dbo.ACCOUNTS.Epagelma, 
                      dbo.ACCOUNTS.AddressStr, dbo.ACCOUNTS.AddressNo, dbo.ACCOUNTS.AddressTK, dbo.ACCOUNTS.AddressCity, dbo.ACCOUNTS.AddressPref, dbo.ACCOUNTS.Tel, dbo.ACCOUNTS.DOY, 
                      ACCOUNTS_1.Epagelma, ACCOUNTS_1.AddressStr, ACCOUNTS_1.AddressNo, ACCOUNTS_1.AddressTK, ACCOUNTS_1.AddressCity, ACCOUNTS_1.AddressPref, ACCOUNTS_1.Tel, 
                      ACCOUNTS_1.DOY, ACCOUNTS_2.Epagelma, ACCOUNTS_2.AddressStr, ACCOUNTS_2.AddressNo, ACCOUNTS_2.AddressTK, ACCOUNTS_2.AddressCity, ACCOUNTS_2.AddressPref, 
                      ACCOUNTS_2.Tel, ACCOUNTS_2.DOY, ACCOUNTS_3.Epagelma, ACCOUNTS_3.AddressStr, ACCOUNTS_3.AddressNo, ACCOUNTS_3.AddressTK, ACCOUNTS_3.AddressCity, 
                      ACCOUNTS_3.AddressPref, ACCOUNTS_3.Tel, ACCOUNTS_3.DOY, dbo.PROFORTOTIKES.AFMAPOSTOLEA, dbo.PROFORTOTIKES.AFMENTOLEA, dbo.PROFORTOTIKES.IF_PRODROMOL, 
                      dbo.PROFORTOTIKES.AFMPARALIPTI, dbo.PROFORTOTIKES.AFMTRITOU, dbo.PROFORTOTIKES.AFMANTAPOKRITI, dbo.PROFORTOTIKES.EXODATRITON, dbo.PROFORTOTIKES.IFPARADOSITOPEL, 
                      ACCOUNTS_1.Mobile, ACCOUNTS_2.Mobile, dbo.ACCOUNTS.Mobile, dbo.PROFORTOTIKES.IDDRIVER, dbo.PROFORTOTIKES.DRIVERDESCR, dbo.PROFORTOTIKES.IDXREOUMENOU, 
                      dbo.PROFORTOTIKES.AA_ANTIK, dbo.PROFORTOTIKES.IFPARALABIFROMPEL, dbo.PROFORTOTIKES.NOLISTASDIANOMIS, dbo.PROFORTOTIKES.IDXRHSHS, dbo.PROFORTOTIKES.IDWAREHOUSE, 
                      dbo.PROFORTOTIKES.IDCOMPANY, dbo.PROFORTOTIKES.IDYPOKATASTIMA, dbo.PROFORTOTIKES.IFCLOSE, dbo.PROFORTOTIKES.EXT_ID, dbo.PROFORTOTIKES.NO_EXT_ORDER,dbo.PROFORTOTIKES.EXT_BARCODE, 
                      dbo.PROFORTOTIKES.UserCreate, dbo.PROFORTOTIKES.DateCreate


GO




