CREATE VIEW FORTOTIKES_LABELS_ANALYTIKA
AS
WITH ST AS (
			SELECT 
				IDFORTOTIKIS,
				MAX(AAGRAMMIS) [SUMTEMAXIA]
			
			FROM TEMAXIAFORTOTIKIS
			GROUP BY IDFORTOTIKIS	
			),
APOST AS (
		SELECT 
			ID,
			EPONIMIA,
			EPAGELMA,
			AFM,
			DOY,
			ADDRESSPREF,
			ADDRESSTK,
			ADDRESSSTR,
			ADDRESSNO,
			ADDRESSZONE,
			ADDRESSCOUNTRY,
			ADDRESSCITY,
			TEL,
			TEL2,
			MOBILE
		FROM ACCOUNTS
		),
PARAL AS (
		SELECT 
			ID,
			EPONIMIA,
			EPAGELMA,
			AFM,
			DOY,
			ADDRESSPREF,
			ADDRESSTK,
			ADDRESSSTR,
			ADDRESSNO,
			ADDRESSZONE,
			ADDRESSCOUNTRY,
			ADDRESSCITY,
			TEL,
			TEL2,
			MOBILE
		FROM ACCOUNTS
		)

SELECT

TF.ID,
TF.IDFORTOTIKIS [IDVOH],
TF.IDGRAMMIS [IDLINE],
GF.TIMDA,
TF.AAGRAMMIS [TEMAXIA],
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY ST.IDFORTOTIKIS ORDER BY ST.IDFORTOTIKIS)>1 
	THEN 0
	ELSE ST.SUMTEMAXIA
END AS SUMTEMAXIA,
GF.SYSKEVASIA,
F.STATUS,
F.DATEPRINT [DATEMOVE],
GF.PERIEXOMENO,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDGRAMMIS ORDER BY TF.IDGRAMMIS)>1
	THEN 0
	ELSE ISNULL(GF.BAROS,0)
END AS BAROS,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDGRAMMIS ORDER BY TF.IDGRAMMIS)>1
	THEN 0
	ELSE ISNULL(GF.KYBIKA,0)
END AS KYBIKA,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDFORTOTIKIS ORDER BY TF.IDFORTOTIKIS)>1
	THEN 0
	ELSE ISNULL(F.SUMPOSO,0)
END AS SUMPOSO,
GF.SYSKEVASIADESCR,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDGRAMMIS ORDER BY TF.IDGRAMMIS)>1
	THEN 0
	ELSE ISNULL(GF.XREOSIANAMONADA,0)
END AS XreosiAnaMonada,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDGRAMMIS ORDER BY TF.IDGRAMMIS)>1
	THEN NULL
	ELSE ISNULL(GF.XeosiSeMonada,'')
END AS XeosiSeMonada,
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY TF.IDGRAMMIS ORDER BY TF.IDGRAMMIS)>1
	THEN 0
	ELSE ISNULL(GF.XreosiGrammis,0)
END AS XreosiGrammis,
TF.BARCODE,
APOST.EPONIMIA [APOST_EPONIMIA],
PARAL.EPONIMIA [PARAL_EPONIMIA],
(ISNULL(PARAL.ADDRESSSTR,'') +' '+ ISNULL(PARAL.ADDRESSNO,'')) [PARAL_ADDRESS],
PARAL.ADDRESSCITY [PARAL_CITY],
CM.EPONIMIA [COMPANY_EPONIMIA],
CM.AFM [COMPANY_AFM],
YPOK.EPONIMIA [YPOK_EPONIMIA],
YPOK.ADDRESSCITY [YPOK_CITY],
ISNULL(YPOK.ADDRESSSTR,'') + ' ' +ISNULL(YPOK.ADDRESSNO,'') [YPOK_ADDRESS]





FROM TEMAXIAFORTOTIKIS TF
LEFT JOIN GRAMMESFORTTIKIS GF ON GF.ID=TF.IDGRAMMIS
LEFT JOIN ST ON ST.IDFORTOTIKIS=TF.IDFORTOTIKIS
LEFT JOIN FORTOTIKES F ON F.ID=TF.IDFORTOTIKIS
LEFT JOIN APOST ON APOST.ID=F.IDAPOSTOLEA
LEFT JOIN PARAL ON PARAL.ID=F.IDPARALIPTI
LEFT JOIN COMPANIES CM ON CM.ID=F.IDCOMPANY
LEFT JOIN COMPANIES YPOK ON YPOK.ID=F.IDYPOKATASTIMA

GO



