ALTER VIEW [dbo].[FORTOTIKESLABELS]
AS
  SELECT GFD.id,
         Round(GFD.baros, 2)                     AS BAROS,
         F.DATEPRINT							 AS DATEMOVE,
         GFD.idline,
         GFD.idvoh,
         Round(GFD.kybika, 3)                    AS KYBIKA,
         GFD.periexomeno,
         GFD.status,
         Round(GFD.sumposo, 2)                   AS SUMPOSO,
         Round(GFD.sumtemaxia, 0)                AS SUMTEMAXIA,
         GFD.syskevasia,
         GFD.syskevasiadescr,
         Round(GFD.temaxia, 2)                   AS TEMAXIA,
         replace((V.SEIRA+ CAST(V.NOPARAST AS NVARCHAR(25))),' ','')	 AS timda,
         GFD.xeosisemonada,
         F.koudouni,
         Round(GFD.xreosianamonada, 2)           AS XreosiAnaMonada,
         Round(GFD.xreosigrammis, 2)             AS XreosiGrammis,
         ACP.eponimia,
         acp.addresscountry,
         ACP.addresspref,
         ( ACP.addressstr + ' ' + acp.addressno )  AS ADDRESS,
         ( ACP.addresscity + ' ' + ACP.addresstk ) AS ADDRESSCITY,
         YP.eponimia                             AS YPOKATASIMA,
         CP.eponimia                             AS COMPANY,
         F.orofosdescr,
         (f.seira + F.noparast)					 as noparast,
		 V.ARRIVAL,
		 F.EXT_BARCODE
  FROM   grammesforttikisdetails AS GFD
		 LEFT JOIN fortotikes AS F  ON GFD.idvoh = F.id
         --LEFT JOIN paradoseis AS PR ON F.identolis = PR.idvoh
		 LEFT JOIN VOH AS V ON V.ID=F.IDENTOLIS
         LEFT JOIN accounts AS ACP  ON F.idparalipti = ACP.id
         LEFT JOIN companies AS CP  ON F.idcompany = CP.iddepartement
         LEFT JOIN companies AS YP  ON F.idypokatastima = YP.id


GO



