ALTER VIEW [dbo].[FORTOTIKILABES] 
AS 
SELECT 
	A.DATEPRINT AS DATEPRINT , 
	D.Eponimia, 
	D.Epagelma, 
	A.APOSTOLEASDESCR, 
	A.PARALISPTISDESCR, 
	(B.AddressStr + ' ' + B.AddressNo) AS ADDRESS,   
