LEFT JOIN GRAMMESFORTTIKIS AS C ON A.ID = C.IDVOH 
LEFT JOIN COMPANIES AS D ON A.IDCOMPANY = D.ID
LEFT JOIN COMPANIES AS E ON E.ID=A.IDYPOKATASTIMA

