CREATE VIEW FORTOTIKESLABELSGROUP
AS
	SELECT 
		DATEPRINT, 
	    Eponimia, 
	    Epagelma, 
	    APOSTOLEASDESCR, 
	    PARALISPTISDESCR, 
	    ADDRESS, 
	    AddressCity, 
	    MIN(ID) AS ID, 
	    MIN(TIMDA) AS TIMDA, 
	    SUM(TEMAXIA) AS TEMAXIA, 
	    MIN(SYSKEVASIADESCR) AS SYSKEVASIADESCR, 
	    YPOK_EPONIMIA, 
	    YPOK_ADDRESS, 
