PARAL.MOBILE [PARAL_MOBILE],
CM.EPONIMIA [COMPANY_EPONIMIA],
CM.AFM [COMPANY_AFM],
CM.DOY [COMPAPNY_DOY],
YPOK.EPONIMIA [YPOK_EPONIMIA],
YPOK.ADDRESSCITY [YPOK_CITY],
ISNULL(YPOK.ADDRESSSTR,'') + ' ' +ISNULL(YPOK.ADDRESSNO,'') [YPOK_ADDRESS],
YPOK.TEL [YPOK_TELEPHONE],
YPOK.MOBILE [YPOK_MOBILE],
YPOK.EMAIL [YPOK_EMAIL]



FROM TEMAXIAFORTOTIKIS TF
LEFT JOIN GRAMMESFORTTIKIS GF ON GF.ID=TF.IDGRAMMIS
LEFT JOIN ST ON ST.IDFORTOTIKIS=TF.IDFORTOTIKIS
LEFT JOIN FORTOTIKES F ON F.ID=TF.IDFORTOTIKIS
LEFT JOIN APOST ON APOST.ID=F.IDAPOSTOLEA
LEFT JOIN PARAL ON PARAL.ID=F.IDPARALIPTI
LEFT JOIN COMPANIES CM ON CM.ID=F.IDCOMPANY
LEFT JOIN COMPANIES YPOK ON YPOK.ID=F.IDYPOKATASTIMA


GO




