ALTER TRIGGER [dbo].[STATUS_HISTORY_TRIGGER] 
   ON  [dbo].[FORTOTIKES] 
   AFTER INSERT,UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	MERGE FORT_STATUS_HISTORY t 
	USING 
	(
		SELECT 
			TRIGROWS.ID, 
			TRIGROWS.STATUS, 
			TRIGROWS.NO_EXT_ORDER, 
			TRIGROWS.DATEPARAD, 
			DS.IFPARADOSI
		FROM inserted TRIGROWS
		JOIN DOC_STATUS DS ON DS.ID = TRIGROWS.STATUS
	) s
	ON 
		(s.ID = t.FORT_ID AND s.STATUS = t.STATUS_ID)
	WHEN MATCHED
	THEN UPDATE SET 
		t.NO_EXT_ORDER = s.NO_EXT_ORDER,
		t.DATE = 
			CASE 
				WHEN ISNULL(s.IFPARADOSI, 0) = 1 THEN GETDATE()
				ELSE GETDATE()
			END
	WHEN NOT MATCHED BY TARGET 
		THEN INSERT (FORT_ID, STATUS_ID, NO_EXT_ORDER, DATE, CREATED_AT)
		VALUES 
		(	
			s.ID, 
			s.STATUS,
			s.NO_EXT_ORDER, 
			CASE 
				WHEN ISNULL(s.IFPARADOSI, 0) = 1 THEN GETDATE()
				ELSE GETDATE()
			END,
			GETDATE()
		)
	; --must close the merge statement with ;
END

GO

---END SCRIPT 1701
