---NEW SCRIPT 1703
CREATE TRIGGER ReMOVE_PARADOSI
   ON  FORT_STATUS_HISTORY
   AFTER INSERT
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	IF EXISTS (SELECT DOC_STATUS.ID FROM DOC_STATUS JOIN INSERTED on INSERTED.STATUS_ID = DOC_STATUS.ID WHERE DOC_STATUS.IFPARADOSI = 0)
	BEGIN
		SELECT FSH.ID
		INTO #tmp
		FROM FORT_STATUS_HISTORY FSH
		JOIN DOC_STATUS DS ON DS.ID = FSH.STATUS_ID
		JOIN INSERTED on INSERTED.FORT_ID = FSH.FORT_ID
		WHERE DS.IFPARADOSI = 1
		
		DELETE FROM FORT_STATUS_HISTORY WHERE ID IN (SELECT ID FROM #tmp);
	END
end
GO




---END SCRIPT 1703
------------------------------------------------------------------------------------
