ALTER VIEW [dbo].[FORTOTIKILABES] 
AS 
SELECT 
	A.DATEPRINT AS DATEPRINT , 
	D.Eponimia, 
	D.Epagelma, 
	A.APOSTOLEASDESCR, 
	A.PARALISPTISDESCR, 
	(B.AddressStr + ' ' + B.AddressNo) AS ADDRESS,   
	B.AddressCity,
	B.ADDRESSTK, 
	B.TEL,
	B.MOBILE,
	C.ID, 
	C.TIMDA, 
	C.TEMAXIA, 
	C.SYSKEVASIADESCR, 
	C.IDVOH,
	E.EPONIMIA [YPOK_EPONIMIA],
	E.ADDRESSCITY [YPOK_CITY],
	E.ADDRESSSTR + ' ' + E.ADDRESSNO [YPOK_ADDRESS],
	E.ADDRESSTK [YPOK_TK],
	E.TEL [YPOK_TEL],
	E.MOBILE [YPOK_MOBILE],
	E.EMAIL [YPOK_EMAIL],
	A.EXT_BARCODE,
	A.NO_EXT_ORDER 
FROM FORTOTIKES AS A 
LEFT JOIN ACCOUNTS AS B ON A.IDPARALIPTI = B.ID 
LEFT JOIN GRAMMESFORTTIKIS AS C ON A.ID = C.IDVOH 
LEFT JOIN COMPANIES AS D ON A.IDCOMPANY = D.ID
LEFT JOIN COMPANIES AS E ON E.ID=A.IDYPOKATASTIMA


GO




---END SCRIPT 1704
