ALTER PROCEDURE [dbo].[InserttoFORTOTIKES]
(
	@SEIRA						NVARCHAR(10)= NULL,
	@NOPARAST					NVARCHAR(20)= NULL,
	@IDPARAST					NUMERIC(18,0)= NULL,
	@PARASTATIKO				NVARCHAR(50)= NULL,
	@IFXRAPOST					INT= 0,
	@IFXRPARAL					INT= 0,
	@IFXRENTOL					INT= 0,
	@IFXRTRITOU					INT= 0,
	@IDAPOSTOLEA				NUMERIC(18,0)= NULL,
	@APOSTOLEASDESCR			NVARCHAR(50)= NULL,
	@IDPARALIPTI				NUMERIC(18,0)= NULL,
	@PARALISPTISDESCR			NVARCHAR(50)= NULL,
	@IDENTOLEA					NUMERIC(18,0)= NULL,
	@IDXREOUMENOU				NUMERIC(18, 0) = NULL,
	@ENTOLEASDESCR				NVARCHAR(50)= NULL,
	@IDTRITOU					NUMERIC(18,0)= NULL,
	@TRITOSDESCR				NVARCHAR(50)= NULL,
	@IDANTAPOKRITI				NUMERIC(18,0)= NULL,
	@ANTAPOKRITISDESCR			NVARCHAR(50)= NULL,
	@DATEPRINT					SMALLDATETIME= NULL,
	@POSO						NUMERIC(8,2)= NULL,
	@TAXISPERCENT				NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,
	@IFANTIKCASH				INT= 0,
	@IFANTIKEPIT				INT= 0,
	@IFANTIKSYNAL				INT= 0,
	@IFANTIKOTHER				INT= 0,
	@ANTIKCASH					NUMERIC(8,2)= NULL,
