------------------------------------------------------------------------------------
---NEW SCRIPT 1717


ALTER PROCEDURE [dbo].[updateFORT_ANA_KAA]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDKAA					NUMERIC(18, 0)= NULL,
	@NoPARASTKAA			NVARCHAR(10)= NULL, 
	@OXIMA					NVARCHAR(60)= NULL,
	@CONTAINER				NVARCHAR (50) =NULL,
	@BOAT					NVARCHAR (50) =NULL,
	@INSERTFORTOTIKES		NVARCHAR(MAX)= NULL,
	@DELETEDFORTOTIKES		NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON

--DECLARE @_STATUSID int
--DECLARE @_STATUS varchar(75)
----SET @_STATUS = 'ΣΕ ΚΑΑ'

--SELECT @_STATUS = STATUS, @_STATUSID = IDSTATUS FROM KAA WHERE ID = @IDKAA

--IF LEN(@_STATUS) < 3 
--BEGIN
--	SELECT TOP 1 @_STATUS = DESCR, @_STATUSID = ID FROM DOC_STATUS WHERE IFSEKAA = 1 
--END







	DECLARE @_STATUSID INT
	DECLARE @_STATUS VARCHAR(75)
	--SET @_STATUS = 'ΣΕ ΚΑΑ'

	DECLARE @_DRIVERID INT
	DECLARE @_DRIVERDESCR NVARCHAR(50)

	SELECT
		@_STATUS = STATUS
	 ,@_STATUSID = IDSTATUS
	 ,@_DRIVERID = isnull(ODIGOI.ID,0)
	 ,@_DRIVERDESCR = isnull(KAA.DRIVER,'')
	FROM KAA
