        INSERT INTO VOH_ANA_LISTAASS (IDLISTAS, IDVOH)  
        VALUES(@IDLISTAS, CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC))
        
        DELETE FROM VOH_ANA_LISTAASS WHERE IDVOH = CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC) AND IDLISTAS <> @IDLISTAS 
        SET @start = @end + 1 
