	ID BIGINT IDENTITY(1,1) PRIMARY KEY,
	IDFORTOTIKIS INT,
	IDKAA INT NULL,
	IDLISTAS INT NULL,
	IFINSERT BIT DEFAULT(0),
	IFDELETE BIT DEFAULT(0),
	IFSENT BIT DEFAULT(0)
)
