CREATE TRIGGER MYNEXT_API_NOTIFICATIONS_FORTOSI_LISTA
   ON  FORTOTIKES_ANA_LISTA
   AFTER INSERT--,DELETE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here

	INSERT INTO API_MYNEXT_NOTIFICATION_LIST(IDFORTOTIKIS, IDLISTAS, IFINSERT)
	SELECT i.IDFORTOTIKIS, i.IDLISTAS, 1
	FROM inserted i
	LEFT JOIN API_MYNEXT_NOTIFICATION_LIST AMNL 
		ON AMNL.IDFORTOTIKIS = i.IDFORTOTIKIS
		AND AMNL.IDLISTAS = i.IDLISTAS
		AND AMNL.IFINSERT = 1
	WHERE AMNL.ID is NULL 
END
GO



CREATE TRIGGER MYNEXT_API_NOTIFICATIONS_FORTOSI_KAA
   ON  FORTOTIKES_ANA_KAA
   AFTER INSERT--,DELETE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here

	INSERT INTO API_MYNEXT_NOTIFICATION_LIST(IDFORTOTIKIS, IDKAA, IFINSERT)
	SELECT i.IDFORTOTIKIS, i.IDKAA, 1
	FROM inserted i
	LEFT JOIN API_MYNEXT_NOTIFICATION_LIST AMNL 
		ON AMNL.IDFORTOTIKIS = i.IDFORTOTIKIS
		AND AMNL.IDKAA = i.IDKAA
		AND AMNL.IFINSERT = 1
	WHERE AMNL.ID is NULL 
END
