	DECLARE @ErrorNumber 	INT
	DECLARE @ErrorDescription NVARCHAR(255)
	DECLARE @Rowcount	INT
	DECLARE @RetVal 	INT
	DECLARE @Number 	NVARCHAR(30)	
	DECLARE @IDOC_COMM	INT
	DECLARE @IDOC_XRE	INT
	DECLARE @CAN_PRINT   	BIT
	DECLARE @ID 		INT
	DECLARE @RET_BATCH_NUM	NVARCHAR(30)
	DECLARE @Courier_Group_Code NVARCHAR(5)

	SET NOCOUNT ON
	SET @ErrorNumber = 0

	SET @TRACOUNT = @@TRANCOUNT
	IF @TRACOUNT = 0 

	--EISAGOGI TOY PARALIPTI EAN DEN YPARXEI STO PINAKA MAS
	--***************************************************************************
	DECLARE @RowCountPelati INT
	DECLARE @IDPARAST INT
	DECLARE @ClientCode INT
	DECLARE @ClientTownCode NVARCHAR(10)
	DECLARE @ClientRegionCode NVARCHAR(10) --TASK 12899
	DECLARE @PelatesAddr	NVARCHAR(60) --TASK 11593
	DECLARE @PelatesProfID	NVARCHAR(30) --TASK 11623
	SET @RowCountPelati=0

	IF @IDAFORA = 0
		BEGIN 	
			SET @KINDKINISIS = 1 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 1
		BEGIN 	
			SET @KINDKINISIS = 0 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 4
		BEGIN 	
			SET @KINDKINISIS = 99 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 5
		BEGIN 	
			SET @KINDKINISIS = 5 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 6
		BEGIN 	
			SET @KINDKINISIS = 6 --@KINDKINISIS = 1
		END 



		BEGIN
			INSERT INTO KINDPARASTATIKON
				(
				Code,
				Descr,
				KindKINISIS,
				KindYpologismou,
				IFENIMEROSITAMEIO,
				TRANSFORMTO,
				IF_AUTONUMBER,
				IF_TRANSFORM,
				AUTONUMBER_FROM,
				IF_ZERO_ON_NEW_YEAR,
				IF_PRINT,
				PREPORT,
				TAXISPERCENT,
				IF_XREOSI,
				IfMisthodosia,
				IfFortotiki,
				IF_PISTOSI,
				IfKAA,
				IF_ENIMEROSIKARTELA,
				IF_XREOSIKARTELA,
				IF_PISTOSIKARTELA,
				IFKEPXREOSI,
				IFKEPPISTOSI,
				IFPROFORTOTIKI,
				IFKEPYO,
				SEIRA,
				PRINTLABEL,
				PROEPSXOLIO,
				IfPreviewFirst,
				PrinterName,
				IDPARASTEXOFLISI,
				DESCRPARASTEXOFLISI,
				IF_ENIMEROSIAPOTHIKI,
				IFEISAGOGI,
				IFEXAGOGI,
				IF_PAROXIYPIRESION,
				IF_ORDER,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IF_LISTADIANOMIS,
				IF_PRODROMOL,
				IF_LISTAANTIKATABOLON,
				IF_FROM_ANTAP,
				--IFCASH,
				--IFPISTOSI,
				--IFOFEILOMENI,
				--IFPREPAY,
				CATKEPYO,
				CodeLog,
				Copies,
				IF_EDMETAFORAS,
				IF_EDSYNARMOL,
				IS_CANCELLATION,
				IF_LISTA_ASS,
				WEBPARASTATIKO,
				IF_ENIMEROSI_AADE,
				AADE_CODE,
				--IF_EDTOPOTH,
				VoucherTypeCode,
				IDCURRENCY,
				IF_ENIMEROSI_FPA

				)
			VALUES
				(
				@CODEPARAST,
				@PARASTATIKO,	
				@KINDKINISIS,			
				@KINDENIMEROSI	,
				@IFENIMEROSITAMEIO,
				@TRANSFORMTO,
				@IF_AUTONUMBER,
				@IF_TRANSFORM,
				@AUTONUMBER_FROM,
				@IF_ZERO_ON_NEW_YEAR,
				@IF_PRINT,
				@PREPORT,
				@TAXISPERCENT	,
				@IF_XREOSI,
				@IfMisthodosia,
				@IfFortotiki,
				@IF_PISTOSI,
				@IfKAA,
				@IF_ENIMEROSIKARTELA,
				@IF_XREOSIKARTELA,
				@IF_PISTOSIKARTELA,
				@IFKEPXREOSI,
				@IFKEPPISTOSI,
				@IFPROFORTOTIKI,
				@IFKEPYO,
				@SEIRA,
				@PRINTLABEL,
				@PROEPSXOLIO,
				@IfPreviewFirst,
				@PrinterName,
				@IDPARASTEXOFLISI,
				@DESCRPARASTEXOFLISI,
				@IF_ENIMEROSIAPOTHIKI,
				@IFEISAGOGI,
				@IFEXAGOGI,
				@IF_PAROXIYPIRESION,
				@IF_ORDER,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IF_LISTADIANOMIS,
				@IF_PRODROMOL,
				@IF_LISTAANTIKATABOLON,
				@IF_FROM_ANTAP,
				--@IFCASH,
				--@IFPISTOSI,
				--@IFOFEILOMENI,
				--@IFPREPAY,
				@CATKEPYO,
				@CodeLog,
				@Copies,			
				@IF_EDMETAFORAS,
				@IF_EDSYNARMOL,
				@IS_CANCELLATION,
				@IF_LISTA_ASS,
				@WEBPARASTATIKO,
				@IF_ENIMEROSI_AADE,
				@AADE_CODE,
				--@IF_EDTOPOTH,
				@VoucherTypeCode,
				@IDCURRENCY,
				@IF_ENIMEROSI_FPA
				)
		END

		SET @IDPARAST= (SELECT MAX(ID) FROM KINDPARASTATIKON WITH (NOLOCK))

		BEGIN
			INSERT INTO PARASTATIKA_ANA_KATHGORIA
				(
				ID_CAT_PARASTATIKON,
				ID_KINDPARASTATIKON
				)
			VALUES
				(
				@IDCATPARAST,
				@IDPARAST
				)
		END

	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************

ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint 

GO

---END SCRIPT 1732
