         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRTRITOU, 
         f.ifantikcash,
         f.ifantikepit,
         f.ifantiksynal,
         f.ifantikother,
         f.ifdelete,
         f.ifcancel,   
         f.aa_antik,
         f.nolistasantik,
         f.ifparadosi,
         f.aitiologiaparastatikou,
         CONVERT(VARCHAR, f.datefortosis, 103)			AS DATEFORTOSIS,
         f.ifepistrofi,
