ALTER VIEW [dbo].[FORTOTIKES_WITHDETAILS_VIEW]
AS
 
SELECT 
	dbo.FORTOTIKES.ID,
    dbo.FORTOTIKES.DATEPRINT,
    dbo.KINDPARASTATIKON.Code,
    dbo.FORTOTIKES.PARASTATIKO,
    dbo.FORTOTIKES.SEIRA,
    CAST(dbo.FORTOTIKES.NOPARAST AS int) AS NOPARAST,
    dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS,
    dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS,
    dbo.FORTOTIKES.OXIMA,
    dbo.FORTOTIKES.OMADPROORISMOS,
    CASE IFXRENTOL * 1 + IFXRAPOST * 2 + IFXRTRITOU * 4 + IFXRTRITOU * 8 
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		ELSE 'ΑΓΝΩΣΤΟ'
	END AS XREOYMENOS,
    ACCOUNTS.Eponimia AS APOSTOLEASDESCR,
    ACCOUNTS_1.Eponimia AS PARALISPTISDESCR,
    ACCOUNTS_2.Eponimia AS ENTOLEASDESCR,
    dbo.GRAMMESFORTTIKIS.ID AS IDGRAMMIS,
    dbo.FORTOTIKES.ANTAPOKRITISDESCR,
    dbo.FORTOTIKES.NOLISTASDIANOMIS,
    ACCOUNTS_3.Eponimia AS TRITOSDESCR,
    dbo.GRAMMESFORTTIKIS.TIMDA,
    CASE T.ROWNUM
        WHEN 1 THEN dbo.FORTOTIKES.POSO
        ELSE NULL
    END AS [POSO],
    CASE T.ROWNUM
        WHEN 1 THEN dbo.FORTOTIKES.TAXIS
        ELSE NULL
    END AS [TAXIS],
    CASE T.ROWNUM
        WHEN 1 THEN dbo.FORTOTIKES.SUMPOSO
        ELSE NULL
    END AS [SUMPOSO],
    dbo.GRAMMESFORTTIKIS.TEMAXIA,
    dbo.GRAMMESFORTTIKIS.PERIEXOMENO,
    dbo.GRAMMESFORTTIKIS.BAROS,
    dbo.GRAMMESFORTTIKIS.KYBIKA,
    dbo.GRAMMESFORTTIKIS.SUMPOSO AS AXIA,
    dbo.Units.UntName AS SYSKEVASIA,
    CASE T.ROWNUM
		WHEN 1 THEN
			CASE dbo.FORTOTIKES.IFPREPAY
				WHEN 1 THEN SUM_XREOSEIS.XREOSEIS
				ELSE 0
			END
		ELSE NULL
    END AS XREOSIPROPLIROMENES,
    CASE T.ROWNUM
		WHEN 1 THEN
			CASE dbo.FORTOTIKES.IFOFEILOMENI
				WHEN 1 THEN SUM_XREOSEIS.XREOSEIS
				ELSE 0
			END
		ELSE NULL
    END AS XREOSIOFEILOMENES,
    CASE T.ROWNUM
		WHEN 1 THEN
			CASE dbo.FORTOTIKES.IFPREPAY
				WHEN 1 THEN
					CASE dbo.FORTOTIKES.IFCASH
						WHEN 1 THEN SUM_XREOSEIS.XREOSEIS
						ELSE 0
					END
				ELSE 0
			END
		ELSE NULL
	END AS XREOSIPROPLIROMENESCASH,
	CASE T.ROWNUM
		WHEN 1 THEN
			CASE dbo.FORTOTIKES.IFPREPAY
				WHEN 1 THEN 
					CASE dbo.FORTOTIKES.IFPISTOSI
						WHEN 1 THEN SUM_XREOSEIS.XREOSEIS
						ELSE 0
					END
				ELSE 0
			END
		ELSE NULL
	END AS XREOSIPROPLIROMENESPISTOSI,
    dbo.FORTOTIKES.PERIOXIFORTOSIS,
    dbo.FORTOTIKES.PERIOXIPARADOSIS,
    FORTOTIKES.NO_EXT_ORDER,
    dbo.FORTOTIKES.COMMENTS,
    CASE T.ROWNUM
		WHEN 1 THEN dbo.FORTOTIKES.SUMANTIK
		ELSE NULL
	END [SUMANTIK],
    dbo.FORTOTIKES.PRAKTOREIODESCR,
    dbo.FORTOTIKES.STATUS,
	dbo.FORTOTIKES.DATEPARAD,
	dbo.FORTOTIKES.IDAPOSTOLEA,
	dbo.FORTOTIKES.IDPARALIPTI,
	dbo.FORTOTIKES.IDENTOLEA,
	dbo.FORTOTIKES.IDANTAPOKRITI,
	dbo.FORTOTIKES.IDTRITOU,
	dbo.FORTOTIKES.IDPRAKTOREIO,
	CASE T.ROWNUM
		WHEN 1 THEN ISNULL(dbo.FORTOTIKES.ANTIKCASH, 0)
		ELSE NULL
	END AS ANTIKCASH,
	CASE T.ROWNUM
		WHEN 1 THEN ISNULL(dbo.FORTOTIKES.ANTIKEPIT, 0)
