ALTER PROCEDURE [dbo].[InserttoACCOUNTS_IMPORT]
(
	@Name			VARCHAR(50),
	@VatNumber		VARCHAR(50) = NULL,
	@Address		VARCHAR(50),
	@ZipCode		VARCHAR(10) = NULL,
	@Telephone		VARCHAR(20) = NULL,
	@Mobile			VARCHAR(20) = NULL,
	@Email			VARCHAR(50) = NULL,
	@CityID			INT,
	@ExternalID		NVARCHAR(20) = NULL,
	@TheID			INT = NULL output
	
	)
AS

SET NOCOUNT ON;

DECLARE @AddressCity NVARCHAR(50)

SELECT TOP 1 @AddressCity = AarName FROM Aar WHERE AarId = @CityID

EXEC InserttoACCOUNTS
	@Eponimia				= @Name,
	@AFM					= @VatNumber,
	@Epagelma				= '',
	@LastName				= '',
	@FirstName				= '',
	@AddressStr				= @Address,
	@AddressNo				= '',
	@AddressTK				= @ZipCode,
	@AddressCity			= @AddressCity,
	@Tel					= @Telephone,
	@Mobile					= @Mobile,
	@Fpa					= '1 - Κανονικό',
	@IF_PROM				=	0,
	@IF_PEL					=	1,
	@IF_ERG					=	0,
	@AddrFortosis			=	@Address,
	@IF_ANTAPOKRITIS		= 0,
	@Comments				= '',
	@IDPARAST				= 0,
	@EMAIL					=	@Email,
	@XREOUMENOS				= 1,
	@CATKEPYO				= 0,
	@EXT_ID					= @ExternalID,
	@TheID					= @TheID output;


	UPDATE ACC
	    SET 
			Code = 'PEL-' + CONVERT(NVARCHAR, @TheID),
			AddressPref = Ast.AstName,
		    AddressCountry = Acr.AcrName,
		    AddressZone = DEP.DESCR
		FROM ACCOUNTS ACC
    --LEFT JOIN AAR AAR1 ON REPLACE(AAR1.AarZipCode, ' ', '') = REPLACE(ACC.AddressTK, ' ', '') AND LEN(AAR1.AarZipCode) > 4
    --LEFT JOIN AAR AAR2 ON AAR2.AarName = ACC.AddressCity AND LEN(AAR2.AarName) > 1
    --LEFT JOIN AAR ON AAR.AarID = COALESCE(AAR1.AarID, AAR2.AarID, 0)
    LEFT JOIN Aar ON Aar.AarID = @CityID
	LEFT JOIN Ast ON AST.AstID = AAR.AarAstID
    LEFT JOIN Departements DEP ON DEP.ID = AST.IDDEPARTEMENT
    LEFT JOIN ACR ON ACR.AcrID = Ast.AstAcrID
    WHERE ACC.ID = @TheID


	SELECT @TheID AS ID;



GO



ALTER PROCEDURE [dbo].[InserttoFORTOTIKES_IMPORT]
(
	
	@IDENTOLEA					NUMERIC(18,0)= NULL,
	@IDAPOSTOLEA				NUMERIC(18,0)= NULL,
	@IDPARALIPTI				NUMERIC(18,0)= NULL,
	@IDTRITOU					NUMERIC(18,0)= NULL,
	@IDPARAST					NUMERIC(18,0)= NULL,
	
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	
	@DATEPRINT					SMALLDATETIME= NULL,

	@NO_EXT_FORT				NVARCHAR(50) = NULL,
	@NO_EXT_ORDER				NVARCHAR(50) = NULL,
	@EXT_BARCODE				NVARCHAR (150) =NULL,


	@POSO						NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,

	@EXODATRITON				NUMERIC(8,2)= NULL,
	
	
	@NOPARASTANTIK				NVARCHAR(50) = NULL,
	@COMMENTS					NVARCHAR(MAX)= NULL,

	@COMPANYID					INT = NULL,
	@YPOKATID					INT = NULL,

	@USERCREATE					NVARCHAR(50) = 'Import Tool',

	@FLAG_PROPLIROMENI			BIT = NULL,
	@FLAG_OFEILOMENI			BIT = NULL,
	@FLAG_METRITIS				BIT = NULL,
	@FLAG_PISTOSI				BIT = NULL,

	@ANTIKCOMMENTS				NVARCHAR(100) = NULL,

	@TheID						NUMERIC(18, 0)= NULL output
	
	)
AS

SET NOCOUNT ON;


DECLARE @PARAST_SEIRA NVARCHAR(50)
DECLARE @PARAST_DESC NVARCHAR(50)
DECLARE @PARAST_AUTONUMBER BIT
DECLARE @PARAST_TAXISPERCENT NUMERIC(18,2)

DECLARE @IDKINDPAYMENT INT
DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

DECLARE @IDSTATUS INT
DECLARE @STATUSDESCR NVARCHAR(50)

DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
DECLARE @AFMAPOSTOLEA NVARCHAR (10) =NULL
DECLARE @AFMENTOLEA NVARCHAR (10) =NULL
DECLARE @AFMPARALIPTI NVARCHAR (10) =NULL
DECLARE @AFMTRITOU NVARCHAR (10) =NULL

DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL
DECLARE @PERIOXIPARADOSIS NVARCHAR(50) = NULL
DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

DECLARE @APOSTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @PARALISPTISDESCR NVARCHAR(50)= NULL
DECLARE @ENTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

DECLARE @IDXRHSHS INT;

select top 1 @IDXRHSHS=ID from XRHSEIS where getdate() between FIRSTDATE and LASTDATE

SELECT @AFMXREOUMENOU = AFM FROM ACCOUNTS WHERE ID = @IDENTOLEA
SELECT @AFMENTOLEA = AFM, @ENTOLEASDESCR = Eponimia FROM ACCOUNTS WHERE ID = @IDENTOLEA

SELECT 
	@AFMAPOSTOLEA = AFM, 
	@APOSTOLEASDESCR = Eponimia,
	@PERIOXIFORTOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDAPOSTOLEA

SELECT 
	@AFMPARALIPTI = AFM, 
	@PARALISPTISDESCR = Eponimia,
	@PERIOXIPARADOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDPARALIPTI

SELECT 
	@AFMTRITOU = AFM, 
	@TRITOSDESCR = Eponimia
FROM ACCOUNTS WHERE ID = @IDTRITOU

SELECT TOP 1
	@IDKINDPAYMENT=ID,
	@KINDPAYMENTDESCR=DESCR
FROM KINDOFPAYMENTS
WHERE IF_PISTOSI = 1
AND IF_IN = 1

SELECT TOP 1
	@IDSTATUS=ID,
	@STATUSDESCR=DESCR
FROM DOC_STATUS
WHERE IF_PRINT = 1
AND IFEKDOSI = 1

SELECT 
	@PARAST_SEIRA = SEIRA,
	@PARAST_DESC = DESCR,
	@PARAST_AUTONUMBER = IF_AUTONUMBER,
	@PARAST_TAXISPERCENT = TAXISPERCENT

FROM KINDPARASTATIKON
WHERE ID = @IDPARAST


	--@STATUSDESCR				NVARCHAR(50) = NULL,


EXEC InserttoFORTOTIKES
	@TheID = @TheID output,
	@IDENTOLEA = @IDENTOLEA,
	@IDAPOSTOLEA = @IDAPOSTOLEA,
	@IDPARALIPTI = @IDPARALIPTI,
	@IDTRITOU = @IDTRITOU,
	@IDANTAPOKRITI = -1,
	@IDXREOUMENOU = @IDTRITOU,
	
	@IDPARAST = @IDPARAST,
	@PARASTATIKO = @PARAST_DESC,
	@SEIRA = @PARAST_SEIRA,
	@IFAUTONUMBER = @PARAST_AUTONUMBER,

	@ANTIKCASH = @ANTIKCASH,
	@ANTIKEPIT = @ANTIKEPIT,
	@ANTIKSYNAL = @ANTIKSYNAL,
	@ANTIKOTHER = @ANTIKOTHER,

	@PERIOXIPARADOSIS = @PERIOXIPARADOSIS,
	@PERIOXIFORTOSIS = @PERIOXIFORTOSIS,



	@IFCASH = 0,
	@IFPISTOSI = 1,
	@IFPREPAY = 1,
	@IFOFEILOMENI = 0,
	@DATEPRINT = @DATEPRINT,
	@IDKINDPAYMENT = @IDKINDPAYMENT,
	@KINDPAYMENTDESCR = @KINDPAYMENTDESCR,
	@NO_EXT_ORDER = @NO_EXT_ORDER,
	@EXT_BARCODE = @EXT_BARCODE,
	@STATUS = @IDSTATUS,
	@STATUSDESCR = @STATUSDESCR,
	@AFMXREOUMENOU = @AFMXREOUMENOU,
	@AFMENTOLEA = @AFMENTOLEA,
	@AFMAPOSTOLEA = @AFMAPOSTOLEA,
	@AFMPARALIPTI = @AFMPARALIPTI,
	@AFMTRITOU = @AFMTRITOU,

	@APOSTOLEASDESCR = @APOSTOLEASDESCR,
	@PARALISPTISDESCR = @PARALISPTISDESCR,
	@ENTOLEASDESCR = @ENTOLEASDESCR,
	@TRITOSDESCR = @TRITOSDESCR,
	@DateCreate = @DATEPRINT,
	@UserCreate	= @USERCREATE,

	@IDXRHSHS = @IDXRHSHS,
	@IDCOMPANY = 1,
	@IDYPOKATASTIMA = 2,
	@TAXISPERCENT = @PARAST_TAXISPERCENT,
	@COMMENTS = @COMMENTS,
	@EXODATRITON = @EXODATRITON
	

update F
	SET 
		IFANTIKCASH = CASE WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKEPIT = CASE WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKSYNAL = CASE WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKOTHER = CASE WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1 ELSE 0 END,
		SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER,0),
		IF_FROM_ANTAP = KP.IF_FROM_ANTAP,
		IFXRTRITOU = 1,
		IFPREPAY = COALESCE(@FLAG_PROPLIROMENI, ENTOL.IFPREPAY),
		IFCASH = COALESCE(@FLAG_METRITIS, ENTOL.IFCASH),
		IFOFEILOMENI = COALESCE(@FLAG_OFEILOMENI, ENTOL.IFOFEILOMENI),
		IFPISTOSI = COALESCE(@FLAG_PISTOSI, ENTOL.IFPISTOSI),
		NO_EXT_FORT = @NO_EXT_FORT,
		COMMENTSANTIK = @ANTIKCOMMENTS
from FORTOTIKES F
join KINDPARASTATIKON KP ON KP.ID = F.IDPARAST
join ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
WHERE F.ID = @TheID;

UPDATE F SET
	F.OMADPROORISMOS=CASE 
							WHEN LEN(OP.Descr)>=2 THEN OP.Descr	
							ELSE (SELECT TOP 1 Descr FROM OMADIKOI_PROORISMOI WHERE LEN(Descr)<=1)
						END,
	F.OXIMA = (SELECT ARKYKLOFORIAS FROM TRUCKS WHERE LEN(ArKykloforias)<=2),
	F.IDDRIVER = (SELECT MIN(ID) [ID] FROM ODIGOI WHERE ifDelete=0),
	F.DRIVERDESCR = (SELECT TOP 1 (LastName + ' ' +FirstName) FROM ODIGOI 
						WHERE IFDELETE =0)  
FROM FORTOTIKES F
LEFT JOIN Aar ON Aar.AarName=F.PERIOXIPARADOSIS
LEFT JOIN AarPerOmProor AOM ON AOM.AarID=Aar.AarID
LEFT JOIN OMADIKOI_PROORISMOI OP ON OP.ID=AOM.IDOmProor
WHERE F.ID = @TheID;


INSERT INTO XREOSISANADELTIO(
	IDVOH, 
	IDXREOSIS, 
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_FORTOTIKI,
	IF_TO_VOH
)
SELECT
	FORT.ID,
	XR.ID,
	XR.CODE,
	XR.Descr,
	XR.TAXISPERCENT,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@POSO, 1)
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@TAXIS, 0.24)
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@SUMPOSO, 1.24)
		ELSE 0
	END,
	1,
	0
		
FROM XREOSISANAPARASTATIKO XAP
JOIN FORTOTIKES FORT ON FORT.IDPARAST = XAP.IDKINDPARASTTIKON
JOIN Xreoseis XR ON XR.ID = XAP.IDXREOSIS
WHERE XAP.ifDelete = 0
AND XR.ifDelete = 0
AND XAP.IDKINDPARASTTIKON = FORT.IDPARAST
AND FORT.ID = @theID;


-- update #10523
with sumxr as (
select
		xad.IDVOH,
		SUM(xad.POSO) POSO,
		SUM(xad.TAXIS) TAXIS,
		SUM(xad.SUMPOSO) SUMPOSO
	from XREOSISANADELTIO xad
	where xad.IF_TO_FORTOTIKI = 1
	and xad.IDVOH = @TheID
	group by xad.IDVOH
) 
UPDATE F
	SET POSO = SUMXR.POSO,
		TAXIS = SUMXR.TAXIS,
		SUMPOSO = SUMXR.SUMPOSO
FROM FORTOTIKES F
JOIN SUMXR on F.ID = SUMXR.IDVOH;

-- κλαιει η μανα του πελε
with SUMXRPF as (
	select
		xap.IDVOH,
		ISNULL(XR.ifKomistra, 0) ifKomistra,
		ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis,
		ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton,
		ISNULL(xr.ifOther, 0) ifOther,
		ISNULL(xr.IfAsfalistra, 0) ifAsfalistra,
		ISNULL(xr.ifErgatika, 0) ifErgatika,
		ISNULL(xr.IfEmvastika, 0) ifEmvastika,
		sum(xap.POSO) POSO
	from XREOSISANADELTIO XAP
	join Xreoseis XR ON XR.ID = XAP.IDXREOSIS
	where xap.IDVOH = @TheID
	GROUP BY
		GROUPING SETS (
			(IDVOH, ifKomistra),
			(IDVOH, ifDikaiomaFortotikis),
			(IDVOH, ifXreosiTriton),
			(IDVOH, ifOther),
			(IDVOH, IfAsfalistra),
			(IDVOH, ifErgatika),
			(IDVOH, ifEmvastika)
		)
	HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		or ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		or ISNULL(xr.ifXreosiTriton, 0) = 1
		or ISNULL(xr.ifOther, 0) = 1
		or ISNULL(xr.IfAsfalistra, 0) = 1
		or ISNULL(xr.ifErgatika, 0) = 1
		or ISNULL(xr.IfEmvastika, 0) = 1
	)
)
INSERT INTO HEADERFORTOTIKIS (
	IDFORT,
	PARASTATIKOFORT,
	SEIRAFORT,
	NOPARASTFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONFORT,
	BAROSFORT,
	KYBIKAFORT,
	POSOFORT,
	TEMAXIAFORT
)
select
	FORT.ID,
	FORT.PARASTATIKO,
	FORT.SEIRA,
	FORT.NOPARAST,
	FORT.ENTOLEASDESCR,
	FORT.PARALISPTISDESCR,
	FORT.APOSTOLEASDESCR,
	ISNULL(SUM_KOMISTRA.POSO, 0),
	ISNULL(SUM_DIKAIOMA.POSO, 0),
	ISNULL(SUM_OTHER.POSO, 0),
	ISNULL(GF.SYSKEVASIA, 0),
	ISNULL(SUM_ASFALISTRA.POSO, 0),
	
	--katharo?
	FORT.POSO,

	FORT.TAXIS,
	FORT.SUMPOSO,
	ISNULL(SUM_ERGATIKA.POSO, 0),
	ISNULL(FORT.EXODATRITON, 0),
	
	--oliko synolo xreoson ?!
	FORT.SUMPOSO + FORT.EXODATRITON,
	
	ISNULL(GF.BAROS, 0),
	ISNULL(GF.KYBIKA, 0),

	--what the fuck den perigrafw allo
	FORT.POSO,
	ISNULL(GF.TEMAXIA, 0)

from fortotikes FORT
left join (
	SELECT 
		IDVOH,
		MIN(SYSKEVASIADESCR) SYSKEVASIA,
		SUM(BAROS) BAROS,
		SUM(KYBIKA) KYBIKA,
		SUM(TEMAXIA) TEMAXIA
	FROM GRAMMESFORTTIKIS
	GROUP BY IDVOH
) GF ON GF.IDVOH = FORT.ID
left join SUMXRPF SUM_KOMISTRA on SUM_KOMISTRA.ifKomistra = 1
left join SUMXRPF SUM_DIKAIOMA on SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
left join SUMXRPF SUM_OTHER on SUM_OTHER.ifOther = 1
left join SUMXRPF SUM_ASFALISTRA ON SUM_ASFALISTRA.ifAsfalistra = 1
left join SUMXRPF SUM_ERGATIKA ON SUM_ERGATIKA.ifErgatika = 1
left join SUMXRPF SUM_TRITON ON SUM_TRITON.ifXreosiTriton = 1
left join (
	SELECT IDVOH, SUM(POSO) POSO, SUM(TAXIS) TAXIS, SUM(SUMPOSO) SUMPOSO FROM XREOSISANADELTIO GROUP BY IDVOH
) SUMXR ON SUMXR.IDVOH = FORT.ID

where id = @TheID




GO



ALTER PROCEDURE [dbo].[InserttoPROFORTOTIKES_IMPORT] (@IDENTOLEA NUMERIC(18, 0) = NULL,
@IDAPOSTOLEA NUMERIC(18, 0) = NULL,
@IDPARALIPTI NUMERIC(18, 0) = NULL,
@IDTRITOU NUMERIC(18, 0) = NULL,
@IDPARAST NUMERIC(18, 0) = NULL,

@ANTIKCASH NUMERIC(8, 2) = NULL,
@ANTIKEPIT NUMERIC(8, 2) = NULL,
@ANTIKSYNAL NUMERIC(8, 2) = NULL,
@ANTIKOTHER NUMERIC(8, 2) = NULL,

@DATEPRINT SMALLDATETIME = NULL,

@NO_EXT_ORDER NVARCHAR(50) = NULL,
@EXT_BARCODE NVARCHAR(150) = NULL,


@POSO NUMERIC(8, 2) = NULL,
@TAXIS NUMERIC(8, 2) = NULL,
@SUMPOSO NUMERIC(8, 2) = NULL,




@NOPARASTANTIK NVARCHAR(50) = NULL,
@COMMENTS NVARCHAR(MAX) = NULL,

@COMPANYID INT = NULL,
@YPOKATID INT = NULL,

@USERCREATE NVARCHAR(50) = 'Import Tool',

@FLAG_PROPLIROMENI BIT = NULL,
@FLAG_OFEILOMENI BIT = NULL,
@FLAG_METRITIS BIT = NULL,
@FLAG_PISTOSI BIT = NULL,
@ANTIKCOMMENTS NVARCHAR(100) = NULL,

@PERIOXIPARADOSIS NVARCHAR(50) = NULL,

@TheID NUMERIC(18, 0) = NULL OUTPUT)
AS

	SET NOCOUNT ON;


	DECLARE @PARAST_SEIRA NVARCHAR(50)
	DECLARE @PARAST_DESC NVARCHAR(50)
	DECLARE @PARAST_AUTONUMBER BIT
	DECLARE @PARAST_TAXISPERCENT NUMERIC(18, 2)

	DECLARE @IDKINDPAYMENT INT
	DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

	DECLARE @IDSTATUS INT
	DECLARE @STATUSDESCR NVARCHAR(50)

	DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
	DECLARE @AFMAPOSTOLEA NVARCHAR(10) = NULL
	DECLARE @AFMENTOLEA NVARCHAR(10) = NULL
	DECLARE @AFMPARALIPTI NVARCHAR(10) = NULL
	DECLARE @AFMTRITOU NVARCHAR(10) = NULL


	DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL

	DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

	DECLARE @APOSTOLEASDESCR NVARCHAR(50) = NULL
	DECLARE @PARALISPTISDESCR NVARCHAR(50) = NULL
	DECLARE @ENTOLEASDESCR NVARCHAR(50) = NULL
	DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

	DECLARE @IDXRHSHS INT;

	SELECT TOP 1
		@IDXRHSHS = ID
	FROM XRHSEIS
	WHERE GETDATE() BETWEEN FIRSTDATE AND LASTDATE

	SELECT
		@AFMXREOUMENOU = AFM
	FROM ACCOUNTS
	WHERE ID = @IDENTOLEA
	SELECT
		@AFMENTOLEA = AFM
	 ,@ENTOLEASDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDENTOLEA

	SELECT
		@AFMAPOSTOLEA = AFM
	 ,@APOSTOLEASDESCR = Eponimia
	 ,@PERIOXIFORTOSIS = AddressCity
	FROM ACCOUNTS
	WHERE ID = @IDAPOSTOLEA

	SELECT
		@AFMTRITOU = afm
	 ,@TRITOSDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDTRITOU

	SELECT
		@AFMPARALIPTI = AFM
	 ,@PARALISPTISDESCR = Eponimia
	FROM ACCOUNTS
	WHERE ID = @IDPARALIPTI

	SELECT TOP 1
		@IDKINDPAYMENT = ID
	 ,@KINDPAYMENTDESCR = DESCR
	FROM KINDOFPAYMENTS
	WHERE IF_PISTOSI = 1
	AND IF_IN = 1

	SELECT TOP 1
		@IDSTATUS = ID
	 ,@STATUSDESCR = DESCR
	FROM DOC_STATUS
	WHERE IF_PRINT = 1
	AND IFEKDOSI = 1

	SELECT
		@PARAST_SEIRA = SEIRA
	 ,@PARAST_DESC = DESCR
	 ,@PARAST_AUTONUMBER = IF_AUTONUMBER
	 ,@PARAST_TAXISPERCENT = TAXISPERCENT

	FROM KINDPARASTATIKON
	WHERE ID = @IDPARAST


	--@STATUSDESCR				NVARCHAR(50) = NULL,

	DECLARE @BARCODE_PREFIX NVARCHAR(50)
	SET @BARCODE_PREFIX = (SELECT
			BARCODE_PREFIX
		FROM COMPANIES
		WHERE id = @YPOKATID)
	+ CONVERT(NVARCHAR, @IDENTOLEA)


	EXEC InserttoPROFORTOTIKES @TheID = @TheID OUTPUT
														,@IDENTOLEA = @IDENTOLEA
														,@IDAPOSTOLEA = @IDAPOSTOLEA
														,@IDPARALIPTI = @IDPARALIPTI
														,@IDTRITOU = @IDTRITOU
														,@IDANTAPOKRITI = -1
														,@IDXREOUMENOU = @IDENTOLEA
														,@IDPARAST = @IDPARAST
														,@PARASTATIKO = @PARAST_DESC
														,@SEIRA = @PARAST_SEIRA
														,@IFAUTONUMBER = @PARAST_AUTONUMBER
														,@ANTIKCASH = @ANTIKCASH
														,@ANTIKEPIT = @ANTIKEPIT
														,@ANTIKSYNAL = @ANTIKSYNAL
														,@ANTIKOTHER = @ANTIKOTHER
														,@PERIOXIPARADOSIS = @PERIOXIPARADOSIS
														,@PERIOXIFORTOSIS = @PERIOXIFORTOSIS
														,@IFCASH = 0
														,@IFPISTOSI = 1
														,@IFPREPAY = 1
														,@IFOFEILOMENI = 0
														,@DATEPRINT = @DATEPRINT
														,@IDKINDPAYMENT = @IDKINDPAYMENT
														,@KINDPAYMENTDESCR = @KINDPAYMENTDESCR
														,@NO_EXT_ORDER = @NO_EXT_ORDER
														,@EXT_BARCODE = @EXT_BARCODE
														,@STATUS = @IDSTATUS
														,@STATUSDESCR = @STATUSDESCR
														,@AFMXREOUMENOU = @AFMXREOUMENOU
														,@AFMENTOLEA = @AFMENTOLEA
														,@AFMAPOSTOLEA = @AFMAPOSTOLEA
														,@AFMPARALIPTI = @AFMPARALIPTI
														,@AFMTRITOU = @AFMTRITOU
														,@APOSTOLEASDESCR = @APOSTOLEASDESCR
														,@PARALISPTISDESCR = @PARALISPTISDESCR
														,@ENTOLEASDESCR = @ENTOLEASDESCR
														,@TRITOSDESCR = @TRITOSDESCR
														,@DateCreate = @DATEPRINT
														,@UserCreate = @USERCREATE
														,@IDXRHSHS = @IDXRHSHS
														,@TAXISPERCENT = @PARAST_TAXISPERCENT
														,@COMMENTS = @COMMENTS
														,@IDCOMPANY = @COMPANYID
														,@IDYPOKATASTIMA = @YPOKATID


	UPDATE PF
	SET IFANTIKCASH =
			CASE
				WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKEPIT =
			CASE
				WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKSYNAL =
			CASE
				WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1
				ELSE 0
			END
		 ,IFANTIKOTHER =
			CASE
				WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1
				ELSE 0
			END
		 ,SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER, 0)
		 ,IFXRENTOL = 1
		 ,IFPREPAY = ENTOL.IFPREPAY
		 ,IFCASH = ENTOL.IFCASH
		 ,IFOFEILOMENI = ENTOL.IFOFEILOMENI
		 ,IFPISTOSI = ENTOL.IFPISTOSI
		 ,COMMENTSANTIK = @ANTIKCOMMENTS

	FROM PROFORTOTIKES PF
	JOIN ACCOUNTS ENTOL
		ON ENTOL.id = PF.IDENTOLEA
	WHERE PF.ID = @TheID;

	UPDATE PF
	SET PF.OMADPROORISMOS =
			CASE
				WHEN LEN(OP.Descr) >= 2 THEN OP.Descr
				ELSE (SELECT TOP 1
							Descr
						FROM OMADIKOI_PROORISMOI
						WHERE LEN(Descr) <= 1)
			END
		 ,PF.OXIMA = (SELECT
					ARKYKLOFORIAS
				FROM TRUCKS
				WHERE LEN(ArKykloforias) <= 2)
		 ,PF.IDDRIVER = (SELECT
					MIN(ID) [ID]
				FROM ODIGOI
				WHERE ifDelete = 0)
		 ,PF.DRIVERDESCR = (SELECT TOP 1
					(LastName + ' ' + FirstName)
				FROM ODIGOI
				WHERE IFDELETE = 0)
		 ,pf.PERIOXIPARADOSIS = paral.AddressCity

	FROM PROFORTOTIKES PF
	JOIN ACCOUNTS paral
		ON paral.id = pf.IDPARALIPTI
	LEFT JOIN Aar
		ON Aar.AarName = paral.AddressCity
	LEFT JOIN AarPerOmProor AOM
		ON AOM.AarID = Aar.AarID
	LEFT JOIN OMADIKOI_PROORISMOI OP
		ON OP.ID = AOM.IDOmProor
	WHERE PF.ID = @TheID;

	INSERT INTO XREOSISANAPRODELTIO (IDVOH,
	IDXREOSIS,
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_PROFORTOTIKI,
	IF_TO_PROVOH)
		SELECT
			PROFORT.ID
		 ,XR.ID
		 ,XR.CODE
		 ,XR.Descr
		 ,XR.TAXISPERCENT
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 1
				ELSE 0
			END
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 0.24
				ELSE 0
			END
		 ,CASE ISNULL(XR.ifKomistra, 0)
				WHEN 1 THEN 1.24
				ELSE 0
			END
		 ,1
		 ,0

		FROM XREOSISANAPARASTATIKO XAP
		JOIN PROFORTOTIKES PROFORT
			ON PROFORT.IDPARAST = XAP.IDKINDPARASTTIKON
		JOIN Xreoseis XR
			ON XR.ID = XAP.IDXREOSIS
		WHERE XAP.ifDelete = 0
		AND XR.ifDelete = 0
		AND XAP.IDKINDPARASTTIKON = PROFORT.IDPARAST
		AND PROFORT.ID = @theID;

	-- update #10523
	WITH sumxr
	AS
	(SELECT
			xad.IDVOH
		 ,SUM(xad.POSO) POSO
		 ,SUM(xad.TAXIS) TAXIS
		 ,SUM(xad.SUMPOSO) SUMPOSO
		FROM XREOSISANAPRODELTIO xad
		WHERE xad.IF_TO_PROFORTOTIKI = 1
		AND xad.IDVOH = @TheID
		GROUP BY xad.IDVOH)
	UPDATE PF
	SET POSO = SUMXR.POSO
		 ,TAXIS = SUMXR.TAXIS
		 ,SUMPOSO = SUMXR.SUMPOSO
	FROM PROFORTOTIKES PF
	JOIN SUMXR
		ON PF.ID = SUMXR.IDVOH;


	-- κλαιει η μανα του πελε
	WITH SUMXRPF
	AS
	(SELECT
			xap.IDVOH
		 ,ISNULL(XR.ifKomistra, 0) ifKomistra
		 ,ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis
		 ,ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton
		 ,ISNULL(xr.ifOther, 0) ifOther
		 ,ISNULL(xr.IfAsfalistra, 0) ifAsfalistra
		 ,ISNULL(xr.ifErgatika, 0) ifErgatika
		 ,ISNULL(xr.IfEmvastika, 0) ifEmvastika
		 ,SUM(xap.POSO) POSO
		FROM XREOSISANAPRODELTIO XAP
		JOIN Xreoseis XR
			ON XR.ID = XAP.IDXREOSIS
		WHERE xap.IDVOH = @TheID
		GROUP BY GROUPING SETS (
		(IDVOH, ifKomistra),
		(IDVOH, ifDikaiomaFortotikis),
		(IDVOH, ifXreosiTriton),
		(IDVOH, ifOther),
		(IDVOH, IfAsfalistra),
		(IDVOH, ifErgatika),
		(IDVOH, ifEmvastika)
		)
		HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		OR ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		OR ISNULL(xr.ifXreosiTriton, 0) = 1
		OR ISNULL(xr.ifOther, 0) = 1
		OR ISNULL(xr.IfAsfalistra, 0) = 1
		OR ISNULL(xr.ifErgatika, 0) = 1
		OR ISNULL(xr.IfEmvastika, 0) = 1
		))
	INSERT INTO HEADERPROFORTOTIKIS (IDPROFORT,
	PARASTATIKOPROFORT,
	SEIRAPROFORT,
	NOPARASTPROFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRPROFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONPROFORT,
	BAROSPROFORT,
	KYBIKAPROFORT,
	POSOPROFORT,
	TEMAXIAPROFORT)
		SELECT
			PROFORT.ID
		 ,PROFORT.PARASTATIKO
		 ,PROFORT.SEIRA
		 ,PROFORT.NOPARAST
		 ,PROFORT.ENTOLEASDESCR
		 ,PROFORT.PARALISPTISDESCR
		 ,PROFORT.APOSTOLEASDESCR
		 ,ISNULL(SUM_KOMISTRA.POSO, 0)
		 ,ISNULL(SUM_DIKAIOMA.POSO, 0)
		 ,ISNULL(SUM_OTHER.POSO, 0)
		 ,ISNULL(GPF.SYSKEVASIA, 0)
		 ,ISNULL(SUM_ASFALISTRA.POSO, 0)
		 ,

			--katharo?
			PROFORT.POSO
		 ,PROFORT.TAXIS
		 ,PROFORT.SUMPOSO
		 ,ISNULL(SUM_ERGATIKA.POSO, 0)
		 ,ISNULL(PROFORT.EXODATRITON, 0)
		 ,

			--oliko synolo xreoson ?!
			PROFORT.SUMPOSO + PROFORT.EXODATRITON
		 ,ISNULL(GPF.BAROS, 0)
		 ,ISNULL(GPF.KYBIKA, 0)
		 ,

			--what the fuck den perigrafw allo
			PROFORT.POSO
		 ,ISNULL(GPF.TEMAXIA, 0)

		FROM PROFORTOTIKES PROFORT
		LEFT JOIN (SELECT
				IDVOH
			 ,MIN(SYSKEVASIADESCR) SYSKEVASIA
			 ,SUM(BAROS) BAROS
			 ,SUM(KYBIKA) KYBIKA
			 ,SUM(TEMAXIA) TEMAXIA
			FROM GRAMMESPROFORTTIKIS
			GROUP BY IDVOH) GPF
			ON GPF.IDVOH = PROFORT.ID
		LEFT JOIN SUMXRPF SUM_KOMISTRA
			ON SUM_KOMISTRA.ifKomistra = 1
		LEFT JOIN SUMXRPF SUM_DIKAIOMA
			ON SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
		LEFT JOIN SUMXRPF SUM_OTHER
			ON SUM_OTHER.ifOther = 1
		LEFT JOIN SUMXRPF SUM_ASFALISTRA
			ON SUM_ASFALISTRA.ifAsfalistra = 1
		LEFT JOIN SUMXRPF SUM_ERGATIKA
			ON SUM_ERGATIKA.ifErgatika = 1
		LEFT JOIN SUMXRPF SUM_TRITON
			ON SUM_TRITON.ifXreosiTriton = 1
		LEFT JOIN (SELECT
				IDVOH
			 ,SUM(POSO) POSO
			 ,SUM(TAXIS) TAXIS
			 ,SUM(SUMPOSO) SUMPOSO
			FROM XREOSISANAPRODELTIO
			GROUP BY IDVOH) SUMXR
			ON SUMXR.IDVOH = PROFORT.ID

		WHERE id = @TheID;
	INSERT INTO AarAlternativeNames ([FreeText],
	FreeZip)
		SELECT
			P.PERIOXIPARADOSIS
		 ,A.AddressTK
		FROM PROFORTOTIKES p
		LEFT JOIN ACCOUNTS a
			ON A.id = P.IDPARALIPTI

	SELECT
		@TheID AS IDVOH;
GO




---END SCRIPT 1741
