ALTER TRIGGER [dbo].[FORTOTIKES_API_NOTIFICATIONS] 
   ON  [dbo].[FORTOTIKES] 
   AFTER UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here

	INSERT INTO API_DHS_NOTIFICATION_LIST(FORTID, EVENT, DATEMODIFIED)
	SELECT i.ID, 'UPD', GETDATE()
	FROM inserted i
	join deleted d on d.ID = i.ID
	where (
		(i.STATUS <> d.STATUS)
		or (i.ANTIKCASH <> d.ANTIKCASH)
		or (i.ANTIKEPIT <> d.ANTIKEPIT)
		or (i.ANTIKSYNAL <> d.ANTIKSYNAL)
		or (i.ANTIKOTHER <> d.ANTIKOTHER)
		or (i.IFPARALAVIANTIK <> d.IFPARALAVIANTIK)
		or (i.DATEPARALANTIK <> d.DATEPARALANTIK)
		
	) and i.ID not in (
		select distinct fortid from API_DHS_NOTIFICATION_LIST where isnull(IFSENT, 0) = 0
	)
		


END

GO

---END SCRIPT 1742
