CREATE PROCEDURE InserttoAarAlternativeNames (
	@Name NVARCHAR(50),
	@ZipCode NVARCHAR(10)

) AS
	
BEGIN
	SET @ZipCode = REPLACE(@ZipCode, ' ', '');

	with data as (select @Name as [FreeText], @ZipCode as [FreeZip])
	merge AarAlternativeNames t
	using data s
		on s.[FreeText] = t.[FreeText]
		and s.[FreeZip] = t.[FreeZip]
	when not matched by target
	then insert ([FreeText], [FreeZip]) values (@Name, @ZipCode);
END

GO

