ALTER VIEW PARASTATIKAANARECEIPTVIEW 
AS 
SELECT 
PAR.ID, 
PAR.IDRECEIPT, 
KP.DESCR PARASTRECEIPT, 
LTRIM(RTRIM(R.SEIRA)) + CAST(R.DOCNO AS NVARCHAR(15)) NOPARASTRECEIPT, 
R.DATEPRINT DATEPRINTRECEIPT, 
PAR.POSO, 
PAR.IDVOH, 
F.PARASTATIKO PARASTATIKO, 
LTRIM(RTRIM(F.SEIRA)) + CAST(F.NOPARAST AS NVARCHAR(15)) NOPARASTATIKOU, 
F.DATEPRINT DATEPRINTPARASTATIKO, 
F.SUMPOSO POSOPAR,
F.ENTOLEASDESCR,
F.APOSTOLEASDESCR,
F.PARALISPTISDESCR,
PAR.IF_FORTOTIKI,
PAR.IF_VOH, 
PAR.IF_ESODO 
FROM PARASTATIKA_ANA_RECEIPT PAR INNER JOIN RECEIPTS R ON R.ID = 
PAR.IDRECEIPT INNER JOIN KINDPARASTATIKON KP ON KP.ID = R.IDKINDPARAST INNER JOIN FORTOTIKES F ON F.ID = PAR.IDVOH 
WHERE PAR.IF_FORTOTIKI = 1  --ORDER BY PAR.ID ASC

UNION
SELECT 
PAR.ID, 
PAR.IDRECEIPT, 
KP.DESCR PARASTRECEIPT, 
LTRIM(RTRIM(R.SEIRA)) + CAST(R.DOCNO AS NVARCHAR(15)) NOPARASTRECEIPT, 
R.DATEPRINT DATEPRINTRECEIPT, 
PAR.POSO, 
PAR.IDVOH, 
F.PARASTATIKO PARASTATIKO, 
LTRIM(RTRIM(F.SEIRA)) + CAST(F.NOPARAST AS NVARCHAR(15)) NOPARASTATIKOU, 
F.DATEPRINT DATEPRINTPARASTATIKO, 
F.SUMPOSO POSOPAR,
F.CustDescr ENTOLEASDESCR,
F.APOSTOLEASDESCR,
F.PARALISPTISDESCR,
PAR.IF_FORTOTIKI,
PAR.IF_VOH, 
PAR.IF_ESODO 
FROM PARASTATIKA_ANA_RECEIPT PAR INNER JOIN RECEIPTS R ON R.ID = 
PAR.IDRECEIPT INNER JOIN KINDPARASTATIKON KP ON KP.ID = R.IDKINDPARAST INNER JOIN VOH F ON F.ID = PAR.IDVOH 
WHERE PAR.IF_VOH = 1  --ORDER BY PAR.ID ASC

UNION
SELECT 
PAR.ID, 
PAR.IDRECEIPT, 
KP.DESCR PARASTRECEIPT, 
LTRIM(RTRIM(R.SEIRA)) + CAST(R.DOCNO AS NVARCHAR(15)) NOPARASTRECEIPT, 
R.DATEPRINT DATEPRINTRECEIPT,  
PAR.POSO, 
PAR.IDVOH, 
F.PARASTATIKO PARASTATIKO, 
LTRIM(RTRIM(F.SEIRA)) + CAST(F.NOPARAST AS NVARCHAR(15)) NOPARASTATIKOU, 
F.DATEPRINT DATEPRINTPARASTATIKO,
F.SUMPOSO POSOPAR,
F.EPON ENTOLEASDESCR,
'' AS APOSTOLEASDESCR,
'' AS PARALISPTISDESCR,
PAR.IF_FORTOTIKI,
PAR.IF_VOH, 
PAR.IF_ESODO 
FROM PARASTATIKA_ANA_RECEIPT PAR INNER JOIN RECEIPTS R ON R.ID = 
PAR.IDRECEIPT INNER JOIN KINDPARASTATIKON KP ON KP.ID = R.IDKINDPARAST INNER JOIN ESODA F ON F.ID = PAR.IDVOH 
WHERE PAR.IF_ESODO = 1  --ORDER BY PAR.ID ASC

GO

