ALTER view [dbo].[FORTOTIKES_WEB_STATUS_HISTORY] as
select 
	FSH.ID,
	case DS.IFPARADOSI 
		WHEN 1 THEN FORT.DATEPARAD
		ELSE DATE
	END AS 	DATE,
	FSH.FORT_ID,
	FSH.NO_EXT_ORDER,
	DS.DESCR,
	CASE
		WHEN (DS.IFPARALAVI=1 OR DS.IFEKDOSI=1) THEN KENTRIKO.Eponimia + ' - ' + YPOKAT.Eponimia
		WHEN DS.IFSEKAA=1 THEN 'ΟΔΗΓΟΣ: ' + DRV_KAA.LastName + ' ' + DRV_KAA.FirstName
		WHEN (DS.IFSELISTA=1 OR DS.IFEPANADR=1) THEN 'ΟΔΗΓΟΣ: ' + DRV_LISTA.LastName + ' ' + DRV_LISTA.FirstName
		WHEN (DS.IFAKIROSI=1 OR DS.IFPARADOSI=1 OR DS.IFEPISTROFI=1) THEN NULL
		WHEN DS.IFPRK=1 THEN PRK.Eponimia
	END [ContactPerson],
	CASE
		WHEN (DS.IFPARALAVI=1 OR DS.IFEKDOSI=1) THEN YPOKAT.Tel
		WHEN DS.IFSEKAA=1 THEN DRV_KAA.Tel
		WHEN (DS.IFSELISTA=1 OR DS.IFEPANADR=1) THEN ISNULL(DRV_LISTA.Tel, '')
		WHEN (DS.IFAKIROSI=1 OR DS.IFPARADOSI=1 OR DS.IFEPISTROFI=1) THEN NULL
		WHEN DS.IFPRK=1 THEN PRK.Tel
	END [ContactNumber]
	
FROM FORT_STATUS_HISTORY FSH
JOIN DOC_STATUS DS ON DS.ID = FSH.STATUS_ID
JOIN FORTOTIKES FORT ON FORT.ID = FSH.FORT_ID
LEFT JOIN FORTOTIKES_ANA_KAA FAK ON FAK.IDFORTOTIKIS = FORT.ID
LEFT JOIN KAA ON KAA.ID = FAK.IDKAA
LEFT JOIN ODIGOI DRV_KAA ON DRV_KAA.LastName + ' ' + DRV_KAA.FirstName = KAA.DRIVER and DRV_KAA.ifDelete=0

LEFT JOIN FORTOTIKES_ANA_LISTA FAL ON FAL.IDFORTOTIKIS = FORT.ID
LEFT JOIN LISTESDIANOMIS LISTA ON LISTA.ID = FAL.IDLISTAS
LEFT JOIN ODIGOI DRV_LISTA ON DRV_LISTA.LastName + ' ' + DRV_LISTA.FirstName = LISTA.DRIVER and DRV_LISTA.ifDelete=0

LEFT JOIN PRAKTOREIA PRK ON PRK.ID = FORT.IDPRAKTOREIO


JOIN COMPANIES KENTRIKO 
	ON KENTRIKO.IFYPOKATASTHMATA = 1 AND KENTRIKO.IFYPOKATASTHMA = 0 AND KENTRIKO.ID = FORT.IDCOMPANY
	
JOIN COMPANIES YPOKAT ON YPOKAT.ID = FORT.IDYPOKATASTIMA


GO


---END SCRIPT 1751
