CREATE VIEW [dbo].[AADE_CHECKTABLE_VOH_YPHRESIES] AS
with analyshxreoseon as (
	select
		idvoh,
		if_to_fortotiki,
		if_to_voh,
		SUM(
			CASE POSO
				WHEN 0 THEN 0
				ELSE 1
			END
		) noxreoseon,
		SUM(POSO) POSO,
		SUM(TAXIS) TAXIS,
		SUM(SUMPOSO) SUMPOSO
	from XREOSISANADELTIO
	group by idvoh, IF_TO_FORTOTIKI, IF_TO_VOH
)

select
	parastatiko.ID,
	dateprint,
	'voh yphresia' [typos],
	parastatiko.POSO [POSO-PARASTATIKO],
	ax.noxreoseon,
	ax.POSO [POSO-ANALYSH],
	ax.POSO-parastatiko.POSO [POSO-DIAFORA],
	parastatiko.TAXIS [TAXIS-PARASTATIKO],
	ax.TAXIS [TAXIS-ANALYSH],
	ax.TAXIS-parastatiko.TAXIS [TAXIS-DIAFORA],
	parastatiko.SUMPOSO [SUMPOSO-PARASTATIKO],
	ax.SUMPOSO [SUMPOSO-ANALYSH],
	ax.SUMPOSO-parastatiko.SUMPOSO [SUMPOSO-DIAFORA]
from VOH parastatiko
join KINDPARASTATIKON kp on kp.ID = parastatiko.IDPARAST
join analyshxreoseon ax on ax.IDVOH = parastatiko.ID and ax.IF_TO_VOH = 1
where ( 
	ABS(ax.POSO-parastatiko.POSO) > 0
	OR ABS(ax.TAXIS-parastatiko.TAXIS) > 0
	OR ABS(ax.SUMPOSO-parastatiko.SUMPOSO) > 0
) and kp.KindKINISIS = 1


-- union me ta antistoixa gia voh tpy


GO


---END SCRIPT 1760
