IF ABS(@XREOSEIS_TAXIS - @DELTIO_CORRECT_TAXIS) > 0
	print(CONVERT(NVARCHAR, @IDVOH) + ' ' + 'Σφάλμα Περίπτωση #2.2 -> ' + CONVERT(VARCHAR, @XREOSEIS_TAXIS) + ' / ' + CONVERT(VARCHAR, @DELTIO_CORRECT_TAXIS))

IF ABS(@XREOSEIS_SUM - @DELTIO_SUM) > 0
	print(CONVERT(NVARCHAR, @IDVOH) + ' ' + 'Σφάλμα Περίπτωση #2.3')



-- Αν δεν ειναι σωστο το αθροισμα των μικτων, ας ξεκινήσουμε από εκει.
-- Θα μεταβάλλει τα κόμιστρα, το μικτό ποσό των κομίστρων, έτσι ώστε να ταιριάζει με το σύνολο του παραστατικού.

IF ABS(@XREOSEIS_SUM - @DELTIO_SUM) > 0
BEGIN
	print(CONVERT(NVARCHAR, @IDVOH) + ' ' + 'Σφάλμα Περίπτωση #2.4');
	
	
	IF @IDXREOSISKOMISTRONDELTIOU = 0
		print(CONVERT(NVARCHAR, @IDVOH) + ' ' + 'ΔΕΝ ΕΧΕΙ ΚΟΜΙΣΤΡΑ!');
	ELSE 
	BEGIN
		--update στην μεταβλητη
		UPDATE @XREOSEISDELTIOU 
			SET SUMPOSO = SUMPOSO + (@DELTIO_SUM - @XREOSEIS_SUM)
		WHERE ID = @IDXREOSISKOMISTRONDELTIOU;

		--update πισω στον πινακα
		UPDATE XAD SET SUMPOSO = XADUPDATED.SUMPOSO
		FROM XREOSISANADELTIO XAD
		JOIN @XREOSEISDELTIOU XADUPDATED ON XADUPDATED.ID = XAD.ID
		WHERE XAD.ID = @IDXREOSISKOMISTRONDELTIOU;

	END
END

-- ΥΠΟ ΣΥΖΗΤΗΣΗ
UPDATE VOH SET TAXIS = @XREOSEIS_TAXIS WHERE ID = @IDVOH;

--

-- STEP 3 
-- Παμε τώρα να φτιάξουμε και καθαρά/ΦΠΑ στην κάθε χρέωση, αφου τα μικτά της μάλλον είναι ΟΚ...
-- ΜΑΛΑΚΑ


UPDATE @XREOSEISDELTIOU SET POSO = ROUND(SUMPOSO / (0.01 * (100 + TAXISPERCENTXREOSIS)), 2);
UPDATE @XREOSEISDELTIOU SET TAXIS = SUMPOSO - POSO;


UPDATE XAD
	SET XAD.SUMTAXIS = XAD_CORRECTED.TAXIS,
		XAD.TELTIMI = XAD_CORRECTED.POSO
FROM GRAMMESVOH XAD
JOIN @XREOSEISDELTIOU XAD_CORRECTED on XAD_CORRECTED.ID = XAD.ID -- join αντι για UPDATE .... WHERE ....




-- STEP 4
-- ΦΑΚ ΓΙΟΥ
-- ΔΙΟΡΘΩΣΗ ΤΗΣ ΜΑΛΑΚΙΑΣ ΜΙΚΤΟ 1.50 -> ΚΑΘΑΡΟ 1.22 (ΕΙΝΑΙ 1.21 ...)

-- Ξανα-διαβασμα των χρεωσεων αφου τις εχουμε ηδη γαμησει σε ολα τα προηγουμενα steps


SELECT 
	@XREOSEIS_POSO = SUM(POSO),
	@XREOSEIS_TAXIS = SUM(TAXIS),
	@XREOSEIS_SUM = SUM(SUMPOSO)
FROM @XREOSEISDELTIOU;


IF 
	ABS(@XREOSEIS_POSO - @DELTIO_POSO) = ABS(@XREOSEIS_TAXIS - @DELTIO_TAXIS) 
	AND ABS(@XREOSEIS_POSO - @DELTIO_POSO) > 0
	AND ABS(@XREOSEIS_SUM - @DELTIO_SUM) = 0
BEGIN
	print('deltio - poso: ' + convert(varchar, @deltio_poso))
	print('deltio - taxis: ' + convert(varchar, @deltio_taxis))
	print('xreoseis - poso: ' + convert(varchar, @xreoseis_poso))
	print('xreoseis - taxis: ' + convert(varchar, @xreoseis_taxis))

	--UPDATE XREOSISANADELTIO 
	--	SET POSO = POSO + (@DELTIO_POSO - @XREOSEIS_POSO),
	--		TAXIS = TAXIS + (@DELTIO_TAXIS - @XREOSEIS_TAXIS)
	--WHERE ID = @IDXREOSISKOMISTRONDELTIOU

	print('Σφάλμα Περίπτωση - #4.1')

END




GO


---END SCRIPT 1762
