ALTER VIEW [dbo].[AADE_CANCELATION_INVOICES] AS
SELECT
	FORT.ID INVOICEID,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	FORT.DATEPRINT,
	AKYROMENO.AADE_MARK CANCELLED_INVOICE_MARK,
	FORT.IF_ENIM_AADE
FROM FORTOTIKES FORT
JOIN FORTOTIKES AKYROMENO ON AKYROMENO.ID = FORT.ID_CANCELLATION
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 1
AND AKYROMENO.IF_ENIM_AADE = 1
AND AKYROMENO.AADE_MARK IS NOT NULL
UNION
SELECT
	VOH.ID INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	VOH.DATEPRINT,
	AKYROMENO.AADE_MARK CANCELLED_INVOICE_MARK,
	VOH.IF_ENIM_AADE
FROM VOH 
JOIN VOH AKYROMENO ON AKYROMENO.ID = VOH.ID_CANCELLATION
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 1
AND AKYROMENO.IF_ENIM_AADE = 1
AND AKYROMENO.AADE_MARK IS NOT NULL





