ALTER PROCEDURE [dbo].[AADE_FIX_POSA_FORT] (
@IDFORT INT)
AS



SET NOCOUNT ON;


--DECLARE @IDFORT INT;
--SET @IDFORT = 886647;







DECLARE @COUNTXREOSEISDELTIOU INT;

DECLARE @XREOSEISDELTIOU TABLE (
	ID INT,
	IDTYPOUXREOSIS INT,
	TAXISPERCENTXREOSIS NUMERIC(18,2),
	IFKOMISTRA BIT,
	POSO NUMERIC(18,2),
	TAXIS NUMERIC(18,2),
	SUMPOSO NUMERIC(18,2)
)

DECLARE @DELTIO_POSO NUMERIC(18,2);
DECLARE @DELTIO_TAXIS NUMERIC(18,2);
DECLARE @DELTIO_SUM NUMERIC(18,2);


DECLARE @DELTIO_TAXISPERCENT NUMERIC(18,2);

DECLARE @DELTIO_CORRECT_POSO NUMERIC(18,2);
DECLARE @DELTIO_CORRECT_TAXIS NUMERIC(18,2);

DECLARE @IDXREOSISKOMISTRONDELTIOU INT;
DECLARE @XREOSEIS_POSO NUMERIC(18,2);
DECLARE @XREOSEIS_TAXIS NUMERIC(18,2);
DECLARE @XREOSEIS_SUM NUMERIC(18,2);



-- STEP 0
-- ΔΙΑΒΑΣΜΑ ΔΕΔΟΜΕΝΩΝ






SELECT 
	@DELTIO_POSO = POSO,
	@DELTIO_TAXIS = TAXIS,
	@DELTIO_SUM = SUMPOSO
FROM FORTOTIKES
WHERE ID = @IDFORT;


SELECT @DELTIO_TAXISPERCENT = KINDPARASTATIKON.TAXISPERCENT
FROM KINDPARASTATIKON
JOIN FORTOTIKES ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID
WHERE FORTOTIKES.ID = @IDFORT;


DELETE FROM @XREOSEISDELTIOU;
INSERT INTO @XREOSEISDELTIOU(ID, IDTYPOUXREOSIS, TAXISPERCENTXREOSIS, IFKOMISTRA, POSO, TAXIS, SUMPOSO)
SELECT 
	XAD.ID, 
	XAD.IDXREOSIS, 
	XR.TAXISPERCENT, 
	XR.ifKomistra,
	XAD.POSO, 
	XAD.TAXIS, 
	XAD.SUMPOSO
FROM XREOSISANADELTIO XAD 
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
WHERE XAD.IDVOH = @IDFORT 
AND XAD.IF_TO_FORTOTIKI = 1 
AND ABS(XAD.POSO) + ABS(XAD.TAXIS) + ABS(XAD.SUMPOSO) > 0

	
SELECT @IDXREOSISKOMISTRONDELTIOU = ID
FROM @XREOSEISDELTIOU WHERE IFKOMISTRA = 1;


SELECT
	@COUNTXREOSEISDELTIOU = COUNT(ID),
	@XREOSEIS_POSO = SUM(POSO),
	@XREOSEIS_TAXIS = SUM(TAXIS),
	@XREOSEIS_SUM = SUM(SUMPOSO)
FROM @XREOSEISDELTIOU;


--
-- ΚΟΠΑΝΟΙ
--

IF ABS(@XREOSEIS_SUM - @DELTIO_SUM) > 0.01 * @COUNTXREOSEISDELTIOU
	OR ABS(@XREOSEIS_POSO - @DELTIO_POSO) > 0.01 * @COUNTXREOSEISDELTIOU
	OR ABS(@XREOSEIS_TAXIS - @DELTIO_TAXIS) > 0.01 * @COUNTXREOSEISDELTIOU
BEGIN
	print('Σφάλμα Περίπτωση #0.0')
	SELECT 
		@DELTIO_POSO = @XREOSEIS_POSO,
		@DELTIO_SUM = @XREOSEIS_SUM,
		@DELTIO_TAXIS = @XREOSEIS_TAXIS;

	UPDATE FORTOTIKES SET
		POSO = @DELTIO_POSO,
		SUMPOSO = @DELTIO_SUM,
		TAXIS = @DELTIO_TAXIS
	WHERE ID = @IDFORT;
END


-- STEP 1
-- Επιβεβαίωση ότι στο σύνολο του παραστατικού είναι σωστά τα νούμερα 
-- ΜΑΛΑΚΑ


IF @DELTIO_POSO + @DELTIO_TAXIS <> @DELTIO_SUM
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #1.1')


--SET @DELTIO_CORRECT_POSO = ROUND( @DELTIO_SUM / (0.01 * (100 + @DELTIO_TAXISPERCENT)), 2);
--SET @DELTIO_CORRECT_TAXIS = @DELTIO_SUM - @DELTIO_CORRECT_POSO;

SET @DELTIO_CORRECT_POSO = @DELTIO_POSO;
SET @DELTIO_CORRECT_TAXIS = @DELTIO_TAXIS;

IF ABS(@DELTIO_POSO - @DELTIO_CORRECT_POSO) > 0
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #1.2')

IF ABS(@DELTIO_TAXIS - @DELTIO_CORRECT_TAXIS) > 0
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #1.3')


--IF ABS(@DELTIO_POSO - @DELTIO_CORRECT_POSO) + ABS(@DELTIO_TAXIS - @DELTIO_CORRECT_TAXIS) > 0
--BEGIN	
--	UPDATE FORTOTIKES SET
--		POSO = @DELTIO_CORRECT_POSO,
--		TAXIS = @DELTIO_CORRECT_TAXIS
--	WHERE ID = @IDFORT;

--	SET @DELTIO_POSO = @DELTIO_CORRECT_POSO;
--	SET @DELTIO_TAXIS = @DELTIO_CORRECT_TAXIS;

--END

-- STEP 2
-- Πάμε να δούμε αν το άθροισμα των ποσών από τις χρεώσεις μας κάνει το ίδιο με τα σύνολα του παραστατικού
-- ΜΑΛΑΚΑ


IF ABS(@XREOSEIS_POSO - @DELTIO_CORRECT_POSO) > 0
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #2.1')

IF ABS(@XREOSEIS_TAXIS - @DELTIO_CORRECT_TAXIS) > 0
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #2.2 -> ' + CONVERT(VARCHAR, @XREOSEIS_TAXIS) + ' / ' + CONVERT(VARCHAR, @DELTIO_CORRECT_TAXIS))

IF ABS(@XREOSEIS_SUM - @DELTIO_SUM) > 0
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #2.3')



-- Αν δεν ειναι σωστο το αθροισμα των μικτων, ας ξεκινήσουμε από εκει.
-- Θα μεταβάλλει τα κόμιστρα, το μικτό ποσό των κομίστρων, έτσι ώστε να ταιριάζει με το σύνολο του παραστατικού.

IF ABS(@XREOSEIS_SUM - @DELTIO_SUM) > 0
BEGIN
	print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'Σφάλμα Περίπτωση #2.4');
	
	
	IF @IDXREOSISKOMISTRONDELTIOU = 0
		print(CONVERT(NVARCHAR, @IDFORT) + ' ' + 'ΔΕΝ ΕΧΕΙ ΚΟΜΙΣΤΡΑ!');
	ELSE 
	BEGIN
