-- Ξανα-διαβασμα των χρεωσεων αφου τις εχουμε ηδη γαμησει σε ολα τα προηγουμενα steps


SELECT 
	@XREOSEIS_POSO = SUM(POSO),
	@XREOSEIS_TAXIS = SUM(TAXIS),
	@XREOSEIS_SUM = SUM(SUMPOSO)
FROM @XREOSEISDELTIOU;


IF 
	ABS(@XREOSEIS_POSO - @DELTIO_POSO) = ABS(@XREOSEIS_TAXIS - @DELTIO_TAXIS) 
	AND ABS(@XREOSEIS_POSO - @DELTIO_POSO) > 0
	AND ABS(@XREOSEIS_SUM - @DELTIO_SUM) = 0
BEGIN
	print('deltio - poso: ' + convert(varchar, @deltio_poso))
	print('deltio - taxis: ' + convert(varchar, @deltio_taxis))
	print('xreoseis - poso: ' + convert(varchar, @xreoseis_poso))
	print('xreoseis - taxis: ' + convert(varchar, @xreoseis_taxis))

	UPDATE XREOSISANADELTIO 
		SET POSO = POSO + (@DELTIO_POSO - @XREOSEIS_POSO),
			TAXIS = TAXIS + (@DELTIO_TAXIS - @XREOSEIS_TAXIS)
	WHERE ID = @IDXREOSISKOMISTRONDELTIOU

	print('Σφάλμα Περίπτωση - #4.1')

END



