create PROCEDURE [dbo].[AADE_FIX_POSA_VOH_SALES_V2] (
	@IDVOH INT
) AS

BEGIN

	SET NOCOUNT ON;



	DECLARE 
		@DELTIO_POSO NUMERIC(18,2),
		@DELTIO_TAXIS NUMERIC(18,2),
		@DELTIO_SUMPOSO NUMERIC(18,2);

	DECLARE @GRAMMESXREOSIS TABLE (
		IDGV INT,
		POSO NUMERIC(18,2),
		TAXIS NUMERIC(18,2),
		SUMPOSO NUMERIC(18,2) 
	)

	DECLARE 
		@GRAMMES_POSO NUMERIC(18,2),
		@GRAMMES_TAXIS NUMERIC(18,2),
		@GRAMMES_SUMPOSO NUMERIC(18,2)

	DECLARE @GRAMMESVOH INT;
		
	SELECT 
		@DELTIO_POSO = POSO,
		@DELTIO_TAXIS = TAXIS,
		@DELTIO_SUMPOSO = SUMPOSO
	FROM VOH
	WHERE ID = @IDVOH;

	INSERT INTO @GRAMMESXREOSIS (IDGV, POSO, TAXIS, SUMPOSO)
	SELECT ID, TELTIMI, SUMTAXIS, SUMPOSO FROM GRAMMESVOH WHERE IDVOH = @IDVOH;

	SELECT @GRAMMESVOH = COUNT(ID) FROM GRAMMESVOH WHERE IDVOH = @IDVOH;

	SELECT 
		@GRAMMES_POSO = SUM(POSO),
		@GRAMMES_TAXIS = SUM(TAXIS),
		@GRAMMES_SUMPOSO = SUM(SUMPOSO)
	FROM @GRAMMESXREOSIS;




	IF ( 
			ABS(@GRAMMES_POSO - @DELTIO_POSO)
			+ ABS(@GRAMMES_TAXIS - @DELTIO_TAXIS)
			+ ABS(@GRAMMES_SUMPOSO - @DELTIO_SUMPOSO)
		) > @GRAMMESVOH * 0.01
	BEGIN
		print('Σφάλμα #1');
		SET @DELTIO_POSO = @GRAMMES_POSO;
		SET @DELTIO_TAXIS = @GRAMMES_TAXIS;
		SET @DELTIO_SUMPOSO = @GRAMMES_SUMPOSO;

		UPDATE VOH SET
			POSO = @DELTIO_POSO,
			TAXIS = @DELTIO_TAXIS,
			SUMPOSO = @DELTIO_SUMPOSO
		WHERE ID = @IDVOH;
	END
		

	IF ( 
			ABS(@GRAMMES_POSO - @DELTIO_POSO)
			+ ABS(@GRAMMES_TAXIS - @DELTIO_TAXIS)
			+ ABS(@GRAMMES_SUMPOSO - @DELTIO_SUMPOSO)
		) <= @GRAMMESVOH * 0.01
	BEGIN
		print('Σφάλμα #2');
		
		DECLARE @IDPROTISGRAMMISVOH INT = (SELECT MIN(IDGV) FROM @GRAMMESXREOSIS);

		UPDATE GRAMMESVOH SET 
			TELTIMI = TELTIMI + (@DELTIO_POSO - @GRAMMES_POSO),
			SUMTAXIS = SUMTAXIS + (@DELTIO_TAXIS - @GRAMMES_TAXIS),
			SUMPOSO = SUMPOSO + (@DELTIO_SUMPOSO - @GRAMMES_SUMPOSO)
		WHERE ID = @IDPROTISGRAMMISVOH 
	END
END
GO


---END SCRIPT 1772
