---NEW SCRIPT 1774

ALTER view [dbo].[AADE_CHECKTABLE_SALES] AS 
with grammesvohsum as (
	select 
		IDVOH,
		SUM(CONVERT(NUMERIC(18,2), TELTIMI)) TELTIMI,
		SUM(CONVERT(NUMERIC(18,2), SUMTAXIS)) SUMTAXIS,
		SUM(CONVERT(NUMERIC(18,2), SUMPOSO)) SUMPOSO
	from GRAMMESVOH
	group by IDVOH
)

select
	VOH.ID,
	VOH.POSO [DELTIO_POSO],
	VOH.TAXIS [DELTIO_TAXIS],
	VOH.SUMPOSO [DELTIO_SUM],
	gvsum.TELTIMI [GRAMMES_POSO],
	gvsum.SUMTAXIS [GRAMMES_TAXIS],
	gvsum.SUMPOSO [GRAMMES_SUM],
	gvsum.TELTIMI - VOH.POSO [POSO_DIFF],
	gvsum.SUMTAXIS - VOH.TAXIS [TAXIS_DIFF],
	gvsum.SUMPOSO - VOH.SUMPOSO [SUM_DIFF]
from VOH
join KINDPARASTATIKON on KINDPARASTATIKON.ID = VOH.IDPARAST and KINDPARASTATIKON.KindKINISIS = 5 and KINDPARASTATIKON.IF_ENIMEROSI_AADE = 1
join grammesvohsum gvsum on gvsum.IDVOH = VOH.ID
where (
	abs(VOH.POSO - gvsum.TELTIMI) > 0
	or ABS(VOH.TAXIS - gvsum.SUMTAXIS) > 0
	or ABS(VOH.SUMPOSO - gvsum.SUMPOSO) > 0
)


GO

---END SCRIPT 1774
