go
UPDATE KINDOFPAYMENTS SET AADE_CODE=3 WHERE DESCR LIKE '%ετρητ%'
go
UPDATE KINDOFPAYMENTS SET AADE_CODE=4 WHERE DESCR LIKE '%πιταγ%'
go
UPDATE KINDOFPAYMENTS SET AADE_CODE=5 WHERE DESCR LIKE '%πιστωσ%'
go




