ALTER view [dbo].[SYNARMOLOGISI_DIANOMI]
as
	select 
		synarm.id [vohsynarmid],
		metaf.id [vohmetafid],
		fort.id [fortid],
		kaa.id [idkaa],
		ld.id [idlistas]
	from voh synarm 
	join KINDPARASTATIKON kpsynarm on kpsynarm.id = synarm.idparast
	left join voh metaf 
		on metaf.arrival = synarm.arrival 
		and metaf.id <> synarm.id 
		and metaf.IDYPOKATASTIMA = synarm.IDYPOKATASTIMA
	left join KINDPARASTATIKON kpmetaf on kpmetaf.id = metaf.IDPARAST
	left join fortotikes fort on fort.EXT_BARCODE = metaf.EXT_BARCODE and fort.ifDelete = 0
	left join ( 
		select 
			fak.IDFORTOTIKIS, 
			max(fak.id) maxfakid 
			from FORTOTIKES_ANA_KAA fak 
			group by fak.idfortotikis	
	) t1 on t1.IDFORTOTIKIS = fort.id
	left join MAX_FORTOTIKES_ANA_KAA fak on fak.id = t1.maxfakid
	left join KAA on KAA.id = fak.idkaa

	left join ( 
		select 
			fal.IDFORTOTIKIS, 
			max(fal.id) maxfalid 
			from FORTOTIKES_ANA_LISTA fal
			group by fal.idfortotikis	
	) t2 on t2.IDFORTOTIKIS = fort.id
	left join MAX_FORTOTIKES_ANA_LISTA fal on fal.id = t2.maxfalid
	left join LISTESDIANOMIS ld on ld.id = fal.idlistas

	where 
		synarm.ifdelete = 0
		-- apo edw
		and synarm.ARRIVAL is not null
		and metaf.ARRIVAL is not null
		and len(synarm.arrival) > 5 
		and metaf.ifDelete = 0
		-- ews edw
		and kpsynarm.IF_EDSYNARMOL = 1
		and (kpmetaf.IF_EDMETAFORAS = 1 or kpmetaf.if_EDMETAFORAS is null)
GO


---END SCRIPT 1785
