---NEW SCRIPT 1787


exec sp_rename 'TIMOL_VOH_VIEW','TIMOL_VOH_VIEW_OLD'
GO

create VIEW [dbo].[TIMOL_VOH_VIEW]
AS

with grammesvohsum as (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		isnull(SUM(TEMAXIA),0) countid,
		isnull(sum(BAROS),0) baros,
		isnull(sum(KYBIKA),0) kybika,
		isnull(SUM(SUMPOSO),0) AXIA,
		MIN(TIMDA) TIMDA,
		MIN(PERIEXOMENO) PERIEXOMENO
	from grammesvoh group by idvoh
),
grammesfortotikissum as(
		select
			IDVOH,
			ISNULL(SUM(TEMAXIA),0) as temaxia,
			isnull(sum(BAROS),0) as baros,
			ISNULL(SUM(KYBIKA),0) as kybika,
			ISNULL(SUM(SUMPOSO),0) AS AXIA,
			MIN(TIMDA) as timda,
			MIN(PERIEXOMENO) as periexomeno,
			MIN(u.UntName) as untname
		
		from GRAMMESFORTTIKIS gf
		left join Units u on u.UntID=gf.SYSKEVASIA
		group by idvoh
		
),
xreosisanadeltiosum as (
		select
			IDVOH,
			SUM(SUMPOSO) as sumposo
		
		from XREOSISANADELTIO
		where IF_TO_FORTOTIKI=1
		group by IDVOH
),
headerfortotikissum as (
		select
			idfort,
			SUM(komistra) as komistra,
			SUM(dikaiomafortotikis) as dikaiomafortotikis,
			SUM(otherxreosis) as otherxreosis,
			SUM(olikosynoloxreoseonfort) as olikosynoloxreoseonfort,
			SUM(ergatika) as ergatika
			
		from HEADERFORTOTIKIS
		group by IDFORT
),
grammes_assembly as (
			select
				IDVOH,
				SUM(iftransport) iftransport,
				SUM(ifassembly) ifassembly,
				SUM(ifplacement) ifplacement,
				SUM(ifdisassembly) ifdisassembly
			
			from GRAMMESVOH
			group by IDVOH
)

select
	v.ID,
	v.DATEPRINT,
	kp.Code,
	v.PARASTATIKO,
	v.SEIRA,
	CONVERT(int,v.NOPARAST)										as NOPARAST,
	v.NOPARASTDELTIOUDIANOMIS,
	v.NOPARASTDELTIOUAPOSTOLIS,
	v.OXIMA,
	v.OMADPROORISMOS,
	CASE 
		ISNULL(0, v.IFXRENTOL) * 1
		+ ISNULL(0, v.IFXRAPOST) * 2
		+ ISNULL(0, v.IFXRPARAL) * 4
		+ ISNULL(0, v.IFXRTRITOU) * 8

		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		WHEN 8 THEN 'ΤΡΙΤΟΣ'
		ELSE 'ΑΓΝΩΣΤΟΣ'
	END															AS XREOYMENOS,
	 v.apostoleasdescr,
	 v.paralisptisdescr,
	 v.entoleasdescr,
	 v.antapokritisdescr,
	 v.tritosdescr,
	 gf.TIMDA													as TIMDA,
	 v.poso,
     v.taxis,
     v.sumposo,
     gf.temaxia													as TEMAXIA,
     gf.baros													as BAROS,
     gf.kybika													as KYBIKA,
     gf.untname													as SYSKEVASIA,
     case 
		ISNULL(v.ifprepay,0)		
		when 1 then xd.sumposo 
	 else 0
	 end														as XREOSIPROPLIROMENES,
	case 
		ISNULL(v.IFOFEILOMENI,0)		
		when 1 then xd.sumposo 
	 else 0
	 end														as XREOSIOFEILOMENES,
	 case
		ISNULL(V.ifprepay,0)
		when 1 then 
			case V.ifcash 
				when 1 then xd.sumposo
				else 0
			end 
		else 0
	end															as XREOSIPROPLIROMENESCASH,
		 case
		ISNULL(V.ifprepay,0)
		when 1 then 
			case V.IFPISTOSI 
				when 1 then xd.sumposo
				else 0
			end 
		else 0
	end															as XREOSIPROPLIROMENESPISTOSI,
	gf.periexomeno												AS PERIEXOMENO,
	v.perioxifortosis,
	v.perioxiparadosis,
	v.comments,
	v.sumantik,
	v.praktoreiodescr,
	v.status,
	CONVERT(VARCHAR, v.dateparad, 102)          AS DATEPARAD,
	v.idapostolea,
	v.idparalipti,
	v.identolea,
	v.idantapokriti,
	v.idtritou,
	v.idpraktoreio,
	CASE ifantikcash
           WHEN 0 THEN 0
           ELSE antikcash
         END                                               AS ANTIKCASH,
         CASE ifantikepit
           WHEN 0 THEN 0
           ELSE antikepit
         END                                               AS ANTIKEPIT,
         CASE ifantiksynal
           WHEN 0 THEN 0
           ELSE antiksynal
         END                                               AS ANTIKSYNAL,
         CASE ifantikother
           WHEN 0 THEN 0
           ELSE antikother
         END                                               AS ANTIKOTHER,
         CASE ifcancelantik
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFCANCELANTIK,
         v.commentsantik,
         v.dateparadosi,
         v.comments2,
         hf.komistra									   AS KOMISTRA,
         hf.dikaiomafortotikis							   AS DIKAIOMAFORTOTIKIS,
         hf.otherxreosis								   AS OTHERXREOSIS,
         hf.olikosynoloxreoseonfort						   AS OLIKOSYNOLOXREOSEONFORT,
         hf.ergatika									   AS ERGATIKA,
         CASE v.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFPREPAY,
         CASE v.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                               AS IFOFEILOMENI,
         gf.AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRENTOL,
         v.kindpaymentdescr,
         v.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                               AS IFXRTRITOU,
         v.ifantikcash,
         v.ifantikepit,
         v.ifantiksynal,
         v.ifantikother,
         v.ifdelete,
         v.ifcancel,
         CONVERT(VARCHAR, v.datecancel, 102)         AS DATECANCEL,
         v.ifparadosi,
         v.aitiologiaparastatikou,
         CONVERT(VARCHAR, v.datefortosis, 102)       AS DATEFORTOSIS,
         v.ifepistrofi,
         CONVERT(VARCHAR, v.dateepistrofis, 102)     AS DATEEPISTROFIS,
         v.aitiologiaepistrofis,
         v.commentsepistrofis,
         v.ifcash,
         v.ifpistosi,
         v.statusdescr,
         v.ypaitios,
         v.ifepanadromologisi,
         v.ifepanekdosi,
         v.ifokepanadromologisi,
         v.noparastantik,
         v.commentsakirosis,
         v.ifeisprantik,
         v.ifparadosiantik,
         v.ifparalaviantik,
         v.commentsparadantik,
         v.commantsparalantik,
         v.commentseisprantik,
         CONVERT(VARCHAR, v.dateparadantik, 102)     AS DATEPARADANTIK,
         CONVERT(VARCHAR, v.dateparalantik, 102)     AS DATEPARALANTIK,
         CONVERT(VARCHAR, v.dateeisprantik, 102)     AS DATEEISPRANTIK,
         v.eispraxasantik,
         v.noparparadantik,
         v.noparasteisprantik,
         v.noparparalantik,
         CONVERT(VARCHAR, v.dateparal, 102)          AS DATEPARAL,
         v.commentsparad,
         v.commantsparal,
         v.timeparalfrom,
         v.timeparalto,
         v.timeparadfrom,
         v.timeparadto,
         CONVERT(VARCHAR, v.datecancelantik, 102)    AS DATECANCELANTIK,
         v.idparast,
         v.taxispercent,
         v.anamexodo,
         v.id                                        AS IDFORTOTIKIS,
         v.afmxreoumenou,
         hdf.asfalistra,
         Round(hdf.taxis, 2)			             AS TAXISXREOSEON,
         hdf.sumposoxrfort,
         hdf.katharo,
         
         apost.epagelma								 AS EPAGAPOST,
         apost.addressstr							 AS ADDRSTRAPOST,
         apost.addressno							 AS ADDRNOAPOST,
         apost.addresstk							 AS TKAPOST,
         apost.addresscity							 AS CITYAPOST,
         apost.addresspref							 AS NOMOSAPOST,
         apost.tel									 AS TELAPOST,
         apost.doy									 AS DOYAPOST,
         
         paral.epagelma                              AS EPAGPARAL,
         paral.addressstr                            AS ADDRSTRPARAL,
         paral.addressno                             AS ADDRNOPARAL,
         paral.addresstk                             AS ADDRTKPARAL,
         paral.addresscity                           AS ADDRCITYPARAL,
         paral.addresspref                           AS ADDRNOMOSPARAL,
         paral.tel                                   AS TELPARAL,
         paral.doy                                   AS DOYPARAL,
         
         entol.epagelma                              AS EPAGENTOL,
         entol.addressstr                            AS ADDRSTRENTOL,
         entol.addressno                             AS ADDRNOENTOL,
         entol.addresstk                             AS ADDRTKENTOL,
         entol.addresscity                           AS ADDRCITYENTOL,
         entol.addresspref                           AS ADDRNOMOSENTOL,
         entol.tel                                   AS TELENTOL,
         entol.doy                                   AS DOYENTOL,
         
         tritos.epagelma                             AS EPAGTR,
         tritos.addressstr                           AS ADDRSTTR,
         tritos.addressno                            AS ADDRNOTR,
         tritos.addresstk                            AS ADDRTKTR,
         tritos.addresscity                          AS ADDRCITYTR,
         tritos.addresspref                          AS ADSTRDRNOMO,
         tritos.tel                                  AS TELTR,
         tritos.doy                                  AS DOYTR,
         
		 v.afmapostolea,
		 v.afmentolea,
		 v.afmparalipti,
		 v.afmtritou,
		 v.afmantapokriti,
		 paral.mobile                                AS MOBILEPARALIPTI,
         entol.mobile                                AS MOBILEENTOLTEA,
         apost.mobile                                AS MOBILEAPOSTOLEA,
         ''                                          AS IDDRIVER,
         ''                                          AS DRIVERDESCR,
         v.idxrhshs,
         v.idcompany,
         v.idypokatastima,
         v.codeparast,
         v.sxetikaparastatika,
         v.idsxetikaparast,
         v.idcustomer,
         v.codecustomer,
         v.custdescr,
         v.arxikoposo,
         v.discount,
         v.discountpercent,
         v.datekinisis,
         v.thetime,
         v.idskoposdiakinisis,
         v.skoposdiakinisis,
         v.country,
         v.driver,
         v.idlistas,
         v.ifisorder,
         v.noorder,
         v.idorder,
         v.ifexoflisi,
         v.codeentolea,
         v.codeapostolea,
         v.codeparalipti,
         v.seiraorder,
         v.dateprintorder,
         v.orderdetails,
         v.if_close,
         v.posoepivar,
         v.taxisepivar,
         v.sumposoepivar,
         v.ext_id,
         v.ext_barcode,
         v.ext_details,
         v.sumdemata,
         v.sumpaletes,
         v.sumstand,
         v.sumbaros,
         v.sumogos,
         v.container,
         v.boat,
         v.exodatriton,
         v.OROFOS,
         v.OROFOSDESCR,
         v.KOUDOUNI,
		 v.NO_EXT_ORDER_IK,
		 
		 
		 
		 parad.PARADOSISE,
		 parad.Eponimia,
		 parad.AddressCity,
		 parad.AddressStr,
		 parad.AddressNo,
		 parad.AddressTK,
		 v.UserCreate,
		 v.UserMod,
		 v.IDKENTROUKOSTOUS,
		 kns.Descr									 as Kentro_Kostous,
		 CASE 
			WHEN gva.iftransport > 0 THEN 1
			ELSE 0
		END [iftransport],
		CASE 
			WHEN gva.ifassembly > 0 THEN 1
			ELSE 0
		END [ifassembly],
		CASE 
			WHEN gva.ifplacement > 0 THEN 1
			ELSE 0
		END [ifplacement],
		CASE 
			WHEN gva.ifdisassembly > 0 THEN 1
			ELSE 0
		END [ifdisassembly],
		v.ARANAFORAS,
		ypok.Eponimia								AS YPOKATASTHMA,
		ypok.AddressStr								AS ADDRESS_YPOKATASTHMA,
		ypok.AddressTK								AS TK_YPOKATASTHMA,
		ypok.AddressCity							AS CITY_YPOKATASTHMA,
		ypok.BARCODE_Prefix							AS BARCODEPREFIX_YPOKAT,
		ypok.EMAIL									AS EMAIL_YPOKATASTHMA

         
         
         			

from VOH v
left join KINDPARASTATIKON kp on kp.ID=v.IDPARAST
left join grammesvohsum gv on gv.IDVOH=v.ID
left join grammesfortotikissum gf on gf.IDVOH=v.ID
left join xreosisanadeltiosum xd on xd.IDVOH=v.ID
left join headerfortotikissum hf on hf.IDFORT=v.ID
left join HEADERFORTOTIKIS hdf on hdf.idfort=v.ID
left join ACCOUNTS apost on apost.id=v.IDAPOSTOLEA
left join ACCOUNTS entol on entol.id=v.IDENTOLEA
left join ACCOUNTS paral on paral.id=v.IDPARALIPTI
left join ACCOUNTS tritos on tritos.id=v.IDTRITOU
left join PARADOSEIS parad  on parad.IDVOH=(select max( id)from VOH)
left join KentraKostous kns on kns.id=v.IDKENTROUKOSTOUS
left join grammes_assembly gva on gva.IDVOH=v.ID
left join COMPANIES ypok on ypok.id=v.IDYPOKATASTIMA


GO

---END SCRIPT 1787
