ALTER PROCEDURE [dbo].[DELETE_RECORDS]
(
	@TheIDS			NVARCHAR(500) = NULL,
	--@THE_DATE		SMALLDATETIME,-- = NULL,
	@THEREASON		NVARCHAR(500) = MULL,
	@THETABLE		NVARCHAR(500) = MULL,
	@UserDel		NVARCHAR(50),
	@DateDel		SMALLDATETIME
)
AS
DECLARE
  @ErrorMessage   varchar(2000)
 ,@ErrorSeverity  tinyint
 ,@ErrorState     tinyint

BEGIN TRY
BEGIN TRANSACTION

declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @TheIDS) 
    WHILE @start < LEN(@TheIDS) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@TheIDS) + 1

	IF (@THETABLE = 'FORTOTIKES')
	BEGIN
	
		UPDATE FORTOTIKES SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) 
		--AND IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA != 1)-- IN (  @TheIDS )
		
		UPDATE RECEIPTS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=	@UserDel,
		DateDel			=	@DateDel   
		WHERE IDVOH  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@TheIDS ) 
		AND IF_TO_FORTOTIKI=1;
		
		UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT IN(SELECT ID FROM RECEIPTS WHERE IDVOH  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) 
		--IN (@theIDS) 
		AND IF_TO_FORTOTIKI =1); 
		
	END;

	IF (@THETABLE = 'VOH')
	BEGIN
		UPDATE VOH SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) 
		--AND IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA != 1)--IN (  @TheIDS )
		
		UPDATE RECEIPTS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=	@UserDel,
		DateDel			=	@DateDel  
		WHERE IDVOH  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@TheIDS ) 
		AND IF_TO_VOH=1;
		UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT IN(SELECT ID FROM RECEIPTS WHERE IDVOH  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@theIDS)
		 AND IF_TO_VOH =1); 
	END;

	IF (@THETABLE = 'RECEIPTS')
	BEGIN
		UPDATE RECEIPTS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
		
		UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@theIDS)
	END;

	IF (@THETABLE = 'PAYMENTS')
	BEGIN
		UPDATE PAYMENTS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
		
		UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@theIDS) 
	END;

	IF (@THETABLE = 'ESODA')
	BEGIN
		UPDATE ESODA SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) 
		--AND IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA != 1)--IN (  @TheIDS )
		
		UPDATE RECEIPTS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=	@UserDel,
		DateDel			=	@DateDel  
		WHERE IDVOH IN (@TheIDS ) AND IF_TO_ESODA=1;
		UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT IN(SELECT ID FROM RECEIPTS WHERE IDVOH  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (@theIDS)
		 AND IF_TO_ESODA =1); 
	END;

	IF (@THETABLE = 'EXODA')
	BEGIN
		UPDATE EXODA SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) 
		--AND IDPARAST IN (SELECT ID FROM KINDPARASTATIKON WHERE IF_ENIMEROSIKARTELA != 1)--IN (  @TheIDS )
		
		--UPDATE RECEIPTS SET ifDelete = 1, DELREASON = @THEREASON  WHERE IDVOH IN (@TheIDS ) AND IF_TO_FORTOTIKI=1;
	 --   UPDATE RECEIPTDETAILS SET ifDelete=1 WHERE IDPAYMENT 
	 --   IN(SELECT ID FROM RECEIPTS WHERE IDVOH IN (@theIDS) AND IF_TO_FORTOTIKI =1); 
	END;

	IF (@THETABLE = 'KAA')
	BEGIN
		UPDATE KAA SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
	END;

	IF (@THETABLE = 'LISTESDIANOMIS')
	BEGIN
		UPDATE LISTESDIANOMIS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
	END;

	IF (@THETABLE = 'LISTA_ANTIKATABOLON')
	BEGIN
		UPDATE LISTA_ANTIKATABOLON SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
	END;

	IF (@THETABLE = 'LISTES_SYGENTROTIKON')
	BEGIN
		UPDATE LISTES_SYGENTROTIKON SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
	END;

	IF (@THETABLE = 'LISTESSYNARMOLOGISIS')
	BEGIN
		UPDATE LISTESSYNARMOLOGISIS SET 
		ifDelete		=	1, 
		DELREASON		=	@THEREASON, 
		UserDel			=  @UserDel,
		DateDel			=	@DateDel
		WHERE ID  = CAST( SUBSTRING(@TheIDS, @start, @end - @start)AS NUMERIC) --IN (  @TheIDS )
	END;

SET @start = @end + 1 
SET @end = CHARINDEX(@coma, @TheIDS, @start)      
END 
    
COMMIT TRANSACTION

END 
END TRY

BEGIN CATCH
    SET @ErrorMessage  = ERROR_MESSAGE()
    SET @ErrorSeverity = ERROR_SEVERITY()
    SET @ErrorState    = ERROR_STATE()
    RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState)

    --BREAK
END CATCH

GO
          
          
---END SCRIPT 1791
