ALTER PROCEDURE [dbo].[updateVOH_ANA_LISTAASS]
	(
	@ID						NUMERIC(18, 0)= NULL,
	@IDLISTAS				NUMERIC(18, 0)= NULL,
	@NoPARASTLISTAS			NVARCHAR(10)= NULL, 
	@IDEMPLOYEE				NUMERIC(18, 0)= NULL, 
	@EMPLOYEE				NVARCHAR(60)= NULL,
	@INSERTVOH				NVARCHAR(MAX)= NULL,
	@DELETEDVOH				NVARCHAR(MAX)= NULL
	)
AS
SET NOCOUNT ON
DECLARE @_STATUS varchar(75)
DECLARE @_STATUSID int
--SET @_STATUS = 'ΣΕ ΚΑΤΑΣΤΑΣΗ ΑΝΑΘΕΣΗΣ'
DECLARE @_NULL varchar(75)
SET @_NULL = ''


SELECT @_STATUS = STATUS, @_STATUSID = IDSTATUS FROM LISTESSYNARMOLOGISIS WHERE ID = @IDLISTAS

IF LEN(@_STATUS) < 3 
BEGIN
	SELECT TOP 1 @_STATUS = DESCR, @_STATUSID = ID FROM DOC_STATUS WHERE IFSELISTAASSEMBLY = 1 
END


EXEC('DELETE FROM VOH_ANA_LISTAASS WHERE  IDLISTAS = ' + @IDLISTAS)
IF LEN(@DELETEDVOH)>0
BEGIN
	EXEC('UPDATE VOH SET NOPARASTLISTASSYNARMOLOGISIS ='''+@_NULL+''', EMPLOYEE = '''', IDEMPLOYEE = NULL WHERE ID IN(' + @DELETEDVOH + ')')
END
--EXEC('DELETE FROM dbo.FORTOTIKES_ANA_KAA WHERE IDFORTOTIKIS IN(' + @DELETEDFORTOTIKES + ') AND IDKAA = '+@IDKAA)
EXEC('UPDATE VOH SET NOPARASTLISTASSYNARMOLOGISIS ='''+@NoPARASTLISTAS +''', EMPLOYEE ='''+	@EMPLOYEE +
	''', IDEMPLOYEE ='''+@IDEMPLOYEE +''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = '''+@_STATUS+''' WHERE ID IN(' + @INSERTVOH + ')')
declare @coma CHAR(1)
select @coma =','
BEGIN 
    DECLARE @start INT, @end INT 
    SELECT @start = 1, @end = CHARINDEX(@coma, @INSERTVOH) 
    WHILE @start < LEN(@INSERTVOH) + 1 BEGIN 
        IF @end = 0  
            SET @end = LEN(@INSERTVOH) + 1
       
        INSERT INTO VOH_ANA_LISTAASS (IDLISTAS, IDVOH)  
        VALUES(@IDLISTAS, CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC))
        
        DELETE FROM VOH_ANA_LISTAASS WHERE IDVOH = CAST( SUBSTRING(@INSERTVOH, @start, @end - @start)AS NUMERIC) AND IDLISTAS <> @IDLISTAS 
        SET @start = @end + 1 
        SET @end = CHARINDEX(@coma, @INSERTVOH, @start)
        
    END; 
			   
			with sumanalista as (
				select 
					idlistas, 
					count(id) countparast 
				from VOH_ANA_LISTAASS 
				group by IDLISTAS
			)

			update listes
				set count_fort = sumanalista.countparast
			from LISTESSYNARMOLOGISIS listes
			join sumanalista on sumanalista.IDLISTAS = listes.ID
			where DATEDIFF(DAY, listes.DATEPRINT , GETDATE()) < 30
			--listes.id=@IDLISTAS
			END





GO




---END SCRIPT 1792
