SET NOCOUNT ON;

DECLARE @NEWNOPARAST NUMERIC(18,2)=0
--GO
IF @IFAUTONUMBER =1
	BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WITH (NOLOCK) WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
			SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	ELSE
		BEGIN
			SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int)+1, 0)),0)  FROM FORTOTIKES WITH (NOLOCK) WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
			SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END;
	
