---NEW SCRIPT 1802
------------------------------------------------------------------------------------
CREATE VIEW AADE_INVOICE_INCOME_SUMMARIES AS
SELECT
 INVOICEID,
 IF_TO_FORTOTIKI,
 IF_TO_VOH,
 IF_POLISI,
 AADE_CATEGORY_CODE,
 AADE_TYPE_CODE,
 SUM(NET_AMOUNT) NET_AMOUNT
FROM AADE_INVOICE_DETAILS
GROUP BY INVOICEID, IF_TO_FORTOTIKI, IF_TO_VOH, IF_POLISI, AADE_CATEGORY_CODE, AADE_TYPE_CODE

GO

