SELECT
	GV.ID ,
	GV.IDVOH INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	1 IF_POLISI,
	0 IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY GV.IDVOH ORDER BY GV.ID) ROW_NUM,
	GV.TEMAXIA QTY,
