	1,
	POSOEPIVAR,
	TAXIS.AADE_CODE,
	TAXISEPIVAR,
	'category1_3',
	'E3_561_001'	
FROM VOH
JOIN COUNTANAVOH ON COUNTANAVOH.IDVOH = VOH.ID
JOIN KINDPARASTATIKON ON KINDPARASTATIKON.ID = VOH.IDPARAST
LEFT JOIN Taxis on TAXIS.Pososto = KINDPARASTATIKON.TAXISPERCENT
WHERE POSOEPIVAR > 0





