EXEC SP_RENAME 'AADE_FIX_POSA_VOH_YPHRESIA','AADE_FIX_POSA_VOH_YPHRESIA_OLD'
GO

CREATE PROCEDURE AADE_FIX_POSA_VOH_YPHRESIA

(@IDVOH INT )
AS


DECLARE @IDKOMISTRONPARASTATIKOU INT;

DECLARE @MIKTA_PARAST DECIMAL(10,2)
DECLARE @SUM_MIKTA_EKTOS_KOMISTRA DECIMAL(10,2)

select @MIKTA_PARAST = SUMPOSO
from VOH
where ID = @IDVOH

select top 1 @IDKOMISTRONPARASTATIKOU = xad.ID
from XREOSISANADELTIO xad
join Xreoseis xr on xr.ID = xad.IDXREOSIS
where xad.IDVOH = @IDVOH
and xad.IF_TO_VOH = 1
and xr.ifKomistra = 1

if @IDKOMISTRONPARASTATIKOU = 0 
begin
	
	select top 1 @IDKOMISTRONPARASTATIKOU = xad.ID
	from XREOSISANADELTIO xad
	join Xreoseis xr on xr.ID = xad.IDXREOSIS
	where xad.IDVOH = @IDVOH
	and xad.IF_TO_VOH = 1
end

-- Επαναϋπολογισμός ΦΠΑ για όλες τις χρεώσεις του παραστατικού που δεν είναι κόμιστρα
update xad 
	set xad.TAXIS = round(xad.POSO * xr.TAXISPERCENT * 0.01, 2)
from XREOSISANADELTIO xad
join Xreoseis xr on xr.ID = xad.IDXREOSIS
where xad.IDVOH = @IDVOH
and xad.IF_TO_VOH = 1
and xad.POSO > 0
and xad.ID <> @IDKOMISTRONPARASTATIKOU

-- Επαναϋπολογισμός ΜΙΚΤΩΝ για όλες τις χρεώσεις του παραστατικού που δεν είναι κόμιστρα
update xad 
	set xad.SUMPOSO = xad.POSO + xad.TAXIS
from XREOSISANADELTIO xad
where xad.IDVOH = @IDVOH
and xad.IF_TO_VOH = 1
and xad.POSO > 0
and xad.id <> @IDKOMISTRONPARASTATIKOU;



-- Αθροισμα ΜΙΚΤΩΝ εκτός από κόμιστρα για το παραστατικό
select @SUM_MIKTA_EKTOS_KOMISTRA = isnull(sum(isnull(xad.SUMPOSO, 0)), 0)
from XREOSISANADELTIO xad
where xad.IDVOH = @IDVOH
and xad.IF_TO_VOH = 1
and xad.id <> @IDKOMISTRONPARASTATIKOU;


-- Επαναϋπολογισμός των ΜΙΚΤΩΝ για τα κόμιστρα, θα είναι ίσος με (μικτά παραστατικού) - (άθροισμα μικτών όλων των υπολοίπων χρεώσεων) 
update xad
	set xad.SUMPOSO = @MIKTA_PARAST - @SUM_MIKTA_EKTOS_KOMISTRA
from XREOSISANADELTIO xad
where xad.ID = @IDKOMISTRONPARASTATIKOU;



-- Επαναϋπολογισμός των ΚΑΘΑΡΩΝ για τα κόμιστρα, αφαιρώντας τον ΦΠΑ από τα μικτά
update xad 
	set xad.POSO = round( xad.SUMPOSO / (1.00 + 0.01 * xr.TAXISPERCENT) , 2)
from XREOSISANADELTIO xad
join Xreoseis xr on xr.ID = xad.IDXREOSIS
where xad.id = @IDKOMISTRONPARASTATIKOU;


-- Επαναϋπολογισμός του ΦΠΑ για τα κόμιστρα, με αποφορολόγηση των διορθωμένων μικτών
update xad 
	set xad.TAXIS = xad.SUMPOSO - xad.POSO
from XREOSISANADELTIO xad
where xad.ID = @IDKOMISTRONPARASTATIKOU;


-- Επαναυπολογισμός των ΣΥΝΟΛΩΝ του παραστατικού, προσθέτοντας τις γραμμές των χρεώσεων
with synolaparastatikou as (
	select
		IDVOH,
		SUM(POSO) POSO,
		SUM(TAXIS) TAXIS,
		SUM(SUMPOSO) SUMPOSO
	from XREOSISANADELTIO 
	where IDVOH = @IDVOH
	and IF_TO_VOH = 1
	GROUP BY IDVOH
)
update V
	set POSO = synolaparastatikou.POSO,
		TAXIS = synolaparastatikou.TAXIS,
		SUMPOSO = synolaparastatikou.SUMPOSO
from VOH V
join synolaparastatikou on synolaparastatikou.IDVOH = V.ID
where V.ID = @IDVOH

-- Αντιγραφη ΣΥΝΟΛΩΝ του παραστατικού σε λοιπές παπαριές (HEADERVOH? SUMANAVOH? SASGAMHSEKANENASVOHSHMERA?)
-- your choice
--

--select poso, Taxis, sumposo from VOH where ID = 107047
update header
	set KATHARO = VOH.POSO,
		TAXIS = VOH.TAXIS,
		SUMPOSOXRVOH = VOH.SUMPOSO,
		ARXPOSO = VOH.POSO
from HEADERVOH header
join VOH on VOH.ID = header.IDVOH
where header.IDVOH = @IDVOH

GO

---END SCRIPT 1812
