ALTER VIEW [dbo].[AADE_INVOICES] AS
SELECT
	FORT.ID INVOICEID,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	FORT.DATEPRINT,
	FORT.IDXREOUMENOU COUNTERPART_ID,
	FORT.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(FORT.TAXIS) INVOICE_TAX_SUM,
	ABS(FORT.POSO) INVOICE_NET_SUM,
	ABS(FORT.SUMPOSO) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
	NULL [OXIMA] ,
	NULL [SKOPOSDIAKINISIS],
	NULL [DISPATCHED_DATE],
	NULL [DISPATCHED_TIME],
	FORT.IDYPOKATASTIMA,
	FORT.IF_ENIM_AADE,
	0 [IF_VOH_SALES]
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
UNION
SELECT
	VOH.ID INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	VOH.DATEPRINT,
	VOH.IDCUSTOMER COUNTERPART_ID,
	VOH.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(VOH.TAXIS+VOH.TAXISEPIVAR) INVOICE_TAX_SUM,
	ABS(VOH.POSO+VOH.POSOEPIVAR) INVOICE_NET_SUM,
	ABS(VOH.SUMPOSO+VOH.SUMPOSOEPIVAR) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE,
	PAYMENTS.AADE_CODE,
	CASE KP.KINDKINISIS
		WHEN 5 THEN VOH.OXIMA
		ELSE NULL
	END [OXIMA] ,
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN SKD.AADE_CODE
		ELSE NULL
	END [SKOPOSDIAKINISIS],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,23) 
		ELSE NULL
	END [DISPATCHED_DATE],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,8)
		ELSE NULL
	END  [DISPATCHED_TIME],

	VOH.IDYPOKATASTIMA,
	VOH.IF_ENIM_AADE,
	CASE KP.KindKINISIS
		WHEN 5 THEN 1 
		ELSE 0
	END [IF_VOH_SALES]
FROM VOH 
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
JOIN COMPANIES YPOKAT ON YPOKAT.id = VOH.IDYPOKATASTIMA
LEFT JOIN SKOPOSDIAKINISIS SKD ON SKD.DESCR=VOH.SKOPOSDIAKINISIS

WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0

GO



---END SCRIPT 1826
------------------------------------------------------------------------------------
------------------------------------------------------------------------------------
---NEW SCRIPT 1827

ALTER VIEW [dbo].[AADE_INVOICES_ALL] 
AS
SELECT 
	FORT.ID INVOICEID,
	FORT.DATEPRINT,
	FORT.PARASTATIKO,
	LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
	FORT.NOPARAST INVOICE_NUMBER,
	ACC.AFM,
	ACC.Eponimia AS COUNTERPART,
	FORT.POSO INVOICE_NET_SUM,
	FORT.TAXIS INVOICE_TAX_SUM,
	FORT.SUMPOSO INVOICE_GROSS_SUM,
	FORT.IF_ENIM_AADE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	KP.AADE_CODE INVOICE_AADE_CODE,
	PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
	FORT.AADE_UID,
	FORT.AADE_MARK,
	FORT.AADE_AUTHENTICATION_CODE,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	FORT.IDXREOUMENOU COUNTERPART_ID,
	--=FORT.DATEPRINT INVOICE DATE,
	--DATEPRINT INVOICE_DATE,
	FORT.IF_CANCEL,
	FORT.IDPARAST,
	FORT.IDCOMPANY,
	FORT.IDYPOKATASTIMA,
	FORT.ifDelete
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = FORT.IDXREOUMENOU
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0 
UNION
SELECT
	VOH.ID INVOICEID,
	VOH.DATEPRINT,
	VOH.PARASTATIKO,
	LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
	VOH.NOPARAST INVOICE_NUMBER,
	ACC.AFM,
	ACC.Eponimia AS COUNTERPART,
	VOH.POSO INVOICE_NET_SUM,
	VOH.TAXIS INVOICE_TAX_SUM,
	VOH.SUMPOSO INVOICE_GROSS_SUM,
	VOH.IF_ENIM_AADE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	KP.AADE_CODE INVOICE_AADE_CODE,
	PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
	VOH.AADE_UID,
	VOH.AADE_MARK,
	VOH.AADE_AUTHENTICATION_CODE,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	VOH.IDCUSTOMER COUNTERPART_ID,
	--=FORT.DATEPRINT INVOICE DATE,
	--DATEPRINT INVOICE_DATE,
	VOH.IF_CANCEL,
	VOH.IDPARAST,
	VOH.IDCOMPANY,
	VOH.IDYPOKATASTIMA,
	VOH.ifDelete
FROM VOH 
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = VOH.IDCUSTOMER
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0 




GO


