    --DATEPRINT INVOICE_DATE,
    FORT.IF_CANCEL,
    FORT.IDPARAST,
    FORT.IDCOMPANY,
    FORT.IDYPOKATASTIMA,
    FORT.ifDelete
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = FORT.IDXREOUMENOU
LEFT JOIN Acr ON Acr.AcrName = ACC.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
UNION
SELECT
    VOH.ID INVOICEID,
    VOH.DATEPRINT,
    VOH.PARASTATIKO,
    LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
    VOH.NOPARAST INVOICE_NUMBER,
    ACC.AFM,
    ACC.Eponimia AS COUNTERPART,
    VOH.POSO INVOICE_NET_SUM,
    VOH.TAXIS INVOICE_TAX_SUM,
    VOH.SUMPOSO INVOICE_GROSS_SUM,
    VOH.IF_ENIM_AADE,
    CURRENCY.AADE_CODE CURRENCY_AADE_CODE,    
    Acr.AcrPrefix,
    KP.AADE_CODE INVOICE_AADE_CODE,
    PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
    VOH.AADE_UID,
    VOH.AADE_MARK,
    VOH.AADE_AUTHENTICATION_CODE,
    0 IF_TO_FORTOTIKI,
    1 IF_TO_VOH,
    CASE KP.CATKEPYO
        WHEN 1 THEN 1
        ELSE 0
    END IF_LIANIKI,
    VOH.IDCUSTOMER COUNTERPART_ID,
    --=FORT.DATEPRINT INVOICE DATE,
    --DATEPRINT INVOICE_DATE,
    VOH.IF_CANCEL,
    VOH.IDPARAST,
    VOH.IDCOMPANY,
    VOH.IDYPOKATASTIMA,
    VOH.ifDelete
FROM VOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = VOH.IDCUSTOMER
LEFT JOIN Acr ON Acr.AcrName = ACC.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0




GO

---END SCRIPT 1828
