	@IFANTIKCASH				INT= 0,
	@IFANTIKEPIT				INT= 0,
	@IFANTIKSYNAL				INT= 0,
	@IFANTIKOTHER				INT= 0,
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	@SUMANTIK					NUMERIC(8,2)= NULL,
	@EXODATRITON				NUMERIC(8,2)= NULL,
	@IFCANCELANTIK				INT= 0,
	@DATECANCELANTIK			SMALLDATETIME= NULL,
	@AA_ANTIK					NUMERIC(8,0)= NULL,
	@IFPARADOSI					INT= 0,
	@DATEPARADOSI				SMALLDATETIME= NULL,
	@IFCANCEL					INT= 0,
	@DATECANCEL					SMALLDATETIME= NULL,
	@PERIOXIFORTOSIS			NVARCHAR(50)= NULL,
	@PERIOXIPARADOSIS			NVARCHAR(50)= NULL,
	@OMADPROORISMOS				NVARCHAR(50) = NULL,
	@OXIMA						NVARCHAR(60)= NULL,
	@IDKINDPAYMENT				NUMERIC(8,0)= 0,
	@KINDPAYMENTDESCR			NVARCHAR(50)= NULL,
	@AITIOLOGIAPARASTATIKOU		NVARCHAR(50)= NULL,
	@DATEFORTOSIS				SMALLDATETIME= NULL,
	@NOPARASTDELTIOUAPOSTOLIS	NVARCHAR(50)= NULL,
	@NOPARASTDELTIOUDIANOMIS	NVARCHAR(50)= NULL,
	@IFEPISTROFI				INT= 0,
	@DATEEPISTROFIS				SMALLDATETIME= NULL,
	@AITIOLOGIAEPISTROFIS		NVARCHAR(50)= NULL,
	@IDDRIVER					NUMERIC(18,0) = NULL,
	@DRIVERDESCR				NVARCHAR(60)=NULL,
	@IFCASH						INT= 0,
	@IFPISTOSI					INT= 0,
	@IFPREPAY					INT= 0,
	@IFOFEILOMENI				INT=0,
	@IDPRAKTOREIO				NUMERIC(8,0) = NULL,
	@PRAKTOREIODESCR			NVARCHAR(50) = NULL,
	@YPAITIOS					INT= 0, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
	@IFEPANADROMOLOGISI			INT= 0,
	@IFEPANEKDOSI				INT= 0,
	@IFOKEPANADROMOLOGISI		INT= 0,
	@NOPARASTANTIK				NVARCHAR(50) = NULL,
	@IFEXOFLISI					INT= 0,
