Create view [dbo].[_sms_query] as 
select
	CONVERT(varchar, kaa.IDPARAST) + '-' + CONVERT(varchar, kaa.NOPARAST) KAA_FULL_ID,
	fort.ID,
	fort.IDENTOLEA,
	fort.EXT_BARCODE,
	CASE 
		WHEN LEN(ISNULL(fort.NO_EXT_ORDER, '')) > 1 THEN fort.NO_EXT_ORDER
		ELSE fort.EXT_BARCODE
	END ORDER_NO,
	fort.APOSTOLEASDESCR,
	fort.PARALISPTISDESCR,
	paral.AddressStr + ' ' + paral.AddressNo PARALIPTISADDRESS, 
	paral.AddressCity,
	paral.Mobile,
	kaa.DRIVER,
	kaa.OXIMA
from FORTOTIKES_ANA_KAA fak
join KAA kaa on kaa.ID = fak.IDKAA
join FORTOTIKES fort on fort.ID = fak.IDFORTOTIKIS
join ACCOUNTS paral on paral.ID = fort.IDPARALIPTI
where kaa.IDXRHSHS = (
	select ID
	from XRHSEIS
	where CONVERT(date, GETDATE()) BETWEEN FIRSTDATE AND LASTDATE
)
union
select
	CONVERT(varchar, dian.IDPARAST) + '-' + CONVERT(varchar, dian.NOPARAST) KAA_FULL_ID,
	fort.ID,
	fort.IDENTOLEA,
	fort.EXT_BARCODE,
	CASE 
		WHEN LEN(ISNULL(fort.NO_EXT_ORDER, '')) > 1 THEN fort.NO_EXT_ORDER
		ELSE fort.EXT_BARCODE
	END ORDER_NO,
	fort.APOSTOLEASDESCR,
	fort.PARALISPTISDESCR,
	paral.AddressStr + ' ' + paral.AddressNo PARALIPTISADDRESS, 
	paral.AddressCity,
	paral.Mobile,
	dian.DRIVER,
	dian.OXIMA
from FORTOTIKES_ANA_LISTA fal
join LISTESDIANOMIS dian on dian.ID = fal.IDLISTAS
join FORTOTIKES fort on fort.ID = fal.IDFORTOTIKIS
join ACCOUNTS paral on paral.ID = fort.IDPARALIPTI
where dian.IDXRHSHS = (
	select ID
	from XRHSEIS
	where CONVERT(date, GETDATE()) BETWEEN FIRSTDATE AND LASTDATE
)
--order by kaa.IDPARAST, kaa.NOPARAST
GO



---END SCRIPT 1834
