			BEGIN
				if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM VOH WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  
				IDPARAST =@IDPARAST AND ifDelete != 1 AND (DATEPRINT BETWEEN CONVERT(DATETIME, @StrDateFrom,103) AND CONVERT(DATETIME, @StrDateTo,103)))
					 BEGIN
						SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM VOH WHERE 
						((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST AND ifDelete != 1 AND 
						(DATEPRINT BETWEEN CONVERT(DATETIME, @StrDateFrom,103) AND CONVERT(DATETIME, @StrDateTo,103))
						SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
					 END 
				ELSE
					 BEGIN
						SET @NOPARAST =  1
					 END			END;
		UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
	END;
END
ELSE
BEGIN
	IF @IFAUTONUMBER =1
		BEGIN
