						SEIRA = @SEIRA AND  IDPARAST =@IDPARAST AND ifDelete != 1
						SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
					 END 
				ELSE
					 BEGIN
						SET @NOPARAST =  1
					 END
				--SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM VOH WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
				--SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
			END;
		ELSE
			BEGIN
				if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM VOH WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  
				IDPARAST =@IDPARAST AND ifDelete != 1)
					 BEGIN
						SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM VOH WHERE 
						((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST AND ifDelete != 1
						SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
