ALTER VIEW [dbo].[FORTOTIKES_WEB_VOUCHER]
AS

SELECT 

f.ID,
f.IDAPOSTOLEA,
f.IDPARALIPTI,
f.IDENTOLEA,
f.IDPARAST,
f.PARASTATIKO,
f.STATUS,
f.STATUSDESCR,

f.NO_EXT_ORDER [Αρ.Παραγγελίας],
CASE 
	WHEN ROW_NUMBER()OVER (PARTITION BY F.ID ORDER BY f.ID)>1 
	THEN NULL
	ELSE convert(date,f.DATEPRINT) 
END AS [Ημερομηνία],
gf.TEMAXIA [Ποσότητα],
gf.SYSKEVASIADESCR [Συσκευασία],
gf.PERIEXOMENO [Περιεχόμενο],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY f.ID ORDER BY f.ID)>1 THEN NULL 
	ELSE f.ANTIKCASH 
END AS [Αντικαταβολή Μετρητά],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY F.ID ORDER BY f.ID) > 1 THEN NULL
	ELSE f.ANTIKEPIT 
END AS [Αντικαταβολή Επιταγή],
CASE 
	WHEN ROW_NUMBER() OVER (PARTITION BY f.ID ORDER BY f.ID)>1 THEN NULL 
	ELSE f.ANTIKSYNAL 
END AS [Αντικαταβολή Συναλ/κη],
f.APOSTOLEASDESCR [Αποστολέας],
f.PARALISPTISDESCR [Παραλήπτης],
f.PERIOXIPARADOSIS [Περιοχή Παράδοσης],
f.EXT_BARCODE [Εξωτ.Barcode],
CASE 
	WHEN ROW_NUMBER () OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
	ELSE (LTRIM(RTRIM(f.SEIRA))+'-'+f.NOPARAST)
END AS [Αρ.Παραστατικού],
f.comments [Σχόλια]

from FORTOTIKES f
left JOIN GRAMMESFORTTIKIS gf ON gf.IDVOH=f.ID 
WHERE ISNULL(f.ifDelete,0)<>1

GO


---END SCRIPT 1838
