---NEW SCRIPT 1840


ALTER VIEW [dbo].[PARAGGELIESWEB_VIEW]
AS
SELECT
	PF1.ID
	,PF1.EXT_BARCODE
 ,PF1.IDENTOLEA
 ,CONVERT(VARCHAR, PF1.DATEPRINT, 103) AS DATEPRINT
 ,PF1.APOSTOLEASDESCR
 ,PF1.PARALISPTISDESCR
 ,GPF1.TIMDA
 ,PF1.PERIOXIPARADOSIS
 ,CONVERT(DATE, PF1.DATEPRINT) AS DATEPRINTRAW
 ,PROFORTSUM.TEMAXIA
 ,PARAL.AddressCity
 ,PARAL.AddressStr
 ,PARAL.Tel [TEL]
 ,PARAL.Tel2 [TEL2]
 ,PARAL.Mobile [MOBILE]
 ,PF1.NO_EXT_ORDER
 ,CASE PF1.IFPRINT
 		WHEN 1 THEN 'Ναι'
		ELSE 'Οχι'
	END [IFPRINT],
	pf1.IFPRINT IFPRINT_RAW,
	pf1.STATUSDESCR
FROM PROFORTOTIKES PF1
LEFT JOIN (SELECT
		IDVOH
	 ,dbo.GROUP_CONCAT_S(CONVERT(NVARCHAR, TEMAXIA) + ' ' + SYSKEVASIADESCR, 1) [TEMAXIA]
	FROM GRAMMESPROFORTTIKIS
	GROUP BY IDVOH) PROFORTSUM
	ON PROFORTSUM.IDVOH = PF1.ID
LEFT JOIN (SELECT
		GF.IDVOH
	 ,dbo.GROUP_CONCAT(DISTINCT GF.TIMDA) TIMDA
	FROM GRAMMESPROFORTTIKIS GF
	GROUP BY GF.IDVOH) GPF1
	ON PF1.ID = GPF1.IDVOH
LEFT JOIN ACCOUNTS PARAL
	ON PARAL.id = PF1.IDPARALIPTI
WHERE ISNULL(PF1.IFDELETE, 0) = 0
AND ISNULL(PF1.IFCLOSE, 0) = 0
GO



---END SCRIPT 1840
