create view [dbo].[FORTOTIKES_WITH_ANTKATAVOLES] as 
with GF as (
	SELECT
		IDVOH,
		ROW_NUMBER() OVER (PARTITION BY IDVOH ORDER BY ID) [ROWNUM],
		TIMDA,
		TEMAXIA,
		BAROS,
		KYBIKA,
		SYSKEVASIADESCR,
		PERIEXOMENO
		
	FROM GRAMMESFORTTIKIS
)

select
	
	f.ID,
	f.IDENTOLEA,
	f.IDAPOSTOLEA,
	f.IDPARALIPTI,
	f.IDTRITOU,
	f.IDANTAPOKRITI,
	f.IDPRAKTOREIO,
	f.NOPARASTDELTIOUAPOSTOLIS,
	f.NOLISTASDIANOMIS,
	CASE gf.ROWNUM
		WHEN 1 THEN f.OXIMA
		ELSE null
	END [Όχημα], 
	case gf.rownum
		when 1 then f.OMADPROORISMOS
		else null
	end as [Ομ.Προορισμός],
	case gf.rownum
		when 1 then f.STATUSDESCR
		else null
	end as [Κατάσταση Φορτωτικής],
	case gf.rownum
		when 1 then f.PRAKTOREIODESCR
		else null
	end as [Πρακτορείο],
	case gf.rownum
		when 1 then f.PARASTATIKO
		else null
	end as [Παραστατικό],
	
	case gf.rownum
		when 1 then convert(date,f.DATEPRINT) 
		else null
	end as [Ημερομηνία Φορτωτικής],
	case gf.rownum
		when 1 then rtrim(f.SEIRA)+f.NOPARAST 
		else null
	end as [Αρ.Φορτωτικης],
	case gf.rownum
		when 1 then f.APOSTOLEASDESCR 
		else null
	end as [Αποστολέας],
	case gf.rownum
		when 1 then f.PARALISPTISDESCR 
		else null
	end as [Παραλήπτης],
	case gf.rownum
		when 1 then f.ANTIKCASH 
		else 0
	end as [Αντικ. Μετρητά],
	case gf.rownum
		when 1 then f.ANTIKEPIT 
		else 0
	end as [Αντικ. Επιταγή],
	case gf.rownum
		when 1 then f.ANTIKSYNAL 
		else 0 
	end as [Αντικ. Συναλ/κη],
	case gf.rownum
		when 1 then f.ANTIKOTHER 
		else 0
	end as [Αντικ. Άλλο],
	case gf.rownum
		when 1 then f.SUMANTIK 
		else 0
	end as [Σύνολο Αντικ/λης],
	case gf.rownum
		when 1 then convert(date,f.DATEPARALANTIK) 
		else null
	end as [Ημ.Παραλαβής],
	case gf.rownum
		when 1 then convert(date,f.DATEPARADANTIK) 
		else null 
	end as [Ημ.Παράδοσης], 
	gf.TIMDA  [ΤΙΜ/ΔΑ]

from FORTOTIKES f
join  gf on gf.IDVOH=f.ID
where f.SUMANTIK>0 


GO
---END SCRIPT 1842
------------------------------------------------------------------------------------


