GO

CREATE VIEW [dbo].[PROFORTOTIKES_VIEW]
AS

WITH GRAMMESPROFORTOTIKIS AS 
				(
					SELECT 
						IDVOH,
						MIN(TIMDA) AS TIMDA,
						ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
						MIN(U.UntName) AS SYSKEVASIADESCR,
						MIN(PERIEXOMENO) AS PERIEXOMENO,
						ISNULL(SUM(BAROS),0) AS BAROS,
						ISNULL(SUM(KYBIKA),0) AS KYBIKA,
						ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
					FROM GRAMMESPROFORTTIKIS
					LEFT JOIN Units U ON U.UntID=GRAMMESPROFORTTIKIS.SYSKEVASIA
					GROUP BY IDVOH
),
POSAPROFORTOTIKIS AS 
					(
						SELECT 
							ID,
							SUMPOSO,
							ROUND(PROFORTOTIKES.POSO, 2) AS KATHARO,
							ROUND(PROFORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
							ROUND(PROFORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT					
						
						FROM PROFORTOTIKES
					
					)

SELECT

	PF.ID,
	PF.DATEPRINT,
	KP.Code,
    PF.parastatiko,
    PF.seira,
    Cast(PF.noparast AS INT)							AS NOPARAST,
    PF.noparastdeltioudianomis,
    PF.noparastdeltiouapostolis,
    PF.omadproorismos,
    PF.apostoleasdescr,
    PF.paralisptisdescr,
    PF.entoleasdescr,
    PF.comments,
    PF.exodatriton										AS XREOSISTRITON,
    PF.sumantik,
    PSPR.KATHARO										AS POSO,
    PSPR.TAXISXREOSEON									AS TAXIS,
    Round(HDPF.taxis, 2)								AS TAXISXREOSEON,
    PSPR.SUMPOSOXRFORT									AS SUMPOSO,
    Round(HDPF.SUMPOSOXRPROFORT, 2)						AS SUMPOSOXRPROFORT,
    PF.oxima,
    CASE 
		ISNULL(PF.IFXRENTOL, 0) * 1
		+ ISNULL(PF.IFXRAPOST, 0) * 2
		+ ISNULL(PF.IFXRTRITOU, 0) * 4
		+ ISNULL(PF.IFXRPARAL, 0) * 8

		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'

		ELSE 'ΑΓΝΩΣΤΟΣ'
	END													AS XREOYMENOS,
	PF.antapokritisdescr,
    PF.nolistasdianomis,
    PF.tritosdescr,
    HDPF.katharo,
    GRPF.TIMDA,
    GRPF.TEMAXIA,
    GRPF.BAROS,
    GRPF.KYBIKA,
    GRPF.SYSKEVASIADESCR								AS SYSKEVASIA,
    CASE PF.IFPREPAY 
        WHEN 1 THEN ISNULL(PSPR.SUMPOSO,0) 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE PF.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(PSPR.SUMPOSO,0)
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE PF.IFPREPAY 
        WHEN 1 THEN CASE PF.IFCASH 
            WHEN 1 THEN ISNULL(PSPR.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE PF.IFPREPAY 
        WHEN 1 THEN CASE PF.IFPISTOSI 
            WHEN 1 THEN ISNULL(PSPR.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GRPF.PERIEXOMENO,
    
   PF.perioxifortosis,
   PF.perioxiparadosis,
   PF.praktoreiodescr,
   PF.no_ext_order,
   PF.ext_barcode,
   PF.statusdescr,
   PF.status,
   CONVERT(VARCHAR, PF.dateparad, 102)       AS DATEPARAD,
   PF.idapostolea,
   PF.idparalipti,
   PF.identolea,
   PF.idantapokriti,
   PF.idtritou,
   PF.idpraktoreio,
   PF.ANTIKCASH,
   PF.ANTIKEPIT,
   PF.ANTIKSYNAL,
   PF.ANTIKOTHER,
   CASE ifcancelantik
         WHEN 0 THEN 'ΟΧΙ'
         ELSE 'ΝΑΙ'
   END                                                      AS IFCANCELANTIK,
   PF.commentsantik,
   PF.dateparadosi,
   isnull(HDPF.komistra,0)											AS KOMISTRA,
   isnull(HDPF.dikaiomafortotikis,0)								AS DIKAIOMAFORTOTIKIS,
   isnull(HDPF.otherxreosis,0)										AS OTHERXREOSIS,
   isnull(HDPF.olikosynoloxreoseonprofort,0)						AS OLIKOSYNOLOXREOSEONFORT,
   isnull(HDPF.ergatika,0)											AS ERGATIKA,
   CASE PF.ifprepay
         WHEN 1 THEN 'ΝΑΙ'
         ELSE 'ΟΧΙ'
    END			                                                    AS IFPREPAY,
   CASE PF.ifofeilomeni
         WHEN 1 THEN 'ΝΑΙ'
         ELSE 'ΟΧΙ'
   END																AS IFOFEILOMENI,
   GRPF.sumposo														AS AXIA,
   CASE ifxrentol
     WHEN 0 THEN 'ΟΧΙ'
     ELSE 'ΝΑΙ'
   END																AS IFXRENTOL,
   
   CASE ifxrapost
     WHEN 0 THEN 'ΟΧΙ'
     ELSE 'ΝΑΙ'
   END																AS IFXRAPOST,
   CASE ifxrparal
     WHEN 0 THEN 'ΟΧΙ'
     ELSE 'ΝΑΙ'
   END																AS IFXRPARAL,
   CASE ifxrtritou
     WHEN 0 THEN 'ΟΧΙ'
     ELSE 'ΝΑΙ'
   END																AS IFXRTRITOU,
   PF.kindpaymentdescr,
   PF.idkindpayment,
   
   PF.ifantikcash,
   PF.ifantikepit,
   PF.ifantiksynal,
   PF.ifantikother,
   PF.ifdelete,
   PF.ifcancel,
   CONVERT(VARCHAR, PF.datecancel, 102)      AS DATECANCEL,
   PF.aa_antik,
   PF.ifparadosi,
   PF.aitiologiaparastatikou,
   CONVERT(VARCHAR, PF.datefortosis, 102)    AS DATEFORTOSIS,
   PF.ifepistrofi,
   CONVERT(VARCHAR, PF.dateepistrofis, 102)  AS DATEEPISTROFIS,
   PF.aitiologiaepistrofis,
   PF.commentsepistrofis,
   PF.ifcash,
   PF.ifpistosi,
   PF.ypaitios,
   PF.ifepanadromologisi,
   PF.ifepanekdosi,
   PF.ifokepanadromologisi,
   PF.noparastantik,
   PF.commentsakirosis,
   PF.ifeisprantik,
   PF.ifparadosiantik,
   PF.ifparalaviantik,
   PF.commentsparadantik,
   PF.commantsparalantik,
   PF.commentseisprantik,
   CONVERT(VARCHAR, PF.dateparadantik, 102)  AS DATEPARADANTIK,
   CONVERT(VARCHAR, PF.dateparalantik, 102)  AS DATEPARALANTIK,
   CONVERT(VARCHAR, PF.dateeisprantik, 102)  AS DATEEISPRANTIK,
   PF.eispraxasantik,
   PF.noparparadantik,
   PF.noparasteisprantik,
   PF.noparparalantik,
   CONVERT(VARCHAR, PF.dateparal, 102)       AS DATEPARAL,
   PF.commentsparad,
   PF.commantsparal,
   PF.timeparalfrom,
   PF.timeparalto,
   PF.timeparadfrom,
   PF.timeparadto,
   CONVERT(VARCHAR, PF.datecancelantik, 102) AS DATECANCELANTIK,
   PF.idparast,
   PF.taxispercent,
   PF.anamexodo,
   PF.id                                     AS IDFORTOTIKIS,
   PF.afmxreoumenou,
   ISNULL(HDPF.asfalistra,0)				 AS ASFALISTRA,
   PF.container,
   PF.boat,
   
   APOST.epagelma                                    AS EPAGAPOST,
   APOST.addressstr                                  AS ADDRSTRAPOST,
   APOST.addressno                                   AS ADDRNOAPOST,
   APOST.addresstk                                   AS TKAPOST,
   APOST.addresscity                                 AS CITYAPOST,
   APOST.addresspref                                 AS NOMOSAPOST,
   APOST.tel                                         AS TELAPOST,
   APOST.doy                                         AS DOYAPOST,
   APOST.mobile                                      AS MOBILEAPOSTOLEA,
   
   PARAL.epagelma                                    AS EPAGPARAL,
   PARAL.addressstr                                  AS ADDRSTRPARAL,
   PARAL.addressno                                   AS ADDRNOPARAL,
   PARAL.addresstk                                   AS ADDRTKPARAL,
   PARAL.addresscity                                 AS ADDRCITYPARAL,
   PARAL.addresspref                                 AS ADDRNOMOSPARAL,
   PARAL.tel                                         AS TELPARAL,
   PARAL.doy                                         AS DOYPARAL,
   PARAL.mobile                                      AS MOBILEPARALIPTI,
   
   ENTOL.epagelma                                    AS EPAGENTOL,
   ENTOL.addressstr                                  AS ADDRSTRENTOL,
   ENTOL.addressno                                   AS ADDRNOENTOL,
   ENTOL.addresstk                                   AS ADDRTKENTOL,
   ENTOL.addresscity                                 AS ADDRCITYENTOL,
   ENTOL.addresspref                                 AS ADDRNOMOSENTOL,
   ENTOL.tel                                         AS TELENTOL,
   ENTOL.doy                                         AS DOYENTOL,
   ENTOL.mobile                                      AS MOBILEENTOLTEA,
   
   TRITOS.epagelma                                   AS EPAGTR,
   TRITOS.addressstr                                 AS ADDRSTTR,
   TRITOS.addressno                                  AS ADDRNOTR,
   TRITOS.addresstk                                  AS ADDRTKTR,
   TRITOS.addresscity                                AS ADDRCITYTR,
   TRITOS.addresspref                                AS ADSTRDRNOMO,
   TRITOS.tel                                        AS TELTR,
   TRITOS.doy                                        AS DOYTR,
   
   PF.afmapostolea,
   PF.afmentolea,
   PF.afmparalipti,
   PF.afmtritou,
   PF.afmantapokriti,
   PF.ifparadositopel,
   PF.ifparalabifrompel,   
   PF.idxreoumenou,
   PF.if_prodromol,   
   PF.iddriver,
   PF.driverdescr,
   PF.idxrhshs,
   PF.idcompany,
   PF.idypokatastima,
   PF.idwarehouse,
   PF.ext_id,
   PF.ifclose,
   PF.usercreate,
   PF.datecreate

FROM PROFORTOTIKES PF
JOIN KINDPARASTATIKON KP ON KP.ID=PF.IDPARAST
JOIN HEADERPROFORTOTIKIS HDPF ON HDPF.IDPROFORT=PF.ID
LEFT JOIN GRAMMESPROFORTOTIKIS GRPF ON GRPF.IDVOH=PF.ID 
LEFT JOIN POSAPROFORTOTIKIS PSPR ON PSPR.ID=PF.ID
LEFT JOIN ACCOUNTS APOST ON APOST.ID=PF.IDAPOSTOLEA
LEFT JOIN ACCOUNTS PARAL ON PARAL.id=PF.IDPARALIPTI
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id=PF.IDENTOLEA
LEFT JOIN ACCOUNTS TRITOS ON TRITOS.id=PF.IDTRITOU
GO


---END SCRIPT 1844
