ALTER VIEW [dbo].[GRAMMES_FORTOTIKIS_VIEW]
AS
SELECT     TOP (100) PERCENT dbo.GRAMMESFORTTIKIS.ID, dbo.GRAMMESFORTTIKIS.IDVOH, dbo.GRAMMESFORTTIKIS.TIMDA, dbo.GRAMMESFORTTIKIS.TEMAXIA, 
                      dbo.GRAMMESFORTTIKIS.SYSKEVASIA, dbo.GRAMMESFORTTIKIS.PERIEXOMENO, CAST(ROUND(dbo.GRAMMESFORTTIKIS.BAROS, 2) AS DECIMAL(9, 2)) AS BAROS, 
                      CAST(ROUND(dbo.GRAMMESFORTTIKIS.KYBIKA, 2) AS DECIMAL(9, 2)) AS KYBIKO, CAST(ROUND(dbo.GRAMMESFORTTIKIS.SUMPOSO, 2) AS DECIMAL(9, 2)) 
                      AS SUMPOSO, dbo.Units.UntName,dbo.GRAMMESFORTTIKIS.XreosiAnaMonada,
					  dbo.GRAMMESFORTTIKIS.XeosiSeMonada,
					  dbo.GRAMMESFORTTIKIS.XreosiGrammis
FROM         dbo.GRAMMESFORTTIKIS  WITH(NOLOCK) LEFT OUTER JOIN
                      dbo.Units  WITH(NOLOCK) ON dbo.GRAMMESFORTTIKIS.SYSKEVASIA = dbo.Units.UntID
ORDER BY dbo.GRAMMESFORTTIKIS.ID

GO

---END SCRIPT 1845
