CREATE VIEW ANTIKATAVOLESPERDAY_VIEW AS
with grammes as (
					select 
						IDVOH,
						min(TIMDA) as TIMDA
					from GRAMMESFORTTIKIS
					group by idvoh
				)

select
	f.ID,
	kp.Code,
	f.PARASTATIKO, 
	f.SEIRA, 
	f.NOPARAST,
	CONVERT(nvarchar(20),f.DATEPRINT,103) as DATEPRINT,
	f.POSO, 
	f.TAXISPERCENT, 
	f.TAXIS, 
	f.SUMPOSO, 
	f.OXIMA, 
	f.KINDPAYMENTDESCR, 
	f.IDKINDPAYMENT, 
	'' AS STATUS, 
	f.DRIVERDESCR,
	CASE IFXRAPOST WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRAPOST, 
	f.IDAPOSTOLEA, 
	f.APOSTOLEASDESCR, 
	CASE IFXRPARAL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRPARAL, 
	f.IDPARALIPTI, 
	f.PARALISPTISDESCR, 
	CASE IFXRENTOL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRENTOL, 
	f.IDENTOLEA, 
	f.ENTOLEASDESCR, 
	CASE IFXRTRITOU WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRTRITOU,
	f.IDTRITOU, 
	f.TRITOSDESCR, 
	f.IDANTAPOKRITI, 
	f.ANTAPOKRITISDESCR, 
	f.IFANTIKCASH, 
	CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, 
	f.IFANTIKEPIT, 
	CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
	f.IFANTIKSYNAL, 
	CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
	f.IFANTIKOTHER, 
	CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
	f.SUMANTIK, 
	CASE IFCANCELANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFCANCELANTIK, 
	CASE IFCANCELANTIK WHEN 0 THEN NULL ELSE f.DATECANCELANTIK END AS DATECANCELANTIK, 
	f.COMMENTSANTIK, 
	f.NOLISTASANTIK,
	CASE IFPARADOSIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARADOSIANTIK, 
	CASE IFPARADOSIANTIK WHEN 0 THEN NULL ELSE f.DATEPARADANTIK END AS DATEPARADANTIK, 
	CASE IFEISPRANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFEISPRANTIK, 
	CASE IFEISPRANTIK WHEN 0 THEN NULL ELSE f.DATEEISPRANTIK END AS DATEEISPRANTIK, 
	CASE IFPARALAVIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARALAVIANTIK, 
	CASE IFPARALAVIANTIK WHEN 0 THEN NULL ELSE f.DATEPARALANTIK END AS DATEPARALANTIK, 
	f.PERIOXIFORTOSIS, 
	f.PERIOXIPARADOSIS, 
	f.STATUS AS Expr1,
	gr.TIMDA,
	f.IDPARAST, 
	f.IFXRENTOL AS Expr2, 
	f.IFXRPARAL AS Expr3, 
	f.IFXRTRITOU AS Expr4, 
	f.IFXRAPOST AS Expr5, 
	f.ANTIKCASH AS Expr6, 
	f.ANTIKEPIT AS Expr7, 
	f.ANTIKSYNAL AS Expr8, 
	f.ANTIKOTHER AS Expr9, 
	f.COMMENTS, 
	f.ifDelete, 
	f.OMADPROORISMOS, 
	f.AITIOLOGIAPARASTATIKOU, 
	f.DATEFORTOSIS, 
	f.NOPARASTDELTIOUAPOSTOLIS, 
	f.NOPARASTDELTIOUDIANOMIS, 
	f.IFEPISTROFI, 
	f.DATEEPISTROFIS, 
	f.AITIOLOGIAEPISTROFIS, 
	f.COMMENTSEPISTROFIS, 
	f.IFCASH, 
	f.IFPISTOSI, 
	f.IFPREPAY, 
	f.IFOFEILOMENI, 
	f.IDPRAKTOREIO, 
	f.IDYPOKEISPRANTIK, 
	f.IDYPOKPARALANTIK, 
	f.IDYPOKPARADANTIK, 
	f.PRAKTOREIODESCR, 
	f.STATUSDESCR, 
	f.YPAITIOS, 
	f.IFEPANADROMOLOGISI, 
	f.IFEPANEKDOSI, 
	f.IFOKEPANADROMOLOGISI, 
	f.NOPARASTANTIK, 
	f.COMMENTSAKIROSIS, 
	f.NOLISTASDIANOMIS, 
	f.IDXRHSHS, 
	f.IDCOMPANY, 
	f.IDYPOKATASTIMA,
	f.UserCreate, 
	f.UserMod, 
	f.DateCreate, 
	f.DateMod,
	f.COMMENTSEISPRANTIK,
	f.COMMANTSPARALANTIK,
	f.COMMENTSPARADANTIK,
	f.EXT_BARCODE,
	f.NO_EXT_ORDER    

from FORTOTIKES f
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
left join grammes gr on gr.IDVOH=f.ID

WHERE 
	(f.IFCANCELANTIK <> 1)
  AND (f.IFANTIKCASH = 1)  
  or (f.IFANTIKEPIT = 1) 
  or (f.IFANTIKSYNAL = 1) 
  or (f.IFANTIKOTHER = 1) 
  
GO  
---END SCRIPT 1846
