ALTER VIEW [dbo].[APOGRAFIPELVIEW]
AS
with parastatiko as (
						select
							pa.ID_KINDPARASTATIKON
						from PARASTATIKA_ANA_KATHGORIA pa
						join CAT_PARASTATIKON cp on cp.id=pa.ID_CAT_PARASTATIKON
						where cp.If_EXODO=4
					)

SELECT 
		r.ID, 
		r.DATEPRINT, 
		r.IDKINDPARAST, 
		r.KINDPARASTDESCR, 
		r.SEIRA, 
		r.DOCNO AS NOPARAST, 
		r.DOCNO, 
		r.AITIOLOGIA, 
		r.EISPRAXAS, 
		r.IDVOH, 
		r.IDCUSTOMER, 
		r.AFMCUSTOMER, 
		r.CUSTOMERDESCR, 
		r.SUMPOSO, 
		r.IDKINDPAYMENT, 
		r.KINDPAYMENTDESCR, 
		r.ifDelete, 
		kp.IF_IN, 
		kp.IF_OUT, 
		kp.IF_CASH, 
		kp.KINDOFCALCULATION, 
		kp.IFENDDATE, 
		(kp.IF_IN * r.SUMPOSO) AS PISTOSI, 
		(kp.IF_OUT * r.SUMPOSO) AS XREOSI, 
		r.IDXRHSHS, 
		r.IDCOMPANY, 
		r.IDYPOKATASTIMA 
FROM 
  RECEIPTS r WITH (NOLOCK) 
  INNER JOIN KINDOFPAYMENTS kp WITH (NOLOCK) ON r.IDKINDPAYMENT = kp.ID  AND r.IF_APOGRAFI = 1 
  join parastatiko par on par.ID_KINDPARASTATIKON=r.IDKINDPARAST
  

GO

