ALTER view [dbo].[ANTIKATAVOLES_VIEW] as
with grammes as (
					select 
						IDVOH,
						min(TIMDA) as TIMDA
					from GRAMMESFORTTIKIS
					group by idvoh
				)

select 
	
	f.ID,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA, 
    f.NOPARAST, 
	f.DATEPRINT, 
	f.POSO, 
	f.TAXISPERCENT, 
	f.TAXIS, 
	f.SUMPOSO, 
	f.OXIMA, 
	f.DRIVERDESCR, 
	f.KINDPAYMENTDESCR, 
	f.IDKINDPAYMENT,
	CASE IFXRAPOST WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRAPOST, 
	f.IDAPOSTOLEA, 
	f.APOSTOLEASDESCR, 
	CASE IFXRPARAL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRPARAL, 
	f.IDPARALIPTI, 
	f.PARALISPTISDESCR, 
	CASE IFXRENTOL WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRENTOL, 
	f.IDENTOLEA, 
	f.ENTOLEASDESCR, 
	CASE IFXRTRITOU WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFXRTRITOU, 
	f.IDTRITOU, 
	f.TRITOSDESCR,
	f.IDANTAPOKRITI, 
	f.ANTAPOKRITISDESCR, 
	f.AA_ANTIK, 
	f.IFANTIKCASH, 
	gr.TIMDA,
	CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, 
	f.IFANTIKEPIT, 
	CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
	f.IFANTIKSYNAL, 
	CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
	f.IFANTIKOTHER, 
	CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
	f.SUMANTIK, 
	CASE IFCANCELANTIK WHEN 1 THEN CAST('True' AS bit) ELSE CAST('False' AS bit) END AS IFCANCELANTIK, 
	CASE IFCANCELANTIK WHEN 0 THEN NULL ELSE f.DATECANCELANTIK END AS DATECANCELANTIK, 
	f.COMMENTSANTIK, 
	f.IDYPOKEISPRANTIK, 
	f.IDYPOKPARALANTIK, 
	f.IDYPOKPARADANTIK, 
	CASE IFPARADOSIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARADOSIANTIK, 
	CASE IFPARADOSIANTIK WHEN 0 THEN NULL ELSE f.DATEPARADANTIK END AS DATEPARADANTIK, 
	CASE IFEISPRANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFEISPRANTIK, 
	CASE IFEISPRANTIK WHEN 0 THEN NULL ELSE f.DATEEISPRANTIK END AS DATEEISPRANTIK, 
	CASE IFPARALAVIANTIK WHEN 0 THEN CAST('False' AS bit) ELSE CAST('True' AS bit) END AS IFPARALAVIANTIK, 
	CASE IFPARALAVIANTIK WHEN 0 THEN NULL ELSE f.DATEPARALANTIK END AS DATEPARALANTIK,
	f.PERIOXIFORTOSIS, 
	f.PERIOXIPARADOSIS, 
	f.STATUS AS STATUS, 
	f.IDPARAST, 
	f.COMMENTS, 
	f.ifDelete, 
	f.NOPARASTEMVAST, 
	f.OMADPROORISMOS, 
	f.AITIOLOGIAPARASTATIKOU, 
	f.DATEFORTOSIS, 
	f.NOLISTASANTIK, 
	f.NOPARASTDELTIOUAPOSTOLIS, 
	f.NOPARASTDELTIOUDIANOMIS, 
	f.IFEPISTROFI, 
	f.DATEEPISTROFIS, 
	f.AITIOLOGIAEPISTROFIS, 
	f.COMMENTSEPISTROFIS, 
	f.IFCASH, 
	f.IFPISTOSI, 
	f.IFPREPAY, 
	f.IFOFEILOMENI, 
	f.IDPRAKTOREIO, 
	f.IDXREOUMENOU, 
	f.PRAKTOREIODESCR, 
	f.STATUSDESCR, 
	f.YPAITIOS, 
	f.IFEPANADROMOLOGISI, 
	f.IFEPANEKDOSI, 
	f.IFOKEPANADROMOLOGISI, 
	f.NOPARASTANTIK, 
	f.COMMENTSAKIROSIS, 
	f.NOLISTASDIANOMIS, 
	f.IDXRHSHS, 
	f.IDCOMPANY, 
	f.IDYPOKATASTIMA, 
	f.UserCreate, 
	f.UserMod, 
	f.DateCreate, 
	f.DateMod,
	f.COMMENTSEISPRANTIK,
	f.COMMANTSPARALANTIK,
	f.COMMENTSPARADANTIK,
	f.EXT_BARCODE,
	f.NO_EXT_ORDER
	
	
from FORTOTIKES f 
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
left join grammes gr on gr.IDVOH=f.ID

where (f.IFANTIKCASH = 1) 
  OR (f.IFANTIKEPIT = 1) 
  OR (f.IFANTIKSYNAL = 1) 
  OR (f.IFANTIKOTHER = 1) 

--order by f.SUMANTIK
--isnull(f.SUMANTIK,0)!=0


GO



---END SCRIPT 1857
------------------------------------------------------------------------------------
---NEW SCRIPT 1858


ALTER VIEW [dbo].[LISTADIAN_FORT_REPORT]
AS
	SELECT  distinct   TOP (100) PERCENT 
	FORTOTIKES_VIEW.XREOYMENOS, 
	FORTOTIKES_VIEW.APOSTOLEASDESCR, 
	FORTOTIKES_VIEW.PARALISPTISDESCR, 
	ACCOUNTS.AddressCity, 
	LTRIM(RTRIM(LTRIM(RTRIM(ACCOUNTS.AddressStr)) + ' ' + LTRIM(RTRIM(ACCOUNTS.AddressNo)))) AS ADDRESSPARADOSIS,
	LISTESDIANOMIS.PARASTATIKO, 
	FORTOTIKES_VIEW.Code, 
	FORTOTIKES_VIEW.NOPARAST,  
	FORTOTIKES_VIEW.comments, 
	ACCOUNTS.Mobile AS PARALIPTIS_MOBILE,
	LISTESDIANOMIS.SEIRA AS SEIRALISTA, 
	LISTESDIANOMIS.NOPARAST AS NOPARASTKAA, 
	LISTESDIANOMIS.DATEPRINT, 
	LISTESDIANOMIS.OXIMA, 
	LISTESDIANOMIS.DRIVER, 
	FORTOTIKES_VIEW.XREOSISTRITON, 
	TRUCKS.OLastName, 
	TRUCKS.OmProorDescr, 
	FORTOTIKES_VIEW.OMADPROORISMOS, 
	FORTOTIKES_VIEW.SYSKEVASIA, 
	FORTOTIKES_VIEW.TEMAXIA, 
	FORTOTIKES_VIEW.BAROS, 
	FORTOTIKES_VIEW.KYBIKA, 
	ISNULL((FORTOTIKES_VIEW.KOMISTRA * KPAR.IFENIMEROSITAMEIO), 0) AS KOMISTRA, 
	ISNULL((FORTOTIKES_VIEW.DIKAIOMAFORTOTIKIS * KPAR.IFENIMEROSITAMEIO), 0) AS DIKAIOMAFORTOTIKIS, 
	ISNULL((FORTOTIKES_VIEW.OTHERXREOSIS * KPAR.IFENIMEROSITAMEIO), 0) AS OTHERXREOSIS, 
	FORTOTIKES_VIEW.EXT_BARCODE,  
	ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENES * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENES, 
	ISNULL((FORTOTIKES_VIEW.XREOSIOFEILOMENES * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIOFEILOMENES,                       
	ISNULL((FORTOTIKES_VIEW.ASFALISTRA * KPAR.IFENIMEROSITAMEIO), 0) AS ASFALISTRA, 
	ISNULL((FORTOTIKES_VIEW.TAXISXREOSEON * KPAR.IFENIMEROSITAMEIO), 0) AS TAXISXREOSEON, 
	ISNULL((FORTOTIKES_VIEW.KATHARO * KPAR.IFENIMEROSITAMEIO), 0) AS KATHARO, 
	ISNULL((FORTOTIKES_VIEW.SUMPOSO * KPAR.IFENIMEROSITAMEIO), 0) + ISNULL((FORTOTIKES_VIEW.XREOSISTRITON * KPAR.IFENIMEROSITAMEIO), 0)AS SYNOLOOLIKOFORTOTIKIS,
	ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENESCASH * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENESCASH, 
	ISNULL((FORTOTIKES_VIEW.XREOSIPROPLIROMENESPISTOSI * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIPROPLIROMENESPISTOSI,
	ISNULL((FORTOTIKES_VIEW.XREOSIOFEILOMENES * KPAR.IFENIMEROSITAMEIO), 0) AS XREOSIOFEILOMENESCASH,
	FORTOTIKES_VIEW.SUMANTIK, 
	LISTESDIANOMIS.ID, 
	FORTOTIKES_ANA_LISTA.IDFORTOTIKIS
FROM dbo.FORTOTIKES_VIEW AS FORTOTIKES_VIEW WITH (NOLOCK) LEFT JOIN
	dbo.FORTOTIKES_ANA_LISTA AS FORTOTIKES_ANA_LISTA WITH (NOLOCK) ON FORTOTIKES_VIEW.IDFORTOTIKIS = 
	FORTOTIKES_ANA_LISTA.IDFORTOTIKIS LEFT JOIN
	dbo.ACCOUNTS AS ACCOUNTS WITH (NOLOCK) ON FORTOTIKES_VIEW.IDPARALIPTI = ACCOUNTS.id INNER JOIN
	dbo.LISTESDIANOMIS AS LISTESDIANOMIS WITH (NOLOCK) ON FORTOTIKES_ANA_LISTA.IDLISTAS = LISTESDIANOMIS.ID LEFT JOIN
	dbo.TRUCKS AS TRUCKS WITH (NOLOCK) ON LISTESDIANOMIS.OXIMA = TRUCKS.ArKykloforias LEFT JOIN KINDPARASTATIKON AS KPAR 
	ON FORTOTIKES_VIEW.IDPARAST = KPAR.ID
	ORDER BY FORTOTIKES_VIEW.Code, NOPARAST 

GO




---END SCRIPT 1858
------------------------------------------------------------------------------------
---NEW SCRIPT 1859


ALTER VIEW [dbo].[KAA_FORT_REPORT]
AS


with grammes as (
					SELECT 
						IDVOH,
						MIN(TIMDA) AS TIMDA,
						ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
						MIN(U.UntName) AS SYSKEVASIADESCR,
						MIN(PERIEXOMENO) AS PERIEXOMENO,
						ISNULL(SUM(BAROS),0) AS BAROS,
						ISNULL(SUM(KYBIKA),0) AS KYBIKA,
						ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
					FROM GRAMMESFORTTIKIS
					left JOIN Units U ON U.UntID=GRAMMESFORTTIKIS.SYSKEVASIA
					GROUP BY IDVOH
				
				),
XREOSIS AS (
				SELECT 
					IDFORT,
					--KOMISTRA,
					ISNULL(SUM(KOMISTRA),0) AS KOMISTRA,
					ISNULL(SUM(DIKAIOMAFORTOTIKIS),0) AS DIKAIOMAFORTOTIKIS,
					ISNULL(SUM(OTHERXREOSIS),0) AS OTHERXREOSIS,
					isnull(SUM(ASFALISTRA),0) as ASFALISTRA,
					ROUND(ISNULL(SUM(TAXIS),0), 2) AS TAXISXREOSEON,
					ISNULL(SUM(KATHARO),0) AS KATHARO 
				FROM HEADERFORTOTIKIS HD
				GROUP BY IDFORT
	
			),
PIVOTED AS (
					select
						IDVOH,
						[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
					from(
							select
								IDVOH,
								case 
									when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
									when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
									when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
									when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
									when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
									when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
									ELSE 'KOLA'
								END AS SYSKEVASIA,
								TEMAXIA
							from GRAMMESFORTTIKIS
						) AS GF
					pivot
						(
							sum(GF.TEMAXIA)
							FOR GF.SYSKEVASIA in([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
						)AS PV
		)

select
	CASE 
            WHEN f.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' 
            ELSE CASE 
                WHEN f.IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' 
                ELSE CASE 
                    WHEN f.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
                    ELSE CASE 
                        WHEN f.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'                        
                        ELSE 'ΑΓΝΩΣΤΟ' 
                    END 
                END 
            END 
        END AS XREOYMENOS,
        f.AFMAPOSTOLEA,
        f.APOSTOLEASDESCR,
        f.ENTOLEASDESCR,
        f.AFMPARALIPTI,
        f.PARALISPTISDESCR,
        (paral.AddressStr + ' '+paral.AddressNo) as ADDRPARADOSIS,
        paral.AddressCity as ADDRCITYPARAL,
        isnull(grammes.TEMAXIA,0) AS TEMAXIA,
        grammes.SYSKEVASIADESCR AS SYSKEVASIA,
        f.NOPARAST,
        kp.Code,
        paral.AddressCity,
        F.COMMENTS,
        ISNULL(XR.KOMISTRA,0) AS KOMISTRA,
        ISNULL(XR.DIKAIOMAFORTOTIKIS,0) AS DIKAIOMAFORTOTIKIS,
        ISNULL(XR.OTHERXREOSIS,0) AS OTHERXREOSIS,
        grammes.TIMDA,
        ISNULL(grammes.SUMPOSO,0) AS AXIA,
        ISNULL(grammes.BAROS,0) AS BAROS,
        ISNULL(grammes.KYBIKA,0) AS KYBIKA,
        grammes.PERIEXOMENO,
        CASE F.IFPREPAY
			WHEN 1 THEN ISNULL(F.SUMPOSO,0)
			ELSE 0
		END	AS 	XREOSIPROPLIROMENES,
		CASE F.IFOFEILOMENI
			WHEN 1 THEN ISNULL(F.SUMPOSO,0)
			ELSE 0
		END AS XREOSIOFEILOMENES,
		ISNULL(F.SUMANTIK,0) AS SUMANTIK,
		
		CASE F.IFCASH
			WHEN 1 THEN 
				CASE F.IFOFEILOMENI 
					WHEN 1 THEN
						ISNULL(F.SUMPOSO,0)
					ELSE 0
				END 
				ELSE 0  
		END 
		AS XREOSIOFEILOMENESCASH,		
		ISNULL(F.SUMPOSO , 0) + ISNULL(F.EXODATRITON, 0)AS SYNOLOOLIKOFORTOTIKIS,
		KAA.IDPARAST,
        KAA.PARASTATIKO,
        KAA.SEIRA AS SEIRAKAA,
        KAA.NOPARAST AS NOPARASTKAA,
        KAA.POSOEXODA,
		
		
        apost.AddressStr AS ADDRSTRAPOST,
        apost.AddressNo AS ADDRNOAPOST,
        apost.AddressTK AS TKAPOST,
        apost.AddressCity AS CITYAPOST,
        apost.AddressPref AS NOMOSAPOST,
        apost.Tel AS TELAPOST,
        apost.DOY AS DOYAPOST,
        
        PARAL.AddressStr AS ADDRSTRPARAL,
        PARAL.AddressNo AS ADDRNOPARAL,
        PARAL.AddressTK AS ADDRTKPARAL,
        PARAL.AddressPref AS ADDRNOMOSPARAL,
        paral.Mobile AS PARALIPTIS_MOBILE,
		
		KAA.DATEPRINT,
        KAA.OXIMA,
        KAA.DRIVER,
        ISNULL(f.EXODATRITON,0) AS XREOSISTRITON,
        tr.OLastName,
        tr.OmProorDescr,
        (ISNULL(paral.Tel,'') + ' ' + ISNULL(paral.Mobile,'')) AS TELPARALIPTI,  
        f.OMADPROORISMOS,
        ISNULL(XR.ASFALISTRA,0) AS ASFALISTRA, 
        ISNULL(XR.TAXISXREOSEON,0) AS TAXISXREOSEON,
        ISNULL(XR.KATHARO,0) AS KATHARO,
        ISNULL(f.ANAMEXODO,0) AS ANAMEXODO,
        f.EXT_BARCODE,
        case (f.ifprepay*1 + f.IFCASH*2)
			when 3 then ISNULL(f.SUMPOSO,0)
			else 0
		end as XREOSIPROPLIROMENESCASH,
		case (f.ifprepay*1 + f.IFPISTOSI*2)
			when 3 then ISNULL(f.SUMPOSO,0)
			else 0
		end as XREOSIPROPLIROMENESPISTOSI,
		KAA.ID,
		fk.IDFORTOTIKIS,
		ISNULL(DAF.PROPLMETROTHERXREOSEIS , 0) AS PROPLMETROTHERXREOSEIS,
		KAA.IDCOMPANY,
        KAA.IDYPOKATASTIMA,
        KAA.IDXRHSHS,
        KAA.PERIOXIPROORISMOU,
        KAA.PERIOXIPARADOSIS,
        tr.Tel AS TELOWNER,
        f.IDPRAKTOREIO,
        f.PRAKTOREIODESCR, 
        KAA.AFMCUSTOMER,
        KAA.AFMANTAPOKRITIS,
        KAA.ANTAPOKRITIS AS ANTAPOKRITISKAA,
        KAA.FORTOSI,
        KAA.CUSTOMER,
        KAA.ANTAPOKRITIS,
        KAA.OMADPROORISMOS AS OMPROORKAA,
        DR.Tel AS TELDRIVER,
        KAA.CONTAINER,
        KAA.BOAT,
        (ANTAP.AddressStr + ' ' + ANTAP.AddressNo + '  ' + ANTAP.AddressCity + ' - ' + ANTAP.AddressCountry) AS ADDRESSANTAPOKRITI,
        ANTAP.AFM AS AFMANTAPOKRITI,
        ANTAP.DOY AS DOYANTAPOKRITI,
	case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as SYNTHIKI,
        ISNULL(DAF.DIAFORA_EXODA , 0) AS DIAFORA_EXODA,
        ISNULL(DAF.OFEILOMENAKOMISTRA , 0) AS OFEILOMENAKOMISTRA,
        ISNULL(DAF.ERGATIKA , 0) AS ERGETIKA,
        ISNULL(DAF.XREOSEISTRITON , 0) AS XREOSEISTRITON,
        ISNULL(DAF.EMVASTIKA , 0) AS EMVASTIKA,
        ISNULL(DAF.KATHAROPROPLMETR, 0) AS  KATHAROPROPLMETR,
        ISNULL(DAF.TAXISPROPLMETR, 0) AS  TAXISPROPLMETR,
        ISNULL(DAF.KATHAROOFEIL, 0) AS  KATHAROOFEIL,
        ISNULL(DAF.TAXISOFEIL, 0) AS  TAXISOFEIL,
        ISNULL(DAF.OTHERXREOSEIS , 0) AS OTHERXREOSEIS,
        ISNULL(DAF.EXODATRITON, 0)AS EXODATRITON,
        ISNULL(DAF.SYN_POSO_FORTOTIKIS, 0) AS SYN_POSO_FORTOTIKIS,
        ISNULL(DAF.PROPLMETRERGATIKA , 0) AS PROPLMETRERGATIKA,
        ISNULL(DAF.PROPLMETRASFALISTRA , 0) AS PROPLMETRASFALISTRA,
        ISNULL(DAF.PROPLMETRDIKAIOMA , 0) AS PROPLMETRDIKAIOMA, 
        ISNULL(DAF.PROPLMETRKOMISTRA , 0) AS PROPLMETRKOMISTRA,
        (ISNULL(DAF.ERGATIKA , 0)+ ISNULL(DAF.OTHERXREOSEIS , 0) + ISNULL(DAF.ASFALISTRA , 0)) AS ERG_ASF_OTHER, 
        (ISNULL(DAF.ERGATIKA , 0)+ ISNULL(DAF.OTHERXREOSEIS , 0)) AS ERG_OTHER,
        (ISNULL(DAF.ERGATIKA , 0) + ISNULL(DAF.ASFALISTRA , 0)) AS ERG_ASF, 
        (ISNULL(DAF.OTHERXREOSEIS , 0) + ISNULL(DAF.ASFALISTRA , 0)) AS ASF_OTHER,
        (ISNULL(XR.KOMISTRA , 0)+ ISNULL(XR.DIKAIOMAFORTOTIKIS , 0)) AS KOM_DIKAIOMA,
        ISNULL(PVT.DEMATA,0) AS DEMATA,
        ISNULL(PVT.PALETA,0) AS PALETA,
        ISNULL(PVT.KOLA,0) AS KOLA,
        ISNULL(PVT.STAND,0) AS STAND,
        ISNULL(PVT.ROLI,0) AS ROLI,
        ISNULL(PVT.THALAMOS,0) AS THALAMOS
        
from FORTOTIKES f
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI
left join ACCOUNTS APOST on APOST.id=f.IDAPOSTOLEA
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
LEFT JOIN XREOSIS XR ON XR.IDFORT=f.ID
left join FORTOTIKES_ANA_KAA fk on fk.IDFORTOTIKIS=f.ID
left join grammes on grammes.IDVOH=fk.IDFORTOTIKIS
left join KAA on KAA.ID=fk.IDKAA
left join TRUCKS tr on tr.ArKykloforias=KAA.OXIMA
LEFT JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI DAF ON DAF.ID=F.ID
LEFT JOIN ODIGOI DR ON KAA.DRIVER = DR.LastName + ' ' + DR.FirstName
LEFT JOIN ACCOUNTS ANTAP ON ANTAP.id = KAA.IDANTAPOKRITIS
LEFT JOIN PIVOTED PVT ON PVT.IDVOH=FK.IDFORTOTIKIS




GO




---END SCRIPT 1859
