ALTER PROCEDURE [dbo].[diekpFORTOTIKES]
(
	@id							NUMERIC(8,0),
	@IFPARADOSI					INT= 0,
	@DATEPARADOSI				SMALLDATETIME= NULL,
	@IFCANCEL					INT= 0,
	@DATECANCEL					SMALLDATETIME= NULL,
	@IDKINDPAYMENT				NUMERIC(8,0)= NULL,
	@KINDPAYMENTDESCR			NVARCHAR(50)= NULL,
	@AITIOLOGIAPARASTATIKOU		NVARCHAR(50)= NULL,
	@IFEPISTROFI				INT= 0,
	@DATEEPISTROFIS				SMALLDATETIME= NULL,
	@AITIOLOGIAEPISTROFIS		NVARCHAR(50)= NULL,
	@COMMENTSEPISTROFIS			NVARCHAR(MAX)= NULL,
	@YPAITIOS					INT= 0, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
	@IFEPANADROMOLOGISI			INT= 0,
	@IFEPANEKDOSI				INT= 0,
	@IFOKEPANADROMOLOGISI		INT= 0,
	@COMMENTSAKIROSIS			NVARCHAR(MAX)= NULL,
	@DATEPARAL					SMALLDATETIME = NULL,
    @DATEPARAD					SMALLDATETIME = NULL,
    @COMMENTSPARAD				NVARCHAR(MAX) = NULL,
    @COMMANTSPARAL				NVARCHAR(MAX) = NULL,
    @COMMENTS2					NVARCHAR(MAX) = NULL,
    @TIMEPARALFROM				NVARCHAR(5) = NULL,
    @TIMEPARALTO				NVARCHAR(5) = NULL,
    @TIMEPARADFROM				NVARCHAR(5) = NULL,
    @TIMEPARADTO				NVARCHAR(5) = NULL,
	@ANAMEXODO					NUMERIC(18,2)=0,
	@IFPARADOSITOPEL			int =0,
	@IFPARALABIFROMPEL			int =0,
	@IfParadsePrakt				int =0,
	@DateParadsePrakt			DATETIME,
	@CommentsParadsePrakt		NVARCHAR(MAX) = NULL,
	@STATUS						int =0,
	@STATUSDESCR				NVARCHAR(30) = NULL,
	@DateMod					DATETIME,-- = NULL,
	@UserMod					NVARCHAR(50)
	--@TheID						NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;
IF (@IDKINDPAYMENT IS NULL) BEGIN
				UPDATE FORTOTIKES 
				SET 
				IFPARADOSI					=	@IFPARADOSI,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL					=	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				--IDKINDPAYMENT				=	@IDKINDPAYMENT,
				--KINDPAYMENTDESCR			=	@KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU		=	@AITIOLOGIAPARASTATIKOU,
				IFEPISTROFI					=	@IFEPISTROFI,
				DATEEPISTROFIS				=	@DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS		=	@AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS			=	@COMMENTSEPISTROFIS,
				COMMENTSAKIROSIS			=	@COMMENTSAKIROSIS,
				DATEPARAL					=	@DATEPARAL,
				DATEPARAD					=	@DATEPARAD,
				COMMENTSPARAD				=	@COMMENTSPARAD,
				COMMANTSPARAL				=	@COMMANTSPARAL,
				COMMENTS2					=	@COMMENTS2,
				TIMEPARALFROM				=	@TIMEPARALFROM,
				TIMEPARALTO					=	@TIMEPARALTO,
				TIMEPARADFROM				=	@TIMEPARADFROM,
				TIMEPARADTO					=	@TIMEPARADTO,
				ANAMEXODO					=	@ANAMEXODO,
				IFPARADOSITOPEL				=	@IFPARADOSITOPEL,
				IFPARALABIFROMPEL			=	@IFPARALABIFROMPEL,
				IFEPANADROMOLOGISI			=	@IFEPANADROMOLOGISI,
				IFEPANEKDOSI				=	@IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI		=	@IFOKEPANADROMOLOGISI,	
				YPAITIOS					=	@YPAITIOS,
				STATUS						=	@STATUS,
				STATUSDESCR					=	@STATUSDESCR,
				@IfParadsePrakt				=	@IfParadsePrakt,
				DateParadsePrakt			=	@DateParadsePrakt,
				CommentsParadsePrakt		=	@CommentsParadsePrakt,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod

				WHERE ID = @ID
END ELSE BEGIN
				UPDATE FORTOTIKES 
				SET 
				IFPARADOSI					=	@IFPARADOSI,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL					=	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				IDKINDPAYMENT				=	@IDKINDPAYMENT,
				KINDPAYMENTDESCR			=	@KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU		=	@AITIOLOGIAPARASTATIKOU,
				IFEPISTROFI					=	@IFEPISTROFI,
				DATEEPISTROFIS				=	@DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS		=	@AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS			=	@COMMENTSEPISTROFIS,
				COMMENTSAKIROSIS			=	@COMMENTSAKIROSIS,
				DATEPARAL					=	@DATEPARAL,
				DATEPARAD					=	@DATEPARAD,
				COMMENTSPARAD				=	@COMMENTSPARAD,
				COMMANTSPARAL				=	@COMMANTSPARAL,
				COMMENTS2					=	@COMMENTS2,
				TIMEPARALFROM				=	@TIMEPARALFROM,
				TIMEPARALTO					=	@TIMEPARALTO,
				TIMEPARADFROM				=	@TIMEPARADFROM,
				TIMEPARADTO					=	@TIMEPARADTO,
				ANAMEXODO					=	@ANAMEXODO,
				IFPARADOSITOPEL				=	@IFPARADOSITOPEL,
				IFPARALABIFROMPEL			=	@IFPARALABIFROMPEL,
				IFEPANADROMOLOGISI			=	@IFEPANADROMOLOGISI,
				IFEPANEKDOSI				=	@IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI		=	@IFOKEPANADROMOLOGISI,	
				YPAITIOS					=	@YPAITIOS,
				STATUS						=	@STATUS,
				STATUSDESCR					=	@STATUSDESCR,
				@IfParadsePrakt				=	@IfParadsePrakt,
				DateParadsePrakt			=	@DateParadsePrakt,
				CommentsParadsePrakt		=	@CommentsParadsePrakt,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod
				WHERE ID = @ID
		END 

GO

