ALTER PROCEDURE [dbo].[diekpFORTOTIKON]
(
	@IDS						NVARCHAR(MAX),
	@IFDATE_PARADOSI			INT = 0,
	@DATEPARADOSI				NVARCHAR(50)= NULL,--SMALLDATETIME= NULL,
	@IFDATE_CANCEL				INT = 0,
	@DATECANCEL					NVARCHAR(50)= NULL,--SMALLDATETIME= NULL,
	@IFDATE_EPISTROFIS			INT = 0,
	@DATEEPISTROFIS				NVARCHAR(50)= NULL,--SMALLDATETIME= NULL,
	@IFDATE_PARAL				INT = 0,
	@DATEPARAL					NVARCHAR(50)= NULL,--SMALLDATETIME = NULL,
	@IFDATE_PARAD				INT = 0,
    @DATEPARAD					NVARCHAR(50)= NULL,--SMALLDATETIME = NULL,
	@IFDATE_PARADSEPRAKT		INT = 0,
    @DATEPARADSEPRAKT			NVARCHAR(50)= NULL,--SMALLDATETIME = NULL,
    @STATUS						NVARCHAR(1)='0',
	@STATUSDESCR				NVARCHAR(30) = NULL,
	@CHANGES					NVARCHAR(MAX),
	@DateMod					NVARCHAR(50)= NULL,--DATETIME,-- = NULL,
	@UserMod					NVARCHAR(50)= NULL
	)
AS

SET NOCOUNT ON;

DECLARE @THEUPDATESQL NVARCHAR(MAX)
DECLARE @TMPQL NVARCHAR(MAX)

IF (LEN(@IDS) > 0) 
BEGIN
	SET @THEUPDATESQL =	'UPDATE FORTOTIKES SET DateMod = CONVERT(Datetime, ''' +	  @DateMod + '''), UserMod =''' +	@UserMod + ''''
	IF @IFDATE_PARADOSI =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DATEPARADOSI = CONVERT(Datetime, ''' + @DATEPARADOSI + ''')'
		END
	IF @IFDATE_CANCEL =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DATECANCEL = CONVERT(Datetime, ''' + @DATECANCEL + ''')'
		END
	IF @IFDATE_EPISTROFIS =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DATEEPISTROFIS = CONVERT(Datetime, ''' +  @DATEEPISTROFIS+ ''')'
		END
	IF @IFDATE_PARAL =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DATEPARAL = CONVERT(Datetime, ''' + @DATEPARAL +''')'
		END
	IF @IFDATE_PARAD =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DATEPARAD = CONVERT(Datetime, ''' +  @DATEPARAD +''')'
		END
	IF @IFDATE_PARADSEPRAKT =1
		BEGIN
			SET @TMPQL = @THEUPDATESQL
			SET @THEUPDATESQL = @TMPQL + ', DateParadsePrakt = CONVERT(Datetime, ''' +  @DATEPARADSEPRAKT+ ''')'
		END
	SET @TMPQL = @THEUPDATESQL + ', STATUS = ' + @STATUS + ', STATUSDESCR  = ''' + @STATUSDESCR + '''' 
	SET @THEUPDATESQL = @TMPQL + ', ' + @CHANGES + ' WHERE ID IN(' + @IDS + ')'

	EXEC(@THEUPDATESQL);
	--SELECT @THEUPDATESQL;
END      

GO

---END SCRIPT 1864
------------------------------------------------------------------------------------
