ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS

WITH GRAMMES AS 
	(
	SELECT
		IDVOH,
		ISNULL(MIN(TIMDA),'')				  AS TIMDA,
		Isnull(Sum(temaxia), 0)               AS TEMAXIA,
		MIN(u.untname)						  AS SYSKEVASIA,
        Isnull(Sum(baros), 0)                 AS BAROS,
        Isnull(Sum(kybika), 0)                AS KYBIKA,
        ISNULL(MIN(PERIEXOMENO),'')    		  AS PERIEXOMENO,
        ISNULL(SUM(SUMPOSO),0)				  AS AXIA
	FROM GRAMMESFORTTIKIS
	left join Units u on u.UntID = GRAMMESFORTTIKIS.SYSKEVASIA
	GROUP BY IDVOH
	),
POSA AS 
	(
	SELECT 
		ID,
		SUMPOSO,
		ROUND(FORTOTIKES.POSO, 2) AS KATHARO,
		ROUND(FORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
		ROUND(FORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT
	FROM FORTOTIKES
	),
header as
	(
		select 
			IDFORT,
			ROUND(isnull(SUM(hd.komistra),0),2)				  AS  KOMISTRA,
			ROUND(ISNULL(SUM(hd.DIKAIOMAFORTOTIKIS),0),2)     AS DIKAIOMAFORTOTIKIS,
			ROUND(ISNULL(SUM(HD.OTHERXREOSIS),0),2)			  AS OTHERXREOSIS,
			ROUND(ISNULL(SUM(HD.OLIKOSYNOLOXREOSEONFORT),0),2) AS OLIKOSYNOLOXREOSEONFORT,
			ROUND(ISNULL(SUM(HD.ERGATIKA),0),2)				  AS ERGATIKA,
			ROUND(ISNULL(SUM(HD.ASFALISTRA),0),2)			  AS ASFALISTRA,
			ROUND(ISNULL(SUM(HD.TAXIS),0),2)				  AS TAXIS,
			ROUND(ISNULL(SUM(HD.SUMPOSOXRFORT),0),2)		  AS SUMPOSOXRFORT,
			ROUND(ISNULL(SUM(HD.KATHARO),0),2)				  AS KATHARO
			
		from HEADERFORTOTIKIS hd
		GROUP BY IDFORT
	)
	
	
select

	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	Cast(f.noparast AS INT)								AS NOPARAST,
	f.noparastdeltioudianomis,
	f.noparastdeltiouapostolis,
	f.oxima,
	f.omadproorismos,
	CASE f.ifxrentol *1 + f.ifxrapost *2 + f.ifxrparal * 4 + f.ifxrtritou * 8
           WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
           WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
           WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
           WHEN 8 THEN 'ΤΡΙΤΟΣ'
    ELSE 'ΑΓΝΩΣΤΟ'					
    END													AS XREOYMENOS,
    f.apostoleasdescr,
	f.paralisptisdescr,
	f.entoleasdescr,
	f.antapokritisdescr,
	f.nolistasdianomis,
	TRITO.eponimia										AS TRITOSDESCR,
	GR.TIMDA,
	ISNULL(f.POSO,0)									AS POSO,
	ISNULL(f.TAXIS,0)									AS TAXIS,
	ISNULL(f.SUMPOSO,0)									AS SUMPOSO,
	gr.TEMAXIA,
	gr.BAROS,
	gr.KYBIKA,
	gr.SYSKEVASIA,
	CASE F.IFPREPAY 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0) 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE F.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFCASH 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFPISTOSI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GR.PERIEXOMENO,
    f.PERIOXIFORTOSIS,
    f.perioxiparadosis,
    f.comments,
    ISNULL(f.sumantik,0)								AS SUMANTIK,
    f.praktoreiodescr,
    f.status,
    f.idapostolea,
    f.idparalipti,
    f.identolea,
    f.idantapokriti,
    f.idtritou,
    f.idpraktoreio,
    CASE ifantikcash
       WHEN 0 THEN 0
       ELSE antikcash
	END                                                 AS ANTIKCASH,
    CASE ifantikepit
      WHEN 0 THEN 0
      ELSE antikepit
    END                                                 AS ANTIKEPIT,
    CASE ifantiksynal
       WHEN 0 THEN 0
       ELSE antiksynal
    END                                                 AS ANTIKSYNAL,
    CASE ifantikother
       WHEN 0 THEN 0
       ELSE antikother
    END                                                 AS ANTIKOTHER,
    CASE ifcancelantik
       WHEN 0 THEN 'ΟΧΙ'
       ELSE 'ΝΑΙ'
    END                                                 AS IFCANCELANTIK,
   f.commentsantik,
   f.dateparadosi,
   f.comments2,
   HD.komistra						                    AS KOMISTRA,
   f.exodatriton		                                AS XREOSISTRITON,
   HD.dikaiomafortotikis						        AS DIKAIOMAFORTOTIKIS,
   HD.otherxreosis						                AS OTHERXREOSIS,
   HD.olikosynoloxreoseonfort						    AS OLIKOSYNOLOXREOSEONFORT,
   HD.ergatika						                    AS ERGATIKA,
        
   CASE f.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFPREPAY,
         CASE f.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFOFEILOMENI,
         GR.AXIA								        AS AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRENTOL,
         f.kindpaymentdescr,
         f.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRTRITOU, 
         f.ifantikcash,
         f.ifantikepit,
         f.ifantiksynal,
         f.ifantikother,
         f.ifdelete,
         f.ifcancel,   
         f.aa_antik,
         f.nolistasantik,
         f.ifparadosi,
         f.aitiologiaparastatikou,
         CONVERT(VARCHAR, f.datefortosis, 103)			AS DATEFORTOSIS,
         f.ifepistrofi,
         f.DATEEPISTROFIS,
         f.dromologio,
         f.thesi,
         f.aitiologiaepistrofis,
         f.commentsepistrofis,
         f.ifcash,
         f.ifpistosi,
         f.statusdescr,
         f.ypaitios,
         f.ifepanadromologisi,
         f.ifepanekdosi,
         f.ifokepanadromologisi,
         f.noparastantik,
         f.commentsakirosis,
         f.ifeisprantik,
         f.ifparadosiantik,
         f.ifparalaviantik,
         f.commentsparadantik,
         f.commantsparalantik,
         f.commentseisprantik,
         CONVERT(VARCHAR, f.dateparadantik, 102)		AS DATEPARADANTIK,
         CONVERT(VARCHAR, f.dateeisprantik, 102)		AS DATEEISPRANTIK,
         f.eispraxasantik,
         f.noparparadantik,
         f.noparasteisprantik,
         f.noparparalantik,
         f.commentsparad,
         f.commantsparal,
         f.if_transftoesex,
         f.timeparalfrom,
         f.timeparalto,
         f.timeparadfrom,
         f.timeparadto,
         CONVERT(VARCHAR, f.datecancelantik, 102)		AS DATECANCELANTIK,
         f.idparast,
         f.taxispercent,
         f.anamexodo,
         f.id											AS IDFORTOTIKIS,
         f.afmxreoumenou, 
		 HD.asfalistra,
         HD.TAXIS										AS TAXISXREOSEON,
         HD.sumposoxrfort,
         HD.katharo,
         f.orofos,
         f.orofosdescr,
         f.koudouni,
         APOST.epagelma                                 AS EPAGAPOST,
         APOST.AddressCountry							AS COUNTRYAPOST,
         APOST.addressstr                               AS ADDRSTRAPOST,
         APOST.addressno                                AS ADDRNOAPOST,
         APOST.addresstk                                AS TKAPOST,
         APOST.addresscity                              AS CITYAPOST,
         APOST.addresspref                              AS NOMOSAPOST,
         APOST.tel                                      AS TELAPOST,
         APOST.tel2                                     AS TEL2APOST,
         APOST.fax                                      AS FAXAPOST,
         APOST.doy                                      AS DOYAPOST,
         PARAL.epagelma                                 AS EPAGPARAL,
         PARAL.AddressCountry							AS COUNTRYPARAL,
         PARAL.addressstr                               AS ADDRSTRPARAL,
         PARAL.addressno                                AS ADDRNOPARAL,
         PARAL.addresstk                                AS ADDRTKPARAL,
         PARAL.addresscity                              AS ADDRCITYPARAL,
         PARAL.addresspref                              AS ADDRNOMOSPARAL,
         PARAL.tel                                      AS TELPARAL,
         PARAL.tel2                                     AS TEL2PARAL,
         PARAL.fax                                      AS FAXPARAL,
         PARAL.doy                                      AS DOYPARAL,
         ENTOL.epagelma                                 AS EPAGENTOL,
         ENTOL.AddressCountry							AS COUNTRYENTOL,
         ENTOL.addressstr                               AS ADDRSTRENTOL,
         ENTOL.addressno                                AS ADDRNOENTOL,
         ENTOL.addresstk                                AS ADDRTKENTOL,
         ENTOL.addresscity                              AS ADDRCITYENTOL,
         ENTOL.addresspref                              AS ADDRNOMOSENTOL,
         ENTOL.tel                                      AS TELENTOL,
         ENTOL.tel2                                     AS TEL2ENTOL,
         ENTOL.fax                                      AS FAXENTOL,
         ENTOL.doy                                      AS DOYENTOL,
         
         TRITO.epagelma                                 AS EPAGTR,
         TRITO.AddressCountry							AS COUNTRY_TRITOS,
         TRITO.addressstr                               AS ADDRSTTR,
         TRITO.addressno                                AS ADDRNOTR,
         TRITO.addresstk                                AS ADDRTKTR,
         TRITO.addresscity                              AS ADDRCITYTR,
         TRITO.addresspref                              AS ADSTRDRNOMO,
         TRITO.tel                                      AS TELTR,
         TRITO.tel2                                     AS TEL2TR,
         TRITO.fax                                      AS FAXTR,
         TRITO.doy                                      AS DOYTR,
         f.afmapostolea,
         f.afmentolea,
         f.afmparalipti,
         f.afmtritou,
         f.afmantapokriti,
         f.ifparadositopel,
         f.ifparalabifrompel,
         PARAL.mobile                                   AS MOBILEPARALIPTI,
         f.ifexoflisi,
         ENTOL.mobile                                   AS MOBILEENTOLTEA,
         APOST.mobile                                   AS MOBILEAPOSTOLEA,
         TRITO.mobile                                   AS MOBILETRITOU,
         f.iddriver,
         f.driverdescr,
         f.idxrhshs,
         f.idcompany,
         f.idypokatastima,
         f.container,
         f.boat,
         CASE ifxrentol *1 + ifxrapost *2 + ifxrtritou *4 +ifxrparal *8
			when 1 then ENTOL.PrintableComment
			when 2 then APOST.PrintableComment
			when 4 then TRITO.PrintableComment
			when 8 then PARAL.PrintableComment
			else ''
		end as PROEP_SXOLIO,
		f.pod_added,
         f.pod_path,
         f.pod_user,
         f.pod_path_2,
         f.ext_id,
         f.no_ext_order,
         f.usercreate,
         f.datecreate,
         f.ext_barcode,
         OMPR.id                                               AS IDOMPROOR,
         f.idkentroukostous,
         f.no_ext_order_ik,
         f.identolis,
         f.if_cancel,
         f.id_cancellation,
         f.seira_cancellation,
         f.noparast_cancellation,
         f.details_cancellation,
         f.canceldate,
         f.usermod,
         f.datemod,
         f.DATEPARAL,
         f.DATEPARAD,
         f.DATECANCEL,
         f.if_from_antap,
         f.if_to_antap,
         f.IDXREOUMENOU,
         F.NO_EXT_FORT,
         kp.PRINTLABEL,
         ANTAP.DOY												AS DOY_ANTAPOKIRTI,	
         ANTAP.AddressCountry									AS COUNTRY_ANTAPOKRITI,
         ANTAP.AddressCity										AS CITY_ANTAPOKRITI,
         ANTAP.AddressStr										AS ADDRESS_ANTAPOKRITI,
         ANTAP.AddressNo										AS ADDRESSNO_ANTAPOKRITI,
         ANTAP.Tel												AS TEL_ANTAPOKRITI,
         ANTAP.Mobile											AS MOBILE_ANTAPOKRITI, 
         ANTAP.EMAIL											AS EMAIL_ANTAPOKRITI,
         ANTAP.Epagelma											AS EPAGELMA_ANTAPOKRITI,
		 f.ARANAFORAS,
		 YPOK.Eponimia											AS YPOKATASTHMA,
		 YPOK.AddressStr										AS ADDRESS_YPOKATASTHMA,
		 YPOK.AddressTK											AS TK_YPOKATASTHMA,
		 YPOK.AddressCity										AS CITY_YPOKATASTHMA,
		 YPOK.BARCODE_Prefix									AS BARCODEPREFIX_YPOKAT,
		 HDVP.DescrCatalog										AS TIMOKATALOGOS,
		 YPOK.EMAIL												AS EMAIL_YPOKATASTHMA,
		 BANKS_A.FSBANKS_DESCR									AS YPOKATASTHMA_BANK_A,
		 YPOK.IBANA												AS YPOKATASTHMA_IBAN_A,
		 BANKS_B.FSBANKS_DESCR									AS YPOKATASTHMA_BANK_B,
		 YPOK.IBANB												AS YPOKATASTHMA_IBAN_B,
		 BANKS_C.FSBANKS_DESCR									AS YPOKATASTHMA_BANK_C,
		 YPOK.IBANC												AS YPOKATASTHMA_IBAN_C, 
		 ENTOL.EMAIL											AS EMAIL_ENTOL,
		 COMP.Eponimia											AS COMPANY_NAME,
		 COMP.AFM												AS COMPANY_AFM,
		 COMP.DOY												AS COMPANY_DOY,
		 COMP.Epagelma											AS COMPANY_EPAGGELMA,
		 COMP.AddressStr										AS COMPANY_ADDRESS,
		 COMP.AddressTK											AS COMPANY_TK,
		 COMP.AddressCity										AS COMPANY_CITY,
		 COMP.Tel												AS COMPANY_TELEPHONE,
		 COMP.Tel2												AS COMPANY_TELEPHONE_2,
		 COMP.Fax												AS COMPANY_FAX,
		 COMP.Mobile											AS COMPANY_MOBILE,
		 COMP.EMAIL												AS COMPANY_EMAIL,
		 CUR.DESCR												AS CURRENCY_DESCR,
		 CUR.SYMBOL												AS CURRENCY_SYMBOL,		 
		 DBO.GetVOHEAFDSS(f.ID, 2)								AS EAFDSS 


from FORTOTIKES f
LEFT JOIN KINDPARASTATIKON kp ON kp.ID=f.IDPARAST
LEFT JOIN ACCOUNTS APOST	  ON APOST.ID=f.IDAPOSTOLEA
LEFT JOIN ACCOUNTS PARAL	  ON PARAL.ID=f.IDPARALIPTI
LEFT JOIN ACCOUNTS ENTOL	  ON ENTOL.id=f.IDENTOLEA
LEFT JOIN ACCOUNTS TRITO	  ON TRITO.id=F.IDTRITOU
LEFT JOIN ACCOUNTS ANTAP	  ON ANTAP.id=f.IDANTAPOKRITI
LEFT JOIN GRAMMES GR		  ON GR.IDVOH=F.ID
LEFT JOIN POSA				  ON POSA.ID=f.ID
LEFT JOIN HEADER HD			  ON HD.IDFORT=f.ID
LEFT JOIN OMADIKOI_PROORISMOI OMPR ON OMPR.Descr = f.OMADPROORISMOS AND OMPR.IFDELETE!=1
LEFT JOIN dbo.COMPANIES COMP on COMP.id=f.IDCOMPANY
LEFT JOIN dbo.COMPANIES YPOK on YPOK.id=f.IDYPOKATASTIMA
LEFT JOIN dbo.HEADERVOHPRICING HDVP on HDVP.IDVOH=f.IDENTOLIS
LEFT JOIN CURRENCY CUR ON CUR.ID=kp.IDCURRENCY
LEFT JOIN Banks BANKS_A ON BANKS_A.FSBANKS_ID=YPOK.IDBANKA
LEFT JOIN Banks BANKS_B ON BANKS_B.FSBANKS_ID=YPOK.IDBANKB
LEFT JOIN Banks BANKS_C ON BANKS_C.FSBANKS_ID=YPOK.IDBANKC
LEFT JOIN Banks BANKS_D ON BANKS_D.FSBANKS_ID=YPOK.IDBANKD






GO

---END SCRIPT 1866
