ALTER PROCEDURE [dbo].[AADE_FIX_POSA_VOH_SALES] (
	@IDVOH INT
) AS

BEGIN

	SET NOCOUNT ON;



	with taxcorrections as (
		select 
			id,
			idvoh,
			ROUND(TELTIMI * 0.01 * TAXISSET, 2) NEWSUMTAXIS
		from grammesvoh 
		where IDVOH = @IDVOH
	)

	update GRAMMESVOH set
		SUMTAXIS = NEWSUMTAXIS,
		SUMPOSO = TELTIMI + NEWSUMTAXIS
	from grammesvoh
	join taxcorrections on taxcorrections.ID = grammesvoh.ID
	where grammesvoh.idvoh = @IDVOH;

	
	with grammesvohsum as (
		select 
			idvoh,
			SUM(TELTIMI) TELTIMI,
			SUM(SUMTAXIS) SUMTAXIS,
			SUM(SUMPOSO) SUMPOSO
		from GRAMMESVOH
		where idvoh = @IDVOH
		group by IDVOH
	)

	update voh set
		POSO = grammesvohsum.TELTIMI,
		TAXIS = grammesvohsum.SUMTAXIS,
		SUMPOSO = grammesvohsum.SUMPOSO
	from voh
	join grammesvohsum on grammesvohsum.IDVOH = voh.ID;


	-- Αντιγραφη ΣΥΝΟΛΩΝ του παραστατικού σε λοιπές παπαριές (HEADERVOH? SUMANAVOH? SASGAMHSEKANENASVOHSHMERA?)
	-- your choice
	--

	--select poso, Taxis, sumposo from VOH where ID = 107047
	update header
		set KATHARO = VOH.POSO,
			TAXIS = VOH.TAXIS,
			SUMPOSOXRVOH = VOH.SUMPOSO,
			ARXPOSO = VOH.POSO
	from HEADERVOH header
	join VOH on VOH.ID = header.IDVOH
	where header.IDVOH = @IDVOH

END


GO


---END SCRIPT 1873
