ALTER PROCEDURE [dbo].[insertTOKAA]

(
	@IDPARAST					numeric(18, 0)= NULL,
	@PARASTATIKO				nchar(100)= NULL,
	@SEIRA						nchar(10)  = NULL,
	@NOPARAST					nvarchar(20) = NULL,
	@DATEPRINT					smalldatetime =NULL,
	@DATEPARADOSI				smalldatetime =NULL,
	@IFCANCEL					int =0,
	@DATECANCEL					smalldatetime =NULL,
	@OXIMA						nvarchar(60) = NULL,
	@DRIVER						nvarchar(50) = NULL,
	@PERIOXIPROORISMOU			nvarchar(50) = NULL,
	@PERIOXIPARADOSIS			nvarchar(50) = NULL,
	@POSO						numeric(18, 2)= NULL,
	@TAXISPERCENT				numeric(18, 2) =NULL,
	@TAXIS						numeric(18, 2)= NULL,
	@SUMPOSO					numeric(18, 2)= NULL,
	@POSOEXODA					numeric(18, 2)= NULL,
	@TAXISPERCENTEXODA			numeric(18, 2)= NULL,
	@TAXISEXODA					numeric(18, 2) =NULL,
	@SUMPOSOEXODA				numeric(18, 2)= NULL,
	@STATUS						nvarchar(50) = NULL,
	@COMMENTS					nvarchar(max)= NULL,
	@NOFORT						NVARCHAR(10)=NULL,
	@POSOPROPL					numeric(18, 2)= NULL,
	@POSOOFEIL					numeric(18, 2)= NULL,
	@POSOKOMISTRA				numeric(18, 2)= NULL,
	@POSOEXTRITON				numeric(18, 2)= NULL,
	@SUMBAROS					numeric(18, 2)= NULL,
	@IDSTATUS					numeric(18, 0)= NULL,
	@OMADPROORISMOS				nvarchar(50) = NULL,
	@IDXRHSHS					NUMERIC(18,0) = 0,
	@IDCOMPANY					NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = 0,
	@IDCUSTOMER					numeric(18, 0)= NULL,
	@AFMCUSTOMER				NVARCHAR(10)= NULL,
	@CUSTOMER					nchar(80)= NULL,
	@FORTOSI					NVARCHAR (50) = NULL,
	@IDANTAPOKRITIS				numeric(18, 0)= NULL,
	@AFMANTAPOKRITIS			NVARCHAR(10)= NULL,
	@ANTAPOKRITIS				nchar(80)= NULL,
	@CONTAINER					NVARCHAR (50) =NULL,
	@BOAT						NVARCHAR (50) =NULL,
	@UserCreate					nvarchar (50)= NULL,
	@DateCreate					datetime = NULL,	
	@ifDelete					int = 0,
	@TheID						NUMERIC(18, 0)= NULL output
) 
AS
DECLARE @TAXIPERCENT NUMERIC (18,2)
SELECT @TAXIPERCENT= KP.TAXISPERCENT FROM KINDPARASTATIKON KP
JOIN KAA ON KAA.IDPARAST=KP.ID

		
		BEGIN
			INSERT INTO KAA
				(
				IDPARAST,
				PARASTATIKO,
				SEIRA,
				NOPARAST,
				DATEPRINT,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				OXIMA,
				DRIVER,
				PERIOXIPROORISMOU,
				PERIOXIPARADOSIS,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				POSOEXODA,
				TAXISPERCENTEXODA,
				TAXISEXODA,
				SUMPOSOEXODA,
				STATUS,
				COMMENTS,
				NOFORT,
				POSOPROPL,
				POSOOFEIL,
				POSOKOMISTRA,
				POSOEXTRITON,
				SUMBAROS,
				IDSTATUS,
				OMADPROORISMOS,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IDCUSTOMER,
				AFMCUSTOMER,
				CUSTOMER,
				IDANTAPOKRITIS,
				AFMANTAPOKRITIS,
				ANTAPOKRITIS,
				FORTOSI,
				CONTAINER,
				BOAT,
				UserCreate,
				DateCreate,
				ifDelete
				)
			VALUES
				(
				@IDPARAST,
				@PARASTATIKO,
				@SEIRA,
				@NOPARAST,
				@DATEPRINT,
				@DATEPARADOSI,
				@IFCANCEL,
				@DATECANCEL,
				@OXIMA,
				@DRIVER,
				@PERIOXIPROORISMOU,
				@PERIOXIPARADOSIS,
				(@SUMPOSO/(1+@TAXIPERCENT/100)),
				@TAXISPERCENT,
				@SUMPOSO*((@TAXIPERCENT/100)/(1+@TAXIPERCENT/100)),
				@SUMPOSO,
				@POSOEXODA,
				@TAXISPERCENTEXODA,
				@TAXISEXODA,
				@SUMPOSOEXODA,
				@STATUS,
				@COMMENTS,
				@NOFORT,
				@POSOPROPL,
				@POSOOFEIL,
				@POSOKOMISTRA,
				@POSOEXTRITON,
				@SUMBAROS,
				@IDSTATUS,
				@OMADPROORISMOS,
				@IDXRHSHS,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IDCUSTOMER,
				@AFMCUSTOMER,
				@CUSTOMER,
				@IDANTAPOKRITIS,
				@AFMANTAPOKRITIS,
				@ANTAPOKRITIS,
				@FORTOSI,
				@CONTAINER,
				@BOAT,
				@UserCreate,
				@DateCreate,		
				@ifDelete

				)
			SELECT  @TheID = MAX(ID) FROM dbo.KAA WITH (NOLOCK);
		
		update KAA set TAXISPERCENT=@TAXIPERCENT where ID=@TheID;
		
		END
GO


