ALTER VIEW [dbo].[LISTERLISTESDIAN_VIEW]
AS

with fal as (
		select 
			IDLISTAS,
			COUNT(IDFORTOTIKIS) as fortotikes
		from FORTOTIKES_ANA_LISTA fl
		group by IDLISTAS
),
xreoseis_without_dikaioma as (
		select
		
			xrd.IDVOH,
			SUM(xrd.POSO) POSO,
			SUM(xrd.TAXIS) TAXIS,
			SUM(xrd.SUMPOSO) SUPOSO		
		from XREOSISANADELTIO xrd
		join Xreoseis xr on xr.ID=xrd.IDXREOSIS and isnull(xr.ifDikaiomaFortotikis,0)=0
		WHERE ISNULL(IF_TO_FORTOTIKI,0)=1
		GROUP BY IDVOH		
),
xreoseis_dikaioma as(
		select
		
			xrd.IDVOH,
			SUM(xrd.POSO) POSO,
			SUM(xrd.TAXIS) TAXIS,
			SUM(xrd.SUMPOSO) SUPOSO	
		from XREOSISANADELTIO xrd
		join Xreoseis xr on xr.ID=xrd.IDXREOSIS and isnull(xr.ifDikaiomaFortotikis,0)=1
		WHERE ISNULL(IF_TO_FORTOTIKI,0)=1
		GROUP BY IDVOH	
), synola_ana_lista as (
	select 
		ld.ID idlistas,
		SUM(xd.POSO) xdposo,
		SUM(xd.TAXIS) xdtaxis,
		SUM(xd.SUPOSO) xdsumposo,
		SUM(xwd.POSO) xwdposo,
		SUM(xwd.TAXIS) xwdtaxis,
		SUM(xwd.SUPOSO) xwdsumposo
	from LISTESDIANOMIS ld
	join FORTOTIKES_ANA_LISTA fal on fal.IDLISTAS = ld.id
	join xreoseis_dikaioma xd on xd.IDVOH = fal.IDFORTOTIKIS
	join xreoseis_without_dikaioma xwd on xwd.IDVOH = fal.IDFORTOTIKIS
	group by ld.id
)

select 

	ld.ID,
	ld.IDPARAST,
	ld.PARASTATIKO,
	ld.SEIRA,
	ld.NOPARAST,
	ld.DATEPRINT,
	ld.DATEPARADOSI,
    ld.IFCANCEL,
    ld.DATECANCEL,
    ld.OXIMA,
    ld.DRIVER,
    ld.PERIOXIPROORISMOU,
    ld.PERIOXIPARADOSIS,
    ld.POSO,
    ld.TAXISPERCENT,
    ld.TAXIS,
    ld.SUMPOSO,
    ld.POSOEXODA,
    ld.TAXISPERCENTEXODA,
    ld.TAXISEXODA,
    ld.SUMPOSOEXODA,
    ld.POSOPROPL,
    ld.POSOOFEIL,
    ld.POSOKOMISTRA,
    ld.POSOEXTRITON,
    ld.SUMBAROS,
    ld.IDSTATUS,
    ld.STATUS,
    ld.COMMENTS,
    ld.ifDelete,
    ld.OMADPROORISMOS,
    ld.IDXRHSHS,
    ld.IDCOMPANY,
    ld.IDYPOKATASTIMA,
    ld.UserCreate,
    ld.DateCreate,
    ld.UserMod,
    ld.DateMod,
	isnull(sal.xwdposo,0) KATHAROXREOSEON,
	isnull((sal.xwdtaxis+sal.xdtaxis),0)  AS TAXISXREOSEON,
	isnull(sal.xdposo,0) AS DIKFORTOTIKIS,
	
	isnull(fal.fortotikes,0) as fortotikes  
	
	

from LISTESDIANOMIS ld
left join fal on fal.IDLISTAS=ld.ID
left join synola_ana_lista sal on sal.idlistas = ld.ID


GO


---END SCRIPT 1879
