ALTER TABLE companies ADD AutoSendAadeValue INT DEFAULT(0)
GO
CREATE FUNCTION FIX_AADE_HOUR 
(
	@POUTSBLOU VARCHAR(10)
)
RETURNS VARCHAR(5)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @NEWPOUTSBLOU VARCHAR(5)

	DECLARE @SPLITCHAR CHAR = ':'
	DECLARE @INDEX INT = CHARINDEX(@SPLITCHAR, @POUTSBLOU);

	DECLARE @HOUR VARCHAR(2) = SUBSTRING(@POUTSBLOU, 0, @INDEX);
	DECLARE @MINUTE VARCHAR(2) = SUBSTRING(@POUTSBLOU, @INDEX+1, LEN(@POUTSBLOU)-@INDEX);

	DECLARE @NEWHOUR VARCHAR(2) = REPLICATE('0', 2-LEN(@HOUR)) + @HOUR;
	DECLARE @NEWMINUTE VARCHAR(2) = REPLICATE('0', 2-LEN(@MINUTE)) + @MINUTE;

	SET @NEWPOUTSBLOU = @NEWHOUR + @SPLITCHAR + @NEWMINUTE;

	-- Return the result of the function
	RETURN @NEWPOUTSBLOU

END
GO



CREATE TRIGGER FIX_AUTOSENDVALUE
   ON  COMPANIES
   AFTER  INSERT,UPDATE
AS 
BEGIN
	SET NOCOUNT ON;

	UPDATE COMPANIES
		SET AutoSendAadeValue = dbo.FIX_AADE_HOUR(companies.AutoSendAadeValue)
	FROM COMPANIES
	JOIN INSERTED ON INSERTED.ID = COMPANIES.ID

END
GO




