ALTER VIEW [dbo].[SUMPOSA_PER_ACCOUNT_PEL]
AS 
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDPARASTATIKON.IF_XREOSI) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA 
FROM FORTOTIKES LEFT JOIN KINDPARASTATIKON ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_XREOSI = 1 
AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) LEFT OUTER JOIN
PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = dbo.KINDPARASTATIKON.ID INNER JOIN
CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON AND If_EXODO = 0
INNER JOIN ACCOUNTS ON FORTOTIKES.IDXREOUMENOU = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE FORTOTIKES.ifDelete = 0 
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, 
ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA 
