	)
AS

SET NOCOUNT ON;
IF (@IDKINDPAYMENT IS NULL) BEGIN
				UPDATE PROFORTOTIKES 
				SET 
				IFPARADOSI					=	@IFPARADOSI,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL					=	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				--IDKINDPAYMENT				=	@IDKINDPAYMENT,
				--KINDPAYMENTDESCR			=	@KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU		=	@AITIOLOGIAPARASTATIKOU,
				IFEPISTROFI					=	@IFEPISTROFI,
				DATEEPISTROFIS				=	@DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS		=	@AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS			=	@COMMENTSEPISTROFIS,
				COMMENTSAKIROSIS			=	@COMMENTSAKIROSIS,
				DATEPARAL					=	@DATEPARAL,
				DATEPARAD					=	@DATEPARAD,
				COMMENTSPARAD				=	@COMMENTSPARAD,
				COMMANTSPARAL				=	@COMMANTSPARAL,
				COMMENTS2					=	@COMMENTS2,
				TIMEPARALFROM				=	@TIMEPARALFROM,
				TIMEPARALTO					=	@TIMEPARALTO,
				TIMEPARADFROM				=	@TIMEPARADFROM,
				TIMEPARADTO					=	@TIMEPARADTO,
				ANAMEXODO					=	@ANAMEXODO,
				IFPARADOSITOPEL				=	@IFPARADOSITOPEL,
				IFPARALABIFROMPEL			=	@IFPARALABIFROMPEL,
				IFEPANADROMOLOGISI			=	@IFEPANADROMOLOGISI,
				IFEPANEKDOSI				=	@IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI		=	@IFOKEPANADROMOLOGISI,	
				YPAITIOS					=	@YPAITIOS,
				STATUS						=	@STATUS,
				STATUSDESCR					=	@STATUSDESCR,
				--IfParadsePrakt				=	@IfParadsePrakt,
				--DateParadsePrakt			=	@DateParadsePrakt,
				--CommentsParadsePrakt		=	@CommentsParadsePrakt,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod

				WHERE ID = @ID
END ELSE BEGIN
				UPDATE PROFORTOTIKES 
				SET 
				IFPARADOSI					=	@IFPARADOSI,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL					=	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				IDKINDPAYMENT				=	@IDKINDPAYMENT,
				KINDPAYMENTDESCR			=	@KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU		=	@AITIOLOGIAPARASTATIKOU,
				IFEPISTROFI					=	@IFEPISTROFI,
				DATEEPISTROFIS				=	@DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS		=	@AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS			=	@COMMENTSEPISTROFIS,
				COMMENTSAKIROSIS			=	@COMMENTSAKIROSIS,
				DATEPARAL					=	@DATEPARAL,
				DATEPARAD					=	@DATEPARAD,
				COMMENTSPARAD				=	@COMMENTSPARAD,
				COMMANTSPARAL				=	@COMMANTSPARAL,
				COMMENTS2					=	@COMMENTS2,
				TIMEPARALFROM				=	@TIMEPARALFROM,
				TIMEPARALTO					=	@TIMEPARALTO,
				TIMEPARADFROM				=	@TIMEPARADFROM,
				TIMEPARADTO					=	@TIMEPARADTO,
				ANAMEXODO					=	@ANAMEXODO,
				IFPARADOSITOPEL				=	@IFPARADOSITOPEL,
				IFPARALABIFROMPEL			=	@IFPARALABIFROMPEL,
				IFEPANADROMOLOGISI			=	@IFEPANADROMOLOGISI,
				IFEPANEKDOSI				=	@IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI		=	@IFOKEPANADROMOLOGISI,	
				YPAITIOS					=	@YPAITIOS,
				STATUS						=	@STATUS,
				STATUSDESCR					=	@STATUSDESCR,
				--IfParadsePrakt				=	@IfParadsePrakt,
				--DateParadsePrakt			=	@DateParadsePrakt,
				--CommentsParadsePrakt		=	@CommentsParadsePrakt,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod
				WHERE ID = @ID
		END 
		
GO

