 ALTER PROCEDURE [dbo].[InserttoGRAMMESVOH]
(
	@IDVOH				NUMERIC(8,0)= NULL,
	@LINE				int = NULL,
	@CodeEidos			NVARCHAR(20),	
	@DescrEidos			NVARCHAR(50),	
	@SYSKEVASIA			NVARCHAR(50)= NULL,
	@SYSKEVASIADESCR	NVARCHAR(50)= NULL,	
	@TEMAXIA			NUMERIC(18,4)= NULL,
	@BarCode			NVARCHAR(50)= NULL,
	@TIMDA				NVARCHAR(50)= NULL,
	@TIMITEM			NUMERIC(18,4)= NULL,
	@ARXTIMI			NUMERIC(18,4)= NULL,
	@EKPTPERCENT		NUMERIC(18,4)= NULL,
	@EKPT				NUMERIC(18,4)= NULL,
	@TELTIMI			NUMERIC(18,2)= NULL,
	@TAXISSET			NUMERIC(18,2)= NULL,
	@SUMTAXIS			NUMERIC(18,2)= NULL,
	@SUMPOSO			NUMERIC(18,2)= NULL,
	@IDMMB				NUMERIC(18,0)= NULL,
	@TEMAXIAB			NUMERIC(18,4)= NULL,
	@FIELDXREOSIS		NVARCHAR(15)= NULL,			
	@TIMITEMB			NUMERIC(18,4) = NULL,
	@MMBDESCR			NVARCHAR(50)= NULL,	
	@SxesiAB			NUMERIC(18,4) = NULL,
	@BAROS				NUMERIC(18,4)= NULL,	
	@KYBIKA				NUMERIC(18,3)= NULL,
	@IDMMA				NUMERIC(8,0)= NULL,
	@EndDate			smalldatetime = NULL,
	@Comments			NVARCHAR(255)= NULL,
	@IfTransport		int = 0,
	@IfPlacement		int = 0,
	@IfAssembly			int = 0,
	@IfDisAssembly		int = 0,	
	@TheID				NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;
			INSERT INTO GRAMMESVOH
			(
				IDVOH,
				LINE,
				CodeEidos,	
				DescrEidos,	
				SYSKEVASIA,
				SYSKEVASIADESCR,	
				TEMAXIA,
				BarCode,
				TIMDA,
				TIMITEM,
				ARXTIMI,
				EKPTPERCENT,
				EKPT,
				TELTIMI,
				TAXISSET,
				SUMTAXIS,
				SUMPOSO,
				IDMMB,
				TEMAXIAB,
				FIELDXREOSIS,
				TIMITEMB,
				MMBDESCR,	
				BAROS,	
				KYBIKA,
				SxesiAB,
				Comments,			
				IfTransport,
				IfPlacement,
				IfAssembly,
				IfDisAssembly,	
				EndDate	
			)
			VALUES
			(
				@IDVOH,
				@LINE,
				@CodeEidos,	
				@DescrEidos,	
				@SYSKEVASIA,
				@SYSKEVASIADESCR,	
				@TEMAXIA,
				@BarCode,
				@TIMDA,
				@TIMITEM,
				@ARXTIMI,
				@EKPTPERCENT,
				@EKPT,
				@TELTIMI,
				@TAXISSET,
				@SUMTAXIS,
				@teltimi+@SUMTAXIS,
				@IDMMB,
				@TEMAXIAB,
				@FIELDXREOSIS,
				@TIMITEMB,
				@MMBDESCR,	
				@BAROS,	
				@KYBIKA,
				@SxesiAB,
				@Comments,
				@IfTransport,
				@IfPlacement,
				@IfAssembly,
				@IfDisAssembly,	
				@EndDate	
			)

SELECT  @TheID = MAX(ID) FROM dbo.GRAMMESVOH WITH (NOLOCK)

;

GO

---END SCRIPT 1885
