 UNION 
 SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
 SUM(SUMPOSO * KINDPARASTATIKON.IF_PISTOSI) * (-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA,  
 ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC FROM ESODA LEFT JOIN KINDPARASTATIKON ON ESODA.IDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_PISTOSI = 1 
 AND KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5)
 INNER JOIN ACCOUNTS ON ESODA.IDPROM = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE ESODA.ifDelete = 0 
