ACCOUNTS.IF_PROM, ACCOUNTS.ifDelete, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA, ACCOUNTS.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDPARASTATIKON.IF_PISTOSI)*(-1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA, 
ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC FROM RECEIPTS LEFT JOIN KINDOFPAYMENTS ON RECEIPTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID AND KINDOFPAYMENTS.IF_CASH = 1-- AND IF_IN = 1 
LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON RECEIPTS.IDKINDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_AFORAEXTRITON != 1
INNER JOIN ACCOUNTS ON RECEIPTS.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE RECEIPTS.ifDelete = 0 
AND (IFENIMEROSITAMEIO = 1 OR IF_ENIMEROSIKARTELA = 1)  
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA, ACCOUNTS.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * IF_XREOSI)*(1) AS SUMPOSO,DATEPRINT,  ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA,  
ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC FROM RECEIPTS LEFT JOIN KINDOFPAYMENTS ON RECEIPTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID AND KINDOFPAYMENTS.IF_CASH = 1-- AND IF_OUT = 1
LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON RECEIPTS.IDKINDPARAST = KINDPARASTATIKON.ID AND KINDPARASTATIKON.IF_AFORAEXTRITON != 1
INNER JOIN ACCOUNTS ON RECEIPTS.IDCUSTOMER = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 WHERE RECEIPTS.ifDelete = 0 
AND ((IFENIMEROSITAMEIO = 1 OR IF_ENIMEROSIKARTELA = 1) AND IF_AFORAEXTRITON != 1)
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
ACCOUNTS.ifDelete, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA, ACCOUNTS.IDYPOKATASTIMA  

