ACCOUNTS.IF_PROM, PAYMENTS.IDCOMPANY, PAYMENTS.IDYPOKATASTIMA, ACCOUNTS.ifDelete, ACCOUNTS.IDYPOKATASTIMA  
UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDOFPAYMENTS.IF_OUT)*(1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, PAYMENTS.IDCOMPANY, PAYMENTS.IDYPOKATASTIMA, 
ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC FROM PAYMENTS INNER JOIN KINDOFPAYMENTS ON PAYMENTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID AND KINDOFPAYMENTS.IF_CASH = 1 AND IF_OUT = 1
INNER JOIN ACCOUNTS ON PAYMENTS.IDCUSTOMER = ACCOUNTS.ID WHERE PAYMENTS.ifDelete = 0 
AND (PAYMENTS.IDKINDPARAST IN(SELECT ID FROM KINDPARASTATIKON WHERE IF_APOGR_PROM != 1 OR (IF_APOGR_PROM IS NULL) AND IF_ENIMEROSIKARTELA = 1))
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, 
ACCOUNTS.IF_PROM, PAYMENTS.IDCOMPANY, PAYMENTS.IDYPOKATASTIMA, ACCOUNTS.ifDelete, ACCOUNTS.IDYPOKATASTIMA  


UNION
SELECT ACCOUNTS.ID, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, ACCOUNTS.IF_PROM, 
SUM(SUMPOSO * KINDOFPAYMENTS.KINDOFCALCULATION)*(1) AS SUMPOSO, DATEPRINT, ACCOUNTS.ifDelete, PAYMENTS.IDCOMPANY, PAYMENTS.IDYPOKATASTIMA, 
ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC FROM PAYMENTS INNER JOIN KINDOFPAYMENTS ON PAYMENTS.IDKINDPAYMENT = KINDOFPAYMENTS.ID --AND KINDOFPAYMENTS.IF_CASH = 1 AND IF_OUT = 1
INNER JOIN ACCOUNTS ON PAYMENTS.IDCUSTOMER = ACCOUNTS.ID WHERE PAYMENTS.ifDelete = 0 
AND (PAYMENTS.IDKINDPARAST IN(SELECT ID FROM KINDPARASTATIKON WHERE IF_APOGR_PROM = 1 AND IF_ENIMEROSIKARTELA = 1))
GROUP BY ACCOUNTS.ID, DATEPRINT, ACCOUNTS.Code, ACCOUNTS.AFM, ACCOUNTS.EPONIMIA, ACCOUNTS.AddressCity, ACCOUNTS.Tel, ACCOUNTS.IF_PEL, 
ACCOUNTS.IF_PROM, PAYMENTS.IDCOMPANY, PAYMENTS.IDYPOKATASTIMA, ACCOUNTS.ifDelete , ACCOUNTS.IDYPOKATASTIMA 



GO



