ALTER VIEW [dbo].[PROFORTOTIKES_WITHDETAILS_VIEW]
AS
SELECT     dbo.PROFORTOTIKES.ID, dbo.PROFORTOTIKES.DATEPRINT, dbo.KINDPARASTATIKON.Code, dbo.PROFORTOTIKES.PARASTATIKO, dbo.PROFORTOTIKES.SEIRA, 
                      CAST(dbo.PROFORTOTIKES.NOPARAST AS int) AS NOPARAST, dbo.PROFORTOTIKES.NOPARASTDELTIOUDIANOMIS, 
                      dbo.PROFORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, dbo.PROFORTOTIKES.OXIMA, dbo.PROFORTOTIKES.OMADPROORISMOS, 
                      CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
                       ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
                      dbo.PROFORTOTIKES.APOSTOLEASDESCR, dbo.PROFORTOTIKES.PARALISPTISDESCR, dbo.PROFORTOTIKES.ENTOLEASDESCR, dbo.GRAMMESPROFORTTIKIS.ID AS IDGRAMMIS, 
                      dbo.PROFORTOTIKES.ANTAPOKRITISDESCR, dbo.PROFORTOTIKES.NOLISTASDIANOMIS, dbo.PROFORTOTIKES.TRITOSDESCR, dbo.GRAMMESPROFORTTIKIS.TIMDA, dbo.PROFORTOTIKES.POSO, 
                      dbo.PROFORTOTIKES.TAXIS, dbo.PROFORTOTIKES.SUMPOSO, dbo.GRAMMESPROFORTTIKIS.TEMAXIA, dbo.GRAMMESPROFORTTIKIS.PERIEXOMENO, 
                      dbo.GRAMMESPROFORTTIKIS.BAROS, dbo.GRAMMESPROFORTTIKIS.KYBIKA, dbo.GRAMMESPROFORTTIKIS.SUMPOSO AS AXIA, 
                      MIN(dbo.Units.UntName) AS SYSKEVASIA, CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END AS XREOSIPROPLIROMENES, 
                      CASE dbo.PROFORTOTIKES.IFOFEILOMENI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END AS XREOSIOFEILOMENES, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.PROFORTOTIKES.IFCASH WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.PROFORTOTIKES.IFPISTOSI WHEN 1 THEN
                          (SELECT     SUM(SUMPOSO) AS XREOSEIS
                            FROM          XREOSIS_ANAPRODELTIO_VIEW WITH (NOLOCK)
                            WHERE      IDVOH = dbo.PROFORTOTIKES.ID AND IF_TO_PROFORTOTIKI = 1) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESPISTOSI, 
                      dbo.PROFORTOTIKES.PERIOXIFORTOSIS, dbo.PROFORTOTIKES.PERIOXIPARADOSIS, 
                      dbo.PROFORTOTIKES.COMMENTS, dbo.PROFORTOTIKES.SUMANTIK, dbo.PROFORTOTIKES.PRAKTOREIODESCR, dbo.PROFORTOTIKES.STATUS, CONVERT(varchar, 
                      dbo.PROFORTOTIKES.DATEPARAD, 102) AS DATEPARAD, dbo.PROFORTOTIKES.IDAPOSTOLEA, dbo.PROFORTOTIKES.IDPARALIPTI, dbo.PROFORTOTIKES.IDENTOLEA, 
                      dbo.PROFORTOTIKES.IDANTAPOKRITI, dbo.PROFORTOTIKES.IDTRITOU, dbo.PROFORTOTIKES.IDPRAKTOREIO, 
                      CASE IFANTIKCASH WHEN 0 THEN 0 ELSE ANTIKCASH END AS ANTIKCASH, CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE ANTIKEPIT END AS ANTIKEPIT, 
                      CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE ANTIKSYNAL END AS ANTIKSYNAL, 
                      CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE ANTIKOTHER END AS ANTIKOTHER, 
                      CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, dbo.PROFORTOTIKES.COMMENTSANTIK, 
                      dbo.PROFORTOTIKES.DATEPARADOSI, dbo.PROFORTOTIKES.COMMENTS2, MIN(dbo.SUM_XREOSEIS_GRAMMES_PROFORTOTIKIS.KOMISTRA) AS KOMISTRA, 
                      dbo.PROFORTOTIKES.EXODATRITON AS XREOSISTRITON, MIN(dbo.SUM_XREOSEIS_GRAMMES_PROFORTOTIKIS.DIKAIOMAFORTOTIKIS) 
                      AS DIKAIOMAFORTOTIKIS, MIN(dbo.SUM_XREOSEIS_GRAMMES_PROFORTOTIKIS.OTHERXREOSIS) AS OTHERXREOSIS, 
                      MIN(dbo.SUM_XREOSEIS_GRAMMES_PROFORTOTIKIS.OLIKOSYNOLOXREOSEONPROFORT) AS OLIKOSYNOLOXREOSEONFORT, 
                      MIN(dbo.SUM_XREOSEIS_GRAMMES_PROFORTOTIKIS.ERGATIKA) AS ERGATIKA, KINDPARASTATIKON.IF_PRODROMOL, 
                      CASE dbo.PROFORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
                      CASE dbo.PROFORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, dbo.PROFORTOTIKES.KINDPAYMENTDESCR, 
                      dbo.PROFORTOTIKES.IDKINDPAYMENT, CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
                      CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, 
                      dbo.PROFORTOTIKES.IFANTIKCASH, dbo.PROFORTOTIKES.IFANTIKEPIT, dbo.PROFORTOTIKES.IFANTIKSYNAL, dbo.PROFORTOTIKES.IFANTIKOTHER, 
                      dbo.PROFORTOTIKES.ifDelete, dbo.PROFORTOTIKES.IFCANCEL, CONVERT(varchar, dbo.PROFORTOTIKES.DATECANCEL, 102) AS DATECANCEL, PROFORTOTIKES.AA_ANTIK, 
                      dbo.PROFORTOTIKES.IFPARADOSI, dbo.PROFORTOTIKES.AITIOLOGIAPARASTATIKOU, CONVERT(varchar, dbo.PROFORTOTIKES.DATEFORTOSIS, 102) 
                      AS DATEFORTOSIS, dbo.PROFORTOTIKES.IFEPISTROFI, CONVERT(varchar, dbo.PROFORTOTIKES.DATEEPISTROFIS, 102) AS DATEEPISTROFIS, 
                      dbo.PROFORTOTIKES.AITIOLOGIAEPISTROFIS, dbo.PROFORTOTIKES.COMMENTSEPISTROFIS, dbo.PROFORTOTIKES.IFCASH, dbo.PROFORTOTIKES.IFPISTOSI, 
                      dbo.PROFORTOTIKES.STATUSDESCR, dbo.PROFORTOTIKES.YPAITIOS, dbo.PROFORTOTIKES.IFEPANADROMOLOGISI, dbo.PROFORTOTIKES.IFEPANEKDOSI, 
                      dbo.PROFORTOTIKES.IFOKEPANADROMOLOGISI, dbo.PROFORTOTIKES.NOPARASTANTIK, dbo.PROFORTOTIKES.COMMENTSAKIROSIS, 
