                      dbo.PROFORTOTIKES.DATEPARADANTIK, 102) AS DATEPARADANTIK, CONVERT(varchar, dbo.PROFORTOTIKES.DATEPARALANTIK, 102) AS DATEPARALANTIK, 
                      CONVERT(varchar, dbo.PROFORTOTIKES.DATEEISPRANTIK, 102) AS DATEEISPRANTIK, dbo.PROFORTOTIKES.EISPRAXASANTIK, 
                      dbo.PROFORTOTIKES.NOPARPARADANTIK, dbo.PROFORTOTIKES.NOPARASTEISPRANTIK, dbo.PROFORTOTIKES.NOPARPARALANTIK, 
