CREATE PROCEDURE ADD_BARCODE_PROFORTOTIKIS
	@PROFORTID INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	BEGIN
		UPDATE p
		SET EXT_BARCODE = c.BARCODE_Prefix + '0' + CONVERT(VARCHAR, p.ID)
		FROM PROFORTOTIKES p
		JOIN COMPANIES c ON c.ID = p.IDYPOKATASTIMA
		WHERE p.ID = @PROFORTID
	END

END
GO


