				@DateCreate,
				@UserCreate

				)

SET @TheID = (SELECT SCOPE_IDENTITY()) --(SELECT MAX(ID) AS ID FROM dbo.FORTOTIKES WITH (NOLOCK))
IF(@EXT_BARCODE IS NULL OR @EXT_BARCODE ='')
BEGIN
	SET Context_Info 0x55555 

	DECLARE @PREFIX NVARCHAR(6)
	SELECT @PREFIX = BARCODE_Prefix FROM COMPANIES WHERE COMPANIES.id = @IDYPOKATASTIMA
	SELECT @EXT_BARCODE = RTRIM(@PREFIX) + RTRIM(CAST(@TheID AS NVARCHAR(18)))
	UPDATE FORTOTIKES SET EXT_BARCODE = @EXT_BARCODE WHERE ID = @TheID
END
SELECT @TheID [ID]
waitfor delay '00:00:00:40'            
commit;



go

