           ,AnamEsodo AS OLIKOSYNOLOXREOSEONPROFORT ,0 AS BAROSPROFORT ,0 AS KYBIKAPROFORT ,0 AS POSOPROFORT ,1 AS TEMAXIAPROFORT 
           FROM ProgrammatismosExtraErgasion AS PR WHERE ID = @IDPROFORT
           
				
INSERT INTO GRAMMESFORTTIKIS (TIMDA, IDVOH, TEMAXIA, PERIEXOMENO, SYSKEVASIA, SYSKEVASIADESCR, BAROS, KYBIKA, 
SUMPOSO, XreosiAnaMonada, XeosiSeMonada, XreosiGrammis, IF_KOMISTRO, IF_KATHARO, IF_MIKTO, IF_STANDAR)
SELECT '' AS TIMDA, @IDFORT AS IDVOH, 1, DescrEidousErgasias, 21, 'ΔΕΜΑΤΑ', NULL, NULL,
				NULL, NULL, 'Συσκευασία', NULL, 0, 0, 0, 1 FROM EXTRA_ERGASIES WHERE ID = @IDPROFORT 
           
SELECT  @TheID = @IDFORT --MAX(ID) FROM dbo.FORTOTIKES WITH (NOLOCK)

DECLARE @EXT_BARCODE NVARCHAR(60) 
DECLARE @IDYPOKATASTIMA NUMERIC(18, 00) 

SELECT @IDYPOKATASTIMA = IDYPOKATASTIMA FROM FORTOTIKES WHERE ID = @TheID
IF (@EXT_BARCODE IS NULL) OR LEN(@EXT_BARCODE)<1
BEGIN
	DECLARE @PREFIX NVARCHAR(6)
	SELECT @PREFIX = BARCODE_Prefix FROM COMPANIES WHERE ID = @IDYPOKATASTIMA
	SELECT @EXT_BARCODE = RTRIM(@PREFIX) + RTRIM(CAST(@TheID AS NVARCHAR(18)))
	UPDATE FORTOTIKES SET EXT_BARCODE = @EXT_BARCODE WHERE ID = @TheID
END

waitfor delay '00:00:00:40'            
commit;

go



