				ANTAPOKRITISDESCR,
				IDXREOUMENOU,
				@DATEPRINT AS DATEPRINT,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				IFANTIKCASH,
				IFANTIKEPIT,
				IFANTIKSYNAL,
				IFANTIKOTHER,
				ANTIKCASH,
				ANTIKEPIT,
				ANTIKSYNAL,
				ANTIKOTHER,
				SUMANTIK,
				EXODATRITON,
				IFCANCELANTIK,
				DATECANCELANTIK,
				COMMENTSANTIK,
				IFPARADOSI,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				PERIOXIFORTOSIS,
				PERIOXIPARADOSIS,
				OMADPROORISMOS,
				OXIMA,
				IDKINDPAYMENT,
				KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI,
				DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS,
				COMMENTS,
				COMMENTS2,
				IFCASH,
				IFPISTOSI,
				IFPREPAY,
				IFOFEILOMENI,
				IDPRAKTOREIO,
				PRAKTOREIODESCR,
				YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI,
				IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI,
				NOPARASTANTIK,
				COMMENTSAKIROSIS,
				@STATUSDESC,
				IDDRIVER,
				DRIVERDESCR,
				IFEXOFLISI,
				@STATUS,
				DATEPARAL,
				DATEPARAD,
				COMMENTSPARAD,
				COMMANTSPARAL,
				TIMEPARALFROM,
				TIMEPARALTO,
				TIMEPARADFROM,
				TIMEPARADTO,
				ANAMEXODO,
				AFMAPOSTOLEA,
				AFMENTOLEA,
				AFMPARALIPTI,
				AFMTRITOU,
				AFMANTAPOKRITI,
				AFMXREOUMENOU,
				IFPARADOSITOPEL,
				IFPARALABIFROMPEL,
				NOLISTASDIANOMIS,
				AA_ANTIK,
				CONTAINER,
				BOAT,
				OROFOS,
				OROFOSDESCR,
				KOUDOUNI,
				NO_EXT_ORDER,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				DateCreate,
				UserCreate FROM PROFORTOTIKES --INNER JOIN (SELECT ID AS IDA , AddressCity FROM ACCOUNTS) A 
				--ON A.IDA = PROFORTOTIKES.IDAPOSTOLEA INNER JOIN (SELECT ID AS IDB, AddressCity FROM ACCOUNTS) B 
				--ON B.IDB = PROFORTOTIKES.IDPARALIPTI
				 WHERE ID = @IDPROFORT 
SELECT @IDFORT = MAX(ID) FROM dbo.FORTOTIKES WITH (NOLOCK)
SELECT @KATHARO = POSO, @TAXIS = TAXIS, @SUMPOSO = SUMPOSO FROM dbo.FORTOTIKES WHERE ID = @IDFORT

INSERT INTO HEADERFORTOTIKIS
           (IDFORT ,PARASTATIKOFORT ,SEIRAFORT ,NOPARASTFORT ,ENTOLEASDESCR ,PARALISPTISDESCR
           ,APOSTOLEASDESCR ,KOMISTRA ,DIKAIOMAFORTOTIKIS ,OTHERXREOSIS ,SYSKEVASIA
           ,ASFALISTRA ,KATHARO ,TAXIS ,SUMPOSOXRFORT ,ERGATIKA ,XREOSISTRITON
           ,OLIKOSYNOLOXREOSEONFORT ,BAROSFORT ,KYBIKAFORT ,POSOFORT ,TEMAXIAFORT)
SELECT 
			@IDFORT AS IDFORT,@PARASTATIKO AS  PARASTATIKOFORT, @SEIRA AS SEIRA,
			@NOPARAST AS NOPARAST, ENTOLEASDESCR ,PARALISPTISDESCR
           ,APOSTOLEASDESCR ,KOMISTRA ,DIKAIOMAFORTOTIKIS ,OTHERXREOSIS ,SYSKEVASIA
           ,ASFALISTRA ,KATHARO ,TAXIS ,SUMPOSOXRPROFORT ,ERGATIKA ,XREOSISTRITON
           ,OLIKOSYNOLOXREOSEONPROFORT ,BAROSPROFORT ,KYBIKAPROFORT ,POSOPROFORT ,TEMAXIAPROFORT 
           FROM HEADERPROFORTOTIKIS WHERE IDPROFORT = @IDPROFORT
INSERT INTO XREOSISANADELTIO
           (IDVOH, IDXREOSIS, CODEXREOSIS, DESCR, TAXISPERCENT, POSO, TAXIS, SUMPOSO, 
           IF_TO_FORTOTIKI, IF_TO_VOH)         
SELECT   @IDFORT AS IDVOH, XR.ID, XR.CODE, XR.Descr, XR.TAXISPERCENT, @KATHARO AS POSO, 
			@TAXIS AS TAXIS, @SUMPOSO AS SUMPOSO, 1 AS IF_TO_FORTOTIKI, 0 AS IF_TO_VOH
FROM Xreoseis XR INNER JOIN 
			XREOSISANAPARASTATIKO XAP ON XR.ID = XAP.IDXREOSIS WHERE XR.ifKomistra = 1  
			AND XAP.IDKINDPARASTTIKON = @IDPARAST AND XR.ifDelete = 0
SELECT  @TheID = @IDFORT --MAX(ID) FROM dbo.FORTOTIKES WITH (NOLOCK)


DECLARE @EXT_BARCODE NVARCHAR(60) 
DECLARE @IDYPOKATASTIMA NUMERIC(18, 00) 
SELECT @EXT_BARCODE = EXT_BARCODE FROM PROFORTOTIKES WHERE ID = @IDPROFORT
IF (@EXT_BARCODE IS NULL) OR LEN(@EXT_BARCODE)<1
BEGIN
	DECLARE @PREFIX NVARCHAR(6)
	SELECT @IDYPOKATASTIMA = IDYPOKATASTIMA FROM PROFORTOTIKES WHERE ID = @IDPROFORT
	SELECT @PREFIX = BARCODE_Prefix FROM COMPANIES WHERE ID = @IDYPOKATASTIMA
	SELECT @EXT_BARCODE = RTRIM(@PREFIX) + RTRIM(CAST(@TheID AS NVARCHAR(18)))
END
UPDATE FORTOTIKES SET EXT_BARCODE = @EXT_BARCODE WHERE ID = @TheID



waitfor delay '00:00:00:40'            
commit;

go

---END SCRIPT 1917
