create TRIGGER [dbo].[ASFALISTRA]	
   ON  [dbo].[ACCOUNTS]
   AFTER INSERT
AS 
BEGIN

UPDATE ACCOUNTS SET IF_ASFALISTRA=1,ASFALISTRA=30

FROM ACCOUNTS A 
JOIN INSERTED I ON I.ID=A.ID


END

go

DISABLE TRIGGER ASFALISTRA ON ACCOUNTS

GO


