ALTER VIEW [dbo].[VOH_VIEW]
AS

WITH GRAMMES AS 
	(
		SELECT 
			IDVOH,
			ISNULL(Min(dbo.grammesvoh.timda),'')                 AS TIMDA,
            Isnull(Sum(dbo.grammesvoh.temaxia), 0)               AS TEMAXIA,
            Isnull(Sum(dbo.grammesvoh.baros), 0)                 AS BAROS,
            Isnull(Sum(dbo.grammesvoh.kybika), 0)                AS KYBIKA,
            ISNULL(MIN(PERIEXOMENO),'')							 AS PERIEXOMENO,
            ISNULL(SUM(SUMPOSO),0)								 AS AXIA
		
		FROM GRAMMESVOH
		GROUP BY IDVOH
	),
XREOSIS AS	(
		SELECT 
			IDVOH,
			SUM(SUMPOSO) AS SUPOSO
			
		FROM XREOSISANADELTIO
		WHERE IF_TO_VOH=1
			
		GROUP BY IDVOH
		)

SELECT

	V.ID,
	V.DATEPRINT,
	KP.Code,
	V.PARASTATIKO,
	V.SEIRA,
	CAST(V.NOPARAST AS NVARCHAR(15)) [NOPARAST],
	V.CustDescr,
	V.EPAGELMA,
	V.AFM,
	V.CITY,
	V.TEL,
	V.MOBILE,
	V.POSO,
	V.TAXIS,
	V.SUMPOSO,
	V.KINDPAYMENTDESCR,
	V.EXT_BARCODE,
	V.OXIMA,
	V.OMADPROORISMOS,
	V.SXETIKAPARASTATIKA,
	CASE ifxrentol * 1 + ifxrapost * 2 + ifxrtritou * 4 + ifxrparal * 8
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		ELSE 'ΑΓΝΩΣΤΟ'
	END AS XREOYMENOS,
	  V.noparastdeltioudianomis,
      V.noparastdeltiouapostolis,
      GRAMMES.TIMDA,
      GRAMMES.TEMAXIA,
      GRAMMES.BAROS,
      GRAMMES.KYBIKA,
      CASE V.IFPREPAY
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIPROPLIROMENES,
	  CASE V.IFOFEILOMENI
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIOFEILOMENES,
	  GRAMMES.PERIEXOMENO,
	  V.perioxifortosis,
      V.perioxiparadosis,
      V.comments,
      V.sumantik,
      V.praktoreiodescr,
      V.status,
      V.dateparad,
      V.idpraktoreio,
      CASE ifantikcash
        WHEN 0 THEN 0
        ELSE antikcash
      END AS ANTIKCASH,
      CASE ifantikepit
        WHEN 0 THEN 0
        ELSE antikepit
      END AS ANTIKEPIT,
      CASE ifantiksynal
        WHEN 0 THEN 0
        ELSE antiksynal
      END AS ANTIKSYNAL,
      CASE ifantikother
        WHEN 0 THEN 0
        ELSE antikother
      END AS ANTIKOTHER,
      CASE ifcancelantik
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFCANCELANTIK,
      V.commentsantik,
      V.dateparadosi,
      V.comments2,
      hv.KOMISTRA,
      hv.XREOSISTRITON,
      hv.DIKAIOMAFORTOTIKIS,
      hv.OTHERXREOSIS,
      CASE V.ifprepay
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFPREPAY,
