ALTER VIEW [dbo].[AADE_INVOICES] AS
SELECT
	FORT.ID INVOICEID,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	
	FORT.DATEPRINT,
	FORT.IDXREOUMENOU COUNTERPART_ID,
	FORT.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(FORT.TAXIS) INVOICE_TAX_SUM,
	ABS(FORT.POSO) INVOICE_NET_SUM,
	ABS(FORT.SUMPOSO) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
	NULL [OXIMA] ,
	NULL [SKOPOSDIAKINISIS],
	NULL [DISPATCHED_DATE],
	NULL [DISPATCHED_TIME],
	FORT.IDYPOKATASTIMA,
	FORT.IF_ENIM_AADE,
	0 [IF_VOH_SALES]
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
JOIN ACCOUNTS CUST ON CUST.ID = FORT.IDXREOUMENOU
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(FORT.ifDelete,0)!=1
UNION
SELECT
	VOH.ID INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	VOH.DATEPRINT,
	VOH.IDCUSTOMER COUNTERPART_ID,
	VOH.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(VOH.TAXIS+VOH.TAXISEPIVAR) INVOICE_TAX_SUM,
	ABS(VOH.POSO+VOH.POSOEPIVAR) INVOICE_NET_SUM,
	ABS(VOH.SUMPOSO+VOH.SUMPOSOEPIVAR) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE,
	PAYMENTS.AADE_CODE,
	CASE KP.KINDKINISIS
		WHEN 5 THEN VOH.OXIMA
		ELSE NULL
	END [OXIMA] ,
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN SKD.AADE_CODE
		ELSE NULL
	END [SKOPOSDIAKINISIS],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,23) 
		ELSE NULL
	END [DISPATCHED_DATE],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,8)
		ELSE NULL
	END  [DISPATCHED_TIME],

	VOH.IDYPOKATASTIMA,
	VOH.IF_ENIM_AADE,
	CASE KP.KindKINISIS
		WHEN 5 THEN 1 
		ELSE 0
	END [IF_VOH_SALES]
FROM VOH 
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
JOIN COMPANIES YPOKAT ON YPOKAT.id = VOH.IDYPOKATASTIMA
LEFT JOIN SKOPOSDIAKINISIS SKD ON SKD.DESCR=VOH.SKOPOSDIAKINISIS
JOIN ACCOUNTS CUST ON CUST.ID = VOH.IDCUSTOMER
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(VOH.ifDelete,0)!=1




GO




---END SCRIPT 1927
