ALTER TRIGGER [dbo].[AADE_URL_1] 
   ON  [dbo].[VOH]
   AFTER INSERT
AS 
BEGIN
	UPDATE v SET QRURL='Απώλεια Διασύνδεσης'
	
	FROM VOH V
	JOIN KINDPARASTATIKON KP ON KP.ID=v.IDPARAST
	join inserted ins on ins.id=v.id
	--join updated upd on upd.id=f.id
	WHERE ISNULL(KP.IF_ENIMEROSI_AADE,0)=1
		AND ISNULL(V.QRURL,'')=''
END
go


ALTER TRIGGER [dbo].[AADE_URL] 
   ON  [dbo].[FORTOTIKES]
   AFTER INSERT
AS 
BEGIN
	UPDATE F SET QRURL='Απώλεια Διασύνδεσης'
	
	FROM FORTOTIKES F
	JOIN KINDPARASTATIKON KP ON KP.ID=F.IDPARAST
	join inserted ins on ins.id=f.id
	--join updated upd on upd.id=f.id
	WHERE ISNULL(KP.IF_ENIMEROSI_AADE,0)=1
		AND ISNULL(F.QRURL,'')=''
END

go

