ALTER VIEW [dbo].[TIMOL_VOH_VIEW]
AS

with grammesvohsum as (
	select 
		idvoh, 
		sum(timitem) timitem, 
		sum(PCS) temaxia, 
		isnull(SUM(TEMAXIA),0) countid,
		isnull(sum(BAROS),0) baros,
		isnull(sum(KYBIKA),0) kybika,
		isnull(SUM(SUMPOSO),0) AXIA,
		MIN(TIMDA) TIMDA,
		MIN(PERIEXOMENO) PERIEXOMENO
	from grammesvoh group by idvoh
),
grammesfortotikissum as(
		select
			IDVOH,
			ISNULL(SUM(TEMAXIA),0) as temaxia,
			isnull(sum(BAROS),0) as baros,
			ISNULL(SUM(KYBIKA),0) as kybika,
			ISNULL(SUM(SUMPOSO),0) AS AXIA,
			MIN(TIMDA) as timda,
			MIN(PERIEXOMENO) as periexomeno,
			MIN(u.UntName) as untname
		
		from GRAMMESFORTTIKIS gf
		left join Units u on u.UntID=gf.SYSKEVASIA
		group by idvoh
		
),
xreosisanadeltiosum as (
		select
			IDVOH,
			SUM(SUMPOSO) as sumposo
		
		from XREOSISANADELTIO
		where IF_TO_FORTOTIKI=1
		group by IDVOH
),
headerfortotikissum as (
		select
			idfort,
			SUM(komistra) as komistra,
			SUM(dikaiomafortotikis) as dikaiomafortotikis,
			SUM(otherxreosis) as otherxreosis,
			SUM(olikosynoloxreoseonfort) as olikosynoloxreoseonfort,
			SUM(ergatika) as ergatika
			
		from HEADERFORTOTIKIS
		group by IDFORT
),
grammes_assembly as (
			select
				IDVOH,
				SUM(iftransport) iftransport,
				SUM(ifassembly) ifassembly,
				SUM(ifplacement) ifplacement,
				SUM(ifdisassembly) ifdisassembly
			
			from GRAMMESVOH
			group by IDVOH
)

select
	v.ID,
	v.DATEPRINT,
	kp.Code,
	v.PARASTATIKO,
	v.SEIRA,
	CONVERT(int,v.NOPARAST)										as NOPARAST,
	v.NOPARASTDELTIOUDIANOMIS,
	v.NOPARASTDELTIOUAPOSTOLIS,
	v.OXIMA,
	v.OMADPROORISMOS,
	CASE 
		ISNULL(0, v.IFXRENTOL) * 1
		+ ISNULL(0, v.IFXRAPOST) * 2
		+ ISNULL(0, v.IFXRPARAL) * 4
		+ ISNULL(0, v.IFXRTRITOU) * 8

		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		WHEN 8 THEN 'ΤΡΙΤΟΣ'
		ELSE 'ΑΓΝΩΣΤΟΣ'
	END															AS XREOYMENOS,
	 v.apostoleasdescr,
	 v.paralisptisdescr,
	 v.entoleasdescr,
	 v.antapokritisdescr,
	 v.tritosdescr,
	 gf.TIMDA													as TIMDA,
	 v.poso,
     v.taxis,
     v.sumposo,
     gf.temaxia													as TEMAXIA,
     gf.baros													as BAROS,
     gf.kybika													as KYBIKA,
     gf.untname													as SYSKEVASIA,
     case 
		ISNULL(v.ifprepay,0)		
		when 1 then xd.sumposo 
	 else 0
	 end														as XREOSIPROPLIROMENES,
	case 
		ISNULL(v.IFOFEILOMENI,0)		
		when 1 then xd.sumposo 
	 else 0
	 end														as XREOSIOFEILOMENES,
	 case
		ISNULL(V.ifprepay,0)
		when 1 then 
			case V.ifcash 
				when 1 then xd.sumposo
				else 0
			end 
		else 0
	end															as XREOSIPROPLIROMENESCASH,
		 case
		ISNULL(V.ifprepay,0)
