	@IfMisthodosia			int = 0,
	@IF_TO_FORTOTIKI		int = 0,
	@IF_TO_VOH				int = 0,
	@IF_APOGRAFI			int = 0,
	@IDXRHSHS				NUMERIC(18,0) = 0,
	@IDCOMPANY				NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA			NUMERIC(18,0) = 0,
	@DateCreate				DATETIME,-- = NULL,
	@UserCreate				NVARCHAR(50),
	@TheID					NUMERIC(18, 0)= NULL output
	--@TheKeySeries			varchar(10) output

	)
AS
SET NOCOUNT ON;
DECLARE @NEWNOPARAST NUMERIC(18, 0)=0;
DECLARE @IF_ZERO_ON_NEW_YEAR int=(SELECT IF_ZERO_ON_NEW_YEAR FROM KINDPARASTATIKON WHERE ID=@IDKINDPARAST)
DECLARE @IF_AUTONUMBER INT

select @IF_AUTONUMBER = IF_AUTONUMBER FROM KINDPARASTATIKON WHERE ID = @IDKINDPARAST

IF (LEN(@DOCNO)<1 OR CONVERT(NUMERIC(18,0),@DOCNO )<1)

IF @IF_AUTONUMBER = 1 BEGIN 
	IF @IF_ZERO_ON_NEW_YEAR = 1 BEGIN
		SELECT @DOCNO=ISNULL(MAX(CAST(DOCNO as INT)), 0) + 1 
		FROM PAYMENTS
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDKINDPARAST = @IDKINDPARAST 
		AND ifDelete != 1
		AND YEAR(DATEPRINT) = YEAR(@DATEPRINT)
	END
	ELSE BEGIN	
		SELECT @DOCNO=ISNULL(MAX(CAST(DOCNO as INT)), 0) + 1 
		FROM PAYMENTS 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDKINDPARAST = @IDKINDPARAST 
		AND ifDelete != 1
	END
	
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@DOCNO + 1) WHERE ID = @IDKINDPARAST;
END



	INSERT INTO PAYMENTS
	(                                      
