	AITIOLOGIA,                                                                                           
	EISPRAXAS,                                                                                            
	IDKINDPAYMENT,                           
	KINDPAYMENTDESCR,                                   
	IDVOH,      
	AFMCUSTOMER,                            
	IDCUSTOMER,                              
	CUSTOMERDESCR,                                      
	SUMPOSO,                                 
	DATEPRINT,
	IfMisthodosia,
	IF_TO_FORTOTIKI,
	IF_TO_VOH,
	IF_APOGRAFI,
	IDXRHSHS,
	IDCOMPANY,
	IDYPOKATASTIMA,
	DateCreate,
	UserCreate
	)
	VALUES
	(
	@SEIRA, 
	@DOCNO,         
	@IDKINDPARAST,                            
	@KINDPARASTDESCR,   
	@IDAFORA,
	@AFORA,                                                                                   
	@AITIOLOGIA,                                                                                           
	@EISPRAXAS,                                                                                            
	@IDKINDPAYMENT,                           
	@KINDPAYMENTDESCR,                                   
	@IDVOH,      
	@AFMCUSTOMER,                            
	@IDCUSTOMER,                              
	@CUSTOMERDESCR,                                      
	@SUMPOSO,                                 
	@DATEPRINT,
	@IfMisthodosia,
	@IF_TO_FORTOTIKI,
	@IF_TO_VOH,
	@IF_APOGRAFI,
	@IDXRHSHS,
	@IDCOMPANY,
	@IDYPOKATASTIMA,
	@DateCreate,
	@UserCreate
	)

--SELECT  @TheID = MAX(ID) FROM dbo.PAYMENTS WITH (NOLOCK)
SELECT @TheID = SCOPE_IDENTITY();



GO

