select 
	a.Code [Κωδικός Συναλλασόμενου],
	a.Eponimia [Επωνυμία],
	a.AFM [ΑΦΜ],
	isnull(i.IRSID,0) [Κωδικός ΔΟΥ],
	a.CATKEPYO [Κεπυο],
	case a.CATKEPYO
		when 0 then 1
		when 1 then 2
		when 2 then 1
		when 3 then 1
		when 4 then 2
		else 0
	end as [Υπόχρεος],		
	a.AddressStr + ' ' + AddressNo [Διεύθυνση],
	a.AddressCity [Πόλη]
from ACCOUNTS a
left join IRS i on isnull(i.Description,0)=isnull(a.DOY,0)

GO


---END SCRIPT 1939
