ALTER view [dbo].[LOGISTIKI_CUSTOMERS_EPSILONNET_C_CATEGORY]
as
select 
	A.id,
	a.Code [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟ],
	a.Eponimia [ΕΠΩΝΥΜΙΑ],
	a.AFM [ΑΦΜ],
	i.IRSID [ΚΩΔΙΚΟΣ ΔΟY],
	a.CATKEPYO [ΚΕΠΥΟ],
	case	
		when A.catkepyo in (2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΟΣ],
	A.addresscountry [ΧΩΡΑ],
	a.AddressStr [ΔΙΕΥΘΥΝΣΗ],
	a.AddressCity [ΠΟΛΗ],
	A.AddressTK [T.K.],
	A.tel [ΤΗΛΕΦΩΝΟ],
	A.Fax [FAX],
	a.IF_PEL,
	a.IF_ANTAPOKRITIS,
	a.IF_PROM,
	a.IF_ERG
from ACCOUNTS a
left join IRS i on i.Description=a.DOY
where a.ifDelete=0

GO

