    @TIMEPARALTO				NVARCHAR(5) = NULL,
    @TIMEPARADFROM				NVARCHAR(5) = NULL,
    @TIMEPARADTO				NVARCHAR(5) = NULL,
	@ANAMEXODO					NUMERIC(18,2)=0,
	@AFMAPOSTOLEA				NVARCHAR (20) =NULL,
	@AFMENTOLEA					NVARCHAR (20) =NULL,
	@AFMPARALIPTI				NVARCHAR (20) =NULL,
	@AFMTRITOU					NVARCHAR (20) =NULL,
	@NOLISTASDIANOMIS			NVARCHAR (10) =NULL,
	@ARANAFORAS					NVARCHAR(20) = NULL,
	@IFAUTONUMBER				int =0,
	@IFPARADOSITOPEL			int =0,
	@IFPARALABIFROMPEL			int =0,
	@AFMANTAPOKRITI				NVARCHAR (20) =NULL,
	@IDXRHSHS					NUMERIC(18,0) = 0,
	@IDCOMPANY					NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = 0,
	@DateCreate					DATETIME,-- = NULL,
	@UserCreate					NVARCHAR(50),
	@CONTAINER					NVARCHAR (50) =NULL,
	@BOAT						NVARCHAR (50) =NULL,
	@IFASFALISTRA				int =0,
	@ASFALISTRAPERCENT			NUMERIC(18,0) = 0,
	@POD_PATH_2					NVARCHAR (MAX) =NULL,
	@NO_EXT_ORDER				NVARCHAR(50) = NULL,
	@DROMOLOGIO					NVARCHAR (50) =NULL,
	@THESI						NVARCHAR(50) = NULL,
	@OROFOS						NUMERIC(5,2) = 0.00,
	@OROFOSDESCR				NVARCHAR(100) =NULL,
	@KOUDOUNI					NVARCHAR(100) =NULL,
	@FILE_PHOTO					NVARCHAR(MAX)= NULL,
	@EXT_BARCODE				NVARCHAR (150) =NULL,
	@IF_ZERO_ON_NEW_YEAR		INT = 0,
	@IfParadsePrakt				INT = 0,
	@DateParadsePrakt			SMALLDATETIME = NULL,
	@CommentsParadsePrakt		NVARCHAR(MAX) = NULL,
	@TheID						NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoFORTOTIKES', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000

--SELECT @@SPID [session_id], @RC [return code], GETDATE()

set @IFAUTONUMBER = (select isnull(if_autonumber,0) from KINDPARASTATIKON where ID=@IDPARAST)

IF @IFAUTONUMBER = 1 BEGIN 
	IF @IF_ZERO_ON_NEW_YEAR = 1 BEGIN
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM FORTOTIKES 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
		AND YEAR(DATEPRINT) = YEAR(@DATEPRINT)
	END
	ELSE BEGIN	
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM FORTOTIKES 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
	END
	
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END


	


	
	--GO
			INSERT INTO FORTOTIKES
				(
				SEIRA,
				NOPARAST,
				IDPARAST,
				PARASTATIKO,
				IFXRAPOST,
				IFXRPARAL,
				IFXRENTOL,
				IFXRTRITOU,
				IDAPOSTOLEA,
				APOSTOLEASDESCR,
				IDPARALIPTI,
