				IDTRITOU,
				TRITOSDESCR,
				IDANTAPOKRITI,
				ANTAPOKRITISDESCR,
				IDXREOUMENOU,
				DATEPRINT,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				IFANTIKCASH,
				IFANTIKEPIT,
				IFANTIKSYNAL,
				IFANTIKOTHER,
				ANTIKCASH,
				ANTIKEPIT,
