				OMADPROORISMOS,
				OXIMA,
				IDKINDPAYMENT,
				KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI,
				DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS,
				COMMENTS,
				COMMENTS2,
				IFCASH,
				IFPISTOSI,
				IFPREPAY,
				IFOFEILOMENI,
				IDPRAKTOREIO,
				PRAKTOREIODESCR,
				YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI,
				IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI,
				NOPARASTANTIK,
				COMMENTSAKIROSIS,
				STATUSDESCR,
				IDDRIVER,
				DRIVERDESCR,
				IFEXOFLISI,
				STATUS,
				DATEPARAL,
				DATEPARAD,
				COMMENTSPARAD,
				COMMANTSPARAL,
				TIMEPARALFROM,
				TIMEPARALTO,
				TIMEPARADFROM,
				TIMEPARADTO,
				ANAMEXODO,
				AFMAPOSTOLEA,
				AFMENTOLEA,
				AFMPARALIPTI,
				AFMTRITOU,
				AFMANTAPOKRITI,
				AFMXREOUMENOU,
				IFPARADOSITOPEL,
				IFPARALABIFROMPEL,
				NOLISTASDIANOMIS,
				AA_ANTIK,
				CONTAINER,
				BOAT,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IFASFALISTRA,
				ASFALISTRAPERCENT,
				POD_PATH_2,
				NO_EXT_ORDER,
				DROMOLOGIO,
				THESI,
				OROFOS,
				EXT_BARCODE,
				OROFOSDESCR,				
				KOUDOUNI,
				ARANAFORAS,
				FILE_PHOTO,
				IfParadsePrakt,
				DateParadsePrakt,
				CommentsParadsePrakt,
				DateCreate,
				UserCreate
				)
			VALUES
				(
				@SEIRA,
				@NOPARAST,
				@IDPARAST,
				@PARASTATIKO,
				@IFXRAPOST,
				@IFXRPARAL,
				@IFXRENTOL,
				@IFXRTRITOU,
				@IDAPOSTOLEA,
				@APOSTOLEASDESCR,
				@IDPARALIPTI,
				@PARALISPTISDESCR,
				@IDENTOLEA,
				@ENTOLEASDESCR,
				@IDTRITOU,
				@TRITOSDESCR,
				@IDANTAPOKRITI,
				@ANTAPOKRITISDESCR,
				@IDXREOUMENOU,
				@DATEPRINT,
				@POSO,
				@TAXISPERCENT,
				@TAXIS,
				@SUMPOSO,
				@IFANTIKCASH,
				@IFANTIKEPIT,
				@IFANTIKSYNAL,
				@IFANTIKOTHER,
				@ANTIKCASH,
				@ANTIKEPIT,
				@ANTIKSYNAL,
				@ANTIKOTHER,
				@SUMANTIK,
				@EXODATRITON,
				@IFCANCELANTIK,
				@DATECANCELANTIK,
				@COMMENTSANTIK,
				@IFPARADOSI,
				@DATEPARADOSI,
				@IFCANCEL,
				@DATECANCEL,
				@PERIOXIFORTOSIS,
				@PERIOXIPARADOSIS,
				@OMADPROORISMOS,
				@OXIMA,
				@IDKINDPAYMENT,
				@KINDPAYMENTDESCR,
				@AITIOLOGIAPARASTATIKOU,
				@DATEFORTOSIS,
				@NOPARASTDELTIOUAPOSTOLIS,
				@NOPARASTDELTIOUDIANOMIS,
				@IFEPISTROFI,
				@DATEEPISTROFIS,
				@AITIOLOGIAEPISTROFIS,	
				@COMMENTSEPISTROFIS,
				@COMMENTS,
				@COMMENTS2,
				@IFCASH,
				@IFPISTOSI,
				@IFPREPAY,
				@IFOFEILOMENI,
				@IDPRAKTOREIO,
				@PRAKTOREIODESCR,
				@YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				@IFEPANADROMOLOGISI,
				@IFEPANEKDOSI,
				@IFOKEPANADROMOLOGISI,
				@NOPARASTANTIK,
				@COMMENTSAKIROSIS,
				@STATUSDESCR,
				@IDDRIVER,
				@DRIVERDESCR,
				@IFEXOFLISI,
				@STATUS,
				@DATEPARAL,
				@DATEPARAD,
				@COMMENTSPARAD,
				@COMMANTSPARAL,
				@TIMEPARALFROM,
				@TIMEPARALTO,
				@TIMEPARADFROM,
				@TIMEPARADTO,
				@ANAMEXODO,
				@AFMAPOSTOLEA,
				@AFMENTOLEA,
				@AFMPARALIPTI,
				@AFMTRITOU,
				@AFMANTAPOKRITI,
				@AFMXREOUMENOU,
				@IFPARADOSITOPEL,
				@IFPARALABIFROMPEL,
				@NOLISTASDIANOMIS,
				@AA_ANTIK,
				@CONTAINER,
				@BOAT,
				@IDXRHSHS,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IFASFALISTRA,
				@ASFALISTRAPERCENT,
				@POD_PATH_2,
				@NO_EXT_ORDER,
				@DROMOLOGIO,
				@THESI,
				@OROFOS,
				@EXT_BARCODE,
				@OROFOSDESCR,
				@KOUDOUNI,
				@ARANAFORAS,
				@FILE_PHOTO,
				@IfParadsePrakt,
				@DateParadsePrakt,
				@CommentsParadsePrakt,
				@DateCreate,
				@UserCreate

				)

SET @TheID = (SELECT SCOPE_IDENTITY()) --(SELECT MAX(ID) AS ID FROM dbo.FORTOTIKES WITH (NOLOCK))
IF(@EXT_BARCODE IS NULL OR @EXT_BARCODE ='')
BEGIN
	SET Context_Info 0x55555 

	DECLARE @PREFIX NVARCHAR(6)
	SELECT @PREFIX = BARCODE_Prefix FROM COMPANIES WHERE COMPANIES.id = @IDYPOKATASTIMA
	SELECT @EXT_BARCODE = RTRIM(@PREFIX) + RTRIM(CAST(@TheID AS NVARCHAR(18)))
	UPDATE FORTOTIKES SET EXT_BARCODE = @EXT_BARCODE WHERE ID = @TheID
END
SELECT @TheID [ID]
waitfor delay '00:00:00:40'            
commit;

go

---END SCRIPT 1942
