---NEW SCRIPT 1943
begin tran;
with doubles as (
	select
		IDPARAST,
		idxrhshs,
		noparast,
		COUNT(*) cnt
	from FORTOTIKES
	group by IDPARAST,NOPARAST,idxrhshs
	having COUNT(*)>1
), fixes as (
	select
		f.ID,
		ROW_NUMBER() OVER (PARTITION BY f.idxrhshs, f.IDPARAST, f.NOPARAST ORDER BY f.ID) rownum,
		'0'+f.NOPARAST  NEWNOPARAST
	from FORTOTIKES f
	join doubles on doubles.IDPARAST = f.IDPARAST
				and doubles.NOPARAST = f.NOPARAST
				and doubles.IDXRHSHS = f.IDXRHSHS
)
--select *
update f set f.NOPARAST = fixes.NEWNOPARAST
from FORTOTIKES f
join fixes on fixes.ID = f.id
where rownum > 1
--order by f.IDPARAST, f.NOPARAST
commit;
go

---END SCRIPT 1943
