				IF_XREOSIKARTELA,
				IF_PISTOSIKARTELA,
				IFKEPXREOSI,
				IFKEPPISTOSI,
				IFPROFORTOTIKI,
				IFKEPYO,
				SEIRA,
				PRINTLABEL,
				PROEPSXOLIO,
				IfPreviewFirst,
				PrinterName,
				IDPARASTEXOFLISI,
				DESCRPARASTEXOFLISI,
				IF_ENIMEROSIAPOTHIKI,
				IFEISAGOGI,
				IFEXAGOGI,
				IF_PAROXIYPIRESION,
				IF_ORDER,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IF_LISTADIANOMIS,
				IF_PRODROMOL,
				IF_LISTAANTIKATABOLON,
				IF_FROM_ANTAP,
				--IFCASH,
				--IFPISTOSI,
				--IFOFEILOMENI,
				--IFPREPAY,
				CATKEPYO,
				CodeLog,
				Copies,
				IF_EDMETAFORAS,
				IF_EDSYNARMOL,
				IS_CANCELLATION,
				IF_LISTA_ASS,
				WEBPARASTATIKO,
				IF_ENIMEROSI_AADE,
				AADE_CODE,
				IfReceiptAntik,
				--IF_EDTOPOTH,
				VoucherTypeCode,
				IDCURRENCY,
				IF_ENIMEROSI_FPA

				)
			VALUES
				(
				@CODEPARAST,
				@PARASTATIKO,	
				@KINDKINISIS,			
				@KINDENIMEROSI	,
				@IFENIMEROSITAMEIO,
				@TRANSFORMTO,
				@IF_AUTONUMBER,
				@IF_TRANSFORM,
				@AUTONUMBER_FROM,
				@IF_ZERO_ON_NEW_YEAR,
				@IF_PRINT,
