ALTER VIEW [dbo].[ANTIKATAVOLESANALYSI_VIEW]
AS

with timda as (
	select  
	idvoh,
	dbo.GROUP_CONCAT(timda) timda
	from GRAMMESFORTTIKIS
	group by IDVOH
)

SELECT F.ID, 
LTRIM(RTRIM(K.CODE)) + ' ' + LTRIM(RTRIM(F.SEIRA)) + '' + CAST(F.NOPARAST AS NVARCHAR(20)) AS NOPARAST, 
F.IDPARAST,
F.PARASTATIKO, 
F.NOPARAST_AP_EISPR_ANTIK,
F.DATEPRINT_AP_EISPR_ANTIK,
    CASE 
        WHEN SUMANTIK IS NULL THEN 0
        WHEN SUMANTIK = 0 THEN 0
        ELSE 1
    END AS TEMAXIA,
    ISNULL(SUMANTIK, 0) AS SUMANTIK,
  CASE 
        WHEN ANTIKCASH IS NULL THEN 0
        WHEN ANTIKCASH = 0 THEN 0
        ELSE 1
    END AS TEMCASH,
    ISNULL(ANTIKCASH, 0) AS ANTIKCASH, 
    CASE 
        WHEN ANTIKEPIT IS NULL THEN 0
        WHEN ANTIKEPIT = 0 THEN 0
        ELSE 1
    END AS TEMEPIT,
    ISNULL(ANTIKEPIT, 0) AS ANTIKEPIT,
    CASE 
        WHEN ANTIKSYNAL IS NULL THEN 0
        WHEN ANTIKSYNAL = 0 THEN 0
        ELSE 1
    END AS TEMSYNAL, 
    ISNULL(ANTIKSYNAL, 0) AS ANTIKSYNAL,
    CASE 
        WHEN ANTIKOTHER IS NULL THEN 0
        WHEN ANTIKOTHER = 0 THEN 0
        ELSE 1
    END AS TEMOTHER, 
    ISNULL(ANTIKOTHER, 0) AS ANTIKOTHER, 
      CASE  
        WHEN ANTIKCASHSYNAR IS NULL THEN 0
        WHEN ANTIKCASHSYNAR = 0 THEN 0
        ELSE 1
    END AS TEMCASHSYNAR, 
    ISNULL(ANTIKCASHSYNAR, 0) AS ANTIKCASHSYNAR, 
ACCOUNTS.ID AS IDCUSTOMER, 
ACCOUNTS.AFM AS CUSTOMERAFM, 
ACCOUNTS.Eponimia AS CUSTOMERDESCR,
apost.ID AS APOSTOLEA_ID, 
apost.AFM AS APOSTOLEA_AFM, 
apost.Eponimia AS APOSTOLEASDECR,
paral.ID AS PARALIPTIS_ID, 
paral.AFM AS PARALIPTIS_AFM, 
paral.Eponimia AS PARALIPTISDECR,
td.TIMDA,
F.COMMENTSANTIK

FROM FORTOTIKES AS F WITH(NOLOCK) 
LEFT JOIN  KINDPARASTATIKON AS K WITH(NOLOCK) ON F.IDPARAST = K.ID  
LEFT JOIN ACCOUNTS WITH(NOLOCK) ON F.IDXREOUMENOU = ACCOUNTS.ID 
left join ACCOUNTS apost on apost.id=f.IDAPOSTOLEA
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI
left join timda td on td.idvoh=f.ID

GO
