			GOTO ErrorPoint
		END

ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint

GO

