ALTER VIEW [dbo].[FORTOTIKESLIGHT_VIEW]
AS


WITH GRAMMES AS (
	SELECT 
		IDVOH,
		MIN(TIMDA) AS TIMDA,
		ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
		MIN(U.UntName) AS SYSKEVASIADESCR,
		MIN(PERIEXOMENO) AS PERIEXOMENO,
		ISNULL(SUM(BAROS),0) AS BAROS,
		ISNULL(SUM(KYBIKA),0) AS KYBIKA,
		ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
	FROM GRAMMESFORTTIKIS
	LEFT JOIN Units U ON U.UntID=GRAMMESFORTTIKIS.SYSKEVASIA
	GROUP BY IDVOH
),
POSA AS (
	SELECT 
		ID,
		SUMPOSO,
		ROUND(FORTOTIKES.POSO, 2) AS KATHARO,
		ROUND(FORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
		ROUND(FORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT
	FROM FORTOTIKES
),
pivoted as (
	select
		IDVOH AS FORTID,[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
	from 
		(
			select
				idvoh,
				case 
					when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
					when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
					when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
					when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
					when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
					when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
					ELSE 'KOLA'
				END AS SYSKEVASIA,
				TEMAXIA
			FROM  GRAMMESFORTTIKIS
		)AS GF
	PIVOT
	(
		SUM(TEMAXIA)
		FOR SYSKEVASIA IN ([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS])
	) AS PV
	
)


select 
	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	CAST(f.noparast as int) as NOPARAST,
	F.NOPARASTDELTIOUDIANOMIS,
	F.NOPARASTDELTIOUAPOSTOLIS,
	F.OXIMA,
	F.DRIVERDESCR,
	F.OMADPROORISMOS,

	CASE 
		ISNULL(IFXRENTOL, 0) * 1
		+ ISNULL(IFXRAPOST, 0) * 2
		+ ISNULL(IFXRTRITOU, 0) * 4
		+ ISNULL(IFXRPARAL, 0) * 8

		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'

		ELSE 'ΑΓΝΩΣΤΟΣ'
	END XREOYMENOS,
    APOST.Eponimia AS APOSTOLEASDESCR,
    PARAL.Eponimia AS PARALISPTISDESCR,
    ENTOL.Eponimia AS ENTOLEASDESCR,
    F.ANTAPOKRITISDESCR,
    f.NOLISTASDIANOMIS,
    CONVERT(VARCHAR,LD.DATEPRINT,103) [DATE_LISTAS_DIANOMIS],
    TRITOS.Eponimia AS TRITOSDESCR,
    HD.DESCRCATALOG AS TIMOKATALOGOS,
    GRAMMES.TIMDA AS TIMDA,
    ISNULL(f.POSO,0) AS POSO,
    ISNULL(POSA.TAXISXREOSEON,0) AS TAXISXREOSEON,
    ISNULL(POSA.SUMPOSOXRFORT,0) AS SUMPOSOXRFORT,
    ISNULL(f.TAXIS,0) AS TAXIS,
    ISNULL(F.SUMPOSO,0) AS SUMPOSO,
    ISNULL(GRAMMES.TEMAXIA,0) AS TEMAXIA,
    ISNULL(GRAMMES.BAROS,0) AS BAROS,
    ISNULL(GRAMMES.KYBIKA,0) AS KYBIKA,
    GRAMMES.SYSKEVASIADESCR AS SYSKEVASIA,
    CASE F.IFPREPAY 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0) 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE F.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFCASH 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFPISTOSI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GRAMMES.PERIEXOMENO,
    F.PERIOXIFORTOSIS,
    F.PERIOXIPARADOSIS,
    F.COMMENTS,
    ISNULL(F.SUMANTIK,0) AS SUMANTIK,
    F.PRAKTOREIODESCR,
    F.STATUS,
    F.DATEPARAD,
    F.IDAPOSTOLEA,
    F.IDPARALIPTI,
    F.IDENTOLEA,
    F.IDANTAPOKRITI,
    F.IDTRITOU,
    F.IDPRAKTOREIO,
	F.ANTIKCASH,
	F.ANTIKEPIT,
	F.ANTIKSYNAL,
	F.ANTIKOTHER,

    CASE F.IFCANCELANTIK 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFCANCELANTIK,
    F.COMMENTSANTIK,
    F.DATEPARADOSI,
    F.COMMENTS2,
    ISNULL(F.EXODATRITON,0) AS XREOSISTRITON,
    CASE F.IFPREPAY 
        WHEN 1 THEN 'ΝΑΙ' 
        ELSE 'ΟΧΙ' 
    END AS IFPREPAY,
    F.NO_EXT_ORDER,
    CASE f.IFOFEILOMENI 
        WHEN 1 THEN 'ΝΑΙ' 
        ELSE 'ΟΧΙ' 
    END AS IFOFEILOMENI,
    ISNULL(GRAMMES.SUMPOSO,0) AS AXIA,
    CASE IFXRENTOL 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRENTOL,
    F.KINDPAYMENTDESCR,
    F.IDKINDPAYMENT,
    CASE IFXRAPOST 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRAPOST,
    CASE IFXRPARAL 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRPARAL,
    CASE IFXRTRITOU 
        WHEN 0 THEN 'ΟΧΙ' 
        ELSE 'ΝΑΙ' 
    END AS IFXRTRITOU,
    F.IFANTIKCASH,
    F.IFANTIKEPIT,
    F.IFANTIKSYNAL,
    F.IFANTIKOTHER,
    F.ifDelete,
    F.IFCANCEL,
    F.DATECANCEL,
    F.DROMOLOGIO,
    F.THESI,
    F.IFPARADOSI,
    F.AITIOLOGIAPARASTATIKOU,
    CONVERT(varchar,F.DATEFORTOSIS,102) AS DATEFORTOSIS,
    F.IFEPISTROFI,
    F.DATEEPISTROFIS,
    F.AITIOLOGIAEPISTROFIS,
    F.COMMENTSEPISTROFIS,
    F.IFCASH,
    F.IFPISTOSI,
    F.STATUSDESCR,
    F.YPAITIOS,
    F.IFEPANADROMOLOGISI,
    F.IFEPANEKDOSI,
    F.IFOKEPANADROMOLOGISI,
    F.NOPARASTANTIK,
    F.COMMENTSAKIROSIS,
    F.IFEISPRANTIK,
    F.IFPARADOSIANTIK,
    F.IFPARALAVIANTIK,
    F.COMMENTSPARADANTIK,
    F.COMMANTSPARALANTIK,
    F.COMMENTSEISPRANTIK,
    CONVERT(varchar,F.DATEPARADANTIK,102) AS DATEPARADANTIK,
    CONVERT(varchar,F.DATEPARALANTIK,102) AS DATEPARALANTIK,
    CONVERT(varchar, F.DATEEISPRANTIK,102) AS DATEEISPRANTIK,
    F.EISPRAXASANTIK,
    F.NOPARPARADANTIK,
    F.NOPARASTEISPRANTIK,
    F.NOPARPARALANTIK,
    F.DATEPARAL,
    F.COMMENTSPARAD,
    F.COMMANTSPARAL,
    F.TIMEPARALFROM,
    F.TIMEPARALTO,
    F.TIMEPARADFROM,
    F.TIMEPARADTO,
    CONVERT(varchar,F.DATECANCELANTIK,102) AS DATECANCELANTIK,
    F.IDPARAST,
    ISNULL(F.TAXISPERCENT,0) AS TAXISPERCENT,
    ISNULL(F.ANAMEXODO,0) AS ANAMEXODO,
    F.ID AS IDFORTOTIKIS,
    F.AFMXREOUMENOU,
    ISNULL(posa.KATHARO,0) AS KATHARO,
    apost.Epagelma AS EPAGAPOST,
    apost.AddressStr AS ADDRSTRAPOST,
    apost.AddressNo AS ADDRNOAPOST,
    apost.AddressTK AS TKAPOST,
    apost.AddressCity AS CITYAPOST,
    apost.AddressPref AS NOMOSAPOST,
    apost.Tel AS TELAPOST,
    apost.DOY AS DOYAPOST,
    PARAL.Epagelma AS EPAGPARAL,
    PARAL.AddressStr AS ADDRSTRPARAL,
    PARAL.AddressNo AS ADDRNOPARAL,
    PARAL.AddressTK AS ADDRTKPARAL,
    PARAL.AddressCity AS ADDRCITYPARAL,
    PARAL.AddressPref AS ADDRNOMOSPARAL,
    PARAL.Tel AS TELPARAL,
    PARAL.DOY AS DOYPARAL,
    ENTOL.Epagelma AS EPAGENTOL,
    ENTOL.AddressStr AS ADDRSTRENTOL,
    ENTOL.AddressNo AS ADDRNOENTOL,
    ENTOL.AddressTK AS ADDRTKENTOL,
    ENTOL.AddressCity AS ADDRCITYENTOL,
    ENTOL.AddressPref AS ADDRNOMOSENTOL,
    ENTOL.Tel AS TELENTOL,
    ENTOL.DOY AS DOYENTOL,
    TRITOS.Epagelma AS EPAGTR,
    TRITOS.AddressStr AS ADDRSTTR,
    TRITOS.AddressNo AS ADDRNOTR,
    TRITOS.AddressTK AS ADDRTKTR,
    TRITOS.AddressCity AS ADDRCITYTR,
    TRITOS.AddressPref AS ADSTRDRNOMO,
    TRITOS.Tel AS TELTR,
    TRITOS.DOY AS DOYTR,
    F.AFMAPOSTOLEA,
    F.AFMENTOLEA,
    F.IF_TRANSFTOESEX,
    F.AFMPARALIPTI,
    F.AFMTRITOU,
    F.AFMANTAPOKRITI,
    F.IFPARADOSITOPEL,
    F.IFPARALABIFROMPEL,
    F.IDXRHSHS,
    F.IDCOMPANY,
    F.IFEXOFLISI,
    F.IDYPOKATASTIMA,
    F.UserMod,
    F.DateMod,
    F.CONTAINER,
    F.BOAT,
    F.POD_ADDED,
    F.IDKENTROUKOSTOUS,
    F.NO_EXT_ORDER_IK,
    F.IDENTOLIS,
    F.IF_CANCEL,
    F.ID_CANCELLATION,
    F.SEIRA_CANCELLATION,
    F.NOPARAST_CANCELLATION,
    F.DETAILS_CANCELLATION,
    F.CANCELDATE,
    F.EXT_BARCODE,
    F.NO_EXT_FORT,
    F.POD_PATH,
    F.POD_USER,
    F.POD_PATH_2,
    F.UserCreate,
    F.DateCreate,
    F.IF_FROM_ANTAP,
    F.IF_TO_ANTAP,
	F.ARRIVAL,
	f.ARANAFORAS,
	F.NOPARAST_AP_EISPR_ANTIK,
    case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as SYNTHIKI,
    isnull(pivoted.DEMATA,0) as DEMATA,
    isnull(pivoted.PALETA,0) as PALETA,
    isnull(pivoted.KOLA,0) AS KOLA,
    isnull(pivoted.STAND,0) AS STAND,
    isnull(pivoted.ROLI,0) AS ROLI,
    isnull(pivoted.THALAMOS,0) AS THALAMOS
from FORTOTIKES f
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST 
join PARASTATIKA_ANA_KATHGORIA par on par.ID_KINDPARASTATIKON=f.IDPARAST and par.ID_CAT_PARASTATIKON=4
LEFT JOIN ACCOUNTS APOST ON APOST.id=F.IDAPOSTOLEA
LEFT JOIN ACCOUNTS PARAL ON PARAL.id = F.IDPARALIPTI
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
LEFT JOIN ACCOUNTS TRITOS ON TRITOS.id=F.IDTRITOU
LEFT JOIN MAX_FORTOTIKES_ANA_LISTA FAL ON FAL.IDFORTOTIKIS=F.ID
LEFT JOIN LISTESDIANOMIS LD ON LD.ID=FAL.IDLISTAS
LEFT JOIN dbo.HEADERVOHPRICING HD WITH (NOLOCK) ON HD.IDVOH=F.IDENTOLIS  

LEFT JOIN GRAMMES ON GRAMMES.IDVOH=f.ID
LEFT JOIN POSA ON POSA.ID=f.ID
left join pivoted on pivoted.FORTID=f.id





GO



---END SCRIPT 1969
