ALTER VIEW [dbo].[STORED_KAA_FORT_REPORT]
AS
WITH pivoted as
(
					
			select
				IDVOH AS FORTID,[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS],[XB],[KLOUBA],[KLOUBAKI],[L2],[40X40],[MXP],[PEP]
			from 
				(
					select
						idvoh,
						case 							
							when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
							when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
							when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
							when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
							when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
							when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
							when SYSKEVASIADESCR like 'Χ/Β%' then '[XB]'
							when SYSKEVASIADESCR like 'ΚΛΟΥΒΑ' then 'KLOUBA'
							when SYSKEVASIADESCR like 'ΚΛΟΥΒΑΚΙ%' then 'KLOUBAKI'
							when SYSKEVASIADESCR like 'L2%' then 'L2'
							when SYSKEVASIADESCR like '40X40X21%' then '[40X40]'
							when SYSKEVASIADESCR like 'ΜΧΡ%' then 'MXP'
							when SYSKEVASIADESCR like 'ΠΕΠ%' then 'PEP'
							ELSE 'KOLA'
						END AS SYSKEVASIA,
						TEMAXIA
					FROM  GRAMMESFORTTIKIS
				)AS GF
			PIVOT
			(
				SUM(TEMAXIA)
				FOR SYSKEVASIA IN ([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
									,[XB],[KLOUBA],[KLOUBAKI],[L2],[40X40],[MXP],[PEP])
			) AS PV
)	

select
	fk.XREOYMENOS,
	fk.APOSTOLEASDESCR,
	fk.ENTOLEASDESCR,
	paral.AFM as AFMPARALIPTI,
	fk.PARALISPTISDESCR,
	APOST.AFM AS AFMAPOSTOLEA,
	ISNULL(fk.TEMAXIA,0) AS TEMAXIA,
	fk.SYSKEVASIA,
	fk.NOPARASTFORT AS NOPARAST,
	fk.CODE,
	ISNULL(fk.BAROS, 0) AS BAROS, 
    ISNULL(fk.KYBIKA, 0) AS KYBIKA, 
    fk.PERIEXOMENO,
    paral.Mobile AS PARALIPTIS_MOBILE,
    paral.AddressCity, 
    isnull(fk.KOMISTRA,0) AS KOMISTRA, 
    isnull(fk.DIKAIOMA,0) AS DIKAIOMAFORTOTIKIS, 
    isnull(fk.OTHERPOSO,0) AS OTHERXREOSIS,
    (paral.AddressStr + ' ' + paral.AddressNo) AS ADDRPARADOSIS, 
    paral.AddressCity AS ADDRCITYPARAL, 
    isnull(fk.XREOSIPROPLIROMENES,0) AS XREOSIPROPLIROMENES, 
    ISNULL(fk.XREOSIOFEILOMENES,0) AS XREOSIOFEILOMENES,
    (ISNULL(paral.Tel,'') + ' ' + ISNULL(paral.Mobile,'')) AS TELPARALIPTI,
	ISNULL(f.ANTIKCASH,0) AS ANTIKCASH,
	ISNULL(F.ANTIKEPIT,0) AS ANTIKEPIT,
	ISNULL(F.ANTIKSYNAL,0) AS ANTIKSYNAL,
	ISNULL(F.ANTIKOTHER,0) AS ANTIKOTHER,      
    ISNULL(fk.SUMANTIK,0) AS SUMANTIK,
    KAA.PARASTATIKO, 
    KAA.SEIRA AS SEIRAKAA, 
    KAA.NOPARAST AS NOPARASTKAA, 
    KAA.DATEPRINT, 
    KAA.OXIMA, 
    KAA.DRIVER,
    fk.EXODATRITON AS XREOSISTRITON, 
    TRUCKS.OLastName, 
    TRUCKS.OmProorDescr, 
    ISNULL(fk.AXIA, 0) AS AXIA, 
    fk.TIMDA, 
    fk.ANTAPOKRITIS,
    F.EXT_BARCODE,
    fk.OMADPROORISMOS, 
    ISNULL(fk.ASFALISTRA,0) AS ASFALISTRA, 
    ISNULL(fk.TAXIS,0) AS TAXISXREOSEON, 
    ISNULL(fk.POSO,0) AS KATHARO, 
    ISNULL(fk.EXODATRITON,0) AS EXODATRITON,
    ISNULL(fk.XREOSIPROPLIROMENESCASH,0) AS XREOSIPROPLIROMENESCASH,
    ISNULL(fk.XREOSIPROPLIROMENESPISTOSI,0) AS XREOSIPROPLIROMENESPISTOSI,
    case (f.IFOFEILOMENI*1 + f.IFPISTOSI*2)
		when 3 then ISNULL(f.SUMPOSO,0)
		else 0
	end as XREOSIOFEILOMENESPISTOSI, 
    KAA.ID, 
    fk.IDFORTOTIKIS, 
    ISNULL(fk.OFEILOMENAKOMISTRA,0) AS OFEILOMENAKOMISTRA, 
    ISNULL(fk.SYN_POSO_FORTOTIKIS,0) AS SYN_POSO_FORTOTIKIS,
    KAA.IDCOMPANY, 
    KAA.IDYPOKATASTIMA, 
    KAA.IDXRHSHS, 
    KAA.PERIOXIPROORISMOU, 
    KAA.PERIOXIPARADOSIS, 
    TRUCKS.Tel AS TELOWNER, 
    KAA.AFMCUSTOMER, 
    KAA.AFMANTAPOKRITIS, 
    KAA.FORTOSI, 
    KAA.CUSTOMER, 
    
		KAA.NOFORT,
        KAA.POSOEXODA,
        KAA.TAXISEXODA,
        KAA.SUMPOSOEXODA,
        
    ANTAP.Eponimia AS ANTAPOKRITISKAA,
    KAA.OMADPROORISMOS AS OMPROORKAA,
    OD.Tel AS TELDRIVER,
    KAA.CONTAINER, 
    KAA.BOAT,
    (ANTAP.AddressStr + ' ' + ANTAP.AddressNo + '  ' + ANTAP.AddressCity + ' - ' + ANTAP.AddressCountry) AS ADDRESSANTAPOKRITI, 
    ANTAP.AFM AS AFMANTAPOKRITI, 
    ANTAP.DOY AS DOYANTAPOKRITI , 
    ISNULL(fk.DIAFORA_EXODA , 0) AS DIAFORA_EXODA,
    ISNULL(fk.ERGATIKA , 0) AS ERGETIKA, 
	ISNULL(fk.XREOSEISTRITON , 0) AS XREOSEISTRITON, 
	ISNULL(fk.EMVASTIKA , 0) AS EMVASTIKA, 
	ISNULL(fk.OTHERXREOSEIS , 0) AS OTHERXREOSEIS,--, 
	ISNULL(fk.PROPLMETRERGATIKA , 0) AS PROPLMETRERGATIKA, 
	ISNULL(fk.PROPLMETRASFALISTRA , 0) AS PROPLMETRASFALISTRA, 
	ISNULL(fk.PROPLMETRDIKAIOMA , 0) AS PROPLMETRDIKAIOMA, 
	ISNULL(fk.PROPLMETRKOMISTRA , 0) AS PROPLMETRKOMISTRA, 
	(ISNULL(fk.ERGATIKA , 0)+ ISNULL(fk.OTHERXREOSEIS , 0) + ISNULL(fk.ASFALISTRA , 0)) AS ERG_ASF_OTHER, 
	(ISNULL(fk.ERGATIKA , 0)+ ISNULL(fk.OTHERXREOSEIS , 0)) AS ERG_OTHER, (ISNULL(fk.ERGATIKA , 0) + ISNULL(fk.ASFALISTRA , 0)) AS ERG_ASF, ISNULL(fk.KATHAROPROPLMETR , 0) AS KATHAROPROPLMETR, 
	ISNULL(fk.TAXISPROPLMETR , 0) AS TAXISPROPLMETR, 
	ISNULL(fk.KATHAROOFEIL , 0) AS KATHAROOFEIL, 
	ISNULL(fk.TAXISOFEIL , 0) AS TAXISOFEIL, 
	(ISNULL(fk.OTHERXREOSEIS , 0) + ISNULL(fk.ASFALISTRA , 0)) AS ASF_OTHER, 
	(ISNULL(fk.KOMISTRA , 0)+ ISNULL(fk.DIKAIOMA , 0)) AS KOM_DIKAIOMA, 
	fk.IDPRAKTOREIO, 
	fk.PRAKTOREIODESCR,  
	ISNULL(fk.PROPLMETROTHERXREOSEIS , 0) AS PROPLMETROTHERXREOSEIS,
	ISNULL(fk.ANAMEXODO , 0) AS ANAMEXODO,
	ISNULL(PVT.DEMATA,0) AS DEMATA,
    ISNULL(PVT.PALETA,0) AS PALETA,
    ISNULL(PVT.KOLA,0) AS KOLA,
    ISNULL(PVT.STAND,0) AS STAND,
    ISNULL(PVT.ROLI,0) AS ROLI,
    ISNULL(PVT.THALAMOS,0) AS THALAMOS,
    ISNULL(PVT.[XB],0) AS X_B,
    ISNULL(PVT.KLOUBA,0) AS KLOUBA,
    ISNULL(PVT.KLOUBAKI,0) AS KLOUBAKI,
    ISNULL(PVT.L2,0) AS L2,
    ISNULL(PVT.[40X40],0) AS D40_40,
    ISNULL(PVT.MXP,0) AS MXP,
    ISNULL(PVT.PEP,0) AS PEP
	
   
     
from FORTOTIKES_ANA_KAA fk
left join ACCOUNTS paral on paral.id=fk.IDPARALIPTI
left join ACCOUNTS APOST on APOST.id=fk.IDAPOSTOLEA
LEFT JOIN KAA ON KAA.ID=fk.IDKAA
LEFT JOIN TRUCKS ON TRUCKS.ArKykloforias=KAA.OXIMA
LEFT JOIN FORTOTIKES F ON F.ID=fk.IDFORTOTIKIS
LEFT JOIN ACCOUNTS ANTAP ON ANTAP.ID=KAA.IDANTAPOKRITIS
LEFT JOIN ODIGOI OD ON (OD.LastName+ ' '+OD.FirstName)=KAA.DRIVER
LEFT JOIN pivoted PVT ON PVT.FORTID=fk.IDFORTOTIKIS

GO




---END SCRIPT 1974
