create TRIGGER [dbo].[IDVOH_SUGENTROTIKO]
   ON  [dbo].[FORTOTIKES]
   AFTER UPDATE
AS 
BEGIN

	SET NOCOUNT ON;

    IF UPDATE (NOPARASTDELTIOUDIANOMIS) 
    BEGIN
		
		UPDATE FORT
			SET FORT.IDVOH = VOH.ID
		FROM FORTOTIKES FORT
		JOIN INSERTED INS on INS.ID = FORT.ID
		JOIN VOH ON LTRIM(RTRIM(VOH.SEIRA)) + LTRIM(RTRIM(VOH.NOPARAST)) = LTRIM(RTRIM(FORT.NOPARASTDELTIOUDIANOMIS))
		WHERE LEN(RTRIM(LTRIM(INS.NOPARASTDELTIOUDIANOMIS))) > 1
		
	END
END

go

---END SCRIPT 1977
