---NEW SCRIPT 1978

create view [dbo].[VOH_VIEW_WITH_ANALYSI_GRAMMON] as 

with row_num as (
	SELECT
		dbo.GRAMMESFORTTIKIS.IDVOH [IDVOH],
		dbo.GRAMMESFORTTIKIS.ID [IDGF],
		ROW_NUMBER() OVER (PARTITION BY dbo.GRAMMESFORTTIKIS.IDVOH ORDER BY dbo.GRAMMESFORTTIKIS.ID) [ROWNUM]
	FROM dbo.GRAMMESFORTTIKIS
)


select 
	v.id,
	convert(int,f.noparast) noparast,
	gf.TIMDA,
	gf.syskevasiadescr,
	gf.PERIEXOMENO,
	gf.temaxia,
	gf.KYBIKA,
	gf.BAROS,
	gf.SUMPOSO axia,
	case rn.ROWNUM
		when 1 then f.poso
	else null
	end as poso,
	case rn.rownum
		when 1 then f.taxis
	else null
	end as taxis,
	case rn.rownum
		when 1 then f.sumposo
	else null
	end as sumposo	

from fortotikes f
join voh v on f.IDVOH=v.id
join grammesforttikis gf on gf.idvoh = f.id
join row_num rn on rn.IDGF = gf.id 


GO


---END SCRIPT 1978
