---NEW SCRIPT 1979
UPDATE XREOSEIS SET IFKOMISTRA=1 WHERE DESCR LIKE '%ΚΟΜΙΣΤΡ%'
GO

EXEC SP_RENAME 'FORTOTIKES_ANALYSH_XREOSEON','FORTOTIKES_ANALYSH_XREOSEON_OLD'
GO


CREATE view [dbo].[FORTOTIKES_ANALYSH_XREOSEON] AS 

with pivot_xreoseon as (
						select
							idvoh as fortid, [KOMISTRA],[DIKAIOMA],[ERGATIKA],[ASFALISTRA],[EMVASTIKA],[LOIPA],[OTHERPOSO]
						FROM (

								select
									xad.IDVOH,
									CASE 
										WHEN isnull(xr.ifkomistra,0)=1 then 'KOMISTRA'
										WHEN isnull(xr.ifDikaiomaFortotikis,0)=1 then 'DIKAIOMA'
										WHEN isnull(xr.ifERGATIKA,0)=1 then 'ERGATIKA'
										WHEN isnull(xr.ifASFALISTRA,0)=1 then 'ASFALISTRA'
										WHEN isnull(xr.IfEmvastika,0)=1 then 'EMVASTIKA'
										WHEN isnull(xr.ifOther,0)=1 then 'LOIPA'
									ELSE 'OTHERPOSO'
									END AS XREOSI,
									XAD.POSO

								from XREOSISANADELTIO xad
								join Xreoseis xr on xr.ID=xad.IDXREOSIS
								where isnull(xad.if_to_fortotiki,0)=1
						) AS XRS
						PIVOT ( 
								SUM(POSO)
								FOR XREOSI IN ([KOMISTRA],[DIKAIOMA],[ERGATIKA],[ASFALISTRA],[EMVASTIKA],[LOIPA],[OTHERPOSO])
								) AS PV
),
grammes AS (
			SELECT 
				IDVOH, 
				ISNULL(SUM(GRF.BAROS),0) AS BAROS , 
				ISNULL(SUM(GRF.KYBIKA),0) AS KYBIKA, 
				ISNULL(SUM(GRF.TEMAXIA),0) AS TEMAXIA, 
				ISNULL(SUM(GRF.SUMPOSO),0) AS AXIA, 
				MIN(GRF.PERIEXOMENO) AS PERIEXOMENO, 
				MIN(GRF.TIMDA) AS TIMDA, 
				MIN(GRF.SYSKEVASIADESCR) AS SYSKEVASIA 
			FROM GRAMMESFORTTIKIS GRF
			--LEFT JOIN Units U ON U.UntID=GRF.SY
			GROUP BY IDVOH
			)
select
	f.ID, 
	f.DATEPRINT, 
	f.IDPARALIPTI, 
	f.PARALISPTISDESCR, 
	f.IDAPOSTOLEA, 
	f.APOSTOLEASDESCR, 
	f.IDENTOLEA, 
	f.ENTOLEASDESCR, 
	f.IDTRITOU, 
	f.TRITOSDESCR, 
	f.OMADPROORISMOS, 
	f.OXIMA, 
	f.DRIVERDESCR, 
	f.NOPARAST, 
	kp.code,
	f.NOPARAST AS NOPARASTFORT, 
	CASE 
		WHEN f.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' 
		WHEN f.IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' 
		WHEN f.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ'
		WHEN f.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' 
		ELSE 'ΑΓΝΩΣΤΟ' 
	END AS XREOYMENOS, 
	CASE f.IFPREPAY 
		WHEN 1 THEN ISNULL(f.SUMPOSO,0) 
		ELSE 0 
	END AS XREOSIPROPLIROMENES, 
	CASE f.IFOFEILOMENI 
		WHEN 1 THEN ISNULL(f.SUMPOSO,0) 
		ELSE 0 
	END AS XREOSIOFEILOMENES, 
	CASE f.IFPREPAY 
		WHEN 1 THEN 
			CASE f.IFCASH WHEN 1 THEN ISNULL(f.SUMPOSO,0) 
			ELSE 0 
			END ELSE 0 
	END AS XREOSIPROPLIROMENESCASH, 
	CASE f.IFPREPAY 
		WHEN 1 THEN 
			CASE f.IFPISTOSI WHEN 1 THEN ISNULL(f.SUMPOSO,0)  
			ELSE 0 
			END ELSE 0 
	END AS XREOSIPROPLIROMENESPISTOSI, 
	isnull(f.POSO,0) POSO, 
	isnull(f.TAXIS,0) TAXIS, 
	isnull(f.SUMPOSO,0) SUMPOSO,
	isnull(px.KOMISTRA,0) KOMISTRA,
	isnull(px.DIKAIOMA,0) DIKAIOMA,
	isnull(px.ERGATIKA,0) ERGATIKA,
	isnull(px.ASFALISTRA,0) ASFALISTRA,
	isnull(px.EMVASTIKA,0) EMVASTIKA,
	isnull(px.LOIPA,0) LOIPA,
	(isnull(px.OTHERPOSO,0)+isnull(px.ERGATIKA,0)+isnull(px.ASFALISTRA,0)+isnull(px.EMVASTIKA,0)+isnull(px.LOIPA,0)) OTHERPOSO,
	isnull(f.ANTIKCASH,0) ANTIKCASH, 
	isnull(f.ANTIKEPIT,0) ANTIKEPIT, 
	isnull(f.ANTIKSYNAL,0) ANTIKSYNAL, 
	isnull(f.ANTIKOTHER,0) ANTIKOTHER, 
	isnull(f.EXODATRITON,0) EXODATRITON, 
	isnull(f.SUMANTIK,0) SUMANTIK,
	gr.BAROS, 
	gr.KYBIKA, 
	gr.TEMAXIA, 
	gr.AXIA,
	gr.SYSKEVASIA,
	gr.PERIEXOMENO, 
	gr.TIMDA, 
	f.IDXRHSHS, 
	f.IDCOMPANY, 
	f.IDYPOKATASTIMA, 
	f.IDPRAKTOREIO, 
    f.PRAKTOREIODESCR,  
	f.IF_TRANSFTOESEX, 
	f.ANAMEXODO



from FORTOTIKES f
join KINDPARASTATIKON kp on kp.id=f.IDPARAST
left join pivot_xreoseon px on px.fortid=f.ID
left join grammes gr on gr.IDVOH=f.ID


GO


---END SCRIPT 1979
