ALTER PROCEDURE [dbo].[AddMAILSETTINGS]
(
	@IDCOMPANY NUMERIC(18, 0),
	@pop3Server NVARCHAR (50)= NULL,
	@smtpServer NVARCHAR(50) =NULL,
	@mailAddress NVARCHAR(60)= NULL,
	@mailUsername NVARCHAR(30)= NULL,
	@mailPassword NVARCHAR(25)= NULL,
	@pop3Port int = 110,
	@smtpPort int = 25,
	@mailTIME_OUT NUMERIC (18,0) = 20000,
	@IFSSl	int =0,
	@IfExportToPdf	int = 0,
	@IFSENDMAILWITHKAA INT =0,
	@IFSENDMAILWITHLISTADIAN INT =0,
	@TheID NUMERIC(18, 0)= NULL output
	)
AS
	DECLARE @TRACOUNT 	INT
	DECLARE @ErrorNumber 	INT
	DECLARE @ErrorDescription NVARCHAR(255)
	DECLARE @Rowcount	INT
	DECLARE @RetVal 	INT
	DECLARE @Number 	NVARCHAR(30)	
	SET NOCOUNT ON
	SET @ErrorNumber = 0
		BEGIN
		DELETE FROM COMPANYSETTINGS WHERE IDCOMPANY=@IDCOMPANY;
		
			INSERT INTO COMPANYSETTINGS
				(
					IDCOMPANY,
					pop3Server,
					smtpServer,
					mailAddress,
					mailUsername,
					mailPassword,
					pop3Port,
					mailTIME_OUT,
					IFSSL,
					IFSENDMAILWITHKAA,
					IFSENDMAILWITHLISTADIAN,
					smtpPort,
					IfExportToPdf
				)
			VALUES
				(
					@IDCOMPANY,
					@pop3Server,
					@smtpServer,
					@mailAddress,
					@mailUsername,
					@mailPassword,
					@pop3Port,
					@mailTIME_OUT,
					@IFSSL,
					@IFSENDMAILWITHKAA,
					@IFSENDMAILWITHLISTADIAN,
					@smtpPort,
					@IfExportToPdf
					)
			SELECT  @TheID = MAX(ID) FROM dbo.COMPANYSETTINGS

		END

	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************


ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint

;
GO

---END SCRIPT 1984
