IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[LOGISTIKI_CUSTOMERS_EPSILONNET_C_CATEGORY]'))
DROP VIEW [dbo].[LOGISTIKI_CUSTOMERS_EPSILONNET_C_CATEGORY]
GO

CREATE view [dbo].[LOGISTIKI_CUSTOMERS_EPSILONNET_C_CATEGORY]
as
select 
	A.id,
	a.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟ],
	a.Eponimia [ΕΠΩΝΥΜΙΑ],
	a.AFM [ΑΦΜ],
	i.IRSID [ΚΩΔΙΚΟΣ ΔΟY],
	a.CATKEPYO [ΚΕΠΥΟ],
	case	
		when A.catkepyo in (2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΟΣ],
	A.addresscountry [ΧΩΡΑ],
	a.AddressStr [ΔΙΕΥΘΥΝΣΗ],
	a.AddressCity [ΠΟΛΗ],
	A.AddressTK [T.K.],
	A.tel [ΤΗΛΕΦΩΝΟ],
	A.Fax [FAX],
	a.IF_PEL,
	a.IF_ANTAPOKRITIS,
	a.IF_PROM,
	a.IF_ERG
from ACCOUNTS a
left join IRS i on i.Description=a.DOY
where a.ifDelete=0

union

select 
	emp.id,
	'90000000'+emp.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟ],
	emp.Eponimia [ΕΠΩΝΥΜΙΑ],
	emp.AFM [ΑΦΜ],
	i.IRSID [ΚΩΔΙΚΟΣ ΔΟY],
	null [ΚΕΠΥΟ],
	'0' [ΥΠΟΧΡΕΟΣ],
	emp.addresscountry [ΧΩΡΑ],
	emp.AddressStr [ΔΙΕΥΘΥΝΣΗ],
	emp.AddressCity [ΠΟΛΗ],
	emp.AddressTK [T.K.],
	emp.tel [ΤΗΛΕΦΩΝΟ],
	emp.Fax [FAX],
	'0' [IF_PEL],
	'0' [IF_ANTAPOKRITIS],
	'0' [IF_PROM],
	'1' [IF_ERG]
from EMPLOYEE emp
left join IRS i on i.Description=emp.DOY
where emp.ifDelete=0




GO


---END SCRIPT 1987
