---NEW SCRIPT 1988
IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[LOGISTIKI_EPSILONNET_B_CATEGORY]'))
DROP VIEW [dbo].[LOGISTIKI_EPSILONNET_B_CATEGORY]
GO


CREATE view [dbo].[LOGISTIKI_EPSILONNET_B_CATEGORY]
AS
select 
	f.id,
	'100'+CAST(f.id as varchar) [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'0' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end as	[ΚΕΠΥΟ],
	case 
		when A.catkepyo in (0,2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	a.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	a.id ACID,
	CAST(f.dateprint as date)[DATEPRINT],
	CONVERT (varchar, f.dateprint, 103) [ΗΜΕΡΟΜΗΝΙΑ],
	A.Eponimia [ΑΙΤΙΟΛΟΓΙΑ],
	rtrim(ltrim(f.PARASTATIKO))+'  ' +'#'+ rtrim(ltrim(isnull(f.seira,'')))+ ' ' +rtrim(ltrim(f.noparast))[ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then f.POSO
		else 0
	end as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then f.TAXIS
		else 0
	end as [Αξία ΚΕΠΥΟ Φ.Π.Α.],
	isnull(k.CodeLog,'') [ΛΟΓΑΡΙΑΣΜΟΣ],
	f.POSO [ΚΑΘΑΡΗ ΑΞΙΑ],
	f.TAXIS [ΑΞΙΑ ΦΠΑ],
	isnull(a.CodeLog,'') [ΓΕΝΙΚΟΣ ΛΟΓΑΡΙΑΣΜΟΣ],
	null [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	null [Λοιπές Δαπάνες],
	null [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	f.ifDelete [Ακυρωμένο],
	null [Πεδίο Ομαδοποίησης Ακύρωσης]
	
from FORTOTIKES f
join ACCOUNTS a on a.id=f.IDXREOUMENOU
join kindparastatikon k on k.id=f.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (1,5)
union
select
	v.ID,
	'200'+CAST(v.id as varchar)  [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'0' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	a.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	a.id ACID,
	CAST(v.dateprint as date)[DATEPRINT],
	CONVERT (varchar, v.dateprint, 103) [ΗΜΕΡΟΜΗΝΙΑ],
	A.Eponimia [ΑΙΤΙΟΛΟΓΙΑ],
	rtrim(ltrim(v.PARASTATIKO))+'  ' +'#'+ rtrim(ltrim(isnull(v.seira,'')))+ ' ' +rtrim(ltrim(v.noparast)) [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then v.POSO
		else 0
	end as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then v.TAXIS
		else 0
	end as [Αξία ΚΕΠΥΟ Φ.Π.Α.],
	isnull(k.CodeLog,'') [ΛΟΓΑΡΙΑΣΜΟΣ],
	v.POSO [ΚΑΘΑΡΗ ΑΞΙΑ],
	v.TAXIS [ΑΞΙΑ ΦΠΑ],
	isnull(a.codelog,'') [ΓΕΝΙΚΟΣ ΛΟΓΑΡΙΑΣΜΟΣ],
	null [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	null [Λοιπές Δαπάνες],
	null [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	v.ifDelete [Ακυρωμένο],
	null [Πεδίο Ομαδοποίησης Ακύρωσης]

from VOH v
join ACCOUNTS a on a.id=v.IDCUSTOMER
join kindparastatikon k on k.id=v.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (1,5)
union
select
	e.ID,
	'300'+CAST(e.id as varchar)  [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'0' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	a.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	a.id ACID,
	CAST(e.dateprint as date)[DATEPRINT],
	CONVERT (varchar, e.dateprint, 103) [ΗΜΕΡΟΜΗΝΙΑ],
	A.Eponimia [ΑΙΤΙΟΛΟΓΙΑ],
	rtrim(ltrim(e.PARASTATIKO))+'  '  +'#'+ rtrim(ltrim(isnull(e.seira,'')))+ ' ' +rtrim(ltrim(e.noparast)) [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then e.POSO
		else 0
	end as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then e.TAXIS
		else 0
	end as [Αξία ΚΕΠΥΟ Φ.Π.Α.],
	isnull(k.CodeLog,'') [ΛΟΓΑΡΙΑΣΜΟΣ],
	e.POSO [ΚΑΘΑΡΗ ΑΞΙΑ],
	e.TAXIS [ΑΞΙΑ ΦΠΑ],
	isnull(a.CodeLog,'') [ΓΕΝΙΚΟΣ ΛΟΓΑΡΙΑΣΜΟΣ],
	null [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	null [Λοιπές Δαπάνες],
	null [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	e.ifDelete [Ακυρωμένο],
	null [Πεδίο Ομαδοποίησης Ακύρωσης]

from ESODA e
join ACCOUNTS a on a.id=e.IDPROM
join kindparastatikon k on k.id=e.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (1,5)




GO





---END SCRIPT 1988
