IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[LOGISTIKI_EPSILONNET_EISPRAKSEIS_PLIROMES_C_CATEGORY]'))
DROP VIEW [dbo].[LOGISTIKI_EPSILONNET_EISPRAKSEIS_PLIROMES_C_CATEGORY]
GO


CREATE VIEW [dbo].[LOGISTIKI_EPSILONNET_EISPRAKSEIS_PLIROMES_C_CATEGORY]
AS (
select 
	
	kp.id													[KID],
	AC.ID													[ACID],
	'01'+CONVERT(NVARCHAR(20),R.ID)							[ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)],
	'ΤΑΜ'													[ΕΙΔΟΣ_ΚΙΝΗΣΗΣ],
	'0'														[ΚΕΠΥΟ],
	AC.CATKEPYO												[ΥΠΟΧΡΕΩΣΗ_ΥΠΟΒΟΛΗΣ],
	AC.Code													[ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	ac.AFM													[ΑΦΜ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	R.DATEPRINT												[ΗΜΕΡΟΜΗΝΙΑ],
	R.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ],
	LTRIM(RTRIM(R.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(R.DOCNO)))		[ΠΑΡΑΣΤΑΤΙΚΟ],
	'0'														[ΑΞΙΑ_ΚΕΠΥΟ_ΥΠΟΧΡΕΟΥ],
	'0'														[ΦΠΑ_ΚΕΠΥΟ],
	KP.CodeLog												[ΛΟΓΑΡΙΑΣΜΟΣ],
	'0'														[(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	
	R.SUMPOSO												[ΑΞΙΑ],
	LTRIM(RTRIM(R.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(R.DOCNO)))	[ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ],
	R.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ],
	''														[ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ],
	CASE R.ifDelete
		WHEN 1 THEN 1
		ELSE ''
	END AS													[ΑΚΥΡΩΜΕΝΟ],
	''														[Πεδίο_Ομαδοποίησης_Ακύρωσης]

from RECEIPTS R
JOIN ACCOUNTS AC ON AC.id=R.IDCUSTOMER
JOIN KINDPARASTATIKON KP ON KP.ID=R.IDKINDPARAST

--WHERE AC.id=66764

UNION

select 
	
	kp.id													[KID],
	AC.ID													[ACID],
	'01'+CONVERT(NVARCHAR(20),R.ID)							[ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)],
	'ΤΑΜ'													[ΕΙΔΟΣ_ΚΙΝΗΣΗΣ],
	'0'														[ΚΕΠΥΟ],
	AC.CATKEPYO												[ΥΠΟΧΡΕΩΣΗ_ΥΠΟΒΟΛΗΣ],
	AC.Code													[ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	ac.AFM													[ΑΦΜ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	R.DATEPRINT												[ΗΜΕΡΟΜΗΝΙΑ],
	R.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ],
	LTRIM(RTRIM(R.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(R.DOCNO)))		[ΠΑΡΑΣΤΑΤΙΚΟ],
	'0'														[ΑΞΙΑ_ΚΕΠΥΟ_ΥΠΟΧΡΕΟΥ],
	'0'														[ΦΠΑ_ΚΕΠΥΟ],
	AC.CodeLog												[ΛΟΓΑΡΙΑΣΜΟΣ],
	'1'														[(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	
	R.SUMPOSO												[ΑΞΙΑ],
	LTRIM(RTRIM(R.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(R.DOCNO)))	[ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ],
	R.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ],
	''														[ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ],
	CASE R.ifDelete
		WHEN 1 THEN 1
		ELSE ''
	END AS													[ΑΚΥΡΩΜΕΝΟ],
	''														[Πεδίο_Ομαδοποίησης_Ακύρωσης]

from RECEIPTS R
JOIN ACCOUNTS AC ON AC.id=R.IDCUSTOMER
JOIN KINDPARASTATIKON KP ON KP.ID=R.IDKINDPARAST

UNION

select 

	kp.id													[KID],
	AC.ID													[ACID],
	'02'+CONVERT(NVARCHAR(20),P.ID)							[ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)],
	'ΤΑΜ'													[ΕΙΔΟΣ_ΚΙΝΗΣΗΣ],
	'0'														[ΚΕΠΥΟ],
	AC.CATKEPYO												[ΥΠΟΧΡΕΩΣΗ_ΥΠΟΒΟΛΗΣ],
	AC.Code													[ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	ac.AFM													[ΑΦΜ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	P.DATEPRINT												[ΗΜΕΡΟΜΗΝΙΑ],
	P.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ],
	LTRIM(RTRIM(P.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(P.DOCNO)))		[ΠΑΡΑΣΤΑΤΙΚΟ],
	'0'														[ΑΞΙΑ_ΚΕΠΥΟ_ΥΠΟΧΡΕΟΥ],
	'0'														[ΦΠΑ_ΚΕΠΥΟ],
	KP.CodeLog												[ΛΟΓΑΡΙΑΣΜΟΣ],
	'1'														[(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	
	P.SUMPOSO												[ΑΞΙΑ],
	LTRIM(RTRIM(P.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(P.DOCNO)))	[ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ],
	P.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ],
	''														[ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ],
	CASE P.ifDelete
		WHEN 1 THEN 1
		ELSE ''
	END AS													[ΑΚΥΡΩΜΕΝΟ],
	''														[Πεδίο_Ομαδοποίησης_Ακύρωσης]

from PAYMENTS P
JOIN ACCOUNTS AC ON AC.id=P.IDCUSTOMER
JOIN KINDPARASTATIKON KP ON KP.ID=P.IDKINDPARAST

--WHERE AC.id=66764

UNION

select 

	kp.id													[KID],
	AC.ID													[ACID],
	'02'+CONVERT(NVARCHAR(20),P.ID)							[ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)],
	'ΤΑΜ'													[ΕΙΔΟΣ_ΚΙΝΗΣΗΣ],
	'0'														[ΚΕΠΥΟ],
	AC.CATKEPYO												[ΥΠΟΧΡΕΩΣΗ_ΥΠΟΒΟΛΗΣ],
	AC.Code													[ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	ac.AFM													[ΑΦΜ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	P.DATEPRINT												[ΗΜΕΡΟΜΗΝΙΑ],
	P.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ],
	LTRIM(RTRIM(P.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(P.DOCNO)))		[ΠΑΡΑΣΤΑΤΙΚΟ],
	'0'														[ΑΞΙΑ_ΚΕΠΥΟ_ΥΠΟΧΡΕΟΥ],
	'0'														[ΦΠΑ_ΚΕΠΥΟ],
	AC.CodeLog												[ΛΟΓΑΡΙΑΣΜΟΣ],
	'0'														[(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	
	P.SUMPOSO												[ΑΞΙΑ],
	LTRIM(RTRIM(P.KINDPARASTDESCR))+'  '+CONVERT(NVARCHAR(20),LTRIM(RTRIM(P.DOCNO)))	[ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ],
	P.AITIOLOGIA											[ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ],
	''														[ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ],
	CASE P.ifDelete
		WHEN 1 THEN 1
		ELSE ''
	END AS													[ΑΚΥΡΩΜΕΝΟ],
	''														[Πεδίο_Ομαδοποίησης_Ακύρωσης]

from PAYMENTS P
JOIN ACCOUNTS AC ON AC.id=P.IDCUSTOMER
JOIN KINDPARASTATIKON KP ON KP.ID=P.IDKINDPARAST


--WHERE AC.id=66764

