---NEW SCRIPT 1990
IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[LOGISTIKI_EPSILONNET_ESODA]'))
DROP VIEW [dbo].[LOGISTIKI_EPSILONNET_ESODA]
GO


CREATE view [dbo].[LOGISTIKI_EPSILONNET_ESODA] 
as 
select
	f.IDPARAST,
	f.IDENTOLEA, 
	CONVERT(DATE, f.DATEPRINT) [Ημερομηνία],
	f.PARASTATIKO [Όνομα Παραστατικού],
	f.SEIRA [Σειρά],
	f.NOPARAST [Αριθμός],
	f.IDAPOSTOLEA [Κωδικός Αποστολέα],
	f.APOSTOLEASDESCR [Επωνυμία Αποστολέα],
	ap.AddressStr [Διεύθυνση Αποστολέα],
	ap.DOY [ΔΟΥ Αποστολέα],
	convert(varchar(15),ap.AFM) [ΑΦΜ Αποστολέα],
	ap.Tel	[Τηλ Αποστολέα],
	f.IDPARALIPTI [Κωδικός Παραλήπτη],
	f.PARALISPTISDESCR [Επωνυμία Παραλήπτη],
	par.AddressStr [Διεύθυνση Παραλήπτη],
	par.DOY [ΔΟΥ Παραλήπτη],
	convert(varchar(15),par.AFM) [ΑΦΜ Παραλήπτη],
	par.Tel [Τηλ Παραλήπτη],
	f.IDENTOLEA [Κωδικός Εντολέα],
	f.ENTOLEASDESCR [Επωνυμία Εντολέα],
	ent.AddressStr [Διεύθυνση Εντολέα],
	ent.DOY [ΔΟΥ Εντολέα],
	convert(varchar(15),ent.AFM) [ΑΦΜ Εντολέα],
	ent.Tel [Τηλ Εντολέα],
	f.OXIMA [Αυτοκίνητο],
	f.DRIVERDESCR [Επωνυμία Οδηγού],
	replace(f.POSO,'.',',') [ΚΟΜΙΣΤΡΑ],
	null [ΛΟΙΠΑ],
	null [ΕΡΓΑΤΙΚΑ],
	replace(f.TAXIS,'.',',') [ΦΠΑ],
	replace(f.SUMPOSO,'.',',') [ΣΥΝΟΛΟ],
	case (1*ISNULL(F.IFXRAPOST,0)+2*ISNULL(F.IFXRENTOL,0)+4*ISNULL(F.IFXRPARAL,0)+8*ISNULL(IFXRTRITOU,0))
		when 1 then 'Αποστολέας'
		when 2 then 'Εντολέας'
		when 4 then 'Παραλήπτης'
		when 8 then 'Τρίτος Συναλ.'
	else 'Αγνωστο'
	end	as [Χρέωση Σε],
	f.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	f.COMMENTS [Σχόλια],
	case f.ifDelete
		when 0 then 'ΟΧΙ'
	else 'ΝΑΙ'
	end as [Έχει Ακυρωθεί],
	null [Έχει Μετασχηματιστεί],
	null [Μετασχηματίζει],
	sumgf.tEMAXIA [Δέματα],
	sumgf.weight [Βάρος],
	convert(varchar(15),xr.AFM ) [ΑΦΜ(που χρεώνεται)]
	from FORTOTIKES f 
join ACCOUNTS ap on ap.id=f.IDAPOSTOLEA
join ACCOUNTS par on par.id= f.IDPARALIPTI
join ACCOUNTS ent on ent.id= f.IDENTOLEA
join 
(
 select 
	SUM(TEMAXIA) [tEMAXIA],
	replace(SUM(BAROS),'.',',') [weight],
	IDVOH
 from GRAMMESFORTTIKIS gf
group by IDVOH) sumgf on sumgf.IDVOH=f.ID
join ACCOUNTS xr on xr.id=f.IDXREOUMENOU
join KINDPARASTATIKON kp on kp.ID=f.IDPARAST 
where  kp.IF_ENIMEROSIKARTELA=1 and f.IF_FROM_ANTAP=0
union
select
	v.IDCUSTOMER [IDENTOLEA],
	v.IDPARAST [IDPARAST],
	CONVERT(Date, v.dateprint) [Ημερομηνία],
	v.PARASTATIKO [Όνομα Παραστατικού],
	v.SEIRA [Σειρά],
	v.NOPARAST [Αριθμός Παραστ],
	null [Κωδικός Αποστολέα],
	null [Επωνυμία Αποστολέα],
	null [Διεύθυνση Αποστολέα],
	null [ΔΟΥ Αποστολέα],
	null [ΑΦΜ Αποστολέα],
	null [Τηλ Αποστολέα],
	null [Κωδικός Παραλήπτη],
	null [Επωνυμία Παραλήπτη],
	null [Διεύθυνση Παραλήπτη],
	null [ΔΟΥ Παραλήπτη],
	null [ΑΦΜ Παραλήπτη],
	null [Τηλ Παραλήπτη],
	v.IDCUSTOMER [Κωδικός Εντολέα],
	v.CustDescr [Επωνυμία Εντολέα],
	ent.AddressStr [Διεύθυνση Εντολέα],
	ent.DOY [ΔΟΥ Εντολέα],
	convert(varchar(15),ent.AFM) [ΑΦΜ Εντολέα],
	ent.Tel [Τηλ Εντολέα],
	v.OXIMA [Αυτοκίνητο],
	v.DRIVER [Επωνυμία Οδηγού],
	replace (v.POSO ,'.',',') [ΚΟΜΙΣΤΡΑ],
	null [ΛΟΙΠΑ],
	null [ΕΡΓΑΤΙΚΑ],
	replace (v.TAXIS,'.',',') [ΦΠΑ],
	replace (v.SUMPOSO,'.',',') [ΣΥΝΟΛΟ],
	'Εντολέας' [Χρέωση Σε],
	v.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	v.COMMENTS [Σχόλια],
	case V.ifdelete
		when 0 then 'ΟΧΙ'
	else 'ΝΑΙ'
	end as [Έχει Ακυρωθεί],
	null [Έχει Μετασχηματιστεί],
	null [Μετασχηματίζει],
	null [Δέματα],
	null [Βάρος],
	convert(varchar(15),ent.AFM) [ΑΦΜ(που χρεώνεται)]from VOH v
join ACCOUNTS ent on ent.id=v.IDCUSTOMER
join KINDPARASTATIKON kp on kp.ID=v.IDPARAST
where kp.IF_ENIMEROSIKARTELA=1 
union
select
	e.IDPROM [IDENTOLEA],
	e.IDPARAST [IDPARAST],  
	CONVERT(Date, e.DATEPRINT) [Ημερομηνία],
	e.PARASTATIKO [Όνομα Παραστατικού],
	e.SEIRA [Σειρά],
	e.NOPARAST [Αριθμός Παραστ],
	null [Κωδικός Αποστολέα],
	null [Επωνυμία Αποστολέα],
	null [Διεύθυνση Αποστολέα],
	null [ΔΟΥ Αποστολέα],
	null [ΑΦΜ Αποστολέα],
	null [Τηλ Αποστολέα],
	null [Κωδικός Παραλήπτη],
	null [Επωνυμία Παραλήπτη],
	null [Διεύθυνση Παραλήπτη],
	null [ΔΟΥ Παραλήπτη],
	null [ΑΦΜ Παραλήπτη],
	null [Τηλ Παραλήπτη],
	e.IDPROM [Κωδικός Εντολέα],
	e.EPON [Επωνυμία Εντολέα],
	ac.AddressStr [Διεύθυνση Εντολέα],
	ac.DOY [ΔΟΥ Εντολέα],
	convert(varchar(15),ac.AFM) [ΑΦΜ Εντολέα],
	ac.Tel [Τηλ Εντολέα],
	e.OXIMA [Αυτοκίνητο],
	e.DRIVERDESCR [Επωνυμία Οδηγού],
	replace(e.POSO,'.',',') [ΚΟΜΙΣΤΡΑ],
	null [ΛΟΙΠΑ],
	null [ΕΡΓΑΤΙΚΑ],
	replace(e.TAXIS,'.',',') [ΦΠΑ],
	replace(e.SUMPOSO,'.',',') [ΣΥΝΟΛΟ],
	'Εντολέας' [Χρέωση Σε],
	e.KINDPAYMENTDESCR [Τρόπος Πληρωμής],
	e.COMMENTS [Σχόλια],
	case e.ifDelete
		when 0 then 'ΟΧΙ'
	else 'ΝΑΙ'
	end as [Έχει Ακυρωθεί],
	null [Έχει Μετασχηματιστεί],
	null [Μετασχηματίζει],
	null [Δέματα],
	null [Βάρος],
	convert(varchar(15),e.afm) [ΑΦΜ(που χρεώνεται)]from ESODA e
join ACCOUNTS ac on ac.id=e.IDPROM
join KINDPARASTATIKON kp on kp.ID=e.IDPARAST
where kp.IF_ENIMEROSIKARTELA=1 

GO


---END SCRIPT 1990
