---NEW SCRIPT 1991
IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[LOGISTIKI_EPSILONNET_EXODA_B_CATEGORY]'))
DROP VIEW [dbo].[LOGISTIKI_EPSILONNET_EXODA_B_CATEGORY]
GO


CREATE view [dbo].[LOGISTIKI_EPSILONNET_EXODA_B_CATEGORY]
AS
select
	ex.ID,
	'700'+CAST(ex.id as varchar)  [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'1' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else '90000000'+emp.id 
	end as [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else emp.id 
	end as ACID,
	CAST(ex.dateprint as date)[DATEPRINT],
	CONVERT (varchar, ex.dateprint, 103) [ΗΜΕΡΟΜΗΝΙΑ],
	case 
		when ISNULL(k.IfMisthodosia,0)=0 then a.Eponimia
		else emp.Eponimia
	end as [ΑΙΤΙΟΛΟΓΙΑ],
	rtrim(ltrim(ex.PARASTATIKO))+'  '  +'#'+ rtrim(ltrim(isnull(ex.seira,'')))+ ' ' +rtrim(ltrim(ex.noparast)) [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then ex.POSO
		else 0
	end as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then ex.TAXIS
		else 0
	end as [Αξία ΚΕΠΥΟ Φ.Π.Α.],
	isnull(k.CodeLog,'') [ΛΟΓΑΡΙΑΣΜΟΣ],
	ex.POSO [ΚΑΘΑΡΗ ΑΞΙΑ],
	ex.TAXIS [ΑΞΙΑ ΦΠΑ],
	case 
		when ISNULL(k.IfMisthodosia,0)=0 then '50-00-00-000'
		else '53-03-00-0000'
	end as  [ΓΕΝΙΚΟΣ ΛΟΓΑΡΙΑΣΜΟΣ],
	null [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	null [Λοιπές Δαπάνες],
	null [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	ex.ifDelete [Ακυρωμένο],
	null [Πεδίο Ομαδοποίησης Ακύρωσης]

from EXODA ex
left join ACCOUNTS a on a.id=ex.IDPROM
left join EMPLOYEE emp on emp.id=ex.IDPROM
join kindparastatikon k on k.id=ex.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (0,6)
union
select
	vex.ID,
	'800'+CAST(vex.id as varchar)  [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'1' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	a.id [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	a.id ACID,
	CAST(vex.dateprint as date)[DATEPRINT],
	CONVERT (varchar, vex.dateprint, 103) [ΗΜΕΡΟΜΗΝΙΑ],
	A.Eponimia [ΑΙΤΙΟΛΟΓΙΑ],
	rtrim(ltrim(vex.PARASTATIKO))+'  '  +'#'+ rtrim(ltrim(isnull(vex.seira,'')))+ ' ' +rtrim(ltrim(vex.noparast)) [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then vex.POSO
		else 0
	end as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then vex.TAXIS
		else 0
	end as [Αξία ΚΕΠΥΟ Φ.Π.Α.],
	isnull(k.CodeLog,'') [ΛΟΓΑΡΙΑΣΜΟΣ],
	vex.POSO [ΚΑΘΑΡΗ ΑΞΙΑ],
	vex.TAXIS [ΑΞΙΑ ΦΠΑ],
	case 
		when ISNULL(k.IfMisthodosia,0)=0 then '50-00-00-000'
		else '53-03-00-0000'
	end as  [ΓΕΝΙΚΟΣ ΛΟΓΑΡΙΑΣΜΟΣ], 
	null [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	null [Λοιπές Δαπάνες],
	null [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	vex.ifDelete [Ακυρωμένο],
	null [Πεδίο Ομαδοποίησης Ακύρωσης]

from VOH vex
join ACCOUNTS a on a.id=vex.IDCUSTOMER
join kindparastatikon k on k.id=vex.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (0,6)




GO



---END SCRIPT 1992
