---NEW SCRIPT 1993
declare @id int
set @id = (select max(id)+1 from IRS)
if not exists ( select description from irs where description like '%ΚΕΦΟ%')
BEGIN
insert into irs (IRSID,Description,id,SECONDID,ifDelete)
values (1190,'ΚΕΦΟΔΕ ΑΤΤΙΚΗΣ',@id,null,0)
END
ELSE 
BEGIN 
UPDATE IRS SET IRSID=1190 WHERE Description LIKE '%ΚΕΦΟ%'
END

GO

update KINDPARASTATIKON set REPORT_PATH_FOR_EMAILS='C:\Program Files (x86)\PRAKTOREIA\TPY_FOR_ALL.rpt'
