ALTER VIEW [dbo].[VOH_VIEW]
AS

WITH GRAMMES AS 
	(
		SELECT 
			IDVOH,
			ISNULL(Min(dbo.grammesvoh.timda),'')                 AS TIMDA,
            Isnull(Sum(dbo.grammesvoh.temaxia), 0)               AS TEMAXIA,
            Isnull(Sum(dbo.grammesvoh.baros), 0)                 AS BAROS,
            Isnull(Sum(dbo.grammesvoh.kybika), 0)                AS KYBIKA,
            ISNULL(MIN(PERIEXOMENO),'')							 AS PERIEXOMENO,
            ISNULL(SUM(SUMPOSO),0)								 AS AXIA
		
		FROM GRAMMESVOH
		GROUP BY IDVOH
	),
XREOSIS AS	(
		SELECT 
			IDVOH,
			SUM(SUMPOSO) AS SUPOSO
			
		FROM XREOSISANADELTIO
		WHERE IF_TO_VOH=1
			
		GROUP BY IDVOH
		)

SELECT

	V.ID,
	V.DATEPRINT,
	KP.Code,
	V.PARASTATIKO,
	V.SEIRA,
	CAST(V.NOPARAST AS NVARCHAR(15)) [NOPARAST],
	V.CustDescr,
	V.EPAGELMA,
	V.AFM,
	V.CITY,
	V.TEL,
	V.MOBILE,
	V.POSO,
	V.TAXIS,
	V.SUMPOSO,
	V.KINDPAYMENTDESCR,
	V.EXT_BARCODE,
	V.OXIMA,
	V.OMADPROORISMOS,
	V.SXETIKAPARASTATIKA,
	CASE V.IFXRENTOL * 1 + V.IFXRAPOST * 2 + V.IFXRTRITOU * 4 + V.IFXRPARAL * 8
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		ELSE 'ΑΓΝΩΣΤΟ'
	END AS XREOYMENOS,
	  V.noparastdeltioudianomis,
      V.noparastdeltiouapostolis,
      GRAMMES.TIMDA,
      GRAMMES.TEMAXIA,
      GRAMMES.BAROS,
      GRAMMES.KYBIKA,
      CASE V.IFPREPAY
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIPROPLIROMENES,
	  CASE V.IFOFEILOMENI
		WHEN 1 THEN XREOSIS.SUPOSO 
		ELSE 0
	  END AS XREOSIOFEILOMENES,
	  GRAMMES.PERIEXOMENO,
	  V.perioxifortosis,
      V.perioxiparadosis,
      V.comments,
      V.sumantik,
      V.praktoreiodescr,
      V.status,
      V.dateparad,
      V.idpraktoreio,
      CASE V.IFANTIKCASH
        WHEN 0 THEN 0
        ELSE V.ANTIKCASH
      END AS ANTIKCASH,
      CASE V.IFANTIKEPIT
        WHEN 0 THEN 0
        ELSE V.ANTIKEPIT
      END AS ANTIKEPIT,
      CASE V.IFANTIKSYNAL
        WHEN 0 THEN 0
        ELSE V.ANTIKSYNAL
      END AS ANTIKSYNAL,
      CASE V.IFANTIKOTHER
        WHEN 0 THEN 0
        ELSE V.ANTIKOTHER
      END AS ANTIKOTHER,
      CASE V.IFCANCELANTIK
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFCANCELANTIK,
      V.commentsantik,
      V.dateparadosi,
      V.comments2,
      hv.KOMISTRA,
      hv.XREOSISTRITON,
      hv.DIKAIOMAFORTOTIKIS,
      hv.OTHERXREOSIS,
      CASE V.ifprepay
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFPREPAY,
      CASE V.ifofeilomeni
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFOFEILOMENI,
      GRAMMES.AXIA,
      CASE V.IFXRENTOL
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRENTOL,
      V.idkindpayment,
      CASE V.IFXRAPOST
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRAPOST,
      CASE V.IFXRPARAL
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRPARAL,
      CASE V.IFXRTRITOU
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRTRITOU,
      V.ifantikcash,
      V.ifantikepit,
      V.ifantiksynal,
      V.ifantikother,
      V.ifdelete,
      V.ifcancel,
      V.datecancel,
      V.ifparadosi,
      V.aitiologiaparastatikou,
      V.datefortosis,
      V.ifepistrofi,
      V.dateepistrofis,
      V.aitiologiaepistrofis,
      V.commentsepistrofis,
      V.ifcash,
      V.ifpistosi,
      V.statusdescr,
      V.ypaitios,
      V.ifepanadromologisi,
      V.ifepanekdosi,
      V.ifokepanadromologisi,
      V.noparastantik,
      V.commentsakirosis,
      V.ifeisprantik,
      V.ifparadosiantik,
      V.ifparalaviantik,
      V.commentsparadantik,
      V.commantsparalantik,
      V.commentseisprantik,
      V.dateparadantik,
      V.dateparalantik,
      V.dateeisprantik,
      V.eispraxasantik,
      V.noparparadantik,
      V.noparasteisprantik,
      V.noparparalantik,
      V.dateparal,
      V.commentsparad,
      V.commantsparal,
      V.ifexoflisi,
      V.timeparalfrom,
      V.timeparalto,
      V.timeparadfrom,
      V.timeparadto,
      V.datecancelantik,
      V.idparast,
      V.taxispercent,
      V.anamexodo,
      V.id                                           AS IDVOH,
      V.afmxreoumenou,
      hv.ASFALISTRA,
      hv.TAXIS										 AS TAXISXREOSEON,
      hv.SUMPOSOXRVOH,
      hv.KATHARO,
      V.thetime,
      V.identolea                                    AS CUSTOMERID,
      V.entoleasdescr                                AS CUSTOMERDESCR,
      V.idapostolea                                  AS IDSYNAL,
      V.apostoleasdescr                              AS SYNALDESCR,
      V.idcustomer,
      V.doy,
      V.addressstreet,
      V.addressno,
      V.pref,
      V.afmapostolea,
      APOST.epagelma                                 AS SYNALEPAGELMA,
      APOST.addressstr                               AS SYNALADDRSTR,
      APOST.addressno                                AS SYNALADDRNO,
      APOST.addresstk                                AS SYNALADDRTK,
      APOST.addresscity                              AS SYNALCITY,
      APOST.addresscountry                           AS SYNALADDRCOUNTRY,
      APOST.tel                                      AS SYNALTEL,
      APOST.doy										 AS SYNALDOY,
      APOST.afm                                      AS SYNALAFM,
      APOST.mobile				                     AS SYNALMOBILE,
      ENTOL.Code	                                 AS CodeCust,
      ENTOL.addresstk			                     AS CUSTADDRTK,
      ENTOL.addressno                                AS CUSTADDRNO,
      ENTOL.addressstr                               AS CUSTADDRSTR,
      ENTOL.addresscity                              AS CUSTADDRCITY,
      ENTOL.afm                                      AS CUSTAFM,
      ENTOL.doy                                      AS CUSTDOY,
      
      CAST(ENTOL.KINDPAYMENTDESCR AS NVARCHAR(50))+ ' ' + CONVERT(NVARCHAR(20),ENTOL.PayAfter_Days)+ ' ' + 'Ημερών'  AS PAYAFTERDAYS,
      ENTOL.PayAfter_Days							AS PAYMENT_DAYS,
      
      V.idxrhshs,
      V.idcompany,
      V.idypokatastima,
      V.usermod,
      V.datemod,
      V.usercreate,
      V.datecreate,
      V.discountpercent,
      V.discount,
      V.arxikoposo,
      V.skoposdiakinisis,
      V.idskoposdiakinisis,
      V.afmentolea,
      V.afmparalipti,
      V.afmtritou,
      V.afmantapokriti,
      V.country,
      V.driver,
      V.idlistas,
      V.ifisorder,
      V.idorder,
      V.codeentolea,
      V.codeapostolea,
      V.codeparalipti,
      V.seiraorder,
      V.dateprintorder,
      V.orderdetails,
      V.if_close,
      V.noorder,
      V.no_ext_order,
      V.no_ext_order_ik,
      YPOK.eponimia                                  AS YPOKATASTHMA,
      YPOK.addressstr                                AS ADDRESS_YPOKATASTHMA,
      YPOK.addresstk                                 AS TK_YPOKATASTHMA,
      YPOK.addresscity                               AS CITY_YPOKATASTHMA,
      YPOK.barcode_prefix                            AS BARCODEPREFIX_YPOKAT,
      YPOK.email                                     AS EMAIL_YPOKATASTHMA,
      YPOK.Tel										 AS YPOKATASHMA_TELEPHONE,
      YPOK.Tel2										 AS YPOKATASTHMA_TELEPHONE_2,
      YPOK.Fax										 AS YPOKATASTHMA_FAX,
      YPOK.MOBILE									 AS YPOKATASTHMA_MOBILE,
      YPOK.AddressCountry							 AS YPOKATASTHMA_COUNTRY,
      YPOK.AddressNo								 AS YPOKATASTHMA_ADDRESS_NO,
      YPOK.AddressPref								 AS YPOKATASTHMA_NOMOS,
      BANKS_A.FSBANKS_DESCR							 AS YPOKATASTHMA_BANK_A,
      YPOK.IBANA									 AS YPOKATASTHMA_IBAN_A,
      BANKS_B.FSBANKS_DESCR							 AS YPOKATASTHMA_BANK_B,
      YPOK.IBANB									 AS YPOKATASTHMA_IBAN_B,
      BANKS_C.FSBANKS_DESCR							 AS YPOKATASTHMA_BANK_C,
      YPOK.IBANC									 AS YPOKATASTHMA_IBAN_C,
      BANKS_D.FSBANKS_DESCR							 AS YPOKATASTHMA_BANK_D,
      YPOK.IBAND									 AS YPOKATASTHMA_IBAN_D,
      YPOK.YPOKATASTHMA_IMAGE						 AS YPOKATASTHMA_IMAGE,             					
      COMP.Eponimia									 AS COMPANY_NAME,
      COMP.Epagelma									 AS COMPANY_EPAGGELMA,
      COMP.AFM										 AS COMPANY_AFM,
      COMP.DOY										 AS COMPANY_DOY,
      COMP.TEL										 AS COMPANY_TELEPHONE,
      COMP.Tel2										 AS COMPANY_TELEPHONE_2,
      COMP.Fax										 AS COMPANY_FAX,
      COMP.Mobile									 AS COMPANY_MOBILE,
      COMP.EMAIL									 AS COMPANY_EMAIL,
      COMP.AddressCountry							 AS COMPANY_COUNTRY,
      COMP.AddressZone								 AS COMPANY_ZONE,
      COMP.AddressPref								 AS COMPANY_NOMOS,
      COMP.AddressCity								 AS COMPANY_CITY,
      COMP.AddressStr								 AS COMPANY_ADDRESS,
      COMP.AddressNo								 AS COMPANY_ADDRESS_NO,
      COMP.AddressTK								 AS COMPANY_TK,
      COMP.WEBSITE									 AS COMPANY_WEBSITE,
      COMP.GEMINumber								 AS COMPANY_GEMI,
      CUR.DESCR										 AS CURRENCY_DESCR,
	  CUR.SYMBOL									 AS CURRENCY_SYMBOL,
	  DATEADD(DD,ENTOL.PayAfter_Days,V.DATEPRINT)	 AS EXOFLISI_MEXRI,
	  QRURLPERVOHINVOICE.QrUrl	   					 AS QR_BINARY,										
	  kp.PRINTLABEL,	
      dbo.Getvoheafdss(V.id, 1)                      AS EAFDSS

FROM VOH V
LEFT JOIN KINDPARASTATIKON KP ON KP.ID=V.IDPARAST
LEFT JOIN GRAMMES ON GRAMMES.IDVOH=V.ID
LEFT JOIN XREOSIS ON XREOSIS.IDVOH=V.ID
LEFT JOIN HEADERVOH hv on hv.IDVOH=V.ID
LEFT JOIN ACCOUNTS APOST ON APOST.ID=V.IDAPOSTOLEA
LEFT JOIN ACCOUNTS ENTOL ON ENTOL.id=V.IDCUSTOMER
LEFT JOIN COMPANIES YPOK ON YPOK.id=V.IDYPOKATASTIMA
LEFT JOIN COMPANIES COMP ON COMP.ID=V.IDCOMPANY
LEFT JOIN Banks BANKS_A ON BANKS_A.FSBANKS_ID=YPOK.IDBANKA
LEFT JOIN Banks BANKS_B ON BANKS_B.FSBANKS_ID=YPOK.IDBANKB
LEFT JOIN Banks BANKS_C ON BANKS_C.FSBANKS_ID=YPOK.IDBANKC
LEFT JOIN Banks BANKS_D ON BANKS_D.FSBANKS_ID=YPOK.IDBANKD
LEFT JOIN CURRENCY CUR ON CUR.ID=kp.IDCURRENCY
LEFT JOIN QRURLPERVOHINVOICE ON QRURLPERVOHINVOICE.INVOICEID =  V.ID

GO


