ALTER VIEW [dbo].[ISOZYGIO_TAMEIO_PAYMENTS_RECEIPTS]
AS

SELECT '105-' + Cast(payments.id AS NVARCHAR(20)) AS ID,
       payments.seira,
       docno                                      AS NOPARAST,
       kindparastdescr,
       CONVERT(VARCHAR(8), dateprint, 108)        AS THETIME,
       CONVERT(VARCHAR(10), dateprint, 103)       AS STRDATEPRINT,
       dateprint,
       customerdescr,
       sumposo * KINDPARASTATIKON.KindYpologismou    AS SUMPOSO,
       aitiologia,
       kindpaymentdescr,
       eispraxas,
       idvoh,
       idcustomer,
       idkindpayment,
       idkindparast,
       payments.if_to_fortotiki,
       payments.if_to_voh,
       payments.if_to_exoda,
       0                                          AS IF_TO_ESODA,
       payments.ifdelete,
       idxrhshs,
       payments.idcompany,
       payments.idypokatastima,
       payments.usercreate,
       payments.usermod
FROM   dbo.payments WITH (nolock)
       INNER JOIN kindparastatikon ON payments.idkindparast = kindparastatikon.id
                  AND kindparastatikon.ifenimerositameio = 1
UNION
SELECT '106-' + Cast(receipts.id AS NVARCHAR(20))AS ID,
       receipts.seira,
       docno                                     AS NOPARAST,
       kindparastdescr,
       CONVERT(VARCHAR(8), dateprint, 108)       AS THETIME,
       CONVERT(VARCHAR(10), dateprint, 103)      AS STRDATEPRINT,
       dateprint,
       customerdescr,
       sumposo * KINDPARASTATIKON.KindYpologismou as SUMPOSO,
       aitiologia,
       kindpaymentdescr,
       eispraxas,
       idvoh,
       idcustomer,
       idkindpayment,
       idkindparast,
       receipts.if_to_fortotiki,
       receipts.if_to_voh,
       0                                         AS IF_TO_EXODA,
       receipts.if_to_esoda,
       receipts.ifdelete,
       idxrhshs,
       receipts.idcompany,
       receipts.idypokatastima,
       receipts.usercreate,
       receipts.usermod
FROM   dbo.receipts WITH (nolock)
       INNER JOIN kindparastatikon ON receipts.idkindparast = kindparastatikon.id
                  AND kindparastatikon.ifenimerositameio = 1 


GO


---END SCRIPT 2005
