---NEW SCRIPT 2006

exec sp_rename 'ISOZYGIO_PAYMENTS_RECEIPTS_SUM_PERDAY','ISOZYGIO_PAYMENTS_RECEIPTS_SUM_PERDAY_old'
go

create VIEW [dbo].[ISOZYGIO_PAYMENTS_RECEIPTS_SUM_PERDAY] 
AS 

SELECT
	'105-' + CAST(R.ID AS NVARCHAR(20))				AS ID, 
	R.IDVOH, 
	CONVERT(VARCHAR(10), R.DATEPRINT, 103)			AS DATEPRINT,
	R.IF_TO_FORTOTIKI, 
	R.IF_TO_VOH, 
	0												AS IF_TO_EXODA, 
	R.IF_TO_ESODA, 
	R.IDKINDPARAST,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0
		THEN SUM(R.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS METRITA,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=1 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0
		THEN SUM(R.SUMPOSO*KDP.KindYpologismou) ELSE 0
	END AS EMVASMA,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=1 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0 
		THEN SUM(R.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS EPITAGI,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=1 and IF_KARTA=0 
		THEN SUM(R.SUMPOSO*KDP.KindYpologismou) ELSE 0
	END AS SYNALAGMATIKI,
	CASE 
		WHEN ((KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=1)
		OR (KD.DESCR LIKE '%Αντικ%')) 
		THEN SUM(R.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS ALLO,

  R.ifDelete, 
  R.IDXRHSHS, 
  R.IDCOMPANY, 
  R.IDYPOKATASTIMA, 
  R.UserCreate, 
  R.UserMod
		

FROM RECEIPTS R
JOIN KINDOFPAYMENTS KD ON KD.ID=R.IDKINDPAYMENT AND KD.KINDOFCALCULATION=1
JOIN KINDPARASTATIKON KDP ON KDP.ID=R.IDKINDPARAST

GROUP BY  R.ID, R.IDVOH, R.DATEPRINT, R.IDKINDPAYMENT, R.KINDPAYMENTDESCR,  R.ifDelete, R.IDXRHSHS, R.IDCOMPANY, 
R.IF_TO_FORTOTIKI, R.IF_TO_VOH, R.IF_TO_ESODA, R.IDKINDPARAST,
 R.IDYPOKATASTIMA, R.UserCreate, R.UserMod,
 KD.IF_CASH,KD.IF_EMVASMA,KD.IF_EPITAGI,KD.IF_SYNALAGMATIKI,KD.IF_KARTA,KD.DESCR

 UNION

 
 SELECT
	'106-' + CAST(P.ID AS NVARCHAR(20))				AS ID, 
	P.IDVOH, 
	CONVERT(VARCHAR(10), P.DATEPRINT, 103)			AS DATEPRINT,
	P.IF_TO_FORTOTIKI, 
	P.IF_TO_VOH, 
	P.IF_TO_EXODA									AS IF_TO_EXODA, 
	0												AS IF_TO_ESODA, 
	P.IDKINDPARAST,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0
		THEN SUM(P.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS METRITA,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=1 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0
		THEN SUM(P.SUMPOSO*KDP.KindYpologismou) ELSE 0
	END AS EMVASMA,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=1 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=0 
		THEN SUM(P.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS EPITAGI,
	CASE 
		WHEN KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=1 and IF_KARTA=0 
		THEN SUM(P.SUMPOSO*KDP.KindYpologismou) ELSE 0
	END AS SYNALAGMATIKI,
	CASE 
		WHEN ((KD.IF_CASH=1 and KD.IF_EMVASMA=0 and KD.IF_EPITAGI=0 and KD.IF_SYNALAGMATIKI=0 and IF_KARTA=1)
		OR (KD.DESCR LIKE '%Αντικ%')) 
		THEN SUM(P.SUMPOSO*KDP.KindYpologismou) ELSE 0 
	END AS ALLO,

  P.ifDelete, 
  P.IDXRHSHS, 
  P.IDCOMPANY, 
  P.IDYPOKATASTIMA, 
  P.UserCreate, 
  P.UserMod
		

FROM PAYMENTS P
JOIN KINDOFPAYMENTS KD ON KD.ID=P.IDKINDPAYMENT AND KD.KINDOFCALCULATION=1
JOIN KINDPARASTATIKON KDP ON KDP.ID=P.IDKINDPARAST

GROUP BY  P.ID, P.IDVOH, P.DATEPRINT, P.IDKINDPAYMENT, P.KINDPAYMENTDESCR,  P.ifDelete, P.IDXRHSHS, P.IDCOMPANY, 
P.IF_TO_FORTOTIKI, P.IF_TO_VOH, P.IF_TO_EXODA, P.IDKINDPARAST,
 P.IDYPOKATASTIMA, P.UserCreate, P.UserMod,
 KD.IF_CASH,KD.IF_EMVASMA,KD.IF_EPITAGI,KD.IF_SYNALAGMATIKI,KD.IF_KARTA,KD.DESCR



go

---END SCRIPT 2006
