create view LOGISTIKI_EPSILON_FORTOTIKES_VOH_C_CAT AS 
select
	f.id											AS idvoh,
	pel.id											AS ACCOUNT_ID,
	f.DATEPRINT,
	0 IF_TO_VOH,
	1 IF_TO_FORTOTIKI,
	('100'+ convert(nvarchar(10),f.id))				AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΕΣ - ΠΩΛ'										AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	pel.AFM											AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)			AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO									AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Code										AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	(rtrim(ltrim(f.seira))+' ' +f.NOPARAST)			AS 'ΑΡΙΘΜΟΣ',
	pel.CodeLog										AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1												AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.SUMPOSO,0)
		when 2 then ISNULL(f.SUMPOSO,0) * -1
		else 0
	END												AS'ΑΞΙΑ',
	f.ifDelete										AS 'ΑΚΥΡΩΜΕΝΟ'
	
from fortotikes f
join accounts pel on pel.id = f.IDXREOUMENOU
join kindparastatikon kdp on kdp.id=f.idparast and kdp.IF_ENIMEROSIKARTELA=1
--WHERE f.ID=289

union all



select
	xr.IDVOH,
	pel.id											AS ACCOUNT_ID,
