	v.ifDelete										AS 'ΑΚΥΡΩΜΕΝΟ'
	
from XREOSISANADELTIO xr
join Taxis on Taxis.Pososto = xr.TAXISPERCENT and xr.IF_TO_VOH=1
join Xreoseis on Xreoseis.ID = XR.IDXREOSIS and XR.IF_TO_VOH=1
join VOH v on v.id=xr.IDVOH
join ACCOUNTS pel on pel.id=v.IDCUSTOMER
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSIKARTELA=1
--WHERE XR.IDVOH=289
group by xr.IDVOH,pel.id,v.DATEPRINT,IF_TO_FORTOTIKI, IF_TO_VOH, ('200'+convert(nvarchar(10),v.ID)),
pel.AFM,convert(nvarchar(20),v.DATEPRINT,103),v.PARASTATIKO,kdp.Code,
(rtrim(ltrim(v.seira))+' ' +v.NOPARAST),Taxis.CodeLog,kdp.if_xreosi,kdp.if_pistosi,v.ifDelete


GO

---END SCRIPT 2011
