				@KINDKINISIS,			
				@KINDENIMEROSI	,
				@IFENIMEROSITAMEIO,
				@TRANSFORMTO,
				@IF_AUTONUMBER,
				@IF_TRANSFORM,
				@AUTONUMBER_FROM,
				@IF_ZERO_ON_NEW_YEAR,
				@IF_PRINT,
				@PREPORT,
				@REPORT_PATH_FOR_EMAILS,
				@TAXISPERCENT	,
				@IF_XREOSI,
				@IfMisthodosia,
				@IfFortotiki,
				@IF_PISTOSI,
				@IfKAA,
				@IF_ENIMEROSIKARTELA,
				@IF_XREOSIKARTELA,
				@IF_PISTOSIKARTELA,
				@IFKEPXREOSI,
				@IFKEPPISTOSI,
				@IFPROFORTOTIKI,
				@IFKEPYO,
				@SEIRA,
