				--@IFPREPAY,
				@CATKEPYO,
				@CodeLog,
				@Copies,			
				@IF_EDMETAFORAS,
				@IF_EDSYNARMOL,
				@IS_CANCELLATION,
				@IF_LISTA_ASS,
				@WEBPARASTATIKO,
				@IF_ENIMEROSI_AADE,
