			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************

ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
