					  --ESODA.POSO,
					  
					case ISNULL(kindparastatikon.if_xreosi,0) * 1 + ISNULL(kindparastatikon.if_pistosi,0) * 2
						when 1 then ISNULL(ESODA.POSO,0)
						when 2 then ISNULL(ESODA.POSO,0) * -1
						else 0
					end AS POSO,

					 -- ESODA.TAXIS,
					  
