					  IDPROM AS IDPRAKTOREIO, 
                      IDPROM AS IDENTOLEA,
					  IDPROM AS IDAPOSTOLEA, 
					  IDPROM AS IDPARALIPTI, 
					  IDPROM AS IDTRITOU, 
					  IDPROM AS IDANTAPOKRITI,   
					  ACCOUNTS_1.AFM AS AFMENTOLEA, 
					  ACCOUNTS_1.AFM AS AFMAPOSTOLEA,
					  ACCOUNTS_1.AFM AS AFMPARALIPTI, 
					  ACCOUNTS_1.AFM AS AFMTRITOU,
					  ACCOUNTS_1.AFM AS AFMANTAPOKRITI,    
                      ACCOUNTS_1.Eponimia AS PRAKTOREIODESCR, 
					  ACCOUNTS_1.Eponimia AS ENTOLEASDESCR, 
					  ACCOUNTS_1.Eponimia AS APOSTOLEASDESCR, 
                      ACCOUNTS_1.Eponimia AS PARALISPTISDESCR, 
