alter VIEW [dbo].[KAA_FORT_REPORT]
AS

with grammes as (
					SELECT 
						IDVOH,
						MIN(TIMDA) AS TIMDA,
						ISNULL(SUM(TEMAXIA),0) AS TEMAXIA,
						MIN(U.UntName) AS SYSKEVASIADESCR,
						MIN(PERIEXOMENO) AS PERIEXOMENO,
						ISNULL(SUM(BAROS),0) AS BAROS,
						ISNULL(SUM(KYBIKA),0) AS KYBIKA,
						ISNULL(SUM(SUMPOSO),0) AS SUMPOSO
					FROM GRAMMESFORTTIKIS
					left JOIN Units U ON U.UntID=GRAMMESFORTTIKIS.SYSKEVASIA
					GROUP BY IDVOH
				
				),
XREOSIS AS (
				SELECT 
					IDFORT,
					--KOMISTRA,
					ISNULL(SUM(KOMISTRA),0) AS KOMISTRA,
					ISNULL(SUM(DIKAIOMAFORTOTIKIS),0) AS DIKAIOMAFORTOTIKIS,
					ISNULL(SUM(OTHERXREOSIS),0) AS OTHERXREOSIS,
					isnull(SUM(ASFALISTRA),0) as ASFALISTRA,
					ROUND(ISNULL(SUM(TAXIS),0), 2) AS TAXISXREOSEON,
					ISNULL(SUM(KATHARO),0) AS KATHARO 
				FROM HEADERFORTOTIKIS HD
				GROUP BY IDFORT
	
			),
PIVOTED AS (
					select
						IDVOH,
						[DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS],[XB],[KLOUBA],[KLOUBAKI],[L2],[40X40],[MXP],[PEP]
					from(
							select
								IDVOH,
								case 
									when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
									when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
									when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
									when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
									when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
									when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
									when SYSKEVASIADESCR like 'Χ/Β%' then 'XB'
									when SYSKEVASIADESCR like 'ΚΛΟΥΒΑ' then 'KLOUBA'
									when SYSKEVASIADESCR like 'ΚΛΟΥΒΑΚΙ%' then 'KLOUBAKI'
									when SYSKEVASIADESCR like 'L2%' then 'L2'
									when SYSKEVASIADESCR like '40X40X21%' then '40X40'
									when SYSKEVASIADESCR like 'ΜΧΡ%' then 'MXP'
									when SYSKEVASIADESCR like 'ΠΕΠ%' then 'PEP'
									
									ELSE 'KOLA'
								END AS SYSKEVASIA,
								TEMAXIA
							from GRAMMESFORTTIKIS
						) AS GF
					pivot
						(
							sum(GF.TEMAXIA)
							FOR GF.SYSKEVASIA in([DEMATA],[PALETA],[STAND],[KOLA],[ROLI],[THALAMOS]
												,[XB],[KLOUBA],[KLOUBAKI],[L2],[40X40],[MXP],[PEP])
						)AS PV
		),
parastatika_signs as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
	
					)

select
	CASE 
            WHEN f.IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' 
            ELSE CASE 
                WHEN f.IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' 
                ELSE CASE 
                    WHEN f.IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' 
                    ELSE CASE 
                        WHEN f.IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ'                        
                        ELSE 'ΑΓΝΩΣΤΟ' 
                    END 
                END 
            END 
        END AS XREOYMENOS,
        f.AFMAPOSTOLEA,
        f.APOSTOLEASDESCR,
        f.ENTOLEASDESCR,
        f.AFMPARALIPTI,
        f.PARALISPTISDESCR,
        (paral.AddressStr + ' '+paral.AddressNo) as ADDRPARADOSIS,
        paral.AddressCity as ADDRCITYPARAL,
        isnull(grammes.TEMAXIA,0) AS TEMAXIA,
        grammes.SYSKEVASIADESCR AS SYSKEVASIA,
        f.NOPARAST,
        kp.Code,
        paral.AddressCity,
        F.COMMENTS,
        ISNULL(XR.KOMISTRA,0) * ps.signs KOMISTRA,
        ISNULL(XR.DIKAIOMAFORTOTIKIS,0) * ps.signs AS DIKAIOMAFORTOTIKIS,
        ISNULL(XR.OTHERXREOSIS,0) * ps.signs AS OTHERXREOSIS,
        grammes.TIMDA,
        ISNULL(grammes.SUMPOSO,0) * ps.signs AS AXIA,
        ISNULL(grammes.BAROS,0) AS BAROS,
        ISNULL(grammes.KYBIKA,0) AS KYBIKA,
        grammes.PERIEXOMENO,
        CASE F.IFPREPAY
			WHEN 1 THEN ISNULL(F.SUMPOSO * ps.signs,0) 
			ELSE 0
		END	AS 	XREOSIPROPLIROMENES,
		CASE F.IFOFEILOMENI
			WHEN 1 THEN ISNULL(F.SUMPOSO * ps.signs,0) 
			ELSE 0
		END AS XREOSIOFEILOMENES,
		isnull(f.ANTIKCASH,0) AS ANTIKCASH,
		ISNULL(F.ANTIKEPIT,0) AS ANTIKEPIT,
		ISNULL(F.ANTIKSYNAL,0) AS ANTIKSYNAL,
		ISNULL(F.ANTIKOTHER,0) AS ANTIKOTHER,		
		ISNULL(F.SUMANTIK,0) AS SUMANTIK,
		
		CASE F.IFCASH
			WHEN 1 THEN 
				CASE F.IFOFEILOMENI 
					WHEN 1 THEN
						ISNULL(F.SUMPOSO,0) * ps.signs
					ELSE 0
				END 
				ELSE 0  
		END 
		AS XREOSIOFEILOMENESCASH,		
		(ISNULL(F.SUMPOSO , 0) + ISNULL(F.EXODATRITON, 0)) * ps.signs AS SYNOLOOLIKOFORTOTIKIS,
		KAA.IDPARAST,
        KAA.PARASTATIKO,
        KAA.SEIRA AS SEIRAKAA,
        KAA.NOPARAST AS NOPARASTKAA,
		
		KAA.NOFORT,
        KAA.POSOEXODA,
        KAA.TAXISEXODA,
        KAA.SUMPOSOEXODA,
		
        apost.AddressStr AS ADDRSTRAPOST,
        apost.AddressNo AS ADDRNOAPOST,
        apost.AddressTK AS TKAPOST,
        apost.AddressCity AS CITYAPOST,
        apost.AddressPref AS NOMOSAPOST,
        apost.Tel AS TELAPOST,
        apost.DOY AS DOYAPOST,
        
        PARAL.AddressStr AS ADDRSTRPARAL,
        PARAL.AddressNo AS ADDRNOPARAL,
        PARAL.AddressTK AS ADDRTKPARAL,
        PARAL.AddressPref AS ADDRNOMOSPARAL,
        paral.Mobile AS PARALIPTIS_MOBILE,
		
		KAA.DATEPRINT,
        KAA.OXIMA,
        KAA.DRIVER,
        ISNULL(f.EXODATRITON,0) AS XREOSISTRITON,
        tr.OLastName,
        tr.OmProorDescr,
        (ISNULL(paral.Tel,'') + ' ' + ISNULL(paral.Mobile,'')) AS TELPARALIPTI,  
        f.OMADPROORISMOS,
        ISNULL(XR.ASFALISTRA,0) * ps.signs AS ASFALISTRA, 
        ISNULL(XR.TAXISXREOSEON,0) * ps.signs AS TAXISXREOSEON,
        ISNULL(XR.KATHARO,0) * ps.signs AS KATHARO,
        ISNULL(f.ANAMEXODO,0) AS ANAMEXODO,
        f.EXT_BARCODE,
        case (f.ifprepay*1 + f.IFCASH*2)
			when 3 then ISNULL(f.SUMPOSO,0) * ps.signs
			else 0
		end as XREOSIPROPLIROMENESCASH,
		case (f.ifprepay*1 + f.IFPISTOSI*2)
			when 3 then ISNULL(f.SUMPOSO,0) * ps.signs
			else 0
		end as XREOSIPROPLIROMENESPISTOSI,
		
		case (f.IFOFEILOMENI*1 + f.IFPISTOSI*2)
			when 3 then ISNULL(f.SUMPOSO,0) * ps.signs
			else 0
		end as XREOSIOFEILOMENESPISTOSI,
		
		KAA.ID,
		fk.IDFORTOTIKIS,
		ISNULL(DAF.PROPLMETROTHERXREOSEIS , 0) * ps.signs AS PROPLMETROTHERXREOSEIS,
		KAA.IDCOMPANY,
        KAA.IDYPOKATASTIMA,
        KAA.IDXRHSHS,
        KAA.PERIOXIPROORISMOU,
        KAA.PERIOXIPARADOSIS,
        tr.Tel AS TELOWNER,
        f.IDPRAKTOREIO,
        f.PRAKTOREIODESCR, 
        KAA.AFMCUSTOMER,
        KAA.AFMANTAPOKRITIS,
        KAA.ANTAPOKRITIS AS ANTAPOKRITISKAA,
        KAA.FORTOSI,
        KAA.CUSTOMER,
        KAA.ANTAPOKRITIS,
        KAA.OMADPROORISMOS AS OMPROORKAA,
        DR.Tel AS TELDRIVER,
        KAA.CONTAINER,
        KAA.BOAT,
        (ANTAP.AddressStr + ' ' + ANTAP.AddressNo + '  ' + ANTAP.AddressCity + ' - ' + ANTAP.AddressCountry) AS ADDRESSANTAPOKRITI,
        ANTAP.AFM AS AFMANTAPOKRITI,
        ANTAP.DOY AS DOYANTAPOKRITI,
	case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as SYNTHIKI,
        ISNULL(DAF.DIAFORA_EXODA , 0) * ps.signs AS DIAFORA_EXODA,
        ISNULL(DAF.OFEILOMENAKOMISTRA , 0) * ps.signs AS OFEILOMENAKOMISTRA,
        ISNULL(DAF.ERGATIKA , 0) * ps.signs AS ERGETIKA,
        ISNULL(DAF.XREOSEISTRITON , 0) AS XREOSEISTRITON,
        ISNULL(DAF.EMVASTIKA , 0) * ps.signs AS EMVASTIKA,
        ISNULL(DAF.KATHAROPROPLMETR, 0) * ps.signs AS  KATHAROPROPLMETR,
        ISNULL(DAF.TAXISPROPLMETR, 0) * ps.signs AS  TAXISPROPLMETR,
        ISNULL(DAF.KATHAROOFEIL, 0) * ps.signs AS  KATHAROOFEIL,
        ISNULL(DAF.TAXISOFEIL, 0) * ps.signs AS  TAXISOFEIL,
        ISNULL(DAF.OTHERXREOSEIS , 0) * ps.signs AS OTHERXREOSEIS,
        ISNULL(DAF.EXODATRITON, 0) * ps.signs AS EXODATRITON,
        ISNULL(DAF.SYN_POSO_FORTOTIKIS, 0) * ps.signs AS SYN_POSO_FORTOTIKIS,
        ISNULL(DAF.PROPLMETRERGATIKA , 0) * ps.signs AS PROPLMETRERGATIKA,
        ISNULL(DAF.PROPLMETRASFALISTRA , 0) * ps.signs AS PROPLMETRASFALISTRA,
        ISNULL(DAF.PROPLMETRDIKAIOMA , 0) * ps.signs AS PROPLMETRDIKAIOMA, 
        ISNULL(DAF.PROPLMETRKOMISTRA , 0) * ps.signs AS PROPLMETRKOMISTRA,
        (ISNULL(DAF.ERGATIKA , 0)+ ISNULL(DAF.OTHERXREOSEIS , 0) + ISNULL(DAF.ASFALISTRA , 0)) * ps.signs AS ERG_ASF_OTHER, 
        (ISNULL(DAF.ERGATIKA , 0)+ ISNULL(DAF.OTHERXREOSEIS , 0)) * ps.signs AS ERG_OTHER,
        (ISNULL(DAF.ERGATIKA , 0) + ISNULL(DAF.ASFALISTRA , 0)) * ps.signs AS ERG_ASF, 
        (ISNULL(DAF.OTHERXREOSEIS , 0) + ISNULL(DAF.ASFALISTRA , 0)) * ps.signs AS ASF_OTHER,
        (ISNULL(XR.KOMISTRA , 0)+ ISNULL(XR.DIKAIOMAFORTOTIKIS , 0)) * ps.signs AS KOM_DIKAIOMA,
        ISNULL(PVT.DEMATA,0) AS DEMATA,
        ISNULL(PVT.PALETA,0) AS PALETA,
        ISNULL(PVT.KOLA,0) AS KOLA,
        ISNULL(PVT.STAND,0) AS STAND,
        ISNULL(PVT.ROLI,0) AS ROLI,
        ISNULL(PVT.THALAMOS,0) AS THALAMOS,
        ISNULL(PVT.[XB],0) AS X_B,
        ISNULL(PVT.KLOUBA,0) AS KLOUBA,
        ISNULL(PVT.KLOUBAKI,0) AS KLOUBAKI,
        ISNULL(PVT.L2,0) AS L2,
        ISNULL(PVT.[40X40],0) AS D40_40,
        ISNULL(PVT.MXP,0) AS MXP,
        ISNULL(PVT.PEP,0) AS PEP
        
       
        
from FORTOTIKES f
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI
left join ACCOUNTS APOST on APOST.id=f.IDAPOSTOLEA
left join KINDPARASTATIKON kp on kp.ID=f.IDPARAST
LEFT JOIN XREOSIS XR ON XR.IDFORT=f.ID
left join FORTOTIKES_ANA_KAA fk on fk.IDFORTOTIKIS=f.ID
left join grammes on grammes.IDVOH=fk.IDFORTOTIKIS
left join KAA on KAA.ID=fk.IDKAA
left join TRUCKS tr on tr.ArKykloforias=KAA.OXIMA
LEFT JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI DAF ON DAF.ID=F.ID
LEFT JOIN ODIGOI DR ON KAA.DRIVER = DR.LastName + ' ' + DR.FirstName
LEFT JOIN ACCOUNTS ANTAP ON ANTAP.id = KAA.IDANTAPOKRITIS
LEFT JOIN PIVOTED PVT ON PVT.IDVOH=FK.IDFORTOTIKIS
join parastatika_signs ps on ps.ID=f.IDPARAST



GO


---END SCRIPT 2024
