ALTER PROCEDURE [dbo].[inserttoFORT_ANA_KAA] (@ID NUMERIC(18, 0) = NULL,
@IDKAA NUMERIC(18, 0) = NULL,
@NoPARASTKAA NVARCHAR(10) = NULL,
@OXIMA NVARCHAR(60) = NULL,
@CONTAINER NVARCHAR(50) = NULL,
@BOAT NVARCHAR(50) = NULL,
@INSERTFORTOTIKES NVARCHAR(MAX) = NULL)
AS
	SET NOCOUNT ON

	DECLARE @RC INT
	BEGIN TRAN
	EXEC @RC = sp_getapplock @Resource = 'inserttoFORT_ANA_KAA'
													,@LockMode = 'Exclusive'
													,@LockOwner = 'Transaction'
													,@LockTimeout = 1000

	DECLARE @_STATUSID INT
	DECLARE @_STATUS VARCHAR(75)
	--SET @_STATUS = 'ΣΕ ΚΑΑ'

	DECLARE @_DRIVERID INT
	DECLARE @_DRIVERDESCR NVARCHAR(50)

	SELECT
		@_STATUS = STATUS
	 ,@_STATUSID = IDSTATUS
	 ,@_DRIVERID = isnull(ODIGOI.ID,0)
	 ,@_DRIVERDESCR = isnull(KAA.DRIVER,'')
	FROM KAA
	LEFT JOIN ODIGOI ON ODIGOI.LastName + ' ' + ODIGOI.FirstName = KAA.DRIVER
	WHERE KAA.ID = @IDKAA

	IF LEN(@_STATUS) < 3
	BEGIN
		SELECT TOP 1
			@_STATUS = DESCR
		 ,@_STATUSID = ID
		FROM DOC_STATUS
		WHERE IFSEKAA = 1
	END



	DECLARE @_NULL VARCHAR(75)
	SET @_NULL = ''

	EXEC ('UPDATE FORTOTIKES SET NOPARASTDELTIOUAPOSTOLIS =''' + @NoPARASTKAA + ''', CONTAINER =''' + @CONTAINER + ''', OXIMA =''' + @OXIMA +
	''', BOAT =''' + @BOAT + ''', IDDRIVER =	''' + @_DRIVERID + ''', DRIVERDESCR= ''' + @_DRIVERDESCR + ''', STATUS =	''' + @_STATUSID + ''', STATUSDESCR = ''' + @_STATUS + ''' WHERE ID IN(' + @INSERTFORTOTIKES + ')')
	DECLARE @coma CHAR(1)
	SELECT
		@coma = ','
	BEGIN
		DECLARE @start INT
					 ,@end INT
		SELECT
			@start = 1
		 ,@end = CHARINDEX(@coma, @INSERTFORTOTIKES)
		WHILE @start < LEN(@INSERTFORTOTIKES) + 1
		BEGIN
		IF @end = 0
			SET @end = LEN(@INSERTFORTOTIKES) + 1;

with parastatika_sign as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS KPSIGN
				from KINDPARASTATIKON kp
				)

		--DECLARE @DOC_TYPE_SIGNS TABLE(
		--	IDKP INT,
		--	KPSIGN INT
		--);

		--INSERT INTO @DOC_TYPE_SIGNS
		--SELECT
		--	ID,
		--	CASE (ISNULL(IF_XREOSI,0) * 1 + ISNULL(IF_PISTOSI,0) * 2)
		--		WHEN 1 THEN 1
		--		WHEN 2 THEN -1
		--		ELSE 0
		--	END
		--FROM KINDPARASTATIKON;
		
		INSERT INTO FORTOTIKES_ANA_KAA 
		(	IDKAA, 
			IDFORTOTIKIS, 
			KOMISTRA, 
			DIKAIOMA, 
			OTHERPOSO, 
			EXODATRITON, 
			XREOSIPROPLIROMENES,
			XREOSIOFEILOMENES, 
			XREOSIPROPLIROMENESCASH, 
			XREOSIPROPLIROMENESPISTOSI, 
			POSO, 
			TAXIS, 
			SUMPOSO, 
			ANTIKCASH,
			ANTIKEPIT, 
			ANTIKSYNAL, 
			ANTIKOTHER, 
			SUMANTIK, 
			IDPARALIPTI,
			PARALISPTISDESCR, 
			IDAPOSTOLEA, 
			APOSTOLEASDESCR,
			IDENTOLEA, 
			ENTOLEASDESCR, 
			IDTRITOU, 
			TRITOSDESCR,
			XREOYMENOS,
			OMADPROORISMOS,
			OXIMA, 
			DRIVERDESCR, 
			BAROS,
			KYBIKA, 
			TEMAXIA, 
			AXIA, 
			PERIEXOMENO, 
			TIMDA, 
			ASFALISTRA, 
			ERGATIKA,
			CODE, 
			NOPARASTFORT,
			SYSKEVASIA, 
			DIAFORA_EXODA,
			XREOSEISTRITON, 
			EMVASTIKA,
			OTHERXREOSEIS, 
			PROPLMETRERGATIKA,
			PROPLMETRASFALISTRA, 
			PROPLMETRDIKAIOMA,
			PROPLMETRKOMISTRA,
			IDPRAKTOREIO, 
			PRAKTOREIODESCR,
			ANAMEXODO, 
			PROPLMETROTHERXREOSEIS,
			ANTAPOKRITIS, 
			OFEILOMENAKOMISTRA, 
			SYN_POSO_FORTOTIKIS,
			TAXISOFEIL, 
			TAXISPROPLMETR, 
			KATHAROOFEIL, 
			KATHAROPROPLMETR)
			SELECT
			 @IDKAA AS IDKAA
			 ,A.ID
			 ,A.KOMISTRA  * ps.KPSIGN
			 ,A.DIKAIOMA * ps.KPSIGN
			 ,A.OTHERPOSO * ps.KPSIGN
			 ,A.EXODATRITON * ps.KPSIGN
			 ,A.XREOSIPROPLIROMENES * ps.KPSIGN
			 ,A.XREOSIOFEILOMENES * ps.KPSIGN
			 ,A.XREOSIPROPLIROMENESCASH * ps.KPSIGN
			 ,A.XREOSIPROPLIROMENESPISTOSI * ps.KPSIGN
			 ,A.POSO * ps.KPSIGN
			 ,A.TAXIS * ps.KPSIGN
			 ,A.SUMPOSO * ps.KPSIGN
			 ,A.ANTIKCASH
			 ,A.ANTIKEPIT
			 ,A.ANTIKSYNAL
			 ,A.ANTIKOTHER
			 ,A.SUMANTIK
			 ,A.IDPARALIPTI
			 ,A.PARALISPTISDESCR
			 ,A.IDAPOSTOLEA
			 ,A.APOSTOLEASDESCR
			 ,A.IDENTOLEA
			 ,A.ENTOLEASDESCR
			 ,A.IDTRITOU
			 ,A.TRITOSDESCR
			 ,A.XREOYMENOS
			 ,A.OMADPROORISMOS
			 ,A.OXIMA
			 ,A.DRIVERDESCR
			 ,A.BAROS
			 ,A.KYBIKA
			 ,A.TEMAXIA
			 ,A.AXIA
			 ,A.PERIEXOMENO
			 ,A.TIMDA
			 ,G.ASFALISTRA
			 ,G.ERGATIKA
			 ,A.CODE
			 ,A.NOPARASTFORT
			 ,A.SYSKEVASIA
			 ,G.DIAFORA_EXODA
			 ,G.XREOSEISTRITON
			 ,G.EMVASTIKA
			 ,G.OTHERXREOSEIS
			 ,G.PROPLMETRERGATIKA
			 ,G.PROPLMETRASFALISTRA
			 ,G.PROPLMETRDIKAIOMA
			 ,G.PROPLMETRKOMISTRA
			 ,A.IDPRAKTOREIO
			 ,A.PRAKTOREIODESCR
			 ,A.ANAMEXODO
			 ,G.PROPLMETROTHERXREOSEIS
			 ,FR.ANTAPOKRITISDESCR
			 ,G.OFEILOMENAKOMISTRA
			 ,G.SYN_POSO_FORTOTIKIS
			 ,G.TAXISOFEIL
			 ,G.TAXISPROPLMETR
			 ,G.KATHAROOFEIL
			 ,G.KATHAROPROPLMETR
			FROM FORTOTIKES_ANALYSH_XREOSEON AS A
			JOIN FORTOTIKES AS FR
				ON FR.ID = A.ID
			INNER JOIN DIAFORESXREOSEIS_ANA_FORTOTIKI AS G
				ON A.ID = G.ID
			--JOIN @DOC_TYPE_SIGNS ps on ps.IDKP = fr.IDPARAST
			join parastatika_sign ps on ps.ID=fr.IDPARAST
			WHERE A.ID = CAST(SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start) AS NUMERIC)

		--VALUES(@IDKAA, CAST( SUBSTRING(@INSERTFORTOTIKES, @start, @end - @start)AS NUMERIC)) 

		SET @start = @end + 1
		SET @end = CHARINDEX(@coma, @INSERTFORTOTIKES, @start)
		END
	END
		
		
		
	WAITFOR DELAY '00:00:00:40'
	COMMIT;

	with sumanaKAA as (
					select 
						idKAA, 
						count(id) countparast 
					from FORTOTIKES_ANA_KAA 
					group by IDKAA
				)

				update KAA
					set COUNT_FORT = sumanaKAA.countparast
				from KAA
				join sumanaKAA on sumanaKAA.IDKAA = KAA.ID
				where KAA.id=@IDKAA		


GO


---END SCRIPT 2025
