ALTER VIEW [dbo].[KAA_FORT_VIEW] AS 

--ΒΑΡΕΘΗΚΑ ΝΑ ΤΟ ΞΑΝΑ ΓΡΑΨΩ ΟΛΟ ΑΠΟ ΤΗΝ ΑΡΧΗ - 14/10/24---

with parastatika_sign as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS KPSIGN
				from KINDPARASTATIKON kp
				)
SELECT 
  dbo.FORTOTIKES.ID, 
  dbo.FORTOTIKES.DATEPRINT, 
  dbo.KINDPARASTATIKON.Code, 
  dbo.FORTOTIKES.PARASTATIKO, 
  dbo.FORTOTIKES.SEIRA, 
  dbo.FORTOTIKES.NOPARAST, 
  dbo.FORTOTIKES.NOPARASTDELTIOUDIANOMIS, 
  dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS, 
  dbo.FORTOTIKES.OXIMA, 
  dbo.FORTOTIKES.OMADPROORISMOS, 
  CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE 
  CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' 
  ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
  dbo.FORTOTIKES.APOSTOLEASDESCR, 
  dbo.FORTOTIKES.PARALISPTISDESCR, 
  dbo.FORTOTIKES.ENTOLEASDESCR, 
  dbo.FORTOTIKES.ANTAPOKRITISDESCR, 
  dbo.FORTOTIKES.TRITOSDESCR, 
  MIN(dbo.GRAMMESFORTTIKIS.TIMDA) AS TIMDA, 
  dbo.FORTOTIKES.POSO * ps.KPSIGN  AS POSO, 
  dbo.FORTOTIKES.TAXIS * ps.KPSIGN AS TAXIS, 
  dbo.FORTOTIKES.SUMPOSO * ps.KPSIGN AS SUMPOSO, 
  ISNULL(SUM(dbo.GRAMMESFORTTIKIS.TEMAXIA), 0) AS TEMAXIA, 
  ISNULL(SUM(dbo.GRAMMESFORTTIKIS.BAROS), 0) AS BAROS, 
  ISNULL(SUM(dbo.GRAMMESFORTTIKIS.KYBIKA), 0) AS KYBIKA, 
  MIN(dbo.Units.UntName) AS SYSKEVASIA, 
  CASE dbo.FORTOTIKES.IFPREPAY 
  WHEN 1 THEN (
				SELECT 
				  SUM(SUMPOSO) * ps.KPSIGN AS XREOSEIS 
				FROM 
				  XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
				WHERE 
				  IDVOH = dbo.FORTOTIKES.ID 
				  AND ifXreosiTriton <> 1
  ) ELSE 0 END AS XREOSIPROPLIROMENES, 
  CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN (
    SELECT 
      SUM(SUMPOSO) * ps.KPSIGN AS XREOSEIS 
    FROM 
      XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
    WHERE 
      IDVOH = dbo.FORTOTIKES.ID 
      AND ifXreosiTriton <> 1
  ) ELSE 0 END AS XREOSIOFEILOMENES, 
  CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFCASH WHEN 1 THEN (
    SELECT 
      SUM(SUMPOSO) * ps.KPSIGN AS XREOSEIS 
    FROM 
      XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
    WHERE 
      IDVOH = dbo.FORTOTIKES.ID 
      AND ifXreosiTriton <> 1
  ) ELSE 0 END ELSE 0 END AS XREOSIPROPLIROMENESCASH, 
  CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN CASE dbo.FORTOTIKES.IFPISTOSI WHEN 1 THEN (
    SELECT 
      SUM(SUMPOSO) * ps.KPSIGN AS XREOSEIS 
    FROM 
      XREOSIS_ANADELTIO_VIEW WITH (NOLOCK) 
    WHERE 
      IDVOH = dbo.FORTOTIKES.ID 
      AND ifXreosiTriton <> 1
  ) ELSE 0 
  END 
  ELSE 0 
  END AS XREOSIPROPLIROMENESPISTOSI, 
  MIN(dbo.GRAMMESFORTTIKIS.PERIEXOMENO) AS PERIEXOMENO, 
  dbo.FORTOTIKES.PERIOXIFORTOSIS, 
  dbo.FORTOTIKES.PERIOXIPARADOSIS, 
  dbo.FORTOTIKES.COMMENTS, 
  dbo.FORTOTIKES.SUMANTIK, 
  dbo.FORTOTIKES.PRAKTOREIODESCR, 
  dbo.FORTOTIKES.STATUS, 
  dbo.FORTOTIKES.DATEPARAD, 
  dbo.FORTOTIKES.IDAPOSTOLEA, 
  dbo.FORTOTIKES.IDPARALIPTI, 
  dbo.FORTOTIKES.IDENTOLEA, 
  dbo.FORTOTIKES.IDANTAPOKRITI, 
  dbo.FORTOTIKES.IDTRITOU, 
  dbo.FORTOTIKES.IDPRAKTOREIO, 
  CASE IFANTIKCASH WHEN 0 THEN 0 ELSE dbo.FORTOTIKES.ANTIKCASH END AS ANTIKCASH, 
  CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE dbo.FORTOTIKES.ANTIKEPIT END AS ANTIKEPIT, 
  CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE dbo.FORTOTIKES.ANTIKSYNAL END AS ANTIKSYNAL, 
  CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE dbo.FORTOTIKES.ANTIKOTHER END AS ANTIKOTHER, 
  CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, 
  dbo.FORTOTIKES.COMMENTSANTIK, 
  dbo.FORTOTIKES.DATEPARADOSI, 
  dbo.FORTOTIKES.COMMENTS2, 
  MIN(dbo.HEADERFORTOTIKIS.KOMISTRA) * ps.KPSIGN AS KOMISTRA, 
  MIN(dbo.FORTOTIKES.EXODATRITON) AS XREOSISTRITON, 
  MIN(dbo.HEADERFORTOTIKIS.DIKAIOMAFORTOTIKIS) * ps.KPSIGN AS DIKAIOMAFORTOTIKIS, 
  MIN(dbo.HEADERFORTOTIKIS.OTHERXREOSIS) * ps.KPSIGN AS OTHERXREOSIS, 
  MIN(dbo.HEADERFORTOTIKIS.OLIKOSYNOLOXREOSEONFORT) * ps.KPSIGN AS OLIKOSYNOLOXREOSEONFORT, 
  MIN(dbo.HEADERFORTOTIKIS.ERGATIKA) * ps.KPSIGN AS ERGATIKA, 
  CASE dbo.FORTOTIKES.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
  CASE dbo.FORTOTIKES.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, 
  ISNULL(SUM(dbo.GRAMMESFORTTIKIS.SUMPOSO) * ps.KPSIGN, 0) AS AXIA, 
  CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, 
  dbo.FORTOTIKES.KINDPAYMENTDESCR, 
  dbo.FORTOTIKES.IDKINDPAYMENT, 
  CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
  CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, 
  CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, 
  dbo.FORTOTIKES.IFANTIKCASH, 
  dbo.FORTOTIKES.IFANTIKEPIT, 
  dbo.FORTOTIKES.IFANTIKSYNAL, 
  dbo.FORTOTIKES.IFANTIKOTHER, 
  dbo.FORTOTIKES.ifDelete, 
  dbo.FORTOTIKES.IFCANCEL, 
  dbo.FORTOTIKES.DATECANCEL, 
  dbo.FORTOTIKES.IFPARADOSI, 
  dbo.FORTOTIKES.AITIOLOGIAPARASTATIKOU, 
  dbo.FORTOTIKES.DATEFORTOSIS, 
  dbo.FORTOTIKES.IFEPISTROFI, 
  dbo.FORTOTIKES.DATEEPISTROFIS, 
  dbo.FORTOTIKES.AITIOLOGIAEPISTROFIS, 
  dbo.FORTOTIKES.COMMENTSEPISTROFIS, 
  dbo.FORTOTIKES.IFCASH, 
  dbo.FORTOTIKES.IFPISTOSI, 
  dbo.FORTOTIKES.STATUSDESCR, 
  dbo.FORTOTIKES.YPAITIOS, 
  dbo.FORTOTIKES.IFEPANADROMOLOGISI, 
  dbo.FORTOTIKES.IFEPANEKDOSI, 
  dbo.FORTOTIKES.IFOKEPANADROMOLOGISI, 
  dbo.FORTOTIKES.NOPARASTANTIK, 
  dbo.FORTOTIKES.COMMENTSAKIROSIS, 
  dbo.FORTOTIKES.IFEISPRANTIK, 
  dbo.FORTOTIKES.IFPARADOSIANTIK, 
  dbo.FORTOTIKES.IFPARALAVIANTIK, 
  dbo.FORTOTIKES.COMMENTSPARADANTIK, 
  dbo.FORTOTIKES.COMMANTSPARALANTIK, 
  dbo.FORTOTIKES.COMMENTSEISPRANTIK, 
  dbo.FORTOTIKES.DATEPARADANTIK, 
  dbo.FORTOTIKES.DATEPARALANTIK, 
  dbo.FORTOTIKES.DATEEISPRANTIK, 
  dbo.FORTOTIKES.EISPRAXASANTIK, 
  dbo.FORTOTIKES.NOPARPARADANTIK, 
  dbo.FORTOTIKES.NOPARASTEISPRANTIK, 
  dbo.FORTOTIKES.NOPARPARALANTIK, 
  dbo.FORTOTIKES.DATEPARAL, 
  dbo.FORTOTIKES.COMMENTSPARAD, 
  dbo.FORTOTIKES.COMMANTSPARAL, 
  dbo.FORTOTIKES.TIMEPARALFROM, 
  dbo.FORTOTIKES.TIMEPARALTO, 
  dbo.FORTOTIKES.TIMEPARADFROM, 
  dbo.FORTOTIKES.TIMEPARADTO, 
  dbo.FORTOTIKES.DATECANCELANTIK, 
  dbo.FORTOTIKES.IDPARAST, 
  dbo.FORTOTIKES.TAXISPERCENT, 
  dbo.FORTOTIKES.ANAMEXODO, 
  dbo.FORTOTIKES.ID AS IDFORTOTIKIS, 
  dbo.FORTOTIKES.AFMXREOUMENOU, 
  dbo.HEADERFORTOTIKIS.ASFALISTRA * ps.KPSIGN AS ASFALISTRA, 
  dbo.HEADERFORTOTIKIS.TAXIS * ps.KPSIGN AS TAXISXREOSEON, 
  dbo.HEADERFORTOTIKIS.SUMPOSOXRFORT * ps.KPSIGN AS SUMPOSOXRFORT , 
