  dbo.ACCOUNTS.Epagelma AS EPAGAPOST, 
  dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, 
  dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, 
  dbo.ACCOUNTS.AddressTK AS TKAPOST, 
  dbo.ACCOUNTS.AddressCity AS CITYAPOST, 
  dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, 
  dbo.ACCOUNTS.Tel AS TELAPOST, 
  dbo.ACCOUNTS.DOY AS DOYAPOST, 
  ACCOUNTS_1.Epagelma AS EPAGPARAL, 
  ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, 
  ACCOUNTS_1.AddressNo AS ADDRNOPARAL, 
  ACCOUNTS_1.AddressTK AS ADDRTKPARAL, 
  ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, 
  ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, 
  ACCOUNTS_1.Tel AS TELPARAL, 
  ACCOUNTS_1.DOY AS DOYPARAL, 
  ACCOUNTS_2.Epagelma AS EPAGENTOL, 
  ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, 
