FROM 
  dbo.FORTOTIKES WITH (NOLOCK) 
  LEFT OUTER JOIN dbo.FORTOTIKES_ANA_KAA WITH (NOLOCK) ON dbo.FORTOTIKES.ID = dbo.FORTOTIKES_ANA_KAA.IDFORTOTIKIS 
  LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) ON dbo.FORTOTIKES.IDAPOSTOLEA = dbo.ACCOUNTS.id 
