ALTER view [dbo].[LISTA_KAA_WITH_ANTAPIKRITI]
as
with parastatika_sign as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS KPSIGN
				from KINDPARASTATIKON kp
				)
SELECT
	K.ID,
	K.DATEPRINT ,
	K.SEIRA,
	K.NOPARAST,
	K.IDPARAST,
	K.PARASTATIKO,
	K.OMADPROORISMOS,
	K.IDANTAPOKRITIS,
	K.AFMANTAPOKRITIS,
	K.OXIMA,
	K.DRIVER,
	COUNT(FK.ID)  AS COUNTFORT,-- [SUMFORTOTIKES],	
	SUM(FK.KOMISTRA * ps.KPSIGN)  AS POSOKOMISTRA, -- [KOMISTRA],
	SUM((FK.DIKAIOMA + FK.OTHERPOSO)* ps.KPSIGN)   AS POSOLOIPA,--  [LOIPA],
	SUM(FK.TAXIS * ps.KPSIGN)   AS TAXIS,--  [FPA],
	SUM(FK.XREOSIPROPLIROMENES * ps.KPSIGN)   AS POSOPROPL, -- [POSOPROPL],
	SUM(FK.XREOSIOFEILOMENES * ps.KPSIGN)   AS POSOOFEIL, -- [POSOOFEIL],
	K.POSOEXTRITON,
	K.POSOEXODA ,
	K.TAXISEXODA ,
	K.SUMPOSOEXODA ,
	K.NOFORT, --[NOPARASTEX],
	K.ANTAPOKRITIS  ,
	SUM(FK.SUMANTIK) AS SINOLO_ANTIKATABOLWN,
	K.IDYPOKATASTIMA 
FROM KAA K
LEFT join FORTOTIKES_ANA_KAA FK ON FK.IDKAA=K.ID
left join FORTOTIKES f on f.ID=fk.IDFORTOTIKIS
left JOIN parastatika_sign ps on ps.ID=f.IDPARAST
WHERE K.IFDELETE=0
group by K.ID,
	K.DATEPRINT ,
	K.SEIRA,
	K.NOPARAST ,
	K.IDPARAST,
	K.PARASTATIKO ,
	K.OMADPROORISMOS,
	K.IDANTAPOKRITIS,
	K.AFMANTAPOKRITIS,
	K.OXIMA ,
	K.DRIVER ,
	K.POSOEXTRITON,
	K.POSOEXODA ,
	K.TAXISEXODA ,
	K.SUMPOSOEXODA ,
	K.NOFORT ,
	K.ANTAPOKRITIS,
	K.IDYPOKATASTIMA,
	ps.KPSIGN


GO


---END SCRIPT 2028
