ALTER VIEW [dbo].[KARTELES_PELATES]
AS

SELECT     ACCOUNTS.ID AS ACCOUNTID, ACCOUNTS.Eponimia, ACCOUNTS.Epagelma, ACCOUNTS.AddressStr, ACCOUNTS.AddressNo, ACCOUNTS.Code, ACCOUNTS.AddressTK, 
                      ACCOUNTS.Tel, ACCOUNTS.Tel2, ACCOUNTS.Fax, ACCOUNTS.Mobile, ACCOUNTS.AFM, ACCOUNTS.IF_PROM, ACCOUNTS.IF_PEL, '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20)) AS ID, 
                      FORTOTIKES.DATEPRINT, '' AS THETIME, FORTOTIKES.SEIRA, CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))  AS DOCNO, 'ΠΩΛΗΣΕΙΣ' AS AFORA, FORTOTIKES.IDPARAST, 
                      FORTOTIKES.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, 0 AS IDDRIVER, '' AS DRIVERDESCR, FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI AS XREOSI,
                       FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, 0 AS EXODATRITON, '' AS AITIOLOGIA, '' AS EISPRAXAS, GetDATE() AS MHNASPOYAFORA, YEAR(gETdate()) 
                      AS ETOSPOYAFORA, 0 AS IFEXOFLISI, 0 AS IFPROKATABOLI, FORTOTIKES.COMMENTS, FORTOTIKES.OXIMA, NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA, FORTOTIKES.ifDelete, FORTOTIKES.IDXRHSHS, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA
FROM         FORTOTIKES WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDAPOSTOLEA = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 
WHERE  --    KINDPARASTATIKON.IF_XREOSI = 1 AND 
KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND FORTOTIKES.ifDelete = 0 AND FORTOTIKES.IFXRAPOST = 1 

UNION
SELECT     ACCOUNTS.ID AS ACCOUNTID, ACCOUNTS.Eponimia, ACCOUNTS.Epagelma, ACCOUNTS.AddressStr, ACCOUNTS.AddressNo, ACCOUNTS.Code, ACCOUNTS.AddressTK, 
                      ACCOUNTS.Tel, ACCOUNTS.Tel2, ACCOUNTS.Fax, ACCOUNTS.Mobile, ACCOUNTS.AFM, ACCOUNTS.IF_PROM, ACCOUNTS.IF_PEL, '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20)) AS ID, 
                      FORTOTIKES.DATEPRINT, '' AS THETIME, FORTOTIKES.SEIRA, CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))  AS DOCNO, 'ΠΩΛΗΣΕΙΣ' AS AFORA, FORTOTIKES.IDPARAST, 
                      FORTOTIKES.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, 0 AS IDDRIVER, '' AS DRIVERDESCR, FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI AS XREOSI,
                       FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, FORTOTIKES.EXODATRITON, '' AS AITIOLOGIA, '' AS EISPRAXAS, GetDATE() AS MHNASPOYAFORA, YEAR(gETdate()) 
                      AS ETOSPOYAFORA, 0 AS IFEXOFLISI, 0 AS IFPROKATABOLI, FORTOTIKES.COMMENTS, FORTOTIKES.OXIMA, NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA, FORTOTIKES.ifDelete, FORTOTIKES.IDXRHSHS, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA
FROM         FORTOTIKES WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS ON FORTOTIKES.IDENTOLEA = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0 
WHERE -- KINDPARASTATIKON.IF_XREOSI = 1 AND 
KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND FORTOTIKES.ifDelete = 0 AND FORTOTIKES.IFXRENTOL = 1  

UNION
SELECT     ACCOUNTS.ID AS ACCOUNTID, ACCOUNTS.Eponimia, ACCOUNTS.Epagelma, ACCOUNTS.AddressStr, ACCOUNTS.AddressNo, ACCOUNTS.Code, ACCOUNTS.AddressTK, 
                      ACCOUNTS.Tel, ACCOUNTS.Tel2, ACCOUNTS.Fax, ACCOUNTS.Mobile, ACCOUNTS.AFM, ACCOUNTS.IF_PROM, ACCOUNTS.IF_PEL, '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20)) AS ID, 
                      FORTOTIKES.DATEPRINT, '' AS THETIME, FORTOTIKES.SEIRA, CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))  AS DOCNO, 'ΠΩΛΗΣΕΙΣ' AS AFORA, FORTOTIKES.IDPARAST, 
                      FORTOTIKES.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, 0 AS IDDRIVER, '' AS DRIVERDESCR, FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI AS XREOSI,
                       FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, FORTOTIKES.EXODATRITON, '' AS AITIOLOGIA, '' AS EISPRAXAS, GetDATE() AS MHNASPOYAFORA, YEAR(gETdate()) 
                      AS ETOSPOYAFORA, 0 AS IFEXOFLISI, 0 AS IFPROKATABOLI, FORTOTIKES.COMMENTS, FORTOTIKES.OXIMA, NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA, FORTOTIKES.ifDelete, FORTOTIKES.IDXRHSHS, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA
FROM         FORTOTIKES WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS ON FORTOTIKES.IDPARALIPTI = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0
WHERE  --  KINDPARASTATIKON.IF_XREOSI = 1 AND 
KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND FORTOTIKES.ifDelete = 0 AND FORTOTIKES.IFXRPARAL = 1  

UNION
SELECT     ACCOUNTS.ID AS ACCOUNTID, ACCOUNTS.Eponimia, ACCOUNTS.Epagelma, ACCOUNTS.AddressStr, ACCOUNTS.AddressNo, ACCOUNTS.Code, ACCOUNTS.AddressTK, 
                      ACCOUNTS.Tel, ACCOUNTS.Tel2, ACCOUNTS.Fax, ACCOUNTS.Mobile, ACCOUNTS.AFM, ACCOUNTS.IF_PROM, ACCOUNTS.IF_PEL, '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20)) AS ID, 
                      FORTOTIKES.DATEPRINT, '' AS THETIME, FORTOTIKES.SEIRA, CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))  AS DOCNO, 'ΠΩΛΗΣΕΙΣ' AS AFORA, FORTOTIKES.IDPARAST, 
                      FORTOTIKES.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, 0 AS IDDRIVER, '' AS DRIVERDESCR, FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI AS XREOSI,
                       FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, FORTOTIKES.EXODATRITON, '' AS AITIOLOGIA, '' AS EISPRAXAS, GetDATE() AS MHNASPOYAFORA, YEAR(gETdate()) 
                      AS ETOSPOYAFORA, 0 AS IFEXOFLISI, 0 AS IFPROKATABOLI, FORTOTIKES.COMMENTS, FORTOTIKES.OXIMA, NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA, FORTOTIKES.ifDelete, FORTOTIKES.IDXRHSHS, FORTOTIKES.IDCOMPANY, FORTOTIKES.IDYPOKATASTIMA
FROM         FORTOTIKES WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDTRITOU = ACCOUNTS.ID AND ACCOUNTS.ifDelete = 0
WHERE   -- KINDPARASTATIKON.IF_XREOSI = 1 AND 
KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND FORTOTIKES.ifDelete = 0 AND FORTOTIKES.IFXRTRITOU = 1 

UNION
SELECT     ACCOUNTS_2.id AS ACCOUNTID, 
ACCOUNTS_2.Eponimia, ACCOUNTS_2.Epagelma, ACCOUNTS_2.AddressStr, ACCOUNTS_2.AddressNo, ACCOUNTS_2.Code, 
                      ACCOUNTS_2.AddressTK, ACCOUNTS_2.Tel, ACCOUNTS_2.Tel2, ACCOUNTS_2.Fax, ACCOUNTS_2.Mobile, ACCOUNTS_2.AFM, ACCOUNTS_2.IF_PROM, 
                      ACCOUNTS_2.IF_PEL, '102' + CAST(VOH.ID AS NVARCHAR(20)) AS ID, VOH.DATEPRINT, VOH.THETIME, VOH.SEIRA, CAST(VOH.NOPARAST AS NVARCHAR(20))  AS DOCNO, 'ΠΩΛΗΣΕΙΣ' AS AFORA, VOH.IDPARAST, VOH.PARASTATIKO, 
                      'ΕΣΟΔΑ' AS EIDOSKINHSHS, 0 AS IDDRIVER, VOH.DRIVER AS DRIVERDESCR, (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR)  * KINDPARASTATIKON.IF_XREOSI AS XREOSI, 
                      (VOH.SUMPOSO + VOH.SUMPOSOEPIVAR) * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, 
					  0 AS EXODATRITON, 
					  VOH.COMMENTS AS AITIOLOGIA, '' AS EISPRAXAS, GetDATE() AS MHNASPOYAFORA, YEAR(gETdate()) 
                      AS ETOSPOYAFORA, 
					  0 AS IFEXOFLISI, 0 AS IFPROKATABOLI, 
					  VOH.COMMENTS, 
					  VOH.OXIMA, 
					  NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA,
					  VOH.ifDelete, VOH.IDXRHSHS, VOH.IDCOMPANY, VOH.IDYPOKATASTIMA
FROM         VOH WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON ON VOH.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON VOH.IDCUSTOMER = ACCOUNTS_2.id AND ACCOUNTS_2.ifDelete = 0
WHERE  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND VOH.ifDelete = 0
UNION
SELECT     ACCOUNTS.id AS ACCOUNTID, ACCOUNTS.Eponimia, ACCOUNTS.Epagelma, ACCOUNTS.AddressStr, ACCOUNTS.AddressNo, ACCOUNTS.Code, ACCOUNTS.AddressTK, 
                      ACCOUNTS.Tel, ACCOUNTS.Tel2, ACCOUNTS.Fax, ACCOUNTS.Mobile, ACCOUNTS.AFM, ACCOUNTS.IF_PROM, ACCOUNTS.IF_PEL, '103' + CAST(ESODA.ID AS NVARCHAR(20)) AS ID, ESODA.DATEPRINT, 
                      ESODA.THETIME, ESODA.SEIRA, CAST(ESODA.NOPARAST AS NVARCHAR(20))  AS DOCNO, ESODA.AFORA, ESODA.IDPARAST, ESODA.PARASTATIKO, 'ΕΣΟΔΑ' AS EIDOSKINHSHS, 
                      ESODA.IDDRIVER, ESODA.DRIVERDESCR, ESODA.SUMPOSO * KINDPARASTATIKON.IF_XREOSI AS XREOSI, 
                      ESODA.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, 0 AS EXODATRITON, '' AS AITIOLOGIA, '' AS EISPRAXAS, ESODA.MHNASPOYAFORA, ESODA.ETOSPOYAFORA, 
                      ESODA.IFEXOFLISI, ESODA.IFPROKATABOLI, ESODA.COMMENTS, ESODA.OXIMA, NULL AS IDKINDPAYMENT, '' AS KINDPAYMENTDESCR, 
                      KINDPARASTATIKON.IF_ENIMEROSIKARTELA, ESODA.ifDelete, ESODA.IDXRHSHS, ESODA.IDCOMPANY, ESODA.IDYPOKATASTIMA
FROM         ESODA WITH (NOLOCK) LEFT JOIN KINDPARASTATIKON WITH (NOLOCK) ON ESODA.IDPARAST = KINDPARASTATIKON.ID INNER JOIN
                      ACCOUNTS WITH (NOLOCK) ON ESODA.IDPROM = ACCOUNTS.id AND ACCOUNTS.ifDelete = 0
WHERE KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 AND KINDPARASTATIKON.KindKINISIS IN(1, 5) AND  ESODA.ifDelete = 0

UNION
SELECT     ACCOUNTS_4.id AS ACCOUNTID, ACCOUNTS_4.Eponimia, ACCOUNTS_4.Epagelma, ACCOUNTS_4.AddressStr, ACCOUNTS_4.AddressNo, ACCOUNTS_4.Code, 
                      ACCOUNTS_4.AddressTK, ACCOUNTS_4.Tel, ACCOUNTS_4.Tel2, ACCOUNTS_4.Fax, ACCOUNTS_4.Mobile, ACCOUNTS_4.AFM, ACCOUNTS_4.IF_PROM, 
                      ACCOUNTS_4.IF_PEL, '105' + CAST(RECEIPTS.ID AS NVARCHAR(20)) AS ID, RECEIPTS.DATEPRINT, NULL AS THETIME, RECEIPTS.SEIRA, 
                      CAST(RECEIPTS.DOCNO AS NVARCHAR(20))  AS DOCNO, NULL AS AFORA, RECEIPTS.IDKINDPARAST AS IDPARAST, RECEIPTS.KINDPARASTDESCR 
                      AS PARASTATIKO, 'ΕΙΣΠΡΑΞΕΙΣ' AS EIDOSKINHSHS, NULL AS IDDRIVER, '' AS DRIVERDESCR, RECEIPTS.SUMPOSO * KINDPARASTATIKON_1.IF_XREOSI 
                      AS XREOSI, RECEIPTS.SUMPOSO * KINDPARASTATIKON_1.IF_PISTOSI AS PISTOSI, 0 AS EXODATRITON, 
                      LTRIM(RTRIM(RECEIPTS.AITIOLOGIA)), RECEIPTS.EISPRAXAS, NULL AS MHNASPOYAFORA, NULL AS ETOSPOYAFORA, NULL AS IFEXOFLISI, NULL AS 
                      IFPROKATABOLI, NULL AS COMMENTS, NULL AS OXIMA, RECEIPTS.IDKINDPAYMENT, RECEIPTS.KINDPAYMENTDESCR, 
                      KINDPARASTATIKON_1.IF_ENIMEROSIKARTELA, 
                      RECEIPTS.ifDelete, RECEIPTS.IDXRHSHS, RECEIPTS.IDCOMPANY, RECEIPTS.IDYPOKATASTIMA
FROM         RECEIPTS WITH (NOLOCK) INNER JOIN KINDPARASTATIKON AS KINDPARASTATIKON_1 WITH (NOLOCK) ON RECEIPTS.IDKINDPARAST = KINDPARASTATIKON_1.ID 
INNER JOIN ACCOUNTS AS ACCOUNTS_4 WITH (NOLOCK) ON RECEIPTS.IDCUSTOMER = ACCOUNTS_4.id AND ACCOUNTS_4.ifDelete = 0
WHERE     (KINDPARASTATIKON_1.IF_ENIMEROSIKARTELA = 1 OR 
KINDPARASTATIKON_1.IFENIMEROSITAMEIO = 1) 
AND RECEIPTS.ifDelete = 0


GO


