ALTER view [dbo].[TZIROS_ANA_HMEROMHNIA] AS 
with parastatika_sign as (
					select 
						id,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
),
TRANSFORMED_PARASTATIKA AS (select
							TRANSFORMTO
							from KINDPARASTATIKON 
							where IF_ENIMEROSIKARTELA!=1 
							and KindKINISIS in (1,5) 
							AND IF_TRANSFORM=1
					)

select
	convert(date,dateprint) as dateprint,
	count(f.ID) as count_row,
	f.IDYPOKATASTIMA,
	f.IDPARAST,
	PARASTATIKO,
	sum(poso) *ps.signs as poso,
	sum(taxis) *ps.signs as taxis,
	sum(sumposo) *ps.signs as sumposo

	
from fortotikes f
join KINDPARASTATIKON kp on kp.ID=f.IDPARAST 
join parastatika_sign ps on ps.ID=f.IDPARAST
where isnull(f.ifDelete,0)!=1
and kp.IfFortotiki=1
and kp.KindKINISIS in (1,5)
and isnull(kp.IF_FROM_ANTAP,0)=0
and isnull(f.ifdelete,0)=0
group by convert(date,dateprint),PARASTATIKO,ps.signs, f.IDPARAST, f.IDYPOKATASTIMA

union all

select

	convert(date,dateprint) as dateprint,
	count(v.id) as count_row,
	v.IDYPOKATASTIMA,
	v.IDPARAST,
	parastatiko,
	sum(POSO) * ps.signs as poso,
	sum(TAXIS) * ps.signs as taxis,
	sum(SUMPOSO) * ps.signs as sumposo

from voh v
join KINDPARASTATIKON kp on kp.ID=v.IDPARAST 
join parastatika_sign ps on ps.ID=v.IDPARAST
where isnull(v.ifDelete,0)!=1 and  v.IDPARAST not in ( select
TRANSFORMTO
from KINDPARASTATIKON  where IF_ENIMEROSIKARTELA!=1 and KindKINISIS in (1,5) 
AND IF_TRANSFORM=1)
and kp.IF_ORDER!=1
and isnull(v.ifdelete,0)=0
group by convert(date,dateprint),PARASTATIKO,ps.signs, v.IDPARAST, v.IDYPOKATASTIMA

GO


---END SCRIPT 2041
