ALTER view [dbo].[LOGISTIKI_EPSILON_EISPRAKSEIS_PLIROMES_C_CATEGORY] AS
select
	kdp.ID																AS KID,
	cast(r.id as int)													AS IDVOH,
	r.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'1'																	AS IF_RECEIPTS,
	'0'																	AS IF_PAYMENTS,
	pel.id																AS ACCOUNT_ID,
	convert(date,r.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('800'+ convert(nvarchar(10),r.id))									AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΤΑΜ'																AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	pel.AFM																AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),r.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	r.KINDPARASTDESCR													AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Code															AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))							AS 'ΑΡΙΘΜΟΣ',
	pel.CodeLog															AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	r.sumposo* kdp.KindYpologismou										AS 'ΑΞΙΑ',
	r.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	r.IF_EXPORTED
	
from receipts r
join accounts pel on pel.id = r.IDCUSTOMER
join kindparastatikon kdp on kdp.id=r.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=r.IDYPOKATASTIMA


UNION ALL

select
	kdp.ID																AS KID,
	cast(r.id as int)													AS IDVOH,
	r.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'1'																	AS IF_RECEIPTS,
	'0'																	AS IF_PAYMENTS,
	pel.id																AS ACCOUNT_ID,
	convert(date,r.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('800'+ convert(nvarchar(10),r.id))									AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΤΑΜ'																AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	pel.AFM																AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),r.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	r.KINDPARASTDESCR													AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Code															AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))							AS 'ΑΡΙΘΜΟΣ',
	case 
		WHEN kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and r.IDYPOKATASTIMA=2 then kp.CodeLog
		when kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and r.IDYPOKATASTIMA=17 then '38-00-00-0001'
	else kp.CodeLog															
	END																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	r.sumposo* kdp.KindYpologismou										AS 'ΑΞΙΑ',
	r.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	r.IF_EXPORTED
	
from KINDOFPAYMENTS kp
join receipts r on r.IDKINDPAYMENT=kp.ID
join accounts pel on pel.id = r.IDCUSTOMER
join kindparastatikon kdp on kdp.id=r.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=r.IDYPOKATASTIMA

union all

select
	kdp.ID																AS KID,
	cast(p.id as int)													AS IDVOH,
	P.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'0'																	AS IF_RECEIPTS,
	'1'																	AS IF_PAYMENTS,
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.id
	else pel.id			
	end AS ACCOUNT_ID,
	convert(date,p.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('900'+ convert(nvarchar(10),p.id))									AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΤΑΜ'																AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.AFM
		else PEL.AFM																
	END AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),p.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	p.KINDPARASTDESCR													AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Code															AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))							AS 'ΑΡΙΘΜΟΣ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.CodeLog
	else pel.CodeLog										
	end AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	p.IF_EXPORTED
	
from PAYMENTS p
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=p.IDYPOKATASTIMA

union all

select
	kdp.ID																AS KID,
	cast(p.id as int)													AS IDVOH,
	P.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'0'																	AS IF_RECEIPTS,
	'1'																	AS IF_PAYMENTS,
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.id
	else pel.id			
	end AS ACCOUNT_ID,
	convert(date,p.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('900'+ convert(nvarchar(10),p.id))									AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΤΑΜ'																AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.AFM
		else PEL.AFM																
	END AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),p.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	p.KINDPARASTDESCR													AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Code															AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))							AS 'ΑΡΙΘΜΟΣ',
	case 
		WHEN kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=2 then kp.CodeLog
		when kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=17 then '38-00-00-0001'
	else kp.CodeLog															
	END																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	p.IF_EXPORTED
	
from KINDOFPAYMENTS kp
join PAYMENTS p on p.IDKINDPAYMENT=kp.ID
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=p.IDYPOKATASTIMA

GO




---END SCRIPT 2046
