	ROW_NUMBER() OVER(PARTITION BY GV.IDVOH ORDER BY GV.ID) ROW_NUM,
	GV.DescrEidos,
	GV.TEMAXIA QTY,

	BASICUNIT.AADE_UNIT_TYPE BASIC_UNIT_AADE_CODE, 

