	PERIOXIPARADOSIS,
	OMADPROORISMOS,
	OXIMA,
	IDKINDPAYMENT,
	KINDPAYMENTDESCR,
	AITIOLOGIAPARASTATIKOU,
	DATEFORTOSIS,
	NOPARASTDELTIOUAPOSTOLIS,
	NOPARASTDELTIOUDIANOMIS,
	IFEPISTROFI,
	DATEEPISTROFIS,
	AITIOLOGIAEPISTROFIS,
	COMMENTSEPISTROFIS,
	COMMENTS,
	COMMENTS2,
	IFCASH,
	IFPISTOSI,
	IFPREPAY,
	IFOFEILOMENI,
	IDPRAKTOREIO,
	PRAKTOREIODESCR,
	YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
	IFEPANADROMOLOGISI,
	IFEPANEKDOSI,
	IFOKEPANADROMOLOGISI,
	NOPARASTANTIK,
	COMMENTSAKIROSIS,
	STATUSDESCR,
	IDDRIVER,
	DRIVERDESCR,
	IFEXOFLISI,
	STATUS,
	DATEPARAL,
	DATEPARAD,
	COMMENTSPARAD,
	COMMANTSPARAL,
	TIMEPARALFROM,
	TIMEPARALTO,
	TIMEPARADFROM,
	TIMEPARADTO,
	ANAMEXODO,
	AFMAPOSTOLEA,
	AFMENTOLEA,
	AFMPARALIPTI,
	AFMTRITOU,
	AFMANTAPOKRITI,
	AFMXREOUMENOU,
