	IDXRHSHS,
	IDCOMPANY,
	IDYPOKATASTIMA,
	IDWAREHOUSE,
	UntRatio,
	IF_PRODROMOL,
	IFASFALISTRA,
	ASFALISTRAPERCENT,
	NO_EXT_ORDER,
	OROFOS,
	EXT_BARCODE,
	OROFOSDESCR,
	KOUDOUNI,
	IDSKOPOSDIAKINISIS,
	SKOPOSDIAKINISIS,	
	DateCreate,
	UserCreate)
		VALUES (@SEIRA, @NOPARAST, @IDPARAST, @PARASTATIKO, @IFXRAPOST, @IFXRPARAL, @IFXRENTOL, @IFXRTRITOU, @IDAPOSTOLEA, @APOSTOLEASDESCR, @IDPARALIPTI, @PARALISPTISDESCR, @IDENTOLEA, @ENTOLEASDESCR, @IDTRITOU, @TRITOSDESCR, @IDANTAPOKRITI, @ANTAPOKRITISDESCR, @IDXREOUMENOU, @DATEPRINT, @POSO, @TAXISPERCENT, @TAXIS, @SUMPOSO, @IFANTIKCASH, @IFANTIKEPIT, @IFANTIKSYNAL, @IFANTIKOTHER, @ANTIKCASH, @ANTIKEPIT, @ANTIKSYNAL, @ANTIKOTHER, @SUMANTIK, @EXODATRITON, @IFCANCELANTIK, @DATECANCELANTIK, @COMMENTSANTIK, @IFPARADOSI, @DATEPARADOSI, @IFCANCEL, @DATECANCEL, @PERIOXIFORTOSIS, @PERIOXIPARADOSIS, @OMADPROORISMOS, @OXIMA, @IDKINDPAYMENT, @KINDPAYMENTDESCR, @AITIOLOGIAPARASTATIKOU, @DATEFORTOSIS, @NOPARASTDELTIOUAPOSTOLIS, @NOPARASTDELTIOUDIANOMIS, @IFEPISTROFI, @DATEEPISTROFIS, @AITIOLOGIAEPISTROFIS, @COMMENTSEPISTROFIS, @COMMENTS, @COMMENTS2, @IFCASH, @IFPISTOSI, @IFPREPAY, @IFOFEILOMENI, @IDPRAKTOREIO, @PRAKTOREIODESCR, @YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
		@IFEPANADROMOLOGISI, @IFEPANEKDOSI, @IFOKEPANADROMOLOGISI, @NOPARASTANTIK, @COMMENTSAKIROSIS, @STATUSDESCR, @IDDRIVER, @DRIVERDESCR, @IFEXOFLISI, @STATUS, @DATEPARAL, @DATEPARAD, @COMMENTSPARAD, @COMMANTSPARAL, @TIMEPARALFROM, @TIMEPARALTO, @TIMEPARADFROM, @TIMEPARADTO, @ANAMEXODO, @AFMAPOSTOLEA, @AFMENTOLEA, @AFMPARALIPTI, @AFMTRITOU, @AFMANTAPOKRITI, @AFMXREOUMENOU, @IFPARADOSITOPEL, @IFPARALABIFROMPEL, @NOLISTASDIANOMIS, @AA_ANTIK, @CONTAINER, @BOAT, @IDXRHSHS, @IDCOMPANY, @IDYPOKATASTIMA, @IDWAREHOUSE, @UntRatio, @IF_PRODROMOL, @IFASFALISTRA, @ASFALISTRAPERCENT, @NO_EXT_ORDER, @OROFOS, @EXT_BARCODE, @OROFOSDESCR, @KOUDOUNI, @IDSKOPOSDIAKINISIS, @SKOPOSDIAKINISIS,	@DateCreate, @UserCreate)

	SELECT
		@TheID = MAX(ID)
	FROM dbo.PROFORTOTIKES WITH (NOLOCK)

	IF LEN(ISNULL(@EXT_BARCODE, '')) = 0
	BEGIN
		UPDATE p
		SET EXT_BARCODE = c.BARCODE_Prefix + '0' + CONVERT(VARCHAR, p.ID)
		FROM PROFORTOTIKES p
		JOIN COMPANIES c ON c.ID = p.IDYPOKATASTIMA
		WHERE p.ID = @TheID
	END

	WAITFOR DELAY '00:00:00:40'
	COMMIT;
GO

