ALTER VIEW [dbo].[AADE_INVOICES] AS
SELECT
	FORT.ID INVOICEID,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	
	FORT.DATEPRINT,
	FORT.IDXREOUMENOU COUNTERPART_ID,
	FORT.IDAPOSTOLEA SENDER_ID,
	FORT.IDPARALIPTI RECIPIENT_ID,
	FORT.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(FORT.TAXIS) INVOICE_TAX_SUM,
	ABS(FORT.POSO) INVOICE_NET_SUM,
	ABS(FORT.SUMPOSO) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
	NULL [OXIMA] ,
	CASE 
		WHEN KP.AADE_CODE = '9.3' THEN 19
		ELSE NULL
	END [SKOPOSDIAKINISIS],
	NULL [DISPATCHED_DATE],
	NULL [DISPATCHED_TIME],
	FORT.IDYPOKATASTIMA,
	FORT.IF_ENIM_AADE,
	0 [IF_VOH_SALES],
	KP.IF_PEPPOL,
	FORT.PEPPOL_PARTY_IDENTIFICATION,
	FORT.PEPPOL_PROJECT_REFERENCE,
	FORT.PEPPOL_DUE_DATE
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
JOIN ACCOUNTS CUST ON CUST.ID = FORT.IDXREOUMENOU
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(FORT.ifDelete,0)!=1
UNION
SELECT
	VOH.ID INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	VOH.DATEPRINT,
	VOH.IDCUSTOMER COUNTERPART_ID,
	VOH.IDAPOSTOLEA SENDER_ID,
	VOH.IDPARALIPTI RECIPIENT_ID,
	VOH.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(VOH.TAXIS+VOH.TAXISEPIVAR) INVOICE_TAX_SUM,
	ABS(VOH.POSO+VOH.POSOEPIVAR) INVOICE_NET_SUM,
	ABS(VOH.SUMPOSO+VOH.SUMPOSOEPIVAR) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE,
	PAYMENTS.AADE_CODE,
	CASE KP.KINDKINISIS
		WHEN 5 THEN VOH.OXIMA
		ELSE NULL
	END [OXIMA] ,
	
	SKD.AADE_CODE SKOPOSDIAKINISIS,
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,23) 
		ELSE NULL
	END [DISPATCHED_DATE],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,8)
		ELSE NULL
	END  [DISPATCHED_TIME],

	VOH.IDYPOKATASTIMA,
	VOH.IF_ENIM_AADE,
	CASE KP.KindKINISIS
		WHEN 5 THEN 1 
		ELSE 0
	END [IF_VOH_SALES],
	KP.IF_PEPPOL,
	VOH.PEPPOL_PARTY_IDENTIFICATION,
	VOH.PEPPOL_PROJECT_REFERENCE,
	VOH.PEPPOL_DUE_DATE
FROM VOH 
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
left JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
JOIN COMPANIES YPOKAT ON YPOKAT.id = VOH.IDYPOKATASTIMA
LEFT JOIN SKOPOSDIAKINISIS SKD ON SKD.ID=VOH.IDSKOPOSDIAKINISIS
JOIN ACCOUNTS CUST ON CUST.ID = VOH.IDCUSTOMER
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(VOH.ifDelete,0)!=1
GO

---END SCRIPT 2082
------------------------------------------------------------------------------------


---NEW SCRIPT 2083

ALTER VIEW [dbo].[AADE_INVOICE_DETAILS] 
AS
-- ΦΟΡΤΩΤΙΚΕΣ
WITH COUNTANAVOH AS (
	SELECT 
		IDVOH,
		COUNT(*) COUNT
	FROM GRAMMESVOH
	GROUP BY IDVOH
)


SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	--XAD2.TAXIS VAT_AMOUNT,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	XR.AADE_CATEGORY_CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	XR.AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_FORTOTIKI = 1
UNION
-- ΠΑΡΟΧΗΣ ΥΠΗΡΕΣΙΩΝ 
-- ΠΡΕΠΕΙ ΝΑ ΜΠΕΙ ΚΑΠΟΙΟ ΕΠΙΠΛΕΟΝ ΦΙΛΤΡΟ ΣΤΑ WHERE
-- ΓΙΑ ΝΗ ΜΗΝ ΦΕΡΝΕΙ ΤΑ ΤΗΣ ΠΩΛΗΣΗΣ ΕΔΩ
SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	--XAD2.TAXIS VAT_AMOUNT,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	
	XR.AADE_CATEGORY_CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	XR.AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
--JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN VOH ON VOH.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 1 AND ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_VOH = 1

UNION

-- ΠΩΛΗΣΗΣ!

SELECT
	GV.ID ,
	GV.IDVOH INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	1 IF_POLISI,
	0 IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY GV.IDVOH ORDER BY GV.ID) ROW_NUM,
	GV.TEMAXIA QTY,
	ABS(GV.TELTIMI) NET_AMOUNT,
	TAXIS.AADE_CODE ,
	ABS(GV.SUMTAXIS) VAT_AMOUNT,
	'category1_2',
	'E3_561_001',
	NULL,
	PR.PEPPOL_CPV,
	PR.PEPPOL_MEASUREMENT_UNIT_ID
FROM GRAMMESVOH GV
JOIN PRODUCTS PR ON PR.Code = GV.CodeEidos
LEFT JOIN Taxis ON Taxis.id = PR.ID_TAXIS
JOIN VOH ON VOH.ID = GV.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 5 
AND ABS(GV.SUMPOSO) > 0
--WHERE GV.IDVOH = 2036


UNION

-- ΠΩΛΗΣΗΣ ΜΕ ΜΕΤΑΦΟΡΑ !

SELECT
	NULL,
	VOH.ID,
	0,
	1,
	1,
	0,
	COUNTANAVOH.COUNT + 1,
	1,
	ABS(POSOEPIVAR),
	TAXIS.AADE_CODE,
	ABS(TAXISEPIVAR),
	'category1_3',
	'E3_561_001',
	NULL,
	NULL PEPPOL_CPV,
	NULL PEPPOL_MEASUREMENT_UNIT_ID
FROM VOH
JOIN COUNTANAVOH ON COUNTANAVOH.IDVOH = VOH.ID
JOIN KINDPARASTATIKON ON KINDPARASTATIKON.ID = VOH.IDPARAST
LEFT JOIN Taxis on TAXIS.Pososto = KINDPARASTATIKON.TAXISPERCENT
WHERE ABS(POSOEPIVAR) > 0



GO


---END SCRIPT 2083
------------------------------------------------------------------------------------


