ALTER PROCEDURE [dbo].[InserttoCATPARAST]
(
	
	@AFORA						NVARCHAR(100),
	@PARASTATIKO				NVARCHAR(150),
	@IDAFORA					NUMERIC(8,0)= NULL,
	@IDKINDPARAST				NUMERIC(8,0)= NULL,
	@KINDENIMEROSI				NUMERIC(8,0)= NULL,
	@IDCATPARAST				NUMERIC(8,0)= NULL,
	@IFENIMEROSITAMEIO			NUMERIC(8,0)= NULL,
	@CODEPARAST					NVARCHAR(15)= NULL,
	@TRANSFORMTO				NVARCHAR(15)=NULL,
	@IF_AUTONUMBER				INT= 0,
	@IF_TRANSFORM				INT= 0,
	@AUTONUMBER_FROM			NUMERIC(8,0)= 0,
	@IF_ZERO_ON_NEW_YEAR		INT= 0,
	@IF_PRINT					INT=0,
	@PREPORT					NVARCHAR(255),
	@TAXISPERCENT				NUMERIC(18,0)=0,
	@IF_XREOSI					INT= 0,
	@IfMisthodosia				INT=0,
	@IfFortotiki				INT=0,
