	K_P.copies,
	K_P.if_enimerosiapothiki,
	K_P.if_paroxiypiresion,
	K_P.idcompany,
	K_P.if_aforaextriton,
	K_P.idypokatastima,
	K_P.if_listadianomis,
	K_P.codelog,
	K_P.ifeisagogi,
	K_P.ifexagogi,
	K_P.if_order,
	K_P.isnoactive,
	K_P.if_prodromol,
	K_P.if_apografi,
	K_P.ifreceiptantik,
	K_P.if_apogr_pel,
	K_P.if_apogr_apothikis,
	K_P.if_apogr_prom,
	K_P.vouchertypecode,
