  FROM   cat_parastatikon AS CAT_PAR WITH (nolock)
  INNER JOIN parastatika_ana_kathgoria AS PAC WITH (nolock) ON CAT_PAR.id = PAC.id_cat_parastatikon
  INNER JOIN kindparastatikon AS K_P WITH (nolock) ON PAC.id_kindparastatikon = K_P.id
