ALTER PROCEDURE [dbo].[updateCATPARAST]
(
	@IDPARAST					NUMERIC(8,0)= NULL,
	--@AFORA						NVARCHAR(100),
	@PARASTATIKO				NVARCHAR(150),
	@Abbreviation				nvarchar(25)=null,
	@IDAFORA					NUMERIC(8,0)= NULL,
	@IDKINDPARAST				NUMERIC(8,0)= NULL,
	@KINDENIMEROSI				NUMERIC(8,0)= NULL,
	@IDCATPARAST				NUMERIC(8,0)= NULL,
	@IFENIMEROSITAMEIO			NUMERIC(8,0)= NULL,
	@CODEPARAST					NVARCHAR(15)= NULL,
	@TRANSFORMTO				NVARCHAR(15)=NULL,
	@IF_AUTONUMBER				INT= 0,
	@IF_TRANSFORM				INT= 0,
	@AUTONUMBER_FROM			NUMERIC(8,0)= 0,
	@IF_ZERO_ON_NEW_YEAR		INT= 0,
	@IF_PRINT					INT=0,
	@PREPORT					NVARCHAR(255),
	@REPORT_PATH_FOR_EMAILS		NVARCHAR(255),
	@TAXISPERCENT				NUMERIC(18,2)=0,
	@IF_XREOSI					INT= 0,
	@IfMisthodosia				INT=0,
	@IfFortotiki				INT=0,
	@IF_PISTOSI					INT= 0,
	@IfKAA						INT= 0,
	@IF_ENIMEROSIKARTELA		INT= 0,
	@IF_LISTADIANOMIS			INT = 0,
	@IF_XREOSIKARTELA			INT= 0,
	@IF_PISTOSIKARTELA			INT= 0,
	@IFKEPXREOSI				INT= 0,
	@IFKEPPISTOSI				INT= 0,
	@IFPROFORTOTIKI				INT= 0,
	@IFKEPYO					INT= 0,
	@IF_LISTAANTIKATABOLON		INT = 0,
	--@IFCASH						int = NULL,
	--@IFPISTOSI					int = NULL,
	--@IFOFEILOMENI				int = NULL,
	--@IFPREPAY					int = NULL,
	@CATKEPYO					int = 0,
	@SEIRA						NVARCHAR(5),
	@PROEPSXOLIO				NVARCHAR(150) = NULL,
	@PrinterName				NVARCHAR(50) = NULL,
	@IfPreviewFirst				int = 0,
	@PRINTLABEL					NVARCHAR(50),
	@IDPARASTEXOFLISI			NUMERIC(18,0)=0,
	@DESCRPARASTEXOFLISI		NVARCHAR(30),
	@IF_ENIMEROSIAPOTHIKI		INT =0,
	@IFEXAGOGI					INT =0,
	@IFEISAGOGI					INT =0,
	@IF_PAROXIYPIRESION			INT =0,
	@IF_ORDER					INT = 0,
	@IF_PRODROMOL				INT = 0,
	@IF_FROM_ANTAP				INT = 0,
	@IDCOMPANY					numeric(18,0) =0,
	@IDYPOKATASTIMA				numeric(18,0) =0,
	@CodeLog					NVARCHAR(30),
	@Copies						int = 1,
	@IF_EDMETAFORAS				INT = 0,
	@IF_EDSYNARMOL				INT = 0,
	@IS_CANCELLATION			INT = 0,
	@IF_LISTA_ASS				INT = 0,
	@IfReceiptAntik				INT = 0,
	--@IF_EDTOPOTH				INT = 0,
	@WEBPARASTATIKO				INT = 0,
	@IF_ENIMEROSI_AADE			INT = 0,
	@AADE_CODE					NVARCHAR(30),
	@IDSKOPOSDIAKINISIS			numeric (18, 0)= NULL,
	@SKOPOSDIAKINISIS			nvarchar (50)= NULL,
	@VoucherTypeCode			NVARCHAR(3),
	@IDCURRENCY					NUMERIC(5, 0) = NULL,
	@IF_PEPPOL					Bit = 0,
	@IF_ENIMEROSI_FPA			INT = 0
		)
AS
-- TASK 
-- TASK 
	DECLARE @KINDKINISIS 	INT
	DECLARE @TRACOUNT 	INT
	DECLARE @ErrorNumber 	INT
	DECLARE @ErrorDescription NVARCHAR(255)
	DECLARE @Rowcount	INT
	DECLARE @RetVal 	INT
	DECLARE @Number 	NVARCHAR(30)	
	DECLARE @IDOC_COMM	INT
	DECLARE @IDOC_XRE	INT
	DECLARE @CAN_PRINT   	BIT
	DECLARE @ID 		INT
	DECLARE @RET_BATCH_NUM	NVARCHAR(30)
	DECLARE @Courier_Group_Code NVARCHAR(5)

	SET NOCOUNT ON
	SET @ErrorNumber = 0

	SET @TRACOUNT = @@TRANCOUNT
	IF @TRACOUNT = 0 
	--EISAGOGI TOY PARALIPTI EAN DEN YPARXEI STO PINAKA MAS
	--***************************************************************************
	DECLARE @RowCountPelati INT
	DECLARE @ClientCode INT
	DECLARE @ClientTownCode NVARCHAR(10)
	DECLARE @ClientRegionCode NVARCHAR(10) --TASK 12899
	DECLARE @PelatesAddr	NVARCHAR(60) --TASK 11593
	DECLARE @PelatesProfID	NVARCHAR(30) --TASK 11623
	SET @RowCountPelati=0

	IF @IDAFORA = 0
		BEGIN 	
			SET @KINDKINISIS = 1 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 1
		BEGIN 	
			SET @KINDKINISIS = 0 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 4
		BEGIN 	
			SET @KINDKINISIS = 99 --@KINDKINISIS = 1
		END 
		
	IF @IDAFORA = 5
		BEGIN 	
			SET @KINDKINISIS = 5 --@KINDKINISIS = 1
		END 
	IF @IDAFORA = 6
		BEGIN 	
			SET @KINDKINISIS = 6 --@KINDKINISIS = 1
		END 


		BEGIN
			UPDATE KINDPARASTATIKON
				SET
				Code					=		@CODEPARAST,
				Descr					=		@PARASTATIKO,
				Abbreviation			=		@Abbreviation,
				KindKINISIS				=		@KINDKINISIS,
				KindYpologismou			=		@KINDENIMEROSI,
				IFENIMEROSITAMEIO		=		@IFENIMEROSITAMEIO,
				TRANSFORMTO				=		@TRANSFORMTO,
				IF_AUTONUMBER			=		@IF_AUTONUMBER,
				IF_TRANSFORM			=		@IF_TRANSFORM,
				AUTONUMBER_FROM			=		@AUTONUMBER_FROM,
				IF_ZERO_ON_NEW_YEAR		=		@IF_ZERO_ON_NEW_YEAR,
				IF_PRINT				=		@IF_PRINT,
				PREPORT					=		@PREPORT,
				REPORT_PATH_FOR_EMAILS	=		@REPORT_PATH_FOR_EMAILS,
				TAXISPERCENT			=		@TAXISPERCENT,
				IF_XREOSI				=		@IF_XREOSI,
				IF_PISTOSI				=		@IF_PISTOSI,
				IfMisthodosia			=		@IfMisthodosia,
				IfFortotiki				=		@IfFortotiki,
				IfKAA					=		@IfKAA,
				IF_ENIMEROSIKARTELA		=		@IF_ENIMEROSIKARTELA,
				IF_XREOSIKARTELA		=		@IF_XREOSIKARTELA,
				IF_PISTOSIKARTELA		=		@IF_PISTOSIKARTELA,
				SEIRA					=		@SEIRA,
				IFKEPXREOSI				=		@IFKEPXREOSI,
				IFKEPPISTOSI			=		@IFKEPPISTOSI,
				IFPROFORTOTIKI			=		@IFPROFORTOTIKI,
				IFKEPYO					=		@IFKEPYO,
				PRINTLABEL				=		@PRINTLABEL,
				PROEPSXOLIO				=		@PROEPSXOLIO,
				IfPreviewFirst			=		@IfPreviewFirst,
				PrinterName				=		@PrinterName,
				IDPARASTEXOFLISI		=		@IDPARASTEXOFLISI,
				DESCRPARASTEXOFLISI		=		@DESCRPARASTEXOFLISI, 
				IF_ENIMEROSIAPOTHIKI	=		@IF_ENIMEROSIAPOTHIKI,
				IFEISAGOGI				=		@IFEISAGOGI,
				IFEXAGOGI				=		@IFEXAGOGI,	
				IF_PAROXIYPIRESION		=		@IF_PAROXIYPIRESION,
				IF_ORDER				=		@IF_ORDER,
				IDCOMPANY				=		@IDCOMPANY,
				IDYPOKATASTIMA			=		@IDYPOKATASTIMA,
				IF_LISTADIANOMIS		=		@IF_LISTADIANOMIS,
				IF_PRODROMOL			=		@IF_PRODROMOL,
				IF_LISTAANTIKATABOLON	=		@IF_LISTAANTIKATABOLON,
				IF_FROM_ANTAP			=		@IF_FROM_ANTAP,
				--IFPISTOSI				=		@IFPISTOSI,
				--IFOFEILOMENI			=		@IFOFEILOMENI,
				--IFPREPAY				=		@IFPREPAY,
				CATKEPYO				=		@CATKEPYO,
				CodeLog					=		@CodeLog,	
				Copies					=		@Copies,
				IF_EDMETAFORAS			=		@IF_EDMETAFORAS,
				IF_EDSYNARMOL			=		@IF_EDSYNARMOL,
				IS_CANCELLATION			=		@IS_CANCELLATION,
				IF_LISTA_ASS			=		@IF_LISTA_ASS,
				WEBPARASTATIKO			=		@WEBPARASTATIKO,
				IF_ENIMEROSI_AADE		=		@IF_ENIMEROSI_AADE,
				AADE_CODE				=		@AADE_CODE,
				IDSKOPOSDIAKINISIS			=	@IDSKOPOSDIAKINISIS,
				SKOPOSDIAKINISIS			=	@SKOPOSDIAKINISIS,
				IfReceiptAntik			=		@IfReceiptAntik,
				--IF_EDTOPOTH				=		@IF_EDTOPOTH,
				VoucherTypeCode			=		@VoucherTypeCode,
				IDCURRENCY				=		@IDCURRENCY,
				IF_PEPPOL				=		@IF_PEPPOL,
				IF_ENIMEROSI_FPA		=		@IF_ENIMEROSI_FPA

				WHERE ID = @IDPARAST
		END
--'''''''''''''''''''''''''''''''''''''''''''''''''''
		BEGIN
			DELETE FROM PARASTATIKA_ANA_KATHGORIA WHERE ID_KINDPARASTATIKON = @IDPARAST --AND  ID_CAT_PARASTATIKON = @IDCATPARAST
			INSERT INTO PARASTATIKA_ANA_KATHGORIA
				(
				ID_CAT_PARASTATIKON,
				ID_KINDPARASTATIKON
				)
			VALUES
				(
				@IDCATPARAST,
				@IDPARAST
				)
		END
--...................................................
	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************


ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint
GO

---END SCRIPT 2093
------------------------------------------------------------------------------------

---NEW SCRIPT 2094

ALTER TABLE FORTOTIKES ADD IF_TRANSMISSION_FAILURE NVARCHAR(100) NULL
GO
ALTER TABLE VOH ADD IF_TRANSMISSION_FAILURE NVARCHAR(100) NULL
GO


ALTER TRIGGER [dbo].[AADE_URL] 
   ON  [dbo].[FORTOTIKES]
   AFTER INSERT
AS 
BEGIN
	UPDATE F SET QRURL='Απώλεια Διασύνδεσης',IF_TRANSMISSION_FAILURE='Απώλεια Διασύνδεσης'
	
	FROM FORTOTIKES F
	JOIN KINDPARASTATIKON KP ON KP.ID=F.IDPARAST
	join inserted ins on ins.id=f.id
	--join updated upd on upd.id=f.id
	WHERE ISNULL(KP.IF_ENIMEROSI_AADE,0)=1
		AND ISNULL(F.QRURL,'')=''
END

GO


ALTER TRIGGER [dbo].[AADE_URL_1] 
   ON  [dbo].[VOH]
   AFTER INSERT
AS 
BEGIN
	UPDATE v SET QRURL='Απώλεια Διασύνδεσης',IF_TRANSMISSION_FAILURE='Απώλεια Διασύνδεσης'
	
	FROM VOH V
	JOIN KINDPARASTATIKON KP ON KP.ID=v.IDPARAST
	join inserted ins on ins.id=v.id
	--join updated upd on upd.id=f.id
	WHERE ISNULL(KP.IF_ENIMEROSI_AADE,0)=1
		AND ISNULL(V.QRURL,'')=''
END

GO
---END SCRIPT 2094
------------------------------------------------------------------------------------


---NEW SCRIPT 2095

ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS

WITH GRAMMES AS 
	(
	SELECT
		IDVOH,
		ISNULL(MIN(TIMDA),'')				  AS TIMDA,
		Isnull(Sum(temaxia), 0)               AS TEMAXIA,
		MIN(u.untname)						  AS SYSKEVASIA,
        Isnull(Sum(baros), 0)                 AS BAROS,
        Isnull(Sum(kybika), 0)                AS KYBIKA,
        ISNULL(MIN(PERIEXOMENO),'')    		  AS PERIEXOMENO,
        ISNULL(SUM(SUMPOSO),0)				  AS AXIA
	FROM GRAMMESFORTTIKIS
	left join Units u on u.UntID = GRAMMESFORTTIKIS.SYSKEVASIA
	GROUP BY IDVOH
	),
POSA AS 
	(
	SELECT 
		ID,
		SUMPOSO,
		ROUND(FORTOTIKES.POSO, 2) AS KATHARO,
		ROUND(FORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
		ROUND(FORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT
	FROM FORTOTIKES
	),
header as
	(
		select 
			IDFORT,
			ROUND(isnull(SUM(hd.komistra),0),2)				  AS  KOMISTRA,
			ROUND(ISNULL(SUM(hd.DIKAIOMAFORTOTIKIS),0),2)     AS DIKAIOMAFORTOTIKIS,
			ROUND(ISNULL(SUM(HD.OTHERXREOSIS),0),2)			  AS OTHERXREOSIS,
			ROUND(ISNULL(SUM(HD.OLIKOSYNOLOXREOSEONFORT),0),2) AS OLIKOSYNOLOXREOSEONFORT,
			ROUND(ISNULL(SUM(HD.ERGATIKA),0),2)				  AS ERGATIKA,
			ROUND(ISNULL(SUM(HD.ASFALISTRA),0),2)			  AS ASFALISTRA,
			ROUND(ISNULL(SUM(HD.TAXIS),0),2)				  AS TAXIS,
			ROUND(ISNULL(SUM(HD.SUMPOSOXRFORT),0),2)		  AS SUMPOSOXRFORT,
			ROUND(ISNULL(SUM(HD.KATHARO),0),2)				  AS KATHARO
			
		from HEADERFORTOTIKIS hd
		GROUP BY IDFORT
	),
parastatika_sign as (
					select 
						id,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
)	
	
select

	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	Cast(f.noparast AS INT)								AS NOPARAST,
	f.noparastdeltioudianomis,
	f.noparastdeltiouapostolis,
	f.oxima,
	f.omadproorismos,
	CASE f.ifxrentol *1 + f.ifxrapost *2 + f.ifxrparal * 4 + f.ifxrtritou * 8
           WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
           WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
           WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
           WHEN 8 THEN 'ΤΡΙΤΟΣ'
    ELSE 'ΑΓΝΩΣΤΟ'					
    END													AS XREOYMENOS,
    f.apostoleasdescr,
	f.paralisptisdescr,
	f.entoleasdescr,
	f.antapokritisdescr,
	f.nolistasdianomis,
	TRITO.eponimia										AS TRITOSDESCR,
	GR.TIMDA,
	ISNULL(f.POSO,0)*ps.signs									AS POSO,
	ISNULL(f.TAXIS,0)*ps.signs									AS TAXIS,
	ISNULL(f.SUMPOSO,0)*ps.signs								AS SUMPOSO,
	gr.TEMAXIA,
	gr.BAROS,
	gr.KYBIKA,
	gr.SYSKEVASIA,
	CASE F.IFPREPAY 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE F.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFCASH 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFPISTOSI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GR.PERIEXOMENO,
    f.PERIOXIFORTOSIS,
    f.perioxiparadosis,
    f.comments,
    ISNULL(f.sumantik,0)								AS SUMANTIK,
    f.praktoreiodescr,
    f.status,
    f.idapostolea,
    f.idparalipti,
    f.identolea,
    f.idantapokriti,
    f.idtritou,
    f.idpraktoreio,
    CASE ifantikcash
       WHEN 0 THEN 0
       ELSE antikcash
	END                                                 AS ANTIKCASH,
    CASE ifantikepit
      WHEN 0 THEN 0
      ELSE antikepit
    END                                                 AS ANTIKEPIT,
    CASE ifantiksynal
       WHEN 0 THEN 0
       ELSE antiksynal
    END                                                 AS ANTIKSYNAL,
    CASE ifantikother
       WHEN 0 THEN 0
       ELSE antikother
    END                                                 AS ANTIKOTHER,
    CASE ifcancelantik
       WHEN 0 THEN 'ΟΧΙ'
       ELSE 'ΝΑΙ'
    END                                                 AS IFCANCELANTIK,
   f.commentsantik,
   f.dateparadosi,
   f.comments2,
   HD.komistra *ps.signs			                    AS KOMISTRA,
   f.exodatriton		                                AS XREOSISTRITON,
   HD.dikaiomafortotikis *ps.signs				        AS DIKAIOMAFORTOTIKIS,
   HD.otherxreosis	*ps.signs			                AS OTHERXREOSIS,
   HD.olikosynoloxreoseonfort	*ps.signs			    AS OLIKOSYNOLOXREOSEONFORT,
   HD.ergatika  *ps.signs			                    AS ERGATIKA,
        
   CASE f.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFPREPAY,
         CASE f.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFOFEILOMENI,
         GR.AXIA								        AS AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRENTOL,
         f.kindpaymentdescr,
         f.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRTRITOU, 
         f.ifantikcash,
         f.ifantikepit,
         f.ifantiksynal,
         f.ifantikother,
         f.ifdelete,
         f.ifcancel,   
         f.aa_antik,
         f.nolistasantik,
         f.ifparadosi,
         f.aitiologiaparastatikou,
         CONVERT(VARCHAR, f.datefortosis, 103)			AS DATEFORTOSIS,
         f.ifepistrofi,
         f.DATEEPISTROFIS,
         f.dromologio,
         f.thesi,
         f.aitiologiaepistrofis,
         f.commentsepistrofis,
         f.ifcash,
         f.ifpistosi,
         f.statusdescr,
         f.ypaitios,
         f.ifepanadromologisi,
         f.ifepanekdosi,
         f.ifokepanadromologisi,
         f.noparastantik,
         f.commentsakirosis,
         f.ifeisprantik,
         f.ifparadosiantik,
         f.ifparalaviantik,
         f.commentsparadantik,
         f.commantsparalantik,
         f.commentseisprantik,
         CONVERT(VARCHAR, f.dateparadantik, 102)		AS DATEPARADANTIK,
         CONVERT(VARCHAR, f.dateeisprantik, 102)		AS DATEEISPRANTIK,
         f.eispraxasantik,
         f.noparparadantik,
         f.noparasteisprantik,
         f.noparparalantik,
         f.commentsparad,
         f.commantsparal,
         f.if_transftoesex,
         f.timeparalfrom,
         f.timeparalto,
         f.timeparadfrom,
         f.timeparadto,
         CONVERT(VARCHAR, f.datecancelantik, 102)		AS DATECANCELANTIK,
         f.idparast,
         f.taxispercent,
         f.anamexodo,
         f.id											AS IDFORTOTIKIS,
         f.afmxreoumenou, 
		 HD.asfalistra *ps.signs						as ASFALISTRA,
         HD.TAXIS *ps.signs								AS TAXISXREOSEON,
         HD.sumposoxrfort *ps.signs						AS sumposoxrfort,
         HD.katharo *ps.signs							AS katharo,
         f.orofos,
         f.orofosdescr,
         f.koudouni,
         APOST.epagelma                                 AS EPAGAPOST,
         APOST.AddressCountry							AS COUNTRYAPOST,
         APOST.addressstr                               AS ADDRSTRAPOST,
         APOST.addressno                                AS ADDRNOAPOST,
         APOST.addresstk                                AS TKAPOST,
         APOST.addresscity                              AS CITYAPOST,
         APOST.addresspref                              AS NOMOSAPOST,
         APOST.tel                                      AS TELAPOST,
         APOST.tel2                                     AS TEL2APOST,
         APOST.fax                                      AS FAXAPOST,
         APOST.doy                                      AS DOYAPOST,
         PARAL.epagelma                                 AS EPAGPARAL,
         PARAL.AddressCountry							AS COUNTRYPARAL,
         PARAL.addressstr                               AS ADDRSTRPARAL,
         PARAL.addressno                                AS ADDRNOPARAL,
         PARAL.addresstk                                AS ADDRTKPARAL,
         PARAL.addresscity                              AS ADDRCITYPARAL,
         PARAL.addresspref                              AS ADDRNOMOSPARAL,
         PARAL.tel                                      AS TELPARAL,
         PARAL.tel2                                     AS TEL2PARAL,
         PARAL.fax                                      AS FAXPARAL,
         PARAL.doy                                      AS DOYPARAL,
         ENTOL.epagelma                                 AS EPAGENTOL,
         ENTOL.AddressCountry							AS COUNTRYENTOL,
         ENTOL.addressstr                               AS ADDRSTRENTOL,
         ENTOL.addressno                                AS ADDRNOENTOL,
         ENTOL.addresstk                                AS ADDRTKENTOL,
         ENTOL.addresscity                              AS ADDRCITYENTOL,
         ENTOL.addresspref                              AS ADDRNOMOSENTOL,
         ENTOL.tel                                      AS TELENTOL,
         ENTOL.tel2                                     AS TEL2ENTOL,
         ENTOL.fax                                      AS FAXENTOL,
         ENTOL.doy                                      AS DOYENTOL,
        
         CAST(XREOYM.KINDPAYMENTDESCR AS NVARCHAR(50))+ ' ' + CONVERT(NVARCHAR(20),XREOYM.PayAfter_Days)+ ' ' + 'Ημερών'  AS PAYAFTERDAYS,
         XREOYM.PayAfter_Days							AS PAYMENT_DAYS,
         
