ALTER VIEW [dbo].[VOH_VIEW]
AS

WITH GRAMMES AS 
	(
		SELECT 
			IDVOH,
			ISNULL(Min(dbo.grammesvoh.timda),'')                 AS TIMDA,
            Isnull(Sum(dbo.grammesvoh.temaxia), 0)               AS TEMAXIA,
            Isnull(Sum(dbo.grammesvoh.baros), 0)                 AS BAROS,
            Isnull(Sum(dbo.grammesvoh.kybika), 0)                AS KYBIKA,
            ISNULL(MIN(PERIEXOMENO),'')							 AS PERIEXOMENO,
            ISNULL(SUM(SUMPOSO),0)								 AS AXIA
		
		FROM GRAMMESVOH
		GROUP BY IDVOH
	),
XREOSIS AS	(
		SELECT 
			IDVOH,
			SUM(SUMPOSO) AS SUPOSO
			
		FROM XREOSISANADELTIO
		WHERE IF_TO_VOH=1
			
		GROUP BY IDVOH
		),
parastatika_sign as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS KPSIGN
				from KINDPARASTATIKON kp
				)

SELECT

	V.ID,
	V.DATEPRINT,
	KP.Code,
	V.PARASTATIKO,
	V.SEIRA,
	CAST(V.NOPARAST AS NVARCHAR(15)) [NOPARAST],
	V.CustDescr,
	V.EPAGELMA,
	V.AFM,
	V.CITY,
	V.TEL,
	V.MOBILE,
	V.POSO * PS.KPSIGN AS POSO,
	V.TAXIS * PS.KPSIGN AS TAXIS,
	V.SUMPOSO * PS.KPSIGN AS SUMPOSO,
	V.KINDPAYMENTDESCR,
	V.EXT_BARCODE,
	V.OXIMA,
	V.OMADPROORISMOS,
	V.SXETIKAPARASTATIKA,
	CASE V.IFXRENTOL * 1 + V.IFXRAPOST * 2 + V.IFXRTRITOU * 4 + V.IFXRPARAL * 8
		WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
		WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
		WHEN 4 THEN 'ΤΡΙΤΟΣ'
		WHEN 8 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
		ELSE 'ΑΓΝΩΣΤΟ'
	END AS XREOYMENOS,
	  V.noparastdeltioudianomis,
      V.noparastdeltiouapostolis,
      GRAMMES.TIMDA,
      GRAMMES.TEMAXIA,
      GRAMMES.BAROS,
      GRAMMES.KYBIKA,
      CASE V.IFPREPAY
		WHEN 1 THEN XREOSIS.SUPOSO * PS.KPSIGN
		ELSE 0
	  END AS XREOSIPROPLIROMENES,
	  CASE V.IFOFEILOMENI
		WHEN 1 THEN XREOSIS.SUPOSO * PS.KPSIGN
		ELSE 0
	  END AS XREOSIOFEILOMENES,
	  GRAMMES.PERIEXOMENO,
	  V.perioxifortosis,
      V.perioxiparadosis,
      V.comments,
      V.sumantik,
      V.praktoreiodescr,
      V.status,
      V.dateparad,
      V.idpraktoreio,
      CASE V.IFANTIKCASH
        WHEN 0 THEN 0
        ELSE V.ANTIKCASH
      END AS ANTIKCASH,
      CASE V.IFANTIKEPIT
        WHEN 0 THEN 0
        ELSE V.ANTIKEPIT
      END AS ANTIKEPIT,
      CASE V.IFANTIKSYNAL
        WHEN 0 THEN 0
        ELSE V.ANTIKSYNAL
      END AS ANTIKSYNAL,
      CASE V.IFANTIKOTHER
        WHEN 0 THEN 0
        ELSE V.ANTIKOTHER
      END AS ANTIKOTHER,
      CASE V.IFCANCELANTIK
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFCANCELANTIK,
      V.commentsantik,
      V.dateparadosi,
      V.comments2,
      hv.KOMISTRA * PS.KPSIGN AS KOMISTRA,
      hv.XREOSISTRITON,
      hv.DIKAIOMAFORTOTIKIS * PS.KPSIGN AS DIKAIOMAFORTOTIKIS,
      hv.OTHERXREOSIS * PS.KPSIGN AS OTHERXREOSIS,
      CASE V.ifprepay
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFPREPAY,
      CASE V.ifofeilomeni
        WHEN 1 THEN 'ΝΑΙ'
        ELSE 'ΟΧΙ'
      END AS IFOFEILOMENI,
      GRAMMES.AXIA,
      CASE V.IFXRENTOL
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRENTOL,
      V.idkindpayment,
      CASE V.IFXRAPOST
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRAPOST,
      CASE V.IFXRPARAL
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRPARAL,
      CASE V.IFXRTRITOU
        WHEN 0 THEN 'ΟΧΙ'
        ELSE 'ΝΑΙ'
      END AS IFXRTRITOU,
      V.ifantikcash,
      V.ifantikepit,
      V.ifantiksynal,
      V.ifantikother,
      V.ifdelete,
      V.ifcancel,
      V.datecancel,
      V.ifparadosi,
      V.aitiologiaparastatikou,
      V.datefortosis,
      V.ifepistrofi,
      V.dateepistrofis,
      V.aitiologiaepistrofis,
      V.commentsepistrofis,
