left join KINDPARASTATIKON kp on kp.ID=v.IDPARAST
left join grammesvohsum gv on gv.IDVOH=v.ID
left join grammesfortotikissum gf on gf.IDVOH=v.ID
left join xreosisanadeltiosum xd on xd.IDVOH=v.ID
left join headerfortotikissum hf on hf.IDFORT=v.ID
left join HEADERFORTOTIKIS hdf on hdf.idfort=v.ID
left join ACCOUNTS apost on apost.id=v.IDAPOSTOLEA
left join ACCOUNTS entol on entol.id=v.IDENTOLEA
left join ACCOUNTS paral on paral.id=v.IDPARALIPTI
left join ACCOUNTS tritos on tritos.id=v.IDTRITOU
left join PARADOSEIS parad  on parad.IDVOH=(select max( id)from VOH)
left join KentraKostous kns on kns.id=v.IDKENTROUKOSTOUS
left join grammes_assembly gva on gva.IDVOH=v.ID
left join COMPANIES ypok on ypok.id=v.IDYPOKATASTIMA
LEFT JOIN COMPANIES COMP ON COMP.ID=V.IDCOMPANY
LEFT JOIN Banks BANKS_A ON BANKS_A.FSBANKS_ID=YPOK.IDBANKA
LEFT JOIN Banks BANKS_B ON BANKS_B.FSBANKS_ID=YPOK.IDBANKB
LEFT JOIN Banks BANKS_C ON BANKS_C.FSBANKS_ID=YPOK.IDBANKC
LEFT JOIN Banks BANKS_D ON BANKS_D.FSBANKS_ID=YPOK.IDBANKD
LEFT JOIN CURRENCY CUR ON CUR.ID=kp.IDCURRENCY
LEFT JOIN QRURLPERVOHINVOICE ON QRURLPERVOHINVOICE.INVOICEID =  V.ID





