	@IDPARAST					NUMERIC(8,0)= NULL,
	@PARASTATIKO				NVARCHAR(50)= NULL,
	@IFXRAPOST					INT= 0,
	@IFXRPARAL					INT= 0,
	@IFXRENTOL					INT= 0,
	@IFXRTRITOU					INT= 0,
	@IDAPOSTOLEA				NUMERIC(8,0)= NULL,
	@APOSTOLEASDESCR			NVARCHAR(50)= NULL,
	@IDPARALIPTI				NUMERIC(8,0)= NULL,
	@PARALISPTISDESCR			NVARCHAR(50)= NULL,
