	@CODEAPOSTOLEA				NVARCHAR(50)= NULL,
	@CODEPARALIPTI				NVARCHAR(50)= NULL,
	@IDTRITOU					NUMERIC(8,0)= NULL,
	@TRITOSDESCR				NVARCHAR(50)= NULL,
	@IDANTAPOKRITI				NUMERIC(8,0)= NULL,
	@ANTAPOKRITISDESCR			NVARCHAR(50)= NULL,
	@DATEPRINT					SMALLDATETIME= NULL,
	@POSO						NUMERIC(8,2)= NULL,
	@TAXISPERCENT				NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,
	@IFANTIKCASH				INT= 0,
	@IFANTIKEPIT				INT= 0,
	@IFANTIKSYNAL				INT= 0,
	@IFANTIKOTHER				INT= 0,
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	@SUMANTIK					NUMERIC(8,2)= NULL,
	@IFCANCELANTIK				INT= 0,
	@DATECANCELANTIK			SMALLDATETIME= NULL,
