---NEW SCRIPT 2105


ALTER view [dbo].[AADE_INVOICES_ALL]
AS
SELECT
    FORT.ID INVOICEID,
    FORT.DATEPRINT,
    FORT.PARASTATIKO,
    LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
    FORT.NOPARAST INVOICE_NUMBER,
    ACC.AFM,
    ACC.Eponimia AS COUNTERPART,
    FORT.POSO INVOICE_NET_SUM,
    FORT.TAXIS INVOICE_TAX_SUM,
    FORT.SUMPOSO INVOICE_GROSS_SUM,
    FORT.IF_ENIM_AADE,
    CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
    Acr.AcrPrefix,
    KP.AADE_CODE INVOICE_AADE_CODE,
    PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
    FORT.AADE_UID,
    FORT.AADE_MARK,
    FORT.AADE_AUTHENTICATION_CODE,
    FORT.AADE_CANCELLATION_MARK,
    1 IF_TO_FORTOTIKI,
    0 IF_TO_VOH,
    CASE KP.CATKEPYO
        WHEN 1 THEN 1
        ELSE 0
    END IF_LIANIKI,
    FORT.IDXREOUMENOU COUNTERPART_ID,
    --=FORT.DATEPRINT INVOICE DATE,
    --DATEPRINT INVOICE_DATE,
    FORT.IF_CANCEL,
    FORT.IDPARAST,
    FORT.IDCOMPANY,
    FORT.IDYPOKATASTIMA,
    FORT.ifDelete
FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = FORT.IDXREOUMENOU
LEFT JOIN Acr ON Acr.AcrName = ACC.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
UNION
SELECT
    VOH.ID INVOICEID,
    VOH.DATEPRINT,
    VOH.PARASTATIKO,
    LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
    VOH.NOPARAST INVOICE_NUMBER,
    ACC.AFM,
    ACC.Eponimia AS COUNTERPART,
    VOH.POSO INVOICE_NET_SUM,
    VOH.TAXIS INVOICE_TAX_SUM,
    VOH.SUMPOSO INVOICE_GROSS_SUM,
    VOH.IF_ENIM_AADE,
    CURRENCY.AADE_CODE CURRENCY_AADE_CODE,    
    Acr.AcrPrefix,
    KP.AADE_CODE INVOICE_AADE_CODE,
    PAYMENTS.AADE_CODE PAYMENT_AADE_CODE,
    VOH.AADE_UID,
    VOH.AADE_MARK,
    VOH.AADE_AUTHENTICATION_CODE,
    VOH.AADE_CANCELLATION_MARK,
    0 IF_TO_FORTOTIKI,
    1 IF_TO_VOH,
    CASE KP.CATKEPYO
        WHEN 1 THEN 1
        ELSE 0
    END IF_LIANIKI,
    VOH.IDCUSTOMER COUNTERPART_ID,
    --=FORT.DATEPRINT INVOICE DATE,
    --DATEPRINT INVOICE_DATE,
    VOH.IF_CANCEL,
    VOH.IDPARAST,
    VOH.IDCOMPANY,
    VOH.IDYPOKATASTIMA,
    VOH.ifDelete
FROM VOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
left JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
LEFT JOIN ACCOUNTS ACC ON ACC.ID = VOH.IDCUSTOMER
LEFT JOIN Acr ON Acr.AcrName = ACC.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0


GO


---END SCRIPT 2105
------------------------------------------------------------------------------------
------------------------------------------------------------------------------------

---NEW SCRIPT 2106

ALTER view [dbo].[AADE_INVOICE_DETAILS] 
AS
-- ΦΟΡΤΩΤΙΚΕΣ
WITH COUNTANAVOH AS (
	SELECT 
		IDVOH,
		COUNT(*) COUNT
	FROM GRAMMESVOH
	GROUP BY IDVOH
)


SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	XR.AADE_CATEGORY_CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	XR.AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID,
	case
		when XR.ifKomistra=1 then 'Κόμιστρα'
		when XR.ifDikaiomaFortotikis=1 then 'Δικ.Φορ/κης'
		when XR.ifErgatika=1 then 'Εργατικά'
		when XR.IfAsfalistra=1 then 'Ασφάλιστρα'
		when XR.ifOther=1 then 'Λοιπά'
		when XR.IfEmvastika=1 then 'Εμβαστικά'
		else 'Καθ.Αξία' 
	end as XREOSI_ALIAS	
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_FORTOTIKI = 1
UNION
-- ΠΑΡΟΧΗΣ ΥΠΗΡΕΣΙΩΝ 
-- ΠΡΕΠΕΙ ΝΑ ΜΠΕΙ ΚΑΠΟΙΟ ΕΠΙΠΛΕΟΝ ΦΙΛΤΡΟ ΣΤΑ WHERE
-- ΓΙΑ ΝΗ ΜΗΝ ΦΕΡΝΕΙ ΤΑ ΤΗΣ ΠΩΛΗΣΗΣ ΕΔΩ
SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	XR.AADE_CATEGORY_CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	XR.AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID,
	case
		when XR.ifKomistra=1 then 'Κόμιστρα'
		when XR.ifDikaiomaFortotikis=1 then 'Δικ.Φορ/κης'
		when XR.ifErgatika=1 then 'Εργατικά'
		when XR.IfAsfalistra=1 then 'Ασφάλιστρα'
		when XR.ifOther=1 then 'Λοιπά'
		when XR.IfEmvastika=1 then 'Εμβαστικά'
		else 'Καθ.Αξία' 
	end as XREOSI_ALIAS	
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
--JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN VOH ON VOH.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 1 AND ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_VOH = 1

UNION

-- ΠΩΛΗΣΗΣ!

SELECT
	GV.ID ,
	GV.IDVOH INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	1 IF_POLISI,
	0 IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY GV.IDVOH ORDER BY GV.ID) ROW_NUM,
	GV.TEMAXIA QTY,
	ABS(GV.TELTIMI) NET_AMOUNT,
	TAXIS.AADE_CODE ,
	ABS(GV.SUMTAXIS) VAT_AMOUNT,
	'category1_2',
	'E3_561_001',
	NULL,
	PR.PEPPOL_CPV,
	PR.PEPPOL_MEASUREMENT_UNIT_ID,
	'Καθ.Αξία' XREOSI_ALIAS	
FROM GRAMMESVOH GV
JOIN PRODUCTS PR ON PR.Code = GV.CodeEidos
LEFT JOIN Taxis ON Taxis.id = PR.ID_TAXIS
JOIN VOH ON VOH.ID = GV.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 5 
AND ABS(GV.SUMPOSO) > 0
--WHERE GV.IDVOH = 2036


UNION

-- ΠΩΛΗΣΗΣ ΜΕ ΜΕΤΑΦΟΡΑ !

SELECT
	NULL,
	VOH.ID,
	0,
	1,
	1,
	0,
	COUNTANAVOH.COUNT + 1,
	1,
	ABS(POSOEPIVAR),
	TAXIS.AADE_CODE,
	ABS(TAXISEPIVAR),
	'category1_3',
	'E3_561_001',
	NULL,
	NULL PEPPOL_CPV,
	NULL PEPPOL_MEASUREMENT_UNIT_ID,
	'Καθ.Αξία' XREOSI_ALIAS	
FROM VOH
JOIN COUNTANAVOH ON COUNTANAVOH.IDVOH = VOH.ID
JOIN KINDPARASTATIKON ON KINDPARASTATIKON.ID = VOH.IDPARAST
LEFT JOIN Taxis on TAXIS.Pososto = KINDPARASTATIKON.TAXISPERCENT
WHERE ABS(POSOEPIVAR) > 0




GO



---END SCRIPT 2106
