	@PEPPOL_PROJECT_REFERENCE	NVARCHAR(100) = NULL,
	@PEPPOL_DUE_DATE			DATE = NULL,
	@YPAITIOS					INT= 0, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
	@IFEPANADROMOLOGISI			INT= 0,
	@IFEPANEKDOSI				INT= 0,
	@IFOKEPANADROMOLOGISI		INT= 0,
	@NOPARASTANTIK				NVARCHAR(50),
	@COMMENTSAKIROSIS			NVARCHAR(MAX),
	@DateMod					DATETIME,-- = NULL,
	@UserMod					NVARCHAR(50),

	@STATUS						INT= 0
	)
AS


SET NOCOUNT ON;
			UPDATE FORTOTIKES 
				SET 
				SEIRA						=	@SEIRA,
				NOPARAST					=	@NOPARAST,
				IFXRAPOST					=	@IFXRAPOST,
				IFXRPARAL					=	@IFXRPARAL,
				IFXRENTOL					=	@IFXRENTOL,
				IFXRTRITOU					=	@IFXRTRITOU,
				IDAPOSTOLEA					=	@IDAPOSTOLEA,
				APOSTOLEASDESCR				=	@APOSTOLEASDESCR,
				IDPARALIPTI					=	@IDPARALIPTI,
				PARALISPTISDESCR			=	@PARALISPTISDESCR,
				IDENTOLEA					=	@IDENTOLEA,
				ENTOLEASDESCR				=	@ENTOLEASDESCR,
				IDTRITOU					=	@IDTRITOU,
				TRITOSDESCR					=	@TRITOSDESCR,
				IDANTAPOKRITI				=	@IDANTAPOKRITI,
				ANTAPOKRITISDESCR			=	@ANTAPOKRITISDESCR,
				DATEPRINT					=	@DATEPRINT,
				POSO						=	@POSO,
				TAXISPERCENT				=	@TAXISPERCENT,
				TAXIS						=	@TAXIS,
				SUMPOSO						=	@SUMPOSO,
				IFANTIKCASH					=	@IFANTIKCASH,
				IFANTIKEPIT					=	@IFANTIKEPIT,
				IFANTIKSYNAL				=	@IFANTIKSYNAL,
				IFANTIKOTHER				=	@IFANTIKOTHER,
				ANTIKCASH					=	@ANTIKCASH,
				ANTIKEPIT					=	@ANTIKEPIT,
				ANTIKSYNAL					=	@ANTIKSYNAL,
				ANTIKOTHER					=	@ANTIKOTHER,
				SUMANTIK					=	@SUMANTIK,
				IFCANCELANTIK				=	@IFCANCELANTIK,
				DATECANCELANTIK				=	@DATECANCELANTIK,
				COMMENTSANTIK				=	@COMMENTSANTIK,
				IFPARADOSI					=	@IFPARADOSI,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL					=	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				PERIOXIFORTOSIS				=	@PERIOXIFORTOSIS,
				PERIOXIPARADOSIS			=	@PERIOXIPARADOSIS,
				OMADPROORISMOS				=	@OMADPROORISMOS,
				OXIMA						=	@OXIMA,
				IDKINDPAYMENT				=	@IDKINDPAYMENT,
				KINDPAYMENTDESCR			=	@KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU		=	@AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS				=	@DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS	=	@NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS		=	@NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI					=	@IFEPISTROFI,
				DATEEPISTROFIS				=	@DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS		=	@AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS			=	@COMMENTSEPISTROFIS,
				COMMENTS					=	@COMMENTS,
				IFCASH						=	@IFCASH,
				IFPISTOSI					=	@IFPISTOSI,
				IFPREPAY					=	@IFPREPAY,
				IFOFEILOMENI				=	@IFOFEILOMENI,
				IDPRAKTOREIO				=	@IDPRAKTOREIO,
				PRAKTOREIODESCR				=	@PRAKTOREIODESCR,
				YPAITIOS					=	@YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI			=	@IFEPANADROMOLOGISI,
				IFEPANEKDOSI				=	@IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI		=	@IFOKEPANADROMOLOGISI,
				NOPARASTANTIK				=	@NOPARASTANTIK,
				COMMENTSAKIROSIS			=	@COMMENTSAKIROSIS,
				IF_PEPPOL					=	@IF_PEPPOL,
				PEPPOL_PARTY_IDENTIFICATION	=	@PEPPOL_PARTY_IDENTIFICATION,
				PEPPOL_PROJECT_REFERENCE	=	@PEPPOL_PROJECT_REFERENCE,
				PEPPOL_DUE_DATE				=	@PEPPOL_DUE_DATE,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod,
				STATUS						=	@STATUS

WHERE ID  = @ID

;

set ANSI_NULLS ON
set QUOTED_IDENTIFIER ON




GO



