	@EXT_BARCODE							NVARCHAR (150) =NULL,
	@IF_ZERO_ON_NEW_YEAR					INT = 0,
	@IfParadsePrakt							INT = 0,
	@DateParadsePrakt						SMALLDATETIME = NULL,
	@CommentsParadsePrakt					NVARCHAR(MAX) = NULL,
	@IDSKOPOSDIAKINISIS						numeric (18, 0)= NULL,
	@SKOPOSDIAKINISIS						nvarchar (50)= NULL,
	@IF_PEPPOL								BIT = 0,
	@PEPPOL_PARTY_IDENTIFICATION			 NVARCHAR(100) = NULL,
	@PEPPOL_PROJECT_REFERENCE				NVARCHAR(100) = NULL,
	@PEPPOL_DUE_DATE						DATE = NULL,
	@SymvBtoG								nvarchar (50)= NULL,	
	@PEPPOL_BUYERREFERENCE					NVARCHAR(50)= NULL,
	@PEPPOL_INVOICEDOCUMENTREFERENCE		NVARCHAR(50)= NULL,
	@PEPPOL_PURCHASEORDERREFERENCE			nvarchar(150)= NULL,
	@PEPPOL_SALESORDERREFERENCE				nvarchar(150)= NULL,
	@TheID									NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoFORTOTIKES', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000

--SELECT @@SPID [session_id], @RC [return code], GETDATE()

set @IFAUTONUMBER = (select isnull(if_autonumber,0) from KINDPARASTATIKON where ID=@IDPARAST)

IF @IFAUTONUMBER = 1 BEGIN 
	IF @IF_ZERO_ON_NEW_YEAR = 1 BEGIN
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM FORTOTIKES 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
		AND YEAR(DATEPRINT) = YEAR(@DATEPRINT)
	END
	ELSE BEGIN	
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM FORTOTIKES 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
	END
	
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END



	
	--GO
			INSERT INTO FORTOTIKES
				(
				SEIRA,
				NOPARAST,
				IDPARAST,
				PARASTATIKO,
				IFXRAPOST,
				IFXRPARAL,
