				PERIOXIFORTOSIS,
				PERIOXIPARADOSIS,
				OMADPROORISMOS,
				OXIMA,
				IDKINDPAYMENT,
				KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI,
				DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS,
				COMMENTS,
				COMMENTS2,
				IFCASH,
				IFPISTOSI,
				IFPREPAY,
				IFOFEILOMENI,
				IDPRAKTOREIO,
				PRAKTOREIODESCR,
				YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI,
				IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI,
				NOPARASTANTIK,
				COMMENTSAKIROSIS,
				STATUSDESCR,
				IDDRIVER,
				DRIVERDESCR,
				IFEXOFLISI,
				STATUS,
				DATEPARAL,
				DATEPARAD,
				COMMENTSPARAD,
				COMMANTSPARAL,
				TIMEPARALFROM,
				TIMEPARALTO,
				TIMEPARADFROM,
				TIMEPARADTO,
				ANAMEXODO,
				AFMAPOSTOLEA,
				AFMENTOLEA,
				AFMPARALIPTI,
				AFMTRITOU,
				AFMANTAPOKRITI,
				AFMXREOUMENOU,
				IFPARADOSITOPEL,
				IFPARALABIFROMPEL,
				NOLISTASDIANOMIS,
				AA_ANTIK,
				CONTAINER,
				BOAT,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				IFASFALISTRA,
				ASFALISTRAPERCENT,
				POD_PATH_2,
				NO_EXT_ORDER,
				DROMOLOGIO,
				THESI,
				OROFOS,
				EXT_BARCODE,
				OROFOSDESCR,				
				KOUDOUNI,
				ARANAFORAS,
				FILE_PHOTO,
				IfParadsePrakt,
				IDSKOPOSDIAKINISIS,
				SKOPOSDIAKINISIS,
				IF_PEPPOL,
				PEPPOL_PARTY_IDENTIFICATION,
				PEPPOL_PROJECT_REFERENCE,
				PEPPOL_DUE_DATE,
				SymvBtoG,
				PEPPOL_BUYERREFERENCE,
				PEPPOL_INVOICEDOCUMENTREFERENCE,
				PEPPOL_PURCHASEORDERREFERENCE,
				PEPPOL_SALESORDERREFERENCE,			
				DateParadsePrakt,
				CommentsParadsePrakt,
				DateCreate,
				UserCreate
				)
			VALUES
				(
				@SEIRA,
				@NOPARAST,
