				@IfPlacement,
				@IfAssembly,
				@IfDisAssembly
				)
IF LEN(@IDORDER) > 0
	BEGIN
		UPDATE VOH SET IF_CLOSE = 1 WHERE ID = @IDORDER 
	END
	--SELECT  @TheID = MAX(ID) FROM dbo.VOH WITH (NOLOCK)
	SELECT @TheID = SCOPE_IDENTITY()
waitfor delay '00:00:00:40'            
commit;


GO


---END SCRIPT 2123
