ALTER view [dbo].[AADE_INVOICES] AS
SELECT
	FORT.ID INVOICEID,
	1 IF_TO_FORTOTIKI,
	0 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	
	FORT.DATEPRINT,
	FORT.IDXREOUMENOU COUNTERPART_ID,
	FORT.IDAPOSTOLEA SENDER_ID,
	FORT.IDPARALIPTI RECIPIENT_ID,
	FORT.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(FORT.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(FORT.TAXIS) INVOICE_TAX_SUM,
	ABS(FORT.POSO) INVOICE_NET_SUM,
	ABS(FORT.SUMPOSO) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE CURRENCY_AADE_CODE,
	isnull(PAYMENTS.AADE_CODE,5) PAYMENT_AADE_CODE,
	NULL [OXIMA] ,
	CASE 
		WHEN KP.AADE_CODE = '9.3' THEN 19
		ELSE NULL
	END [SKOPOSDIAKINISIS],
	NULL [DISPATCHED_DATE],
	NULL [DISPATCHED_TIME],
	FORT.IDYPOKATASTIMA,
	FORT.IF_ENIM_AADE,
	0 [IF_VOH_SALES],
	KP.IF_PEPPOL,
	FORT.PEPPOL_PARTY_IDENTIFICATION,
	FORT.PEPPOL_PROJECT_REFERENCE,
	CONVERT(NVARCHAR, FORT.PEPPOL_DUE_DATE, 127) PEPPOL_DUE_DATE,
	SymvBtoG,
	CASE WHEN LEN(PEPPOL_BUYERREFERENCE) > 1 THEN PEPPOL_BUYERREFERENCE ELSE NULL END PEPPOL_BUYERREFERENCE,
	CASE WHEN LEN(PEPPOL_INVOICEDOCUMENTREFERENCE) > 1 THEN PEPPOL_INVOICEDOCUMENTREFERENCE ELSE NULL END PEPPOL_INVOICEDOCUMENTREFERENCE,
	CASE WHEN LEN(PEPPOL_SALESORDERREFERENCE) > 1 THEN PEPPOL_SALESORDERREFERENCE ELSE NULL END PEPPOL_SALESORDERREFERENCE,
	CASE WHEN LEN(PEPPOL_PURCHASEORDERREFERENCE) > 1 THEN PEPPOL_PURCHASEORDERREFERENCE ELSE NULL END PEPPOL_PURCHASEORDERREFERENCE,
	IDSYSXETIZOMENOU,
	FORT.IF_TRANSMISSION_FAILURE

FROM FORTOTIKES FORT
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = FORT.IDKINDPAYMENT
JOIN ACCOUNTS CUST ON CUST.ID = FORT.IDXREOUMENOU
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(FORT.ifDelete,0)!=1
UNION
SELECT
	VOH.ID INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	CASE KP.CATKEPYO
		WHEN 1 THEN 1
		ELSE 0
	END IF_LIANIKI,
	CASE 
		WHEN ISNULL(KP.CATKEPYO, 0) = 1 THEN 0
		ELSE 1
	END IncludeCounterpart,
	CASE 
		WHEN (ISNULL(CUSTCNTRY.AcrPrefix, 'GR') <> 'GR'  OR ISNULL(CUST.CATKEPYO, 0) = 4) THEN 1
		ELSE 0
	END IncludeCounterpartName,
	VOH.DATEPRINT,
	VOH.IDCUSTOMER COUNTERPART_ID,
	ISNULL(VOH.IDAPOSTOLEA, 0) SENDER_ID,
	isnull(VOH.IDPARALIPTI,0) RECIPIENT_ID,
	VOH.NOPARAST INVOICE_NUMBER,
	LTRIM(RTRIM(ISNULL(VOH.SEIRA, ''))) INVOICE_SERIES,
	--=FORT.DATEPRINT INVOICE DATE,
	DATEPRINT INVOICE_DATE,
	ABS(VOH.TAXIS+VOH.TAXISEPIVAR) INVOICE_TAX_SUM,
	ABS(VOH.POSO+VOH.POSOEPIVAR) INVOICE_NET_SUM,
	ABS(VOH.SUMPOSO+VOH.SUMPOSOEPIVAR) INVOICE_GROSS_SUM,
	KP.AADE_CODE INVOICE_AADE_CODE,
	CURRENCY.AADE_CODE,
	isnull(PAYMENTS.AADE_CODE,5) PAYMENT_AADE_CODE,
	CASE KP.KINDKINISIS
		WHEN 5 THEN VOH.OXIMA
		ELSE NULL
	END [OXIMA] ,
	
	SKD.AADE_CODE SKOPOSDIAKINISIS,
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,23) 
		ELSE NULL
	END [DISPATCHED_DATE],
	
	CASE KP.KINDKINISIS
		WHEN 5 THEN CONVERT(NVARCHAR(20),VOH.DATEPRINT,8)
		ELSE NULL
	END  [DISPATCHED_TIME],

	VOH.IDYPOKATASTIMA,
	VOH.IF_ENIM_AADE,
	CASE KP.KindKINISIS
		WHEN 5 THEN 1 
		ELSE 0
	END [IF_VOH_SALES],
	KP.IF_PEPPOL,
	VOH.PEPPOL_PARTY_IDENTIFICATION,
	VOH.PEPPOL_PROJECT_REFERENCE,
	CONVERT(NVARCHAR, VOH.PEPPOL_DUE_DATE, 127) PEPPOL_DUE_DATE,
	SymvBtoG,
	CASE WHEN LEN(PEPPOL_BUYERREFERENCE) > 1 THEN PEPPOL_BUYERREFERENCE ELSE NULL END PEPPOL_BUYERREFERENCE,
	CASE WHEN LEN(PEPPOL_INVOICEDOCUMENTREFERENCE) > 1 THEN PEPPOL_INVOICEDOCUMENTREFERENCE ELSE NULL END PEPPOL_INVOICEDOCUMENTREFERENCE,
	CASE WHEN LEN(PEPPOL_SALESORDERREFERENCE) > 1 THEN PEPPOL_SALESORDERREFERENCE ELSE NULL END PEPPOL_SALESORDERREFERENCE,
	CASE WHEN LEN(PEPPOL_PURCHASEORDERREFERENCE) > 1 THEN PEPPOL_PURCHASEORDERREFERENCE ELSE NULL END PEPPOL_PURCHASEORDERREFERENCE,
	IDSYSXETIZOMENOU,
	VOH.IF_TRANSMISSION_FAILURE
FROM VOH 
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
JOIN CURRENCY ON CURRENCY.ID = KP.IDCURRENCY
left JOIN KINDOFPAYMENTS PAYMENTS ON PAYMENTS.ID = VOH.IDKINDPAYMENT
JOIN COMPANIES YPOKAT ON YPOKAT.id = VOH.IDYPOKATASTIMA
LEFT JOIN SKOPOSDIAKINISIS SKD ON SKD.ID=VOH.IDSKOPOSDIAKINISIS
JOIN ACCOUNTS CUST ON CUST.ID = VOH.IDCUSTOMER
LEFT JOIN Acr CUSTCNTRY on CUSTCNTRY.AcrName = CUST.AddressCountry
WHERE KP.IF_ENIMEROSI_AADE = 1
AND KP.IS_CANCELLATION = 0
AND ISNULL(VOH.ifDelete,0)!=1


GO


---END SCRIPT 2129
