---NEW SCRIPT 2133


ALTER VIEW [dbo].[AADE_PISTOTIKA] AS

select
	pistotiko.ID idpistotikou,
	original.id idoriginal,
	0 IF_TO_FORT,
	1 IF_TO_VOH,
	comp.afm + '|' + 
	convert(nvarchar, original.DATEPRINT, 101) + '|' + 
	convert(nvarchar, ypokat.AAYPOKATASTHMA) + '|' + 
	kp_original.AADE_CODE + '|' + 
	CASE WHEN LEN(LTRIM(RTRIM(kp_original.SEIRA)))>0 THEN LTRIM(RTRIM(kp_original.SEIRA)) else 'ΑΝΕΥ' end + '|'  +
	original.NOPARAST PRIMERID

from VOH pistotiko
join VOH original on original.id = pistotiko.IDSYSXETIZOMENOU
join KINDPARASTATIKON kp_original on kp_original.ID = original.IDPARAST
join companies ypokat on ypokat.id = original.IDYPOKATASTIMA
join companies comp on comp.id = ypokat.IDPARENTCOMPANY

union

select
	pistotiko.ID idpistotikou,
	original.id idoriginal,
	1 IF_TO_FORT,
	0 IF_TO_VOH,
	comp.afm + '|' + 
	convert(nvarchar, original.DATEPRINT, 101) + '|' + 
	convert(nvarchar, ypokat.AAYPOKATASTHMA) + '|' + 
	kp_original.AADE_CODE + '|' + 
	CASE WHEN LEN(LTRIM(RTRIM(kp_original.SEIRA)))>0 THEN LTRIM(RTRIM(kp_original.SEIRA)) else 'ΑΝΕΥ' end + '|'  +
	original.NOPARAST

from FORTOTIKES pistotiko
join FORTOTIKES original on original.id = pistotiko.IDSYSXETIZOMENOU
join KINDPARASTATIKON kp_original on kp_original.ID = original.IDPARAST
join companies ypokat on ypokat.id = original.IDYPOKATASTIMA
join companies comp on comp.id = ypokat.IDPARENTCOMPANY

GO

---END SCRIPT 2133
