	@AFMENTOLEA								NVARCHAR (20) =NULL,
	@AFMPARALIPTI							NVARCHAR (20) =NULL,
	@AFMTRITOU								NVARCHAR (20) =NULL,
	@AFMANTAPOKRITI							NVARCHAR (20) =NULL,
	@NOLISTASDIANOMIS						NVARCHAR (10) =NULL,
	@IFAUTONUMBER							int =0,
	@IFPARADOSITOPEL						int =0,
	@IFPARALABIFROMPEL						int =0,
	@AFMXREOUMENOU							NVARCHAR(20) = NULL,
	@CONTAINER								NVARCHAR (50) =NULL,
	@BOAT									NVARCHAR (50) =NULL,
	@IDXRHSHS								NUMERIC(18,0) = 0,
	@IDCOMPANY								NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA							NUMERIC(18,0) = 0,
	@IFASFALISTRA							int =0,
	@ASFALISTRAPERCENT						NUMERIC(18,0) = 0,
	@POD_PATH_2								NVARCHAR (MAX) =NULL,
	@NO_EXT_ORDER							NVARCHAR(50) = NULL,
	@DROMOLOGIO								NVARCHAR (50) =NULL,
	@THESI									NVARCHAR(50) = NULL,
	@OROFOS									NUMERIC(5,2) = 0.00,
	@OROFOSDESCR							NVARCHAR(100) =NULL,
	@KOUDOUNI								NVARCHAR(100) =NULL,
	@FILE_PHOTO								NVARCHAR(MAX)= NULL,
	@EXT_BARCODE							NVARCHAR (150) =NULL,
	@IfParadsePrakt							INT = 0,
	@DateParadsePrakt						SMALLDATETIME = NULL,
	@CommentsParadsePrakt					NVARCHAR(MAX) = NULL,
	@IF_PEPPOL								BIT = 0,
	@PEPPOL_PARTY_IDENTIFICATION			NVARCHAR(100) = NULL,
	@PEPPOL_PROJECT_REFERENCE				NVARCHAR(100) = NULL,
	@PEPPOL_DUE_DATE						DATE = NULL,
	@SymvBtoG								nvarchar (50)= NULL,	
	@PEPPOL_BUYERREFERENCE					NVARCHAR(50)= NULL,
	@PEPPOL_INVOICEDOCUMENTREFERENCE		NVARCHAR(50)= NULL,
	@PEPPOL_PURCHASEORDERREFERENCE			nvarchar(150)= NULL,
	@PEPPOL_SALESORDERREFERENCE				nvarchar(150)= NULL,
	@DateMod								DATETIME,-- = NULL,
	@UserMod								NVARCHAR(50),
	@IDSKOPOSDIAKINISIS						numeric (18, 0)= NULL,
	@SKOPOSDIAKINISIS						nvarchar (50)= NULL
	--@TheID								NUMERIC(18, 0)= NULL output
	)
AS


SET NOCOUNT ON;

DECLARE @NEWNOPARAST NUMERIC(18,2)=0
--GO
IF @IFAUTONUMBER =1
	BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WITH (NOLOCK) WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
			SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	ELSE
		BEGIN
			SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int)+1, 0)),0)  FROM FORTOTIKES WITH (NOLOCK) WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
			SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END;
	
	--GO
			
			UPDATE FORTOTIKES 
				SET 
				SEIRA							=	@SEIRA,
				NOPARAST						=	@NOPARAST,
				IDPARAST						=	@IDPARAST,
				PARASTATIKO						=	@PARASTATIKO,
				IFXRAPOST						=	@IFXRAPOST,
				IFXRPARAL						=	@IFXRPARAL,
				IFXRENTOL						=	@IFXRENTOL,
				IFXRTRITOU						=	@IFXRTRITOU,
				IDAPOSTOLEA						=	@IDAPOSTOLEA,
				APOSTOLEASDESCR					=	@APOSTOLEASDESCR,
				IDPARALIPTI						=	@IDPARALIPTI,
				PARALISPTISDESCR				=	@PARALISPTISDESCR,
				IDENTOLEA						=	@IDENTOLEA,
				ENTOLEASDESCR					=	@ENTOLEASDESCR,
				IDTRITOU						=	@IDTRITOU,
				TRITOSDESCR						=	@TRITOSDESCR,
				IDANTAPOKRITI					=	@IDANTAPOKRITI,
				ANTAPOKRITISDESCR				=	@ANTAPOKRITISDESCR,
				IDXREOUMENOU					=	@IDXREOUMENOU,
				DATEPRINT						=	@DATEPRINT,
				AA_ANTIK						=	@AA_ANTIK,
				POSO							=	@POSO,
				TAXISPERCENT					=	@TAXISPERCENT,
