				IDCOMPANY,
				IDYPOKATASTIMA,
				IF_LISTADIANOMIS,
				IF_PRODROMOL,
				IF_LISTAANTIKATABOLON,
				IF_FROM_ANTAP,
				--IFCASH,
				--IFPISTOSI,
				--IFOFEILOMENI,
				--IFPREPAY,
				CATKEPYO,
				CodeLog,
				Copies,
				IF_EDMETAFORAS,
				IF_EDSYNARMOL,
				IS_CANCELLATION,
				IF_LISTA_ASS,
				WEBPARASTATIKO,
				IF_ENIMEROSI_AADE,
				AADE_CODE,
				IDSKOPOSDIAKINISIS,
				SKOPOSDIAKINISIS,
				IfReceiptAntik,
				--IF_EDTOPOTH,
				VoucherTypeCode,
				IDCURRENCY,
				IF_PEPPOL,
				IF_ENIMEROSI_FPA,
				IF_PISTOTIKO

				)
			VALUES
				(
				@CODEPARAST,
				@PARASTATIKO,
				@Abbreviation,	
				@KINDKINISIS,			
				@KINDENIMEROSI	,
				@IFENIMEROSITAMEIO,
				@TRANSFORMTO,
				@IF_AUTONUMBER,
				@IF_TRANSFORM,
				@AUTONUMBER_FROM,
				@IF_ZERO_ON_NEW_YEAR,
				@IF_PRINT,
				@PREPORT,
				@REPORT_PATH_FOR_EMAILS,
				@TAXISPERCENT	,
				@IF_XREOSI,
				@IfMisthodosia,
				@IfFortotiki,
				@IF_PISTOSI,
				@IfKAA,
				@IF_ENIMEROSIKARTELA,
				@IF_XREOSIKARTELA,
				@IF_PISTOSIKARTELA,
				@IFKEPXREOSI,
				@IFKEPPISTOSI,
				@IFPROFORTOTIKI,
				@IFKEPYO,
				@SEIRA,
				@PRINTLABEL,
				@PROEPSXOLIO,
				@IfPreviewFirst,
				@PrinterName,
				@IDPARASTEXOFLISI,
				@DESCRPARASTEXOFLISI,
				@IF_ENIMEROSIAPOTHIKI,
				@IFEISAGOGI,
				@IFEXAGOGI,
				@IF_PAROXIYPIRESION,
				@IF_ORDER,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@IF_LISTADIANOMIS,
				@IF_PRODROMOL,
				@IF_LISTAANTIKATABOLON,
				@IF_FROM_ANTAP,
				--@IFCASH,
				--@IFPISTOSI,
				--@IFOFEILOMENI,
				--@IFPREPAY,
				@CATKEPYO,
				@CodeLog,
				@Copies,			
				@IF_EDMETAFORAS,
				@IF_EDSYNARMOL,
				@IS_CANCELLATION,
				@IF_LISTA_ASS,
				@WEBPARASTATIKO,
				@IF_ENIMEROSI_AADE,
				@AADE_CODE,
				@IDSKOPOSDIAKINISIS,
				@SKOPOSDIAKINISIS,
				@IfReceiptAntik,
				--@IF_EDTOPOTH,
				@VoucherTypeCode,
				@IDCURRENCY,
				@IF_PEPPOL,
				@IF_ENIMEROSI_FPA,
				@IF_PISTOTIKO
				)
		END

		SET @IDPARAST= (SELECT MAX(ID) FROM KINDPARASTATIKON WITH (NOLOCK))

		BEGIN
			INSERT INTO PARASTATIKA_ANA_KATHGORIA
				(
				ID_CAT_PARASTATIKON,
				ID_KINDPARASTATIKON
				)
			VALUES
				(
				@IDCATPARAST,
				@IDPARAST
				)
		END

	SET @ErrorNumber = @@Error
	IF @ErrorNumber <> 0 
		BEGIN
			SET @ErrorDescription = 'ΔΗΜΙΟΥΡΓΗΘΗΚΕ ΣΦΑΛΜΑ ΣΤΗΝ ΕΙΣΑΓΩΓΗ ΤΗΣ ΕΓΓΡΑΦΗΣ'
			GOTO ErrorPoint
		END
	IF @RetVal <> 0
		BEGIN
			SET @ErrorNumber = @RetVal
			GOTO ErrorPoint
		END
	--*****************************************************************************

ExitPoint:
	RETURN @ErrorNumber

ErrorPoint:
	IF @TRACOUNT = 0 
		BEGIN 	
			ROLLBACK
		END 
	GOTO ExitPoint 

GO

---END SCRIPT 2139
