  CASE KINDPARASTATIKON_5.IF_PISTOSI 
	WHEN 1 THEN ISNULL((VOH.SUMPOSO + VOH.SUMPOSOEPIVAR), 0)*(-1) 
	ELSE ISNULL((VOH.SUMPOSO + VOH.SUMPOSOEPIVAR), 0) 
  END AS sumposo, 
  NULL AS MHNASPOYAFORA, 
  NULL AS ETOSPOYAFORA, 
  NULL AS IFEXOFLISI, 
  NULL AS IFPROKATABOLI, 
  dbo.VOH.COMMENTS, 
  NULL AS OXIMA, 
  '' AS IDKINDPAYMENT, 
  '' AS KINDPAYMENTDESCR, 
  dbo.VOH.ifDelete, 
  dbo.VOH.IDXRHSHS, 
  dbo.VOH.IDCOMPANY, 
  dbo.VOH.IDYPOKATASTIMA, 
  VOH.UserCreate, 
  VOH.UserMod 
FROM 
  dbo.ACCOUNTS AS ACCOUNTS_7 WITH (NOLOCK) 
  INNER JOIN dbo.VOH WITH (NOLOCK) ON ACCOUNTS_7.id = dbo.VOH.IDCUSTOMER 
  INNER JOIN dbo.KINDPARASTATIKON AS KINDPARASTATIKON_5 WITH (NOLOCK) ON dbo.VOH.IDPARAST = KINDPARASTATIKON_5.ID 
WHERE 
  (
    KINDPARASTATIKON_5.IF_ENIMEROSIKARTELA = 1 
    AND KINDPARASTATIKON_5.KindKINISIS IN(0, 6)
  ) 
union all
SELECT 
  ('101' + convert(nvarchar,dbo.FORTOTIKES.ID)) AS ID, 
  dbo.FORTOTIKES.DATEPRINT AS DATEPRINT, 
  ACCOUNTS_6.id AS ACCOUNTID, 
  ACCOUNTS_6.Eponimia, 
  ACCOUNTS_6.Eponimia as EPON, 
  ACCOUNTS_6.Epagelma, 
  ACCOUNTS_6.AddressStr, 
  ACCOUNTS_6.AddressNo, 
  ACCOUNTS_6.Code, 
  ACCOUNTS_6.AddressTK, 
  ACCOUNTS_6.Tel, 
  ACCOUNTS_6.Tel2, 
  ACCOUNTS_6.Fax, 
  ACCOUNTS_6.Mobile, 
  ACCOUNTS_6.AFM, 
  ACCOUNTS_6.IF_PROM, 
  ACCOUNTS_6.IF_PEL, 
  ' ' AS THETIME, 
  dbo.FORTOTIKES.SEIRA, 
  CAST(dbo.FORTOTIKES.NOPARAST AS NVARCHAR(20)) AS NOPARAST, 
  NULL AS AFORA, 
  dbo.FORTOTIKES.IDPARAST, 
  dbo.FORTOTIKES.PARASTATIKO, 
  'ΠΩΛΗΣΕΙΣ' AS EIDOSKINHSHS, 
  ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) * KINDPARASTATIKON_6.IF_XREOSI AS XREOSI, 
  ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) * KINDPARASTATIKON_6.IF_PISTOSI AS PISTOSI, 
  ' ' AS SKOPOSDIAKINISIS, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.POSO, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.POSO, 0) END AS POSO, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.TAXIS, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.TAXIS, 0) END AS taxis, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.SUMPOSO, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) END AS sumposo, 
  NULL AS MHNASPOYAFORA, 
  NULL AS ETOSPOYAFORA, 
  NULL AS IFEXOFLISI, 
  NULL AS IFPROKATABOLI, 
  dbo.FORTOTIKES.COMMENTS, 
  NULL AS OXIMA, 
  '' AS IDKINDPAYMENT, 
  '' AS KINDPAYMENTDESCR, 
  dbo.FORTOTIKES.ifDelete, 
  dbo.FORTOTIKES.IDXRHSHS, 
  dbo.FORTOTIKES.IDCOMPANY, 
  dbo.FORTOTIKES.IDYPOKATASTIMA, 
  FORTOTIKES.UserCreate, 
  FORTOTIKES.UserMod 
FROM 
  dbo.ACCOUNTS AS ACCOUNTS_6 WITH (NOLOCK) 
  INNER JOIN dbo.FORTOTIKES WITH (NOLOCK) ON ACCOUNTS_6.id = dbo.FORTOTIKES.IDENTOLEA 
  INNER JOIN dbo.KINDPARASTATIKON AS KINDPARASTATIKON_6 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = KINDPARASTATIKON_6.ID 
  LEFT OUTER JOIN PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = KINDPARASTATIKON_6.ID 
  INNER JOIN CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON 
  AND If_EXODO = 0 
WHERE 
  (
    KINDPARASTATIKON_6.IF_ENIMEROSIKARTELA = 1
  ) 
union all
SELECT 
  ('101' + convert(nvarchar,dbo.FORTOTIKES.ID)) AS ID, 
  dbo.FORTOTIKES.DATEPRINT AS DATEPRINT, 
  ACCOUNTS_6.id AS ACCOUNTID, 
  ACCOUNTS_6.Eponimia, 
  ACCOUNTS_6.Eponimia as EPON, 
  ACCOUNTS_6.Epagelma, 
  ACCOUNTS_6.AddressStr, 
  ACCOUNTS_6.AddressNo, 
  ACCOUNTS_6.Code, 
  ACCOUNTS_6.AddressTK, 
  ACCOUNTS_6.Tel, 
  ACCOUNTS_6.Tel2, 
  ACCOUNTS_6.Fax, 
  ACCOUNTS_6.Mobile, 
  ACCOUNTS_6.AFM, 
  ACCOUNTS_6.IF_PROM, 
  ACCOUNTS_6.IF_PEL, 
  ' ' AS THETIME, 
  dbo.FORTOTIKES.SEIRA, 
  CAST(dbo.FORTOTIKES.NOPARAST AS NVARCHAR(20)) AS NOPARAST, 
  NULL AS AFORA, 
  dbo.FORTOTIKES.IDPARAST, 
  dbo.FORTOTIKES.PARASTATIKO, 
  'ΠΩΛΗΣΕΙΣ' AS EIDOSKINHSHS, 
  ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) * KINDPARASTATIKON_6.IF_XREOSI AS XREOSI, 
  ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) * KINDPARASTATIKON_6.IF_PISTOSI AS PISTOSI, 
  ' ' AS SKOPOSDIAKINISIS, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.POSO, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.POSO, 0) END AS POSO, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.TAXIS, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.TAXIS, 0) END AS taxis, 
  CASE KINDPARASTATIKON_6.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.FORTOTIKES.SUMPOSO, 0)*(-1) ELSE ISNULL(dbo.FORTOTIKES.SUMPOSO, 0) END AS sumposo, 
  NULL AS MHNASPOYAFORA, 
  NULL AS ETOSPOYAFORA, 
  NULL AS IFEXOFLISI, 
  NULL AS IFPROKATABOLI, 
  dbo.FORTOTIKES.COMMENTS, 
  NULL AS OXIMA, 
  '' AS IDKINDPAYMENT, 
  '' AS KINDPAYMENTDESCR, 
  dbo.FORTOTIKES.ifDelete, 
  dbo.FORTOTIKES.IDXRHSHS, 
  dbo.FORTOTIKES.IDCOMPANY, 
  dbo.FORTOTIKES.IDYPOKATASTIMA, 
  FORTOTIKES.UserCreate, 
  FORTOTIKES.UserMod 
FROM 
  dbo.ACCOUNTS AS ACCOUNTS_6 WITH (NOLOCK) 
  INNER JOIN dbo.FORTOTIKES WITH (NOLOCK) ON ACCOUNTS_6.id = dbo.FORTOTIKES.IDTRITOU 
  INNER JOIN dbo.KINDPARASTATIKON AS KINDPARASTATIKON_6 WITH (NOLOCK) ON dbo.FORTOTIKES.IDPARAST = KINDPARASTATIKON_6.ID 
  LEFT OUTER JOIN PARASTATIKA_ANA_KATHGORIA ON PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON = KINDPARASTATIKON_6.ID 
  INNER JOIN CAT_PARASTATIKON ON CAT_PARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON 
  AND If_EXODO = 1 
WHERE 
  (
    KINDPARASTATIKON_6.IF_ENIMEROSIKARTELA = 1
  ) 
UNION ALL 
SELECT 
  ('110' + convert(nvarchar,dbo.EXODA.ID)) AS ID, 
  dbo.EXODA.DATEPRINT AS DATEPRINT, 
  EMPLOYEE.id AS ACCOUNTID, 
  EMPLOYEE.Eponimia, 
  EMPLOYEE.Eponimia as EPON, 
  EMPLOYEE.Epagelma, 
  EMPLOYEE.AddressStr, 
  EMPLOYEE.AddressNo, 
  EMPLOYEE.Code, 
  EMPLOYEE.AddressTK, 
  EMPLOYEE.Tel, 
  EMPLOYEE.Tel2, 
  EMPLOYEE.Fax, 
  EMPLOYEE.Mobile, 
  EMPLOYEE.AFM, 
  0 AS IF_PROM, 
  0 AS IF_PEL, 
  dbo.EXODA.THETIME, 
  dbo.EXODA.SEIRA, 
  CAST(dbo.EXODA.NOPARAST AS NVARCHAR(20)) AS NOPARAST, 
  NULL AS AFORA, 
  dbo.EXODA.IDPARAST, 
  dbo.EXODA.PARASTATIKO, 
  'ΜΙΣΘΟΔΟΣΙΑ' AS EIDOSKINHSHS, 
  ISNULL(dbo.EXODA.SUMPOSO, 0) * PACV.IF_XREOSI AS XREOSI, 
  ISNULL(dbo.EXODA.SUMPOSO, 0) * PACV.IF_PISTOSI AS PISTOSI, 
  '' AS SKOPOSDIAKINISIS, 
  CASE PACV.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.EXODA.POSO, 0)*(-1) ELSE ISNULL(dbo.EXODA.POSO, 0) END AS POSO, 
  CASE PACV.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.EXODA.TAXIS, 0)*(-1) ELSE ISNULL(dbo.EXODA.TAXIS, 0) END AS taxis, 
  CASE PACV.IF_PISTOSI WHEN 1 THEN ISNULL(dbo.EXODA.SUMPOSO, 0)*(-1) ELSE ISNULL(dbo.EXODA.SUMPOSO, 0) END AS sumposo, 
  NULL AS MHNASPOYAFORA, 
  NULL AS ETOSPOYAFORA, 
  NULL AS IFEXOFLISI, 
  NULL AS IFPROKATABOLI, 
  dbo.EXODA.COMMENTS, 
  NULL AS OXIMA, 
  '' AS IDKINDPAYMENT, 
  '' AS KINDPAYMENTDESCR, 
  dbo.EXODA.ifDelete, 
  dbo.EXODA.IDXRHSHS, 
  dbo.EXODA.IDCOMPANY, 
  dbo.EXODA.IDYPOKATASTIMA, 
  EXODA.UserCreate, 
  EXODA.UserMod 
FROM 
  dbo.EMPLOYEE AS EMPLOYEE WITH (NOLOCK) 
  INNER JOIN dbo.EXODA WITH (NOLOCK) ON EMPLOYEE.id = dbo.EXODA.IDPROM 
  INNER JOIN dbo.PAR_ANA_CAT_VIEW AS PACV WITH (NOLOCK) ON dbo.EXODA.IDPARAST = PACV.ID_KINDPARASTATIKON 
  AND PACV.ID_CAT_PARASTATIKON = 2 
WHERE 
  (PACV.IF_ENIMEROSIKARTELA = 1) 
  
GO


