ALTER FUNCTION [dbo].[GET_AADE_DOCID_VOH]
(
	@DOCID INT
)
RETURNS NVARCHAR(100)
AS
BEGIN
	DECLARE @UID NVARCHAR(100);
	-- Declare the return variable here
	SELECT @UID=(
		com.AFM+
		'-'+
		CONVERT(NVARCHAR, CONVERT(DATE, doc.DATEPRINT), 126)+
		'-'+
		convert(nvarchar, br.AAYPOKATASTHMA)+
		'-'+
		convert(nvarchar,kp.AADE_CODE)  +
		'-'+
		CASE WHEN LEN(rtrim(ltrim(ISNULL(doc.SEIRA, '')))) = 0 THEN 'ΑΝΕΥ' ELSE ltrim(rtrim(doc.SEIRA)) END+
		'-'+
		doc.NOPARAST
	)
	FROM VOH doc
	JOIN COMPANIES com on com.ID = doc.IDCOMPANY
	JOIN COMPANIES br on br.ID = doc.IDYPOKATASTIMA
	JOIN KINDPARASTATIKON kp on kp.ID = doc.IDPARAST
	where doc.ID = @DOCID

	-- Return the result of the function
	RETURN @UID

END

GO

---END SCRIPT 2146
