ALTER VIEW [dbo].[FORTOTIKES_VIEW]
AS

WITH GRAMMES AS 
	(
	SELECT
		IDVOH,
		ISNULL(MIN(TIMDA),'')				  AS TIMDA,
		Isnull(Sum(temaxia), 0)               AS TEMAXIA,
		MIN(u.untname)						  AS SYSKEVASIA,
        Isnull(Sum(baros), 0)                 AS BAROS,
        Isnull(Sum(kybika), 0)                AS KYBIKA,
        ISNULL(MIN(PERIEXOMENO),'')    		  AS PERIEXOMENO,
        ISNULL(SUM(SUMPOSO),0)				  AS AXIA
	FROM GRAMMESFORTTIKIS
	left join Units u on u.UntID = GRAMMESFORTTIKIS.SYSKEVASIA
	GROUP BY IDVOH
	),
POSA AS 
	(
	SELECT 
		ID,
		SUMPOSO,
		ROUND(FORTOTIKES.POSO, 2) AS KATHARO,
		ROUND(FORTOTIKES.TAXIS, 2) AS TAXISXREOSEON,
		ROUND(FORTOTIKES.SUMPOSO, 2) AS SUMPOSOXRFORT
	FROM FORTOTIKES
	),
header as
	(
		select 
			IDFORT,
			ROUND(isnull(SUM(hd.komistra),0),2)				  AS  KOMISTRA,
			ROUND(ISNULL(SUM(hd.DIKAIOMAFORTOTIKIS),0),2)     AS DIKAIOMAFORTOTIKIS,
			ROUND(ISNULL(SUM(HD.OTHERXREOSIS),0),2)			  AS OTHERXREOSIS,
			ROUND(ISNULL(SUM(HD.OLIKOSYNOLOXREOSEONFORT),0),2) AS OLIKOSYNOLOXREOSEONFORT,
			ROUND(ISNULL(SUM(HD.ERGATIKA),0),2)				  AS ERGATIKA,
			ROUND(ISNULL(SUM(HD.ASFALISTRA),0),2)			  AS ASFALISTRA,
			ROUND(ISNULL(SUM(HD.TAXIS),0),2)				  AS TAXIS,
			ROUND(ISNULL(SUM(HD.SUMPOSOXRFORT),0),2)		  AS SUMPOSOXRFORT,
			ROUND(ISNULL(SUM(HD.KATHARO),0),2)				  AS KATHARO
			
		from HEADERFORTOTIKIS hd
		GROUP BY IDFORT
	),
parastatika_sign as (
					select 
						id,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
)	
	
select

	f.ID,
	f.DATEPRINT,
	kp.Code,
	f.PARASTATIKO,
	f.SEIRA,
	Cast(f.noparast AS INT)								AS NOPARAST,
	f.noparastdeltioudianomis,
	f.noparastdeltiouapostolis,
	f.oxima,
	f.omadproorismos,
	CASE f.ifxrentol *1 + f.ifxrapost *2 + f.ifxrparal * 4 + f.ifxrtritou * 8
           WHEN 1 THEN 'ΕΝΤΟΛΕΑΣ'
           WHEN 2 THEN 'ΑΠΟΣΤΟΛΕΑΣ'
           WHEN 4 THEN 'ΠΑΡΑΛΗΠΤΗΣ'
           WHEN 8 THEN 'ΤΡΙΤΟΣ'
    ELSE 'ΑΓΝΩΣΤΟ'					
    END													AS XREOYMENOS,
    f.apostoleasdescr,
	f.paralisptisdescr,
	f.entoleasdescr,
	f.antapokritisdescr,
	f.nolistasdianomis,
	TRITO.eponimia										AS TRITOSDESCR,
	GR.TIMDA,
	ISNULL(f.POSO,0)*ps.signs									AS POSO,
	ISNULL(f.TAXIS,0)*ps.signs									AS TAXIS,
	ISNULL(f.SUMPOSO,0)*ps.signs								AS SUMPOSO,
	gr.TEMAXIA,
	gr.BAROS,
	gr.KYBIKA,
	gr.SYSKEVASIA,
	CASE F.IFPREPAY 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs 
        ELSE 0 
    END AS XREOSIPROPLIROMENES,
    CASE F.IFOFEILOMENI 
        WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
        ELSE 0 
    END AS XREOSIOFEILOMENES,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFCASH 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESCASH,
    CASE F.IFPREPAY 
        WHEN 1 THEN CASE F.IFPISTOSI 
            WHEN 1 THEN ISNULL(POSA.SUMPOSO,0)*ps.signs
            ELSE 0 
        END 
        ELSE 0 
    END AS XREOSIPROPLIROMENESPISTOSI,
    GR.PERIEXOMENO,
    f.PERIOXIFORTOSIS,
    f.perioxiparadosis,
    f.comments,
    ISNULL(f.sumantik,0)								AS SUMANTIK,
    f.praktoreiodescr,
    f.status,
    f.idapostolea,
    f.idparalipti,
    f.identolea,
    f.idantapokriti,
    f.idtritou,
    f.idpraktoreio,
    CASE ifantikcash
       WHEN 0 THEN 0
       ELSE antikcash
	END                                                 AS ANTIKCASH,
    CASE ifantikepit
      WHEN 0 THEN 0
      ELSE antikepit
    END                                                 AS ANTIKEPIT,
    CASE ifantiksynal
       WHEN 0 THEN 0
       ELSE antiksynal
    END                                                 AS ANTIKSYNAL,
    CASE ifantikother
       WHEN 0 THEN 0
       ELSE antikother
    END                                                 AS ANTIKOTHER,
    CASE ifcancelantik
       WHEN 0 THEN 'ΟΧΙ'
       ELSE 'ΝΑΙ'
    END                                                 AS IFCANCELANTIK,
   f.commentsantik,
   f.dateparadosi,
   f.comments2,
   HD.komistra *ps.signs			                    AS KOMISTRA,
   f.exodatriton		                                AS XREOSISTRITON,
   HD.dikaiomafortotikis *ps.signs				        AS DIKAIOMAFORTOTIKIS,
   HD.otherxreosis	*ps.signs			                AS OTHERXREOSIS,
   HD.olikosynoloxreoseonfort	*ps.signs			    AS OLIKOSYNOLOXREOSEONFORT,
   HD.ergatika  *ps.signs			                    AS ERGATIKA,
        
   CASE f.ifprepay
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFPREPAY,
         CASE f.ifofeilomeni
           WHEN 1 THEN 'ΝΑΙ'
           ELSE 'ΟΧΙ'
         END                                            AS IFOFEILOMENI,
         GR.AXIA								        AS AXIA,
         CASE ifxrentol
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRENTOL,
         f.kindpaymentdescr,
         f.idkindpayment,
         CASE ifxrapost
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRAPOST,
         CASE ifxrparal
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRPARAL,
         CASE ifxrtritou
           WHEN 0 THEN 'ΟΧΙ'
           ELSE 'ΝΑΙ'
         END                                            AS IFXRTRITOU, 
         f.ifantikcash,
         f.ifantikepit,
         f.ifantiksynal,
         f.ifantikother,
         f.ifdelete,
         f.ifcancel,   
         f.aa_antik,
         f.nolistasantik,
         f.ifparadosi,
         f.aitiologiaparastatikou,
         CONVERT(VARCHAR, f.datefortosis, 103)			AS DATEFORTOSIS,
         f.ifepistrofi,
         f.DATEEPISTROFIS,
         f.dromologio,
         f.thesi,
         f.aitiologiaepistrofis,
         f.commentsepistrofis,
         f.ifcash,
         f.ifpistosi,
         f.statusdescr,
         f.ypaitios,
         f.ifepanadromologisi,
         f.ifepanekdosi,
         f.ifokepanadromologisi,
         f.noparastantik,
         f.commentsakirosis,
         f.ifeisprantik,
         f.ifparadosiantik,
         f.ifparalaviantik,
         f.commentsparadantik,
         f.commantsparalantik,
         f.commentseisprantik,
         CONVERT(VARCHAR, f.dateparadantik, 102)		AS DATEPARADANTIK,
         CONVERT(VARCHAR, f.dateeisprantik, 102)		AS DATEEISPRANTIK,
         f.eispraxasantik,
         f.noparparadantik,
         f.noparasteisprantik,
         f.noparparalantik,
         f.commentsparad,
         f.commantsparal,
         f.if_transftoesex,
         f.timeparalfrom,
         f.timeparalto,
         f.timeparadfrom,
         f.timeparadto,
         CONVERT(VARCHAR, f.datecancelantik, 102)		AS DATECANCELANTIK,
         f.idparast,
         f.taxispercent,
         f.anamexodo,
         f.id											AS IDFORTOTIKIS,
         f.afmxreoumenou, 
		 HD.asfalistra *ps.signs						as ASFALISTRA,
         HD.TAXIS *ps.signs								AS TAXISXREOSEON,
         HD.sumposoxrfort *ps.signs						AS sumposoxrfort,
         HD.katharo *ps.signs							AS katharo,
         f.orofos,
         f.orofosdescr,
         f.koudouni,
         APOST.epagelma                                 AS EPAGAPOST,
         APOST.AddressCountry							AS COUNTRYAPOST,
         APOST.addressstr                               AS ADDRSTRAPOST,
         APOST.addressno                                AS ADDRNOAPOST,
         APOST.addresstk                                AS TKAPOST,
