         CAST(XREOYM.KINDPAYMENTDESCR AS NVARCHAR(50))+ ' ' + CONVERT(NVARCHAR(20),XREOYM.PayAfter_Days)+ ' ' + 'Ημερών'  AS PAYAFTERDAYS,
