ALTER VIEW [dbo].[STORED_KAA_FORT_VIEW] AS 
with parastatika_sign as (
				select 
						kp.ID,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS KPSIGN
				from KINDPARASTATIKON kp
				)
SELECT 
  A.ID, 
  A.DATEPRINT, 
  dbo.KINDPARASTATIKON.Code, 
  A.PARASTATIKO, 
  A.SEIRA, 
  B.NOPARASTFORT AS NOPARAST, 
  A.NOPARASTDELTIOUDIANOMIS, 
  A.NOPARASTDELTIOUAPOSTOLIS, 
  B.OXIMA, 
  A.OMADPROORISMOS, 
  B.DRIVERDESCR, 
  CASE WHEN IFXRENTOL = 1 THEN 'ΕΝΤΟΛΕΑΣ' ELSE CASE WHEN IFXRAPOST = 1 THEN 'ΑΠΟΣΤΟΛΕΑΣ' ELSE CASE WHEN IFXRTRITOU = 1 THEN 'ΤΡΙΤΟΣ' ELSE CASE WHEN IFXRPARAL = 1 THEN 'ΠΑΡΑΛΗΠΤΗΣ' ELSE 'ΑΓΝΩΣΤΟ' END END END END AS XREOYMENOS, 
  B.APOSTOLEASDESCR, 
  B.PARALISPTISDESCR, 
  B.ENTOLEASDESCR, 
  A.ANTAPOKRITISDESCR, 
  B.TRITOSDESCR, 
  B.TIMDA, 
  B.POSO * ps.KPSIGN as POSO, 
  B.TAXIS * ps.KPSIGN as TAXIS, 
  B.SUMPOSO * ps.KPSIGN as SUMPOSO, 
  ISNULL(SUM(B.TEMAXIA), 0) AS TEMAXIA, 
  ISNULL(SUM(B.BAROS), 0) AS BAROS, 
  ISNULL(SUM(B.KYBIKA), 0) AS KYBIKA, 
  B.SYSKEVASIA, 
  --MIN(dbo.Units.UntName) AS SYSKEVASIA, 
  B.XREOSIPROPLIROMENES * ps.KPSIGN AS XREOSIPROPLIROMENES, 
  B.XREOSIOFEILOMENES * ps.KPSIGN AS XREOSIOFEILOMENES, 
  B.XREOSIPROPLIROMENESCASH * ps.KPSIGN AS XREOSIPROPLIROMENESCASH, 
  B.XREOSIPROPLIROMENESPISTOSI * ps.KPSIGN AS XREOSIPROPLIROMENESPISTOSI, 
  MIN(B.PERIEXOMENO) AS PERIEXOMENO, 
  A.PERIOXIFORTOSIS, 
  A.PERIOXIPARADOSIS, 
  A.COMMENTS, 
  B.SUMANTIK, 
  A.PRAKTOREIODESCR, 
  A.STATUS, 
  A.DATEPARAD, 
  B.IDAPOSTOLEA, 
  B.IDPARALIPTI, 
  B.IDENTOLEA, 
  A.IDANTAPOKRITI, 
  B.IDTRITOU, 
  A.IDPRAKTOREIO, 
  CASE IFANTIKCASH WHEN 0 THEN 0 ELSE B.ANTIKCASH END AS ANTIKCASH, 
  CASE IFANTIKEPIT WHEN 0 THEN 0 ELSE B.ANTIKEPIT END AS ANTIKEPIT, 
  CASE IFANTIKSYNAL WHEN 0 THEN 0 ELSE B.ANTIKSYNAL END AS ANTIKSYNAL, 
  CASE IFANTIKOTHER WHEN 0 THEN 0 ELSE B.ANTIKOTHER END AS ANTIKOTHER, 
  CASE IFCANCELANTIK WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFCANCELANTIK, 
  A.COMMENTSANTIK, 
  A.DATEPARADOSI, 
  A.COMMENTS2, 
  B.KOMISTRA * ps.KPSIGN AS KOMISTRA, 
  B.EXODATRITON AS XREOSISTRITON, 
  B.DIKAIOMA * ps.KPSIGN AS DIKAIOMAFORTOTIKIS, 
  B.OTHERPOSO * ps.KPSIGN AS OTHERXREOSIS, 
  MIN(dbo.HEADERFORTOTIKIS.OLIKOSYNOLOXREOSEONFORT * ps.KPSIGN) AS OLIKOSYNOLOXREOSEONFORT, 
  MIN(dbo.HEADERFORTOTIKIS.ERGATIKA * ps.KPSIGN) AS ERGATIKA, 
  CASE A.IFPREPAY WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFPREPAY, 
  CASE A.IFOFEILOMENI WHEN 1 THEN 'ΝΑΙ' ELSE 'ΟΧΙ' END AS IFOFEILOMENI, 
  ISNULL(SUM(B.AXIA * ps.KPSIGN),0) AS AXIA, 
  CASE IFXRENTOL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRENTOL, 
  A.KINDPAYMENTDESCR, 
  A.IDKINDPAYMENT, 
  CASE IFXRAPOST WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRAPOST, 
  CASE IFXRPARAL WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRPARAL, 
  CASE IFXRTRITOU WHEN 0 THEN 'ΟΧΙ' ELSE 'ΝΑΙ' END AS IFXRTRITOU, 
  A.IFANTIKCASH, 
  A.IFANTIKEPIT, 
  A.IFANTIKSYNAL, 
  A.IFANTIKOTHER, 
  A.ifDelete, 
  A.IFCANCEL, 
  A.DATECANCEL, 
  A.IFPARADOSI, 
  A.AITIOLOGIAPARASTATIKOU, 
  A.DATEFORTOSIS, 
  A.IFEPISTROFI, 
  A.DATEEPISTROFIS, 
  A.AITIOLOGIAEPISTROFIS, 
  A.COMMENTSEPISTROFIS, 
  A.IFCASH, 
  A.IFPISTOSI, 
  A.STATUSDESCR, 
  A.YPAITIOS, 
  A.IFEPANADROMOLOGISI, 
  A.IFEPANEKDOSI, 
  A.IFOKEPANADROMOLOGISI, 
  A.NOPARASTANTIK, 
  A.COMMENTSAKIROSIS, 
  A.IFEISPRANTIK, 
  A.IFPARADOSIANTIK, 
  A.IFPARALAVIANTIK, 
  A.COMMENTSPARADANTIK, 
  A.COMMANTSPARALANTIK, 
  A.COMMENTSEISPRANTIK, 
  A.DATEPARADANTIK, 
  A.DATEPARALANTIK, 
  A.DATEEISPRANTIK, 
  A.EISPRAXASANTIK, 
  A.NOPARPARADANTIK, 
  A.NOPARASTEISPRANTIK, 
  A.NOPARPARALANTIK, 
  A.DATEPARAL, 
  A.COMMENTSPARAD, 
  A.COMMANTSPARAL, 
  A.TIMEPARALFROM, 
  A.TIMEPARALTO, 
  A.TIMEPARADFROM, 
  A.TIMEPARADTO, 
  A.DATECANCELANTIK, 
  A.IDPARAST, 
  A.TAXISPERCENT, 
  A.ANAMEXODO, 
  A.ID AS IDFORTOTIKIS, 
  A.AFMXREOUMENOU, 
  dbo.HEADERFORTOTIKIS.ASFALISTRA * ps.KPSIGN AS ASFALISTRA, 
  dbo.HEADERFORTOTIKIS.TAXIS * ps.KPSIGN AS TAXISXREOSEON, 
  dbo.HEADERFORTOTIKIS.SUMPOSOXRFORT * ps.KPSIGN AS SUMPOSOXRFORT, 
  dbo.HEADERFORTOTIKIS.KATHARO * ps.KPSIGN AS KATHARO, 
  dbo.ACCOUNTS.Epagelma AS EPAGAPOST, 
  dbo.ACCOUNTS.AddressStr AS ADDRSTRAPOST, 
  dbo.ACCOUNTS.AddressNo AS ADDRNOAPOST, 
  dbo.ACCOUNTS.AddressTK AS TKAPOST, 
  dbo.ACCOUNTS.AddressCity AS CITYAPOST, 
  dbo.ACCOUNTS.AddressPref AS NOMOSAPOST, 
  dbo.ACCOUNTS.Tel AS TELAPOST, 
  dbo.ACCOUNTS.DOY AS DOYAPOST, 
  ACCOUNTS_1.Epagelma AS EPAGPARAL, 
  ACCOUNTS_1.AddressStr AS ADDRSTRPARAL, 
  ACCOUNTS_1.AddressNo AS ADDRNOPARAL, 
  ACCOUNTS_1.AddressTK AS ADDRTKPARAL, 
  ACCOUNTS_1.AddressCity AS ADDRCITYPARAL, 
  ACCOUNTS_1.AddressPref AS ADDRNOMOSPARAL, 
  ACCOUNTS_1.Tel AS TELPARAL, 
  ACCOUNTS_1.DOY AS DOYPARAL, 
  ACCOUNTS_2.Epagelma AS EPAGENTOL, 
  ACCOUNTS_2.AddressStr AS ADDRSTRENTOL, 
  ACCOUNTS_2.AddressNo AS ADDRNOENTOL, 
  ACCOUNTS_2.AddressTK AS ADDRTKENTOL, 
  ACCOUNTS_2.AddressCity AS ADDRCITYENTOL, 
  ACCOUNTS_2.AddressPref AS ADDRNOMOSENTOL, 
  ACCOUNTS_2.Tel AS TELENTOL, 
  ACCOUNTS_2.DOY AS DOYENTOL, 
  ACCOUNTS_3.Epagelma AS EPAGTR, 
  ACCOUNTS_3.AddressStr AS ADDRSTTR, 
  ACCOUNTS_3.AddressNo AS ADDRNOTR, 
  ACCOUNTS_3.AddressTK AS ADDRTKTR, 
  ACCOUNTS_3.AddressCity AS ADDRCITYTR, 
  ACCOUNTS_3.AddressPref AS ADSTRDRNOMO, 
  ACCOUNTS_3.Tel AS TELTR, 
  ACCOUNTS_3.DOY AS DOYTR, 
  B.IDKAA, 
  A.NOLISTASDIANOMIS, 
  A.IDXRHSHS, 
  A.IDCOMPANY, 
  A.IDYPOKATASTIMA 
FROM 
  FORTOTIKES AS A WITH (NOLOCK) 
  LEFT OUTER JOIN FORTOTIKES_ANA_KAA AS B WITH (NOLOCK) ON A.ID = B.IDFORTOTIKIS 
  left join parastatika_sign ps on ps.ID=a.IDPARAST
  LEFT OUTER JOIN dbo.ACCOUNTS WITH (NOLOCK) ON B.IDAPOSTOLEA = dbo.ACCOUNTS.id 
  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_1 WITH (NOLOCK) ON B.IDPARALIPTI = ACCOUNTS_1.id 
  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON B.IDENTOLEA = ACCOUNTS_2.id 
  LEFT OUTER JOIN dbo.ACCOUNTS AS ACCOUNTS_3 WITH (NOLOCK) ON B.IDTRITOU = ACCOUNTS_3.id 
  LEFT OUTER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON A.IDPARAST = dbo.KINDPARASTATIKON.ID 
  LEFT OUTER JOIN --dbo.GRAMMESFORTTIKIS WITH (NOLOCK) ON dbo.GRAMMESFORTTIKIS.IDVOH = A.ID LEFT OUTER JOIN
  dbo.HEADERFORTOTIKIS WITH (NOLOCK) ON dbo.HEADERFORTOTIKIS.IDFORT = A.ID --LEFT OUTER JOIN
  --dbo.Units WITH (NOLOCK) ON cast(B.SYSKEVASIA AS NUMERIC(18,0)) = dbo.Units.UntID 

