ALTER view [dbo].[AADE_INVOICE_DETAILS] 
AS
-- ΦΟΡΤΩΤΙΚΕΣ
WITH COUNTANAVOH AS (
	SELECT 
		IDVOH,
		COUNT(*) COUNT
	FROM GRAMMESVOH
	GROUP BY IDVOH
)


SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	XR.AADE_CATEGORY_CODE,
	ltrim(rtrim(xr.code)) CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	CASE 
		WHEN XR.AADE_VAT_EXEMPTIONCODE='' THEN NULL
		ELSE XR.AADE_VAT_EXEMPTIONCODE
	END AS AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID,
	case
		when XR.ifKomistra=1 then 'Κόμιστρα'
		when XR.ifDikaiomaFortotikis=1 then 'Δικ.Φορ/κης'
		when XR.ifErgatika=1 then 'Εργατικά'
		when XR.IfAsfalistra=1 then 'Ασφάλιστρα'
		when XR.ifOther=1 then 'Λοιπά'
		when XR.IfEmvastika=1 then 'Εμβαστικά'
		else 'Καθ.Αξία' 
	end as XREOSI_ALIAS	
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = FORT.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_FORTOTIKI = 1
UNION
-- ΠΑΡΟΧΗΣ ΥΠΗΡΕΣΙΩΝ 
-- ΠΡΕΠΕΙ ΝΑ ΜΠΕΙ ΚΑΠΟΙΟ ΕΠΙΠΛΕΟΝ ΦΙΛΤΡΟ ΣΤΑ WHERE
-- ΓΙΑ ΝΗ ΜΗΝ ΦΕΡΝΕΙ ΤΑ ΤΗΣ ΠΩΛΗΣΗΣ ΕΔΩ
SELECT
	XAD.ID XREOSIID,
	XAD.IDVOH INVOICEID,
	IF_TO_FORTOTIKI IF_TO_FORTOTIKI,
	IF_TO_VOH IF_TO_VOH,
	0 IF_POLISI,
	ISNULL(XR.IF_XARTOSIMO, 0) IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY XAD.IDVOH ORDER BY XAD.ID) ROW_NUM,
	1 QTY,
	ABS(XAD.POSO) NET_AMOUNT,
	XR.AADE_VATCODE VAT_CODE,
	ABS(XAD.TAXIS) VAT_AMOUNT,
	XR.AADE_CATEGORY_CODE,
	ltrim(rtrim(xr.code)) CODE,
	CASE KP.CATKEPYO
		WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
		WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	END AADE_TYPE_CODE,
	CASE 
		WHEN XR.AADE_VAT_EXEMPTIONCODE='' THEN NULL
		ELSE XR.AADE_VAT_EXEMPTIONCODE
	END AS AADE_VAT_EXEMPTIONCODE,
	--ltrim(rtrim(xr.code)) CODE,
	--CASE KP.CATKEPYO
	--	WHEN 0 THEN XR.AADE_TYPE_CODE_XONDRIKI
	--	WHEN 1 THEN XR.AADE_TYPE_CODE_LIANIKI
	--END AADE_TYPE_CODE,
	--XR.AADE_VAT_EXEMPTIONCODE,
	XR.PEPPOL_CPV,
	XR.PEPPOL_MEASUREMENT_UNIT_ID,
	case
		when XR.ifKomistra=1 then 'Κόμιστρα'
		when XR.ifDikaiomaFortotikis=1 then 'Δικ.Φορ/κης'
		when XR.ifErgatika=1 then 'Εργατικά'
		when XR.IfAsfalistra=1 then 'Ασφάλιστρα'
		when XR.ifOther=1 then 'Λοιπά'
		when XR.IfEmvastika=1 then 'Εμβαστικά'
		else 'Καθ.Αξία' 
	end as XREOSI_ALIAS	
FROM XREOSISANADELTIO XAD
JOIN Xreoseis XR ON XR.ID = XAD.IDXREOSIS
--JOIN FORTOTIKES FORT ON FORT.ID = XAD.IDVOH
JOIN VOH ON VOH.ID = XAD.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 1 AND ABS(XAD.SUMPOSO) > 0 AND XAD.IF_TO_VOH = 1

UNION

-- ΠΩΛΗΣΗΣ!

SELECT
	GV.ID ,
	GV.IDVOH INVOICEID,
	0 IF_TO_FORTOTIKI,
	1 IF_TO_VOH,
	1 IF_POLISI,
	0 IF_XARTOSIMO,	
	ROW_NUMBER() OVER(PARTITION BY GV.IDVOH ORDER BY GV.ID) ROW_NUM,
	GV.TEMAXIA QTY,
	ABS(GV.TELTIMI) NET_AMOUNT,
	TAXIS.AADE_CODE ,
	ABS(GV.SUMTAXIS) VAT_AMOUNT,
	'category1_2',
	ltrim(rtrim(PR.code)) CODE,
	--'E3_561_001',
	CASE KP.CATKEPYO
		WHEN 0 THEN 'E3_561_001'
		WHEN 1 THEN 'E3_561_003'
	END AADE_TYPE_CODE,
	NULL,
	PR.PEPPOL_CPV,
	PR.PEPPOL_MEASUREMENT_UNIT_ID,
	PR.Descr XREOSI_ALIAS	
FROM GRAMMESVOH GV
JOIN PRODUCTS PR ON PR.Code = GV.CodeEidos
LEFT JOIN Taxis ON Taxis.id = PR.ID_TAXIS
JOIN VOH ON VOH.ID = GV.IDVOH
JOIN KINDPARASTATIKON KP ON KP.ID = VOH.IDPARAST
--JOIN XREOSISANADELTIO_CORRECTED XAD2 ON XAD2.ID = XAD.ID
WHERE KP.KindKINISIS = 5 
AND ABS(GV.SUMPOSO) > 0
--WHERE GV.IDVOH = 2036


UNION

-- ΠΩΛΗΣΗΣ ΜΕ ΜΕΤΑΦΟΡΑ !

SELECT
	NULL,
	VOH.ID,
	0,
	1,
	1,
	0,
	COUNTANAVOH.COUNT + 1,
	1,
	ABS(POSOEPIVAR),
	TAXIS.AADE_CODE,
	ABS(TAXISEPIVAR),
	'category1_3',
	null CODE,
	--'E3_561_001',
	CASE KINDPARASTATIKON.CATKEPYO
		WHEN 0 THEN 'E3_561_001'
		WHEN 1 THEN 'E3_561_003'
	END AADE_TYPE_CODE,
	NULL,
	'60100000' PEPPOL_CPV,
	'Ε48' PEPPOL_MEASUREMENT_UNIT_ID,
	'ΕΠΙΒΑΡΥΝΣΗ' XREOSI_ALIAS	
FROM VOH
JOIN COUNTANAVOH ON COUNTANAVOH.IDVOH = VOH.ID
JOIN KINDPARASTATIKON ON KINDPARASTATIKON.ID = VOH.IDPARAST
LEFT JOIN Taxis on TAXIS.Pososto = KINDPARASTATIKON.TAXISPERCENT
WHERE ABS(POSOEPIVAR) > 0




GO


---END SCRIPT 2160
------------------------------------------------------------------------------------
------------------------------------------------------------------------------------
---NEW SCRIPT 2161


CREATE VIEW [dbo].[LOGISTIKI_EPSILON_FORTOTIKES_VOH_C_CAT_ISTOS] AS

with xreoseisanafortotiki as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanafortotiki as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						),
xreoseisanavoh as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanavoh as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						)



select
	cast(f.id as int)								AS idvoh,
	pel.id											AS ACCOUNT_ID,
	f.DATEPRINT,
	'0' IF_TO_VOH,
	'1' IF_TO_FORTOTIKI,
	('100'+ convert(nvarchar(10),f.id))				AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'											AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.POSO,0)
		when 2 then ISNULL(f.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.TAXIS,0)
		when 2 then ISNULL(f.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	pel.CodeLog																					AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.SUMPOSO,0)
		when 2 then ISNULL(f.SUMPOSO,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED
	
from fortotikes f
join accounts pel on pel.id = f.IDXREOUMENOU
join kindparastatikon kdp on kdp.id=f.idparast and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
--WHERE F.ID in (137544,87509)

--ORDER BY 1


UNION ALL

select
	cast(xrf.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	f.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('100'+convert(nvarchar(10),f.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrf.POSO,0)
		when 2 then ISNULL(xrf.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(XRf.TAXIS,0)
		when 2 then ISNULL(XRf.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	case kdp.CATKEPYO
		when 1 then Xreoseis.CodeLog_Lianiki
	else xreoseis.CodeLog
	end																							AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrf.SUMPOSO,0)
		when 2 then ISNULL(xrf.SUMPOSO,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED
	
from xreoseisanafortotiki xrf
join Xreoseis on Xreoseis.ID = xrf.IDXREOSIS and xrf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=xrf.IDVOH
join ACCOUNTS pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
--WHERE xrf.IDVOH in (137544,87509)
--ORDER BY 1

union all


select 
	cast(trf.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	f.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('100'+convert(nvarchar(10),f.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		--else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)	)							AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
	when 1 then ISNULL(trf.poso,0)
		when 2 then ISNULL(trf.poso,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trf.taxis,0)
		when 2 then ISNULL(trf.taxis,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	taxis.CodeLog																				AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trf.sumposo,0)
		when 2 then ISNULL(trf.sumposo,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED

	
from taxisanafortotiki trf
--join xreosisanafortotiki xrf on xrf.IDVOH=xr.IDVOH
join Taxis on Taxis.Pososto = trf.TAXISPERCENT and trf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=trf.IDVOH
join accounts pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
--where f.id in (137544,87509)

--order by 1

union all


select
	cast(v.id as int)								AS idvoh,
	pel.id											AS ACCOUNT_ID,
	v.DATEPRINT,
	'1' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('200'+ convert(nvarchar(10),v.id))				AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'											AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),v.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	v.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(v.POSO,0)
		when 2 then ISNULL(v.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(v.TAXIS,0)
		when 2 then ISNULL(v.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	pel.CodeLog																					AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(v.SUMPOSO,0)
		when 2 then ISNULL(v.SUMPOSO,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	v.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	v.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	v.IF_EXPORTED
	
from voh v
join accounts pel on pel.id = v.IDCUSTOMER
join kindparastatikon kdp on kdp.id=v.idparast and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
--WHERE v.ID in (42180)

--ORDER BY 1


UNION ALL

select
	cast(xrv.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	v.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('200'+convert(nvarchar(10),v.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),v.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	v.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrv.POSO,0)
		when 2 then ISNULL(xrv.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrv.TAXIS,0)
		when 2 then ISNULL(xrv.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	case kdp.CATKEPYO
		when 1 then Xreoseis.CodeLog_Lianiki
	else xreoseis.CodeLog
	end																							AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrv.SUMPOSO,0)
		when 2 then ISNULL(xrv.SUMPOSO,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	v.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	v.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	v.IF_EXPORTED
	
from xreoseisanavoh xrv
join Xreoseis on Xreoseis.ID = xrv.IDXREOSIS and xrv.IF_TO_VOH=1
join voh v on v.id=xrv.IDVOH
join ACCOUNTS pel on pel.id=v.IDCUSTOMER
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
