ALTER PROCEDURE [dbo].[AADE_LOG_ADDENTRY] (
	@PARASTID INT,
	@IF_TO_FORTOTIKI BIT ,
	@IF_TO_VOH BIT,
	@IF_SUCCESS BIT,
	@MESSAGE NVARCHAR(700)
) AS

BEGIN

	SET NOCOUNT ON;

	DECLARE @LASTATTEMPTNO INT, @NEWATTEMPTNO INT;

	

	SELECT @LASTATTEMPTNO = MAX(attemptno)
	FROM AADE_LOG 
	WHERE idparastatikou = @PARASTID 
	AND if_to_fortotiki = @IF_TO_FORTOTIKI 
	and if_to_voh = @IF_TO_VOH;

	SET @NEWATTEMPTNO = ISNULL(@LASTATTEMPTNO, 0) + 1;

	INSERT INTO AADE_LOG(idparastatikou, attemptno, if_to_fortotiki, if_to_voh, flag_success, response)
	VALUES (@PARASTID, @NEWATTEMPTNO, @IF_TO_FORTOTIKI, @IF_TO_VOH, @IF_SUCCESS, @MESSAGE);

	SELECT @NEWATTEMPTNO;

END;

go


---END SCRIPT 2162
