	@PAY_AFTER				INT= 0,
	@PAY_AFTERDESCR			NVARCHAR(50)= NULL,
	@IF_OTHER				INT= 0,
	@IF_OTHER_CARD			INT = 0,
	@IF_POS					INT = 0,
	@IF_EKDOSI				INT= 0,
	@CodeLog				NVARCHAR(50)= NULL,
	@AADE_CODE				NVARCHAR(50)= NULL,
