	IFENDDATE			=	@IFENDDATE,
	PAY_AFTER			=	@PAY_AFTER,
	PAY_AFTERDESCR		=	@PAY_AFTERDESCR,
	IF_OTHER			=	@IF_OTHER,
	IF_OTHER_CARD		=	@IF_OTHER_CARD,
	IF_POS				=	@IF_POS,
	IF_EKDOSI			=	@IF_EKDOSI,
	CodeLog				=	@CodeLog,
	AADE_CODE			=	@AADE_CODE,	
	IF_PISTOSI			=	@IF_PISTOSI,
	IF_EMVASMA			=	@IF_EMVASMA,
	IF_EPITAGI			=	@IF_EPITAGI,
	IF_SYNALAGMATIKI	=	@IF_SYNALAGMATIKI,
	IF_KARTA			=	@IF_KARTA,
	IF_MASTER			=	@IF_MASTER,
	IF_VISA				=	@IF_VISA,
	IF_DINERS			=	@IF_DINERS,
	IF_AMEXPRESS		=	@IF_AMEXPRESS,	
	IDCOMPANY			=	@IDCOMPANY,
	IDYPOKATASTIMA		=	@IDYPOKATASTIMA

WHERE ID  = @ID;

