ALTER PROCEDURE [dbo].[InserttoKINDOFPAYMENTS]
(                  
	@DESCR					NVARCHAR(100)= NULL,
	@IF_IN					INT= 0,
	@IF_OUT					INT= 0,
	@KINDOFCALCULATION		INT= 0,
	@IF_CASH				INT= 0,
	@IFENDDATE				INT= 0,
	@PAY_AFTER				INT= 0,
	@PAY_AFTERDESCR			NVARCHAR(50)= NULL,
	@IF_OTHER				INT= 0,
	@IF_OTHER_CARD			INT = 0,
	@IF_POS					INT = 0,
	@IF_EKDOSI				INT= 0,
	@CodeLog				NVARCHAR(50)= NULL,
	@AADE_CODE				NVARCHAR(50)= NULL,
	@IF_PISTOSI				INT = 0,
	@IF_EMVASMA				INT = 0,
	@IF_EPITAGI				INT = 0,
	@IF_SYNALAGMATIKI		INT = 0,
	@IF_KARTA				INT = 0,
	@IF_MASTER				INT = 0,
	@IF_VISA				INT = 0,
	@IF_DINERS				INT = 0,
	@IF_AMEXPRESS			INT = 0,
	@IDCOMPANY				NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA			NUMERIC(18,0) = 0,	
	@TheID					NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoKINDOFPAYMENTS', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000
--SELECT @@SPID [session_id], @RC [return code], GETDATE()

INSERT INTO KINDOFPAYMENTS
(
	DESCR,
	IF_IN,
	IF_OUT,
	KINDOFCALCULATION,
	IF_CASH,
	IFENDDATE,
	PAY_AFTER,
	PAY_AFTERDESCR,
	IF_OTHER,
	IF_OTHER_CARD,
	IF_POS,
	IF_EKDOSI,
	CodeLog,
	AADE_CODE,
	IF_PISTOSI,
	IF_EMVASMA,
	IF_EPITAGI,
	IF_SYNALAGMATIKI,
	IF_KARTA,
	IF_MASTER,
	IF_VISA,
	IF_DINERS,
	IF_AMEXPRESS,	
	IDCOMPANY,
	IDYPOKATASTIMA
)
VALUES
(
	@DESCR,
	@IF_IN,
	@IF_OUT,
	@KINDOFCALCULATION,
	@IF_CASH,
	@IFENDDATE,
	@PAY_AFTER,
	@PAY_AFTERDESCR,
	@IF_OTHER,
	@IF_OTHER_CARD,
	@IF_POS,
	@IF_EKDOSI,
	@CodeLog,
	@AADE_CODE,
	@IF_PISTOSI,
	@IF_EMVASMA,
	@IF_EPITAGI,
	@IF_SYNALAGMATIKI,
	@IF_KARTA,
	@IF_MASTER,
	@IF_VISA,
	@IF_DINERS,
	@IF_AMEXPRESS,	
	@IDCOMPANY,
	@IDYPOKATASTIMA
)

SET @TheID = (SELECT MAX(ID) AS ID FROM dbo.KINDOFPAYMENTS WITH (NOLOCK))
waitfor delay '00:00:00:40'            
commit;

go


---END SCRIPT 2166
