ALTER PROCEDURE [dbo].[ISOZYGIO_PELATON] (
	@DATEFROM DATE,
	@DATETO DATE,
	@IDPELATI INT = NULL
	
) AS

with lista as (
	select
		'fortotikes' pinakas,
		f.id,
		convert(date,f.DATEPRINT)							AS HMEROMHNIA,
		f.IDXREOUMENOU													AS ID_XREOUMENOU,
		f.IDPARAST														AS IDPARAST,
		f.SUMPOSO + isnull(f.EXODATRITON, 0)							AS poso,
		case ISNULL(kdp.if_xreosi,0) * 1 + ISNULL(kdp.if_pistosi, 0) * 2
			when 1 then +1
			when 2 then -1
		end	as prosimo
	from FORTOTIKES f
	join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSIKARTELA=1
	where f.ifdelete=0

	union all

	select 
		'voh',
		v.id,
		convert(date, v.DATEPRINT),							
		v.IDCUSTOMER,
		v.IDPARAST,
		v.SUMPOSO + isnull(v.sumposoepivar ,0),
		case ISNULL(kdp.if_xreosi,0) * 1 + ISNULL(kdp.if_pistosi, 0) * 2
			when 1 then +1
			when 2 then -1
		end	as prosimo
	from VOH v
	join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSIKARTELA=1
	where v.ifdelete=0

	union all

	select 
		'esoda',
		e.id,
		convert(date,e.DATEPRINT),
		e.IDPROM,
		e.IDPARAST,
		e.SUMPOSO,
		case ISNULL(kdp.if_xreosi,0) * 1 + ISNULL(kdp.if_pistosi, 0) * 2
			when 1 then +1
			when 2 then -1
		end	as prosimo
	from ESODA e
	join KINDPARASTATIKON kdp on kdp.id=e.IDPARAST and kdp.IF_ENIMEROSIKARTELA=1
	where e.ifdelete=0
	

	union all

	select 
		'receipts',
		r.id,
		convert(date, r.DATEPRINT),
		r.IDCUSTOMER,
		r.IDKINDPARAST,
		isnull(r.sumposo, 0),
		case ISNULL(kdp.if_xreosi,0) * 1 + ISNULL(kdp.if_pistosi, 0) * 2
			when 1 then +1
			when 2 then -1
		end	as prosimo
	from RECEIPTS r
	join KINDPARASTATIKON kdp on kdp.id=r.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1
	where r.ifdelete=0 
), soumesPeriodou as (
	select
		lista.ID_XREOUMENOU,
		lista.prosimo,
		sum(lista.poso) poso
	from lista
	where lista.HMEROMHNIA between @DATEFROM and @DATETO
	group by lista.prosimo, lista.ID_XREOUMENOU
), soumaProigoumena as (
	select
		lista.ID_XREOUMENOU,
		sum( lista.poso * lista.prosimo) ypoloipo
	from lista
	where lista.HMEROMHNIA < @DATEFROM
	group by lista.ID_XREOUMENOU
), accountIdsFull as (
	select distinct ID_XREOUMENOU
	from soumesPeriodou 
	union 
	select distinct ID_XREOUMENOU 
	from soumaProigoumena
), accountIds as ( select distinct ID_XREOUMENOU from accountIdsFull), 
t as (
	select
		accountIds.ID_XREOUMENOU,
		ac.code as PEL_CODE,
		ac.eponimia as PELATIS,
		ac.afm as AFM_PELATI,
		ISNULL(xreosiPeriodou.poso, 0) xreosiPeriodou,
		--ISNULL(pistosiPeriodou.poso, 0) pistosiPeriodou,
		case 
			when (ISNULL(soumaProigoumena.ypoloipo, 0) + ISNULL(xreosiPeriodou.poso, 0) - ISNULL(pistosiPeriodou.poso, 0))>0 THEN (ISNULL(soumaProigoumena.ypoloipo, 0) + ISNULL(xreosiPeriodou.poso, 0) - ISNULL(pistosiPeriodou.poso, 0))
			else 0
		end as XREOSTIKO_YPOLOIPO,
		case 
			when (ISNULL(soumaProigoumena.ypoloipo, 0) + ISNULL(xreosiPeriodou.poso, 0) - ISNULL(pistosiPeriodou.poso, 0))<0 THEN (ISNULL(soumaProigoumena.ypoloipo, 0) + ISNULL(xreosiPeriodou.poso, 0) - ISNULL(pistosiPeriodou.poso, 0))
			else 0
		end as PISTOTIKO_YPOLOIPO
		--ISNULL(soumaProigoumena.ypoloipo, 0) + ISNULL(xreosiPeriodou.poso, 0) - ISNULL(pistosiPeriodou.poso, 0) ypoloipo
	from accountIds
	left join soumesPeriodou xreosiPeriodou 
		on xreosiPeriodou.ID_XREOUMENOU = accountIds.ID_XREOUMENOU
		and xreosiPeriodou.prosimo > 0
	left join soumesPeriodou pistosiPeriodou
		on pistosiPeriodou.ID_XREOUMENOU = accountIds.ID_XREOUMENOU
		and pistosiPeriodou.prosimo < 0

	left join soumaProigoumena on soumaProigoumena.ID_XREOUMENOU = accountIds.ID_XREOUMENOU
	join ACCOUNTS ac on ac.id=accountIds.ID_XREOUMENOU
	where @IDPELATI IS NULL or (@IDPELATI IS NOT NULL and accountIds.ID_XREOUMENOU = @IDPELATI)
)

select 
	ROW_NUMBER() OVER (ORDER BY ID_XREOUMENOU) ROWINDEX,
	* from t 
where abs(XREOSTIKO_YPOLOIPO) > 0 or abs(PISTOTIKO_YPOLOIPO) > 0 or abs(xreosiPeriodou) > 0 
--where abs(XREOSTIKO_YPOLOIPO) + abs(PISTOTIKO_YPOLOIPO) + abs(xreosiPeriodou) > 0

go 


---END SCRIPT 2168
