ALTER VIEW [dbo].[LOGISTIKI_EPSILON_FORTOTIKES_VOH_C_CAT_ISTOS] AS

with xreoseisanafortotiki as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanafortotiki as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						),
xreoseisanavoh as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanavoh as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						)



select
	cast(f.id as int)								AS idvoh,
	pel.id											AS ACCOUNT_ID,
	f.DATEPRINT,
	'0' IF_TO_VOH,
	'1' IF_TO_FORTOTIKI,
	('100'+ convert(nvarchar(10),f.id))				AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'											AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.POSO,0)
		when 2 then ISNULL(f.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.TAXIS,0)
		when 2 then ISNULL(f.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	pel.CodeLog																					AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.SUMPOSO,0)
		when 2 then ISNULL(f.SUMPOSO,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED
	
from fortotikes f
join accounts pel on pel.id = f.IDXREOUMENOU
join kindparastatikon kdp on kdp.id=f.idparast and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1


UNION ALL

select
	cast(xrf.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	f.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('100'+convert(nvarchar(10),f.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrf.POSO,0)
		when 2 then ISNULL(xrf.POSO,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(XRf.TAXIS,0)
		when 2 then ISNULL(XRf.TAXIS,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	case kdp.CATKEPYO
		when 1 then Xreoseis.CodeLog_Lianiki
	else xreoseis.CodeLog
	end																							AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(xrf.poso,0)
		when 2 then ISNULL(xrf.poso,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED
	
from xreoseisanafortotiki xrf
join Xreoseis on Xreoseis.ID = xrf.IDXREOSIS and xrf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=xrf.IDVOH
join ACCOUNTS pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1

union all


select 
	cast(trf.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	f.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('100'+convert(nvarchar(10),f.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)	)							AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
	when 1 then ISNULL(trf.poso,0)
		when 2 then ISNULL(trf.poso,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trf.taxis,0)
		when 2 then ISNULL(trf.taxis,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	taxis.CodeLog																				AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trf.taxis,0)
		when 2 then ISNULL(trf.taxis,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED

	
from taxisanafortotiki trf
join Taxis on Taxis.Pososto = trf.TAXISPERCENT and trf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=trf.IDVOH
join accounts pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1

union all


select
	cast(v.id as int)								AS idvoh,
	pel.id											AS ACCOUNT_ID,
	v.DATEPRINT,
	'1' IF_TO_VOH,
