ALTER VIEW [dbo].[LOGISTIKI_EPSILONNET_EXODA_C_CATEGORY_ISTOS] AS

with xreoseisanafortotiki as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanafortotiki as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						),
xreoseisanavoh as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanavoh as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						)


