	0																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	isnull(trf.taxis,0)																			AS 'ΑΞΙΑ',
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +convert(nvarchar,f.NOPARAST)))			AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
