	isnull(xrv.poso,0)																			AS 'ΑΞΙΑ',
	v.PARASTATIKO																				AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +convert(nvarchar,v.NOPARAST)))			AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	v.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	v.IF_EXPORTED,
	'1'																							AS	IF_TO_VOH,
	'0'																							AS IF_TO_FORTOTIKI,
	'0'																							AS IF_TO_EXODA
	
from xreoseisanavoh xrv
join Xreoseis on Xreoseis.ID = xrv.IDXREOSIS and xrv.IF_TO_VOH=1
join voh v on v.id=xrv.IDVOH
join ACCOUNTS pel on pel.id=v.IDCUSTOMER
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS IN (0,6)
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=kdp.ID 
