---NEW SCRIPT 2179

ALTER VIEW [dbo].[LOGISTIKI_EPSILONNET_EXODA_C_CATEGORY_ISTOS] AS

with xreoseisanafortotiki as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanafortotiki as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_FORTOTIKI=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						),
xreoseisanavoh as (
							select 
								IDVOH,
								idxreosis,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,idxreosis,taxispercent,
								if_to_fortotiki,if_to_voh
								having sum(poso)<>0
						),
taxisanavoh as (
							select 
								IDVOH,
								taxispercent,
								if_to_fortotiki,
								if_to_voh,
								sum(poso) as poso,
								sum(taxis) as taxis,
								sum(sumposo) as sumposo
							from XREOSISANADELTIO
							where IF_TO_VOH=1
							group by IDVOH,taxispercent,
								if_to_fortotiki,if_to_voh

						)


select
	cast(ex.ID as int)																	as id,
	k.ID																				AS KID,
	('700'+CAST(ex.id as nvarchar))														AS [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'12' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end																					as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end																					as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else ('90000000'+convert(nvarchar,emp.id)) 
	end																					as [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else emp.id 
	end																					as ACCOUNT_ID,
	CAST(ex.dateprint as date)															AS [DATEPRINT],
	CONVERT (varchar, ex.dateprint, 103) 												AS [ΗΜΕΡΟΜΗΝΙΑ],
	K.Abbreviation																		AS [ΑΙΤΙΟΛΟΓΙΑ],
	(k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST)))	AS [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.SUMPOSO,0)
		else 0
	end																					as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.TAXIS,0)
		else 0
	end																					as [ΦΠΑ ΚΕΠΥΟ],
	k.CodeLog																			AS [ΛΟΓΑΡΙΑΣΜΟΣ],
	'0'																					AS [(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	ISNULL(ex.POSO,0)																	AS [ΑΞΙΑ],
	ex.PARASTATIKO																		AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST))	AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																				AS [Κωδικός Ταμειακής],
	null																				AS [Λοιπές Δαπάνες],
	null																				AS [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	ex.ifDelete																			AS [Ακυρωμένο],
	null																				AS [Πεδίο Ομαδοποίησης Ακύρωσης],
	ex.IF_EXPORTED,
	'0'																					AS IF_TO_VOH,
	'0'																					AS IF_TO_FORTOTIKI,
	'1'																					AS IF_TO_EXODA

from EXODA ex
join ACCOUNTS a on a.id=ex.IDPROM
left join EMPLOYEE emp on emp.id=ex.IDPROM
join kindparastatikon k on k.id=ex.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (0,6)
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=k.ID 
join CAT_PARASTATIKON cp on cp.ID=pk.ID_CAT_PARASTATIKON and cp.ID<=10

UNION ALL

select
	cast(ex.ID as int)																	as id,
	k.ID																				AS KID,
	('700'+CAST(ex.id as nvarchar))														AS [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'12'																				AS [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end																					as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end																					as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else ('90000000'+convert(nvarchar,emp.id)) 
	end																					as [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else emp.id 
	end																					as ACCOUNT_ID,
	CAST(ex.dateprint as date)															AS [DATEPRINT],
	CONVERT (varchar, ex.dateprint, 103) 												AS [ΗΜΕΡΟΜΗΝΙΑ],
	K.Abbreviation																		AS [ΑΙΤΙΟΛΟΓΙΑ],
	(k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST)))	AS [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.SUMPOSO,0)
		else 0
	end																					as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.TAXIS,0)
		else 0
	end																					as [ΦΠΑ ΚΕΠΥΟ],
	case 
		when ISNULL(k.IfMisthodosia,0)=0 then a.Codelog_Promitheyton
		else emp.CodeLog
	end																					as [ΛΟΓΑΡΙΑΣΜΟΣ],

	'1'																					AS [(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	ISNULL(ex.SUMPOSO,0)																	AS [ΑΞΙΑ],
	ex.PARASTATIKO																		AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST))	AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	NULL																				AS [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	NULL																				AS [Λοιπές Δαπάνες],
	NULL																				AS [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	ex.ifDelete																			AS [Ακυρωμένο],
	NULL																				AS [Πεδίο Ομαδοποίησης Ακύρωσης],
	ex.IF_EXPORTED,
	'0'																					AS IF_TO_VOH,
	'0'																					AS IF_TO_FORTOTIKI,
	'1'																					AS IF_TO_EXODA

from EXODA ex
join ACCOUNTS a on a.id=ex.IDPROM
left join EMPLOYEE emp on emp.id=ex.IDPROM
join kindparastatikon k on k.id=ex.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (0,6)
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=k.ID 
join CAT_PARASTATIKON cp on cp.ID=pk.ID_CAT_PARASTATIKON and cp.ID<=10


UNION ALL


select
	cast(ex.ID as int)																	as id,
	k.ID																				AS KID,
	('700'+CAST(ex.id as nvarchar))														AS [ΚΩΔΙΚΟΣ (ΜΟΝΑΔΙΚΟΣ ΑΡΙΘΜΟΣ ΕΓΓΡΑΦΗΣ)],
	'12' [ΕΙΔΟΣ ΚΙΝΗΣΗΣ],
	case	
		when k.CATKEPYO in (0,2,3) then 1
		else 0
	end																					as	[ΚΕΠΥΟ],
	case 
		when a.catkepyo in (0,2,3) then 0
		else 1
	end																					as [ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else ('90000000'+convert(nvarchar,emp.id)) 
	end																					as [ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ],
	case 
		when isnull(k.IfMisthodosia,0)=0 then a.id 
		else emp.id 
	end																					as ACCOUNT_ID,
	CAST(ex.dateprint as date)															AS [DATEPRINT],
	CONVERT (varchar, ex.dateprint, 103) 												AS [ΗΜΕΡΟΜΗΝΙΑ],
	K.Abbreviation																		AS [ΑΙΤΙΟΛΟΓΙΑ],
	(k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST)))	AS [ΠΑΡΑΣΤΑΤΙΚΟ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.POSO,0)
		else 0
	end																					as [ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ],
	case 
		when k.CATKEPYO in (0,2,3) then isnull(ex.TAXIS,0)
		else 0
	end																					as [ΦΠΑ ΚΕΠΥΟ],
	isnull(Taxis.CodeLog,'')															AS [ΛΟΓΑΡΙΑΣΜΟΣ],
	'0'																					AS [(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)],
	ISNULL(ex.TAXIS,0)																	AS [ΑΞΙΑ],
	ex.PARASTATIKO																		AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	k.Abbreviation +' '+ (rtrim(ltrim(ex.seira))+' ' +convert(nvarchar,ex.NOPARAST))	AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	NULL																				AS [Κωδικός Ταμειακής ('κενο' = χειρόγραφα ή 'Κωδικό ταμειακής')],
	NULL																				AS [Λοιπές Δαπάνες],
	NULL																				AS [Ταυτότητα Λιανικών (0=ΌΧΙ,1=ΝΑΙ)],
	ex.ifDelete																			AS [Ακυρωμένο],
	NULL																				AS [Πεδίο Ομαδοποίησης Ακύρωσης],
	ex.IF_EXPORTED,
	'0'																					AS IF_TO_VOH,
	'0'																					AS IF_TO_FORTOTIKI,
	'1'																					AS IF_TO_EXODA

from EXODA ex
join ACCOUNTS a on a.id=ex.IDPROM
LEFT join EMPLOYEE emp on emp.id=ex.IDPROM
join kindparastatikon k on k.id=ex.idparast and k.IF_ENIMEROSI_FPA=1 and k.KindKINISIS in (0,6)
JOIN Taxis on taxis.Pososto=ex.TAXISPERCENT
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=k.ID 
join CAT_PARASTATIKON cp on cp.ID=pk.ID_CAT_PARASTATIKON and cp.ID<=10

union all


select
	cast(f.id as int)																			AS id,
	kdp.ID																						AS KID,
	('900'+ convert(nvarchar(10),f.id))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'12'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	
	case
		when pel.catkepyo IN (0,2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	pel.id																						AS ACCID,
	f.DATEPRINT 																				AS DATEPRINT,
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +convert(nvarchar,f.NOPARAST)))			AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	isnull(f.sumposo,0)																			AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	isnull(f.taxis,0)																			AS 'ΦΠΑ ΚΕΠΥΟ',
	pel.Codelog_Promitheyton																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	isnull(f.SUMPOSO,0)																			AS 'ΑΞΙΑ',
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +convert(nvarchar,f.NOPARAST)))			AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED,
	'0'																							AS IF_TO_VOH,
	'1'																							AS IF_TO_FORTOTIKI,
	'0'																							AS IF_TO_EXODA
	
from fortotikes f
join accounts pel on pel.id = f.IDXREOUMENOU
join kindparastatikon kdp on kdp.id=f.idparast and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=0
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=kdp.ID 
join CAT_PARASTATIKON cp on cp.ID=pk.ID_CAT_PARASTATIKON and cp.ID<=10



UNION ALL

select
	cast(xrf.IDVOH as int)																		AS id,
	kdp.ID																						AS KID,
	('900'+convert(nvarchar(10),f.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'12'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	pel.id																						AS ACCOUNT_ID,
	f.DATEPRINT																					AS 'DATEPRINT',
	convert(nvarchar(20),f.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	isnull(xrf.sumposo,0)																		AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	isnull(xrf.taxis,0)																			AS 'ΦΠΑ ΚΕΠΥΟ',
	case kdp.CATKEPYO
		when 1 then Xreoseis.CodeLog_Lianiki
	else xreoseis.CodeLog
	end																							AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	isnull(xrf.poso,0)																			AS 'ΑΞΙΑ',
	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +convert(nvarchar,f.NOPARAST)))			AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	f.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	f.IF_EXPORTED,
	'0'																							AS IF_TO_VOH,
	'1'																							AS IF_TO_FORTOTIKI,
	'0'																							AS IF_TO_EXODA
	
from xreoseisanafortotiki xrf
join Xreoseis on Xreoseis.ID = xrf.IDXREOSIS and xrf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=xrf.IDVOH
join ACCOUNTS pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=0
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=kdp.ID 
join CAT_PARASTATIKON cp on cp.ID=pk.ID_CAT_PARASTATIKON and cp.ID<=10


union all


