	isnull(trf.sumposo,0)																		AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	isnull(trf.taxis,0)																			AS 'ΦΠΑ ΚΕΠΥΟ',
