from taxisanafortotiki trf
join Taxis on Taxis.Pososto = trf.TAXISPERCENT and trf.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=trf.IDVOH
join accounts pel on pel.id=f.IDXREOUMENOU
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=0
JOIN PARASTATIKA_ANA_KATHGORIA pk on pk.ID_KINDPARASTATIKON=kdp.ID 
