	cast(v.id as int)																			AS id,
	kdp.ID																						AS KID,
	('800'+ convert(nvarchar(10),v.id))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'12'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
