	(kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +convert(nvarchar,v.NOPARAST)))			AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	isnull(v.sumposo,0)																			AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	isnull(v.taxis,0)																			AS 'ΦΠΑ ΚΕΠΥΟ',
	pel.Codelog_Promitheyton																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
