	NULL																						AS 'Ταυτότητα Λιανικών',
	v.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	v.IF_EXPORTED
	
from xreoseisanavoh xrv
join Xreoseis on Xreoseis.ID = xrv.IDXREOSIS and xrv.IF_TO_VOH=1
join voh v on v.id=xrv.IDVOH
join ACCOUNTS pel on pel.id=v.IDCUSTOMER
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1

union all


select 
	cast(trv.IDVOH as int)																		AS idvoh,
	pel.id																						AS ACCOUNT_ID,
	kdp.ID																						as KID,
	v.DATEPRINT																					AS 'DATEPRINT',
	'0' IF_TO_VOH,
	'0' IF_TO_FORTOTIKI,
	('200'+convert(nvarchar(10),v.ID))															AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'13'																						AS 'ΕΙΔΟΣ ΚΙΝΗΣΗΣ',
	case kdp.IFKEPYO
		when 1 then 
			case kdp.KindKINISIS
				when 1 then 1
				when 0 then 2
				else 0
			end
		else 0
		
	end 																						AS 'ΚΕΠΥΟ',
	case
		when pel.catkepyo IN (2,3) then 1
		else 0
	end 																						AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	pel.id																						AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),v.DATEPRINT,103)														AS 'ΗΜΕΡΟΜΗΝΙΑ',
	kdp.Abbreviation																			AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)	)							AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
	when 1 then ISNULL(trv.poso,0)
		when 2 then ISNULL(trv.poso,0) * -1
		else 0
	END																							AS 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΎ',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trv.taxis,0)
		when 2 then ISNULL(trv.taxis,0) * -1
		else 0
	END																							AS 'ΦΠΑ ΚΕΠΥΟ',
	taxis.CodeLog																				AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																							AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(trv.taxis,0)
		when 2 then ISNULL(trv.taxis,0) * -1
		else 0
	END																							AS'ΑΞΙΑ',
	
	
	v.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(v.seira))+' ' +v.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	null																						AS 'Κωδικός Ταμειακής',
	NULL																						AS 'Λοιπές Δαπάνες',
	NULL																						AS 'Ταυτότητα Λιανικών',
	v.ifDelete																					AS 'ΑΚΥΡΩΜΕΝΟ',
	NULL																						AS 'Πεδίο Ομαδοποίησης Ακύρωσης',
	v.IF_EXPORTED

	
from taxisanavoh trv
join Taxis on Taxis.Pososto = trv.TAXISPERCENT and trv.IF_TO_VOH=1
join voh v on v.id=trv.IDVOH
join accounts pel on pel.id=v.IDCUSTOMER
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and kdp.IF_ENIMEROSI_FPA=1 and kdp.IF_FROM_ANTAP!=1 and kdp.KindKINISIS=1
GO





---END SCRIPT 2180
