ALTER VIEW [dbo].[KARTELES_PROM]
AS
SELECT 
  '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20))				AS ID, 
  FORTOTIKES.DATEPRINT, 
  ACCOUNTS.ID												AS ACCOUNTID, 
  ACCOUNTS.Eponimia, 
  ACCOUNTS.Epagelma, 
  ACCOUNTS.AddressStr, 
  ACCOUNTS.AddressNo, 
  ACCOUNTS.Code, 
  ACCOUNTS.AddressTK, 
  ACCOUNTS.Tel, 
  ACCOUNTS.Tel2, 
  ACCOUNTS.Fax, 
  ACCOUNTS.Mobile, 
  ACCOUNTS.AFM, 
  ACCOUNTS.IF_PROM, 
  ACCOUNTS.IF_PEL, 
  ''														AS THETIME, 
  FORTOTIKES.SEIRA, 
  CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))					AS DOCNO, 
  'ΑΓΟΡΕΣ'													AS AFORA, 
  FORTOTIKES.IDPARAST, 
  FORTOTIKES.PARASTATIKO, 
  'ΕΞΟΔΑ'													AS EIDOSKINHSHS, 
  0															AS IDDRIVER, 
  ''														AS DRIVERDESCR, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI			AS XREOSI, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI			AS PISTOSI, 
  0															AS EXODATRITON, 
  ''														AS AITIOLOGIA, 
  ''														AS EISPRAXAS, 
  GetDATE()													AS MHNASPOYAFORA, 
  YEAR(gETdate())											AS ETOSPOYAFORA, 
  0															AS IFEXOFLISI, 
  0															AS IFPROKATABOLI, 
  FORTOTIKES.COMMENTS, 
  FORTOTIKES.OXIMA, 
  NULL														AS IDKINDPAYMENT, 
  ''														AS KINDPAYMENTDESCR, 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA, 
  FORTOTIKES.ifDelete, 
  FORTOTIKES.IDXRHSHS, 
  FORTOTIKES.IDCOMPANY, 
  FORTOTIKES.IDYPOKATASTIMA 
FROM 
  FORTOTIKES WITH (NOLOCK) 
  INNER JOIN ACCOUNTS ON FORTOTIKES.IDAPOSTOLEA = ACCOUNTS.ID 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND FORTOTIKES.IFXRAPOST = 1 
  AND KINDPARASTATIKON.ID IN(
    SELECT 
      KINDPARASTATIKON.ID 
    FROM KINDPARASTATIKON WITH (NOLOCK) 
      INNER JOIN PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) ON KINDPARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON 
      INNER JOIN CAT_PARASTATIKON WITH (NOLOCK) ON PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON = CAT_PARASTATIKON.ID 
    WHERE CAT_PARASTATIKON.If_EXODO = 1) 
  AND FORTOTIKES.ifDelete <> 1 
UNION 
SELECT 
  '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20))								AS ID, 
  FORTOTIKES.DATEPRINT, 
  ACCOUNTS.ID																AS ACCOUNTID, 
  ACCOUNTS.Eponimia, 
  ACCOUNTS.Epagelma, 
  ACCOUNTS.AddressStr, 
  ACCOUNTS.AddressNo, 
  ACCOUNTS.Code, 
  ACCOUNTS.AddressTK, 
  ACCOUNTS.Tel, 
  ACCOUNTS.Tel2, 
  ACCOUNTS.Fax, 
  ACCOUNTS.Mobile, 
  ACCOUNTS.AFM, 
  ACCOUNTS.IF_PROM, 
  ACCOUNTS.IF_PEL, 
  '' AS THETIME, 
  FORTOTIKES.SEIRA, 
  CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))									AS DOCNO, 
  'ΑΓΟΡΕΣ'																	AS AFORA, 
  FORTOTIKES.IDPARAST, 
  FORTOTIKES.PARASTATIKO, 
  'ΕΞΟΔΑ'																	AS EIDOSKINHSHS, 
  0																			AS IDDRIVER, 
  ''																		AS DRIVERDESCR, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI							AS XREOSI, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI							AS PISTOSI, 
  0																			AS EXODATRITON, 
  ''																		AS AITIOLOGIA, 
  ''																		AS EISPRAXAS, 
  GetDATE()																	AS MHNASPOYAFORA, 
  YEAR(gETdate())															AS ETOSPOYAFORA, 
  0																			AS IFEXOFLISI, 
  0																			AS IFPROKATABOLI, 
  FORTOTIKES.COMMENTS, 
  FORTOTIKES.OXIMA, 
  NULL																		AS IDKINDPAYMENT, 
  ''																		AS KINDPAYMENTDESCR, 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA, 
  FORTOTIKES.ifDelete, 
  FORTOTIKES.IDXRHSHS, 
  FORTOTIKES.IDCOMPANY, 
  FORTOTIKES.IDYPOKATASTIMA 
FROM FORTOTIKES WITH (NOLOCK) 
  INNER JOIN ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDENTOLEA = ACCOUNTS.ID 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND FORTOTIKES.IFXRENTOL = 1 
  AND KINDPARASTATIKON.ID IN(
    SELECT 
      KINDPARASTATIKON.ID 
    FROM KINDPARASTATIKON WITH (NOLOCK) 
      INNER JOIN PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) ON KINDPARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON 
      INNER JOIN CAT_PARASTATIKON WITH (NOLOCK) ON PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON = CAT_PARASTATIKON.ID 
    WHERE 
      CAT_PARASTATIKON.If_EXODO = 1
  ) 
  AND FORTOTIKES.ifDelete <> 1 
UNION 
SELECT 
  '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20))									AS ID, 
  FORTOTIKES.DATEPRINT, 
  ACCOUNTS.ID																	AS ACCOUNTID, 
  ACCOUNTS.Eponimia, 
  ACCOUNTS.Epagelma, 
  ACCOUNTS.AddressStr, 
  ACCOUNTS.AddressNo, 
  ACCOUNTS.Code, 
  ACCOUNTS.AddressTK, 
  ACCOUNTS.Tel, 
  ACCOUNTS.Tel2, 
  ACCOUNTS.Fax, 
  ACCOUNTS.Mobile, 
  ACCOUNTS.AFM, 
  ACCOUNTS.IF_PROM, 
  ACCOUNTS.IF_PEL, 
  ''																				AS THETIME, 
  FORTOTIKES.SEIRA, 
  CAST(FORTOTIKES.NOPARAST AS NVARCHAR(20))											AS DOCNO, 
  'ΑΓΟΡΕΣ'																			AS AFORA, 
  FORTOTIKES.IDPARAST, 
  FORTOTIKES.PARASTATIKO, 
  'ΕΞΟΔΑ'																			AS EIDOSKINHSHS, 
  0																					AS IDDRIVER, 
  ''																				AS DRIVERDESCR, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI									AS XREOSI, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI									AS PISTOSI, 
  0																					AS EXODATRITON, 
  ''																				AS AITIOLOGIA, 
  ''																				AS EISPRAXAS, 
  GetDATE()																			AS MHNASPOYAFORA, 
  YEAR(gETdate())																	AS ETOSPOYAFORA, 
  0																					AS IFEXOFLISI, 
  0																					AS IFPROKATABOLI, 
  FORTOTIKES.COMMENTS, 
  FORTOTIKES.OXIMA, 
  NULL																				AS IDKINDPAYMENT, 
  ''																				AS KINDPAYMENTDESCR, 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA, 
  FORTOTIKES.ifDelete, 
  FORTOTIKES.IDXRHSHS, 
  FORTOTIKES.IDCOMPANY, 
  FORTOTIKES.IDYPOKATASTIMA 
FROM 
  FORTOTIKES WITH (NOLOCK) 
  INNER JOIN ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDPARALIPTI = ACCOUNTS.ID 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND FORTOTIKES.IFXRPARAL = 1 
  AND KINDPARASTATIKON.ID IN(
    SELECT 
      KINDPARASTATIKON.ID 
    FROM 
      KINDPARASTATIKON WITH (NOLOCK) 
      INNER JOIN PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) ON KINDPARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON 
      INNER JOIN CAT_PARASTATIKON WITH (NOLOCK) ON PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON = CAT_PARASTATIKON.ID 
    WHERE 
      CAT_PARASTATIKON.If_EXODO = 1
  ) 
  AND FORTOTIKES.ifDelete <> 1 
UNION 
SELECT 
  '101' + CAST(FORTOTIKES.ID AS NVARCHAR(20))																AS ID, 
  FORTOTIKES.DATEPRINT, 
  ACCOUNTS.ID																								AS ACCOUNTID, 
  ACCOUNTS.Eponimia, 
