  'ΑΓΟΡΕΣ'																									AS AFORA, 
  FORTOTIKES.IDPARAST, 
  FORTOTIKES.PARASTATIKO, 
  'ΕΞΟΔΑ'																									AS EIDOSKINHSHS, 
  0																											AS IDDRIVER, 
  ''																										AS DRIVERDESCR, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_XREOSI															AS XREOSI, 
  FORTOTIKES.SUMPOSO * KINDPARASTATIKON.IF_PISTOSI															AS PISTOSI, 
  0																											AS EXODATRITON, 
  ''																										AS AITIOLOGIA, 
  ''																										AS EISPRAXAS, 
  GetDATE()																									AS MHNASPOYAFORA, 
  YEAR(gETdate())																							AS ETOSPOYAFORA, 
  0																											AS IFEXOFLISI, 
  0																											AS IFPROKATABOLI, 
  FORTOTIKES.COMMENTS, 
  FORTOTIKES.OXIMA, 
  NULL																										AS IDKINDPAYMENT, 
  ''																										AS KINDPAYMENTDESCR, 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA, 
  FORTOTIKES.ifDelete, 
  FORTOTIKES.IDXRHSHS, 
  FORTOTIKES.IDCOMPANY, 
  FORTOTIKES.IDYPOKATASTIMA 
FROM 
  FORTOTIKES WITH (NOLOCK) 
  INNER JOIN ACCOUNTS WITH (NOLOCK) ON FORTOTIKES.IDTRITOU = ACCOUNTS.ID 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON FORTOTIKES.IDPARAST = KINDPARASTATIKON.ID 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND FORTOTIKES.IFXRTRITOU = 1 
  AND KINDPARASTATIKON.ID IN(
    SELECT 
      KINDPARASTATIKON.ID 
    FROM 
      KINDPARASTATIKON WITH (NOLOCK) 
      INNER JOIN PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) ON KINDPARASTATIKON.ID = PARASTATIKA_ANA_KATHGORIA.ID_KINDPARASTATIKON 
      INNER JOIN CAT_PARASTATIKON WITH (NOLOCK) ON PARASTATIKA_ANA_KATHGORIA.ID_CAT_PARASTATIKON = CAT_PARASTATIKON.ID 
    WHERE 
      CAT_PARASTATIKON.If_EXODO = 1
  ) 
  AND FORTOTIKES.ifDelete <> 1 
