  KINDPARASTATIKON.IF_ENIMEROSIKARTELA, 
  VOH.ifDelete, 
  VOH.IDXRHSHS, 
  VOH.IDCOMPANY, 
  VOH.IDYPOKATASTIMA 
FROM 
  VOH WITH (NOLOCK) 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON VOH.IDPARAST = KINDPARASTATIKON.ID 
  INNER JOIN ACCOUNTS AS ACCOUNTS_2 WITH (NOLOCK) ON VOH.IDCUSTOMER = ACCOUNTS_2.id 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND KINDPARASTATIKON.ID IN(
