  EXODA.ifDelete, 
  EXODA.IDXRHSHS, 
  EXODA.IDCOMPANY, 
  EXODA.IDYPOKATASTIMA 
FROM 
  EXODA WITH (NOLOCK) 
  INNER JOIN KINDPARASTATIKON WITH (NOLOCK) ON EXODA.IDPARAST = KINDPARASTATIKON.ID 
  INNER JOIN ACCOUNTS WITH (NOLOCK) ON EXODA.IDPROM = ACCOUNTS.id 
WHERE 
  KINDPARASTATIKON.IF_ENIMEROSIKARTELA = 1 
  AND KINDPARASTATIKON.ID IN(
    SELECT 
