  ''																									AS DRIVERDESCR, 
  PAYMENTS.SUMPOSO * KINDPARASTATIKON_1.IF_XREOSI														AS XREOSI, 
  PAYMENTS.SUMPOSO * KINDPARASTATIKON_1.IF_PISTOSI														AS PISTOSI, 
  0																										AS EXODATRITON, 
  LTRIM(RTRIM(PAYMENTS.AITIOLOGIA)), 
  PAYMENTS.EISPRAXAS, 
  NULL																									AS MHNASPOYAFORA, 
  NULL																									AS ETOSPOYAFORA, 
  NULL																									AS IFEXOFLISI, 
  NULL																									AS IFPROKATABOLI, 
  NULL																									AS COMMENTS, 
  NULL																									AS OXIMA, 
  PAYMENTS.IDKINDPAYMENT, 
  PAYMENTS.KINDPAYMENTDESCR, 
  KINDPARASTATIKON_1.IF_ENIMEROSIKARTELA, 
  PAYMENTS.ifDelete, 
  PAYMENTS.IDXRHSHS, 
  PAYMENTS.IDCOMPANY, 
  PAYMENTS.IDYPOKATASTIMA 
FROM 
  PAYMENTS WITH (NOLOCK) 
  INNER JOIN KINDPARASTATIKON AS KINDPARASTATIKON_1 WITH (NOLOCK) ON PAYMENTS.IDKINDPARAST = KINDPARASTATIKON_1.ID 
  INNER JOIN ACCOUNTS AS ACCOUNTS_4 WITH (NOLOCK) ON PAYMENTS.IDCUSTOMER = ACCOUNTS_4.id 
  AND PAYMENTS.IfMisthodosia != 1 
WHERE 
  (
    KINDPARASTATIKON_1.IF_ENIMEROSIKARTELA = 1 
    OR KINDPARASTATIKON_1.IFENIMEROSITAMEIO = 1
  ) 
  AND PAYMENTS.ifDelete <> 1 
  AND PAYMENTS.IDAFORA != 2 

GO


---END SCRIPT 2181
