	f.PARASTATIKO																				AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	kdp.Abbreviation +' '+ (rtrim(ltrim(f.seira))+' ' +f.NOPARAST)								AS 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
