	'0'																	AS 'ΦΠΑ ΚΕΠΥΟ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.CodeLog
	else pel.Codelog_Promitheyton										
	end																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	kdp.Abbreviation+' '+p.SEIRA+' '+															
		rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))						AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	p.AITIOLOGIA														as 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ ΤΑΜΕΙΑΚΗΣ',
	''																	AS 'ΛΟΙΠΕΣ ΔΑΠΑΝΕΣ',
	''																	AS 'ΤΑΥΤΟΤΗΤΑ ΛΙΑΝΙΚΩΝ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'ΠΕΔΙΟ ΟΜΑΔΟΠΟΙΗΣΗΣ ΑΚΥΡΩΣΗΣ',
	p.IF_EXPORTED
	
from PAYMENTS p
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2) and kdp.ID!=191
join COMPANIES c on c.id=p.IDYPOKATASTIMA


union all


select
	kdp.ID																AS KID,
	cast(p.id as int)													AS IDVOH,
	P.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'0'																	AS IF_RECEIPTS,
	'1'																	AS IF_PAYMENTS,
	convert(date,p.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.id
	else pel.id			
	end																	AS ACCOUNT_ID,
	('600'+ convert(nvarchar(10),p.id))									AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'14'																AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	'0'																	AS 'ΚΕΠΥΟ',
	case 
		when pel.CATKEPYO not in (1,4) then 0
		else 1
	end																	AS 'ΥΠΟΧΡΕΩΣΗ ΥΠΟΒΟΛΗΣ',
	CASE
	when ISNULL(P.IfMisthodosia,0)=1 then ('9000'+convert(nvarchar(10),empl.id))
	else pel.id			
	end																	AS 'ΚΩΔΙΚΟΣ ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	convert(nvarchar(20),p.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	p.KINDPARASTDESCR													AS 'ΑΙΤΙΟΛΟΓΙΑ',
	kdp.Abbreviation+' '+p.SEIRA+' '+															
		rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))						AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	'0'																	as 'ΑΞΙΑ ΚΕΠΥΟ ΥΠΟΧΡΕΟΥ',
	'0'																	AS 'ΦΠΑ ΚΕΠΥΟ',
	case 
		WHEN kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=2 then kp.CodeLog
		when kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=17 then '38-00-00-0001'
	else kp.CodeLog															
	END																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	kdp.Abbreviation+' '+p.SEIRA+' '+															
		rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))						AS 'ΠΑΡΑΣΤΑΤΙΚΟ ΑΡΘΡΟΥ',
	p.AITIOLOGIA														as 'ΑΙΤΙΟΛΟΓΙΑ ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ ΤΑΜΕΙΑΚΗΣ',
	''																	AS 'ΛΟΙΠΕΣ ΔΑΠΑΝΕΣ',
	''																	AS 'ΤΑΥΤΟΤΗΤΑ ΛΙΑΝΙΚΩΝ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'ΠΕΔΙΟ ΟΜΑΔΟΠΟΙΗΣΗΣ ΑΚΥΡΩΣΗΣ',
	p.IF_EXPORTED
	
from KINDOFPAYMENTS kp
join PAYMENTS p on p.IDKINDPAYMENT=kp.ID
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2) and kdp.ID!=191
join COMPANIES c on c.id=p.IDYPOKATASTIMA


GO



---END SCRIPT 2184
