---NEW SCRIPT 2185


ALTER PROCEDURE [dbo].[TRANFORMFROMVOHTOFORTOTIKES]
(
	@IDORDER		NUMERIC(18, 0)= NULL,
	@IDPARAST		NUMERIC(18,0) = NULL,
	@PARASTATIKO	NVARCHAR (50),
	@SEIRA			NVARCHAR(5),
	@NOPARAST		NUMERIC(18, 0) = NULL,
	@IFAUTONUMBER	INT = 0,
	@DATEPRINT		SMALLDATETIME = NULL,
	@DATEFORTOSIS	SMALLDATETIME = NULL,
	@OXIMA			NVARCHAR (50) = NULL,
	@IDDRIVER		NUMERIC(18, 0)= NULL,
	@DRIVERDESCR	NVARCHAR (100) = NULL,
	@TheID			NUMERIC(18, 0)= NULL output
	)
AS

SET NOCOUNT ON;

DECLARE @RC INT
Begin tran
Exec @RC =sp_getapplock @Resource='InserttoFORTOTIKES', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000
--SELECT @@SPID [session_id], @RC [return code], GETDATE()

--DECLARE @NOPARAST NUMERIC(18,0)
DECLARE @NEWNOPARAST NUMERIC(18,2)=0
--DECLARE @IDXRHSHS NUMERIC(18,0) = (SELECT TOP 1 ID FROM XRHSEIS WHERE @DATEPRINT BETWEEN FIRSTDATE AND LASTDATE)

--DECLARE @DATEPRINT smalldatetime
IF @DATEPRINT IS NULL
BEGIN
	SELECT @DATEPRINT = GETDATE();
END
DECLARE @IDFORT numeric(18, 0);
DECLARE @TAXPERC NUMERIC(18,3), @TAXIS NUMERIC(18,3), @KATHARO NUMERIC(18,3), @SYNOLO NUMERIC(18,3);

DECLARE @STATUS INT
DECLARE @STATUSDESC NVARCHAR(30)	
SELECT @STATUS = ID, @STATUSDESC = DESCR FROM DOC_STATUS WHERE DESCR LIKE 'ΕΚΔΟ%'

--GO

IF @IFAUTONUMBER =1
	BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM FORTOTIKES WHERE  SEIRA = @SEIRA AND  IDPARAST =@IDPARAST )
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END
			--SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
			--SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	ELSE
		BEGIN
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM FORTOTIKES WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST )
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM FORTOTIKES WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST 
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END
			--SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int)+1, 0)),0)  FROM FORTOTIKES WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
			--SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
		END;
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END;

			INSERT INTO FORTOTIKES
				(
				SEIRA,
				NOPARAST, 
				IDPROFORTOTIKIS,
				IDPARAST,
				PARASTATIKO,
				IFXRAPOST,
				IFXRPARAL,
				IFXRENTOL,
				IFXRTRITOU,
				IDAPOSTOLEA,
				APOSTOLEASDESCR,
				IDPARALIPTI,
				PARALISPTISDESCR,
				IDENTOLEA,
				ENTOLEASDESCR,
				IDTRITOU,
				TRITOSDESCR,
				IDANTAPOKRITI,
				ANTAPOKRITISDESCR,
				IDXREOUMENOU,
				DATEPRINT,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				IFANTIKCASH,
				IFANTIKEPIT,
				IFANTIKSYNAL,
				IFANTIKOTHER,
				ANTIKCASH,
				ANTIKEPIT,
				ANTIKSYNAL,
				ANTIKOTHER,
				SUMANTIK,
				EXODATRITON,
				IFCANCELANTIK,
				DATECANCELANTIK,
				COMMENTSANTIK,
				IFPARADOSI,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				PERIOXIFORTOSIS,
				PERIOXIPARADOSIS,
				OMADPROORISMOS,
				OXIMA,
				IDKINDPAYMENT,
				KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI,
				DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS,
				COMMENTS,
				COMMENTS2,
				IFCASH,
				IFPISTOSI,
				IFPREPAY,
				IFOFEILOMENI,
				IDPRAKTOREIO,
				PRAKTOREIODESCR,
				YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI,
				IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI,
				NOPARASTANTIK,
				COMMENTSAKIROSIS,
				STATUSDESCR,
				IDDRIVER,
				DRIVERDESCR,
				IFEXOFLISI,
				STATUS,
				DATEPARAL,
				DATEPARAD,
				COMMENTSPARAD,
				COMMANTSPARAL,
				TIMEPARALFROM,
				TIMEPARALTO,
				TIMEPARADFROM,
				TIMEPARADTO,
				ANAMEXODO,
				AFMAPOSTOLEA,
				AFMENTOLEA,
				AFMPARALIPTI,
				AFMTRITOU,
				AFMANTAPOKRITI,
				AFMXREOUMENOU,
				NO_EXT_ORDER,
				IFPARADOSITOPEL,
				IFPARALABIFROMPEL,
				NOLISTASDIANOMIS,
				AA_ANTIK,
				CONTAINER,
				BOAT,
				OROFOS,
				OROFOSDESCR,
				KOUDOUNI,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				DateCreate,
				UserCreate 
				)
SELECT @SEIRA AS SEIRA,
				@NOPARAST AS NOPARAST,
				@IDORDER AS IDPROFORT,
				@IDPARAST AS IDPARAST,
				@PARASTATIKO AS PARASTATIKO,
				IFXRAPOST,
				IFXRPARAL,
				IFXRENTOL,
				IFXRTRITOU,
				IDAPOSTOLEA,
				APOSTOLEASDESCR,
				IDPARALIPTI,
				PARALISPTISDESCR,
				VOH.IDENTOLEA,
				VOH.ENTOLEASDESCR,
				IDTRITOU,
				VOH.TRITOSDESCR,
				IDANTAPOKRITI,
				ANTAPOKRITISDESCR,
				CASE WHEN IFXRENTOL = 1 THEN VOH.IDENTOLEA ELSE CASE WHEN IFXRAPOST = 1 
                      THEN VOH.IDAPOSTOLEA ELSE CASE WHEN IFXRTRITOU = 1 THEN VOH.IDTRITOU
                       ELSE CASE WHEN IFXRPARAL = 1 THEN VOH.IDPARALIPTI ELSE VOH.IDCUSTOMER 
                       END END END END AS IDXREOUMENOU,
				@DATEPRINT AS DATEPRINT,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				IFANTIKCASH,
				IFANTIKEPIT,
				IFANTIKSYNAL,
				IFANTIKOTHER,
				ANTIKCASH,
				ANTIKEPIT,
				ANTIKSYNAL,
				ANTIKOTHER,
				SUMANTIK,
				EXODATRITON,
				IFCANCELANTIK,
				DATECANCELANTIK,
				COMMENTSANTIK,
				IFPARADOSI,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				ACAP.AddressCity AS PERIOXIFORTOSIS,
				ACPA.AddressCity AS PERIOXIPARADOSIS,
				OMP.Descr AS OMADPROORISMOS,
				@OXIMA,
				VOH.IDKINDPAYMENT,
				VOH.KINDPAYMENTDESCR,
				AITIOLOGIAPARASTATIKOU,
				DATEFORTOSIS,
				NOPARASTDELTIOUAPOSTOLIS,
				NOPARASTDELTIOUDIANOMIS,
				IFEPISTROFI,
				@DATEFORTOSIS, --DATEEPISTROFIS,
				AITIOLOGIAEPISTROFIS,	
				COMMENTSEPISTROFIS,
				VOH.COMMENTS,
				COMMENTS2,CASE WHEN IFXRENTOL = 1 THEN ACEN.IFCASH ELSE CASE WHEN IFXRAPOST = 1 
                      THEN ACAP.IFCASH ELSE CASE WHEN IFXRTRITOU = 1 THEN ACTR.IFCASH
                       ELSE CASE WHEN IFXRPARAL = 1 THEN ACPA.IFCASH ELSE VOH.IFCASH 
                       END END END END AS IFCASH,
				CASE WHEN IFXRENTOL = 1 THEN ACEN.IFPISTOSI ELSE CASE WHEN IFXRAPOST = 1 
                      THEN ACAP.IFPISTOSI ELSE CASE WHEN IFXRTRITOU = 1 THEN ACTR.IFPISTOSI
                       ELSE CASE WHEN IFXRPARAL = 1 THEN ACPA.IFPISTOSI ELSE VOH.IFPISTOSI 
                       END END END END AS IFPISTOSI,
				CASE WHEN IFXRENTOL = 1 THEN ACEN.IFPREPAY ELSE CASE WHEN IFXRAPOST = 1 
                      THEN ACAP.IFPREPAY ELSE CASE WHEN IFXRTRITOU = 1 THEN ACTR.IFPREPAY
                       ELSE CASE WHEN IFXRPARAL = 1 THEN ACPA.IFPREPAY ELSE VOH.IFPREPAY 
                       END END END END AS IFPREPAY,
				CASE WHEN IFXRENTOL = 1 THEN ACEN.IFOFEILOMENI ELSE CASE WHEN IFXRAPOST = 1 
                      THEN ACAP.IFOFEILOMENI ELSE CASE WHEN IFXRTRITOU = 1 THEN ACTR.IFOFEILOMENI
                       ELSE CASE WHEN IFXRPARAL = 1 THEN ACPA.IFOFEILOMENI ELSE VOH.IFOFEILOMENI 
                       END END END END AS IFOFEILOMENI,
				IDPRAKTOREIO,
				PRAKTOREIODESCR,
				YPAITIOS, -- 0 = κανενός, 1 = πελατης,  2 = δικη μας
				IFEPANADROMOLOGISI,
				IFEPANEKDOSI,
				IFOKEPANADROMOLOGISI,
				NOPARASTANTIK,
				COMMENTSAKIROSIS,
				@STATUSDESC,
				@IDDRIVER AS IDDRIVER,
				@DRIVERDESCR AS DRIVER,
				IFEXOFLISI,
				@STATUS,
				DATEPARAL,
				DATEPARAD,
				COMMENTSPARAD,
				COMMANTSPARAL,
				TIMEPARALFROM,
				TIMEPARALTO,
				TIMEPARADFROM,
				TIMEPARADTO,
				ANAMEXODO,
				AFMAPOSTOLEA,
				VOH.AFMENTOLEA,
				AFMPARALIPTI,
				AFMTRITOU,
				AFMANTAPOKRITI,
				AFMXREOUMENOU,
				SXETIKAPARASTATIKA,
				0,--IFPARADOSITOPEL,
				0,--IFPARALABIFROMPEL,
				'',--NOLISTASDIANOMIS,
				null,--AA_ANTIK,
				CONTAINER,
				BOAT,
				OROFOS,
				OROFOSDESCR,
				KOUDOUNI,
				IDXRHSHS,
				IDCOMPANY,
				voh.IDYPOKATASTIMA,
				DateCreate,
				UserCreate FROM VOH 
				LEFT JOIN ACCOUNTS AS ACAP ON.VOH.IDAPOSTOLEA = ACAP.ID 
				LEFT JOIN ACCOUNTS AS ACPA ON VOH.IDPARALIPTI = ACPA.ID 
				LEFT JOIN ACCOUNTS AS ACEN ON.VOH.IDENTOLEA = ACEN.ID 
				LEFT JOIN ACCOUNTS AS ACTR ON VOH.IDTRITOU = ACTR.ID 
				LEFT JOIN ACCOUNTS AS ACAN ON VOH.IDANTAPOKRITI = ACAN.ID
				LEFT JOIN (SELECT DISTINCT AarName, AarID FROM Aar) AS Aar ON Aar.AarName =  ACPA.AddressCity
				LEFT JOIN  AarPerOmProor AS APOMP ON APOMP.AarID = Aar.AarID AND APOMP.IDOmProor != -1
				INNER JOIN OMADIKOI_PROORISMOI AS OMP  ON APOMP.IDOmProor = OMP.ID
				WHERE VOH.ID = @IDORDER 
				
SELECT @IDFORT = MAX(ID) FROM dbo.FORTOTIKES WITH (NOLOCK)
SELECT @KATHARO = POSO, @TAXIS = TAXIS, @SYNOLO = SUMPOSO FROM dbo.FORTOTIKES WHERE ID = @IDFORT

DECLARE @FINDSUMS INT
SELECT @FINDSUMS = 0;
EXECUTE  CREATEGRAMMESFORTFROMVOH  @IDVOH = @IDORDER, @IDFORT = @IDFORT, @OUTRESULT = @FINDSUMS OUTPUT
--select @FINDSUMS
--EXECUTE @FINDSUMS = CREATEGRAMMESFORTFROMVOH @IDORDER --@IDVOH= , @OUTRESULT = @FINDSUMS

--print 'VRETHIKAN : ' + CAST(@FINDSUMS AS NVARCHAR(3))
IF(@FINDSUMS != 1)
BEGIN 
		--print 'DEN VRETHIKAN : 0'
		INSERT INTO GRAMMESFORTTIKIS
		(TIMDA, IDVOH, TEMAXIA, PERIEXOMENO, SYSKEVASIA,
		SYSKEVASIADESCR, BAROS, KYBIKA, SUMPOSO, XreosiAnaMonada,
		XeosiSeMonada, XreosiGrammis)
		SELECT
		VOH.SEIRA + CAST(VOH.NOPARAST AS NVARCHAR(15)),
		@IDFORT,-- AS IDVOH,
		GV.TEMAXIA,
		GV.PERIEXOMENO,
		Units.UntID AS SYSKEVASIA,
		GV.SYSKEVASIADESCR,
		GV.BAROS,
		GV.KYBIKA,
		GV.SUMPOSO,
		0,--XreosiAnaMonada,
		'',--XeosiSeMonada,
		0 --XreosiGrammis 
		FROM GRAMMESVOH AS GV INNER JOIN VOH ON GV.IDVOH = VOH.ID 
		INNER JOIN Units ON GV.SYSKEVASIA = Units.UntName WHERE GV.IDVOH = @IDORDER
END
           
--           INSERT INTO GRAMMESFORTTIKIS
--		   (TIMDA, IDVOH, TEMAXIA, PERIEXOMENO, SYSKEVASIA,
--		   SYSKEVASIADESCR, BAROS, KYBIKA, SUMPOSO, XreosiAnaMonada,
--		   XeosiSeMonada, XreosiGrammis)
--		   SELECT
--				VOH.SEIRA + CAST(VOH.NOPARAST AS NVARCHAR(15)),
--				@IDFORT,-- AS IDVOH,
--				GV.TEMAXIA,
--				GV.PERIEXOMENO,
--				Units.UntID AS SYSKEVASIA,
--				GV.SYSKEVASIADESCR,
--				GV.BAROS,
--				GV.KYBIKA,
--				GV.SUMPOSO,
--				0,--XreosiAnaMonada,
--				'',--XeosiSeMonada,
--				0 --XreosiGrammis 
--				FROM GRAMMESVOH AS GV INNER JOIN VOH ON GV.IDVOH = VOH.ID 
--				INNER JOIN Units ON GV.SYSKEVASIA = Units.UntName WHERE GV.IDVOH = @IDORDER
		
		
IF EXISTS (	SELECT IDXREOSIS, @IDORDER AS IDVOH, CODEXREOSIS,
DESCR, TYPOS, TAXISPERCENT, TAXIS, POSO, SUMPOSO,
IF_TO_VOH FROM XREOSISANADELTIO WHERE 
IDVOH = @IDFORT AND IF_TO_VOH =1)
	BEGIN	
		SELECT @TAXPERC = TAXISPERCENT, @TAXIS = TAXIS, @KATHARO = POSO, @SYNOLO = SUMPOSO FROM XREOSISANADELTIO WHERE 
		IDVOH = @IDFORT AND IF_TO_VOH =1
		IF (@KATHARO < 0.1)
		BEGIN
			SELECT @TAXIS = 0.1 * (@TAXPERC*0.01)
			SELECT @KATHARO = 0.1
			SELECT @SYNOLO = 0.1 + (0.1 * (@TAXPERC*0.01))		
		END
		--SELECT @TAXIS = 0.1 * (@TAXPERC*0.01)
		--SELECT @KATHARO = 0.1
		--SELECT @SYNOLO = 0.1 + (0.1 * (@TAXPERC*0.01));
		
		INSERT INTO  XREOSISANADELTIO
		(IDXREOSIS, IDVOH, CODEXREOSIS, DESCR, TYPOS,
		TAXISPERCENT, TAXIS, POSO, SUMPOSO, IF_TO_FORTOTIKI) 
		SELECT IDXREOSIS, @IDORDER AS IDVOH, CODEXREOSIS,
		DESCR, TYPOS, TAXISPERCENT, TAXIS, POSO, SUMPOSO,
		IF_TO_VOH FROM XREOSISANADELTIO WHERE 
		IDVOH = @IDFORT AND IF_TO_VOH =1
	END
ELSE
	BEGIN
		SELECT @TAXPERC = TAXISPERCENT FROM Xreoseis  WHERE ifKomistra = 1 AND TAXISPERCENT > 0	
		IF (@KATHARO < 0.1)
		BEGIN
			SELECT @TAXIS = 0.1 * (@TAXPERC*0.01)
			SELECT @KATHARO = 0.1
			SELECT @SYNOLO = 0.1 + (0.1 * (@TAXPERC*0.01))		
		END

		INSERT INTO  XREOSISANADELTIO
		(IDXREOSIS, IDVOH, CODEXREOSIS, DESCR, TYPOS,
		TAXISPERCENT, TAXIS, POSO, SUMPOSO, IF_TO_FORTOTIKI)	
		SELECT ID, @IDFORT AS IDVOH, CODE,
		DESCR, '', @TAXPERC, @TAXIS, @KATHARO, @SYNOLO,
		1 FROM Xreoseis  WHERE ifKomistra = 1 AND TAXISPERCENT > 0	
	END
UPDATE FORTOTIKES SET POSO = @KATHARO, SUMPOSO = @SYNOLO, TAXIS = @TAXIS, TAXISPERCENT = @TAXPERC WHERE ID = @IDFORT	

INSERT INTO HEADERFORTOTIKIS
           (IDFORT ,PARASTATIKOFORT ,SEIRAFORT ,NOPARASTFORT ,ENTOLEASDESCR ,PARALISPTISDESCR
           ,APOSTOLEASDESCR ,KOMISTRA ,DIKAIOMAFORTOTIKIS ,OTHERXREOSIS ,SYSKEVASIA
           ,ASFALISTRA ,KATHARO ,TAXIS ,SUMPOSOXRFORT ,ERGATIKA ,XREOSISTRITON
           ,OLIKOSYNOLOXREOSEONFORT ,BAROSFORT ,KYBIKAFORT ,POSOFORT ,TEMAXIAFORT)
SELECT 
			@IDFORT AS IDFORT,@PARASTATIKO AS  PARASTATIKOFORT, @SEIRA AS SEIRA,
			@NOPARAST AS NOPARAST, ENTOLEASDESCR ,PARALISPTISDESCR
           ,APOSTOLEASDESCR ,KOMISTRA ,DIKAIOMAFORTOTIKIS ,OTHERXREOSIS ,SYSKEVASIA
           ,ASFALISTRA ,@KATHARO ,@TAXIS ,@SYNOLO ,ERGATIKA ,XREOSISTRITON
           ,OLIKOSYNOLOXREOSEONVOH ,BAROSVOH ,KYBIKAVOH ,POSOVOH ,TEMAXIAVOH 
           FROM HEADERVOH WHERE IDVOH = @IDORDER

SELECT  @TheID = @IDFORT --MAX(ID) FROM dbo.FORTOTIKES WITH (NOLOCK)


DECLARE @EXT_BARCODE NVARCHAR(60) 
DECLARE @IDYPOKATASTIMA NUMERIC(18, 00) 
SELECT @EXT_BARCODE = EXT_BARCODE FROM VOH WHERE ID = IDORDER
IF (@EXT_BARCODE IS NULL) OR LEN(@EXT_BARCODE)<1
BEGIN
	DECLARE @PREFIX NVARCHAR(6)
	SELECT @IDYPOKATASTIMA = IDYPOKATASTIMA FROM VOH WHERE ID = IDORDER
	SELECT @PREFIX = BARCODE_Prefix FROM COMPANIES WHERE ID = @IDYPOKATASTIMA
	SELECT @EXT_BARCODE = RTRIM(@PREFIX) + RTRIM(CAST(@TheID AS NVARCHAR(18)))
END
UPDATE FORTOTIKES SET EXT_BARCODE = @EXT_BARCODE WHERE ID = @TheID



waitfor delay '00:00:00:40'            
commit;

GO

---END SCRIPT 2185
