	  v.AADE_UID									 AS AADE_UID,
	  v.AADE_AUTHENTICATION_CODE					 AS AUTHENTICATION_CODE,										
	  kp.PRINTLABEL,
	  v.IF_TRANSMISSION_FAILURE						 AS TRANSMISSION_FAILURE,				
	  v.if_peppol,
