create view XREOSI_EXAGOGON_APOTHIKIS as
with parastatika_sign as (
					select 
						id,
						case ISNULL(kp.IFEISAGOGI,0) * 1 + ISNULL(kp.IFEXAGOGI,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
				where KindKINISIS in (0,1) and isnull(IF_ENIMEROSIAPOTHIKI,0)=1
),
exagoges as (
			select 

				id,
				Descr,
				IFEXAGOGI
			from KINDPARASTATIKON kdp
			where kdp.KindKINISIS in (0,1) and isnull(IF_ENIMEROSIAPOTHIKI,0)=1
			and isnull(IFEXAGOGI,0)=1
)

select 

	convert(date,v.DATEPRINT) dateprint,
	v.PARASTATIKO		parastatiko,
	v.AFMENTOLEA  afmpelati,
	v.ENTOLEASDESCR pelatis,
	isnull(sum(sumdemata),0)*ps.signs				as demata,
	isnull(sum(sumpaletes),0)*ps.signs				as paletes,
	isnull(sum(sumstand),0)*ps.signs				as stand,
		case 
		when AFMENTOLEA='999407814' then (isnull(sum(SUMDEMATA),0)*ps.signs )* 0 
		when AFMENTOLEA='999407814' then (isnull(sum(SUMDEMATA),0)*ps.signs )* 0
		when AFMENTOLEA='999407814' then (isnull(sum(SUMDEMATA),0)*ps.signs )* 0
		when AFMENTOLEA='999407814' then (isnull(sum(SUMDEMATA),0)*ps.signs )* 0
		when AFMENTOLEA='999407814' then (isnull(sum(SUMDEMATA),0)*ps.signs )* 0
	end as Out_Boxes,
	case 
		when AFMENTOLEA='999407814' then abs((isnull(sum(SUMPALETES),0)*ps.signs )* 1.02 )
		when AFMENTOLEA='999407814' then abs((isnull(sum(SUMPALETES),0)*ps.signs )* 1.10)
		when AFMENTOLEA='999407814' then abs((isnull(sum(SUMPALETES),0)*ps.signs )* 1) 
		when AFMENTOLEA='999407814' then abs((isnull(sum(SUMPALETES),0)*ps.signs )* 1.50)
		when AFMENTOLEA='999407814' then abs((isnull(sum(SUMPALETES),0)*ps.signs )* 1.40)
	end as Out_Palets,
	case 
		when AFMENTOLEA='999407814' then (isnull(sum(SUMSTAND),0)*ps.signs )* 0 
		when AFMENTOLEA='999407814' then (isnull(sum(SUMSTAND),0)*ps.signs )* 0
		when AFMENTOLEA='999407814' then (isnull(sum(SUMSTAND),0)*ps.signs )* 0 
		when AFMENTOLEA='999407814' then (isnull(sum(SUMSTAND),0)*ps.signs )* 0
		when AFMENTOLEA='999407814' then (isnull(sum(SUMSTAND),0)*ps.signs )* 0
	end as Out_Stands
from voh v 
join exagoges ex on ex.id=v.IDPARAST
join parastatika_sign ps on ps.ID=v.IDPARAST
--where v.DATEPRINT>='2025-01-01'
group by convert(date,v.DATEPRINT),
v.PARASTATIKO		,
	v.AFMENTOLEA ,
	v.ENTOLEASDESCR,
	ps.signs

	go


---END SCRIPT 2196
