------------------------------------------------------------------------------------
---NEW SCRIPT 2197


create view FORTOTIKES_PER_SYSKEVASIA_ANA_KAA
AS

WITH GRAMMES AS (
					
			select
				IDVOH AS FORTID,DEMATA,PALETA,STAND,KOLA,ROLI,THALAMOS
			from 
				(
					select
						idvoh,
						case 
							--when CONVERT(NVARCHAR(50),isnull(SYSKEVASIADESCR,0))=0 then 'ΔΕΜΑΤΑ'
							when SYSKEVASIADESCR like 'ΔΕΜ%' then 'DEMATA'
							when SYSKEVASIADESCR like 'ΠΑΛ%' then 'PALETA'
							when SYSKEVASIADESCR like 'ΣΤΑΝ%' then 'STAND'
							when SYSKEVASIADESCR like 'ΡΟΛ%' then 'ROLI'
							when SYSKEVASIADESCR like 'ΘΑΛΑΜ%' then 'THALAMOS'
							when SYSKEVASIADESCR like 'ΤΕΜ%' then 'DEMATA'
							ELSE 'KOLA'
						END AS SYSKEVASIA,
						TEMAXIA
					FROM  GRAMMESFORTTIKIS
				)AS GF
			PIVOT
			(
				SUM(TEMAXIA)
				FOR SYSKEVASIA IN (DEMATA,PALETA,STAND,KOLA,ROLI,THALAMOS)
			) AS PV
	)
select
	f.id AS ID,
	f.DATEPRINT,
	f.noparast,
	f.IDAPOSTOLEA,
	apost.Eponimia APOSTOLEASDESCR,
	f.IDPARALIPTI,
	paral.Eponimia PARALISPTISDESCR,
	(paral.AddressStr +' '+ paral.AddressNo) ADDRSTRPARAL,
	paral.AddressCity AS ADDRCITYPARAL,
	paral.AddressTK,
	case APOST.ext_id
		when '300' then 'ΞΗΡΟ'
		when '134' then 'ΨΥΓΕΙΟ'
		when '395' then 'ΜΑΝΑΒΙΚΗ'
		else null
	end as SYNTHIKI,
	f.THESI AS THESI,
	f.DROMOLOGIO AS DROMOLOGIO,
	grammes.DEMATA AS DEMATA,
	grammes.PALETA AS PALETA,
	grammes.STAND,
	grammes.KOLA AS KOLA,
	grammes.ROLI AS ROLI,
	grammes.THALAMOS  AS THALAMOS,
	F.OMADPROORISMOS AS OMADPROORISMOS,
	f.ifDelete,
	KAA.ID as IDKAA,
	KAA.NOPARAST AS NOPARASTKAA,
	KAA.DATEPRINT AS DATEPRINTKAA,
	KAA.OXIMA AS OXIMAKAA,
	KAA.DRIVER as DRIVERKAA,	
	KAA.NOFORT,
	KAA.POSOEXODA,
	KAA.TAXISEXODA,
	KAA.SUMPOSOEXODA
		
from FORTOTIKES f

left join ACCOUNTS apost on apost.id=f.IDAPOSTOLEA
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI
left join GRAMMES ON GRAMMES.FORTID=F.ID 
inner join FORTOTIKES_ANA_KAA FAK on FAK.IDFORTOTIKIS = f.ID
inner join KAA on KAA.id=FAK.IDKAA

GO






---END SCRIPT 2197
