ALTER VIEW [dbo].[LOGISTIKI_EPSILON_FORTOTIKES_VOH_C_CAT_MASTROGIORGIS] AS
select

	kdp.ID											AS KID,
	f.IDYPOKATASTIMA,
	c.Eponimia										AS YPOKATASTHMA,
	cast(f.id as int)								AS idvoh,
	pel.id											AS ACCOUNT_ID,
	convert(date,f.DATEPRINT)						AS DATEPRINT,
	'0'												AS IF_TO_VOH,
	'1'												AS IF_TO_FORTOTIKI,
	('100'+ convert(nvarchar(10),f.id))				AS 'ΑΡ_ΕΓΓΡΑΦΗΣ',
	'ΕΣ - ΠΩΛ'										AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	case 
		when kdp.CATKEPYO = 1 then '000000000'
		else pel.AFM
	end 											AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)			AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO									AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation +' '+(rtrim(ltrim(f.seira))))	AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	f.NOPARAST										AS 'ΑΡΙΘΜΟΣ',
	pel.CodeLog										AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	1												AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(f.SUMPOSO,0)
		when 2 then ISNULL(f.SUMPOSO,0) * -1
		else 0
	END												AS'ΑΞΙΑ',
	f.ifDelete										AS 'ΑΚΥΡΩΜΕΝΟ',
	f.IF_EXPORTED
	
from fortotikes f
join accounts pel on pel.id = f.IDXREOUMENOU
join kindparastatikon kdp on kdp.id=f.idparast and kdp.IF_ENIMEROSIKARTELA=1
join COMPANIES c on c.id=f.IDYPOKATASTIMA
--WHERE f.ID=289

union all



select

	kdp.ID											AS KID,
	f.IDYPOKATASTIMA,
	c.Eponimia										AS YPOKATASTHMA,
	cast(xr.IDVOH as int)							AS idvoh,
	pel.id											AS ACCOUNT_ID,
