	'ΕΣ - ΠΩΛ'										AS 'ΤΥΠΟΣ ΚΙΝΗΣΗΣ',
	case 
		when kdp.CATKEPYO = 1 then '000000000'
		else pel.AFM
	end 											AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),f.DATEPRINT,103)			AS 'ΗΜΕΡΟΜΗΝΙΑ',
	f.PARASTATIKO									AS 'ΑΙΤΙΟΛΟΓΙΑ',
	(kdp.Abbreviation+' ' +(rtrim(ltrim(f.seira))))	AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	f.NOPARAST										AS 'ΑΡΙΘΜΟΣ',
	case kdp.CATKEPYO
		when 1 then Xreoseis.CodeLog_Lianiki
	else xreoseis.CodeLog
	end												AS	 'ΛΟΓΑΡΙΑΣΜΟΣ',
	
	--Xreoseis.CodeLog								AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	0												AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	case isnull(kdp.if_xreosi,0)*1 + isnull(kdp.if_pistosi,0)*2
		when 1 then ISNULL(sum(xr.POSO),0)
		when 2 then ISNULL(sum(xr.POSO),0) * -1
		else 0
	END												AS'ΑΞΙΑ',
	f.ifDelete										AS 'ΑΚΥΡΩΜΕΝΟ',
	f.IF_EXPORTED
	
from XREOSISANADELTIO xr
join Xreoseis on Xreoseis.ID = XR.IDXREOSIS and XR.IF_TO_FORTOTIKI=1
join fortotikes f on f.id=xr.IDVOH
join ACCOUNTS pel on pel.id=f.IDXREOUMENOU
