--DROP VIEW LISTAAPOTHEMATOS
--GO

create view LISTAAPOTHEMATOS
 AS
SELECT WH.DESCRIPTION AS WAREHOUSE, HW.DESCRIPTION AS HALLWAY, DP.DESCRIPTION AS DEPTH, 
LV.DESCRIPTION AS LEVEL, PO.DESCRIPTION AS POSITION, PD.Descr AS ITEM, IPP.TEMAXIA, 
IPP.IF_IN, IPP.IF_OUT, IPP.SYSKEVASIA, IPP.TEMDESCR , PO.ID AS ID        
 FROM ITEMSTRANS  AS IPP 
INNER JOIN Positions AS PO ON PO.IDDEPTH = IPP.IDPOSITION 
INNER JOIN Levels AS LV ON  LV.id = PO.IDLEVEL 
INNER JOIN DEPTHS AS DP ON DP.id = PO.IDDEPTH 
INNER JOIN HallWays AS HW ON HW.IDDEPARTEMENT = PO.IDHALLWAY 
INNER JOIN WAREHOUSE AS WH ON WH.IDDEPARTEMENT = PO.IDWAREHOUSE  
INNER JOIN PRODUCTS AS PD ON PD.ID = IPP.IDITEM


GO




