ALTER view [dbo].[LISTAAPOTHEMATOS]
AS
SELECT DISTINCT  (PO.ID) AS ID, 
min(WH.DESCRIPTION) AS WAREHOUSE, 
min(HW.DESCRIPTION) AS HALLWAY,
 MIN(DP.DESCRIPTION) AS DEPTH, 
MIN(LV.DESCRIPTION) AS LEVEL, 
MIN(PO.DESCRIPTION) AS POSITION, 
MIN(PD.Descr) AS ITEM, 
SUM(IPP.TEMAXIA) AS TEMAXIA, 
PD.ID AS ITEMID,
MIN(IPP.SYSKEVASIA) AS SYSKEVASIA
--, 
--MIN(IPP.ITEMDESCR) AS ITEMDESCR        
 FROM (
 
 SELECT ID,  SYSKEVASIA, 
 CASE
    WHEN IF_OUT = 1 THEN TEMAXIA * (-1)
    WHEN IF_IN = 1 THEN TEMAXIA
    ELSE 0
END 
  AS TEMAXIA, IDPOSITION,  TEMDESCR AS ITEMDESCR, 
IDITEM  FROM ITEMSTRANS WHERE ifDelete = 0    
 ) AS IPP 
INNER JOIN (SELECT DISTINCT ID, IDLEVEL, IDDEPTH, IDHALLWAY, 
IDWAREHOUSE, DESCRIPTION FROM POSITIONS) AS PO ON PO.IDDEPTH = IPP.IDPOSITION 
INNER JOIN Levels AS LV ON  LV.id = PO.IDLEVEL 
INNER JOIN DEPTHS AS DP ON DP.id = PO.IDDEPTH 
INNER JOIN HallWays AS HW ON HW.ID = PO.IDHALLWAY 
INNER JOIN WAREHOUSE AS WH ON WH.IDDEPARTEMENT = PO.IDWAREHOUSE  
INNER   JOIN PRODUCTS AS PD ON PD.ID = IPP.IDITEM 
GROUP BY PO.ID, PD.ID  -- , IPP.TEMAXIA 




GO



---END SCRIPT 2211
------------------------------------------------------------------------------------

