---NEW SCRIPT 2213



ALTER VIEW [dbo].[LISTAAPOTHEMATOS] AS

WITH IN_OUT AS (
				SELECT
					--ID,
					SYSKEVASIA,
					IDPOSITION,
					IDITEM,
					IDVOH,
					TEMDESCR AS ITEMDESCR,
					CASE	
						WHEN ISNULL(IF_IN,0) = 1 THEN SUM(TEMAXIA)
						WHEN ISNULL(IF_OUT,0) = 1 THEN SUM(TEMAXIA) * (-1)
						ELSE 0 
					END AS TEMAXIA
				FROM ITEMSTRANS
				WHERE ifDelete=0
				GROUP BY --ID,
					SYSKEVASIA,
					IDPOSITION,
					IDVOH,
					IDITEM,
					TEMDESCR,
					ISNULL(IF_IN,0),
					ISNULL(IF_OUT,0)
				

	)

SELECT distinct
	PO.ID						AS ID,
	WH.DESCRIPTION				AS WAREHOUSE,
	HW.DESCRIPTION				AS HALLWAY,
	DP.DESCRIPTION				AS DEPTH,
	LV.DESCRIPTION				AS [LEVEL],
