	IPP.IDVOH

FROM ITEMSTRANS ITS
JOIN IN_OUT IPP ON IPP.IDITEM=ITS.IDITEM 
JOIN Positions PO ON PO.id=ITS.IDPOSITION
JOIN PRODUCTS PD ON PD.ID=ITS.IDITEM
JOIN WAREHOUSE WH ON WH.id=PO.IDWAREHOUSE
JOIN HallWays HW ON HW.ID=PO.IDHALLWAY
JOIN DEPTHS DP ON DP.ID=PO.IDDEPTH
JOIN Levels LV ON LV.id=PO.IDLEVEL


