ALTER VIEW PositionBarCode AS 
SELECT 
PO.ID AS IDPOSITION,
WH.Code AS WH_PREFIX,
WH.DESCRIPTION AS WAREHOUSE,
HW.Code AS HW_PREFIX,
HW.DESCRIPTION AS HALLWAY,
DP.Code AS DP_PREFIX,
DP.DESCRIPTION AS DEPTH,
LV.Code AS LV_PREFIX,
LV.DESCRIPTION AS LEVEL, 
PO.DESCRIPTION AS POSITION, 
(HW.DESCRIPTION + '-' + DP.DESCRIPTION + '-' + LV.DESCRIPTION) AS BARCODE
FROM  Positions AS PO 
INNER JOIN Levels AS LV ON  LV.id = PO.IDLEVEL 
INNER JOIN DEPTHS AS DP ON DP.id = PO.IDDEPTH 
INNER JOIN HallWays AS HW ON HW.ID = PO.IDHALLWAY 
INNER JOIN WAREHOUSE AS WH ON WH.ID = PO.IDWAREHOUSE 

