CREATE view [dbo].[LOGISTIKI_EPSILON_EISPRAKSEIS_PLIROMES_C_CATEGORY_VLACHOU] AS
select
	kdp.ID																AS KID,
	cast(r.id as int)													AS IDVOH,
	r.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'1'																	AS IF_RECEIPTS,
	'0'																	AS IF_PAYMENTS,
	pel.id																AS ACCOUNT_ID,
	convert(date,r.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('800'+ convert(nvarchar(10),r.id))									AS 'ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)',
	'ΤΑΜ'																AS 'ΕΙΔΟΣ_ΚΙΝΗΣΗΣ',
	pel.Code															AS 'ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	pel.AFM																AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),r.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	LTRIM(RTRIM(r.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ',
	LTRIM(RTRIM(r.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	pel.CodeLog															AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	LTRIM(RTRIM(r.KINDPAYMENTDESCR))									AS 'Τρ.Πληρωμής',
	1																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	r.sumposo* kdp.KindYpologismou										AS 'ΑΞΙΑ',
	LTRIM(RTRIM(r.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ',
	LTRIM(RTRIM(r.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ',
	r.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'Πεδίο_Ομαδοποίησης_Ακύρωσης',
	r.IF_EXPORTED
	
from receipts r
join accounts pel on pel.id = r.IDCUSTOMER
join kindparastatikon kdp on kdp.id=r.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=r.IDYPOKATASTIMA


UNION ALL

select
	kdp.ID																AS KID,
	cast(r.id as int)													AS IDVOH,
	r.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'1'																	AS IF_RECEIPTS,
	'0'																	AS IF_PAYMENTS,
	pel.id																AS ACCOUNT_ID,
	convert(date,r.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('800'+ convert(nvarchar(10),r.id))									AS 'ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)',
	'ΤΑΜ'																AS 'ΕΙΔΟΣ_ΚΙΝΗΣΗΣ',
	pel.Code															AS 'ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	pel.AFM																AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),r.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	LTRIM(RTRIM(r.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ',
	LTRIM(RTRIM(r.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case 
		WHEN kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and r.IDYPOKATASTIMA=2 then kp.CodeLog
		when kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and r.IDYPOKATASTIMA=17 then '38-00-00-0001'
	else kp.CodeLog															
	END																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	LTRIM(RTRIM(R.KINDPAYMENTDESCR))									AS 'Τρ.ΠΛΗΡΩΜΗΣ',
	0																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	r.sumposo* kdp.KindYpologismou										AS 'ΑΞΙΑ',
	LTRIM(RTRIM(r.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),r.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ',
	LTRIM(RTRIM(r.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ',
	r.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'Πεδίο_Ομαδοποίησης_Ακύρωσης',
	r.IF_EXPORTED
	
from KINDOFPAYMENTS kp
join receipts r on r.IDKINDPAYMENT=kp.ID
join accounts pel on pel.id = r.IDCUSTOMER
join kindparastatikon kdp on kdp.id=r.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=r.IDYPOKATASTIMA

union all

select
	kdp.ID																AS KID,
	cast(p.id as int)													AS IDVOH,
	P.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'0'																	AS IF_RECEIPTS,
	'1'																	AS IF_PAYMENTS,
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.id
	else pel.id			
	end AS ACCOUNT_ID,
	convert(date,p.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('900'+ convert(nvarchar(10),p.id))									AS 'ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)',
	'ΤΑΜ'																AS 'ΕΙΔΟΣ_ΚΙΝΗΣΗΣ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.Code
		else empl.AFM																
	END																	AS 'ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.AFM
		else PEL.AFM																
	END																	AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),p.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	LTRIM(RTRIM(p.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ',
	LTRIM(RTRIM(p.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.CodeLog
	else pel.CodeLog										
	end																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	LTRIM(RTRIM(p.KINDPAYMENTDESCR))									AS 'Τρ.ΠΛΗΡΩΜΗΣ',
	0																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	LTRIM(RTRIM(p.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ',
	LTRIM(RTRIM(p.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'Πεδίο_Ομαδοποίησης_Ακύρωσης',
	p.IF_EXPORTED
	
from PAYMENTS p
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=p.IDYPOKATASTIMA

union all

select
	kdp.ID																AS KID,
	cast(p.id as int)													AS IDVOH,
	P.IDYPOKATASTIMA,
	c.Eponimia															AS YPOKATASTHMA,
	'0'																	AS IF_RECEIPTS,
	'1'																	AS IF_PAYMENTS,
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.id
	else pel.id			
	end AS ACCOUNT_ID,
	convert(date,p.DATEPRINT)											AS DATEPRINT,
	0 IF_TO_VOH,
	0 IF_TO_FORTOTIKI,
	('900'+ convert(nvarchar(10),p.id))									AS 'ΚΩΔΙΚΟΣ(ΜΟΝΑΔΙΚΟΣ_ΑΡΙΘΜΟΣ_ΕΓΓΡΑΦΗΣ)',
	'ΤΑΜ'																AS 'ΕΙΔΟΣ_ΚΙΝΗΣΗΣ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.Code
		else empl.AFM																
	END																	AS 'ΚΩΔΙΚΟΣ_ΣΥΝΑΛΛΑΣΣΟΜΕΝΟΥ',
	case 
		when ISNULL(P.IfMisthodosia,0)=1 then empl.AFM
		else PEL.AFM																
	END																	AS 'ΑΦΜ ΣΥΝΑΛΛΑΣΟΜΕΝΟΥ',
	convert(nvarchar(20),p.DATEPRINT,103)								AS 'ΗΜΕΡΟΜΗΝΙΑ',
	LTRIM(RTRIM(p.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ',
	LTRIM(RTRIM(p.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ',
	case 
		WHEN kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=2 then kp.CodeLog
		when kp.IF_CASH=1 and kp.IF_EMVASMA=0 and kp.IF_EPITAGI=0 and kp.IF_SYNALAGMATIKI=0 and IF_KARTA=0 and p.IDYPOKATASTIMA=17 then '38-00-00-0001'
	else kp.CodeLog															
	END																	AS 'ΛΟΓΑΡΙΑΣΜΟΣ',
	LTRIM(RTRIM(p.KINDPAYMENTDESCR))									AS 'Τρ.ΠΛΗΡΩΜΗΣ',
	1																	AS '(0=ΧΡΕΩΣΗ,1=ΠΙΣΤΩΣΗ)',
	p.sumposo															AS 'ΑΞΙΑ',
	LTRIM(RTRIM(p.KINDPARASTDESCR))+' '+rtrim(ltrim(convert(nvarchar(25),p.DOCNO)))   AS 'ΠΑΡΑΣΤΑΤΙΚΟ_ΑΡΘΡΟΥ',
	LTRIM(RTRIM(p.AITIOLOGIA))											AS 'ΑΙΤΙΟΛΟΓΙΑ_ΑΡΘΡΟΥ',
	''																	AS 'ΚΩΔΙΚΟΣ_ΤΑΜΕΙΑΚΗΣ',
	p.ifDelete															AS 'ΑΚΥΡΩΜΕΝΟ',
	''																	AS 'Πεδίο_Ομαδοποίησης_Ακύρωσης',
	p.IF_EXPORTED
	
from KINDOFPAYMENTS kp
join PAYMENTS p on p.IDKINDPAYMENT=kp.ID
left join accounts pel on pel.id = p.IDCUSTOMER
left join EMPLOYEE empl on empl.id=p.IDCUSTOMER
join kindparastatikon kdp on kdp.id=p.IDKINDPARAST and kdp.IF_ENIMEROSIKARTELA=1 and kdp.KindKINISIS in (3,2)
join COMPANIES c on c.id=p.IDYPOKATASTIMA

GO






---END SCRIPT 2216
