---NEW SCRIPT 2217

create view EBS_ESODA_PATRIKOVASILAKOS AS 
select
	
	convert(nvarchar(20),dateprint,103)			as 'Ημερομηνία',
	isnull(kdp.Abbreviation,'')					as 'Τύπος Παραστατικού ΑΑΔΕ',
	LTRIM(RTRIM(kdp.Abbreviation))+'-'+
	LTRIM(RTRIM(f.SEIRA))+'-'+
	LTRIM(RTRIM(F.NOPARAST))					as 'Κωδικός Παραστατικού',
	isnull(f.AADE_MARK,'')						as 'ΜΑρΚ Παραστατικού',
	isnull(pel.afm,'')							as 'ΑΦΜ Συναλασσομένου',
	pel.Code									as 'Κωδικός Συναλασσομένου',
	pel.Fpa										as 'Καθεστώς ΦΠΑ',
	isnull(f.POSO,0)							as 'Καθαρή Αξία',
	isnull(f.TAXIS,0)							as 'Αξία ΦΠΑ',
	isnull(f.SUMPOSO,0)							as 'Συνολική Αξία',
	f.PARALISPTISDESCR							as 'Παραλήπτης - Επωνυμία',
	isnull(LTRIM(RTRIM(paral.AddressStr)),'')+' '+
	isnull(LTRIM(RTRIM(paral.addressno)),'')	as 'Παραλήπτης - Διεύθυνση',
	isnull(LTRIM(RTRIM(kdp.AADE_CODE)),'')		as 'Κωδικός Παραστατικού ΑΑΔΕ',
	case	
		when isnull(IFEXOFLISI,0)=1 then 'Ναι'
		else 'Όχι'
	end											as 'Εξοφλημένο'	,
	isnull(ltrim(rtrim(f.comments)),'')			as 'Σχόλιο'


from FORTOTIKES f
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST and isnull(kdp.IF_ENIMEROSI_FPA,0)=1
join accounts pel on pel.id=f.IDXREOUMENOU
left join ACCOUNTS paral on paral.id=f.IDPARALIPTI


UNION ALL

select
	
	convert(nvarchar(20),v.DATEPRINT,103)		as 'Ημερομηνία',
	isnull(kdp.Abbreviation,'')					as 'Τύπος Παραστατικού ΑΑΔΕ',
	LTRIM(RTRIM(kdp.Abbreviation))+'-'+
	LTRIM(RTRIM(v.SEIRA))+'-'+
	LTRIM(RTRIM(v.NOPARAST))					as 'Κωδικός Παραστατικού',
	isnull(v.AADE_MARK,'')						as 'ΜΑρΚ Παραστατικού',
	isnull(pel.afm,'')							as 'ΑΦΜ Συναλασσομένου',
	pel.Code									as 'Κωδικός Συναλασσομένου',
	pel.Fpa										as 'Καθεστώς ΦΠΑ',
	isnull(v.POSO,0)							as 'Καθαρή Αξία',
	isnull(v.TAXIS,0)							as 'Αξία ΦΠΑ',
	isnull(v.SUMPOSO,0)							as 'Συνολική Αξία',
	isnull(v.PARALISPTISDESCR,'')				as 'Παραλήπτης - Επωνυμία',
	isnull(LTRIM(RTRIM(paral.AddressStr)),'')+' '+
	isnull(LTRIM(RTRIM(paral.addressno)),'')	as 'Παραλήπτης - Διεύθυνση',
	isnull(LTRIM(RTRIM(kdp.AADE_CODE)),'')		as 'Κωδικός Παραστατικού ΑΑΔΕ',
	case	
		when isnull(IFEXOFLISI,0)=1 then 'Ναι'
		else 'Όχι'
	end											as 'Εξοφλημένο'	,
	isnull(ltrim(rtrim(v.comments)),'')			as 'Σχόλιο'


from VOH v
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST and isnull(kdp.IF_ENIMEROSI_FPA,0)=1
join accounts pel on pel.id=v.IDCUSTOMER
left join ACCOUNTS paral on paral.id=v.IDPARALIPTI

GO


---END SCRIPT 2217
