---NEW SCRIPT 2218

--DROP VIEW EBS_SYNAL_PΑTRIKOVASILAKOS
--GO

create view [dbo].[EBS_SYNAL_PΑTRIKOVASILAKOS] as

select
	
	case catkepyo
		when 0 then 'Νομικό Πρόσωπο'
		when 1 then 'Φυσικό Πρόσωπο'
		when 2 then 'Δημόσιο'
		when 3 then 'Αγρότης'
		when 4 then 'Εξωτερικού'
		else 'Αγνωστο'
	end																	as 'Είδος Προσώπου',
	case 
		when ISNULL(if_pel, 0) = 1 then 
			case 
				when ISNULL(if_pel, 0) = 1  and ISNULL(if_prom, 0) = 1 
					then 'Πελάτης / Προμηθευτής'
				else 'Πελάτης'
			end
		else 'Προμηθευτής'
	end																	as 'Τύπος Συναλλασσόμενου',
	isnull(afm,0)														as 'Αφμ Συναλασσόμενου',
	case FPA
		when '1-Κανονικό' then 'Κανονικό'
		when '2-Μειωμένο' then 'Μειωμένο'
		when '0-Μηδενικό/Ενδοκοινοτικό' then 'Μηδενικό'
	end																	as 'Καθεστώς ΦΠΑ',
	code																as 'Κωδικός',
	Eponimia															as 'Επωνυμία',
	isnull(irs.irsid,'')												as 'ΔΟΥ',
	isnull(Epagelma,'')													as 'Επάγγελμα',
	(isnull(addressstr,'') + isnull(addressNo,''))						as 'Διεύθυνση',
	isnull(AddressCity,'')												as 'Πόλη',
	isnull(AddressPref,'')												as 'Περιοχή',
	isnull(AddressTK,'')												as 'TK',
	isnull(Tel,'')														as 'Τηλέφωνο',
	isnull(email,'')													as 'email'
	
from accounts 
left join IRS on IRS.Description=ACCOUNTS.DOY

GO

---END SCRIPT 2218
