---NEW SCRIPT 2219

CREATE view [dbo].[EBS_EISPRAKSEIS_PLIROMES_PATRIKOVASILAKOS] AS 

select
	convert(nvarchar(20),r.DATEPRINT,103)													as 'Ημερομηνία',
	case 
		when kdp.kindkinisis=3 and kdp.if_aforaextriton=0 
			and kdp.if_pistosi=1 then 'Είσπραξη'
		when kdp.kindkinisis=3 and kdp.if_aforaextriton=1
			and kdp.if_pistosi=1 then 'Είσπραξη για λογαριασμό Τρίτων'
		when kdp.kindkinisis=3 and kdp.if_aforaextriton=1
			and kdp.if_xreosi=1 then 'Πληρωμή για λογαριασμό Τρίτων'
		else ''
	end																						as 'Τύπος Παραστατικού ',
	(isnull(kdp.Abbreviation,'')+'-'+isnull(kdp.SEIRA,'')+convert(nvarchar(50),r.DOCNO))	as 'Κωδικός Παραστατικού',
	case 
		when ISNULL(ac.if_pel, 0) = 1 then 
			case 
				when ISNULL(ac.if_pel, 0) = 1  and ISNULL(ac.if_prom, 0) = 1 
					then 'Πελάτης / Προμηθευτής'
				else 'Πελάτης'
			end
		else 'Προμηθευτής'
	end																						as 'Τύπος Συναλλασσόμενου',
	isnull(ac.AFM,'')																		as 'ΑΦΜ Συναλασσομένου',
	isnull(ac.Code,'')																		as 'Κωδικός Συναλασσομένου',
	isnull(sumposo,0)																		as 'Αξία',
	r.KINDPAYMENTDESCR																		as 'Τρόπος Πληρωμής'
from RECEIPTS r
left join KINDPARASTATIKON kdp on kdp.id=r.IDKINDPARAST
left join accounts ac on ac.id=r.IDCUSTOMER

union all

select
	convert(nvarchar(20),p.DATEPRINT,103)								as 'Ημερομηνία',
	case 
		when kdp.kindkinisis=2 and kdp.if_aforaextriton=0 
			and kdp.if_xreosi=1 then 'Πληρωμή σε Προμηθευτή'
		else ''
	end																						as 'Τύπος Παραστατικού ',
	(isnull(kdp.Abbreviation,'')+'-'+isnull(kdp.SEIRA,'')+convert(nvarchar(50),p.DOCNO))	as 'Κωδικός Παραστατικού',
	case 
		when ISNULL(ac.if_pel, 0) = 1 then 
			case 
				when ISNULL(ac.if_pel, 0) = 1  and ISNULL(ac.if_prom, 0) = 1 
					then 'Πελάτης / Προμηθευτής'
				else 'Πελάτης'
			end
		else 'Προμηθευτής'
	end																						as 'Τύπος Συναλλασσόμενου',
	isnull(ac.AFM,'')																		as 'ΑΦΜ Συναλασσομένου',
	isnull(ac.Code,'')																		as 'Κωδικός Συναλασσομένου',
	isnull(sumposo,0)																		as 'Αξία',
	p.KINDPAYMENTDESCR																		as 'Τρόπος Πληρωμής'
from PAYMENTS p
left join KINDPARASTATIKON kdp on kdp.id=p.IDKINDPARAST
left join accounts ac on ac.id=p.IDCUSTOMER


GO


