---NEW SCRIPT 2224



ALTER VIEW [dbo].[LISTAAPOTHEMATOS] AS

WITH IN_OUT AS (
				SELECT
					--ID,
					MAX(SYSKEVASIA) AS SYSKEVASIA,
					IDPOSITION,
					IDITEM AS IDITEM,
					--IDVOH,
					MIN(TEMDESCR) AS ITEMDESCR,
					SUM(TEMAXIA * IF_IN) AS EISAGOGI,
					SUM(TEMAXIA* IF_OUT) AS EXAGOGI,
					(SUM(TEMAXIA * ISNULL(IF_IN,0)) - SUM(TEMAXIA * ISNULL(IF_OUT,0))) AS TEMAXIA--,
					--CASE	
					--	WHEN ISNULL(IF_IN,0) = 1 THEN SUM(TEMAXIA)
					--	WHEN ISNULL(IF_OUT,0) = 1 THEN SUM(TEMAXIA) * (-1)
					--	ELSE 0 
					--END AS TEMAXIA
				FROM ITEMSTRANS
				WHERE ifDelete=0
				GROUP BY 
					IDITEM,
					IDPOSITION
					HAVING ((SUM(TEMAXIA * ISNULL(IF_IN,0)) - SUM(TEMAXIA * ISNULL(IF_OUT,0)))) > 0
				

	)

SELECT distinct
	PO.ID						AS ID,
	WH.DESCRIPTION				AS WAREHOUSE,
	HW.DESCRIPTION				AS HALLWAY,
	DP.DESCRIPTION				AS DEPTH,
	LV.DESCRIPTION				AS [LEVEL],
	PO.DESCRIPTION				AS POSITION,
	PD.Descr					AS ITEM,
	PD.ID						AS ITEMID,
	IPP.TEMAXIA					AS TEMAXIA,
	IPP.SYSKEVASIA				AS SYSKEVASIA--,
	--IPP.IDVOH

FROM ITEMSTRANS ITS
JOIN IN_OUT IPP ON IPP.IDITEM=ITS.IDITEM 
JOIN Positions PO ON PO.id=ITS.IDPOSITION
JOIN PRODUCTS PD ON PD.ID=ITS.IDITEM
JOIN WAREHOUSE WH ON WH.id=PO.IDWAREHOUSE
JOIN HallWays HW ON HW.ID=PO.IDHALLWAY
JOIN DEPTHS DP ON DP.ID=PO.IDDEPTH
JOIN Levels LV ON LV.id=PO.IDLEVEL



GO








---END SCRIPT 2224
