ALTER view [dbo].[Fortotikes_WithDetails_Export]
as
select
	f.ID,
	f.IDENTOLEA,
	f.IDAPOSTOLEA,
	f.IDPARALIPTI,
	f.IDTRITOU,
	f.IDANTAPOKRITI,
	
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE	F.PARASTATIKO
	END AS [Παραστατικό],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE	CONVERT(DATE,F.DATEPRINT)
	END AS [Ημερομηνία],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.NOPARAST 
	END AS [Αρ Παραστατικου],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.APOSTOLEASDESCR
	END AS [Αποστολέας],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.PARALISPTISDESCR
	END AS [Παραλήπτης],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.ENTOLEASDESCR 
	END AS [Εντολέας],
	f.NOPARASTDELTIOUDIANOMIS [Συγκ Τιμολόγιο],	
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.OMADPROORISMOS  
	END AS 	[Ομ Προορισμος],
	gf.TIMDA [Τιμ-Δα],
	gf.TEMAXIA [Τεμάχια],
	gf.SYSKEVASIADESCR [Συσκευασία],
	gf.BAROS [Βάρος],
	gf.KYBIKA [Κυβικά],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.POSO 
	END AS [Καθ Αξία],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.TAXIS 
	END AS [ΦΠΑ],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE f.SUMPOSO
	END AS	[Σύνολο],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE F.STATUSDESCR
	END AS [Κατάσταση],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE F.PRAKTOREIODESCR
	END AS [Πρακτορείο],
	CASE	
		WHEN ROW_NUMBER() OVER (PARTITION BY F.ID ORDER BY F.ID)>1 THEN NULL
		ELSE F.COMMENTS
	END AS [Σχόλια] 

from FORTOTIKES f 
join GRAMMESFORTTIKIS gf on gf.IDVOH=f.ID
where f.ifDelete=0



GO

---END SCRIPT 2231
