ALTER TABLE VOH ADD IF_EDI_SEND bit null
go

alter table voh add IF_TO_PORT bit null
go

alter table kindparastatikon add IF_ENIM_EDI bit null
go

create view FOR_EDI_VIEW AS 

select 
	v.id,
	convert(nvarchar(10),v.DATEPRINT,103)							as issue_date,
	v.parastatiko													as parast_description,
	rtrim(ltrim(convert(nvarchar(10),v.seira)))+' '+
	rtrim(ltrim(convert(nvarchar(10),v.noparast)))					as parast_number,
	v.CODEAPOSTOLEA													as sender_code,
	APOSTOLEASDESCR													as apostoleas,
	v.CODEPARALIPTI													as receiver_code,
	PARALISPTISDESCR												as receiver,
	v.CODEENTOLEA													as customer_code,
	ENTOLEASDESCR													as customer,
	v.SXETIKAPARASTATIKA											as sxetikaparastatika,
	gv.CodeEidos													as container,
	gv.DescrEidos													as eidos,
	gv.LOTNUMBER													as seal_number,
	gv.TEMAXIA														as quantity,
	isnull(v.IF_EDI_SEND,0)											as IF_EDI_SEND,
	isnull(v.IF_TO_PORT,0)											as IF_TO_PORT
	

from voh v
join grammesvoh gv on gv.idvoh=v.id
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
where 1=1 
and	kdp.IF_ENIMEROSIAPOTHIKI=1 
and kdp.KindKINISIS in (1,0)
and kdp.IF_ENIM_EDI=1

GO


---END SCRIPT 2236
------------------------------------------------------------------------------------


---NEW SCRIPT 2237

alter table voh add [FULL_EMPTY] bit null
go



ALTER view [dbo].[FOR_EDI_VIEW] AS 

select 
	v.id,
	ypok.eet_am																						as depo_code,
	case 
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=1 and kdp.ifexagogi=0 then 1
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 then 2
	end																								as [gate_in(1)/gate_out(2)],
	isnull(v.full_empty,0)																			as [full(1)_empty(0)],
	convert(nvarchar(10),v.DATEPRINT,103)															as issue_date,
	v.parastatiko																					as parast_description,
	rtrim(ltrim(convert(nvarchar(10),v.seira)))+' '+
	rtrim(ltrim(convert(nvarchar(10),v.noparast)))													as parast_number,
	v.CODEAPOSTOLEA																					as sender_code,
	APOSTOLEASDESCR																					as apostoleas,
	v.CODEPARALIPTI																					as receiver_code,
	PARALISPTISDESCR																				as receiver,
	v.CODEENTOLEA																					as customer_code,
	ENTOLEASDESCR																					as customer,
	v.SXETIKAPARASTATIKA																			as booking_number,
	gv.CodeEidos																					as container,
	gv.DescrEidos																					as eidos,
	gv.LOTNUMBER																					as seal_number,
	gv.TEMAXIA																						as quantity,
	isnull(v.IF_EDI_SEND,0)																			as IF_EDI_SEND,
	isnull(v.IF_TO_PORT,0)																			as IF_TO_PORT
	

from voh v
join grammesvoh gv on gv.idvoh=v.id
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
join COMPANIES ypok on ypok.id=v.IDYPOKATASTIMA
where 1=1 
and	kdp.IF_ENIMEROSIAPOTHIKI=1 
and kdp.KindKINISIS in (1,0)
and kdp.IF_ENIM_EDI=1

GO




---END SCRIPT 2237
------------------------------------------------------------------------------------


