	BEGIN
	IF LEN(@SEIRA) >0
		BEGIN 
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM VOH WITH (NOLOCK) WHERE  SEIRA = @SEIRA AND  IDPARAST =@IDPARAST)
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM VOH WITH (NOLOCK) WHERE SEIRA = @SEIRA AND  IDPARAST =@IDPARAST
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END
		END;
	ELSE
		BEGIN
			if EXISTS (SELECT (ISNULL(CAST(NOPARAST AS int),0)) FROM VOH WITH (NOLOCK) WHERE  ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST)
				 BEGIN
					SELECT @NEWNOPARAST = ROUND(MAX(ISNULL(CAST(NOPARAST AS int) +1, 0)),0)  FROM VOH WITH (NOLOCK) WHERE ((SEIRA ='') OR (SEIRA IS NULL)) AND  IDPARAST =@IDPARAST
					SET @NOPARAST = replace(@NEWNOPARAST,'.00','')
				 END 
			ELSE
				 BEGIN
					SET @NOPARAST =  1
				 END
		END;
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END;
	
			
			UPDATE VOH 
