	@IfPlacement							int = 0,
	@IfAssembly								int = 0,
	@IfDisAssembly							int = 0,
	@IF_ANTIKCASHSYNAR						int = 0,
	@ANTIKCASHSYNAR							NUMERIC(18, 2) = 0,	
	@IF_ZERO_ON_NEW_YEAR					INT = 0,
	@IDSYSXETIZOMENOU						INT = NULL,
	@POSITION								NVARCHAR(50) = NULL,
	@IF_TO_PORT								Bit = 0,
	@FULL_EMPTY								Bit = 0,
	@TheID									NUMERIC(18, 0)= NULL output
	)
AS


SET NOCOUNT ON;

DECLARE @RC INT
SELECT 
	@IFAUTONUMBER = IF_AUTONUMBER,
	@IF_ZERO_ON_NEW_YEAR  = IF_ZERO_ON_NEW_YEAR 
FROM KINDPARASTATIKON WHERE ID=@IDPARAST;

Begin tran
Exec @RC =sp_getapplock @Resource='InserttoVOH', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout = 1000


DECLARE @NEWNOPARAST NUMERIC(18,2)=0


IF @IFAUTONUMBER = 1 BEGIN 
	IF @IF_ZERO_ON_NEW_YEAR = 1 BEGIN
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM VOH 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
		AND YEAR(DATEPRINT) = YEAR(@DATEPRINT)
	END
	ELSE BEGIN	
		SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
		FROM VOH 
		WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
		AND IDPARAST = @IDPARAST 
		AND ifDelete != 1
	END
	
	UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
END

