---NEW SCRIPT 2242



CREATE VIEW [dbo].[YPOLOIPOAPOTHIKISPERLOT] AS 
SELECT 
PRODUCTS.ID, 
GRAMMESVOH.CodeEidos, 
--GRAMMESVOH.EndDate, 
GRAMMESVOH.LOTNUMBER,
MAX(productS.Descr) AS DescrEidos, 
GRAMMESVOH.SYSKEVASIA AS SYSKEVASIA,
SUM(GRAMMESVOH.TEMAXIA * IFEISAGOGI ) AS EISAGOGES, 
SUM(GRAMMESVOH.TEMAXIA*IFEXAGOGI ) AS EXAGOGES, 
SUM(GRAMMESVOH.TEMAXIA*IFEISAGOGI) - SUM(GRAMMESVOH.TEMAXIA * IFEXAGOGI ) AS YPOLOIPO, 
MIN(CONVERT(varchar,(CONVERT(date,VOH.DATEPRINT,103)),103)) AS FROMDATE, 
MAX(CONVERT(varchar,(CONVERT(date,VOH.DATEPRINT,103)),103)) AS TODATE, 
PRODUCTS.BarCode
FROM GRAMMESVOH WITH (NOLOCK) INNER JOIN
dbo.VOH WITH (NOLOCK) ON dbo.GRAMMESVOH.IDVOH = dbo.VOH.ID and VOH.ifDelete = 0
INNER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.VOH.IDPARAST = dbo.KINDPARASTATIKON.ID
INNER JOIN dbo.PRODUCTS WITH (NOLOCK) ON dbo.GRAMMESVOH.CodeEidos = dbo.PRODUCTS.Code
WHERE PRODUCTS.ifDelete = 0 AND (dbo.VOH.IDPARAST IN
(SELECT ID FROM  dbo.KINDPARASTATIKON AS KINDPARASTATIKON_1 WITH (NOLOCK) 
WHERE (IF_PAROXIYPIRESION <> 1 AND IF_ENIMEROSIAPOTHIKI = 1)))
GROUP BY PRODUCTS.ID, GRAMMESVOH.CodeEidos, --GRAMMESVOH.EndDate, 
GRAMMESVOH.SYSKEVASIA,
PRODUCTS.BarCode,GRAMMESVOH.LOTNUMBER
HAVING ((sum(GRAMMESVOH.TEMAXIA*IFEISAGOGI) - sum(GRAMMESVOH.TEMAXIA * IFEXAGOGI ))<>0)


GO


---END SCRIPT 2242
------------------------------------------------------------------------------------



