CREATE VIEW PositionsView 
AS
SELECT p.ID,
p.Code,
p.FullCode,
p.DESCRIPTION,
l.ID AS IDLEVEL,
l.DESCRIPTION AS LEVEL,
d.ID AS IDDEPTH,
d.DESCRIPTION AS DEPTH,
hw.ID AS IDHALLWAY,
hw.DESCRIPTION AS HALLWAY,
w.ID AS IDWAREHOUSE,
w.DESCRIPTION AS WAREHOUSE,
p.ifDelete
FROM Positions AS p INNEr JOIN Levels AS l ON p.IDLEVEL = l.id 
INNER JOIN Depths as d ON p.IDDEPTH = d.id 
INNER JOIN HallWays AS hw on p.IDHALLWAY = hw.id 
INNER JOIN WAREHOUSE AS w ON p.IDWAREHOUSE = w.id
go

---END SCRIPT 2244
------------------------------------------------------------------------------------

---NEW SCRIPT 2245

exec sp_rename 'YPOLOIPOAPOTHIKISPERLOT','YPOLOIPOAPOTHIKISPERLOT_OLD'
GO

create view YPOLOIPOAPOTHIKISPERLOT as 
with eisagoges_ana_lot as (

							select
								pr.ID,
								CodeEidos,
								max(gv.DescrEidos) as DescrEidos,
								sum(isnull(gv.TEMAXIA,0)) as TEMAXIA,
								gv.LOTNUMBER
							from grammesvoh gv
							join voh v on v.id=gv.IDVOH
							join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
							join Products pr on pr.Code=gv.CodeEidos
							where kdp.IF_ENIMEROSIAPOTHIKI=1 
								and  kdp.IFEISAGOGI=1
							group by gv.CodeEidos,
									pr.ID,
									gv.LOTNUMBER
							having IsNull(gv.lotnumber,0)!=0
	),
exagoges_ana_lot as (
							select
								pr.ID,
								CodeEidos,
								max(gv.DescrEidos) as DescrEidos,
								sum(isnull(gv.TEMAXIA,0)) as TEMAXIA,
								gv.LOTNUMBER
							from grammesvoh gv
							join voh v on v.id=gv.IDVOH
							join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
							join Products pr on pr.Code=gv.CodeEidos
							where kdp.IF_ENIMEROSIAPOTHIKI=1 
								and  kdp.IFEXAGOGI=1
							group by gv.CodeEidos,
									pr.ID,
									gv.LOTNUMBER
							having IsNull(gv.lotnumber,0)!=0
),

ypoloipo_ana_lot as (
						select 
							
							gv.CodeEidos,
							gv.DescrEidos,
							gv.SYSKEVASIA,
							gv.LOTNUMBER,
							(isnull(esl.temaxia,0) - isnull(exl.temaxia,0)) as ypoloipo
						from GRAMMESVOH gv 
						left join eisagoges_ana_lot esl on esl.CodeEidos=gv.CodeEidos
						left join exagoges_ana_lot exl on exl.CodeEidos=gv.CodeEidos
						group by gv.CodeEidos,
								 gv.DescrEidos,
								 gv.SYSKEVASIA,
								 gv.LOTNUMBER,
								 esl.temaxia,
								 exl.temaxia
							having IsNull(gv.lotnumber,0)!=0
									and isnull((isnull(esl.temaxia,0) - isnull(exl.temaxia,0)),0)!=0

)



select

	pr.id,
	yal.CodeEidos,
	yal.DescrEidos,
	yal.SYSKEVASIA,
	isnull(esl.TEMAXIA,0)			as EISAGOGES,
	isnull(exl.TEMAXIA,0)			as EXAGOGES,
	yal.ypoloipo					as YPOLOIPO,
	yal.LOTNUMBER
	
from ypoloipo_ana_lot yal
left join Products pr on pr.Code=yal.CodeEidos
left join eisagoges_ana_lot esl on esl.CodeEidos=yal.CodeEidos
left join exagoges_ana_lot exl on exl.CodeEidos=yal.CodeEidos


go


---END SCRIPT 2245
------------------------------------------------------------------------------------



