---NEW SCRIPT 2248

alter view FOR_EDI_VIEW as 

select 
	v.id,
	v.ProcessingStatus,
	v.LastAttemptTimestamp,
	v.ProcessingNotes,
	v.SentPayload,
	'Maersk'																						as EdiPartnerName,--???
	
	case 
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=1 and kdp.ifexagogi=0 then 'GATEIN'
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 then 'GATEOUT'
	end																								as MovementType,
	v.APOSTOLEASDESCR																				as SenderName,
	v.CODEAPOSTOLEA																					as SenderCode,
	v.PARALISPTISDESCR																				as RecipientName,	
	v.CODEPARALIPTI																					as RecipientCode,
	v.ENTOLEASDESCR																					as PrincipalName,
	v.CODEENTOLEA																					as PrincipalCode,
	gv.CodeEidos																					as ContainerNumber,
	case
		when isnull(v.full_empty,0)=0 then 'EMPTY'
		when isnull(v.full_empty,0)=1 then 'FULL'

	end																								as FullEmptyStatus,
	case 
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=1 and kdp.ifexagogi=0 then 'IMPORT'
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 then 'EXPORT'
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 
					and kdp.IFENDODIAKINISI=1											   then 'POSITIONING'
	end																								as EquipmentStatus,
	v.sumbaros																						as GrossWeight,
	v.sumogos																						as Volume,
	v.dateprint																						as MovementTimestamp,
	ypok.eet_am																						as DepotLocationCode,--???
	isnull(v.IF_TO_PORT,0)																			as IfToPort,
	case 
		when isnull(v.IF_TO_PORT,0)=1 then v.CODEPARALIPTI
		else NULL
	end																								as PortCode,
	v.SXETIKAPARASTATIKA																			as BookingNumber,
	gv.LOTNUMBER																					as SealNumber
	
	
	
	--v.parastatiko																					as parast_description,
	--rtrim(ltrim(convert(nvarchar(10),v.seira)))+' '+
	--rtrim(ltrim(convert(nvarchar(10),v.noparast)))													as parast_number,
	--gv.TEMAXIA																						as quantity,
	--isnull(v.IF_EDI_SEND,0)																			as IF_EDI_SEND,
	
	

from voh v
join grammesvoh gv on gv.idvoh=v.id
join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
join COMPANIES ypok on ypok.id=v.IDYPOKATASTIMA
where 1=1 
and	kdp.IF_ENIMEROSIAPOTHIKI=1 
and kdp.KindKINISIS in (1,0)
and kdp.IF_ENIM_EDI=1

GO



---END SCRIPT 2248
------------------------------------------------------------------------------------

