		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 then 'EXPORT'
		when isnull(kdp.IF_ENIMEROSIAPOTHIKI,0)=1 and kdp.IFEISAGOGI=0 and kdp.ifexagogi=1 
