ALTER view [dbo].[YPOLOIPOAPOTHIKISPERLOT] as 
with eisagoges_ana_lot as (

							select
								pr.ID,
								CodeEidos,
								max(gv.DescrEidos) as DescrEidos,
								sum(isnull(gv.TEMAXIA,0)) as TEMAXIA,
								gv.LOTNUMBER
							from grammesvoh gv
							join voh v on v.id=gv.IDVOH
							join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
							join Products pr on pr.Code=gv.CodeEidos
							where kdp.IF_ENIMEROSIAPOTHIKI=1 
								and  kdp.IFEISAGOGI=1
							group by gv.CodeEidos,
									pr.ID,
									gv.LOTNUMBER
							having IsNull(gv.lotnumber,'')!=''
	),
exagoges_ana_lot as (
							select
								pr.ID,
								CodeEidos,
								max(gv.DescrEidos) as DescrEidos,
								sum(isnull(gv.TEMAXIA,0)) as TEMAXIA,
								gv.LOTNUMBER
							from grammesvoh gv
							join voh v on v.id=gv.IDVOH
							join KINDPARASTATIKON kdp on kdp.id=v.IDPARAST
							join Products pr on pr.Code=gv.CodeEidos
							where kdp.IF_ENIMEROSIAPOTHIKI=1 
								and  kdp.IFEXAGOGI=1
							group by gv.CodeEidos,
									pr.ID,
									gv.LOTNUMBER
							having IsNull(gv.lotnumber,'')!=''
),

ypoloipo_ana_lot as (
						select 
							
							gv.CodeEidos,
							gv.DescrEidos,
							gv.SYSKEVASIA,
							gv.LOTNUMBER,
							(isnull(esl.temaxia,0) - isnull(exl.temaxia,0)) as ypoloipo
						from GRAMMESVOH gv 
						left join eisagoges_ana_lot esl on esl.CodeEidos=gv.CodeEidos
						left join exagoges_ana_lot exl on exl.CodeEidos=gv.CodeEidos
						group by gv.CodeEidos,
								 gv.DescrEidos,
								 gv.SYSKEVASIA,
								 gv.LOTNUMBER,
								 esl.temaxia,
								 exl.temaxia
							having IsNull(gv.lotnumber,'')!=''
									and isnull((isnull(esl.temaxia,0) - isnull(exl.temaxia,0)),0)!=0

)



select

	pr.id,
	yal.CodeEidos,
	yal.DescrEidos,
	yal.SYSKEVASIA,
	sum(isnull(esl.TEMAXIA,0))			as EISAGOGES,
	sum(isnull(exl.TEMAXIA,0))			as EXAGOGES,
	sum(yal.ypoloipo)					as YPOLOIPO,
	yal.LOTNUMBER
	
from ypoloipo_ana_lot yal
left join Products pr on pr.Code=yal.CodeEidos
left join eisagoges_ana_lot esl on esl.CodeEidos=yal.CodeEidos
left join exagoges_ana_lot exl on exl.CodeEidos=yal.CodeEidos
group by 	pr.id,
	yal.CodeEidos,
	yal.DescrEidos,
	yal.SYSKEVASIA,
	yal.LOTNUMBER

GO




