create view Lista_Paradoseon as 
select 
    f.ENTOLEASDESCR												as [Εντολέας]
   ,convert(nvarchar(20),f.dateprint,103)						as [Ημερ.Αποστολής]
   ,f.PARALISPTISDESCR											as [Παραλήπτης]
   ,(paral.AddressStr+ ' ' + isnull(paral.AddressNo,''))		as [Διευθ.Παραλήπτη]
   ,f.PERIOXIPARADOSIS											as [Παράδοση]
   ,paral.AddressTK												as [Τ.Κ.Παράδοσης]
   ,gf.TIMDA													as [Τιμ/Δα]
   ,sum(gf.TEMAXIA)												as [Τεμάχια]
   ,f.DATEPARAD													as [Ημερ.Παράδοσης]
from FORTOTIKES f
left join ACCOUNTS paral on paral.id = f.IDPARALIPTI
left join GRAMMESFORTTIKIS gf on gf.IDVOH=f.ID
where IFPARADOSITOPEL=1
group by 
	f.ENTOLEASDESCR
   ,convert(nvarchar(20),f.dateprint,103)
   ,f.PARALISPTISDESCR
   ,(paral.AddressStr+ ' ' + isnull(paral.AddressNo,''))	
   ,f.PERIOXIPARADOSIS
   ,paral.AddressTK
   ,gf.TIMDA
   ,f.DATEPARAD

GO


