------------------------------------------------------------------------------------
---NEW SCRIPT 2256

 ALTER VIEW [dbo].[SUMPOSA_PER_ACCOUNT_PEL]
AS 
 SELECT 
		
	   accounts.id,
       accounts.code,
       accounts.afm,
       accounts.eponimia,
       accounts.addresscity,
       accounts.tel,
       accounts.if_pel,
       accounts.if_prom,
       case ISNULL(kindparastatikon.if_xreosi,0) * 1 + ISNULL(kindparastatikon.if_pistosi,0) * 2
		when 1 then ISNULL(sumposo,0)
		when 2 then ISNULL(sumposo,0) * -1
		else 0
		end AS SUMPOSO,
       dateprint,
       accounts.ifdelete,
       fortotikes.idcompany,
       fortotikes.idypokatastima,
	   ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC
FROM fortotikes
LEFT JOIN kindparastatikon
      ON fortotikes.idparast = kindparastatikon.id
         AND (kindparastatikon.if_xreosi = 1 or kindparastatikon.if_pistosi = 1)
         AND kindparastatikon.if_enimerosikartela = 1
         AND kindparastatikon.kindkinisis IN( 1, 5 )
LEFT OUTER JOIN parastatika_ana_kathgoria
            ON parastatika_ana_kathgoria.id_kindparastatikon =
               dbo.kindparastatikon.id
INNER JOIN cat_parastatikon
       ON cat_parastatikon.id =
          parastatika_ana_kathgoria.id_cat_parastatikon
          AND if_exodo = 0
INNER JOIN accounts
       ON fortotikes.idxreoumenou = accounts.id
          AND accounts.ifdelete = 0 and ACCOUNTS.IF_PEL=1
WHERE  fortotikes.ifdelete = 0


union ALL



SELECT 
	   accounts.id,
       accounts.code,
       accounts.afm,
       accounts.eponimia,
       accounts.addresscity,
       accounts.tel,
       accounts.if_pel,
       accounts.if_prom,
       case isnull(kindparastatikon.if_xreosi, 0) * 1 + isnull(kindparastatikon.if_pistosi,0) * 2
		when 1 then ISNULL(voh.sumposo, 0) + ISNULL(voh.sumposoepivar, 0)
		when 2 then (ISNULL(voh.sumposo, 0) + ISNULL(voh.sumposoepivar, 0)) * -1
		else 0
		end AS SUMPOSO,
       dateprint,
       accounts.ifdelete,
       voh.idcompany,
       voh.idypokatastima,
	   ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC
FROM   voh
       LEFT JOIN kindparastatikon
              ON voh.idparast = kindparastatikon.id
                 AND (kindparastatikon.if_xreosi = 1 or kindparastatikon.if_pistosi = 1)
                 AND kindparastatikon.if_enimerosikartela = 1
                 AND kindparastatikon.kindkinisis IN( 1, 5 )
       INNER JOIN accounts
               ON voh.idcustomer = accounts.id
                  AND accounts.ifdelete = 0 and ACCOUNTS.IF_PEL=1
WHERE  voh.ifdelete = 0

union ALL


SELECT 
	   accounts.id,
       accounts.code,
       accounts.afm,
       accounts.eponimia,
       accounts.addresscity,
       accounts.tel,
       accounts.if_pel,
       accounts.if_prom,
       case ISNULL(kindparastatikon.if_xreosi,0) * 1 + ISNULL(kindparastatikon.if_pistosi,0) * 2
		when 1 then ISNULL(sumposo,0) 
		when 2 then ISNULL(sumposo,0) * - 1
		else 0 
		end AS SUMPOSO,
       dateprint,
       accounts.ifdelete,
       esoda.idcompany,
       esoda.idypokatastima,
	   ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC
FROM   esoda
       LEFT JOIN kindparastatikon
              ON esoda.idparast = kindparastatikon.id
                 AND (ISNULL(kindparastatikon.if_xreosi, 0) = 1 or ISNULL(kindparastatikon.if_pistosi, 0) = 1)
                 AND kindparastatikon.if_enimerosikartela = 1
                 AND kindparastatikon.kindkinisis IN( 1, 5 )
       INNER JOIN accounts
               ON esoda.idprom = accounts.id
                  AND accounts.ifdelete = 0 and ACCOUNTS.IF_PEL=1
WHERE  esoda.ifdelete = 0

UNION ALL


SELECT 
	   accounts.id,
       accounts.code,
       accounts.afm,
       accounts.eponimia,
       accounts.addresscity,
       accounts.tel,
       accounts.if_pel,
       accounts.if_prom,
       case ISNULL(kindparastatikon.if_xreosi,0) * 1 + ISNULL(kindparastatikon.if_pistosi,0) * 2 
		when 1 then ISNULL(sumposo,0)
		when 2 then ISNULL(sumposo,0) * -1
		else 0
		end AS SUMPOSO,
       dateprint,
       accounts.ifdelete,
       receipts.idcompany,
       receipts.idypokatastima,
	   ACCOUNTS.IDYPOKATASTIMA AS IDYPOKATASTIMAACC
FROM   receipts
       LEFT JOIN kindofpayments
              ON receipts.idkindpayment = kindofpayments.id
                 AND kindofpayments.if_cash = 1-- AND IF_IN = 1 
       LEFT JOIN kindparastatikon WITH (nolock)
              ON receipts.idkindparast = kindparastatikon.id
       INNER JOIN accounts
               ON receipts.idcustomer = accounts.id
                 AND accounts.ifdelete = 0 and ACCOUNTS.IF_PEL=1
WHERE  receipts.ifdelete = 0
       AND ( ( ifenimerositameio = 1
                OR if_enimerosikartela = 1 ))
       


GO




---END SCRIPT 2256
