ALTER VIEW EXTRA_ERGASIESVIEW AS
SELECT 
  TOP (100) PERCENT id, 
  TheTime, 
  theDate, 
  CASE dayOfWeek 
	WHEN 0 THEN 'Δευτέρα' 
	WHEN 1 THEN 'Τρίτη' 
	WHEN 2 THEN 'Τετάρτη' 
	WHEN 3 THEN 'Πέμπτη' 
	WHEN 4 THEN 'Παρασκευή' 
	WHEN 5 THEN 'Σάββατο' 
	WHEN 6 THEN 'Κυριακή' 
	WHEN -1 THEN 'Κυριακή' 
END AS dayOfWeek, 
  DescrOxima, 
  DescrOdigou, 
  DescrEntolea, 
  DescrPelatis, 
  AddressFortosis, 
  Descr, 
  DescrEidousErgasias, 
  CommentsErgasias, 
  AnamEsodo, 
  AnamKostos, 
  AnamEsodo - AnamKostos AS AnamKerdos, 
  CodeNum, 
  idKentroukostous, 
  descrKentrouKostous, 
  idOdigou, 
  idOxima, 
  idEidousErgasias, 
  eidosProgramatismou, 
  ifContinous, 
  ifWeekly, 
  IfOnce, 
  ifStop, 
  CommentsForThesaloniki, 
  idPelatis, 
  Polhths, 
  DescrTimologiti, 
  NO_EXT_ORDER, 
  Code, 
  Ergates, 
  IF_TRANSFORM, 
  idEntolea, 
  IDPARALIPTI, 
  PARALIPTISDESCR,
  ShippingCompany,
  DeliveryDriver,
  BoardingPosition,
  Ship,
  Trailer,
  IDXRHSHS, 
  IDCOMPANY, 
  IDYPOKATASTIMA, 
  UserCreate, 
  DateCreate, 
  ifDelete 
FROM 
  dbo.EXTRA_ERGASIES WITH (NOLOCK) 
ORDER BY 
  DescrPelatis, 
  AddressFortosis, 
  Descr, 
  theDate


  go

---END SCRIPT 2272
