ALTER VIEW [dbo].[EXODA_VIEW] AS

WITH PARASTATIKO AS (
						SELECT
							ID
						FROM KINDPARASTATIKON	
						WHERE (IF_ENIMEROSIKARTELA = 1) 
							   OR (IF_ENIMEROSIKARTELA = 0)
							   AND IfKAA!=1
					),
parastatika_sign as (
					select 
						id,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then ( -1)
							when 2 then 1
							else ( -1)
						end AS signs
				from KINDPARASTATIKON kp)

SELECT 
		EX.ID, 
		EX.DATEPRINT, 
		EX.PARASTATIKO, 
		EX.SEIRA, 
		EX.NOPARAST, 
		EX.AFORA AS AFORA, 
		EX.THETIME, 
		EX.EPON, 
		EX.AFM, 
		EX.DOY, 
		EX.ADDRESS, 
		EX.ADDRCITY, 
		EX.ADDRCOUNTRY, 
		EX.ADDRNOMOS, 
		EX.TEL, 
		EX.FAX, 
		EX.MOBILE, 
		EX.POSO * ps.signs				as POSO, 
		EX.TAXISPERCENT, 
		EX.TAXIS * ps.signs				as TAXIS, 
		EX.SUMPOSO * ps.signs			as SUMPOSO, 
		EX.COMMENTS, 
		EX.OXIMA, 
		EX.YPALLILOS, 
		EX.MHNASPOYAFORA, 
		EX.ETOSPOYAFORA, 
		EX.ifDelete, 
		EX.EPAG, 
		EX.THESI, 
		EX.IFEXOFLISI, 
		EX.IFPROKATABOLI, 
		EX.KLM, 
		EX.LTR, 
		EX.POSOPERLTR, 
		EX.IDKINDPAYMENT, 
		EX.KINDPAYMENTDESCR, 
		EX.IDDRIVER, 
		EX.DRIVERDESCR, 
		EX.IDXRHSHS, 
		EX.IDCOMPANY, 
		EX.IDYPOKATASTIMA, 
		EX.IDPROM 
FROM 
  dbo.EXODA EX WITH (NOLOCK) 
JOIN PARASTATIKO PAR ON PAR.ID=EX.IDPARAST
join parastatika_sign ps on ps.ID=ex.IDPARAST



GO


---END SCRIPT 2277
