ALTER VIEW [dbo].[KARTELES_ERGAZ] AS 
SELECT 
  dbo.EMPLOYEE.id AS ACCOUNTID, 
  dbo.EMPLOYEE.Eponimia, 
  dbo.EMPLOYEE.Epagelma, 
  dbo.EMPLOYEE.AddressStr, 
  dbo.EMPLOYEE.AddressNo, 
  dbo.EMPLOYEE.Code, 
  dbo.EMPLOYEE.AddressTK, 
  dbo.EMPLOYEE.Tel, 
  dbo.EMPLOYEE.Tel2, 
  dbo.EMPLOYEE.Fax, 
  dbo.EMPLOYEE.Mobile, 
  dbo.EMPLOYEE.AFM, 
  NULL AS IF_PROM, 
  NULL AS IF_PEL, 
  NULL AS IF_ERG, 
  '104' + CAST(dbo.EXODA.ID AS NVARCHAR(20)) AS ID, 
  dbo.EXODA.DATEPRINT, 
  dbo.EXODA.THETIME, 
  dbo.EXODA.SEIRA, 
  dbo.EXODA.NOPARAST AS DOCNO, 
  dbo.EXODA.AFORA, 
  dbo.EXODA.IDPARAST, 
  dbo.EXODA.PARASTATIKO, 
  'ΕΞΟΔΑ' AS EIDOSKINHSHS, 
  dbo.EXODA.IDDRIVER, 
  dbo.EXODA.DRIVERDESCR, 
  dbo.EXODA.SUMPOSO * dbo.KINDPARASTATIKON.IF_XREOSI AS XREOSI, 
  dbo.EXODA.SUMPOSO * dbo.KINDPARASTATIKON.IF_PISTOSI AS PISTOSI, 
  '' AS AITIOLOGIA, 
  '' AS EISPRAXAS, 
  dbo.EXODA.MHNASPOYAFORA, 
  dbo.EXODA.ETOSPOYAFORA, 
  dbo.EXODA.IFEXOFLISI, 
  dbo.EXODA.IFPROKATABOLI, 
  dbo.EXODA.COMMENTS, 
  dbo.EXODA.OXIMA, 
  NULL AS IDKINDPAYMENT, 
  '' AS KINDPAYMENTDESCR, 
  dbo.EXODA.ifDelete, 
  dbo.EXODA.IDXRHSHS, 
  dbo.EXODA.IDCOMPANY, 
  dbo.EXODA.IDYPOKATASTIMA 
FROM 
  dbo.EMPLOYEE WITH (NOLOCK) 
  INNER JOIN dbo.EXODA WITH (NOLOCK) ON dbo.EMPLOYEE.id = dbo.EXODA.IDPROM and EXODA.ifdelete=0
  INNER JOIN dbo.KINDPARASTATIKON WITH (NOLOCK) ON dbo.EXODA.IDPARAST = dbo.KINDPARASTATIKON.ID 
WHERE 
  EXODA.IDPARAST IN(
    SELECT 
      ID_KINDPARASTATIKON AS ID 
    FROM 
      dbo.PARASTATIKA_ANA_KATHGORIA WITH (NOLOCK) 
    WHERE 
      ID_CAT_PARASTATIKON = 2
  ) 
  --(dbo.EMPLOYEE.IF_ERG = 1)
UNION 
SELECT 
  EMPLOYEE_4.id AS ACCOUNTID, 
  EMPLOYEE_4.Eponimia, 
  EMPLOYEE_4.Epagelma, 
  EMPLOYEE_4.AddressStr, 
  EMPLOYEE_4.AddressNo, 
  EMPLOYEE_4.Code, 
  EMPLOYEE_4.AddressTK, 
  EMPLOYEE_4.Tel, 
  EMPLOYEE_4.Tel2, 
  EMPLOYEE_4.Fax, 
  EMPLOYEE_4.Mobile, 
  EMPLOYEE_4.AFM, 
  NULL AS IF_PROM, 
  NULL AS IF_PEL, 
  NULL AS IF_ERG, 
  '106' + CAST(dbo.PAYMENTS.ID AS NVARCHAR(20)) AS ID, 
  dbo.PAYMENTS.DATEPRINT, 
  NULL AS THETIME, 
  dbo.PAYMENTS.SEIRA, 
  dbo.PAYMENTS.DOCNO, 
  NULL AS AFORA, 
  dbo.PAYMENTS.IDKINDPARAST AS IDPARAST, 
  dbo.PAYMENTS.KINDPARASTDESCR AS PARASTATIKO, 
  'ΠΛΗΡΩΜΕΣ' AS EIDOSKINHSHS, 
  null AS IDDRIVER, 
  '' AS DRIVERDESCR, 
  dbo.PAYMENTS.SUMPOSO * KINDPARASTATIKON_1.IF_XREOSI AS XREOSI, 
  dbo.PAYMENTS.SUMPOSO * KINDPARASTATIKON_1.IF_PISTOSI AS PISTOSI, 
  dbo.PAYMENTS.AITIOLOGIA, 
  dbo.PAYMENTS.EISPRAXAS, 
  MONTH(GetDATE()) AS MHNASPOYAFORA, 
  YEAR(gETdate()) as ETOSPOYAFORA, 
  NULL AS IFEXOFLISI, 
  NULL AS IFPROKATABOLI, 
  NULL AS COMMENTS, 
  NULL AS OXIMA, 
  dbo.PAYMENTS.IDKINDPAYMENT, 
  dbo.PAYMENTS.KINDPAYMENTDESCR, 
  dbo.PAYMENTS.ifDelete, 
  dbo.PAYMENTS.IDXRHSHS, 
  dbo.PAYMENTS.IDCOMPANY, 
  dbo.PAYMENTS.IDYPOKATASTIMA 
FROM 
  dbo.EMPLOYEE AS EMPLOYEE_4 WITH (NOLOCK) 
  INNER JOIN dbo.PAYMENTS WITH (NOLOCK) ON EMPLOYEE_4.id = dbo.PAYMENTS.IDCUSTOMER 
  INNER JOIN dbo.KINDPARASTATIKON AS KINDPARASTATIKON_1 WITH (NOLOCK) ON dbo.PAYMENTS.IDKINDPARAST = KINDPARASTATIKON_1.ID 
WHERE 
  (PAYMENTS.IfMisthodosia = 1 and PAYMENTS.ifDelete!=1) 
GO


---END SCRIPT 2281
