---NEW SCRIPT 2282

create view Kaa_With_Analysi_Propliromena_Ofeilomena as

SELECT 
    k.DATEPRINT                                                                                             AS Hmeromonia,
    k.NOPARAST                                                                                              AS Ar_Kaa,
    k.OXIMA                                                                                                 AS Oxima,
    k.OMADPROORISMOS                                                                                        as Omadikos_Proorismos,
    
    -- ΠΡΟΠΛΗΡΩΜΕΝΕΣ
    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.KOMISTRA,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Komistra_Propl,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.DIKAIOMAFORTOTIKIS,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Dikaioma_Propl,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN (ISNULL(hf.OTHERXREOSIS,0) + ISNULL(hf.ASFALISTRA,0) + ISNULL(hf.ergatika,0)) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Loipa_Propl,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.taxis,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Taxis_Propl,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.SUMPOSOXRFORT,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Synolo_Propl,

    -- ΟΦΕΙΛΟΜΕΝΕΣ
    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.KOMISTRA,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Komistra_Ofeil,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.DIKAIOMAFORTOTIKIS,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Dikaioma_Ofeil,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN (ISNULL(hf.OTHERXREOSIS,0) + ISNULL(hf.ASFALISTRA,0) + ISNULL(hf.ergatika,0)) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Loipa_Ofeil,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.taxis,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Taxis_Ofeil,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.SUMPOSOXRFORT,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Synolo_Ofeil,

    -- ΕΞΟΔΑ ΤΡΙΤΩΝ
    CAST(SUM(ISNULL(hf.XREOSISTRITON,0)) AS DECIMAL(18,2))                                                  AS Eksoda_Triton,

    -- ΓΕΝΙΚΟ ΣΥΝΟΛΟ (Προπληρωμένα + Οφειλόμενα)
    CAST(SUM(CASE WHEN (ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0) OR 
                        (ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1)
             THEN ISNULL(hf.SUMPOSOXRFORT,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Geniko_Synolo,
    k.ANTAPOKRITIS                                                                                          as Antapokritis,
    isnull(k.nofort,'')                                                                                     as Fortotiki_Exodou,                                                                                        
    isnull(k.POSOEXODA,0)                                                                                   as Kathari_Axia_Exodou,
    isnull(k.taxisexoda,0)                                                                                  as Taxis_Exodou,
    isnull(k.sumposoexoda,0)                                                                                as Synolo_Exodou
    

FROM KAA k
LEFT JOIN FORTOTIKES_ANA_KAA fak ON fak.IDKAA = k.ID
LEFT JOIN FORTOTIKES f ON f.ID = fak.IDFORTOTIKIS
LEFT JOIN HEADERFORTOTIKIS hf ON hf.IDFORT = f.ID
GROUP BY 
    k.ID, 
    k.DATEPRINT, 
    k.NOPARAST, 
    k.OXIMA,
    k.OMADPROORISMOS,
    k.ANTAPOKRITIS,
    k.nofort,
    k.POSOEXODA,
    k.taxisexoda,
    k.sumposoexoda

go

---END SCRIPT 2282
