             THEN ISNULL(hf.taxis,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Taxis_Ofeil,

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.SUMPOSOXRFORT,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Synolo_Ofeil,

    -- ΕΞΟΔΑ ΤΡΙΤΩΝ
    CAST(SUM(ISNULL(hf.XREOSISTRITON,0)) AS DECIMAL(18,2))                                                  AS Eksoda_Triton,

    -- ΓΕΝΙΚΟ ΣΥΝΟΛΟ (Προπληρωμένα + Οφειλόμενα)
    CAST(SUM(CASE WHEN (ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0) OR 
                        (ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1)
             THEN ISNULL(hf.SUMPOSOXRFORT,0) 
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS Geniko_Synolo,
    l.ANTAPOKRITIS                                                                                          as Antapokritis,
    isnull(l.nofort,'')                                                                                     as Fortotiki_Exodou,                                                                                        
    isnull(l.POSOEXODA,0)                                                                                   as Kathari_Axia_Exodou,
    isnull(l.taxisexoda,0)                                                                                  as Taxis_Exodou,
    isnull(l.sumposoexoda,0)                                                                                as Synolo_Exodou
    

FROM LISTESDIANOMIS l
LEFT JOIN FORTOTIKES_ANA_LISTA fal ON fal.IDLISTAS = l.ID
LEFT JOIN FORTOTIKES f ON f.ID = fal.IDFORTOTIKIS
LEFT JOIN HEADERFORTOTIKIS hf ON hf.IDFORT = f.ID
GROUP BY 
    l.ID, 
    l.DATEPRINT, 
    l.NOPARAST, 
    l.OXIMA,
    l.OMADPROORISMOS,
    l.ANTAPOKRITIS,
    l.nofort,
    l.POSOEXODA,
    l.taxisexoda,
    l.sumposoexoda

go



---END SCRIPT 2284
