ALTER PROCEDURE [dbo].[insertTOLISTES]

(
	@IDPARAST					numeric(18, 0)= NULL,
	@PARASTATIKO				nchar(100)= NULL,
	@SEIRA						nchar(10)  = NULL,
	@NOPARAST					nvarchar(20) = NULL,
	@DATEPRINT					smalldatetime =NULL,
	@DATEPARADOSI				smalldatetime =NULL,
	@IFCANCEL					int =0,
	@DATECANCEL					smalldatetime =NULL,
	@OXIMA						nvarchar(60) = NULL,
	@DRIVER						nvarchar(50) = NULL,
	@PERIOXIPROORISMOU			nvarchar(50) = NULL,
	@PERIOXIPARADOSIS			nvarchar(50) = NULL,
	@POSO						numeric(18, 2)= NULL,
	@TAXISPERCENT				numeric(18, 2) =NULL,
	@TAXIS						numeric(18, 2)= NULL,
	@SUMPOSO					numeric(18, 2)= NULL,
	@POSOEXODA					numeric(18, 2)= NULL,
	@TAXISPERCENTEXODA			numeric(18, 2)= NULL,
	@TAXISEXODA					numeric(18, 2) =NULL,
	@SUMPOSOEXODA				numeric(18, 2)= NULL,
	@STATUS						nvarchar(50) = NULL,
	@COMMENTS					nvarchar(max)= NULL,
	@NOFORT						NVARCHAR(10)=NULL,
	@POSOPROPL					numeric(18, 2)= NULL,
	@POSOOFEIL					numeric(18, 2)= NULL,
	@POSOKOMISTRA				numeric(18, 2)= NULL,
	@POSOEXTRITON				numeric(18, 2)= NULL,
	@SUMBAROS					numeric(18, 2)= NULL,
	
	@IDCUSTOMER					numeric(18, 0)= NULL,
	@AFMCUSTOMER				NVARCHAR(10)= NULL,
	@CUSTOMER					nchar(80)= NULL,	
	@IDANTAPOKRITIS				numeric(18, 0)= NULL,
	@AFMANTAPOKRITIS			NVARCHAR(10)= NULL,
	@ANTAPOKRITIS				nchar(80)= NULL,
	
	@IDSTATUS					numeric(18, 0)= NULL,
	@OMADPROORISMOS				nvarchar(50) = NULL,
	@IDXRHSHS					NUMERIC(18,0) = 0,
	@IDCOMPANY					NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = 0,
	@UserCreate					nvarchar (50)= NULL,
	@DateCreate					datetime = NULL,	
	@ifDelete					int = 0,
	@TheID						NUMERIC(18, 0)= NULL output
) 
AS
DECLARE @TAXIPERCENT NUMERIC (18,2)
SELECT @TAXIPERCENT= KP.TAXISPERCENT FROM KINDPARASTATIKON KP
JOIN LISTESDIANOMIS LA ON LA.IDPARAST=KP.ID


BEGIN
		
		
		DECLARE @NEWNOPARAST NUMERIC(18, 0)=0;
		DECLARE @IF_ZERO_ON_NEW_YEAR int=(SELECT IF_ZERO_ON_NEW_YEAR FROM KINDPARASTATIKON WHERE ID=@IDPARAST)
		DECLARE @IF_AUTONUMBER INT

		select @IF_AUTONUMBER = IF_AUTONUMBER FROM KINDPARASTATIKON WHERE ID = @IDPARAST
		
		
		IF @IF_AUTONUMBER = 1 BEGIN 
			IF @IF_ZERO_ON_NEW_YEAR = 1 BEGIN
				SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
				FROM LISTESDIANOMIS
				WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
				AND IDPARAST = @IDPARAST 
				AND ifDelete != 1
				AND YEAR(DATEPRINT) = YEAR(@DATEPRINT)
			END
			ELSE BEGIN	
				SELECT @NOPARAST=ISNULL(MAX(CAST(NOPARAST as INT)), 0) + 1 
				FROM LISTESDIANOMIS 
				WHERE ISNULL(SEIRA, '') = ISNULL(@SEIRA, '') 
				AND IDPARAST = @IDPARAST 
				AND ifDelete != 1
			END
			
			UPDATE KINDPARASTATIKON SET AUTONUMBER_FROM = (@NOPARAST + 1) WHERE ID = @IDPARAST;
		END
END

		BEGIN
			INSERT INTO LISTESDIANOMIS
				(
				IDPARAST,
				PARASTATIKO,
				SEIRA,
				NOPARAST,
				DATEPRINT,
				DATEPARADOSI,
				IFCANCEL,
				DATECANCEL,
				OXIMA,
				DRIVER,
				PERIOXIPROORISMOU,
				PERIOXIPARADOSIS,
				POSO,
				TAXISPERCENT,
				TAXIS,
				SUMPOSO,
				POSOEXODA,
				TAXISPERCENTEXODA,
				TAXISEXODA,
				SUMPOSOEXODA,
				STATUS,
				COMMENTS,
				NOFORT,
				IDCUSTOMER,
				AFMCUSTOMER,
				CUSTOMER,
				IDANTAPOKRITIS,
				AFMANTAPOKRITIS,
				ANTAPOKRITIS,
				POSOPROPL,
				POSOOFEIL,
				POSOKOMISTRA,
				POSOEXTRITON,
				SUMBAROS,
				IDSTATUS,
				OMADPROORISMOS,
				IDXRHSHS,
				IDCOMPANY,
				IDYPOKATASTIMA,
				UserCreate,
				DateCreate,
				ifDelete
				)
			VALUES
				(
				@IDPARAST,
				@PARASTATIKO,
				@SEIRA,
				@NOPARAST,
				@DATEPRINT,
				@DATEPARADOSI,
				@IFCANCEL,
				@DATECANCEL,
				@OXIMA,
				@DRIVER,
				@PERIOXIPROORISMOU,
				@PERIOXIPARADOSIS,
				(@SUMPOSO/(1+@TAXIPERCENT/100)),
				@TAXISPERCENT,
				@SUMPOSO*((@TAXIPERCENT/100)/(1+@TAXIPERCENT/100)),
				@SUMPOSO,
				@POSOEXODA,
				@TAXISPERCENTEXODA,
				@TAXISEXODA,
				@SUMPOSOEXODA,
				@STATUS,
				@COMMENTS,
				@NOFORT,
				@IDCUSTOMER,
				@AFMCUSTOMER,
				@CUSTOMER,
				@IDANTAPOKRITIS,
				@AFMANTAPOKRITIS,
				@ANTAPOKRITIS,
				@POSOPROPL,
				@POSOOFEIL,
				@POSOKOMISTRA,
				@POSOEXTRITON,
				@SUMBAROS,
				@IDSTATUS,
				@OMADPROORISMOS,
				@IDXRHSHS,
				@IDCOMPANY,
				@IDYPOKATASTIMA,
				@UserCreate,
				@DateCreate,		
				@ifDelete

				)
			--SELECT  @TheID = MAX(ID) FROM dbo.LISTESDIANOMIS WITH (NOLOCK)
			SELECT  @TheID = SCOPE_IDENTITY();
			
			update LISTESDIANOMIS set TAXISPERCENT=@TAXIPERCENT where ID=@TheID;
		END
GO


---END SCRIPT 2287
------------------------------------------------------------------------------------
------------------------------------------------------------------------------------
---NEW SCRIPT 2288



ALTER PROCEDURE [dbo].[updateLISTES]

(
	@ID							NUMERIC(18,0),
	@IDPARAST					numeric(18, 0)= NULL,
	@PARASTATIKO				nchar(100)= NULL,
	@SEIRA						nchar(10)  = NULL,
	@NOPARAST					nvarchar(20) = NULL,
	@DATEPRINT					smalldatetime =NULL,
	@DATEPARADOSI				smalldatetime =NULL,
	@IFCANCEL					int =0,
	@DATECANCEL					smalldatetime =NULL,
	@OXIMA						nvarchar(60) = NULL,
	@DRIVER						nvarchar(50) = NULL,
	@PERIOXIPROORISMOU			nvarchar(50) = NULL,
	@PERIOXIPARADOSIS			nvarchar(50) = NULL,
	@POSO						numeric(18, 2)= NULL,
	@TAXISPERCENT				numeric(18, 2) =NULL,
	@TAXIS						numeric(18, 2)= NULL,
	@SUMPOSO					numeric(18, 2)= NULL,
	@POSOEXODA					numeric(18, 2)= NULL,
	@TAXISPERCENTEXODA			numeric(18, 2)= NULL,
	@TAXISEXODA					numeric(18, 2) =NULL,
	@SUMPOSOEXODA				numeric(18, 2)= NULL,
	@STATUS						nvarchar(50) = NULL,
	@COMMENTS					nvarchar(max)= NULL,
	
	@IDCUSTOMER					numeric(18, 0)= NULL,
	@AFMCUSTOMER				NVARCHAR(10)= NULL,
	@CUSTOMER					nchar(80)= NULL,	
	@IDANTAPOKRITIS				numeric(18, 0)= NULL,
	@AFMANTAPOKRITIS			NVARCHAR(10)= NULL,
	@ANTAPOKRITIS				nchar(80)= NULL,
		
	@NOFORT						NVARCHAR(10)=NULL,
	@POSOPROPL					numeric(18, 2)= NULL,
	@POSOOFEIL					numeric(18, 2)= NULL,
	@POSOKOMISTRA				numeric(18, 2)= NULL,
	@POSOEXTRITON				numeric(18, 2)= NULL,
	@SUMBAROS					numeric(18, 2)= NULL,
	@IDSTATUS					numeric(18, 2)= NULL,
	@OMADPROORISMOS				nvarchar(50) = NULL,
	@IDXRHSHS					NUMERIC(18,0) = 0,
	@IDCOMPANY					NUMERIC(18,0) = 0,
	@IDYPOKATASTIMA				NUMERIC(18,0) = 0,
	@UserMod					nvarchar (50)= NULL,
	@DateMod					datetime  = NULL,	
	@ifDelete					int = 0
	--@TheID						NUMERIC(18, 0)= NULL output
) 
AS


DECLARE @TAXIPERCENT NUMERIC (18,2)
SELECT @TAXIPERCENT= KP.TAXISPERCENT FROM KINDPARASTATIKON KP
JOIN LISTESDIANOMIS LA ON LA.IDPARAST=KP.ID

		BEGIN
			UPDATE  LISTESDIANOMIS
				SET
				IDPARAST					=	@IDPARAST,
				PARASTATIKO					=	@PARASTATIKO,
				SEIRA						=	@SEIRA,
				NOPARAST					=	@NOPARAST,
				DATEPRINT					=	@DATEPRINT,
				DATEPARADOSI				=	@DATEPARADOSI,
				IFCANCEL                    =	@IFCANCEL,
				DATECANCEL					=	@DATECANCEL,
				OXIMA						=	@OXIMA,
				DRIVER						=	@DRIVER,
				PERIOXIPROORISMOU			=	@PERIOXIPROORISMOU,
				PERIOXIPARADOSIS			=	@PERIOXIPARADOSIS,
				POSO						=	(@SUMPOSO/(1+@TAXIPERCENT/100)),
				TAXISPERCENT				=	@TAXISPERCENT,
				TAXIS						=	@SUMPOSO*((@TAXIPERCENT/100)/(1+@TAXIPERCENT/100)),
				SUMPOSO						=	@SUMPOSO,
				POSOEXODA                   =	@POSOEXODA,
				TAXISPERCENTEXODA			=	@TAXISPERCENTEXODA,
				TAXISEXODA                  =	@TAXISEXODA,
				SUMPOSOEXODA                =	@SUMPOSOEXODA,
				STATUS						=	@STATUS,
				COMMENTS                    =	@COMMENTS,
				NOFORT						=	@NOFORT,
				IDCUSTOMER					=	@IDCUSTOMER,
				AFMCUSTOMER					=	@AFMCUSTOMER,
				CUSTOMER					=	@CUSTOMER,
				IDANTAPOKRITIS				=	@IDANTAPOKRITIS,
				AFMANTAPOKRITIS				=	@AFMANTAPOKRITIS,
				ANTAPOKRITIS				=	@ANTAPOKRITIS,
				POSOPROPL					=	@POSOPROPL,
				POSOOFEIL					=	@POSOOFEIL,
				POSOKOMISTRA				=	@POSOKOMISTRA,
				POSOEXTRITON				=	@POSOEXTRITON,
				SUMBAROS					=	@SUMBAROS,
				IDSTATUS					=	@IDSTATUS,
				OMADPROORISMOS				=	@OMADPROORISMOS,
				IDXRHSHS				=		@IDXRHSHS,
				IDCOMPANY				=		@IDCOMPANY,
				IDYPOKATASTIMA			=		@IDYPOKATASTIMA,
				DateMod						=	@DateMod,
				UserMod						=	@UserMod,
				ifDelete					=	@ifDelete

		WHERE	ID							=	@ID

--			SELECT  @TheID = MAX(ID) FROM dbo.LISTESDIANOMIS

;
 with sumanaLISTA as (
					select 
						idLISTAS , 
						count(id) countparast 
					from FORTOTIKES_ANA_LISTA 
					group by IDLISTAS
				)

				update LISTESDIANOMIS
					set COUNT_FORT = isnull(sumanaLISTA.countparast,0),TAXISPERCENT=@TAXIPERCENT
					from LISTESDIANOMIS
				left join sumanaLISTA on sumanaLISTA.IDLISTAS = LISTESDIANOMIS.ID
				where LISTESDIANOMIS.ID=@ID
				--KAA.id=@IDKAA
		END
		
		GO



---END SCRIPT 2288
