---NEW SCRIPT 2289


alter view Kaa_With_Analysi_Propliromena_Ofeilomena as


with parastatika_sign as (
					select 
						id,
						case ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
							when 1 then 1
							when 2 then ( -1)
							else 1
						end AS signs
				from KINDPARASTATIKON kp
)

SELECT 
	k.ID																									as ID,
    k.DATEPRINT                                                                                             AS 'Ημερομηνία',
    k.NOPARAST                                                                                              AS 'Αρ_ΚΑΑ',
    k.OXIMA                                                                                                 AS 'Όχημα',
    k.OMADPROORISMOS                                                                                        as 'Ομαδικός_Προορισμός',
    
    -- ΠΡΟΠΛΗΡΩΜΕΝΕΣ
    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.KOMISTRA,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Προπληρωμένα_Κόμιστρα',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.DIKAIOMAFORTOTIKIS,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Προπληρωμένο_Δικ.Φορτωτικής',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN (ISNULL(hf.OTHERXREOSIS,0) + ISNULL(hf.ASFALISTRA,0) + ISNULL(hf.ergatika,0)) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Προπληρωμένα_Λοιπά',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.taxis,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Προπληρωμένα_ΦΠΑ',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0 
             THEN ISNULL(hf.SUMPOSOXRFORT,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Προπληρωμένα_Σύνολο',

    -- ΟΦΕΙΛΟΜΕΝΕΣ
    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.KOMISTRA,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Οφειλόμενα_Κόμιστρα',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.DIKAIOMAFORTOTIKIS,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Όφειλόμενα_Δικ_Φορτωτικής',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN (ISNULL(hf.OTHERXREOSIS,0) + ISNULL(hf.ASFALISTRA,0) + ISNULL(hf.ergatika,0)) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Οφειλόμενα_Λοιπά',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.taxis,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Όφειλόμενα_ΦΠΑ',

    CAST(SUM(CASE WHEN ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1 
             THEN ISNULL(hf.SUMPOSOXRFORT,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Όφειλόμενα_Σύνολο',

    -- ΕΞΟΔΑ ΤΡΙΤΩΝ
    CAST(SUM(ISNULL(hf.XREOSISTRITON,0)) AS DECIMAL(18,2))                                                  AS 'Έξοδα_Τρίτων',

    -- ΓΕΝΙΚΟ ΣΥΝΟΛΟ (Προπληρωμένα + Οφειλόμενα)
    CAST(SUM(CASE WHEN (ISNULL(f.ifprepay,0) = 1 AND ISNULL(f.ifofeilomeni,0) = 0) OR 
                        (ISNULL(f.ifprepay,0) = 0 AND ISNULL(f.ifofeilomeni,0) = 1)
             THEN ISNULL(hf.SUMPOSOXRFORT,0) *ps.signs
             ELSE 0 END) AS DECIMAL(18,2))                                                                  AS 'Γενικό_Σύνολο',
    k.ANTAPOKRITIS                                                                                          as 'Ανταποκριτής',
    isnull(k.nofort,'')                                                                                     as 'Φορτωτική_Εξόδου',                                                                                        
    isnull(k.POSOEXODA,0)                                                                                   as 'Καθ_Αξία_Εξόδου',
    isnull(k.taxisexoda,0)                                                                                  as 'ΦΠΑ_Εξόδου',
    isnull(k.sumposoexoda,0)                                                                                as 'Σύνολο_Εξόδου'
    

FROM KAA k
LEFT JOIN FORTOTIKES_ANA_KAA fak ON fak.IDKAA = k.ID
LEFT JOIN FORTOTIKES f ON f.ID = fak.IDFORTOTIKIS
LEFT JOIN HEADERFORTOTIKIS hf ON hf.IDFORT = f.ID
left join parastatika_sign ps on ps.id=f.IDPARAST
GROUP BY 
    k.ID, 
    k.DATEPRINT, 
    k.NOPARAST, 
    k.OXIMA,
    k.OMADPROORISMOS,
    k.ANTAPOKRITIS,
    k.nofort,
    k.POSOEXODA,
    k.taxisexoda,
    k.sumposoexoda

go
---END SCRIPT 2289
