-- 3. Εισαγωγή μόνο όσων δεν υπάρχουν ήδη βάσει του AcrExtCode
INSERT INTO [dbo].[Acr] (AcrID, AcrName, AcrPrefix, AcrExtCode)
SELECT 
    @LastID + ROW_NUMBER() OVER (ORDER BY Name), 
    Name, 
    ISO, -- Prefix (GR, US, κλπ)
    ISO  -- ExtCode (ISO Code)
FROM NewCountries NC
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[Acr] A 
    WHERE A.AcrPrefix = NC.ISO
);

GO

