---NEW SCRIPT 2294

create view Fortotikes_With_Status as 

select 
	f.id
	,convert(nvarchar(20),f.DATEPRINT,103)									as [Date]
	,kdp.Code																as Code_Parast
	,f.APOSTOLEASDESCR														as Apostoleas
	,f.PARALISPTISDESCR														as Paraliptis
	,ltrim(rtrim(isnull(gf.TIMDA,'')))										as TimDa
	
	,case isnull(IFPARALABIFROMPEL,0)	
		when 1 then	'Ok'
		else ''
	 end																	as Paralavi
	,case IFPARALABIFROMPEL
		when 1 then convert(nvarchar(20),DATEPARAL,103)
		else ''
	 end																	as Date_Paralavis
	 ,case IFPARALABIFROMPEL
		when 1 then convert(nvarchar(5),DATEPARAL,108)
		else ''
	 end																	as Time_Paralavis


	 ,case isnull(IfParadsePrakt,0)	
		when 1 then	'Ok'
		else ''
	 end																	as Paradosi_Se_Praktoreio
	,case IfParadsePrakt
		when 1 then convert(nvarchar(20),DateParadsePrakt,103)
		else ''
	 end																	as Date_Paradosis_se_Praktoreio
	 ,case IfParadsePrakt
		when 1 then convert(nvarchar(5),DateParadsePrakt,108)
		else ''
	 end																	as Time_Paradosis_se_Praktoreio

	
	,case isnull(IFPARADOSITOPEL,0)	
		when 1 then	'Ok'
		else ''
	 end																	as Paradosi
	,case isnull(IFPARADOSITOPEL,0)	
		when 1 then convert(nvarchar(20),DATEPARAD,103)
		else ''
	 end																	as Date_Paradosis
	 ,case isnull(IFPARADOSITOPEL,0)	
		when 1 then convert(nvarchar(5),DATEPARAD,108)
		else ''
	 end																	as Time_Paradosis


	,case isnull(IFCANCEL,0)	
		when 1 then	'Ok'
		else ''
	 end																	as Akirosi
	,case IFCANCEL
		when 1 then convert(nvarchar(20),DATECANCEL,103)
		else ''
	 end																	as Date_Akyrosis


	,case isnull(IFEPISTROFI,0)	
		when 1 then	'Ok'
		else ''
	 end																	as Epistrofi
	,case IFEPISTROFI
		when 1 then convert(nvarchar(20),DATEEPISTROFIS,103)
		else ''
	 end																	as Date_Epistrofis
	
from FORTOTIKES f
join KINDPARASTATIKON kdp on kdp.id=f.IDPARAST
left join GRAMMESFORTTIKIS gf on gf.IDVOH=f.ID

go


---END SCRIPT 2294
