---NEW SCRIPT 2298

exec sp_rename 'KAA_SUMPOSA','KAA_SUMPOSA_OLD'
GO

create PROCEDURE [dbo].[KAA_SUMPOSA] 
	-- Add the parameters for the stored procedure here
	(@IDKAA numeric(18,0)--,
	--@return Numeric  Output
	)
AS
SELECT dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS,
        SUM(CASE WHEN ifKomistra = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END)  AS KOMISTRA, 
                      SUM(CASE WHEN ifDikaiomaFortotikis = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END)   AS DIKAIOMAFORTOTIKIS, 
                      SUM(CASE WHEN ifOther = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END) AS OTHERXREOSIS,
                      SUM(CASE WHEN Xreoseis.IfAsfalistra = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END)  AS ASFALISTRA, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 THEN XREOSISANADELTIO.POSO ELSE 0 END) AS KATHARO, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 THEN XREOSISANADELTIO.TAXIS ELSE 0 END) AS TAXIS, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 THEN XREOSISANADELTIO.SUMPOSO ELSE 0 END)  AS SUMPOSOXRFORT, 
                      SUM(CASE WHEN ifErgatika = 1 THEN XREOSISANADELTIO.SUMPOSO ELSE 0 END) AS ERGATIKA, 
                      ROUND(SUM(dbo.FORTOTIKES.EXODATRITON/5),2)AS XREOSISTRITON, 
                      SUM(dbo.XREOSISANADELTIO.SUMPOSO) AS OLIKOSYNOLOXREOSEONFORT,
                      SUM(CASE WHEN ifOther = 1 AND FORTOTIKES.IFOFEILOMENI = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END) AS OTHERXREOSISOFEILOMENON,
                      SUM(CASE WHEN Xreoseis.IfAsfalistra = 1 AND FORTOTIKES.IFOFEILOMENI = 1 THEN XREOSISANADELTIO.POSO ELSE 0 END)  AS ASFALISTRAOFEILOMENON, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 AND FORTOTIKES.IFOFEILOMENI = 1  THEN XREOSISANADELTIO.POSO ELSE 0 END) AS KATHAROOFEILOMENON, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 AND FORTOTIKES.IFOFEILOMENI = 1  THEN XREOSISANADELTIO.TAXIS ELSE 0 END) AS TAXISOFEILOMENON, 
                      SUM(CASE WHEN ifXreosiTriton <> 1 AND FORTOTIKES.IFOFEILOMENI = 1  THEN XREOSISANADELTIO.SUMPOSO ELSE 0 END)  AS SUMPOSOXRFORTOFEILOMENON, 
                      SUM(CASE WHEN ifErgatika = 1 AND FORTOTIKES.IFOFEILOMENI = 1  THEN XREOSISANADELTIO.SUMPOSO ELSE 0 END) AS ERGATIKAOFEILOMENON, 
                      ROUND(SUM(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN (dbo.FORTOTIKES.EXODATRITON/5) ELSE 0 END),2) AS XREOSISTRITONOFEILOMENON 
                       
FROM         dbo.FORTOTIKES WITH (NOLOCK) LEFT OUTER JOIN
                      dbo.XREOSISANADELTIO WITH (NOLOCK) ON dbo.FORTOTIKES.ID = dbo.XREOSISANADELTIO.IDVOH AND dbo.XREOSISANADELTIO.IF_TO_FORTOTIKI=1 LEFT OUTER JOIN
                      dbo.Xreoseis WITH (NOLOCK) ON dbo.XREOSISANADELTIO.IDXREOSIS = dbo.Xreoseis.ID 
                      WHERE FORTOTIKES.ID IN (SELECT IDFORTOTIKIS FROM dbo.FORTOTIKES_ANA_KAA WITH (NOLOCK) WHERE IDKAA = @IDKAA) 
GROUP BY dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS

GO

---END SCRIPT 2298
