------------------------------------------------------------------------------------
---NEW SCRIPT 2299

exec sp_rename 'KAA_SUMPOSA_STORED','KAA_SUMPOSA_STORED_OLD'
GO

create PROCEDURE [dbo].[KAA_SUMPOSA_STORED] 
	-- Add the parameters for the stored procedure here
	(@IDKAA numeric(18,0)--,
	--@return Numeric  Output
	)
AS
SELECT dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS,
        SUM(ROUND(ISNULL(B.KOMISTRA,0) ,2))  AS KOMISTRA, 
                      SUM(ROUND(ISNULL(B.DIKAIOMA,0) ,2))   AS DIKAIOMAFORTOTIKIS, 
                      SUM(ROUND(ISNULL(B.OTHERPOSO,0) ,2))  AS OTHERXREOSIS,
                      SUM(ROUND(ISNULL(B.ASFALISTRA,0) ,2))   AS ASFALISTRA, 
                      SUM(ROUND(ISNULL(B.POSO,0) ,2))  AS KATHARO, 
                      SUM(ROUND(ISNULL(B.TAXIS, 0) ,2)) AS TAXIS, 
                      SUM(ROUND(ISNULL(B.SUMPOSO, 0) ,2))  AS SUMPOSOXRFORT, 
                      SUM(ROUND(ISNULL(B.ERGATIKA, 0) ,2)) AS ERGATIKA, 
                      SUM(ROUND(ISNULL(B.EXODATRITON, 0),2))AS XREOSISTRITON, 
                      SUM(ROUND(ISNULL(B.EXODATRITON, 0),2)  + ROUND(ISNULL(B.SUMPOSO, 0) ,2)) AS OLIKOSYNOLOXREOSEONFORT ,
                      
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.DIKAIOMA ELSE 0 END,0) ,2))   AS DIKAIOMAFORTOTIKISOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.OTHERPOSO ELSE 0 END,0) ,2))  AS OTHERXREOSISOFEILOMENON,
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.ASFALISTRA ELSE 0 END,0) ,2))   AS ASFALISTRAOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.POSO ELSE 0 END,0) ,2))  AS KATHAROOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.TAXIS ELSE 0 END, 0) ,2)) AS TAXISOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.SUMPOSO ELSE 0 END, 0) ,2))  AS SUMPOSOXRFORTOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.ERGATIKA ELSE 0 END , 0) ,2)) AS ERGATIKAOFEILOMENON, 
                      SUM(ROUND(ISNULL(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN B.EXODATRITON ELSE 0 END, 0),2))AS XREOSISTRITONOFEILOMENON, 
                      SUM(CASE WHEN  FORTOTIKES.IFOFEILOMENI = 1 THEN ROUND(ISNULL(B.EXODATRITON, 0),2)  + ROUND(ISNULL(B.SUMPOSO, 0) ,2) ELSE 0 END) AS OLIKOSYNOLOXREOSEONFORTOFEILOMENON 
FROM         dbo.FORTOTIKES WITH (NOLOCK) INNER JOIN
                      dbo.FORTOTIKES_ANA_KAA AS B WITH (NOLOCK) ON dbo.FORTOTIKES.ID = B.IDFORTOTIKIS AND B.IDKAA = @IDKAA
                      --dbo.XREOSISANADELTIO.IF_TO_FORTOTIKI=1 
                      --LEFT OUTER JOIN
                     -- dbo.Xreoseis WITH (NOLOCK) ON dbo.XREOSISANADELTIO.IDXREOSIS = dbo.Xreoseis.ID 
                      --WHERE FORTOTIKES.ID IN (SELECT IDFORTOTIKIS FROM dbo.FORTOTIKES_ANA_KAA WITH (NOLOCK) WHERE ) 
GROUP BY dbo.FORTOTIKES.NOPARASTDELTIOUAPOSTOLIS

GO


