---NEW SCRIPT 2305

update SKOPOSDIAKINISIS 
set AADE_CODE=9
where descr='Αγορά' and ISNULL(aade_code,'')=''

go

alter table skoposdiakinisis alter column descr nvarchar(50) null;
go


INSERT INTO [dbo].[SKOPOSDIAKINISIS] ([DESCR], [AADE_CODE])
SELECT src.DESCR, src.AADE_CODE
FROM (
    VALUES 
    (N'Πώληση', '1'),
    (N'Πώληση για Λογαριασμό Τρίτων', '2'),
    (N'Δειγματισμός', '3'),
    (N'Έκθεση', '4'),
    (N'Επιστροφή', '5'),
    (N'Φύλαξη', '6'),
    (N'Επεξεργασία - Συναρμολόγηση - Αποσυναρμολόγηση', '7'),
    (N'Ενδοδιακίνηση (Μεταξύ Εγκαταστάσεων Οντότητας)', '8'),
    (N'Αγορά', '9'),
    (N'Εφοδιασμός πλοίων και αεροσκαφών', '10'),
    (N'Δωρεάν διάθεση', '11'),
    (N'Εγγύηση', '12'),
    (N'Χρησιδανεισμός', '13'),
    (N'Αποθήκευση σε Τρίτους', '14'),
    (N'Επιστροφή από Φύλαξη', '15'),
    (N'Ανακύκλωση', '16'),
    (N'Καταστροφή άχρηστου υλικού', '17'),
    (N'Διακίνηση Παγίων (Ενδοδιακίνηση)', '18'),
    (N'Λοιπές Διακινήσεις', '19'),
    (N'Μεταφορές - Ταχυμεταφορές', '20')
) AS src(DESCR, AADE_CODE)
WHERE NOT EXISTS (
    SELECT 1 
    FROM [dbo].[SKOPOSDIAKINISIS] 
    WHERE [AADE_CODE] = src.AADE_CODE
);

go

