	@ANAMEXODO								NUMERIC(18,2)=0,
	@AFMAPOSTOLEA							NVARCHAR (20) =NULL,
	@AFMENTOLEA								NVARCHAR (20) =NULL,
	@AFMPARALIPTI							NVARCHAR (20) =NULL,
	@AFMTRITOU								NVARCHAR (20) =NULL,
