    IF_PISTOPOIHTIKO1, endDatePISTOPOIHTIKO1, ifDelete, IDOmProor, OmProorDescr, PROMPERCENT, IF_SYROMENO, MHKOS,
    Tel, CAT_TRUCK, CAT_TRUCKDESCR
)
SELECT 
    '..', '..', '..', 0, NULL, 0, NULL, 
    0, NULL, 0, NULL, 0, NULL, 
    0, NULL, 0, 3, '.', 0.00, 1, 0.00, 
    NULL, NULL, NULL
WHERE NOT EXISTS (
    SELECT 1 
    FROM TRUCKS 
    WHERE ArKykloforias = '..' 
      AND ISNULL(IF_SYROMENO, 0) = 1
);

go

