CREATE PROCEDURE Diorthosi_Poson_Fortotikis
    @TargetID INT      -- Για τον πίνακα FORTOTIKES
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Ενημέρωση στον πίνακα FORTOTIKES
        UPDATE FORTOTIKES 
        SET 
            POSO = POSO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSO = SUMPOSO * -1
        WHERE ID = @TargetID;

        -- 2. Ενημέρωση στον πίνακα XREOSISANADELTIO
        UPDATE XREOSISANADELTIO 
        SET 
            POSO = POSO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSO = SUMPOSO * -1
        WHERE IDVOH = @TargetID and isnull(IF_TO_FORTOTIKI,0)=1;

        -- 3. Ενημέρωση στον πίνακα HEADERFORTOTIKIS
        UPDATE HEADERFORTOTIKIS 
        SET 
            KOMISTRA = KOMISTRA * -1,
            DIKAIOMAFORTOTIKIS = DIKAIOMAFORTOTIKIS * -1,
            OTHERXREOSIS = OTHERXREOSIS * -1,
            ASFALISTRA = ASFALISTRA * -1,
            KATHARO = KATHARO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSOXRFORT = SUMPOSOXRFORT * -1,
            ERGATIKA = ERGATIKA * -1,
            OLIKOSYNOLOXREOSEONFORT = OLIKOSYNOLOXREOSEONFORT * -1
        WHERE IDFORT = @TargetID;

        -- Αν όλα πήγαν καλά, οριστικοποίηση
        COMMIT TRANSACTION;
        
        PRINT 'Η αντιστροφή των ποσών ολοκληρώθηκε επιτυχώς.';
    END TRY

    BEGIN CATCH
        -- Αν υπάρξει σφάλμα, ακύρωση όλων των αλλαγών
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- Επιστροφή πληροφοριών σφάλματος
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
    END CATCH
END;

GO


