CREATE PROCEDURE Diorthosi_Poson_Voh
    @TargetID INT     
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

       
        UPDATE VOH 
        SET 
            POSO = POSO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSO = SUMPOSO * -1
        WHERE ID = @TargetID;

       
        UPDATE XREOSISANADELTIO 
        SET 
            POSO = POSO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSO = SUMPOSO * -1
        WHERE IDVOH = @TargetID and isnull(IF_TO_VOH,0)=1;

        
        UPDATE HEADERVOH 
        SET 
            KOMISTRA = KOMISTRA * -1,
            DIKAIOMAFORTOTIKIS = DIKAIOMAFORTOTIKIS * -1,
            OTHERXREOSIS = OTHERXREOSIS * -1,
            ASFALISTRA = ASFALISTRA * -1,
            KATHARO = KATHARO * -1,
            TAXIS = TAXIS * -1,
            SUMPOSOXRVOH = SUMPOSOXRVOH * -1,
            ERGATIKA = ERGATIKA * -1,
            OLIKOSYNOLOXREOSEONVOH = OLIKOSYNOLOXREOSEONVOH * -1
        WHERE IDVOH = @TargetID;

       
        COMMIT TRANSACTION;
        
        PRINT 'Η αντιστροφή των ποσών ολοκληρώθηκε επιτυχώς.';
    END TRY

    BEGIN CATCH
        
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
    END CATCH
END;

