ALTER PROCEDURE [dbo].[TRANSFORMTORAMMESFORTOTIKIS] (@IDPROFORT NUMERIC(18, 0) = NULL,
@IDVOH NUMERIC(18, 0) = NULL,
@TheID NUMERIC(18, 0) = NULL OUTPUT)
AS


BEGIN
	SET NOCOUNT ON;
	DECLARE @IDGRAMMISPROFORTOTIKIS INT;

	DECLARE CUR CURSOR FOR SELECT
		ID
	FROM GRAMMESPROFORTTIKIS
	WHERE IDVOH = @IDPROFORT;

	OPEN CUR;

	FETCH NEXT FROM CUR INTO @IDGRAMMISPROFORTOTIKIS;

	WHILE @@FETCH_STATUS = 0
	BEGIN
	INSERT INTO GRAMMESFORTTIKIS (
		TIMDA,
		IDVOH,
		TEMAXIA,
		PERIEXOMENO,
		SYSKEVASIA,
		SYSKEVASIADESCR,
		BAROS,
		KYBIKA,
		SUMPOSO,
		XreosiAnaMonada,
		XeosiSeMonada,
		XreosiGrammis,
		EXT_qrUrl
		)
		SELECT
		TIMDA,
		@IDVOH AS IDVOH,
		TEMAXIA,
		PERIEXOMENO,
		SYSKEVASIA,
		SYSKEVASIADESCR,
		BAROS,
		KYBIKA,
		SUMPOSO,
		XreosiAnaMonada,
		XeosiSeMonada,
		XreosiGrammis,
		EXT_qrUrl
		FROM GRAMMESPROFORTTIKIS
		WHERE ID = @IDGRAMMISPROFORTOTIKIS

	INSERT INTO TEMAXIAFORTOTIKIS (IDFORTOTIKIS, IDGRAMMIS, BARCODE, AAGRAMMIS, AAFORT, FLAGPARALAVI, DATEPARALAVI)
		SELECT
			@IDVOH
			,@@IDENTITY
		 ,BARCODE
		 ,AAGRAMMIS
		 ,AAFORT
		 ,FLAGPARALAVI
		 ,DATEPARALAVI
		FROM TEMAXIAPROFORTOTIKIS
		WHERE IDGRAMMIS = @IDGRAMMISPROFORTOTIKIS

	FETCH NEXT FROM CUR INTO @IDGRAMMISPROFORTOTIKIS;
	END

	CLOSE CUR;
	DEALLOCATE CUR;

END

GO

---END SCRIPT 2320
------------------------------------------------------------------------------------

