ALTER VIEW [dbo].[QRURL_ANA_KAA] AS

select
	
	kaa.id																				IDKAA,
	f.ID																				IDPARASTATIKOU,
	KAA.OXIMA																			OXIMA,
	ISNULL(KAA.Trailer,'')																TRAILER,
	KAA.DRIVER																			DRIVER,
	kaa.AFMANTAPOKRITIS																	AFM_ANTAPOKRITIS,
	KAA.ANTAPOKRITIS																	ANTAPOKRITIS,
	RTRIM(LTRIM(isnull(antap.AddressStr,'')+' '+isnull(antap.AddressNo,'')))			ANTAPOKRITIS_STREET,
	KAA.AFMCUSTOMER																		AFM_TRITOU,
	KAA.CUSTOMER																		TRITOSSYNAL,
	RTRIM(LTRIM(isnull(TRITOS.AddressStr,'')+' '+isnull(TRITOS.AddressNo,'')))			TRITOS_STREET,
	pr.AFM																				AFM_PRAKTOREIO,
	PR.Eponimia																			PRAKTOREIO,
	RTRIM(LTRIM(isnull(PR.AddressStr,'')+' '+isnull(PR.AddressNo,'')))					PRAKTOREIO_STREET,
	KAA.CONTAINER																		CONTAINER,
	KAA.BOAT																			BOAT,
	F.qrUrl																				QRURL
	
from kaa
join FORTOTIKES_ANA_KAA fak on fak.IDKAA=kaa.ID
join fortotikes f on f.id=fak.IDFORTOTIKIS and isnull(f.IF_ENIM_AADE,0)=1
left join GRAMMESFORTTIKIS grf on grf.IDVOH=f.ID and isnull(f.IF_ENIM_AADE,0)=1
left join ACCOUNTS antap on antap.id=kaa.IDANTAPOKRITIS
left join ACCOUNTS tritos on tritos.id=kaa.IDCUSTOMER
left join PRAKTOREIA pr on pr.id=f.IDPRAKTOREIO
