---NEW SCRIPT 2329

exec sp_rename 'SUMPOSA_PER_ACCOUNT_PROM','SUMPOSA_PER_ACCOUNT_PROM_OLD'
GO

CREATE VIEW SUMPOSA_PER_ACCOUNT_PROM
AS

WITH parastatika_sign AS (
    SELECT 
        id,
        CASE ISNULL(kp.if_xreosi,0) * 1 + ISNULL(kp.if_pistosi,0) * 2
            WHEN 1 THEN (1)
            WHEN 2 THEN (-1)
            ELSE 1
        END AS signs
    FROM KINDPARASTATIKON kp
),


RawBalances AS (
    -- FORTOTIKES
    SELECT 
        f.IDXREOUMENOU                                          AS AccountID,
        ISNULL(f.SUMPOSO * ps.signs, 0)                         AS SUMPOSO,
        f.DATEPRINT,
        f.IDCOMPANY,
        f.IDYPOKATASTIMA,
        f.ifDelete
    FROM FORTOTIKES f 
    INNER JOIN KINDPARASTATIKON kd ON kd.id = f.IDPARAST 
        AND ISNULL(kd.KindKINISIS,0) IN (0,6) 
        AND ISNULL(kd.IF_ENIMEROSIKARTELA,0) = 1 
    INNER JOIN parastatika_sign ps ON ps.ID = kd.ID
    WHERE f.ifDelete != 1

    UNION ALL

    -- VOH
    SELECT 
        v.IDCUSTOMER														AS AccountID,
        (ISNULL(v.SUMPOSO,0) + isnull(v.SUMPOSOEPIVAR, 0)) * ps.signs       AS SUMPOSO,
        v.DATEPRINT,
        v.IDCOMPANY,
        v.IDYPOKATASTIMA,
        v.ifDelete
    FROM VOH v 
    INNER JOIN KINDPARASTATIKON kd ON kd.id = v.IDPARAST 
        AND ISNULL(kd.KindKINISIS,0) IN (0,6) 
        AND ISNULL(kd.IF_ENIMEROSIKARTELA,0) = 1 
    INNER JOIN parastatika_sign ps ON ps.ID = kd.ID
    WHERE v.ifDelete != 1

    UNION ALL

    -- EXODA
    SELECT 
        ex.IDPROM                                               AS AccountID,
        ISNULL(ex.SUMPOSO, 0) * ps.signs                        AS SUMPOSO,
        ex.DATEPRINT,
        ex.IDCOMPANY,
        ex.IDYPOKATASTIMA,
        ex.ifDelete

    FROM EXODA ex 
    INNER JOIN KINDPARASTATIKON kd ON kd.id = ex.IDPARAST 
        AND ISNULL(kd.KindKINISIS,0) IN (0,6) 
        AND ISNULL(kd.IF_ENIMEROSIKARTELA,0) = 1 
    INNER JOIN parastatika_sign ps ON ps.ID = kd.ID
    WHERE ex.ifDelete != 1

    UNION ALL

    -- PAYMENTS
    SELECT 
        p.IDCUSTOMER                                            AS AccountID,
        ISNULL(p.SUMPOSO * ps.signs, 0)                         AS SUMPOSO,
        p.DATEPRINT,
        p.IDCOMPANY,
        p.IDYPOKATASTIMA,
        p.ifDelete
    FROM PAYMENTS p 
    INNER JOIN KINDPARASTATIKON kd ON kd.id = p.IDKINDPARAST 
        AND ISNULL(kd.KindKINISIS,0) IN (2,99) 
        AND ISNULL(kd.IF_ENIMEROSIKARTELA,0) = 1 
    INNER JOIN parastatika_sign ps ON ps.ID = kd.ID
    WHERE p.ifDelete != 1
)


SELECT 
    acc.id                                                      AS ID,
    acc.Code                                                    AS Code,
    isnull(acc.AFM,'')                                          AS AFM,
    acc.Eponimia                                                AS EPONIMIA,
    acc.AddressCity                                             AS AddressCity,
    acc.Tel                                                     AS Tel,
    acc.If_Pel                                                  AS IF_PEL,
    acc.IF_PROM                                                 AS IF_PROM,
    isnull(rb.SUMPOSO,0)                                        AS SUMPOSO, 
    rb.DATEPRINT                                                AS DATEPRINT,
    rb.ifDelete                                                 AS ifDelete,
    rb.IDCOMPANY                                                AS IDCOMPANY,     
    rb.IDYPOKATASTIMA                                           AS IDYPOKATASTIMA,
    acc.IDYPOKATASTIMA                                          AS IDYPOKATASTIMAACC
FROM RawBalances rb
INNER JOIN ACCOUNTS acc ON acc.id = rb.AccountID;

GO


---END SCRIPT 2329
