CREATE FUNCTION [dbo].[GET_PRAKTOREIO_IMPORT]
(
	@AgentExtID NVARCHAR(100) = NULL,
	@AgentAfm NVARCHAR(20) = NULL,
	@AgentName NVARCHAR(100) = NULL,
	@AgentPoli NVARCHAR(100) = NULL,
	@AgentNomos NVARCHAR(100) = NULL,
	@AgentStreet NVARCHAR(100) = NULL,
	@AgentZipCode NVARCHAR(10) = NULL,
	@AgentPhone NVARCHAR(20) = NULL,
	@AgentMobile NVARCHAR(20) = NULL,
	@AgentEmail NVARCHAR(100) = NULL
)
RETURNS int
AS
BEGIN
	
	DECLARE @Result INT;

	SET @RESULT = -1;


	SELECT TOP 1 @RESULT=ISNULL(idprk, -1)
	FROM PRAKTOREIA_EXTCODES
	WHERE ext_id = ISNULL(@AgentExtID, '');

	IF @RESULT = -1 AND LEN(ISNULL(@AgentAfm, '')) > 0
	BEGIN
		SELECT TOP 1 @RESULT=ISNULL(ID, -1)
		FROM PRAKTOREIA
		WHERE AFM = ISNULL(@AgentAfm, '');
	END

	-- Return the result of the function
	RETURN @RESULT;

END
GO


