---NEW SCRIPT 2336


ALTER PROCEDURE [dbo].[InserttoFORTOTIKES_IMPORT]
(
	
	@IDENTOLEA					NUMERIC(18,0)= NULL,
	@IDAPOSTOLEA				NUMERIC(18,0)= NULL,
	@IDPARALIPTI				NUMERIC(18,0)= NULL,
	@IDTRITOU					NUMERIC(18,0)= NULL,
	@IDPARAST					NUMERIC(18,0)= NULL,
	
	@ANTIKCASH					NUMERIC(8,2)= NULL,
	@ANTIKEPIT					NUMERIC(8,2)= NULL,
	@ANTIKSYNAL					NUMERIC(8,2)= NULL,
	@ANTIKOTHER					NUMERIC(8,2)= NULL,
	
	@DATEPRINT					DATETIME= NULL,

	@NO_EXT_FORT				NVARCHAR(50) = NULL,
	@NO_EXT_ORDER				NVARCHAR(50) = NULL,
	@EXT_BARCODE				NVARCHAR (150) =NULL,


	@POSO						NUMERIC(8,2)= NULL,
	@TAXIS						NUMERIC(8,2)= NULL,
	@SUMPOSO					NUMERIC(8,2)= NULL,

	@EXODATRITON				NUMERIC(8,2)= NULL,
	
	
	@NOPARASTANTIK				NVARCHAR(50) = NULL,
	@COMMENTS					NVARCHAR(MAX)= NULL,

	@COMPANYID					INT = NULL,
	@YPOKATID					INT = NULL,

	@USERCREATE					NVARCHAR(50) = 'Import Tool',

	@FLAG_PROPLIROMENI			BIT = NULL,
	@FLAG_OFEILOMENI			BIT = NULL,
	@FLAG_METRITIS				BIT = NULL,
	@FLAG_PISTOSI				BIT = NULL,

	@ANTIKCOMMENTS				NVARCHAR(100) = NULL,

	@IDSTATUS					INT,
	@PERIOXIPARADOSIS NVARCHAR(50),
	@IDPRAKTOREIO int = null,
	@PRAKTOREIODESCR nvarchar(80) = null,
	@AADE_MOVE_PURPOSE_CODE nvarchar(10) = null,

	@TheID						NUMERIC(18, 0)= NULL output
	
	)
AS

SET NOCOUNT ON;


DECLARE @PARAST_SEIRA NVARCHAR(50)
DECLARE @PARAST_DESC NVARCHAR(50)
DECLARE @PARAST_AUTONUMBER BIT
DECLARE @PARAST_TAXISPERCENT NUMERIC(18,2)

DECLARE @IDKINDPAYMENT INT
DECLARE @KINDPAYMENTDESCR NVARCHAR(50)

--DECLARE @IDSTATUS INT
DECLARE @STATUSDESCR NVARCHAR(50)

DECLARE @AFMXREOUMENOU NVARCHAR(10) = NULL
DECLARE @AFMAPOSTOLEA NVARCHAR (10) =NULL
DECLARE @AFMENTOLEA NVARCHAR (10) =NULL
DECLARE @AFMPARALIPTI NVARCHAR (10) =NULL
DECLARE @AFMTRITOU NVARCHAR (10) =NULL

DECLARE @PERIOXIFORTOSIS NVARCHAR(50) = NULL
--DECLARE @PERIOXIPARADOSIS NVARCHAR(50) = NULL
DECLARE @OMPROORISMOS NVARCHAR(50) = NULL

DECLARE @APOSTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @PARALISPTISDESCR NVARCHAR(50)= NULL
DECLARE @ENTOLEASDESCR NVARCHAR(50)= NULL
DECLARE @TRITOSDESCR NVARCHAR(50) = NULL

DECLARE @IDXRHSHS INT;


DECLARE @IDSKOPOUDIAKINISIS INT;
DECLARE @SKOPOSDIAKINISISDESCR NVARCHAR(100);


SELECT TOP 1
	@IDSKOPOUDIAKINISIS=ID,
	@SKOPOSDIAKINISISDESCR=DESCR
FROM SKOPOSDIAKINISIS
WHERE AADE_CODE = @AADE_MOVE_PURPOSE_CODE


SET @DATEPRINT = GETDATE();

select top 1 @IDXRHSHS=ID from XRHSEIS where getdate() between FIRSTDATE and LASTDATE

SELECT @AFMXREOUMENOU = AFM FROM ACCOUNTS WHERE ID = @IDENTOLEA
SELECT @AFMENTOLEA = AFM, @ENTOLEASDESCR = Eponimia FROM ACCOUNTS WHERE ID = @IDENTOLEA

SELECT 
	@AFMAPOSTOLEA = AFM, 
	@APOSTOLEASDESCR = Eponimia,
	@PERIOXIFORTOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDAPOSTOLEA

SELECT 
	@AFMPARALIPTI = AFM, 
	@PARALISPTISDESCR = Eponimia
	--,@PERIOXIPARADOSIS = AddressCity
FROM ACCOUNTS WHERE ID = @IDPARALIPTI

SELECT 
	@AFMTRITOU = AFM, 
	@TRITOSDESCR = Eponimia
FROM ACCOUNTS WHERE ID = @IDTRITOU

SELECT TOP 1
	@IDKINDPAYMENT=ID,
	@KINDPAYMENTDESCR=DESCR
FROM KINDOFPAYMENTS
WHERE IF_PISTOSI = 1
AND IF_IN = 1

--SELECT TOP 1
--	@IDSTATUS=ID,
--	@STATUSDESCR=DESCR
--FROM DOC_STATUS
--WHERE IF_PRINT = 1
--AND IFEKDOSI = 1

SELECT @STATUSDESCR = DESCR
FROM DOC_STATUS WHERE ID = @IDSTATUS;

SELECT 
	@PARAST_SEIRA = SEIRA,
	@PARAST_DESC = DESCR,
	@PARAST_AUTONUMBER = IF_AUTONUMBER,
	@PARAST_TAXISPERCENT = TAXISPERCENT

FROM KINDPARASTATIKON
WHERE ID = @IDPARAST




EXEC InserttoFORTOTIKES
	@TheID = @TheID output,
	@IDENTOLEA = @IDENTOLEA,
	@IDAPOSTOLEA = @IDAPOSTOLEA,
	@IDPARALIPTI = @IDPARALIPTI,
	@IDTRITOU = @IDTRITOU,
	@IDANTAPOKRITI = -1,
	@IDXREOUMENOU = @IDTRITOU,
	
	@IDPARAST = @IDPARAST,
	@PARASTATIKO = @PARAST_DESC,
	@SEIRA = @PARAST_SEIRA,
	@IFAUTONUMBER = @PARAST_AUTONUMBER,

	@ANTIKCASH = @ANTIKCASH,
	@ANTIKEPIT = @ANTIKEPIT,
	@ANTIKSYNAL = @ANTIKSYNAL,
	@ANTIKOTHER = @ANTIKOTHER,

	@PERIOXIPARADOSIS = @PERIOXIPARADOSIS,
	@PERIOXIFORTOSIS = @PERIOXIFORTOSIS,



	@IFCASH = 0,
	@IFPISTOSI = 1,
	@IFPREPAY = 1,
	@IFOFEILOMENI = 0,
	@DATEPRINT = @DATEPRINT,
	@IDKINDPAYMENT = @IDKINDPAYMENT,
	@KINDPAYMENTDESCR = @KINDPAYMENTDESCR,
	@NO_EXT_ORDER = @NO_EXT_ORDER,
	@EXT_BARCODE = @EXT_BARCODE,
	@STATUS = @IDSTATUS,
	@STATUSDESCR = @STATUSDESCR,
	@AFMXREOUMENOU = @AFMXREOUMENOU,
	@AFMENTOLEA = @AFMENTOLEA,
	@AFMAPOSTOLEA = @AFMAPOSTOLEA,
	@AFMPARALIPTI = @AFMPARALIPTI,
	@AFMTRITOU = @AFMTRITOU,

	@APOSTOLEASDESCR = @APOSTOLEASDESCR,
	@PARALISPTISDESCR = @PARALISPTISDESCR,
	@ENTOLEASDESCR = @ENTOLEASDESCR,
	@TRITOSDESCR = @TRITOSDESCR,
	@DateCreate = @DATEPRINT,
	@UserCreate	= @USERCREATE,

	@IDXRHSHS = @IDXRHSHS,
	@IDCOMPANY = @COMPANYID,
	@IDYPOKATASTIMA = @YPOKATID,
	@TAXISPERCENT = @PARAST_TAXISPERCENT,
	@COMMENTS = @COMMENTS,
	@EXODATRITON = @EXODATRITON,
	@IDPRAKTOREIO = @IDPRAKTOREIO,
	@PRAKTOREIODESCR = @PRAKTOREIODESCR,
	@IDSKOPOSDIAKINISIS = @IDSKOPOUDIAKINISIS,
	@SKOPOSDIAKINISIS = @SKOPOSDIAKINISISDESCR
	

update F
	SET 
		IFANTIKCASH = CASE WHEN ISNULL(ANTIKCASH, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKEPIT = CASE WHEN ISNULL(ANTIKEPIT, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKSYNAL = CASE WHEN ISNULL(ANTIKSYNAL, 0) > 0 THEN 1 ELSE 0 END,
		IFANTIKOTHER = CASE WHEN ISNULL(ANTIKOTHER, 0) > 0 THEN 1 ELSE 0 END,
		SUMANTIK = ISNULL(ANTIKCASH, 0) + ISNULL(ANTIKEPIT, 0) + ISNULL(ANTIKSYNAL, 0) + ISNULL(ANTIKOTHER,0),
		IF_FROM_ANTAP = KP.IF_FROM_ANTAP,
		IFXRTRITOU = 1,
		IFPREPAY = COALESCE(@FLAG_PROPLIROMENI, ENTOL.IFPREPAY),
		IFCASH = COALESCE(@FLAG_METRITIS, ENTOL.IFCASH),
		IFOFEILOMENI = COALESCE(@FLAG_OFEILOMENI, ENTOL.IFOFEILOMENI),
		IFPISTOSI = COALESCE(@FLAG_PISTOSI, ENTOL.IFPISTOSI),
		NO_EXT_FORT = @NO_EXT_FORT,
		COMMENTSANTIK = @ANTIKCOMMENTS
from FORTOTIKES F
join KINDPARASTATIKON KP ON KP.ID = F.IDPARAST
join ACCOUNTS ENTOL ON ENTOL.id = F.IDENTOLEA
WHERE F.ID = @TheID;

UPDATE F SET
	F.OMADPROORISMOS=CASE 
							WHEN LEN(OP.Descr)>=2 THEN OP.Descr	
							ELSE (SELECT TOP 1 Descr FROM OMADIKOI_PROORISMOI WHERE LEN(Descr)<=1)
						END,
	F.OXIMA = (SELECT TOP 1 ARKYKLOFORIAS FROM TRUCKS WHERE LEN(ArKykloforias)<=2),
	F.IDDRIVER = (SELECT MIN(ID) [ID] FROM ODIGOI WHERE ifDelete=0),
	F.DRIVERDESCR = (SELECT TOP 1 (LastName + ' ' +FirstName) FROM ODIGOI 
						WHERE IFDELETE =0)  
FROM FORTOTIKES F
JOIN ACCOUNTS PARAL ON PARAL.id = F.IDPARALIPTI
LEFT JOIN Aar ON Aar.AarName=PARAL.AddressCity
LEFT JOIN AarPerOmProor AOM ON AOM.AarID=Aar.AarID
LEFT JOIN OMADIKOI_PROORISMOI OP ON OP.ID=AOM.IDOmProor
WHERE F.ID = @TheID;


INSERT INTO XREOSISANADELTIO(
	IDVOH, 
	IDXREOSIS, 
	CODEXREOSIS,
	DESCR,
	TAXISPERCENT,
	POSO,
	TAXIS,
	SUMPOSO,
	IF_TO_FORTOTIKI,
	IF_TO_VOH
)
SELECT
	FORT.ID,
	XR.ID,
	XR.CODE,
	XR.Descr,
	XR.TAXISPERCENT,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@POSO, 1)
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@TAXIS, 0.24)
		ELSE 0
	END,
	CASE ISNULL(XR.ifKomistra, 0)
		WHEN 1 THEN ISNULL(@SUMPOSO, 1.24)
		ELSE 0
	END,
	1,
	0
		
FROM XREOSISANAPARASTATIKO XAP
JOIN FORTOTIKES FORT ON FORT.IDPARAST = XAP.IDKINDPARASTTIKON
JOIN Xreoseis XR ON XR.ID = XAP.IDXREOSIS
WHERE XAP.ifDelete = 0
AND XR.ifDelete = 0
AND XAP.IDKINDPARASTTIKON = FORT.IDPARAST
AND FORT.ID = @theID;


-- update #10523
with sumxr as (
select
		xad.IDVOH,
		SUM(xad.POSO) POSO,
		SUM(xad.TAXIS) TAXIS,
		SUM(xad.SUMPOSO) SUMPOSO
	from XREOSISANADELTIO xad
	where xad.IF_TO_FORTOTIKI = 1
	and xad.IDVOH = @TheID
	group by xad.IDVOH
) 
UPDATE F
	SET POSO = SUMXR.POSO,
		TAXIS = SUMXR.TAXIS,
		SUMPOSO = SUMXR.SUMPOSO
FROM FORTOTIKES F
JOIN SUMXR on F.ID = SUMXR.IDVOH;

-- κλαιει η μανα του πελε
with SUMXRPF as (
	select
		xap.IDVOH,
		ISNULL(XR.ifKomistra, 0) ifKomistra,
		ISNULL(xr.ifDikaiomaFortotikis, 0) ifDikaiomaFortotikis,
		ISNULL(xr.ifXreosiTriton, 0) ifXreosiTriton,
		ISNULL(xr.ifOther, 0) ifOther,
		ISNULL(xr.IfAsfalistra, 0) ifAsfalistra,
		ISNULL(xr.ifErgatika, 0) ifErgatika,
		ISNULL(xr.IfEmvastika, 0) ifEmvastika,
		sum(xap.POSO) POSO
	from XREOSISANADELTIO XAP
	join Xreoseis XR ON XR.ID = XAP.IDXREOSIS
	where xap.IDVOH = @TheID
	GROUP BY
		GROUPING SETS (
			(IDVOH, ifKomistra),
			(IDVOH, ifDikaiomaFortotikis),
			(IDVOH, ifXreosiTriton),
			(IDVOH, ifOther),
			(IDVOH, IfAsfalistra),
			(IDVOH, ifErgatika),
			(IDVOH, ifEmvastika)
		)
	HAVING (
		ISNULL(xr.ifKomistra, 0) = 1
		or ISNULL(xr.ifDikaiomaFortotikis, 0) = 1
		or ISNULL(xr.ifXreosiTriton, 0) = 1
		or ISNULL(xr.ifOther, 0) = 1
		or ISNULL(xr.IfAsfalistra, 0) = 1
		or ISNULL(xr.ifErgatika, 0) = 1
		or ISNULL(xr.IfEmvastika, 0) = 1
	)
)
INSERT INTO HEADERFORTOTIKIS (
	IDFORT,
	PARASTATIKOFORT,
	SEIRAFORT,
	NOPARASTFORT,
	ENTOLEASDESCR,
	PARALISPTISDESCR,
	APOSTOLEASDESCR,
	KOMISTRA,
	DIKAIOMAFORTOTIKIS,
	OTHERXREOSIS,
	SYSKEVASIA,
	ASFALISTRA,
	KATHARO,
	TAXIS,
	SUMPOSOXRFORT,
	ERGATIKA,
	XREOSISTRITON,
	OLIKOSYNOLOXREOSEONFORT,
	BAROSFORT,
	KYBIKAFORT,
	POSOFORT,
	TEMAXIAFORT
)
select
	FORT.ID,
	FORT.PARASTATIKO,
	FORT.SEIRA,
	FORT.NOPARAST,
	FORT.ENTOLEASDESCR,
	FORT.PARALISPTISDESCR,
	FORT.APOSTOLEASDESCR,
	ISNULL(SUM_KOMISTRA.POSO, 0),
	ISNULL(SUM_DIKAIOMA.POSO, 0),
	ISNULL(SUM_OTHER.POSO, 0),
	ISNULL(GF.SYSKEVASIA, 0),
	ISNULL(SUM_ASFALISTRA.POSO, 0),
	
	--katharo?
	FORT.POSO,

	FORT.TAXIS,
	FORT.SUMPOSO,
	ISNULL(SUM_ERGATIKA.POSO, 0),
	ISNULL(FORT.EXODATRITON, 0),
	
	--oliko synolo xreoson ?!
	FORT.SUMPOSO + FORT.EXODATRITON,
	
	ISNULL(GF.BAROS, 0),
	ISNULL(GF.KYBIKA, 0),

	--what the fuck den perigrafw allo
	FORT.POSO,
	ISNULL(GF.TEMAXIA, 0)

from fortotikes FORT
left join (
	SELECT 
		IDVOH,
		MIN(SYSKEVASIADESCR) SYSKEVASIA,
		SUM(BAROS) BAROS,
		SUM(KYBIKA) KYBIKA,
		SUM(TEMAXIA) TEMAXIA
	FROM GRAMMESFORTTIKIS
	GROUP BY IDVOH
) GF ON GF.IDVOH = FORT.ID
left join SUMXRPF SUM_KOMISTRA on SUM_KOMISTRA.ifKomistra = 1
left join SUMXRPF SUM_DIKAIOMA on SUM_DIKAIOMA.ifDikaiomaFortotikis = 1
left join SUMXRPF SUM_OTHER on SUM_OTHER.ifOther = 1
left join SUMXRPF SUM_ASFALISTRA ON SUM_ASFALISTRA.ifAsfalistra = 1
left join SUMXRPF SUM_ERGATIKA ON SUM_ERGATIKA.ifErgatika = 1
left join SUMXRPF SUM_TRITON ON SUM_TRITON.ifXreosiTriton = 1
left join (
	SELECT IDVOH, SUM(POSO) POSO, SUM(TAXIS) TAXIS, SUM(SUMPOSO) SUMPOSO FROM XREOSISANADELTIO GROUP BY IDVOH
) SUMXR ON SUMXR.IDVOH = FORT.ID

where id = @TheID


GO

