CREATE VIEW ISOZYGIO_PAYMENTS_RECEIPTS_ISTOS AS

SELECT '105' + Cast(receipts.id AS NVARCHAR(20))							AS ID,
       rtrim(ltrim(receipts.seira))											as 'Σειρά',
       docno																AS 'Αρ.Παραστ',
       rtrim(ltrim(kindparastdescr))										as 'Παραστατικό',
       CONVERT(VARCHAR(10), dateprint, 103)									AS 'Ημερομηνία',
       isnull(afmcustomer,'')												as 'Αφμ',
	   customerdescr														as 'Συναλλασσόμενος',	
       isnull(sumposo * ( kindparastatikon.kindypologismou ),0)				AS 'Ποσό',
       aitiologia															as 'Αιτιολογία',
       kindpaymentdescr														as 'Τρ.Πληρωμής',
       receipts.dateprint													AS PRINTDATE,
       receipts.ifdelete
FROM   dbo.receipts
       INNER JOIN kindparastatikon
               ON receipts.idkindparast = kindparastatikon.id
                  AND kindparastatikon.ifenimerositameio = 1
WHERE  1=1
       AND receipts.ifdelete = 0
       AND receipts.idcompany = 1


UNION all

 SELECT '106' + Cast(payments.id AS NVARCHAR(20))							AS ID,
       rtrim(ltrim(payments.seira))											as 'Σειρά',
       docno																AS 'Αρ.Παραστ',
       rtrim(ltrim(kindparastdescr))										as 'Παραστατικό',
       CONVERT(VARCHAR(10), dateprint, 103)									AS 'Ημερομηνία',
       isnull(afmcustomer,'')												as 'Αφμ',
	   customerdescr														as 'Συναλλαασσόμενος',
       sumposo * ( kindparastatikon.kindypologismou )						AS 'Ποσό',
       aitiologia															as 'Αιτιολογία',
       kindpaymentdescr														as 'Τρ.Πληρωμής',
       payments.dateprint													AS PRINTDATE,
       payments.ifdelete
FROM   dbo.payments
       INNER JOIN kindparastatikon
               ON payments.idkindparast = kindparastatikon.id
                  AND kindparastatikon.ifenimerositameio = 1
WHERE  1=1
       AND payments.ifdelete = 0
       AND payments.idcompany = 1

GO

---END SCRIPT 2343
